window.XZ=window.XZ||{};(window.XZ.bank=window.XZ.bank||{})["外科学"]=[["1988-N22",15,"","",1988,22,"A","","癫痫持续状态是指",[["A","精神运动性发作数日"],["B","一侧肢体抽搐不已"],["C","阵挛发作从一处开始，逐扩散"],["D","大发作频繁，不能用药物控制"],["E","大发作频繁，意识持续丧失"]],"D","略","","N"],["1988-N25",0,"第三节 手术进行中的无菌原则","手术进行中的无菌原则",1988,25,"A","","无菌手术后手套未破，连续施行一手术时应",[["A","直接更换手套、手术衣"],["B","不必更换手套、手术衣"],["C","按规定方法重新刷手和浸泡酒精5分钟后穿手术衣、戴手套"],["D","不必重新刷手，仅浸泡酒精5分钟穿手术衣、戴手套"],["E","以上都不是"]],"D","此题书本上无统一叙述，通常在无菌手术后手套未破，连续施行手术时不必重新刷手，仅浸泡酒精5分钟穿手术衣、戴手套（D对）。仅对于无菌手术采取此法，对于有可能被污染的手术（如感染灶的处理或胃肠道手术），进行下一台手术时需重新洗手并进行手消毒。手术过程中若手套有破损，则无论是否为无菌手术都要重新进行洗手、消毒。","","N"],["1988-N27",5,"","",1988,27,"A","","深部感染体表症状哪项最重要",[["A","局部红热"],["B","局部波动感"],["C","局部肿胀"],["D","局部皮肤凹陷性水肿"],["E","表面皮肤过敏"]],"D","深部感染由于位置较深，肿胀无法在体表表现（C错），红热也无法感知（A错），仅有浅部感染可触及波动感，深部感染难以触及（B错）。过敏反应是指已产生免疫的机体在再次接受相同抗原刺激时所发生的组织损伤或功能紊乱的反应；无论是浅部或者深部感染，引起的仅仅是普通的炎症反应，尚达不到过敏反应的强度，不会引起过敏（E错）。深部感染的临床表现主要是在深部感染处可有疼痛及深压痛，并当炎症反应较强时，相应的皮肤表面可出现凹陷性水肿，所以局部皮肤凹陷性水肿是深部感染最重要体表症状（D对）。","","N"],["1988-N28",7,"第一节 热力烧伤","烧伤面积",1988,28,"A","","四岁小儿头颈部和右下肢全部烧伤，其面积为",[["A","20%"],["B","40%"],["C","30%"],["D","25%"],["E","36%"]],"E","估算烧伤面积时，女性和儿童有所差别：一般成年女性的臀部和双足各占6%；儿童头大，下肢小，可按下法计算（%）：头颈部面积＝9＋（12-年龄），双下肢＝46-（12-年龄）。4岁小儿头颈部和右下肢全部烧伤，头颈部面积9＋（12-4）＝17，右下肢面积＝{46-（12-4）}/2＝19。故此患儿烧伤面积占体表面积的17%＋19%＝36%（E对）。需牢固记忆成人体表面积划分法，儿童可经公式计算得出。","","N"],["1988-N29",17,"第一节 甲状腺疾病","甲亢手术指征",1988,29,"A","","下列不能列为甲状腺大部切除术适应症的是",[["A","继发性甲亢或高功能腺瘤"],["B","中度以上的原发性甲亢"],["C","青少年甲亢患者"],["D","有压迫症状或胸骨后甲状腺肿伴甲亢"],["E","抗甲状腺药物或碘治疗后复发者"]],"C","甲状腺大部切除术指征为可简单记忆为五种情况：继发性甲亢，症状严重者，压迫症状者，药物无效者，中早妊娠者。甲状腺素是具有促进机体生长作用的重要激素，且能够促进个体的发育成熟，对于青少年病人，非恶性疾病情况下均应保留甲状腺组织，因此青少年甲亢（C错，为本题正确答案）不是甲状腺大部切除术的适应证。","","N"],["1988-N30",18,"第三节 乳腺良性疾病","导管内乳头状瘤概述",1988,30,"A","","下列乳房肿块可能发生6%～8%恶变的是",[["A","Paget乳头病"],["B","乳房囊性增生病"],["C","乳腺纤维腺瘤"],["D","乳管内乳头状瘤"],["E","乳瘘"]],"D","Paget乳头病（A错）是乳头湿疹样乳腺癌，此病少见，恶性程度低，发展慢。乳房囊性增生病（B错）有无恶变尚无定论。乳腺纤维腺瘤（C错）是最多见的乳房良性肿瘤。乳瘘（E错）常由急性乳腺炎脓肿形成时治疗不当，损伤乳管造成，不是乳房肿块。乳管内乳头状瘤（D对）一般属良性，恶变率为6%～8%。","","N"],["1988-N31",30,"第二节 肝脓肿","细菌性肝脓肿临床表现",1988,31,"A","","细菌性肝脓肿，哪项是正确的",[["A","起病骤急，体温可高达39～40℃"],["B","70%为血源性"],["C","大部分病例，细菌沿门静脉入肝"],["D","肝区部有剧烈的绞痛"],["E","胸部有左胸腔积液"]],"A","细菌性肝脓肿属于急性细菌性感染性疾病，起病骤急，体温可高达39～40℃（A对），并伴有寒战、恶心呕吐、周身乏力等感染中毒症状。肝脏有门静脉和肝动脉双重血供，又通过胆道系统与肠腔相通，因而细菌可经多种方式侵入肝脏引发肝脓肿。常见途径主要有经胆道、肝动脉、门静脉，但最常见的感染途径为胆源性，约占41.4%，血源性感染约占23.9%（B错）。部分病例，细菌可沿门静脉入肝（C错），但不是大部分。肝实质内无神经末梢分布，不产生痛觉，所呈现的胀痛由肿大的肝脏压迫被膜引起，常表现为持续性钝痛，无肝区剧烈绞痛（D错）。右叶脓肿可使右膈肌升高；肝阴影增大或有局限性隆起；有时出现右侧反应性胸膜炎或右侧胸腔积液（E错）。","","N"],["1988-N32",22,"第四节 静脉疾病","原发性下肢深静脉瓣膜功能不全治疗",1988,32,"A","","大隐静脉曲张，高位结扎手术用于",[["A","静脉血栓形成"],["B","静脉石形成"],["C","交通支瓣膜闭锁不全"],["D","大隐静脉上端瓣闭锁不全"],["E","深静脉梗阻"]],"D","下肢静脉血大部分从深静脉回流，浅静脉只占小部分，因此在治疗大隐静脉曲张时，应确保深静脉通畅及深静脉瓣膜功能良好的情况下才可进行大隐静脉的结扎。静脉血栓形成（A错）、静脉石形成（B错）及深静脉的梗阻（E错）均会导致深静脉的不通畅，此时采取高位结扎术则导致下肢静脉血无法回流，出现下肢严重淤血，甚至引起下肢坏死。对于因交通支瓣膜闭锁不全（C错）导致的大隐静脉曲张，可选择筋膜外、筋膜下或借助内镜作交通静脉结扎术。大隐静脉高位结扎的适应证包括：大隐静脉上端瓣闭锁不全（D对）、下肢浅静脉曲张明显，伴有小腿胀痛和肿胀，色素沉着，慢性复发性溃疡。既往无深静脉血栓形成病史，且深静脉瓣膜功能良好者。","","N"],["1988-N33",44,"第四节 骨折愈合过程","骨折愈合过程概述",1988,33,"A","","在骨折愈合过程中，哪项是错误的",[["A","血肿机化演进期约需两周方能初步完成"],["B","内、外骨痂由膜内化骨而来，环状及腔内骨痂由软骨内化骨而来"],["C","原始骨痂形成期，骨痂不断加强，能抗拒一定应力，即达临床愈合"],["D","骨痂由血肿机化而来，血肿较大骨痂多"],["E","骨痂改造塑形期在临床愈合以后"]],"D","骨的愈合过程大体上分为三步，这三个阶段并不孤立，而是相互交织的。各阶段特点如下：①血肿炎症机化期，大约需要两周方能初步完成（A对）。此期主要生长特点为：血肿机化，胶原纤维沉积，晚期骨膜内层成骨细胞增生分化。X线片可见骨折线；②原始骨痂形成期，骨痂不断钙化加强，当其达到足以抵抗肌收缩力及剪力和旋转力时，骨折达到临床愈合（C对），在成人一般约需12～24周。此期主要生长特点为：内、外骨痂形成，并在此基础上形成桥梁骨痂。X线片骨折线隐约可见；③骨痂塑形期，约需1～2年，原始骨痂方能被板层骨痂替代。此期主要生长特点为：破骨细胞和成骨细胞相互作用，多余骨痂被吸收，应力方向上骨组织不断强化。一般来说，内、外骨痂由膜内化骨而来，环状及腔内骨痂由软骨内化骨而来（B对）。骨痂改造塑形期在临床愈合以后（E对）。血肿机化导致胶原纤维沉积形成的是纤维性骨样组织（D错，为本题正确答案），而骨痂是由成骨反应生成。","","N"],["1988-N34",53,"第二节 腰椎退行性疾病","腰椎侧凸",1988,34,"A","","腰椎间盘突出在神经根的外侧，则",[["A","腰椎凸向健侧"],["B","腰椎凸向患侧"],["C","腰椎无侧凸"],["D","腰椎前凸消失"],["E","腰前凸增加"]],"B","神经根的肩部即神经根的外侧，腋部则是神经根的内侧。腰椎侧突是一种为减轻疼痛的姿势性代偿畸形，与腰椎间盘突出组织和相邻神经根的相对位置关系有关：突出物在神经根内侧，上身向患侧弯曲，腰椎凸向健侧使患侧纤维环紧张和髓核部分还纳，可缓解疼痛。突出物在神经根的外侧，上身向健侧弯曲，腰椎凸向患侧可松弛受压的神经根，达到减轻椎间盘对神经根的压迫，可缓解疼痛（B对）。","","N"],["1988-N35",55,"第四节 膝关节结核","膝关节结核关节镜检查",1988,35,"A","","早期滑膜结核与类风湿性关节炎最可靠的鉴别诊断是",[["A","单一关节肿痛"],["B","血沉高于正常"],["C","X线照片关节变窄"],["D","经组织切片检查"],["E","结核菌素试验"]],"D","滑膜结核和类风湿性关节炎病变均位于关节处，经组织切片检查（D对）可以直接观察病变的病理表现：滑膜结核可见抗酸染色阳性杆菌及特征性的干酪性肉芽肿病变；类风湿性关节炎可见滑膜增生肥厚，有突入关节腔的绒毛皱褶，边缘有肉芽组织血管翳，逐渐延伸至软骨表面。单一关节肿痛（A错）不具有特异性，无法用于两者的鉴别诊断。两种疾病均会导致患者的血沉高于正常（B错）。类风湿关节炎和关节结核在早期阶段，均无X线照片关节变窄的表现（C错）。结核菌素试验（E错）阳性只能说明既往曾经接触结核杆菌或接种过卡介苗，但无法说明关节病变即结核杆菌引起。","","N"],["1988-N36",57,"第一节 骨肿瘤概论","骨肿瘤临床表现",1988,36,"A","","一般良性骨肿瘤",[["A","生长慢有症状"],["B","生长快无症状"],["C","生长慢无症状"],["D","生长快有症状"],["E","生长慢有疼痛"]],"C","良性骨肿瘤一般肿块增长缓慢，无或少疼痛（C对）；恶性骨肿瘤一般肿块生长迅速，多伴疼痛。良性骨肿瘤一般界限清楚，无压痛或轻压痛；恶性骨肿瘤一般界限不清，与周围浸润、粘连，压痛明显，可有体表皮肤红热，静脉扩张。良性骨肿瘤的X线表现一般为膨胀性生长，界限清晰，骨皮质变薄，通常无骨膜反应；恶性骨肿瘤的X线表现一般为浸润性生长，界限不清，早期骨破坏，骨膜反应明显，可有Codman三角、日光放射现象。","","N"],["1988-N37",42,"第二节 尿路上皮肿瘤","浸润深度",1988,37,"A","","膀胱原位癌的病变",[["A","限于固有层"],["B","限于粘膜层"],["C","达膀胱浅肌层"],["D","侵犯膀胱外"],["E","达膀胱深肌层"]],"B","原位癌即局限于上皮内的癌，未突破基底膜。对于膀胱癌来说，除要求未突破基底膜、局限于黏膜层外（B对），尚需要无乳头状突出，即癌细胞局限于上皮内，方可称膀胱原位癌，TNM分期为Tis。若出现乳头状癌，即使局限于黏膜内，TNM分期仍归为Ta期。","","N"],["1988-N38",39,"","",1988,38,"A","","临床型肾结核绝大多数是",[["A","双侧性病变"],["B","腰痛症状显著"],["C","全身症状突出"],["D","尿毒症症状明显"],["E","尿频、尿急、尿痛为主要表现"]],"E","肾结核的典型症状不在肾脏而在膀胱，多数病人的最初症状为尿频，以后尿频逐渐加重并有尿急、尿痛（E对），同时可出现血尿，因为含有结核杆菌的尿液刺激膀胱产生。临床肾结核绝大多数为单侧病变（A错），故对于肾结核，极少有因肾结核引起双侧肾功能衰竭。大多数病人即使单侧肾结核病情严重，也不会导致尿毒症（D错）。肾结核病人一般无明显腰痛（B错），仅少数病变破坏严重的肾结核，可发生结核性脓肾或输尿管堵塞，引起腰部钝痛或绞痛。肾结核一般没有明显的全身症状（C错），但部分晚期肾结核或合并其他器官活动性结核时，可出现典型的结核中毒症状。","","N"],["1988-N39",19,"第三节 气胸","开放性气胸急救处理",1988,39,"A","","开放性气胸急救处理时应立即",[["A","胸穿"],["B","闭式引流"],["C","加压吸氧"],["D","封闭胸部创口"]],"D","正常情况下，胸膜腔为负压，因而肺组织可以在胸腔内保持膨胀形态不至于塌陷；当发生开放性气胸时，胸膜腔负压不复存在，肺组织失去了使其膨胀的原动力，肺泡回缩，肺组织塌陷，如同漏气的气球。故当务之急是先封闭开放性胸部创口，可用无菌敷料如纱布、棉垫等，甚至必要情况下选择清洁的杯子等，在病人呼气末封盖吮吸伤口，并加压包扎（D对）。胸穿（A错）、闭式引流（B错）、加压吸氧（C错）均为在保证胸腔密闭的情况下行的治疗手段。","","N"],["1988-N40",20,"第三节 肺肿瘤","支气管镜检查",1988,40,"A","","诊断肺癌首选的检查方法是",[["A","X线检查"],["B","痰细胞学检查"],["C","支气管镜检查"],["D","纵隔镜检查"],["E","同位素扫描"]],"C","此题目不严谨。病理诊断是金标准，包括痰细胞学检查、支气管镜检查、纵隔镜检查、经胸壁针吸细胞学或组织学检查（TTNA）、胸腔积液检查等。临床上需根据具体情况具体选择方法。对于中央型肺癌，确诊首选纤维支气管镜＋活组织检查。对于周围型肺癌，确诊首选经胸壁穿刺活检。对于怀疑肺癌转移所致胸腔积液，可抽取胸腔积液做细胞学检查，寻找癌细胞。对于中央型肺癌，特别是伴有血痰的病例，痰中找到癌细胞的机会较高。本题给出答案为C选项，可能是考虑支气管镜可直接观察到肺癌并可取组织活检，但其多用于中心型肺癌的诊断，对于周围型肺癌意义不大。X线检查（A错）是肺癌常用的筛查方法。痰细胞学检查（B错）主要用于中央型肺癌伴有血痰的辅助诊断。纵隔镜检查（D错）主要用于明确有无纵隔淋巴结转移。同位素扫描（E错）对确诊肺癌价值不大。","","N"],["1988-N41",14,"","",1988,41,"A","","小脑幕切迹疝的临床表现中，最有助于与枕大孔疝区别的临床征像是",[["A","意识障碍"],["B","剧烈头痛、频繁呕吐"],["C","血压升高、脉快、呼吸减慢"],["D","一侧瞳孔散大，另侧肢体瘫痪"],["E","去大脑强直发作"]],"D","小脑幕切迹疝与枕大孔疝最大区别是：前者呼吸和循环障碍出现较晚，而瞳孔变化与意识障碍在早期出现（D对）。","","N"],["1988-N42",44,"第二节 骨折的临床表现及影像学检查","骨折临床表现",1988,42,"A","","颅底骨折的诊要依赖于",[["A","头颅X线摄片"],["B","CT断层扫描"],["C","典型的临床表现"],["D","头颅超声波检查"],["E","脑电图检查"]],"C","颅底骨折的诊断依靠临床表现，具体分为颅前窝骨折、颅中窝骨折、颅后窝骨折的不同典型临床表现，另外明确诊断需要头颅CT（C对）。","","N"],["1988-N67",36,"第四节 泌尿、男生殖系统专科检查","排泄性尿路造影",1988,67,"A","","女，30岁，三天前不慎扭伤腰部，次日感畏寒、高热（39．5℃）伴恶心，腰痛及尿频、尿急。检查：左腰部轻叩痛，为明确诊断应首选下列哪项检查",[["A","腹部平片"],["B","血培养"],["C","核素肾扫描"],["D","尿常规"],["E","静脉肾盂造影"]],"E","30岁女性患者，三天前不慎扭伤腰部（外伤史）。两天前出现畏寒、高热（39.5℃）伴恶心（感染中毒症状），腰痛及尿频、尿急（膀胱刺激征，提示泌尿系存在感染）。体查：左腰部轻叩痛。综合该患者病史、体查，诊断初步考虑肾脏外伤继发的感染。为明确诊断应首选静脉肾盂造影（E对），可以了解是否存在尿外渗情况。腹部平片（A错）对于结石的显示效果好，而对肾脏外伤继发感染无明显阳性提示意义。血培养（B错）用于判断败血症情况，对诊断肾脏外伤继发感染无帮助。核素肾扫描（C错）多用于肿瘤性疾病的判断以及肾功能的评估。尿常规（D错）可以辅助诊断尿路感染，但对于进一步明确感染发生部位无益。","","N"],["1988-N68",1,"第二节 水、钠代谢紊乱","等渗性脱水治疗",1988,68,"A","","急性粘连性肠梗阻3天患者，中度缺水，血压90/70mmHg，血清钠140mmol/L，血清钾3．5mmol/L、二氧化碳结合力35%，应先输下列那种液体",[["A","0.3%氯化钾液"],["B","5%碳酸氢钠液"],["C","平衡盐液"],["D","5%氯化钠溶液"],["E","5%葡萄糖溶液"]],"C","患者因急性粘连性肠梗阻引起中度缺水，血压90/70mmHg，需立刻补液扩容。患者血清钠140mmol/L，十版诊断学正常值为137～147mmol/L，尚未缺钠；血清钾仅3.5mmol/L，十版诊断学正常值在3.5～5.3mmol/L，处于正常值下限，考虑等渗性中度缺水。平衡盐液（C对）的电解质含量和血浆内含量相仿，优于高氯水平的等渗盐水，用来治疗等渗性缺水比较理想。0.3％氯化钾液（A错）可用于补充患者丢失的钾盐，但不能大量输注用于纠正脱水状态。5％碳酸氢钠液（B错）可用于纠正严重的酸中毒，而该患者并未出现酸碱失衡症状。5％氯化钠为高渗溶液（D错），可用于低渗性脱水的治疗，可纠正细胞外液的低渗状态和补充血容量。5％葡萄糖（E错）溶液为等渗液体，可用于高渗性脱水治疗，可纠正细胞外液的高渗状态，恢复血容量。","","N"],["1988-N69",26,"第三节 胃十二指肠溃疡的外科治疗","胃十二指肠溃疡穿孔检查",1988,69,"A","","男性，42岁，餐后上腹隐痛4年，此次饱餐后突发上腹刀割样剧痛2小时，疼痛很快扩散到全腹。体检：脸色苍白，出冷汗，体温36.5℃，脉搏96次/分，血压110/80mmHg，全腹压痛，反跳痛、肌紧张，以中上腹最明显，肠鸣音消失，白细胞12000/mm³，中性80%为协助诊断，首先应作哪项检查",[["A","急查血淀粉酶"],["B","急症胃镜检查"],["C","急症钡餐检查"],["D","腹部站立位X线透视"],["E","急查尿淀粉酶"]],"D","42岁男性患者，餐后上腹隐痛4年（胃溃疡典型的临床表现为规律发作的餐后痛）。饱餐后（穿孔的常见诱因）突发上腹刀割样剧痛2小时，扩散至全腹（穿孔的典型腹痛表现）。体检：全腹压痛，反跳痛、肌紧张，以中上腹最明显，肠鸣音消失（典型的腹膜刺激征表现），白细胞12000/mm³，中性粒细胞占比约80%（白细胞绝对计数升高，中性粒细胞比值升高，提示存在感染），诊断考虑消化性溃疡穿孔合并继发性腹膜炎。腹部左侧卧位或站立位X线透视（D对）若观察到膈下游离气体可以支持穿孔的诊断，阳性率约70%，但是该检查阴性也不能排除穿孔可能。急查血尿淀粉酶（AE错）主要用于辅助诊断急性胰腺炎。上消化道穿孔急性期不宜行急症胃镜检查（B错），胃镜检查时需用流水冲洗视野以便获得清晰的影像，水流可经穿孔处流入腹腔，加重腹膜炎。钡餐主要用于胃溃疡、胃部占位性疾病的诊断，对于已经发生穿孔的病人，不可采用急诊钡餐检查（C错）。","","N"],["1988-N74",27,"第四节 肠梗阻","粘连性肠梗阻治疗",1988,74,"B","","无血运障碍的粘连性肠梗阻",[["A","手术治疗为主"],["B","非手术治疗为主"],["C","先用非手术治疗必要时采取手术"],["D","必须手术治疗"],["E","中医中药治疗"]],"C","无血运障碍的粘连性肠梗阻可通过保守治疗缓解，主要措施为胃肠减压、纠正水、电解质与酸碱平衡紊乱和抗感染，部分病人经过非手术治疗病情可得到缓解；对于部分症状严重，病情反复发作且不易缓解的病人，可根据病情行即期或择期手术治疗。综上所述，无血运障碍的粘连性肠梗阻先用非手术治疗必要时采取手术（C对）。","","N"],["1988-N75",27,"第四节 肠梗阻","肠扭转治疗",1988,75,"B","","小肠扭转",[["A","手术治疗为主"],["B","非手术治疗为主"],["C","先用非手术治疗必要时采取手术"],["D","必须手术治疗"],["E","中医中药治疗"]],"A","肠扭转是一种较为严重的机械性肠梗阻，扭转肠袢血运较少甚至消失，因而可在短时间内发生肠绞窄、坏死。若不能得到及时正确的处理，将有较高的死亡率。及时的手术治疗（A对），将扭转的肠袢回转复位可降低死亡率，更可减少小肠切除后的短肠综合征。","","N"],["1988-N92",1,"第二节 水、钠代谢紊乱","等渗性脱水临床表现",1988,92,"C","","等渗性缺水可发生",[["A","代谢性碱中毒"],["B","代谢性酸中毒"],["C","两者均可"],["D","两者均否"]],"C","等渗性缺水导致休克时，常因微循环障碍、局部酸性代谢产物大量产生和积聚，导致代谢性酸中毒；此外，若原发疾病为低位小肠梗阻，则可因为大量呕吐丢失碱性肠液，导致代谢性酸中毒（B对）。若原发疾病为幽门梗阻，则呕吐所丧失的体液以酸性胃液为主，常导致代谢性碱中毒（A对），需引起考生注意两方面考虑问题。本题AB均对，正确答案为C。","","N"],["1988-N93",1,"第二节 水、钠代谢紊乱","高渗性脱水临床表现",1988,93,"C","","高渗性缺水可发生",[["A","代谢性碱中毒"],["B","代谢性酸中毒"],["C","两者均可"],["D","两者均否"]],"C","高渗性缺水导致循环血量减少，导致微循环障碍、局部酸性代谢产物大量产生和积聚，导致代谢性酸中毒，同时肾脏血流减少，肾排泄固定酸的能力下降，亦可加重代谢性酸中毒。在特定条件下，如肾脏调节异常、合并呕吐（胃酸丢失）或长期使用利尿剂（导致低氯性碱中毒），可能引发代谢性碱中毒（C对）。","","N"],["1988-N116",14,"","",1988,116,"X","","腰穿是诊断流脑的重要手段之一，但在下列哪些情况下不要强穿或不宜腰穿",[["A","暴发型流脑休克型"],["B","流行期间，根据临床已可明确诊断者"],["C","有明显颅内高压、短期内陷入昏迷"],["D","疾病早期、败血症期"]],"AC","颅内压明显增高，腰穿减压易导致脑疝，故禁忌。暴发型流脑腰穿易导致感染扩散，且处于休克期，病人全身情况不稳定，易加重病情（AC错）。","","N"],["1988-N121",2,"第二节 输血的不良反应及其防治","溶血反应治疗",1988,121,"X","","输血发生溶血反应时应",[["A","减慢输血速度"],["B","肌注肾上腺素"],["C","静滴0.3%氯化钾液"],["D","静注5%碳酸氢钠液"]],"D","溶血反应发生于配型不合血制品的输入，故需立即停止输血（A错）；肾上腺素（B错）用于过敏反应严重者；由于溶血引起的肾功能下降，使得尿液排钾功能降低，若选用0.3%氯化钾液（C错）扩容可能引起高钾血症。溶血早期可给予5%碳酸氢钠（D对）静注以碱化尿液，促血红蛋白溶解，可防止血红蛋白沉淀于肾小管并造成阻塞。","","N"],["1988-N122",10,"第四节 局部麻醉","神经阻滞",1988,122,"X","","神经干阻滞麻醉的特点",[["A","麻醉剂量小而产生较大的麻醉区"],["B","无生理干扰"],["C","效果好而安全"],["D","施麻醉后不致产生并发症与副损伤"]],"AC","神经干阻滞麻醉与表面麻醉相比，由于局麻药直接作用于神经干，使得神经干支配的一片区域的运动、感觉阻滞，通过较小的麻醉剂用量产生较大的麻醉区（A对）。局麻药通过阻滞神经纤维离子正常平衡产生麻醉效果，其作用受到受阻滞神经所处内环境的影响（B错）。与腰麻及硬膜外麻醉相比，神经干麻醉的特点是效果好且安全（C对）。神经干阻滞作为有创操作，且局麻药本身具有毒性，例如锁骨上臂丛神经干阻滞易发生气胸并发症以及膈神经、喉返神经麻痹和霍纳综合征等并发症（D错）。此题选项不严谨，没有指明与其他哪种麻醉方式做对比。","","N"],["1988-N123",8,"第二节 常见体表肿瘤与囊肿","皮肤基底细胞癌",1988,123,"X","","基底细胞癌",[["A","恶性程度较低"],["B","手术切除效果好"],["C","呈鼠咬状溃疡"],["D","隆起呈菜花状"]],"ABC","皮肤癌是皮肤最常见的恶性肿瘤，主要有两种类型，即基底细胞癌与鳞状细胞癌，多见于头面部及下肢。具有发展慢、恶性程度低（A对）、治愈率高等特点。皮肤基底细胞癌来源于皮肤或附件基底细胞，发展缓慢，呈浸润性生长，很少有血道或淋巴道转移。亦可同时伴色素增多，呈黑色，称色素性基底细胞癌，临床上易误诊为恶性黑色素瘤，但质较硬；破溃者呈鼠咬状溃疡边缘（C对）。好发于头面，如鼻梁旁、眼睫等处。对放射线敏感，故可行放疗；早期也可手术切除（B对）。","","N"],["1988-N124",23,"第一节 腹外疝概述","腹外疝病理解剖",1988,124,"X","","腹外疝的组成包含",[["A","疝环"],["B","疝内容物"],["C","疝外被盖"],["D","疝囊"]],"ABCD","典型的腹外疝由疝囊（D对）、疝内容物（B对）和疝外被盖（C对）组成。其中疝囊包括疝囊颈和疝囊体。疝囊颈是疝囊比较狭窄的部分，是疝环（A对）所在的部位，也是疝突向体表的门户，又称疝门，亦是腹壁薄弱区或缺损所在；疝囊体包绕疝内容物的组织，多数为壁层腹膜，呈囊状。疝内容物为进入疝囊的腹内脏器或组织，以小肠为最多见，大网膜次之；其余腹腔脏器如盲肠、阑尾、膀胱等也可称为疝内容物。疝外被盖为疝囊以外的各层组织，如皮下脂肪、皮肤等。","","N"],["1988-N125",25,"第一节 急性弥漫性腹膜炎","急性弥漫性腹膜炎非手术治疗",1988,125,"X","","急性腹膜炎的病人，取半卧位的目的是什么",[["A","使脓液集中盆腔便于引流"],["B","避免膈肌压迫、有利呼吸和循环"],["C","减少毒素吸收"],["D","减少肠粘连的发生"]],"ABC","许多腹部手术在术后均采取坐位或半卧位，其目的就是将渗出液引流至盆腔，利用盆腔的吸收能力差的特点，减少毒素吸收和中毒症状（C对），有利于局限和引流（A对）；同时由于重力作用，使得膈肌下移，扩大了胸腔内的容积，减轻了腹腔器官对膈肌的压迫，有利于呼吸和循环功能（B对）。粘连形成是机体的一种纤维增生的炎症反应，是否形成纤维性粘连的决定因素是局部纤维分解的速度，与腹膜炎半卧位引流无关（D错）。","","N"],["1988-N126",32,"第二节 胆道疾病影像学检查","胆道疾病超声检查",1988,126,"X","","B型超声扫描诊断胆道疾病，方法上不足之处为",[["A","肥胖病人难于判断病变"],["B","肠腔胀气过多难于判断病变"],["C","病灶过小时难于发现"],["D","肝内胆管﹤4毫米常不显示"]],"ABC","超声诊断是极有用的方法，术前超声诊断胆囊结石、胆囊息肉样病变、急性胆囊炎、慢性胆囊炎及胆囊癌、胆管结石等病变，诊断准确率可达95%～98%。但是，超声检查也有其一定的局限性和限制：①超声诊断对仪器和操作者要求高，重复检查的可对比性不如CT及MRI；②易受腹腔内含气脏器的干扰（B对），对软组织阴影的显示和定性的准确性不够，并受骨质和厚层脂肪的影响，因而肥胖病人难于判断病变（A对）；③胆囊结石中以较硬的、含结晶较多和较大结石的声像图最典型，结石的声影最明显，但对小的结石、胆囊内无胆汁的充满型结石、胆囊管的结石、肝内外胆管的软性色素性结石等，常难以发现（C对）。超声能检出2mm以上的结石（D错）。","","N"],["1988-N127",33,"第二节 胰腺炎","重症急性胰腺炎",1988,127,"X","","下列哪种反映急性胰腺炎的病情严重",[["A","休克"],["B","尿糖增高"],["C","血钙降低"],["D","血尿淀粉酶明显升高"]],"AC","急性胰腺炎可分为轻症急性胰腺炎、中症急性胰腺炎和重症急性胰腺炎，轻症急性胰腺炎时血尿淀粉酶升高，体征较轻，通过及时的保守治疗短期内可好转；重症急性胰腺炎多为出血坏死性胰腺炎，体征较明显，可伴休克（A对），也可并发脏器功能障碍和严重的代谢障碍。重型胰腺炎时，胰腺实质坏死严重，胰岛功能严重受损，导致胰岛素分泌骤降，血糖升高（＞11.1mmol/L），此时虽亦可出现尿糖增高，但并不能准确反映急性胰腺炎的严重程度（B错），因为尿糖也受肾功能影响。重型胰腺炎可导致腹腔内脂肪组织大量坏死，释放出的脂肪酸与钙离子结合，生成不溶性脂肪酸钙（钙皂），导致血钙降低（＜1.87mmol/L）（C对）。胰腺出血坏死广泛时，由于胰腺细胞大量坏死，不再产生和释放淀粉酶，血尿淀粉酶可不升高甚至出现降低（D错）。","","N"],["1988-N128",44,"第四节 骨折愈合过程","原始骨痂形成期",1988,128,"X","","经软骨内化骨形成的连接骨痂是",[["A","外骨痂"],["B","环状骨痂"],["C","内骨痂"],["D","腔内骨痂"]],"BD","注意各种骨痂形成的不同方式：膜内成骨形成内骨痂（C错）、外骨痂（A错）；软骨内成骨形成连接骨痂，包括环形骨痂（B对）和髓腔内骨痂（D对）；连接骨痂与内、外骨痂相连，形成桥梁骨痂。","","N"],["1988-N129",53,"第二节 腰椎退行性疾病","感觉异常",1988,129,"X","","骶₁神经根受压可出现",[["A","小腿上外侧皮肤感觉减退"],["B","外踝部皮肤感觉减退"],["C","拇趾根部皮肤感觉减退"],["D","足背外侧皮肤感觉减退"]],"BD","腰4神经根受压时，小腿前内侧感觉减退。腰5神经根受压时，小腿上外侧或足背皮肤感觉减退（A错）、拇趾皮肤感觉减退（C错）。骶1神经根受压时，外踝附近及足外侧感觉减退（BD对）。","","N"],["1988-N130",54,"第二节 化脓性关节炎","化脓性关节炎治疗",1988,130,"X","","急性化脓性关节炎的治疗原则是",[["A","早期足量有效抗菌素肌注或静滴"],["B","局部固定"],["C","关节内注入抗菌素"],["D","关节切开引流"]],"ABCD","急性化脓性关节炎起病急骤，毒血症症状明显，须早期足量有效抗菌素肌注或静滴（A对）。关节腔内直接注射抗生素（C对）可提高关节内抗生素浓度，抑制局部细菌生长，可减轻关节的损害，有利于活动功能的保持。关节切开引流（D对）适用于较深的大关节，较小的关节可用穿刺引流，可迅速降低关节腔内压，减轻疼痛，缓解炎症症状。为防止关节内粘连，尽可能保留关节功能，可做持续性关节被动活动，没有上（下）肢功能锻炼器时应将局部适当固定（B对），以防止或纠正关节挛缩。按最新教材观点，本题B选项有争议，应以最新教材为准。","","N"],["1988-N131",41,"第二节 上尿路结石","适应证",1988,131,"X","","肾、输尿管结石手术治疗指征",[["A","直径大于1厘米"],["B","引起梗阻，影响肾功能"],["C","非手术疗法无效"],["D","引起急性无尿"]],"ABCD","随着ESWL、PCNL等技术的发展，此题已过时，可忽略。外科治疗包括开放性手术、腔内泌尿外科手术、体外冲击波碎石及腹腔镜手术。视具体情况采用适宜的治疗方法（可参考七版黄家驷外科学P2352～P2354），但以损伤性较小的体外冲击波碎石为首选。","","N"],["1988-N132",38,"第二节 肾损伤","血尿",1988,132,"X","","肾损伤血尿停止后再次出血是由于",[["A","未用止血剂"],["B","过早活动"],["C","未用抗菌素"],["D","局部感染"]],"BD","大多数肾损伤由于钝性损伤所致。肾损伤后出血，血液经肾盂、肾盏进入尿液，从而出现血尿。对于轻度的肾损伤，可自行愈合，血尿也将消失；仅严重肾裂伤需通过手术治疗挽救病情。在肾损伤出血停止后的一段时间，肾脏的愈合尚未牢靠，若过早活动，则可能导致伤口破裂出血（B对）。肾损伤后可在局部形成血肿，为细菌的良好培养基，若发生局部感染（D对），约30%患者可出现血尿。使用止血剂属于非手术治疗的方式之一，可促进伤口凝血，但未用止血剂（A错）并不会导致再次出血。早期合理应用抗生素可预防部分感染，但未用抗生素（C错）并非再次出血的直接原因。","","N"],["1988-N133",19,"第二节 肋骨骨折","肋骨骨折临床表现",1988,133,"X","","纵隔扑动主要发生在",[["A","胸部挤压伤"],["B","多发肋骨骨折"],["C","闭合性气胸"],["D","开放性气胸"]],"BD","闭合性气胸以及胸部挤压伤患者胸腔未和外界相通，不会产生两侧不对等的气压变化（AC错）。多发肋骨骨折以连枷胸为主要表现，连枷胸的反常呼吸运动可使伤侧肺受到塌陷胸壁的压迫，呼吸时两侧胸腔压力的不均衡造成纵膈扑动（B对）。","","N"],["1988-N135",6,"第四节 治疗原则","开放性创伤的处理",1988,135,"X","","开放性颅脑损伤的手术目的是",[["A","彻底止血"],["B","清除异物"],["C","清除无生活能力的脑组织"],["D","变开放性损伤为闭合性颅脑损伤"]],"A","开放性颅脑损伤应争取6～8小时内施行清创术，术中吸除血肿和破碎的脑组织，彻底止血。硬脑膜严密缝合。术后加强抗感染（A对）。","","N"],["1988-N136",16,"","",1988,136,"X","","桥脑小脑角区肿瘤常见的症状是",[["A","颅神经Ⅴ、Ⅵ、Ⅶ及后组颅神经损伤"],["B","同侧小脑症状"],["C","晚期出现脑干症状"],["D","出现视乳头原发萎缩"]],"A","略","","N"],["1989-N3",33,"第二节 胰腺炎","胆道疾病",1989,3,"A","","在我国引起急性胰腺炎最主要的病因为",[["A","胆道疾病"],["B","胰管结石"],["C","酗酒"],["D","高脂血症"],["E","外伤"]],"A","正常情况下，在胰腺实质与胰管之间、胰管和十二指肠之间以及胰管中的胰液分泌压与胆道中的胆汁分泌压之间均存在正常的压力梯度，不会发生异常反流。当存在胆结石、胆道水肿等致胆汁引流不畅的疾病时，胆汁可经“共同通道”返流入胰管，致急性胰腺炎。在我国引起急性胰腺炎最主要的病因为胆道疾病（A对），称胆源性胰腺炎，约占50%以上。在西方国家，酒精中毒/酗酒是引起急性胰腺炎的主要原因。胰管结石多由于大量饮酒和高脂血症引起，并不常见。此外，暴饮暴食、高脂血症、高钙血症都引起急性胰腺炎的危险因素，但起主要作用的还是胆道疾病的影响；外伤可直接损伤胰腺造成急性胰腺炎，但是发生率很低。","","N"],["1989-N30",0,"第二节 手术人员和病人手术区域的准备","病人手术区的准备",1989,30,"A","","关于病人手术区的准备下列哪项是不正确",[["A","碘酒、酒精涂擦皮肤消毒范围要包括手术切口周围15cm"],["B","一律应自手术区中心部向四周涂擦"],["C","铺巾顺序：先铺操作者对面或铺相对不洁区，最后铺靠近操作者的一侧，手术巾位置不准确时只能由手术区向外移不应向内移动"],["D","大单头端应盖过麻醉架，两侧和足端应垂下超过手术床边30cm"]],"B","手术区皮肤消毒范围要包括手术切口周围15cm的区域（A对），如切口有延长的可能，应相应扩大皮肤消毒范围。涂擦消毒剂时，应由手术区中心部向四周涂擦。如为感染部位手术，或为肛门区手术，则应从手术区外周涂向感染处或会阴肛门处（B错，为本题正确答案）。铺巾顺序先铺相对不洁区（如下腹部、会阴部），最后铺靠近操作者的一侧（C对）。大单布的头单应盖过麻醉架，两侧和足端都应垂下超过手术台边30cm（D对）。关于手术过程中的消毒和铺巾等问题以及其他有关无菌操作注意事项的题目是外科的重点知识，外科医生需牢固树立无菌意识。","","N"],["1989-N31",17,"第一节 甲状腺疾病","甲状腺结节的诊断和处理原则",1989,31,"A","","儿童甲状腺结节有多少机会是恶性的",[["A","10%"],["B","25%"],["C","50%"],["D","75%"],["E","90%"]],"C","此题为数字记忆性题目。儿童甲状腺结节50%是恶性的（C对）。此外，乳头状癌占儿童甲状腺癌的全部。","","N"],["1989-N32",18,"第二节 乳房检查","活组织病理检查",1989,32,"A","","乳房肿块下列诊断检查方法是不宜采用的",[["A","切取部分肿块活检"],["B","穿刺肿块吸取组织活检"],["C","液晶热图象"],["D","切除肿块活检"],["E","钼靶X检查"]],"A","切除活组织病理检查是乳腺癌检查的可靠方法，作活检时应将肿块完整切除（D对），并最好在肋间神经阻滞麻醉或硬膜外麻醉下进行，避免局麻下手术造成的肿瘤播散，且一般不宜做切取部分肿块活检（A错，为本题正确答案）。不能明确肿瘤性质时，可用细针管穿刺肿块，吸取组织做涂片细胞学检查，其诊断准确率高（B对）；液晶热图像通过显示肿瘤组织的高代谢高热表现，从而有助于乳腺癌的诊断（C对）；对于乳房肿块，若无法排除，均应警惕乳腺癌可能。对于乳腺肿块的影像学检查，常用钼靶X线摄片，适用于观察软组织结构，常用于乳腺癌高发人群的普查（E对）。","","N"],["1989-N33",23,"第一节 腹外疝概述","腹外疝病理解剖",1989,33,"A","","腹外疝的疝囊是",[["A","壁层腹膜"],["B","脏层腹膜"],["C","腹横筋膜"],["D","精索内筋膜"],["E","腹内斜肌筋膜"]],"A","典型的腹外疝由疝囊、疝内容物和疝外被盖组成。疝囊是壁腹膜的憩室样突出部，由疝囊颈和疝囊体组成。壁层腹膜覆盖于腹腔内面，若腹壁有缺损或孔隙，则腹内脏器脱出时被壁腹膜所兜托，因此壁腹膜（A对）形成疝囊。疝内容物为进入疝囊的腹内脏器或组织，以小肠为最多见，大网膜次之。脏层腹膜（B错）是覆盖在腹内脏器表面的单层细胞上皮，疝形成时属于疝内容物。疝外被盖是指疝囊以外的各层组织，如皮下脂肪和皮肤。腹横筋膜位于腹横肌深面，其下面部分的外侧1/2附着于腹股沟韧带，内侧1/2附着于耻骨梳韧带,且有精索或子宫圆韧带自腹横筋膜穿出，若此处薄弱、缺损，则有腹内容物突出形成疝，腹横筋膜属于疝外被盖。在男性，腹横筋膜由此向下包绕精索形成精索内筋膜（D错），斜疝时疝通过此处可掉入阴囊，属于疝外被盖的一部分。腹内斜肌筋膜（E错）是腹壁的支持结构，若形成疝，腹内斜肌筋膜覆于疝囊体上，也属于疝外被盖的一部分。","","N"],["1989-N34",2,"第三节 自体输血和大量输血","大量输血处理",1989,34,"A","","输库血每超过800毫升后，应注射",[["A","安乃近2毫升"],["B","肝素10单位"],["C","5%碳酸氢钠液200毫升"],["D","10%葡萄糖酸钙10毫升"],["E","6-氨基己酸3克"]],"D","库存血的存储无法避免部分血细胞的死亡裂解，释放出钾离子，当输注入人体后，可致高钾血症，高血钾有导致心脏骤停等心律失常的危险，钙与钾有对抗作用。输库存血超过800ml后，给予10%葡萄糖酸钙10ml缓慢静脉注射可用于拮抗高钾的心脏毒性作用，用于对抗心律失常。同时，输库血每超过800ml后，应注射10%葡萄糖酸钙10ml，可对抗抗凝血剂枸橼酸盐所导致的暂时性低血钙（D对）。安乃近（A错）主要用于退热，亦用于治疗急性关节炎、头痛、风湿性痛、牙痛及肌肉痛等。肝素（B错）主要用于抗凝血，5%碳酸氢钠液（C错）为碱性溶液，大量输入库存血会导致碱中毒，使用碳酸氢钠加重碱中毒。6-氨基已酸（E错）主要用于止血。","","N"],["1989-N35",3,"第一节 外科休克概述","外科休克概念",1989,35,"A","","休克的实质为",[["A","血压下降"],["B","中心静脉压下降"],["C","脉压下降"],["D","心脏指数下降"],["E","组织血流量下降及细胞缺氧"]],"E","休克是指机体有效循环血容量减少、组织灌注不足，细胞代谢紊乱和功能受损的病理过程，它是一个由多种病因引起的综合征。休克的本质是氧供给不足和需求增加（E对）；休克的特征是产生炎症介质；休克的共同点是机体有效循环血量减少；休克的救治原则首先是补充血容量。上述知识点是对休克及其治疗最根本的概括，需牢固掌握。","","N"],["1989-N36",13,"第一节 术前准备","肺功能障碍",1989,36,"A","","不宜施行择期手术的肺最大通气量是",[["A","在预计值85%以上"],["B","在预计值75～84%"],["C","在预计值70～74%"],["D","在预计值60～69%"],["E","在预计值60%以下"]],"E","该题已过时，不必深究。老数据为肺最大通气量在预计值的60%以下时不宜施行择期手术（E对）。黄家驷外科学第七版P420认为如果最大通气量（MVV）<50%，血气分析PaO2<70mmHg，PaCO2>50mmHg，则提示病人的肺功能很差，很难耐受大手术。","","N"],["1989-N37",6,"第四节 治疗原则","污染伤口的处理",1989,37,"A","","头面部污染性伤口清创缝合的时限最长为",[["A","6～8小时"],["B","8～12小时"],["C","13～20小时"],["D","24小时左右"],["E","48小时"]],"B","清创术是指伤后早期充分清除坏死或失去生机的组织、血块、异物等有害物质，控制伤口出血，尽可能将已污染的伤口变为清洁伤口，争取为伤口早期愈合创造良好的局部条件。伤后应尽早清创，最好在伤后6～8小时内进行；头面部伤口由于局部血运良好，抗感染能力强，且伤口多位于浅表部位，污染不易扩散至深层组织，限时可延长至10小时，甚至更长（B对）。","","N"],["1989-N38",30,"第二节 肝脓肿","细菌性肝脓肿临床表现",1989,38,"A","","不符合细菌性肝脓肿临床表现的是",[["A","继发于胆道感染，门静脉或其它感染"],["B","起病急、中毒症状明显"],["C","穿刺脓液呈棕褐色"],["D","肝肿大有压痛"],["E","可并发膈下脓肿"]],"C","胆道感染时，细菌循胆管上行，可引起细菌性肝脓肿；门静脉血供约占肝血供的75%，门静脉感染可继发细菌性肝脓肿；肝毗邻感染病灶中的细菌可循淋巴系统侵入，引起细菌性肝脓肿；在开放性肝损伤时，细菌可随致伤异物、破裂的小胆管或创口直接侵入肝脏而引发细菌性肝脓肿。因此，细菌性肝脓肿可继发于胆道感染，门静脉或其它感染（A对）。阿米巴肝脓肿穿刺脓液为棕褐色，镜检时可发现阿米巴滋养体；细菌性肝脓肿的脓液多为黄白色脓液（C错，为本题正确答案），涂片和培养可发现细菌。肝脓肿一般起病较急，寒战、高热等中毒症状明显（B对），可同时伴肝肿大并有压痛（D对），由于肝血窦无瓣膜，感染易进入血液，患者全身中毒症状明显。右叶肝脓肿若穿破肝被膜，可并发膈下脓肿（E对），甚至穿破膈肌侵入肺，形成肺脓肿。","","N"],["1989-N39",22,"第四节 静脉疾病","原发性下肢静脉曲张治疗",1989,39,"A","","大隐静脉曲张伴有深静脉阻塞者应采用",[["A","大隐静脉高位结扎术"],["B","高位结扎加曲张静脉切除术"],["C","5％鱼肝油酸钠注射治疗"],["D","下肢静脉交通支结扎术"],["E","以上都不对"]],"E","深静脉阻塞患者，深静脉收纳的血液经交通支进入大隐静脉等浅静脉实现回流，下肢浅静脉对下肢血液回流至关重要。大隐静脉曲张伴有深静脉阻塞者若采用大隐静脉高位结扎术（A错）、高位结扎加曲张静脉切除术（B错）、5%鱼肝油酸钠注射治疗（C错）、下肢静脉交通支结扎术（D错），则下肢静脉血将无法回流，可导致下肢严重淤血，甚至引起下肢坏死。本题ABCD均错，正确答案为E。在治疗大隐静脉曲张时，应确保深静脉通畅及深静脉瓣膜功能良好，否则，应视为曲张静脉剥脱术的禁忌症。","","N"],["1989-N77",1,"第五节 酸碱平衡失调","代谢性酸中毒治疗",1989,77,"A","","急性弥漫性腹膜炎病人，体重50公斤，入院时，血压100/60毫米汞柱，心率100/分，呼吸30次/分，呼吸深，面色潮红，呼气中有酮味。补液应给哪项",[["A","输全血"],["B","生理盐水或复方氯化钠溶液"],["C","11.2%乳酸钠溶液"],["D","5%碳酸氢钠溶液"],["E","5%氯化钠溶液"]],"D","病人呼吸深，频率30次/分，且呼出气体带酮味，为典型的重度的酸中毒表现。对于重度的酸中毒患者，仅仅依靠单纯补液和自身调节不足以代偿酸中毒对机体的危害，需给予一定的碱剂用于迅速改善酸中毒症状。最常用的碱性药物为5%碳酸氢钠溶液（D对），一般来说，5%碳酸氢钠100ml可以使血液PH上升0.1。11.2%乳酸钠溶液（C错）亦曾用于治疗酸中毒，但现在临床已不再采用。输全血（A错）主要用于急性大量失血病人的抢救，该患者不具备输血指征。生理盐水或复方氯化钠溶液（B错）分别用于治疗部分代谢性碱中毒和等渗性缺水。5%氯化钠（E错）为高渗液，可用于纠正低渗性缺水。","","N"],["1989-N79",5,"第五节 脓毒症","脓毒症诊断",1989,79,"A","","有一大面积烧伤病人，烧伤已5天，突然发生寒战，继而高烧。不久，体温不升，白细胞升高不明显，四肢冰冷，尿少，脉快。根据以上临床表现，诊断为",[["A","革兰氏阳性细菌败血症"],["B","革兰阴性细菌败血症"],["C","低血容量性休克"],["D","真菌性败血症"],["E","以上都不是"]],"B","大面积烧伤的病人，烧伤后5天，此时创面的渗出液回吸收，该过程会带入大量的“毒素”，加之前期渗出体液丢失大量营养物质，使得病人面临巨大的感染可能。患者出现体温不升、白细胞升高不明显、四肢冰冷等临床表现符合革兰阴性杆菌脓毒症的三低现象（低温、低白细胞、低血压）；而尿少，脉快等表现则提示出现了感染性休克中的冷休克，而冷休克通常由革兰阴性细菌引起。因此，本例可诊断为革兰阴性细菌败血症（B对）。革兰氏阳性细菌败血症（A错）的特点是高热、白细胞明显升高、四肢潮红等，常表现为暖休克。低血容量性休克（C错）可表现为四肢冰冷，尿少，脉快，但是多发生在烧伤后1-2天内，且一般不会突发寒战高烧。真菌性败血症（D错）主要与抗生素使用不当、菌群失调有关，烧伤患者一般不会发生。","","N"],["1989-N80",28,"第二节 急性阑尾炎","急性阑尾炎临床诊断",1989,80,"A","","女性，50岁，脐周痛12小时，扩散至全腹痛2小时，右侧腹部压痛，反跳痛，肌紧张，尤以右下腹为显著，结肠充气试验（+），腹部透视无异常，白细胞：20000/ml，中性87%，尿红细胞2～4/HP。应考虑",[["A","急性胰腺炎"],["B","急性胆囊炎"],["C","右侧输尿管结石"],["D","右侧输卵管妊娠破裂"],["E","急性阑尾炎，穿孔"]],"E","该患者以脐周痛为始，渐发展为全腹痛，但仍旧以右下腹为著，出现压痛反跳痛肌紧张，此为典型的转移性右下腹痛表现，见于急性阑尾炎，白细胞升高支持此诊断；结肠充气试验（＋），是急性阑尾炎辅助诊断的体征。患者右侧腹部压痛，反跳痛，肌紧张，此为腹膜刺激征象，出现时提示阑尾炎症加重，出现化脓、坏疽或穿孔等病理改变。所以本例诊断应考虑急性阑尾炎，穿孔（E对）。急性胰腺炎（A错）疼痛部位始于上腹部，为突发剧烈上腹痛，牵涉痛虽可引起全腹痛，但以上腹部为著，而不会似本例以右下腹疼痛为著。急性胆囊炎（B错）多发生于夜间，以右上腹绞痛为主，可放射至右肩背部，但一般不会引起全腹痛，黄疸少见，急性发作时典型体征为Murphy征阳性，与本例不符。右侧输尿管结石（C错）引起的疼痛为剧烈绞痛，绞痛沿输尿管向外阴部和股内侧放射，疼痛部位因结石位置而异，但不会引起全腹痛，腹部透视通常可见结石影，与本例不符。右侧输卵管妊娠破裂（D错）表现为突发右下腹剧烈疼痛，同时伴有失血性休克表现，通常不会引起白细胞的升高，且通常会出现停经史；该病人年龄已达到50岁，该年龄女性通常已到绝经期，怀孕可能性较低。","","N"],["1989-N85",27,"第四节 肠梗阻","呕吐",1989,85,"B","","低位小肠梗阻",[["A","血性呕吐"],["B","粪性呕吐"],["C","胆汁性呕吐"],["D","呕吐宿食伴酸臭味"],["E","喷射性呕吐"]],"B","血性呕吐（A错）通常为消化道大出血的症状。胆汁性呕吐（C错）主要见于胃空肠吻合术后的输出袢梗阻及慢性不全性输入袢梗阻。幽门位置位于胃的末端，是连接胃与十二指肠的部分，若幽门梗阻，食物无法顺利下行到达肠腔，积聚于胃中，通常不会立即发生呕吐，食物在胃中经过发酵，在第二天由于胃部不适而呕吐出来，故为呕吐宿食伴酸臭味（D错）。喷射性呕吐（E错）主要是中枢神经系统病变引起（直接刺激呕吐中枢），如颅内压增高等。低位小肠梗阻的发生部位为消化道中下段，食物在小肠中已经经历了较久的消化作用而变成残渣，且靠近下段消化道部分含有大肠杆菌等正常菌群，可腐败残渣，若此处梗阻，则呕吐物为已消化的食物残渣，伴有粪便臭味，即粪性呕吐（B对）。","","N"],["1989-N86",26,"第三节 胃十二指肠溃疡的外科治疗","胃十二指肠溃疡瘢痕性幽门梗阻临床表现",1989,86,"B","","幽门梗阻",[["A","血性呕吐"],["B","粪性呕吐"],["C","胆汁性呕吐"],["D","呕吐宿食伴酸臭味"],["E","喷射性呕吐"]],"D","血性呕吐（A错）通常为消化道大出血的症状。粪性呕吐（B错）多见于低位小肠梗阻。胆汁性呕吐（C错）主要见于胃空肠吻合术后的输出袢梗阻及慢性不全性输入袢梗阻。喷射性呕吐（E错）主要是由中枢神经系统病变引起（直接刺激呕吐中枢），如颅内压增高等。幽门位于胃的末端，连接胃与十二指肠，若幽门梗阻，食物则无法顺利下行到达肠腔，积聚于胃中，通常不会立即发生呕吐，食物在胃中经过发酵，在第二天由于胃部不适而发生呕吐，呕吐物为隔夜宿食且伴酸臭味（D对）。","","N"],["1989-N87",32,"第五节 胆道感染","急性梗阻性化脓性胆管炎临床表现",1989,87,"B","","腹痛、寒战高烧、黄疸，常见于",[["A","急性胆囊炎"],["B","急性胰腺炎"],["C","胆道蛔虫病"],["D","急性化脓性胆管炎"],["E","急性肠梗阻"]],"D","腹痛、寒战高烧、黄疸为典型的Charcot三联征，常见于急性胆管炎。若患者除Charcot三联征以外，尚有休克及中枢神经系统受抑制的表现统称Reynolds五联征，常见于急性梗阻性化脓性胆管炎。本题选项中仅急性化脓性胆管炎（D对）与正解接近，但并非最佳。急性胆囊炎（A错）常有腹痛，轻至中度发热，通常无寒战，10%～20%的病人可出现轻度黄疸。急性胰腺炎（B错）常有腹痛，一般无寒战高热，若结石嵌顿或胰头肿大压迫胆总管可出现黄疸。胆道蛔虫病（C错）常表现为腹部钻顶样绞痛，无寒战高热，如有黄疸出现一般均较轻。急性肠梗阻（E错）表现为阵发性绞痛，一般无寒战高热、黄疸。","","N"],["1989-N88",32,"第七节 胆道蛔虫病","胆道蛔虫病临床表现",1989,88,"B","","腹痛发作突然，缓解也突然，常见于",[["A","急性胆囊炎"],["B","急性胰腺炎"],["C","胆道蛔虫病"],["D","急性化脓性胆管炎"],["E","急性肠梗阻"]],"C","胆道蛔虫病（C对）为蛔虫钻入胆道引起的一系列临床症状的统称，其典型表现为蛔虫活动时突发剑突下钻顶样剧烈绞痛，阵发性加剧。疼痛时辗转不安、呻吟不止、大汗淋漓，可伴有恶心、呕吐或吐出蛔虫。常可放射至右肩胛或背部，腹痛可骤然缓解，间歇期可全无症状。疼痛可反复发作，持续时间各不相同。急性胆囊炎（A错）主要是上腹部疼痛，开始时仅有上午胀痛不适，逐渐发展至呈阵发性绞痛；夜间发作常见，饱餐、进食肥腻食物常诱发发作。疼痛放射至右肩、肩胛和背部。急性胰腺炎（B错）的腹痛常于饱餐和饮酒后突然发作，腹痛剧烈，多位于左上腹，向左肩及左腰背部放射。急性化脓性梗阻性胆管炎（D错）有典型的Reynolds五联征，即为腹痛、寒战高热、黄疸、休克、神经中枢系统受抑制表现。急性肠梗阻（E错）有典型的腹痛为阵发性绞痛，若肠袢绞窄则腹痛发作急骤，表现为持续性剧烈腹痛，阵发性加剧。","","N"],["1989-N103",7,"第一节 热力烧伤","切痂术",1989,103,"C","","成人双侧小腿Ⅲ度烧伤",[["A","早期一次切痂植皮"],["B","分期切痂植皮"],["C","两者均可"],["D","两者均不可"]],"A","成人双小腿Ⅲ°烧伤占体表面积的13%，对于小面积深度烧伤，全身状况稳定者，应争取早期一次手术去痂，用自体皮全覆盖（A对）。分期切痂植皮（B错）适用于Ⅲ°烧伤面积在30％以上者。此题年代久远，不必深究。","","N"],["1989-N104",7,"第一节 热力烧伤","切痂术",1989,104,"C","","成人双上肢及躯干前方均为Ⅲ度烧伤",[["A","早期一次切痂植皮"],["B","分期切痂植皮"],["C","两者均可"],["D","两者均不可"]],"B","成人双上肢及躯干前方均为Ⅲ°烧伤占体表面积的31％。烧伤面积在30％以上者，一次性治愈难度大，应于伤后48小时后，待血流动力学和全身情况趋于稳定时再行切痂、植皮覆盖，手术可分次进行，一般每次切除15～30％的体表面积（B对）。早期一次切痂植皮（A错）适用于Ⅲ°烧伤面积在30％以下者。此题年代久远，不必深究。","","N"],["1989-N135",23,"第二节 腹股沟疝","腹股沟管解剖",1989,135,"X","","腹股沟管后壁包括",[["A","腹膜"],["B","腹横筋膜"],["C","内侧1/3腹肌和腹内斜肌所构成的联合肌腱"],["D","耻骨梳韧带"]],"ABC","腹股沟管“两口四壁”结构需要掌握。两口：内口（深环）：精索或子宫圆韧带自此穿出腹腔；外口（浅环）：精索自此降入阴囊。四壁：前壁：皮肤、皮下组织、腹外斜肌腱膜、外1/3有腹内斜肌；后壁：腹横筋膜、腹膜、内侧1/3有腹股沟镰；上壁：腹内斜肌、腹横肌的弓状下缘；下壁：腹股沟韧带和腔隙韧带。","","N"],["1989-N136",13,"第三节 术后并发症的防治","腹腔脓肿和腹膜炎",1989,136,"X","","腹腔引流的目的是",[["A","控制暂存的炎症"],["B","防止腹腔脓肿的发生"],["C","使腹内渗物排出体外"],["D","减少粘连，预防肠梗阻"]],"ABC","外科引流的目的是将人体组织间或体腔中积聚的脓、血、及其他渗出液导引至体外，防止术后感染或影响伤口愈合。腹腔引流能够将腹腔内渗出物连同细菌、坏死组织、积血积脓等引出体外（C对），从而防止腹腔脓肿的发生（B对）、控制暂时存在的炎症（A对），减少炎症蔓延；此外，腹腔引流还用于治疗吻合口瘘。术后出现腹腔粘连一直是腹部手术的难题，主要是由于手术对组织的损伤引起；提高手术水平、减轻手术造成的组织损伤，尽可能减少对腹膜的刺激是减少粘连的有效方法，引流本身无法减少粘连的发生（D错）","","N"],["1989-N137",10,"第二节 麻醉前评估和准备","麻醉前准备",1989,137,"X","","正确的麻醉前用药应是",[["A","老年人应适当减少镇静药、镇痛药用量"],["B","小儿心率快，全麻前阿托品用量应酌减"],["C","拟行硫喷妥钠麻醉时，阿托品量应增大"],["D","小儿呼吸快，吗啡用量应酌增"]],"AC","老年人身体状况相对较差，新陈代谢较慢，应适当减少镇静药、镇痛药用量（A对）。小儿代谢旺盛，腺体分泌发达，阿托品用量需加大才能抑制呼吸道、消化道等的分泌（B错）；硫喷妥钠用后无呕吐、头痛等副作用，但常引起喉痉挛、支气管收缩，故麻醉前最好给予阿托品以作预防（C对）；吗啡具有呼吸中枢抑制作用，且病人为小儿，耐受能力差，故吗啡应避免或酌情减少剂量使用（D错）。","","N"],["1989-N139",29,"第十二节 痔","内痔",1989,139,"X","","内痔脱出未及时复位可致",[["A","嵌顿"],["B","水肿"],["C","感染"],["D","坏死"]],"ABCD","内痔脱出后，若未及时复位，局部组织血液回流不畅，可出现水肿（B对）。水肿后组织体积变大，可导致回纳困难，甚至嵌顿（A对）。裸露在外的痔组织反复摩擦，可导致黏膜受损，可导致感染（C对）甚至坏死（D对）。","","N"],["1989-N157",28,"第二节 急性阑尾炎","急性阑尾炎的并发症",1989,157,"X","","急性化脓性阑尾炎的并发症有",[["A","阑尾穿孔"],["B","局限性或弥漫性腹膜炎"],["C","阑尾系膜血栓性静脉炎并发转移性肝脓肿"],["D","阑尾纤维瘢痕形成"]],"ABC","阑尾动脉系回结肠动脉的一个分支，是一种无侧支的终末动脉，在阑尾炎症时，组织水肿，阑尾腔内压力升高，均会压迫阑尾动脉引起血液循环障碍，故急性阑尾炎时难引起出血并发症，而常见阑尾组织的缺血、坏死和穿孔（A对）。阑尾炎若治疗不及时，周围有大网膜等组织包绕，可引起腹腔的局限性化脓性病变，以阑尾周围脓肿最常见，也可在盆腔、肠间隙形成脓肿；若病情猛烈，大网膜等周围组织无法包绕阑尾穿孔后流出的脓液，则会引起弥漫性腹膜炎（B对）。阑尾静脉属于回、结肠静脉终末支，其血流经回结肠静脉、肠系膜上静脉、门静脉入肝。急性阑尾炎时，阑尾静脉中的感染性血栓，可沿肠系膜上静脉至门静脉，导致化脓性门静脉炎症；如病情加重会产生感染性休克和脓毒症，治疗延误可发展为细菌性肝脓肿（C对）。阑尾炎属于化脓性炎症，若不及时治疗，其结局通常是向蜂窝织炎、坏疽性阑尾炎，阑尾穿孔发展，而不会发展为纤维瘢痕；仅慢性阑尾炎时可出现不同程度的纤维化（D错）。","","N"],["1990-N31",6,"第一节 创伤概述","按致伤机制分类",1990,31,"A","","伤口边缘整齐，呈线状，出血多，周围组织损伤轻的是",[["A","刺伤"],["B","撕裂伤"],["C","切伤"],["D","挫伤"],["E","皮肤撕脱伤"]],"C","切伤为锐利物体（如刀刃）切开体表所致，其创缘较整齐，伤口大小及深浅不一，严重者其深部血管、神经或肌肉可被切断；利器对伤口周围组织刺激轻微，故切断的血管多无明显收缩，出血较多（C对）。刺伤（A错）的伤口多较小而深，易阻塞，有时会伤及内脏，易并发感染，尤其是厌氧菌感染。撕裂伤（B错）是由于钝性暴力作用于体表，造成皮肤和皮下组织撕开和断裂，伤口形态各异，但常见有特征性的细丝状物，恰似“藕断丝连”，是尚未断离的抗裂强度较大且富于胶原的纤维组织，多污染较重。挫伤（D错）最为常见，为钝性暴力或重物打击所致的皮下软组织损伤，主要表现为伤处肿胀、皮下淤血，有压痛，可有肌纤维撕裂和深部血肿。皮肤撕脱伤（E错）的组织损伤广泛，血管、神经、肌腱从不同平面撕脱，常需复杂的血管移植，再植成功率较低，即使成功，功能恢复差。","","N"],["1990-N32",13,"第二节 术后处理","胃肠道功能",1990,32,"A","","术后腹胀主要是由于",[["A","细菌产生的气体"],["B","腹膜后血肿"],["C","组织代谢产生的气体"],["D","血液内气体弥散到肠腔内"],["E","咽下的空气积存于肠腔内过多"]],"E","腹胀是腹部手术术后常见的临床症状，主要是由于肠道功能尚未完全恢复，蠕动能力差，随吞咽进入气体无法顺利通过肠腔排除而积聚在肠腔内，从而引起腹胀（E对）。腹部手术前服用抑菌剂且经过灌肠处理，术后排气前不允许进食，肠腔内细菌量少且活力差，又无食物进行发酵，产生的气体不足以引起腹胀（A错）。腹膜后血肿（P342）（B错）突出的表现为内出血征象、腰背痛和肠麻痹，伴尿路损伤者可有血尿，与术后腹胀并无多大关系。组织代谢产生的气体（C错）因弥散进入组织液进而进入血液，在肺部进行气体交换，不会进入腹腔。人和高等动物的机体同外界环境进行气体（主要为氧和二氧化碳）交换的整个过程称为气体交换，人与外界的气体交换发生的唯一部位是肺，消化道无此功能，因而血液内溶解的气体不会弥散到肠腔内（D错）。","","N"],["1990-N33",2,"第二节 输血的不良反应及其防治","疾病传播",1990,33,"A","","输血可传播以下哪一种疾病",[["A","结核"],["B","伤寒"],["C","疟疾"],["D","钩虫病"],["E","甲型肝炎"]],"C","病毒和细菌性疾病可通过输血传播。病毒包括EB病毒，巨细胞病毒，乙、丙、丁型肝炎病毒，HIV和人类T细胞白血病病毒（HTLV）Ⅰ、Ⅱ型等；细菌性疾病如布氏杆菌病等。其他还有梅毒、疟疾（C对）等。其中以输血后肝炎和疟疾多见。结核（A错）最常见和最重要的传播途径是呼吸道传播；伤寒（B错）和甲、戊型肝炎（E错）均通过消化道传播；钩虫病（D错）主要通过皮肤接触传播。","","N"],["1990-N34",1,"第三节 钾代谢紊乱","低钾血症临床表现",1990,34,"A","","低血钾可引起",[["A","酸中毒"],["B","碱中毒"],["C","高渗性缺水"],["D","低渗性缺水"],["E","等渗性缺水"]],"B","低钾可引起代谢性碱中毒（B对A错）。其发生机制是：①细胞外液K⁺浓度减少，此时细胞内液K⁺移出，而细胞外液中的H⁺移入细胞内，引起细胞外碱中毒；②肾小管上皮细胞内K⁺浓度降低，造成肾小管上皮Na⁺、K⁺交换减少，Na⁺、H⁺交换增加，使得肾脏排K⁺减少，排H⁺增多，加重代谢性碱中毒，并同时出现反常性酸性尿。缺水可同时伴有钾的丢失，但低血钾不会导致缺水（CDE错）。","","N"],["1990-N35",0,"第二节 手术人员和病人手术区域的准备","手术人员的术前准备",1990,35,"A","","戴无菌手套时，尚未戴无菌手套的手，只能允许接触手套的",[["A","外面"],["B","套口的翻折部分"],["C","掌面"],["D","套口"],["E","侧面"]],"B","手套的外面为接触手术范围的完全无菌区，故未带手套的手只能接触手套口的翻折部分（B对）。正确的穿戴无菌手套步骤为：①穿好手术衣后，取出手套包（或盒）内的无菌滑石粉小纸包，将滑石粉散在手心，然后均匀的抹在手指、手掌和手背上，再取无菌手套一副（现医用无菌手套通常内面已均匀撒好石灰粉）。②取手套时只能捏住手套口的翻折部分，不能用手接触手套外。③对好两只手套，使两只手套的拇指对向前方并靠拢。右手提起手套，左手插入手套内，并使各手指尽量深的插入相应的指筒末端。再将已戴手套的左手指插入右侧手套口翻折部下，将右侧手套拿稳，然后再将右手插入右侧手套内，最后将手套套口翻折部翻转包盖于手术衣的袖口上。","","N"],["1990-N36",18,"第二节 乳房检查","活组织病理检查",1990,36,"A","","确诊乳房深部脓肿的根据是",[["A","有波动感"],["B","寒战高热"],["C","乳房胀痛"],["D","穿刺有脓"],["E","白细胞数明显增高"]],"D","乳房深部穿刺抽出脓液是乳房深部脓肿最直观的证据（D对）。有波动感为浅表脓肿的表现（A错）；无论脓肿深浅均可有乳房胀痛，且乳房胀痛也可出现于乳腺囊性增生病等其他疾病（C错）；寒战高热（B错）和白细胞数明显升高（E错）是化脓性疾病的全身症状，不作为评判乳腺脓肿的指标。","","N"],["1990-N37",23,"第二节 腹股沟疝","腹股沟疝概述",1990,37,"A","","最常见的腹外疝是",[["A","股疝"],["B","腹壁切口疝"],["C","腹股沟斜疝"],["D","脐疝"],["E","腹股沟直疝"]],"C","腹外疝中，由于精索或子宫圆韧带经腹股沟管深环穿出的原因，使得此处的腹壁存在先天薄弱。在腹压增高时，腹腔内容物可经此先天薄弱处疝出，故该处发生的腹股沟斜疝（C对）最为常见。","","N"],["1990-N38",29,"第七节 直肠癌","直肠指诊触及肿物",1990,38,"A","","对有便血，排便习惯改变的人首先进行简便又十分重要的检查是",[["A","直肠指检"],["B","乙状结肠镜检"],["C","纤维结肠镜检"],["D","钡剂灌肠透视"],["E","超声波检查"]],"A","有便血，排便习惯改变的病人，均需考虑是否患有直肠癌可能。直肠指检（A对）是简单易行而又十分重要的检查，国人直肠癌约70%为低位直肠癌，能在直肠指诊时触及。乙状结肠镜检（B错）、纤维结肠镜检（C错）、钡剂灌肠透视（D错）、超声波检查（E错）虽然在直肠疾病检查中均有一定价值，但是这些检查均需要仪器的辅助方能实现，远不如直肠指检来得直接简便。","","N"],["1990-N39",33,"第二节 胰腺炎","其他项目",1990,39,"A","","急性坏死性胰腺炎常发生",[["A","血钙升高"],["B","血钙降低"],["C","血钾升高"],["D","血钾降低"],["E","血磷降低"]],"B","急性坏死性胰腺炎时，腹腔内脂肪组织大量坏死，释放出的脂肪酸与钙离子结合，生成不溶性脂肪酸钙（钙皂），导致血钙降低（＜1.87mmol/L）（B对A错）。由于呕吐和胃肠减压丢失大量富含钾离子的消化液，禁食导致钾离子的摄入不足，但大量细胞坏死导致钾离子释放增加，钾离子的变化不明确（CD错）。继发肾功能衰竭时可出现血磷升高（E错）。","","N"],["1990-N40",17,"第一节 甲状腺疾病","甲状腺功能亢进临床表现",1990,40,"A","","判定甲亢病情程度和治疗效果的最重要标志是",[["A","体重增减、食量大小"],["B","脉率快慢、脉压大小"],["C","腺体软硬、大小"],["D","出汗多少、手颤有无"],["E","情绪改变，睡眠好坏"]],"B","甲亢病情程度和治疗效果的判定主要依靠临床表现，结合辅助检查。临床表现主要是靠测基础代谢率，测定方法可根据脉率快慢、脉压大小来计算（B对），或用基础代谢率测定器测定。甲亢的其它临床表现包括体重增减、食量大小（A错）、腺体软硬、大小（C错）、出汗多少、皮肤潮湿、手颤有无、怕热（D错）、情绪改变，睡眠好坏（E错）、内分泌紊乱以及无力、易疲劳、出现肢体近端肌萎缩等。由于这些症状没有特异性，临床一般不作为判定病情程度和治疗效果的指标。","","N"],["1990-N66",17,"第一节 甲状腺疾病","单纯性甲状腺肿临床表现",1990,66,"A","","关于单纯性甲状腺肿，下列的叙述哪一项是正确的",[["A","男性显著多于女性"],["B","年龄越大发病者越多"],["C","甲状腺多呈结节状肿大"],["D","一般不伴有功能亢进或功能低下"],["E","从病变性质来说，可以看作是良性肿瘤"]],"D","单纯性甲状腺肿（A错）多见于女性，一般无全身症状。该病与环境、自身代谢情况有关，与年龄无明显关系（B错）。病程早期，甲状腺呈对称、弥漫性肿大，腺体表面光滑，质地柔软，随吞咽上下移动；随后，在肿大腺体的一侧或两侧可扪及多个（或单个）结节（但单纯性甲状腺肿发展为结节者占少数，多数仍旧停留在对称、弥漫性肿大阶段）（C错）。除极少数结节性单纯性甲状腺肿大可继发甲状腺功能亢进外，单纯性甲状腺肿患者一般不伴有功能亢进或功能低下（D对）。肿瘤有“一旦形成，不因病因消除而停止生长”的特点，但是对于单纯性甲状腺肿的病人来说，去除缺碘的发病因素，或给予甲状腺素片则甲状腺肿大可消除，不应视为良性肿瘤（E错）。","","N"],["1990-N70",5,"第五节 脓毒症","脓毒症概念",1990,70,"A","","下列哪一项符合脓毒血症概念",[["A","细菌大量入血，但不产生中毒症状"],["B","细菌的毒素入血，出现中毒症状"],["C","细菌入血繁殖，产生毒素，出现中毒症状"],["D","细菌随血流运行，在内脏引起多个脓肿，出现中毒症状"],["E","以上都不是"]],"D","脓毒血症的概念是指化脓性病菌侵入血流后，在其中大量繁殖，并通过血流扩散至宿主体内的其他组织或器官，产生新的化脓性病灶（D对）。细菌大量入血，但不产生中毒症状是菌血症（A错），细菌的毒素入血，出现中毒症状是毒血症（B错）。细菌入血繁殖，产生毒素，出现中毒症状是败血症（C错）。","","N"],["1990-N77",32,"第七节 胆道蛔虫病","胆道蛔虫病诊断",1990,77,"A","","男，7岁，阵发性右上腹绞痛，伴呕吐，发作间歇期症状完全消失。查体：体温37．2℃，巩膜无黄染，上腹轻度深压痛，无肌紧张，可能为",[["A","急性胆囊炎"],["B","十二指肠溃疡"],["C","胆石症"],["D","胆道蛔虫病"],["E","化脓性胆管炎"]],"D","7岁男童，阵发性右上腹绞痛伴呕吐，间歇期症状完全消失，上腹部轻度深压痛，诊断考虑胆道蛔虫病（D对）。胆道蛔虫病为蛔虫钻入胆道引起的一系列临床症状的统称，其典型表现为蛔虫活动时突发剑突下钻顶样剧烈绞痛，阵发性加剧。疼痛时辗转不安、呻吟不止、大汗淋漓，可伴有恶心、呕吐或吐出蛔虫。常可放射至右肩胛或背部，腹痛可骤然缓解，间歇期可全无症状。疼痛可反复发作，持续时间各不相同。急性胆囊炎（十版外科学P473）（A错）患者右上腹痛持续，轻中度发热，可有畏寒，体查可发现Murphy征阳性。十二指肠溃疡（B错）好发于青年人，典型症状为周期性发作的空腹痛，且多为烧灼样痛，而非绞痛性质。胆石症（十版外科学P467）（C错）患者通常无临床表现，胆绞痛常为首发症状，也可自发停止，一般无发热和黄疸，但患者年龄仅7岁，患胆石症可能性低。化脓性胆管炎（E错）的典型临床表现为Charcot三联征：腹痛、寒战高热、黄疸。","","N"],["1990-N78",3,"第二节 低血容量性休克","低血容量性休克概述",1990,78,"A","","腹膜炎病人，经扩容治疗血压80/60mmHg，中心静脉压5cm水柱，尿量20毫升/小时，应考虑",[["A","急性肾功能衰竭"],["B","呼吸困难综合征"],["C","低血容量性休克"],["D","急性心力衰竭"],["E","感染未控制"]],"C","血压80/60mmHg，处在正常低限；中心静脉压（CVP）5cm H₂O，为血容量不足的表现；结合患者有腹膜炎病因，可致大量体液渗出于腹腔内聚积，低血容量性休克诊断成立（C对）。CVP除了可以衡量全身血容量情况外，更可作为补液时的参考指标，该患者需继续补液扩容，血容量恢复后，针对腹膜炎症状轻重选择保守或者手术治疗。急性肾功能衰竭（A错）常因水钠潴留，血压升高，中心静脉压升高。呼吸困难综合征（B错）主要表现为呼吸困难。急性心力衰竭（D错）可有血压降低，但中心静脉压升高。","","N"],["1990-N79",5,"第五节 脓毒症","脓毒症诊断",1990,79,"A","","有一大面积烧伤病人，烧伤已5天，突然发生寒战，继而高烧。不久，体温不升，白细胞升高不明显，四肢冰冷，尿少，脉快，根据以上临床表现为，诊断为",[["A","革兰氏阳性细菌败血症"],["B","革兰氏阴性细菌败血症"],["C","低血容量性休克"],["D","真菌性败血症"],["E","以上都不是"]],"B","大面积烧伤的病人，烧伤后5天，此时创面的渗出液回吸收，过程中会带入毒素等，加之前期渗出体液丢失大量营养物质，使得病人面临巨大的感染可能。患者出现体温不升、白细胞升高不明显、四肢冰冷等临床表现符合革兰阴性杆菌脓毒症的三低现象：低温、低白细胞、低血压；而尿少，脉快等表现则提示出现了感染性休克中的冷休克，而冷休克通常由革兰阴性细菌引起。因此，本例可诊断为革兰阴性细菌败血症（B对）。革兰氏阳性细菌败血症（A错）的特点是高热、白细胞明显升高、四肢潮红等，常表现为暖休克。低血容量性休克（C错）可表现为四肢冰冷，尿少，脉快，但是多发生在烧伤后1～2天内，且一般不会突发寒战高烧。真菌性败血症（D错）主要与抗生素使用不当、菌群失调有关，烧伤患者一般不会发生。","","N"],["1990-N80",1,"第二节 水、钠代谢紊乱","高渗性脱水治疗",1990,80,"A","","男，64岁，进行性吞咽困难3个月，近10天来每日中饮水少许，极度口渴、乏力、唇干舌燥，皮层弹性差，眼窝凹陷、尿少，比重1.030。应静滴",[["A","10%葡萄糖液"],["B","林格氏液"],["C","5%葡萄糖盐水"],["D","5%葡萄糖液"],["E","平衡液"]],"D","老年男性患者，进行性吞咽困难3个月，进水不足10天，并有口渴，尿少等缺水表现，尿比重高于正常（随机尿正常值1.003～1.030）。诊断考虑：1.食管癌2.高渗性缺水。对于高渗性脱水治疗以口服进水为佳，无法饮水者可静脉滴注5%葡萄糖溶液（D对）或低渗的0.45%氯化钠溶液纠正高渗状态，恢复血容量。林格氏液（复方氯化钠溶液）（B错）和平衡液（E错）为等渗液，常用于纠正等渗性缺水。5%葡萄糖盐水（C错）为生理盐水中含5%葡萄糖，常用于纠正低渗性缺水。10%葡萄糖液（A错）一般不用于纠正缺水状态。","","N"],["1990-N87",25,"第二节 腹腔脓肿","盆腔脓肿诊断",1990,87,"B","","阑尾切除术后8天，下腹腹胀不适，每天大便20次左右，大便带有黏液，直肠指检，直肠前壁扪及触痛性肿块",[["A","原发性腹膜炎"],["B","盆腔脓肿"],["C","继发性腹膜炎"],["D","出生腹膜炎"],["E","慢性腹膜炎"]],"B","阑尾切除术为腹腔手术，8天后出现下腹腹胀不适提示发生了继发性病变。每天排便20次，此为典型的直肠刺激症状，有黏液便，说明继发病变主要位于盆腔或者直肠。直肠指检发现在直肠前壁可触及有触痛肿物，说明病变主要位于盆腔，可诊断为盆腔脓肿（B对）。腹膜炎的症状主要表现为腹部症状和体征，直肠指检可无阳性症状（ACDE错）。","","N"],["1990-N88",25,"第一节 急性弥漫性腹膜炎","急性弥漫性腹膜炎诊断",1990,88,"B","","全腹压痛和反跳痛，腹肌紧张，穿刺脓液稠厚，有粪臭",[["A","原发性腹膜炎"],["B","盆腔脓肿"],["C","继发性腹膜炎"],["D","出生腹膜炎"],["E","慢性腹膜炎"]],"C","“全腹压痛和反跳痛，腹肌紧张”是急性腹膜炎的标志性体征，穿刺抽出物为稠厚脓液，有粪臭，提示肠道穿孔，肠道内粪便进入腹腔并引起化脓性炎症，故应为继发性腹膜炎（C对）。原发性腹膜炎（A错）穿刺腹腔液多为稀薄脓液，无臭味。盆腔脓肿（B错）不会引起全腹腹膜炎体征，不适感局限。出生腹膜炎（D错）即胎粪性腹膜炎，胎儿在母体内发生肠穿孔、胎粪流入腹腔而引起的无菌性腹膜炎，出生后短期即表现出腹膜炎或肠梗阻症状，由于无细菌的参与，故穿刺液无臭味。慢性腹膜炎（E错）病人的急腹症表现不明显。","","N"],["1990-N103",27,"第四节 肠梗阻","肠套叠临床表现",1990,103,"C","","血便",[["A","粘连性肠梗阻"],["B","肠套叠"],["C","两者都有关"],["D","两者都无关"]],"B","肠套叠（B对）是儿童常见的急腹症，腹痛、血便和腹部肿块为其三大典型表现，需牢记。粘连性肠梗阻在未发展至嵌顿及绞窄前，临床表现以阵发性腹痛和呕吐为主。由于肠管血运尚可，故不出现肠壁坏死和渗血，无血便表现。","","N"],["1990-N104",27,"第四节 肠梗阻","肠套叠临床表现",1990,104,"C","","阵发绞痛",[["A","粘连性肠梗阻"],["B","肠套叠"],["C","两者都有关"],["D","两者都无关"]],"C","粘连性肠梗阻（A对）属于机械性肠梗阻，由于肠内容物下行受限，梗阻肠段以上肠管痉挛性收缩，即发生腹痛。之后由于肠管肌过度疲劳而呈暂时性迟缓状态，腹痛也随之消失，故机械性肠梗阻的腹痛是阵发性绞痛性质。肠套叠（B对）的三大典型症状是腹痛、血便和腹部肿块。表现为突然发作剧烈的阵发性腹痛，病儿阵发哭闹不安，有安静如常的间歇期。本题AB均对，正确答案为C。","","N"],["1990-N135",24,"第一节 腹部损伤概述","有无内脏损伤",1990,135,"X","","腹部闭合性损伤，出现下列情况应考虑有内脏损伤",[["A","有早期休克征象"],["B","肝浊音界消失"],["C","持续性剧烈疼痛"],["D","有呕血或黑便"]],"ABCD","有早期休克征象（A对）表明循环血量急剧减少，多由于腹部大血管损伤或实质性脏器破裂导致。肝浊音界消失（B对），由于肝表面覆盖气体导致，是急性胃肠穿孔的一个重要征象。持续性剧烈疼痛（C对）提示存在腹部损伤继发的急性弥漫性腹膜炎。有呕血或黑便（D对），提示存在腹部损伤引起的上消化道出血。闭合性损伤诊断中需要认真考虑是否有内脏损伤，且绝大部分内脏损伤者需早期手术治疗；如不能及时诊断，可能因贻误手术时机而导致严重后果。事实上，不仅“考点还原”上所述情况才考虑腹内脏器损伤，任何可能造成腹部损伤的外伤史加上腹内症状或全身失血症状均需警惕腹内脏器损伤的可能。","","N"],["1990-N136",25,"第一节 急性弥漫性腹膜炎","急性弥漫性腹膜炎诊断",1990,136,"X","","急性弥漫性腹膜炎的诊断可根据",[["A","持续性腹痛"],["B","中毒症状显著"],["C","腹膜刺激征"],["D","腹腔穿刺抽出脓性分泌物"]],"ABCD","腹痛是腹膜炎最主要的临床表现，急性弥慢性腹膜炎腹痛一般都很剧烈，难以忍受，呈持续性（A对）。此外还存在典型的腹膜刺激征（C对），即压痛、反跳痛和肌紧张。急性弥漫性腹膜炎由于腹腔内的菌群移位及毒素的吸收，可出现明显的中毒症状（B对）。腹腔穿刺抽出脓性分泌物，是腹腔内已形成化脓性炎症的最直接证据（D对）。","","N"],["1990-N137",30,"第二节 肝脓肿","细菌性肝脓肿临床表现",1990,137,"X","","细菌性肝脓肿的临床特征",[["A","全身中毒症状明显"],["B","常继发于胆道感染"],["C","血液细菌培养可为阳性"],["D","穿刺脓液为咖啡色"]],"ABC","细菌性肝脓肿常继发于胆道感染（B对）或其他的全身细菌性感染，起病急骤，全身中毒症状明显（A对），肝大不明显，多无局限性隆起。发生细菌性肝脓肿时，白细胞计数及中性粒细胞均明显升高，细菌培养阳性（C对），抗感染治疗明显有效。细菌性肝脓肿穿刺脓液多为黄白色脓液，涂片和培养有细菌，阿米巴肝脓肿穿刺脓液呈巧克力色（D错），无臭味，镜下可找到阿米巴滋养体","","N"],["1990-N138",30,"第二节 肝脓肿","细菌性肝脓肿检查",1990,138,"X","","对肝脓肿有帮助的辅助诊断方法",[["A","甲胎球蛋白的测定"],["B","同位素肝扫描"],["C","肝功能测定"],["D","超声波检查"]],"D","超声波检查（D对）可明确肝脓肿的部位和大小，其阳性诊断率可达96%以上，为首选的检查方法。甲胎蛋白（AFP）是动物胎儿期由卵黄囊、肝、胃肠道产生的一种球蛋白，肝癌、内胚窦瘤及妊娠者可增高，甲胎球蛋白的测定（A错）在我国用于肝癌筛查，及肝癌复发判断，但是对肝脓肿诊断无意义。放射性核素显像（即同位素扫描）是利用放射性核素及其标记化合物对疾病进行诊断和研究的一类方法，通过口服或注射等方式将含放射性核素标记的药物导入人体，与人体作用一段时间后，再通过体外计算机成像技术追踪放射性药物在体内分布情况，从而进行相关疾病的诊断。同位素肝扫描（B错）通常用于肿瘤的诊断。肝脓肿不吸收被标记药物，故无法对其进行诊断。肝脓肿时虽有肝功能减退，但肝硬化、病毒性肝炎等均可造成肝功能减退，不具有特异性，因而肝功能测定（C错）不能帮助诊断肝脓肿。老版X型题可有1～4个正确答案。","","N"],["1990-N139",22,"第四节 静脉疾病","非手术疗法",1990,139,"X","","预防下肢静脉曲张的措施是",[["A","需长时间站立者，可穿弹力袜"],["B","适当体育锻炼，增强体质及静脉管壁"],["C","勤换工作体位"],["D","改善劳动条件，减轻劳动强度"]],"ABCD","静脉壁软弱、静脉瓣膜缺陷、及浅静脉内压力（跨壁压）升高是引起下肢浅静脉曲张的主要原因。需长时间站立者，可穿弹力袜（A对），以降低跨壁压，且弹力袜的张力由下而上循序降低，可促进血液回流。勤换工作体位（C对），避免长时间的站立及坐姿，间歇活动肢体，可促进静脉回流，预防下肢静脉曲张。适当体育锻炼（B对），不仅可以通过肌肉泵的作用促进血液经深静脉回流，亦可增强体质及静脉管壁；改善劳动条件，减轻劳动强度（D对）可降低下肢浅静脉的跨壁压，并在一定程度上降低了对静脉回流的影响。本题ABCD均对，当年给出的答案为AC。","","N"],["1990-N140",23,"第二节 腹股沟疝","腹股沟疝诊断",1990,140,"X","","下列哪些情况可考虑为腹股沟直疝",[["A","术中发现疝囊颈位于腹壁下动脉的内侧"],["B","不易造成嵌顿"],["C","年老体弱"],["D","疝块坠入阴囊内"]],"ABC","根据“P347表35-1 斜疝和直疝的鉴别”可知：腹股沟斜疝的疝囊颈在腹壁下动脉外侧，腹股沟直疝的疝囊颈在腹壁下动脉内侧（A对）；腹股沟斜疝嵌顿机会较多，腹股沟直疝嵌顿机会极少（B对）；腹股沟斜疝多见于儿童及青壮年，腹股沟直疝多见于老年（C对）；腹股沟斜疝经腹股沟管突出，可进阴囊（D错），腹股沟直疝由直疝三角突出，很少进入阴囊。","","N"],["1990-N141",12,"第二节 心肺脑复苏","人工通气",1990,141,"X","","口对口呼吸的操作要领，以下哪些项目是正确的",[["A","将病人下颌向上后方勾起，头部稍向后仰"],["B","将病人鼻孔捏闭"],["C","深吸气后，对病人的口用力吹气"],["D","吹气频率：每分钟25～30次"]],"AB","对于口对口呼吸的操作，需注意正确的操作方式：（1）将病人下颌向上后方勾起，头部稍向后仰（A对），保持呼吸道通畅。（2）将病人鼻孔捏闭（B对），吸一口气，用口唇把病人的口全罩住，然后缓慢吹气，每次吹气应持续1 秒以上，确保呼吸时有胸廓起伏，施救者实施人工呼吸前，正常吸气即可，无需深吸气（C错）；每次吹毕即将口移开，此时病人凭胸廓的弹性收缩被动地自行完成呼气。（3）人工气道建立后可每6～8秒进行一次人工呼吸或8～10次/分，而不中断心脏按压（D错）。","","N"],["1990-N154",1,"第一节 水、电解质代谢紊乱和酸碱平衡失调概述","体液酸碱度的调节",1990,154,"X","","维持体液pH恒定，必需依靠哪些调节",[["A","血液缓冲系统"],["B","肺脏呼吸功能"],["C","肾脏的排泄和重吸收功能"],["D","每日饮水量的调节"]],"ABC","血液缓冲系统包括HCO₃⁻/H₂CO₃、蛋白质钠盐/蛋白、NaHPO₄/NaH₂PO₄三个缓冲对，参与维持血浆pH的恒定（A对）。肺对体液pH的调节是通过改变肺泡通气量来控制CO₂的排出量而实现的，PCO₂升高或H⁺浓度增高时，刺激中枢和外周化学感受器，使呼吸中枢兴奋，肺泡通气量增大，CO₂排出增多（B对）。肾脏通过分泌排泄H⁺、NH₄⁺和重吸收HCO₃⁻调节机体的酸碱平衡，以维持体液pH恒定（C对）。每日饮水量的调节与维持水和电解质平衡有关，与维持pH恒定无关（D错）。","","N"],["1991-N37",10,"第三节 全身麻醉","吗啡",1991,37,"A","","麻醉前用药中，使用麻醉性镇痛剂（吗啡等）的主要目的是下述哪项",[["A","降低耗氧量"],["B","镇静"],["C","抑制肠管运动"],["D","稳定血压"],["E","止呕"]],"B","麻醉性镇痛剂包括吗啡和哌替啶，主要作用有：镇痛；镇静、致欣快作用；抑制呼吸；镇咳；缩瞳；减慢胃蠕动等。用于麻醉前的主要目的是镇痛和镇静（B对）。降低耗氧量（A错）、抑制肠管运动（C错）、稳定血压（D错）、止呕（E错）也是麻醉性镇痛剂的作用，但不是麻醉前用药的主要目的。","","N"],["1991-N38",26,"","",1991,38,"A","","高选择性胃迷走神经切断术的要点是",[["A","不切断胃窦部的迷走神经支"],["B","保留迷走神经的左主干"],["C","保留迷走神经的右主干"],["D","保留胃壁细胞的迷走分支"],["E","不切断的迷走神经的肝、胆分支"]],"A","由“考点还原”可知，高选择性胃迷走神经切断术中，幽门括约肌的功能得以保留，不需附加引流术，减少了胆汁返流发生机会，而且保留了胃的正常容量，是治疗十二指肠溃疡较为理想的手术（A对）。迷走神经左、右主干及迷走神经的肝胆分支与溃疡发生无关（BCE错），不属于手术切除对象，本身就应予以保留。支配胃壁细胞的迷走分支（D错）为控制胃酸分泌的主要神经纤维，在手术中应尽量予以清除。八版外科学已将此术式删除。","","N"],["1991-N39",27,"第四节 肠梗阻","肠套叠诊断",1991,39,"A","","幼儿发生腹部绞痛、呕吐和便血，并扪及腹部包块，最可能是",[["A","先天性幽门肥厚"],["B","肠蛔虫症"],["C","肠套叠"],["D","肠系膜淋巴结炎"],["E","阑尾脓肿"]],"C","原发性肠套叠多见于2岁以内的幼儿，主要由肠蠕动节律紊乱引起。肠套叠（C对）三大典型症状是腹痛、血便和腹部肿块。表现为突然发作剧烈的阵发性腹痛，病儿阵发哭闹不安，有安静如常的间歇期。伴有呕吐和果酱样血便。先天性幽门肥厚（A错）可导致幽门部的狭窄，早期仅表现为溢奶，后以呕吐为主要表现，长期以往引起患儿营养不良，但无腹痛和便血表现。肠蛔虫症（B错）主要症状是儿童面黄肌瘦，营养不良表现，大量蛔虫缠绕可引起肠梗阻，但以腹痛和呕吐为主，较题中病例症状轻，通常无血便。肠系膜淋巴结炎（D错）好发于儿童和青少年，常发生于上呼吸道感染后，临床表现为腹痛为主，无呕吐和便血。阑尾脓肿（E错）是急性阑尾炎化脓穿孔后大网膜局限包裹形成，以腹痛为主要表现，无呕吐和便血症状，且患者多存在急性阑尾炎病史。","","N"],["1991-N40",25,"第一节 急性弥漫性腹膜炎","急性弥漫性腹膜炎辅助检查",1991,40,"A","","对诊断困难的急性化脓性腹膜炎病变，应做哪项检查以协助明确诊断",[["A","内镜检查"],["B","X线钡餐检查"],["C","诊断性腹腔穿刺"],["D","选择性血管造影"],["E","肝、胆、胰CT扫描"]],"C","内镜检查以腹腔镜为主，可以直观观察腹腔内病变状况，但是其操作难度大，病人需入手术室麻醉后方能执行，对设备和技术要求均较高；相比之下，诊断性腹腔穿刺通过B超引导穿刺腹腔积液，通过分析积液性质、涂片镜检和细菌培养，可以较清晰准确的反应急性化脓性腹膜炎的病变原因（C对A错）。X线钡餐检查（B错）主要用于胃癌及上消化道溃疡的诊断，对于腹膜炎的诊断价值有限。选择性血管造影（D错）多用于肠系膜缺血性疾病的诊断，以及消化道溃疡出血位置的判断，也不用于化脓性腹膜炎的诊断。肝、胆、胰CT扫描（E错）主要用于检查实质器官的病变情况（如急性胰腺炎），但对于急性化脓性腹膜炎，则无法快速准确的给予图像反应。","","N"],["1991-N46",2,"第二节 输血的不良反应及其防治","过敏反应概述",1991,46,"A","","下列哪项症状不是输血所致的过敏反应",[["A","发热"],["B","面色潮红，皮肤瘙痒"],["C","荨麻疹，血管神经性水肿"],["D","支气管痉挛"],["E","过敏性休克"]],"A","输血的并发症为考生需掌握的知识，包括发热反应、过敏反应、溶血反应、细菌污染反应、循环超负荷。重点鉴别为发热反应、过敏反应和溶血反应，其中发热反应无低压，过敏反应无发热（A错，为本题正确答案），溶血反应均有之，通过血压是否下降以及是否存在发热可以较快速鉴别三种并发症。","","N"],["1991-N47",1,"第五节 酸碱平衡失调","代谢性碱中毒治疗",1991,47,"A","","一幽门梗阻病人，血氯83毫克当量/升，血钾3.2毫克当量/升，应补给何种液体",[["A","生理盐水＋氯化钾"],["B","10%葡萄糖液＋氯化钾"],["C","复方氯化钠液"],["D","1.25%碳酸氢钠溶液＋氯化钾"],["E","20%氯化铵溶液＋氯化钾"]],"A","幽门梗阻病人，血氯83mmol/L（正常值103mmol/L），血钾3.2mmol/L（常值为3.5～5.3mmol/L），诊断考虑低钾低氯性碱中毒（钾摄入不足，且由于含有K⁺及Cl⁻的酸性胃液的大量丢失）。补充生理盐水＋氯化钾（A对）既恢复了细胞外液量，补充了Cl⁻，可起到纠正轻度碱中毒的作用，又补充了血钾。应注意须在病人尿量超过40ml/h才可开始补K⁺。10%葡萄糖液＋氯化钾（B错）可纠正缺水及低钾，但无法纠正碱中毒。复方氯化钠液（C错）多用于纠正等渗性缺水。1.25%碳酸氢钠溶液＋氯化钾（D错）为碱性液体，会加重碱中毒。20%氯化铵溶液＋氯化钾（E错）渗透压极高，不宜用于临床。","","N"],["1991-N48",13,"第二节 术后处理","引流管",1991,48,"A","","下列术后引流管的处理方法中，哪项是错误的",[["A","各种引流管注意无阻塞、扭曲、脱出"],["B","注意记录引流液的色泽和量"],["C","置于胆道的“T”形管引流一律在术后一周拔除"],["D","胃肠减压管在胃肠功能恢复后拔出"],["E","乳胶片引流多在术后24～48小时拔出"]],"C","外科引流为的是将人体组织间或体腔中积聚的脓、血、液体导引至体外，防止术后感染或影响伤口愈合。术后引流管的种类很多，比如胸腔引流管、腹腔引流管、T管、导尿管等。各种引流管使用时需注意无阻塞、扭曲、脱出（A对），以保证引流效果；对于引流液的色泽、量、性质等需作出详细记录（B对），以便及时发现病情变化并及时作出相应处理。T管主要用于胆总管取石术后对胆汁的引流，术后两周左右如胆道通畅无结石和其他病变，夹闭T管1～2天，若无腹痛、黄疸、发热等症状即可拔除；如病情不允许，应在手术6周后待纤维窦道形成后行纤维胆道镜检查和取石（C错，为本题正确答案）。胃肠减压管通常术后2～3天，胃肠道功能逐渐恢复，有肛门排气及肠蠕动，引流量减少即可拔除（D对），并开始进食，有助于胃肠道功能的重建。乳胶片通常用于浅表伤口的引流，一般在术后24～48小时即拔除（E对），时间过长有碍于伤口的愈合。有关各种导管的相应处理可参考七版黄家驷外科学P425。","","N"],["1991-N49",23,"第二节 腹股沟疝","腹股沟疝诊断",1991,49,"A","","鉴别腹股沟斜疝直疝最有意义的体征是",[["A","疝块的形状"],["B","疝块是否进入阴囊"],["C","还纳疝块，压住内环，增加腹压，疝块是否脱出"],["D","是否容易嵌顿"],["E","单侧还是双侧"]],"C","腹股沟斜疝为椭圆或梨形，腹股沟直疝为半球形。腹股沟斜疝经腹股沟管突出，可进阴囊，腹股沟直疝由直疝三角突出，很少进入阴囊。腹股沟斜疝嵌顿机会较多，腹股沟直疝嵌顿机会较少。腹股沟斜疝、直疝均好发于单侧（E错）。还纳疝块，压住内环，阻断了斜疝的突出路径，增加腹压，若此时疝块不能脱出，则为斜疝；若疝块仍然出现，则为直疝。根据疝块的形状（A），是否进入阴囊（B），是否发生嵌顿（D）也可鉴别腹股沟斜疝、直疝，但是最有意义的体征是还纳疝块，压住内环，增加腹压，看疝块是否脱出（C对）。","","N"],["1991-N56",44,"第一节 骨折的定义、成因、分类及移位","骨折成因概述",1991,56,"A","","男性20岁工人，用力打苍蝇时致右肱骨上端骨折，此时应首先考虑是",[["A","肱骨大结节撕脱骨折"],["B","肱骨外科颈骨折"],["C","肱骨解剖颈骨折"],["D","病理性骨折"],["E","疲劳骨折"]],"D","做“用力打苍蝇”动作时，骨骼仅受到轻微外力作用，患者出现右肱骨上端骨折，考虑患者本身已经存在骨骼疾病导致的骨质破坏，故该骨折考虑为病理性骨折（D对）。仅通过肱骨上段骨折无法明确判断骨折部位，须有典型体征或影像学检查，因而不考虑ABC选项。知识点延伸：对于病理性骨折，着重病因有“轻微”的特性，即可轻松解题，如轻微撞击引起的骨折通常为病理性骨折；疲劳性骨折（E错）常有解题题眼，如长途行军或新兵训练（跖骨骨折）或芭蕾舞演员（胫腓骨骨折）。","","N"],["1991-N57",57,"第四节 原发性恶性骨肿瘤","骨肉瘤临床表现",1991,57,"A","","下列哪项不是骨肉瘤的典型临床表现",[["A","多见于年轻人"],["B","好发于骨骺生长活跃部位"],["C","骨膜下三角形新生骨（Codman三角）"],["D","出现蜂窝状骨吸收区，夹有钙化斑块"],["E","早期肺转移"]],"D","骨肉瘤多见于年轻人（A对），好发于四肢长骨，尤其是股骨远端、胫骨近端和肱骨近端等骨骺生长活跃部位（B对）。骨肉瘤X线表现为不同形态，密质骨和髓腔有成骨性、溶骨性和混合性骨质破坏，骨膜反应明显，呈侵袭性发展，可见Codman三角（C对）或呈“日光射线”形态。骨肉瘤为间叶组织恶性肿瘤，多经血道转移，故早期易转移至肺（E对）。出现蜂窝状骨吸收区，夹有钙化斑块（D错，为本题正确答案），此为内生软骨瘤（十版外科学P763）的临床表现。","","N"],["1991-N58",55,"第四节 膝关节结核","膝关节结核关节镜检查",1991,58,"A","","确诊膝关节滑膜结核时，以下哪项最可靠",[["A","低烧、盗汗、食欲差"],["B","膝关节肿胀、疼痛、功能受限"],["C","血沉增块"],["D","X线检查膝关节骨质疏松"],["E","滑膜病理检查"]],"E","膝关节滑膜病理检查（E对）若发现典型的结核干酪样病灶或发现抗酸染色阳性细菌的存在，可基本确诊膝关节结核，最具特异性。低烧、盗汗、食欲差（A错）、血沉加快（C错）为结核病的全身表现，不具有特异性。膝关节肿胀、疼痛、功能受限（B错）不仅仅见于膝关节结核，其他关节疾病如类风湿性关节炎同样有此表现。多种疾病可引起X线检查膝关节骨质疏松（D错），不具特异性。","","N"],["1991-N59",7,"第一节 热力烧伤","深Ⅱ度烧伤",1991,59,"A","","深Ⅱ度烧伤局部损伤的深度是",[["A","真皮浅层，部分生发层健在"],["B","表皮层，生发层健在"],["C","真皮深层，有皮肤附件残留"],["D","脂肪层"],["E","脂肪下层"]],"C","皮肤分为表皮层，真皮层和皮下组织。表皮层（二版八年制组织学与胚胎学P161）位于皮肤浅层，由外到内依次是角质层、透明层、颗粒层、棘层、基底层（生发层）。真皮层（二版八年制组织学与胚胎学P164）位于表皮下，由外到内分为乳头层和网织层。皮下组织（二版八年制组织学与胚胎学P165）位于真皮下方，由疏松结缔组织和脂肪组织组成。Ⅰ°烧伤：仅伤及表皮浅层，生发层健在（B错）；浅Ⅱ°烧伤：伤及表皮的生发层和真皮乳头层（A错）；深Ⅱ°烧伤：伤及真皮乳头层以下，但仍残留部分网状层（C对）；Ⅲ°烧伤：又称焦痂型烧伤，全层皮肤烧伤，可深达肌肉甚至骨骼、内脏器官等（DE错）","","N"],["1991-N60",29,"第七节 直肠癌","直肠癌概述",1991,60,"A","","直肠癌最多见于",[["A","直肠与乙状结肠交界处"],["B","直肠壶腹部"],["C","腹膜反折平面以上的直肠内"],["D","齿状线附近"],["E","直肠上窝"]],"B","直肠癌最多见于直肠壶腹部（B对），约占直肠癌的2/3。直肠壶腹是直肠中最膨大的部位，也是粪便排出前的贮存部位，所以当排便的各种生理功能发生障碍时，此处也是容易受粪便中各种有害因素损伤之处，因此此处发生直肠癌的比例最高。","","N"],["1991-N80",0,"第四节 手术室的管理","手术室的管理相关制度",1991,80,"A","","关于无菌术的叙述中，下列哪项是正确的",[["A","手术室应二周彻底清扫一次"],["B","绿脓杆菌感染手术后，手术室应用乳酸空气消毒，1：1000新洁尔灭擦洗物品，并通风一小时"],["C","气性坏疽手术后，应用紫外线消毒"],["D","在HBsAg阳性的病人手术后，手术室应喷洒0.05%次氯酸钠水溶液，20分钟后清拭"],["E","手术室空气消毒最常用的是40%甲醛"]],"B","绿脓杆菌感染手术后，手术室应用乳酸空气消毒，1：1000新洁尔灭（即苯扎溴铵）擦洗物品，并通风一小时（B对）。一般每周要对手术间进行彻底清扫一次，包括地面、墙面、顶部、仪器设备表面等（A错）。气性坏疽手术后，用40%甲醛+高锰酸钾熏蒸（每100m³用40%甲醛200ml+高锰酸钾100g）（C错）。在HBsAg阳性的病人手术后，应喷洒0．1%次氯酸钠或优安净喷洒手术台或地面（黄家驷外科学第七版P174）（D错）。甲醛熏蒸过去常用于手术室的消毒，但其对工作人员的皮肤、神经系统、胃肠道及呼吸道存在一定不良影响，可导致机体免疫力下降，因此目前多用臭氧气体消毒（E错）。","","N"],["1991-N93",44,"第三节 骨折的并发症","缺血性肌挛缩",1991,93,"B","","石膏或夹板过紧会引起",[["A","Volkman缺血挛缩"],["B","创伤性关节炎"],["C","关节强直畸形"],["D","脂肪栓塞"],["E","骨化性肌炎"]],"A","Volkman缺血性肌挛缩，即挛缩畸形，为骨筋膜室综合征未及时处理的严重后果：因较短时间的完全缺血或程度较重的不完全缺血，积极恢复血液供应后，仍有部分肌肉坏死，尚能有纤维组织修复，但因瘢痕挛缩而形成的特有畸形。石膏或夹板过紧使得循环不畅，组织水肿，骨筋膜室内内容物体积增加，而过紧的石膏或夹板又使得骨筋膜室容积减小，造成骨筋膜室内压力过高，形成骨筋膜室综合征，若未得到及时处理，可导致不可逆坏死，出现Volkman缺血挛缩（A对）。关节内骨折可损伤关节面，软骨面不再平整，长期活动磨损会引起创伤性关节炎（十版外科学P618）（B错），致使关节活动时出现疼痛。关节强直畸形（十版外科学P618）（C错）是人体关节在病理状态下关节功能受限、发生纤维粘连所导致的屈伸不利，僵硬、发挺的一种状态，常由关节炎或骨结核引起。脂肪栓塞（D错）为骨折早期并发症之一，多由于较大的长骨骨折（多以股骨干骨折为题干），骨髓非造血组织中的大量脂肪进入血液，可引起肺、脑脂肪栓塞。骨化性肌炎（十版外科学P618）（E错）常见于关节脱位、扭伤及关节附近的骨折，多由于骨膜下出血、血肿机化并在关节附近的软组织内广泛骨化，影响关节活动功能，常见于肘关节。","","N"],["1991-N94",44,"第三节 骨折的并发症","创伤性关节炎",1991,94,"B","","关节内粉碎性骨折会引起",[["A","Volkman缺血挛缩"],["B","创伤性关节炎"],["C","关节强直畸形"],["D","脂肪栓塞"],["E","骨化性肌炎"]],"B","关节内粉碎性骨折使得关节面的正常结构丧失，不再平整，长期活动磨损会引起创伤性关节炎（B对），致使关节活动时出现疼痛。Volkman缺血性肌挛缩，为骨筋膜室综合征未及时处理的严重后果：因较短时间的完全缺血或程度较重的不完全缺血，积极恢复血液供应后，仍有部分肌肉坏死，尚能有纤维组织修复，但因瘢痕挛缩而形成的特有畸形。石膏或夹板过紧使得循环不畅，组织水肿，骨筋膜室内内容物体积增加，而过紧的石膏或夹板又使得骨筋膜室容积减小，造成骨筋膜室内压力过高，形成骨筋膜室综合征，若未得到及时处理，可导致不可逆坏死，出现Volkman缺血挛缩（A错）。关节强直畸形（十版外科学P618）（C错）是人体关节在病理状态下关节功能受限、发生纤维粘连所导致的屈伸不利，僵硬、发挺的一种状态，常因关节炎骨结核引起。脂肪栓塞（十版外科学P618）（D错）为骨折早期并发症之一，多由于较大的长骨骨折（多以股骨干骨折为题干），骨髓非造血组织中的大量脂肪进入血液，可引起肺、脑脂肪栓塞。骨化性肌炎（十版外科学P618）（E错）常见于关节脱位、扭伤及关节附近的骨折，多由于骨膜下出血、血肿机化并在关节附近的软组织内广泛骨化，影响关节活动功能，常见于肘关节。","","N"],["1991-N95",54,"第一节 化脓性骨髓炎","急性化脓性骨髓炎病理",1991,95,"A","","急性血源性骨髓炎早期的病理特点为",[["A","骨质破坏、坏死"],["B","骨髓内脓疡"],["C","骨膜下脓肿"],["D","反应性骨质增生"],["E","软组织蜂窝组织炎"]],"A","急性血源性骨髓炎早期，大量菌栓停滞在长骨的干骺端，阻塞了小血管，迅速发生骨质破坏、坏死（A对）。反应性骨质增生（D错）产生新骨，包绕在骨干的外层，形成“骨性包壳”，为急性血源性骨髓炎后期的病理特点。骨髓内脓疡（B错）、骨膜下脓肿（C错）为急性血源性骨髓炎进展期的病理特点。软组织蜂窝组织炎（E错）可蔓延至骨骼，引起化脓性骨髓炎，称为外来性骨髓炎。","","N"],["1991-N96",54,"第一节 化脓性骨髓炎","急性化脓性骨髓炎病理",1991,96,"A","","急性血源性骨髓炎后期的病理特点为",[["A","骨质破坏、坏死"],["B","骨髓内脓疡"],["C","骨膜下脓肿"],["D","反应性骨质增生"],["E","软组织蜂窝组织炎"]],"D","急性血源性骨髓炎后期有反应性骨质增生产生新骨，包绕在骨干的外层，形成“骨性包壳”（D对）。骨质破坏、坏死（A错）为急性血源性骨髓炎早期的病理特点。骨髓内脓疡（B错）、骨膜下脓肿（C错）为急性血源性骨髓炎进展期的病理特点。软组织蜂窝组织炎（E错）可蔓延至骨骼，引起化脓性骨髓炎，称为外来性骨髓炎。","","N"],["1991-N111",24,"第二节 常见内脏损伤的特征和处理","小肠损伤",1991,111,"C","","小肠损伤的手术方法是",[["A","修补或肠切除吻合"],["B","肠外置或造口术"],["C","两者均可"],["D","两者均不可"]],"A","小肠接受来自胃的食物，胃内高酸环境可杀灭随食物吞咽进入胃的微生物，可视为无菌环境，小肠承接胃内食物，相对清洁，小肠破裂通常可直接用间断横向缝合修补，若肠管损伤过重或已坏死，则可直接切除后做端端吻合（A对）。","","N"],["1991-N112",24,"第二节 常见内脏损伤的特征和处理","结肠损伤",1991,112,"C","","结肠损伤的手术方法通常是",[["A","修补或肠切除吻合"],["B","肠外置或造口术"],["C","两者均可"],["D","两者均不可"]],"B","结肠是消化道的下段部分，内储存着食物残渣转换粪便，滋生有大肠杆菌等肠道正常菌群，这些菌群若进入腹腔则可引起严重的感染，故行肠外置或造口术（B对）引流粪便，同时进行肠道准备做择期吻合手术。对于右半结肠损伤，若裂口小，腹腔污染轻，病人全身情况良好，可以行一期进行修补或肠切除吻合，但多数情况下无法满足上述条件，一期修补容易引起感染而导致手术失败，故不作为结肠损伤通常采用的手术方法（A错）。考虑到本题目出题时间，原答案为B，但根据最新临床观点，AB均对，应选择C。","","N"],["1991-N133",32,"第二节 胆道疾病影像学检查","胆道疾病X线检查",1991,133,"X","","下列哪些情况下，口服胆囊造影时，胆囊不显影",[["A","胃肠吸收功能不良，服药后腹泻"],["B","胆囊管有结石嵌顿"],["C","胆囊因有炎症，浓缩功能丧失"],["D","血胆红素﹥3.0mg/dl"]],"ABCD","口服胆囊造影后，在X线片上看不到胆囊，称为胆囊不显影。通常有以下三个因素：①胆囊本身因素：胆囊管有阻塞时，如胆囊管有结石嵌顿（B对），含有造影剂的胆汁不能进入胆囊；或是因胆囊的吸收功能减退，不能使造影剂浓缩，以致胆囊不能显影，这些大多数是由胆结石和胆囊炎引起的（C对）。②胆囊外因素：病人口服胆囊造影剂后呕吐、腹泻，便会影响到造影剂的吸收（A对）；肝功能有损害，血清胆红素在34μmol/L（2.0mg/dl）以上的病人，肝脏不能将造影剂排入胆汁（D对），等等。③其他：少数正常人，作口服胆囊造影检查，也会有胆囊不显影的情况发生。因此，遇到口服胆囊造影检查胆囊不显影时，要作具体的分析：如果病人没有因呕吐或腹泻等引起造影剂吸收不良或肝脏疾病时，可以再作一次胆囊造影检查，如果胆囊仍不显影，则胆囊有病变的可能性很大。也可采用一些其他的检查方法，如肝胆的B超检查来明确诊断。","","N"],["1991-N134",31,"门静脉高压","门静脉高压临床表现",1991,134,"X","","门静脉高压症的临床表现可有",[["A","消瘦"],["B","肝肿大，肝功能异常"],["C","食道静脉曲张"],["D","腹水"]],"BCD","门脉高压症对机体代谢无明显影响，且由于肝功能的损伤、血浆蛋白的合成减少、腹水的生成等原因使得病人出现水肿症状，而非消瘦（A错）。门静脉高压时，可出现肝脏淤血肿大。门脉血供占肝脏血供的约70%，门脉高压时，肝脏血供减少，肝细胞代谢紊乱，可出现肝功能异常（B对）。门脉高压时，可导致门静脉与腔静脉系的交通支开放，出现食道静脉曲张（C对）。门静脉压力升高，使门静脉系统毛细血管床的滤过压升高，同时肝硬化引起的低蛋白血症，血浆胶体渗透压下降及淋巴液生成增加，促使液体从肝表面、肠浆膜面漏入腹腔而形成腹水。门静脉高压症时虽然静脉内血流量增加，但中心血流量却是减少的，继发刺激醛固酮分泌过多，导致钠、水潴留而加剧腹水形成（D对）。","","N"],["1991-N135",12,"第二节 心肺脑复苏","药物治疗",1991,135,"X","","心脏复苏时，关于心脏用药以下哪些是正确的",[["A","应首选心内注射给药"],["B","应首选肾上腺素"],["C","应首选异丙肾上腺素"],["D","应首选静脉内给药"]],"BD","在急救情况下，如心肺复苏时，药物的作用要求为尽可能短的时间内获得尽可能有效的治疗效果，首选静脉给药（D对），药物直接进入血液循环，高血药浓度的血液流经全身各个组织并作用于靶器官，作用迅速有效。骨内给药药物也是直接进入血液，亦视为首选给药途径。心内注射虽然药物直接作用于心脏，但该操作实际上运行困难，且风险大，无法保证抢救效果，甚至加重机体的损害（A错）。肾上腺素具有如下特征：①具有α与β肾上腺能受体兴奋作用，有助于自主心律的恢复；②可使舒张压升高，周围血管总阻力增加而不增加冠脉和脑血管的阻力；③能增强心肌收缩力，可使室颤者由细颤波转为粗颤波，提高电除颤成功率。鉴于如上特点，肾上腺素被作为心肺复苏中首选药物（B对）。异丙肾上腺素主要激动β受体，对β₁和β₂受体选择性很低，对α受体几乎无作用。对心脏β₁受体具有强大的激动作用，对停搏的心脏具有起搏作用，适用于心室自身节律缓慢，高度房室传导阻滞或窦房结功能衰竭而并发的心脏骤停（C错）。","","N"],["1991-N136",44,"第一节 骨折的定义、成因、分类及移位","开放性骨折",1991,136,"X","","下列哪些骨折属于开放性骨折",[["A","骨折断端刺破皮肤及粘膜外露"],["B","肋骨骨折，肺破裂，血气胸"],["C","耻骨骨折，尿道断裂"],["D","尾骨骨折，直肠破裂"]],"ABCD","闭合性骨折指骨折处皮肤及筋膜或骨膜完整，骨折端不与外界相通。开放性骨折指骨折处皮肤及筋膜或骨膜破裂，骨折端与外界相通。骨折处的创口可由刀伤、枪伤由外向内形成，亦可由骨折端刺破皮肤或黏膜从内向外所致。骨折断端刺破皮肤及黏膜外露（A对），骨折断端直接经皮肤破口与外界相通；肋骨骨折，肺破裂，血气胸（B对），骨折断端经呼吸道与外界相通；耻骨骨折，尿道断裂（C对），骨折断端经尿道与外界相通；尾骨骨折，直肠破裂（D对），骨折断端经直肠与外界相通，以上四者均属于开放性骨折。","","N"],["1991-N140",19,"第三节 气胸","张力性气胸",1991,140,"X","","气胸时发生休克的原因有",[["A","张力性气胸"],["B","交通性气胸"],["C","胸膜撕裂大出血"],["D","剧烈胸痛"]],"ABCD","张力性气胸（A对）时，破裂口呈单向活瓣或活塞作用，胸腔内压力不断增加，阻碍静脉回流，回心血量减少，进而使心排血量减少，组织灌注不足，导致休克；交通性（开放性）气胸（B对）患者呼、吸气时，出现两侧胸膜腔压力不均衡的周期性变化，使纵隔在吸气时移向健侧，呼气时移向伤侧，称为纵隔扑动，纵隔扑动和移位影响静脉回心血量，引起循环障碍；胸膜撕裂大出血（C对）会导致低血容量性休克；剧烈胸痛（D对）会导致疼痛性休克。","","N"],["1991-N142",6,"第二节 创伤的病理生理","全身反应",1991,142,"X","","创伤后，下列哪种激素上升",[["A","17羟类固醇"],["B","酮类固醇"],["C","上述两者同等升高"],["D","生长激素升高"]],"AD","当机体遭受到各种有害刺激，如创伤、手术、感染、中毒等，体内可释放大量ACTH和GC，引起机体发生非特异性的防御反应，即应激。此时体内明显增加的激素还有儿茶酚胺、催乳素、生长激素（D对）、醛固酮等（十版生理学P326）。17-羟类固醇为肾上腺皮质激素的代谢产物，创伤时肾上腺皮质激素分泌增多，导致肾上腺皮质激素的代谢产物 17- 羟类固醇也随之升高（A对）。酮类固醇主要是肾上腺及睾丸雄激素的代谢产物，男性2/3来自肾上腺，1/3来自睾丸；女性则主要来自肾上腺，创伤对雄激素的分泌无明显影响（BC错），因此酮类固醇不会上升。","","N"],["1991-N143",4,"第三节 肠外营养","肠外营养适应证",1991,143,"X","","下列哪些病人应当立即给予深静脉高营养",[["A","女68岁，幽门梗阻患者，PH7.52，PaCO₂46mmHg，HCO₃37mEq/L"],["B","新生儿，小肠闭锁，正常小肠很短，仅14厘米"],["C","男74岁，脑血管意外后，不能主动进食已两周"],["D","女24岁，因胃手术后第9天出现高位小肠瘘"]],"BD","给予深静脉高营养即给予肠外营养，凡是需要营养支持，但又不能或不宜接受肠内营养支持的病人均为肠外营养支持的适应证。女68岁，幽门梗阻患者，虽然幽门梗阻无法进食，但是患者肠道吸收功能无障碍，可以通过空肠插管跨过梗阻的幽门给予肠内营养（A错）；男74岁，脑血管意外后，不能主动进食已两周，但病人肠道功能无损伤，可给予肠内营养维持病人生存（C错）。新生儿，小肠闭锁，正常小肠很短，仅14厘米，即使给予肠内营养，也无法充分吸收满足机体所需，需给予肠外营养维持直至手术治疗患儿的小肠闭锁成功（B对）；女24岁，因胃手术后第9天出现高位小肠瘘（D对），肠瘘患者若给予肠内营养，营养液经瘘口流出可引起急性腹膜炎，故只能给予肠外营养。","","N"],["1991-N144",25,"第一节 急性弥漫性腹膜炎","急性弥漫性腹膜炎病理生理",1991,144,"X","","急性化脓性腹膜炎，导致休克是由于",[["A","心肌功能障碍"],["B","细菌毒素吸收"],["C","有效循环血量减少"],["D","肝功能衰竭"]],"BC","急性化脓性腹膜炎，腹内脏器浸泡在脓性液体中，腹膜严重充血、水肿并渗出大量液体，引起脱水和电解质紊乱，血浆蛋白减低。加之发热、呕吐，肠管麻痹，肠腔内大量积液使血容量明显减少，导致低血容量性休克（C对）。同时因腹膜吸收大量的毒性物质，细菌毒素入血而引发感染性休克（B对）。肠管因麻痹而扩张、胀气，可使 膈肌抬高而影响心肺功能，使血液循环和气体交换受到影响，加重休克导致死亡；毒素入血对于肝功能也存在一定的影响，但是这些都是急性化脓性腹膜炎所造成的后果，而非休克的原因（AD错）。","","N"],["1991-N147",17,"第一节 甲状腺疾病","术后呼吸困难和窒息",1991,147,"X","","甲状腺大部切除术后，出现呼吸困难和窒息，可能由于下列哪些原因造成",[["A","出血压迫"],["B","一侧喉返神经损伤"],["C","喉头水肿"],["D","气管塌陷"]],"ACD","喉返神经含支配声带及喉部肌肉的运动神经纤维，一侧喉返神经损伤，一侧声带麻痹，可引起声嘶，一般不引起呼吸困难和窒息（B错）；双侧喉返神经损伤，可导致双侧声带麻痹，喉肌瘫痪，引起失音或严重的呼吸困难，甚至窒息，需立即作气管切开。甲状腺手术后，伤口引流不畅，出血淤积在切口内，向后压迫气管（A对），可导致呼吸困难和窒息。手术创伤或气管插管可损伤气管黏膜，使喉头黏膜水肿（C对），阻塞气道，引起呼吸困难和窒息。气管壁长期受肿大甲状腺压迫，发生软化，切除甲状腺体的大部分后软化的气管壁失去支撑而塌陷（D对），也可阻塞气道，引起呼吸困难和窒息。","","N"],["1992-N25",0,"第二节 手术人员和病人手术区域的准备","病人手术区的准备",1992,25,"A","","手术区皮肤消毒范围．应包括切口周围",[["A","5厘米"],["B","10厘米"],["C","15厘米"],["D","20厘米"],["E","30厘米"]],"C","病人手术区准备的目的是清除手术切口处及其周围皮肤上的暂居菌，并抑制常驻菌群的移动，最大限度减少手术部位相关感染。需注意擦消毒剂时应由手术区中心部向四周涂擦；如为感染部位或肛门、会阴区手术，则应由手术区域外周向中心涂擦。手术区皮肤消毒范围要包括手术切口周围15cm的区域（C对），如切口有延长可能，应相应扩大皮肤消毒范围。","","N"],["1992-N26",1,"第二节 水、钠代谢紊乱","等渗性脱水诊断",1992,26,"A","","急性肠梗阻病人大量呕吐，脉细速，血压下降，可能是",[["A","低渗性脱水"],["B","等渗性脱水"],["C","高渗性脱水"],["D","低钾血症"],["E","高钾血症"]],"B","等渗性缺水/急性缺水/混合性缺水多发生于急性体液丢失，如急性肠梗阻（B对）发生大量呕吐、大面积烧伤后的体液渗出等情况。低渗性缺水（A错）多发生于慢性体液丢失，如慢性肠梗阻长期反复呕吐、长期胃肠减压、利尿剂的不当使用以及医源性补液不当引起（十版外科学P12）。高渗性缺水（C错）主要原因是水分摄入过少及丧失过多，如长期无法进水、高热大量出汗、糖尿病大量尿排出等（十版外科学P12）。低钾血症（D错）及高钾血症（E错）的症状主要表现为肌肉无力和心电图的异常，与题干不符（十版外科学P14-P15）。消化液大量丢失时，可同时伴有钾的丢失，但该患者可能因血液浓缩，低钾不明显，补充不含钾盐的液体之后可发生低钾的相关症状。上述各类脱水诊断及病因应当熟记，对判断是何种脱水很有帮助。","","N"],["1992-N67",51,"第二节 慢性软组织损伤","腰腿痛病因和分类",1992,67,"A","","下列选项不是引起下腰痛的诱因",[["A","急慢性损伤"],["B","感染"],["C","骨质疏松、代谢紊乱"],["D","高位截瘫"],["E","下肢不等长、扁平足"]],"D","高位截瘫发生时，截瘫节段水平以下运动功能丧失，深浅反射消失，包括痛觉在内的感觉功能亦丧失（D错，为本题正确答案）。腰部肌肉、腰椎处的急慢性损伤，可产生腰痛（A对）。发生于腰部肌肉间隙、肾盂等部位的感染，可引起腰部疼痛（B对）。全身性内分泌障碍，如甲状旁腺功能亢进、老年雌激素缺乏等均有可能引起骨质疏松症，从而造成腰背部疼痛（C对）。下肢不等长使得脊柱承受重力不平衡，扁平足者没有足弓缓冲行走时地面对脚步的反冲力，传导至腰椎的力增加，均可对腰椎造成慢性损伤，引起腰部疼痛（E对）。","","N"],["1992-N68",54,"第一节 化脓性骨髓炎","慢性血源性骨髓炎治疗",1992,68,"A","","8岁男孩急性化脓性骨髓炎已3个月，胫骨中上段有4厘米长整段死骨，周围少许包壳，有瘘道流脓，近三日脓少，发热39℃，局部红肿。下列哪项治疗方法不宜采用",[["A","大量抗生素静脉点滴"],["B","手术取出死骨"],["C","切开引流"],["D","少量输血"],["E","局部应固定"]],"B","八岁男孩急性化脓性骨髓炎3月，已进入慢性阶段。近三日脓少，发热39℃，局部红肿，提示慢性骨髓炎急性发作。此时应以抗生素治疗为主（A对），积脓时宜切开引流（C对）。化脓性感染时往往会有贫血，可隔1～2天输给少量新鲜血（D对），以增加病人的抵抗力。肢体可作皮肤牵引或石膏拖固定，可以起到止痛、防止关节挛缩畸形和防止病理性骨折的作用（E对）。患者有大块死骨而包壳尚未充分生成，过早取掉大块死骨会造成长段骨缺损，因此须等待包壳生成后再手术（B错，为本题正确答案）。","","N"],["1992-N69",2,"第二节 输血的不良反应及其防治","溶血反应概述",1992,69,"A","","一位病人输血40毫升时发生寒战、发热、呼吸困难、腰痛等症状常常提示",[["A","溶血性输血反应"],["B","发热性反应"],["C","血液污染"],["D","变态反应"],["E","枸橼酸盐的毒性"]],"A","输血的并发症为考生需掌握的知识，包括发热反应、过敏反应、溶血反应、细菌污染反应、循环超负荷等。此题可通过不良反应发生的时间对输血并发症进行判断：发热反应（B错）发生在输血后15分钟～2小时内；过敏反应（D错）多发生在输血数分钟后，也可在输血中或输血后发生，临床表现为皮肤局限性或全身性瘙痒或荨麻疹，严重者可出现支气管痉挛、血管神经性水肿、会厌水肿等，表现为咳嗽、喘鸣、呼吸困难以及腹痛、腹泻，甚至过敏性休克乃至昏迷、死亡；溶血反应（A对）在输入十几毫升血型不合的血后立即发生，临床表现为沿输血静脉的红肿及疼痛，寒战、高热、呼吸困难、腰背酸痛、头痛、胸闷、心率加快乃至血压下降、休克，随之出现血红蛋白尿和溶血性黄疸；血液污染反应（C错）多发生在输血后，病人的反应程度依细菌污染的种类、毒力大小和输入的数量而异，临床多表现为烦躁、寒战、高热等中毒症状。枸橼酸盐中毒（十版外科学P25）（E错）是大量输血后产生的并发症，会导致碱中毒以及暂时性低血钙症。","","N"],["1992-N71",5,"第五节 脓毒症","脓毒症诊断",1992,71,"A","","对败血症的病人，抽血送培养的时间最好选择在",[["A","人发热开始时"],["B","发热最高峰时"],["C","寒战初起时"],["D","寒战结束时"],["E","预计寒战、发热前"]],"C","对临床诊断为败血症或怀疑为败血症的病人，都应进行血培养检查，一是明确诊断，二是为找出病原菌，以便合理使用敏感的抗生素。为达到此目的，要使培养的阳性检出率提高，就应在血液循环内的致病菌尚未被人体的防御系统消除和输入的抗生素所杀灭前抽取血标本最合适。老版教材认为：抽血时间最好选择在预计发生寒战和发热之前（E），新版教材认为有寒战、高热时采血送检进行细菌培养，较易发现细菌。此题年代久远，按照最新观点，ABC均可作为抽血送检时间，原参考答案为E。","","N"],["1992-N72",17,"第一节 甲状腺疾病","甲状腺癌病理",1992,72,"A","","下列关于甲状腺癌的描述中哪项不正确",[["A","乳头状腺癌是最常见的甲状腺癌"],["B","滤泡状腺癌发展较迅速，属中等恶性"],["C","未分化癌属高度恶性，多采用同位素治疗"],["D","髓样癌能分泌降钙素"],["E","晚期甲状腺癌可压迫颈交感神经产生Horner综合征"]],"C","甲状腺乳头状癌约占成人甲状腺癌的60%和儿童甲状腺癌的全部，是最常见的甲状腺癌（A对）。甲状腺滤泡状腺癌较乳头状腺癌少见，发展迅速，属中度恶性肿瘤（B对）。晚期甲状腺癌因体积变大，或浸润周围组织的关系，可压迫颈交感神经产生Horner综合征（E对）。髓样癌来源于甲状腺滤泡旁细胞，属于神经内分泌肿瘤，能够分泌降钙素（D对）。未分化癌细胞分化极差，属高度恶性肿瘤，且瘤细胞对¹³¹I摄取率极低，不能够达到内放射治疗的效果（C错，为本题正确答案），但可用放射外照射治疗。","","N"],["1992-N73",23,"第二节 腹股沟疝","直疝三角",1992,73,"A","","下列哪项构成直疝三角",[["A","腹直肌外缘、凹间韧带、腹股沟韧带"],["B","腹直肌外缘、腹壁下动脉、腹股沟韧带"],["C","陷窝韧带、股静脉、腹股沟韧带"],["D","联合肌腱、腹股沟韧带、腹壁下动脉"],["E","凹间韧带、腹直肌外缘、联合肌腱"]],"B","直疝三角又称“海氏三角”，其外侧边是腹壁下动脉，内侧边为腹直肌外侧缘，底边为腹股沟韧带（B对）。此处腹壁缺乏完整的腹肌覆盖，且腹横筋膜又比周围部分薄，故容易发生疝。腹股沟直疝即在此由后向前突出，故称直疝三角。","","N"],["1992-N74",24,"第二节 常见内脏损伤的特征和处理","肝损伤",1992,74,"A","","关于肝破裂的描述．下列哪项是错误的",[["A","肝损伤常合并胆汁性腹膜炎"],["B","肝破裂右肝较左肝多"],["C","肝破裂如肝静脉主干有损伤，有并发空气栓塞的可能"],["D","肝破裂应行肝叶切除术"],["E","肝破裂常有胆道出血"]],"D","肝损伤可伴有毛细胆管中胆汁漏出，常导致胆汁性腹膜炎（A对）。右肝体积原较左侧肝脏大，因而肝破裂右肝较左肝多（B对）。肝破裂如肝静脉主干有损伤，有并发空气栓塞的可能（C对），因肝静脉常为负压，破裂后可导致空气进入血液循环。肝破裂后，血液有时可通过胆管进入十二指肠而出现黑便或呕血，即导致胆道出血（E对）。肝叶切除术（D错，为本题正确答案）属于规则性肝切除，是指按解剖分区施行切肝，如肝段、半肝切除。规则性肝叶切除创伤大，本身就是对伤员的又一次沉重打击，在严重创伤条件下施行半肝或近半肝切除，死亡率可高达50%，因此不应轻易施行。缝合是治疗肝裂伤最常用的方法，大多数边缘整齐的裂伤可做间断普通缝合或褥式缝合，并常规放置引流以防胆汁渗漏和感染。对伴有大块肝组织破损，特别是粉碎性肝破裂，或肝组织挫伤严重的病人应施行肝切除术，但不宜采用创伤大的规则性肝切除术，而是在充分考虑肝解剖特点的基础上作清创式肝切除术。","","N"],["1992-N75",28,"第二节 急性阑尾炎","右下腹压痛",1992,75,"A","","急性阑尾炎病人，当腹痛尚未转至右下腹前，在诊断上具有重要意义的是",[["A","已出现发热"],["B","已有白细胞显著升高"],["C","已有脐区压痛和反跳痛"],["D","脐区及右下腹均有压痛、反跳痛"],["E","压痛已固定在右下腹"]],"E","右下腹压痛是急性阑尾炎最常见的重要体征，故压痛已固定在右下腹在急性阑尾炎病人的诊断上具有重要意义（E对）。发热（A错）、白细胞显著升高（B错），此为炎症反应的全身症状，无法以此诊断早期阑尾炎。阑尾炎引起的脐周疼痛属于牵涉性内脏痛，脐区本身无炎症等病变，故不会产生压痛及反跳痛（CD错）。","","N"],["1992-N76",29,"第九节 肛裂","肛裂概述",1992,76,"A","","肛裂最常见于胸膝位",[["A","12点处"],["B","3点处"],["C","6点处"],["D","9点处"],["E","3点和6点处"]],"A","肛管外括约肌浅部在肛门后正中形成的肛尾韧带伸缩性差、坚硬且血供较差；肛管与直肠成角相延续，排便时，肛管后壁承受的压力最大，故后正中线易受损伤。病人采取胸膝位时后正中线位于最上方，即12点处（A对）。若病人采用截石位，则为6点处。","","N"],["1992-N77",29,"第六节 结肠癌","结肠癌并发急性肠梗阻的手术",1992,77,"A","","左半结肠癌合并急性肠梗阻时，手术方法应是",[["A","局部肠段切除术"],["B","回肠直肠吻合术"],["C","癌近端肠管捷径术"],["D","先行横结肠造口术，以后再行左半结肠切除术"],["E","先行胃肠减压解除梗阻，然后再行左半结肠根治术"]],"D","目前病人的主要矛盾是急性肠梗阻，治疗原则应以解除梗阻为主，切除病灶应放在次要位置。一味追求一期就切除肿瘤吻合，不顾及肠管局部（尤其近端结肠易充血、水肿）及病人的全身情况，有可能会发生吻合口愈合不良、腹膜炎等并发症，所以任何直接行肠段吻合的手术均是不恰当的。正确的是暂行横结肠造瘘术，解除梗阻，待肠管炎症、水肿消退恢复正常，病人一般状况改善后，再限期行二期病灶切除或根治性手术（D对）。","","N"],["1992-N78",12,"第二节 心肺脑复苏","复苏后治疗",1992,78,"A","","心肺复苏的后期处理（院内处理）不包括下列哪项工作",[["A","接替人工呼吸、心脏按摩进行生理监测"],["B","心律转复"],["C","输血输液"],["D","呼吸道管理"],["E","立即对并发的创伤或病变进行外科治疗"]],"E","进行系统的复苏后治疗（PCAC）不仅可以降低因复苏后循环不稳定引起的早期死亡率，及因多器官功能障碍和脑损伤引起的晚期死亡率，而且可以改善病人生存质量。故病人自主循环恢复后应立即转运到有ICU条件的医疗单位进行复苏后治疗。复苏后治疗的主要内容是防治缺氧性脑损伤和多器官功能障碍或衰竭，维持呼吸和循环功能稳定是前提。120赶到后，首先接手病人的胸外按压和人工呼吸，并给予生理各项指标的监测（A对）；对于心律失常发生危及生命者，急救人员携带电除颤仪，给予电复律纠正（B对）。给予呼吸管理（D对）和维持血流动力学稳定（C对），同时需注意多器官功能障碍或衰竭的防治及脑复苏的进行。抢救病人生命是第一要务，对并发的创伤或病变进行外科治疗为次要矛盾，在确保病人已无生命危险后才可考虑执行（E错，为本题正确答案）。","","N"],["1992-N79",44,"第一节 骨折的定义、成因、分类及移位","开放性骨折",1992,79,"A","","耻骨及坐骨支骨折造成直肠损伤，此骨折属于",[["A","稳定骨折"],["B","青枝骨折"],["C","开放骨折"],["D","闭合骨折"],["E","多发骨折"]],"C","开放性骨折指骨折处皮肤及筋膜或骨膜破裂，骨折端与外界相通。骨折处的创口可由刀伤、枪伤由外向内形成，亦可由骨折端刺破皮肤或黏膜从内向外所致。耻骨及坐骨支骨折造成直肠损伤，骨折断端经直肠与外界相通，属于开放骨折（C对）。","","N"],["1992-N80",53,"第一节 颈椎退行性疾病","颈椎病非手术治疗",1992,80,"A","","下列有关颈椎病的诊断治疗哪些是错误的",[["A","各种类型颈椎病均可行推拿牵引治疗"],["B","一过性脑缺血症状有时是由颈椎病所致"],["C","颈椎病可有视物模糊、复视、耳鸣、心前区疼痛等症状"],["D","颈椎病是颈椎骨质增生所致常伴有上肢放射痛及感觉障碍"],["E","颈椎病均应行颈椎X线检查"]],"A","本题不严谨，并未区分颈椎病不同分型。神经根、交感、椎动脉型颈椎病首选保守治疗，只有符合手术指征者方选择手术治疗；脊髓型颈椎病容易引起肢体不同程度的残疾，脊髓长期受压迫及反复刺激后手术治疗效果不良，故一旦诊断明确，应早期手术治疗，推拿牵引不适用于该型病人（A错，为本题正确答案）。对于椎动脉型颈椎病，病因便是由于椎动脉各种原因引起的管径减少或管腔阻塞，引起脑部血供不足所致的一系列症状（B对）。椎动脉型颈椎病可由基底动脉供血不全引起，出现偏头痛、耳鸣、视力障碍、突发性眩晕等，由于椎动脉周围有大量交感神经的节后纤维，可出现心慌、心悸、心律失常等自主神经症状（C对）。颈椎病的发病原因有许多，除了颈椎组织的退行性病变以外，颈椎骨质增生同样可导致神经根受到压迫，从而产生受压神经根支配部位的上肢放射痛及感觉障碍（D对）。X线可显示颈椎曲度改变，结合相应临床表现，为颈椎病的诊断和分型提供证据，因此颈椎病均应行颈椎X线检查（E对）。","","N"],["1992-N93",29,"第六节 结肠癌","结肠癌诊断",1992,93,"B","","大肠腺癌",[["A","CEA升高"],["B","AFP升高"],["C","碱性磷酸酶升高"],["D","酸性磷酸酶升高"],["E","胎儿硫糖蛋白升高"]],"A","CEA即癌胚抗原，是胎儿胃肠道产生的一组糖蛋白，在结肠癌、胃癌、肺癌、乳癌CEA升高（A对），也可用于大肠癌的术后判断预后和复发。AFP为甲胎蛋白，是动物胎儿期由卵黄囊、肝、胃肠道产生的一种球蛋白，AFP升高（B错）常见于肝癌、内胚窦瘤及妊娠，在我国用于肝癌普查，效果良好。骨肉瘤是最常见的原发性恶性骨肿瘤，其具有较为明显的生化表现，即血浆碱性磷酸酶（C错）和乳酸脱氢酶的中度至大幅升高，尤其是碱性磷酸酶（十版外科学P760）的升高反映了肿瘤细胞成骨活动。酸性磷酸酶（九版外科学P772）升高（D错），多作为前列腺癌和前列腺癌发生骨转移的辅助诊断。胎儿硫糖蛋白升高（E错）见于胃癌。","","N"],["1992-N94",57,"第四节 原发性恶性骨肿瘤","骨肉瘤诊断",1992,94,"B","","骨肉瘤",[["A","CEA升高"],["B","AFP升高"],["C","碱性磷酸酶升高"],["D","酸性磷酸酶升高"],["E","胎儿硫糖蛋白升高"]],"C","血清碱性磷酸酶反映成骨活动，在成骨性肿瘤如骨肉瘤中，患者血清碱性磷酸酶升高（C对）。CEA即癌胚抗原，是胎儿胃肠道产生的一组糖蛋白，CEA（九版外科学P391）升高（A错）常见于结肠癌、胃癌、肺癌、乳癌，可用于大肠癌的术后病情监测及复发判断。AFP为甲胎蛋白，是动物胎儿期由卵黄囊、肝、胃肠道产生的一种球蛋白，AFP升高（B错）见于肝癌、内胚窦瘤及妊娠反应，在我国用于肝癌普查，效果良好。酸性磷酸酶升高（D错），多作为前列腺癌和前列腺癌发生骨转移的辅助诊断。胎儿硫糖蛋白升高（E错）见于胃癌。","","N"],["1992-N123",50,"第二节 上肢神经损伤","桡神经损伤",1992,123,"C","","桡神经深支损伤有",[["A","腕下垂"],["B","掌指关节不能主动伸直，拇指不能外展"],["C","两者均有"],["D","两者均无"]],"B","桡神经向下走行时可分为浅支和深支，其中浅支主司感觉，深支主司运动。桡神经主干损伤的表现为伸腕、伸指、前臂旋后障碍及手背桡侧（虎口区）感觉异常，典型表现为垂腕畸形。仅浅支损伤时，仅手背桡侧区感觉异常，不影响运动功能。仅深支损伤时，因深支支配拇指背伸的肌肉群，仅掌指关节不能主动伸直，拇指不能外展（B对），不影响感觉功能，但由于桡侧伸腕长肌的功能尚存，故无垂腕畸形。","","N"],["1992-N124",50,"第二节 上肢神经损伤","桡神经损伤",1992,124,"C","","桡神经浅支损伤有",[["A","腕下垂"],["B","掌指关节不能主动伸直，拇指不能外展"],["C","两者均有"],["D","两者均无"]],"D","桡神经向下走行时可分为浅支和深支，其中浅支主司感觉，深支主司运动。桡神经主干损伤的表现为伸腕、伸指、前臂旋后障碍及手背桡侧（虎口区）感觉异常，典型表现为垂腕畸形。仅浅支损伤时，仅手背桡侧区感觉异常，不影响运动功能（AB错）。仅深支损伤时，因深支支配拇指背伸的肌肉群，仅掌指关节不能主动伸直，拇指不能外展，不影响感觉功能，但由于桡侧伸腕长肌的功能尚存，故无垂腕畸形。本题AB均错，正确答案为D。","","N"],["1992-N125",57,"第二节 良性骨肿瘤","软骨瘤",1992,125,"C","","内生软骨瘤",[["A","好发于长管骨干骺端"],["B","好发于短管骨内"],["C","两者均可"],["D","两者均不可"]],"B","软骨瘤是一种松质骨的、透明软骨组织构成的、软骨源性的良性肿瘤，好发于手和足的管状骨（B对），其中，位于骨干中心者称为内生软骨瘤。","","N"],["1992-N126",57,"第三节 骨巨细胞瘤","骨巨细胞瘤概述",1992,126,"C","","巨细胞瘤",[["A","好发于长管骨干骺端"],["B","好发于短管骨内"],["C","两者均可"],["D","两者均不可"]],"A","骨巨细胞瘤好发于20～40岁。女性略多，好发部位为长骨干骺端（A对）和椎体，特别是股骨远端和胫骨近端，这是十版外科学的最新观点。按照旧版本教材，该题D选项正确。","","N"],["1992-N129",10,"第五节 椎管内麻醉","蛛网膜下腔麻醉",1992,129,"X","","关于腰麻，下述哪些是正确的",[["A","用丁卡因时，其麻醉时间比普鲁卡因长"],["B","腰麻前需保证静脉通路之通畅"],["C","麻黄素是治疗腰麻后血压下降的有效药物"],["D","腰麻后头疼，于立位时加重"]],"ABCD","局麻药注入到蛛网膜下隙，阻断部分脊神经的传导功能而引起相应支配区域的麻醉作用称为蛛网膜下隙阻滞，又称腰麻。腰麻主要适用于2～3小时以内的下腹部、盆腔、下肢和肛门会阴部手术，如阑尾切除、疝修补、半月板摘除、痔切除、肛瘘切除术等。常用药物有普鲁卡因（作用时间1～1.5小时）、丁卡因（作用时间为2～3小时），布比卡因（作用时间为5～6小时）。腰麻操作本身是风险操作，过程中可能发生局麻药的毒性反应，且麻醉过程中也可能发生麻醉过深引起血压、心率过低等症状，故需要开通静脉通道以便急救（B对）。发生血压明显下降时，先补液扩容，效果不明显者静注麻黄碱可起升压作用（麻黄碱为α及β受体激动剂，不仅促进血管收缩，亦可刺激心脏泵血，从而恢复血压）（C对）。丁卡因血浆蛋白结合率为76%，普鲁卡因血浆蛋白结合率仅5.8%，因而丁卡因麻醉时间比普鲁卡因长（A对）。腰麻后头痛为低颅压性头痛，是由于腰麻后脑脊液流失引起，站立时脑脊液流向脊椎内使静水压增高，脑脊液漏增加，颅内压更低，引起头痛加重，平卧后减轻或消失（D对）。","","N"],["1992-N157",18,"第二节 乳房检查","乳房触诊",1992,157,"X","","关于乳腺检查，下列哪些是错误的",[["A","触诊时应用手指掌面循序进行"],["B","不要用手指抓捏乳房组织"],["C","查腋窝淋巴结时，应让病人上肢上举"],["D","查肩胛组淋巴结时，应站在病人背后"]],"C","乳腺检查触诊时应用手指掌面循序进行（A对），因为手指掌面触觉灵敏，循序进行触诊就不会有遗漏。乳房由许多乳腺小叶组成，若用手指捏乳房组织，则会将捏到的腺体组织误认为肿块，所以不要用手指抓捏乳房组织（B对）。检查腋窝淋巴结时，让病人上肢外展，或用检查者的一侧手前臂托着病人的同侧前臂，让该侧手臂放松，这样可以使得腋窝完全松弛，检查者用另外一只手检查病人该侧腋窝；上举手臂会使得腋窝部紧张，不利于淋巴结的触摸，上举手臂用于观察乳房皮肤表面是否存在凹陷（C错，为本题正确答案）。老版教材称背阔肌前内侧淋巴结为肩胛下组淋巴结，扪摸背阔肌前内侧淋巴结，应站在病人背后（D对）。","","N"],["1992-N158",23,"第一节 腹外疝概述","嵌顿疝",1992,158,"X","","以下何种疝属于嵌顿性疝",[["A","Richter疝"],["B","Littre疝"],["C","滑疝"],["D","逆行性嵌顿疝"]],"ABD","几种特殊类型的嵌顿疝需要考生记忆，区别其不同主要看疝内容物的差别：①Richter疝（A对）：嵌顿的内容物仅为部分肠壁；②Littre疝（B对）：嵌顿的内容物为小肠憩室（通常是Meckel憩室）；③逆行性嵌顿疝（D对）：嵌顿的内容物包括几段肠袢，呈现W形。少数病程较长的疝，因疝的长期移动，导致疝囊颈周围结构松弛，以致盲肠、乙状结肠或膀胱随之下移而形成疝囊壁的一部分，这种疝称为滑疝（C错），属于难复性疝，疝内容物血运正常，也无严重的临床症状。","","N"],["1992-N159",34,"第一节 上消化道大出血的诊断和处理","上消化道大出血临床分析",1992,159,"X","","应激性溃疡最常见的原因为",[["A","大面积烧伤，脑外伤"],["B","严重休克"],["C","服用过量的水杨酸和肾上腺皮质激素"],["D","精神因素"]],"ABC","应激性溃疡泛指休克、创伤、手术后和严重全身性感染时发生的溃疡，这类溃疡位于胃的较多，位于十二指肠的较少，常导致大出血。常见的病因有：1.严重创伤：如严重外伤、大面积烧伤、颅内疾病、脑外伤（A对）、腹部手术等。2.长时间低血压：如休克（B对）、慢性肾衰竭、多器官衰竭等。3.药物使用：如抗癌药物和类固醇激素治疗后，阿司匹林（C对）、消炎痛等的长时间使用。注意：精神紧张、焦虑等虽属应激因素，可对黏膜屏障产生一定的影响，为急性胃炎的常见原因，但引起应激性溃疡少见，并不是应激性溃疡的常见原因（D错）。","","N"],["1992-N160",27,"第四节 肠梗阻","绞窄性肠梗阻",1992,160,"X","","下列那些疾患易发生绞窄性肠梗阻",[["A","肠扭转"],["B","蛔虫性肠梗阻"],["C","肠套叠"],["D","肠系膜血管阻塞"]],"ACD","蛔虫性肠梗阻（B错）多见于儿童，由于体内寄生大量蛔虫、相互缠绕形成蛔虫团阻塞肠腔引起的肠道堵阻，虽可出现明显的肠梗阻症状，但是由于血运尚未受到影响，故并非绞窄性肠梗阻，属于机械性肠梗阻范畴。不论发病的原因，而根据肠管血液循环有无障碍，可将肠梗阻分为两类：无血液循环障碍者为单纯性肠梗阻，有血液循环障碍者则为绞窄性肠梗阻。肠扭转（A对）是一段肠管甚至几乎全部小肠及其系膜沿系膜轴顺时针或逆时针扭转360°以上，因此有肠管的梗阻，更有肠系膜血管的扭折不通，血循环中断，属于闭袢性肠梗阻加绞窄性肠梗阻。肠套叠（C对）是肠的一段套入其相连的肠管腔内，由于套入部的肠系膜也随肠管进入，结果不仅发生肠腔梗阻，由于肠系膜血管受压，肠管也可发生绞窄。肠系膜血管阻塞（D对）可引起相应段肠管的血液循环障碍，因此为绞窄性肠梗阻。","","N"],["1993-N65",54,"第一节 化脓性骨髓炎","急性化脓性骨髓炎病理",1993,65,"A","","小儿急性血源性化脓性骨髓炎，脓液进入关节腔继发化脓性关节炎，能发生在",[["A","肩关节"],["B","肘关节"],["C","腕关节"],["D","髋关节"],["E","膝关节"]],"D","小儿骨骺对感染的抵抗力较强具有屏障作用，因此由于直接蔓延而发生化脓性关节炎的机会甚少，但是在髋关节处，股骨头骺板位于髋关节囊内，骨髓炎若穿破骨皮质可直接进入关节囊引起继发性化脓性关节炎（D对）。其他关节附近的骨骺板均位于关节囊以外。","","N"],["1993-N66",55,"第一节 骨与关节结核概论","骨与关节结核发病特点",1993,66,"A","","关于骨关节结核的叙述中下列哪项不对",[["A","骨关节结核中，脊柱结核最多见"],["B","脊柱结核中，腰椎发病占首位"],["C","脊椎结核好发于椎体"],["D","皮质骨结核常见于四肢短管状骨"],["E","滑膜结核最多见于腕关节"]],"E","骨关节结核中，脊柱结核最多见，约占50%（A对），绝大多数发生于椎体（C对）。骨关节结核大多在负重大、活动多、易遭受慢性劳损的部位。在脊柱，腰椎承受的压力最大，易受积劳性损伤，也是脊柱结核最易好发的部位（B对）。皮质骨结核常见于四肢短状骨（D对）。滑膜广泛分布于关节、腱鞘和滑囊等处的内衬，在膝、髋、肘和踝滑膜丰富，滑膜结核发生率也较高，滑膜结核最多见于膝、髋关节（E错，为本题正确答案）。","","N"],["1993-N67",53,"第二节 腰椎退行性疾病","腰椎侧凸",1993,67,"A","","一般说来，下列哪项体征不符合腰₅骶₁间盘突出（后外侧型）",[["A","腰5骶1棘间有压痛"],["B","脊柱侧凸"],["C","患侧外踝部和足外侧感觉异常"],["D","患侧拇趾背伸乏力或不能"],["E","患侧踝反射异常"]],"D","腰椎间盘突出症的体征包括：腰椎侧凸（B对）；腰部活动受限；病变间隙的棘突间有压痛（A对）及骶棘肌痉挛；直腿抬高试验及加强试验阳性；神经系统表现。腰₅骶₁间盘突出压迫骶₁，骶₁神经根受压时，外踝附近及足外侧痛、触觉减退（C对）；踝反射减弱或消失（E对）；足跖屈无力。腰₄～₅椎间盘突出压迫腰₅，腰₅神经根受压时，大腿后外侧、小腿前外侧及足内侧痛、触觉减退；拇趾背伸无力（D错，为本题正确答案）。腰₃～₄椎间盘突出压迫腰₄，腰₄神经根受压时，大腿前内侧及小腿前侧痛、触觉减退；膝反射减弱或消失；伸膝无力。","","N"],["1993-N68",5,"第一节 外科感染概述","外科感染分类",1993,68,"A","","关于外科感染分类的叙述，哪项是错误的",[["A","丹毒、急性阑尾炎、急性乳腺炎等均属特异性感染，非一般感染"],["B","急性感染指病程在三周以内"],["C","条件性感染指平常为非致病的病原菌乘机体抵抗力下降时乘机而入所引起的感染"],["D","院内感染的主要致病菌是条件致病菌"],["E","病程超过二个月者为慢性感染"]],"A","感染常分为特异性和非特异性感染：非特异性感染主要由一般的细菌化脓性感染，由金葡菌、大肠杆菌等常见菌引起；特异性感染如结核、破伤风、气性坏疽、念珠菌病等，因致病菌不同于一般感染，可引起较为独特的病变。丹毒、急性阑尾炎、急性乳腺炎的致病菌常为链球菌、大肠杆菌、金黄色葡萄球菌引起的非特异性感染，为一般感染（A错，为本题正确答案）。感染根据病程长短可分为急性、亚急性与慢性感染。急性感染指病程在三周以内（B对）、病程超过二个月者为慢性感染（E对）、介于二者之间的为亚急性感染。条件性感染指平常为非致病的病原菌在机体抵抗力下降时乘机而入所引起的感染（C对），又称机会性感染。院内感染是指住院病人在医院内获得的感染，包括在住院期间发生的感染和在医院内获得，出院后发生的感染，但不包括入院前已开始或者入院时已处于潜伏期的感染。由于药物的使用，正常致病菌被抑制，而原先不致病的菌群得以繁殖并引起疾病，或由于病人抗感染能力下降，无法耐受原先不致病的微生物而造成感染，这些病原体称为“条件性病原菌”，故院内感染的主要致病菌是条件致病菌（D对）。","","N"],["1993-N69",10,"第五节 椎管内麻醉","硬膜外间隙麻醉",1993,69,"A","","关于硬膜外麻醉，以下哪项叙述是错误的",[["A","老年人比青年人麻药用量少"],["B","在孕妇，麻药可能转移到胎儿"],["C","麻醉药也进入蛛网膜下腔"],["D","比腰麻引起的血压下降轻"],["E","硬脊膜囊终止于第五腰椎水平"]],"E","老年人由于各个系统机能均有所下降，且新陈代谢速度低，对麻药的耐受性减低，故对于老年人应该酌情减量（A对）；麻药具有脂溶性，硬膜外间隙有丰富的静脉丛，麻药在作用过程中会有部分透过静脉丛渗入血液，可透过胎盘屏障进入孕妇子宫内的胎儿体内（B对），故孕妇生产采用硬膜外麻醉镇痛时，需备新生儿呼吸机及抢救物品；硬膜外麻醉时局麻药注入硬膜外间隙，药物本身具有一定脂溶性，可扩散透过硬脊膜，且可通过神经根穿出硬脊膜部位进入蛛网膜下隙（C对）；硬膜外麻醉通过麻药浸入神经根后起到阻滞作用，而腰麻时麻药则直接浸润脊髓和神经根，作用效果较快，且硬膜外麻节段较腰麻局限，因此，硬膜外麻醉比腰麻引起的血压下降轻（D对）；脊髓随着年龄增长的速度慢于脊柱增长的速度，故硬脊膜囊的高度不断缩短，终止于S₂水平（P57）（E错，为本题正确答案）。","","N"],["1993-N70",27,"第四节 肠梗阻","肠梗阻非手术治疗",1993,70,"A","","在肠梗阻的非手术治疗中，下述观察项目哪项最主要",[["A","腹膜刺激征"],["B","脉搏增快"],["C","腹胀较前明显"],["D","肠鸣音较前减弱"],["E","腹痛加重"]],"A","选择合适的方法治疗肠梗阻病人十分重要，虽然大多数肠梗阻需要手术治疗方能解除梗阻、去除病因，但手术本身也是一种损伤，不可避免的造成腹腔内粘连发生，故非手术治疗对于一些轻症病人来说属于首选。观察指标的选择可用于判断是否采取手术治疗。腹膜刺激征（A对）可作为判断病情的重要依据：梗阻恶化时，肠管迅速膨胀，管壁变薄，肠管内压力不断升高，或绞窄引起肠管血运障碍，均可造成肠壁充血、水肿，体液外渗，当炎症波及腹膜时，即出现腹膜刺激征，是肠梗阻病情恶化的标志，需及时手术治疗。相比之下，脉搏增快（B错）属于应急症状，与肠梗阻的疾病情况无关；随着肠梗阻疾病的发展，进食或者吞咽空气均积聚于肠腔，可出现腹胀较前明显（C错），仅说明病症仍在，无法证明是否恶化，只有突然明显的腹胀方采取手术治疗；肠鸣音减弱（D错）不能说明病情恶化需要手术治疗，麻痹性肠梗阻早期即可出现肠鸣音减弱甚至消失；随着疾病的发展，肠内容物的堆积，可出现腹痛加重（E错），但只有严重剧烈的腹痛才作为判断疾病恶化的标志。","","N"],["1993-N71",32,"第二节 胆道疾病影像学检查","经皮肝穿刺胆管造影",1993,71,"A","","梗阻性黄疸病人下列哪项检查对诊断价值不大",[["A","经皮经肝穿刺胆道造影"],["B","B型超声"],["C","静脉法胆道造影"],["D","经内窥镜逆行胰胆管造影"],["E","低张十二指肠钡餐检查"]],"C","静脉法胆道造影（C错，为本题正确答案）：缓慢静脉注射造影剂后，造影剂经肝分泌进入胆道系统，以观察胆管有无狭窄、扩张、充盈缺损等病理改变。本法显影常不清晰，且受多种因素影响，现已为核素胆道造影、直接胆管造影、磁共振胆胰管造影所取代。经皮经肝穿刺胆道造影（A对）是用细针在X线或超声介导下，穿刺肝内扩张胆管并注入造影剂，可显示梗阻近端胆道，以便判断梗阻的部位和原因，适用于高位胆道梗阻。B型超声（B对）是极有用的诊断方法，对于胆囊结石、胆囊息肉样病变、急性胆囊炎、慢性胆囊炎及胆囊癌、胆管结石等病变，诊断准确率可达95%～98%。B超可探查肝内胆管（＞4mm）、肝外胆管（＞10mm）有无扩张，可判定胆道梗阻部位及原因。经内窥镜逆行胰胆管造影（D对）（ERCP）更加适用于低位胆管梗阻的诊断，借助侧视内窥镜可观察十二指肠有无病变，并可活检；插管后注入造影剂使胆管和胰管显影，显示梗阻的部位和病因。低张十二指肠钡餐检查（E对）可显示十二指肠的形态，对观察十二指肠的器质性病变，尤其对梗阻性黄疸及壶腹部周围病变的诊断有价值。","","N"],["1993-N72",30,"第二节 肝脓肿","细菌性肝脓肿鉴别诊断",1993,72,"A","","下列哪项不是阿米巴肝脓肿的征象",[["A","多有阿米巴痢疾的历史"],["B","起病缓、病程长、症状轻"],["C","肝穿刺脓液常为棕褐色"],["D","结肠镜检可见结肠粘膜有慢性溃疡"],["E","脓肿常多发"]],"E","阿米巴肝脓肿是肠道阿米巴感染的并发症，病人常有阿米巴痢疾的病史（A对）。阿米巴痢疾起病缓，病程长，症状轻（B对）。肝穿刺抽液呈巧克力色/棕褐色（C对），无臭味，镜下可找到阿米巴滋养体。结肠镜检查，常可见原发病阿米巴痢疾在结肠壁形成的慢性溃疡（D对）。阿米巴脓肿绝大多数为单发（E错，为本题正确答案）右叶大脓肿，细菌性肝脓肿常为多发性。","","N"],["1993-N73",31,"门静脉高压","食管胃底曲张静脉破裂出血手术治疗",1993,73,"A","","关于门脉高压症，哪项叙述是错误的",[["A","脾大，脾功能亢进，消化道出血和腹水是主要临床表现"],["B","脾功能亢进时都有血细胞减少，以白细胞和血小板改变明显"],["C","外科治疗的主要目的是制止食管胃底静脉曲张破裂所致的大出血"],["D","分流手术主要是阻断门奇静脉间的反常血流"],["E","腹腔—静脉转流术可治疗肝硬变引起的顽固性腹水"]],"D","外科手术治疗门脉高压症、食管静脉曲张的术式主要包括两类：门体分流术和断流手术。门体分流术包括非选择性门体分流术和选择性门体分流术，其机制是将入肝的门静脉血全部（非选择性）或部分（选择性）转流入体循环，分担了门静脉血流量，缓解了门脉高压。奇静脉为接受食管-胃底静脉的回流血并汇入上腔静脉的血管，断流手术是将脾切除，同时离断门奇静脉间的反常血流（D错，为本题正确答案），即离断了食管-胃底静脉的来路血管和去路血管。脾切除的作用是减少门静脉血流、降低门脉高压，同时离断了食管胃底静脉的血供，预防和治疗其破裂出血的并发症。门静脉高压症的主要临床表现为脾大、脾功能亢进、消化道出血及腹水（A对）。脾功能亢进时，其吞噬作用增强，可导致血细胞减少，尤以白细胞和血小板改变明显（B对）。外科治疗门静脉高压症主要是预防和控制食管胃底曲张静脉破裂出血（C对）。肝移植、TIPS及腹腔-腔静脉转流术可治疗肝硬变引起的顽固性腹水（E对）。","","N"],["1993-N74",13,"第一节 术前准备","肺功能障碍",1993,74,"A","","大手术前，病人呼吸系统的准备方面，下列哪项不正确",[["A","停止吸烟"],["B","有阻塞性肺功能不全者，可给麻黄碱、氨茶碱扩张支气管"],["C","有哮喘者，可给口服地塞米松减轻粘膜水肿"],["D","鼓励病人练习深呼吸及咳嗽，增加肺通气量和引流"],["E","慢性支气管炎病人可给吗啡止咳"]],"E","香烟烟雾中含有的焦油、尼古丁和镉等有害物质能损伤呼吸道黏膜，降低局部抵抗力，烟雾还会刺激小气道产生痉挛，从而增加气道阻力，术前停止吸烟（A对），有利于呼吸道功能的恢复。麻黄碱、氨茶碱均为支气管扩张剂，能够扩张支气管，降低通气阻力，适用于术前有阻塞性肺功能不全者（B对）。地塞米松具有强大的抗炎作用，能够缓解呼吸道黏膜水肿及痉挛，有效预防哮喘的发作（C对）。鼓励病人练习深呼吸及咳嗽，深呼吸可以增加肺通气量，咳嗽有助于排出呼吸道分泌物，具有引流功能（D对）。吗啡为镇痛药，具有强力镇痛作用，但是因其具有抑制呼吸中枢的作用，不适于慢性支气管炎病人（E错，为本题正确答案）。","","N"],["1993-N75",18,"第四节 乳腺癌","临床表现",1993,75,"A","","乳癌局部皮肤呈“橘皮样”改变的原因是",[["A","肿物压迫引起"],["B","癌肿位置深，侵及Cooper韧带所致"],["C","癌细胞侵及或堵塞乳房表浅淋巴管导致淋巴水肿所致"],["D","肿物与乳房皮肤粘连所致"],["E","肿瘤周围的炎性改变引起"]],"C","乳腺癌细胞侵及或堵塞乳房表浅淋巴管导致淋巴水肿会导致乳癌局部皮肤呈“橘皮样”改变（C对）。肿物压迫（A错）视压迫部位不同，可引起不同症状。若乳腺癌肿位置深，侵及Cooper韧带会使其缩短而致肿瘤表面皮肤凹陷，即所谓“酒窝征”（B错）。乳腺肿物与乳房皮肤粘连（D错）可致肿物不易推动。肿瘤周围的炎性改变（E错）可见于炎性乳腺癌，此癌并不多见，特点是发展迅速、预后差。","","N"],["1993-N76",26,"第三节 胃十二指肠溃疡的外科治疗","胃十二指肠溃疡穿孔诊断",1993,76,"A","","男性30岁，晚餐进食较多，餐后突然上腹刀割样疼痛速波及全腹，不敢直腰行走，2小时后急诊求治。急性痛苦面容，腹式呼吸消失，腹肌强直，有腹膜刺激征，肝浊音界消失，肠鸣音消失，最可能的诊断是",[["A","阑尾炎穿孔"],["B","溃疡病穿孔"],["C","胆囊穿孔"],["D","绞窄性肠梗阻"],["E","急性胰腺炎"]],"B","年轻男性患者，餐后突发上腹部刀割样痛，并迅速波及全腹。查体可见腹式呼吸消失及腹膜刺激征，肠鸣音及肝浊音界消失，诊断考虑溃疡病穿孔（B对）。病人晚餐进食较多，为溃疡穿孔的诱发因素；突发刀割痛迅速波及全腹，为穿孔后胃内容物流入腹腔引起强烈的腹膜炎表现；广泛的腹膜炎使得整个腹肌高度紧张强直，腹式呼吸被迫停止，腹部板状强直，并因气体进入腹膜腔，导致无法叩清肝浊音界位置，弥漫性腹膜炎可引起麻痹性肠梗阻，肠鸣音消失。阑尾炎穿孔（A错）典型表现为转移性右下腹痛，且由于大网膜的包裹，腹膜炎难以波及全腹，部分病人可有恶心呕吐等轻度的胃肠道症状及程度不等的中毒症状。胆囊穿孔（C错）多继发于急性胆囊炎，典型表现为右上腹压痛，Murphy征阳性，穿孔后炎症可波及全腹，出现腹膜刺激征。绞窄性肠梗阻（D错）典型表现为持续性剧烈腹痛，停止排气排便，腹胀不对称，局部有隆起或可触及的孤立的肿块，未发生穿孔时不会出现肝浊音界消失。急性胰腺炎（E错）的典型表现为为饮酒或饱食，出现左上腹痛且向左肩及左腰背部放射，病变范围较广、程度较重时可导致明显的腹膜炎体征，少数病人可出现皮下青紫色瘀斑，一般无肝浊音界消失。","","N"],["1993-N77",25,"第一节 急性弥漫性腹膜炎","急性弥漫性腹膜炎腹部体征",1993,77,"A","","下列关于急性化脓性腹膜炎的体征中，哪项是错误的",[["A","腹式呼吸减弱"],["B","有腹肌紧张"],["C","腹壁肿胀及静脉曲张"],["D","全腹压痛及反跳痛"],["E","肠鸣音减弱或消失"]],"C","急性化脓性腹膜炎最经典最标志性的体征即为腹膜刺激征，即腹部压痛、腹肌紧张和反跳痛（BD对）。腹式呼吸减弱或消失的原因主要是腹腔内刺激性分泌物或漏出物对腹壁的刺激引起机体防御性腹肌紧张，无法做出规律的呼吸运动（A对）。急性腹膜炎时肠鸣音减弱或消失的原因有两点，一是腹肌紧张以及腹水的形成使得肠鸣音传导变差，二是炎性或细菌毒素因素使得肠道本身的蠕动变差（E对）。腹壁肿胀及静脉曲张是肝硬化门脉高压的临床表现，而非急性化脓性腹膜炎（C错，为本题正确答案）。","","N"],["1993-N78",32,"第四节 胆石症","腹痛",1993,78,"A","","下列有关腹痛性质与疾病的关系中，哪项是错误的",[["A","间歇性刺痛—胆总管结石"],["B","阵发性绞痛—输尿管结石"],["C","阵发性钻顶痛—胆道蛔虫症"],["D","剧烈刀割样痛—十二指肠溃疡穿孔"],["E","持续性胀痛—实质性脏器发炎"]],"A","胆总管结石腹痛常发生在剑突下或右上腹，多为绞痛，呈阵发性发作，或为持续性疼痛阵发性加重，可向右肩或背部放射，常伴恶心、呕吐（A错，为本题正确答案）。阵发性绞痛除了见于输尿管结石外，还可见于机械性肠梗阻（B对）。剑突下阵发性钻顶痛，突发突止，严重的症状和轻微的体征不相符为胆道蛔虫症（C对）。上腹剧烈刀割样痛，伴有腹膜刺激征，X线片可见膈下新月形游离气体，多为消化性溃疡穿孔（D对）。持续性胀痛常见于实质性脏器发炎（E对）如肝脓肿。","","N"],["1993-N79",25,"第一节 急性弥漫性腹膜炎","急性弥漫性腹膜炎诊断",1993,79,"A","","诊断出急性化脓性腹膜炎后，进一步要明确的中心环节是",[["A","病人有无脱水"],["B","是否合并酸碱平衡紊乱"],["C","引起腹膜炎的原因"],["D","感染的主要细菌"],["E","有无贫血"]],"C","对于急性弥漫性腹膜炎，在对症治疗的同时，一定要明确造成腹膜炎的病因，对于及时终止疾病的恶化、制定合理的治疗方案均有重要意义，为进一步要明确的中心环节（C对）。急性弥漫性腹膜炎如果治疗不当，很快会引起低血容量性休克、全身中毒症状、SIRS甚至是病人的死亡，故诊断后的紧急救治很重要。虽然查看病人脱水情况（A错）和电解质平衡情况（B错）很重要，以及明确感染致病菌的数量和种类（D错）有利于合理使用抗生素，但这些都是针对症状或并发症所做的对症治疗。急性化脓性腹膜炎属于急性发作的疾病，与贫血的发生无明显关系（E错）。","","N"],["1993-N80",30,"第一节 肝解剖生理概要","肝的概述",1993,80,"A","","肝十二指肠韧带中不包括下列哪项内容",[["A","门静脉"],["B","肝动脉"],["C","肝静脉"],["D","胆总管"],["E","淋巴管、淋巴结和神经"]],"C","肝十二指肠韧带，通常称之为肝蒂，其中包含的主要结构为门静脉（A对）、肝动脉（B对）、胆总管（D对）、淋巴管、淋巴结和神经（E对）。肝静脉（C错，为本题正确答案）主要参与构成第二及第三肝门。肝脏的三个肝门需考生记忆：第一肝门为肝动脉、门静脉和肝总管进入肝脏的部位；第二肝门为肝三支主静脉（肝右静脉、肝中静脉和肝左静脉）在肝后上缘汇入下腔静脉处；第三肝门为数支肝短静脉在肝后方汇入下腔静脉处。这三个肝门，在肝外科手术中具有十分重要的地位。","","N"],["1993-N95",26,"第三节 胃十二指肠溃疡的外科治疗","胃十二指肠溃疡穿孔临床表现",1993,95,"B","","胃溃疡穿孔",[["A","右上腹绞痛，伴压痛、黄疸、Murphy氏征阳性"],["B","脐周围阵痛，伴有压痛，肠鸣亢进，有肠型"],["C","上腹压痛，板样强直，肝浊音界消失"],["D","上腹部胀痛伴有胃型及拍水声"],["E","胸骨下持续性钝痛，腹部体征正常"]],"C","胃溃疡穿孔后，具有强刺激性的胃内容物进入腹腔，引起急性腹痛及腹膜刺激征，腹壁肌肉强直，因气体进入腹膜腔，导致无法叩清肝浊音界位置。综上胃溃疡穿孔的典型表现为上腹压痛，板样强直，肝浊音界消失（C对）。右上腹绞痛，伴压痛、黄疸、Murphy氏征阳性（A错）是急性胆囊炎伴胆总管结石的典型表现，胆汁下行受阻导致肝管痉挛性收缩以及胆汁淤积引起黄疸，急性胆囊炎可引起胆囊压痛及Murphy氏征阳性。脐周围阵痛，伴有压痛，肠鸣亢进，有肠型（B错）为急性肠梗阻的典型表现，由于肠道内容物下行受阻，肠管痉挛，肠鸣音亢进，使得腹部出现疼痛（内脏痛为钝痛，多体现在脐周），在腹部视诊可见肠型。上腹部胀痛伴有胃型及拍水声（D错），是幽门梗阻的典型表现，因食物及饮水无法通过幽门而停留在胃内，胃内充盈胀满，上腹胀痛并有振水音。胸骨下持续性钝痛，腹部体征正常（E错），多为胸部疾病的表现，常见如心绞痛。","","N"],["1993-N96",27,"第四节 肠梗阻","肠梗阻临床表现",1993,96,"B","","急性肠梗阻",[["A","右上腹绞痛，伴压痛、黄疸、Murphy氏征阳性"],["B","脐周围阵痛，伴有压痛，肠鸣亢进，有肠型"],["C","上腹压痛，板样强直，肝浊音界消失"],["D","上腹部胀痛伴有胃型及拍水声"],["E","胸骨下持续性钝痛，腹部体征正常"]],"B","急性肠梗阻病人，由于肠道内容物下行受阻，肠管痉挛，肠鸣音亢进，使得腹部出现疼痛（内脏痛为钝痛，多体现在脐周），在腹部视诊可见肠型，触诊时因肠管膨胀，可有压痛。综上所述，急性肠梗阻表现为脐周围阵痛，伴有压痛，肠鸣亢进，有肠型（B对）。右上腹绞痛，伴压痛、黄疸、Murphy氏征阳性（A错）是急性胆囊炎伴胆总管结石的典型表现，胆汁下行受阻导致肝管痉挛性收缩以及胆汁淤积引起黄疸，急性胆囊炎可引起胆囊压痛及Murphy氏征阳性。上腹压痛，板样强直，肝浊音界消失（C错）为胃溃疡穿孔的典型表现，穿孔后，具有强刺激性的胃内容物进入腹腔，引起急性腹痛及腹膜刺激征，腹壁肌肉强直，因气体进入腹膜腔，导致无法叩清肝浊音界位置。上腹部胀痛伴有胃型及拍水声（D错），是幽门梗阻的典型表现，因食物及饮水无法通过幽门而停留在胃内，胃内充盈胀满，上腹胀痛并有振水音。胸骨下持续性钝痛，腹部体征正常（E错），多为胸部疾病的表现，如心绞痛。","","N"],["1993-N99",17,"第一节 甲状腺疾病","单纯性甲状腺肿临床表现",1993,99,"B","","向胸骨后生长延伸的常是",[["A","突眼性甲状腺肿"],["B","桥本氏甲状腺肿"],["C","结节性甲状腺肿"],["D","甲状腺高功能腺瘤"]],"C","原发性甲亢最常见，腺体肿大为弥漫性，两侧突出，常伴有眼球突出，故又称“突眼性甲状腺肿”（A错）。桥本氏甲状腺肿（B错），是一种自身免疫性疾病，也是甲状腺功能减退最常见的原因，病变甲状腺组织被大量淋巴细胞、浆细胞和纤维化所代替。甲状腺高功能腺瘤（D错），内有单发的自主性高功能结节，结节周围的甲状腺组织呈萎缩改变。上述种类甲状腺肿通常不会有向胸骨后延伸的表现。病程较长、体积较大的甲状腺肿，发展为结节性甲状腺肿（C对），产生组织增生，并因为重力作用发生下垂，除可下垂于颈下胸骨前方外，还可向胸骨后方延伸生长形成胸骨后甲状腺肿，既压迫食管和气管，还可能压迫颈深部大静脉，引起头颈部回流障碍，出现面部青紫、肿胀和颈胸部表浅静脉扩张。","","N"],["1993-N100",17,"第一节 甲状腺疾病","慢性淋巴细胞性甲状腺炎诊断",1993,100,"B","","摄取¹³¹I减少，基础代谢率降低的是",[["A","突眼性甲状腺肿"],["B","桥本氏甲状腺肿"],["C","结节性甲状腺肿"],["D","甲状腺高功能腺瘤"]],"B","桥本氏甲状腺肿（B对），又称慢性淋巴细胞性甲状腺炎，是一种自身免疫性疾病，也是甲状腺功能减退最常见的原因，病变甲状腺组织被大量淋巴细胞、浆细胞和纤维化所代替，由于大量有功能甲状腺滤泡细胞的破坏，使得甲状腺素合成减少，摄碘率下降，并且基础代谢率降低。原发性甲亢最常见，腺体肿大为弥漫性，两侧突出，常伴有眼球突出，故又称“突眼性甲状腺肿”（A错），基础代谢率增高、甲状腺摄取¹³¹I增高。单纯性甲状腺肿随着缺碘时间的延长，病变继续发展，扩张的滤泡便聚集成多个大小不等的结节，形成结节性甲状腺肿（C错），摄碘率不低，基础代谢率也不低。甲状腺高功能腺瘤（D错），内有单发的自主性高功能结节，结节周围的甲状腺组织呈萎缩改变，摄碘率不低，基础代谢率也不降低，约20%甲状腺高功能腺瘤可引起甲亢。","","N"],["1993-N101",8,"第一节 肿瘤概述","适合放射治疗的肿瘤",1993,101,"B","","对放射线高度敏感的肿瘤是",[["A","肝癌"],["B","绒毛膜上皮癌"],["C","胃癌"],["D","直肠癌"],["E","淋巴肉瘤"]],"E","放射治疗是利用一种或多种电离辐射对恶性肿瘤及一些良性病进行的治疗，放射治疗的手段是电离辐射。对放射线高度敏感的肿瘤：淋巴造血系统肿瘤（E对）、性腺肿瘤、多发性骨髓瘤、肾母细胞瘤等低分化肿瘤。这些肿瘤均为恶性肿瘤，且分化程度低，对放射线的抗性差，故可采用放射线治疗。","","N"],["1993-N102",8,"第一节 肿瘤概述","化学治疗",1993,102,"B","","对化疗较为敏感的肿瘤是",[["A","肝癌"],["B","绒毛膜上皮癌"],["C","胃癌"],["D","直肠癌"],["E","淋巴肉瘤"]],"B","化疗是化学药物治疗的简称，通过使用化学治疗药物杀灭癌细胞达到治疗目的。化疗和手术、放疗一起并称癌症的三大治疗手段。绒毛膜上皮癌是一种高度恶性的滋养细胞肿瘤，简称绒癌。绒癌的治疗以往以手术为主，患者多在1年内死亡，自应用化疗后，大多数患者可治愈，即便已发生转移的病例治愈率可达70%，甚至治愈后可正常妊娠（十版病理学P276）（B对）。肝癌（A）、胃癌（C）、直肠癌（D）多以手术切除为主，但也可辅助以化疗。淋巴肉瘤（E对）为旧分类法中的一类，相当于非霍奇金淋巴瘤分类中的淋巴细胞分化良好性和淋巴细胞分化不良性非霍奇金淋巴瘤，治疗策略为以化疗为主的化、放疗结合的综合治疗（十版内科学P597）。此题题干改为“首选化疗治疗的肿瘤”更为精确，且本题答案应为BE，但参考答案为B。首选化疗的恶性肿瘤可记忆为“大伯培养小林到高中”—“大：大细胞淋巴瘤，伯：Burkitt淋巴瘤，培：胚胎性横纹肌肉瘤，养：恶性滋养细胞瘤（B对），小：小细胞肺癌，林：急性淋巴细胞白血病，高：睾丸精原细胞瘤，中：中枢神经系统淋巴瘤”。","","N"],["1993-N103",57,"第四节 原发性恶性骨肿瘤","骨肉瘤诊断",1993,103,"B","","骨肉瘤可以有",[["A","血钙升高"],["B","血磷升高"],["C","血碱性磷酸酶升高"],["D","血酸性磷酸酶升高"],["E","血总蛋白浓度升高"]],"C","骨肉瘤是最常见的原发性恶性骨肿瘤，可有成骨性、溶骨性或混合性骨质破坏，具有较为明显的生化表现，即血碱性磷酸酶升高（C对）和乳酸脱氢酶的中度至大幅升高。肿瘤切除后ALP可降至正常，肿瘤复发ALP再度升高。若患者骨肉瘤以溶骨性破坏为主，则可出现血钙升高。本题A选项亦正确，但当年给出的答案为C。","","N"],["1993-N104",57,"第一节 骨肿瘤概论","骨肿瘤生化测定",1993,104,"B","","广泛溶骨性转移性骨肿瘤可以有",[["A","血钙升高"],["B","血磷升高"],["C","血碱性磷酸酶升高"],["D","血酸性磷酸酶升高"],["E","血总蛋白浓度升高"]],"A","广泛溶骨性转移骨肿瘤广泛侵蚀骨组织，导致溶骨性破坏。骨的广泛溶解，大量骨钙释放入血，导致血钙明显升高（A对）。此题不严谨，因为对于任何一种骨肿瘤，不会仅发生选项中某一种改变，应将题干改为“最突出的表现是”。","","N"],["1993-N125",23,"第二节 腹股沟疝","腹股沟疝临床表现",1993,125,"C","","站立位阴囊出现包块，平卧位消失者，是",[["A","腹股沟斜疝"],["B","交通性鞘膜积液"],["C","两者均是"],["D","两者均不是"]],"C","腹股沟斜疝的基本临床表现是腹股沟区出现一突出肿块，若疾病时间较短、病情较轻、病人平卧休息或用手将肿块向腹腔推送，肿块可向腹腔回纳而消失（A对）。阴囊鞘膜腔内液体增多形成的囊肿称为鞘膜积液，交通性鞘膜积液属于其中的一种，为先天性疾病，发病原因是鞘状突未闭合，鞘膜腔与腹腔相通，鞘膜腔内积液为腹腔内液体，积液量随体位改变而变化，站立位，积液因重力作用进入阴囊，阴囊出现包块，平卧位积液因重力作用返回腹腔，因此平卧位肿块缩小甚至消失（B对）。本题AB均对，正确答案为C。","","N"],["1993-N126",23,"第二节 腹股沟疝","腹股沟疝临床表现",1993,126,"C","","阴囊包块还纳时可闻及咕咕响声者，是",[["A","腹股沟斜疝"],["B","交通性鞘膜积液"],["C","两者均是"],["D","两者均不是"]],"A","腹股沟斜疝的基本临床表现是腹股沟区出现一突出肿块，在发病早期病情轻者可平卧休息而消失。因肠腔内有由气体和液体，回纳后肠道内容物下行恢复正常，常常发出咕咕声（A对）。阴囊鞘膜腔内液体增多形成的囊肿称为鞘膜积液，交通性鞘膜积液（B错）属于其中的一种，为先天性疾病，发病原因为鞘状突未闭合，鞘膜腔与腹腔相通，鞘膜腔内积液为腹腔内液体，积液量随体位改变而变化，站立位阴囊出现包块，平卧位消失。但是由于鞘膜积液可以在通道内自由流动，且无气体存在，不会发出咕咕声。","","N"],["1993-N127",44,"第七节 骨折的治疗原则","复位标准",1993,127,"C","","儿童股骨骨干骨折复位后",[["A","允许短缩1.8cm"],["B","允许向内侧成角9°"],["C","两者都允许"],["D","两者都不允许"]],"A","儿童处在生长发育阶段时，成骨活动和破骨活动旺盛，最终使得骨生长和良好的塑形，故对于儿童骨折，在某些情况下达到功能复位的要求略松于成人。功能复位标准概括如下：旋转、分离移位必须完全矫正；成人下肢骨折缩短移位不超过1cm、儿童不超过2cm（A对）；与关节活动方向一致的成角移位不超过10°、侧方成角必须完全纠正（B错）；长骨干横行骨折骨折端对位应超过1/3、干骺端对位应超过3/4。","","N"],["1993-N128",44,"第七节 骨折的治疗原则","复位标准",1993,128,"C","","成人股骨骨干骨折复位后",[["A","允许短缩1.8cm"],["B","允许向内侧成角9°"],["C","两者都允许"],["D","两者都不允许"]],"D","儿童处在生长发育阶段时，成骨活动和破骨活动旺盛，最终使得骨生长和良好的塑形，故对于儿童骨折，在某些情况下达到功能复位的要求略松于成人。功能复位标准概括如下：旋转、分离移位必须完全矫正；成人下肢骨折缩短移位不超过1cm（A错）、儿童不超过2cm；与关节活动方向一致的成角移位不超过10°、侧方成角必须完全纠正（B错）；长骨干横行骨折骨折端对位应超过1/3、干骺端对位应超过3/4。股骨干向内侧成角属于侧方成角，无论是儿童还是成人均必须完全纠正。本题AB均错，正确答案为D。","","N"],["1993-N155",44,"第一节 骨折的定义、成因、分类及移位","嵌插骨折",1993,155,"X","","嵌插骨折的主要诊断根据是",[["A","骨折部的压痛和轴向叩击痛"],["B","骨折部的反常活动和骨擦音"],["C","骨折部软组织肿胀和淤斑"],["D","骨折部畸形"]],"A","嵌插骨折多见于干骺端骨折，骨干的密质骨嵌插入骺端的松质骨，骨折两断端不易发生相对移位，不会出现反常活动和骨擦音或骨擦感（B错）；由于基本形态尚存在，常无骨折部畸形（D错）。软组织肿胀和瘀斑（C错）仅能证明出现了软组织的损伤及皮下的出血，无法判断是否发生骨折。而骨折部的压痛和轴向叩痛（A对）在所有骨折病人均会出现，可用于辅助诊断嵌插骨折。","","N"],["1993-N156",7,"第一节 热力烧伤","烧伤创面深度",1993,156,"X","","判断烧伤深度时，临床上主要根据是",[["A","烧伤皮肤的感觉"],["B","烧伤皮肤有无水泡"],["C","烧伤创面色泽"],["D","病人有无休克"]],"ABC","Ⅰ°烧伤：干燥，烧灼感；浅Ⅱ°烧伤：疼痛明显；深Ⅱ°烧伤：痛觉较迟钝；Ⅲ°烧伤：硬如皮革，干燥，无渗液，发凉，针刺和拔毛无痛觉。各型烧伤皮肤的感觉（A对）各不相同，因此可以用于判断烧伤深度。Ⅰ°烧伤：无水泡；浅Ⅱ°烧伤：有大小不一的水泡形成；深Ⅱ°烧伤：有小水泡；Ⅲ°烧伤：无水泡。因此有无水泡（B对）可用于判断烧伤深度。Ⅰ°烧伤：表面红斑状；浅Ⅱ°烧伤：创面红润、潮湿；深Ⅱ°烧伤：创面微湿，红白相间；Ⅲ°烧伤：创面蜡黄或焦黄，甚至炭化。各型烧伤创面色泽（C对）各不相同，因此可以用于判断烧伤深度。休克是一种全身性疾病，与烧伤深度不存在平行关系，仅仅是很小面积的皮肤深度烧伤不会导致休克，而全身大面积烧伤，即使烧伤深度较浅，也会因大量渗液、合并感染等引起休克（D错）。","","N"],["1993-N157",33,"第二节 胰腺炎","胰酶测定",1993,157,"X","","关于急性胰腺炎，哪些是错误的",[["A","常继发于胆道疾患"],["B","腹痛一般呈持续性且剧烈"],["C","重型胰腺炎血糖下降、血钙增高"],["D","胰腺出血坏死越广泛，血和尿中淀粉酶越高"]],"CD","国内急性胰腺炎发病多以胆道疾病为主，约85%的人胰管与胆总管汇合形成“共同通道”，当胆结石、胆道水肿等胆道疾患存在致胆汁引流不畅时，胆汁可经“共同通道”返流入胰管，致急性胰腺炎（A对）。急性胰腺炎腹痛一般呈持续性且剧烈（B对）。重型胰腺炎时，胰腺实质坏死严重，胰岛功能严重受损，导致胰岛素分泌骤降，血糖升高（＞11.1mmol/L）；重型胰腺炎可导致腹腔内脂肪组织大量坏死，释放出的脂肪酸与钙离子结合，生成不溶性脂肪酸钙（钙皂），导致血钙降低（＜1.87mmol/L）（C错，为本题正确答案）。胰腺出血坏死广泛时，由于胰腺细胞大量坏死，不再产生和释放淀粉酶，血尿淀粉酶可不升高甚至出现降低（D错，为本题正确答案）。","","N"],["1993-N158",12,"","",1993,158,"X","","临床上多器官衰竭出现的顺序可能有先有后，下列有描述中你认为哪些是正确的",[["A","血容量降低时，肾功能降低先出现"],["B","感染造成毒血症时，心、肺、脑的功能损害先出现"],["C","某个器官功能降低时，如未能及时发现，可使病情迅速进展成多器官衰竭"],["D","当病人全身性损害极为严重时，一部分病人可同时出现多器官衰竭"]],"ABCD","血容量降低时，敏感的肾素-血管紧张素系统激活，肾血管收缩、血流量减少，故肾功能降低先出现（A对）；由于心、肺、脑是全身血供最为充足的部位（心是全身血流的动力中心，肺血管床容纳约全身总血容量9～12%的血量，脑血流量相当于心输出量的15%），故感染造成毒血症时，心、肺、脑的功能损害先出现（B对）；多器官衰竭综合征是指在严重创伤、感染和休克时，原无器官功能障碍的患者同时或者在短时间内相继出现两个以上器官系统的功能障碍以致机体内环境的稳定必须靠临床干预才能维持的综合征。机体各器官是相互联系、共同保证生命活动的进行，某个器官功能降低时，如未能及时发现，可使病情迅速进展成多器官衰竭，这是MODS发生的原因之一（C对）；当病人全身性损害极为严重时，一部分病人可同时出现多器官衰竭（D对），这是MODS中较严重的一种。","","N"],["1993-N159",24,"第一节 腹部损伤概述","有无内脏损伤",1993,159,"X","","下列关于腹内脏器损伤的叙述中，你认为哪项正确",[["A","有恶心、呕吐、便血、气腹者，多为胃肠道损伤"],["B","有排尿困难、血尿、外阴或会阴部牵涉痛者，提示有泌尿系脏器损伤"],["C","有内出血及同侧肩部牵涉痛者，较多见于肝脾破裂"],["D","有休克者，多为实质性器官损伤"]],"ABC","恶性呕吐为最常见的消化道症状，便血表明存在消化道出血，气腹征提示胃肠道存在破口，腹腔完整性受损，因而有恶心、呕吐、便血、气腹者，多为胃肠道损伤（A对）。排尿困难提示泌尿系梗阻或支配泌尿系的神经或平滑肌受损，血尿提示泌尿道损伤，会阴部及外阴牵涉痛亦常见于泌尿系损伤，因此有排尿困难、血尿、外阴或会阴部牵涉痛者，提示有泌尿系脏器损伤（B对）。肝脾破裂可导致大出血，且支配肩部神经和支配肝脾的神经存在部分重叠，因而有内出血及同侧肩部牵涉痛者，较多见于肝脾破裂（C对）。肝、脾、胰、肾等实质器官损伤主要表现为腹腔内（或腹膜后）出血，病人面色苍白，脉搏增快、细弱，脉压变小，收缩压可下降，出现典型的失血性休克表现。但对于胃肠道、胆囊等空腔脏器破裂，主要表现为弥漫性腹膜炎；若空腔脏器内容物过多、刺激过强，引起严重的炎症反应，释放的炎症介质过多可引起休克；或空腔脏器穿破后内容物含大量细菌（如结肠），造成全腹部的感染引起感染性休克；或腹内大血管的损伤，虽然为空腔脏器，却也能够引起严重的失血性休克。对于腹内脏器损伤，有休克者，多为实质性器官损伤（D对），该题正确答案应为ABCD，但当年的参考答案为ABC。","","N"],["1993-N160",10,"第三节 全身麻醉","哌替啶",1993,160,"X","","下列药物作为手术前用药哪个是正确的",[["A","巴比妥类主要用来催眠镇静"],["B","杜冷丁主要用来催眠镇静及提高痛阈"],["C","纳洛酮（Naloxon）主要用来对抗麻醉药的呼吸抑制"],["D","东莨菪碱的目的之一是镇静作用"]],"ABD","巴比妥类主要作用为镇静、催眠（A对），此外还有抗惊厥的作用。杜冷丁（即哌替啶）镇静、麻醉作用较小，是强效的镇痛药物，能够提高痛阈，用于各种剧痛的治疗、麻醉前用药以及心源性哮喘的治疗，此外还与氯丙嗪、异丙嗪合用作为“冬眠合剂”（B对）。东莨菪碱除了抑制腺体分泌、解除平滑肌痉挛和迷走神经兴奋外，它对中枢的作用与阿托品不同，能抑制大脑皮质，产生嗜睡和健忘，表现为显著的镇静作用（D对）。纳洛酮能竞争性拮抗各类阿片受体，逆转阿片激动剂的所有作用，包括镇痛和呼吸抑制作用，可迅速逆转阿片镇痛药引起的呼吸抑制，仅在解毒时使用（C错），并不具有对抗麻醉药的呼吸抑制作用。","","N"],["1994-N66",20,"第三节 肺肿瘤","肺癌放射治疗",1994,66,"A","","男性，54岁，患右侧肺癌，支气管镜病理检查为鳞癌，TNM分期为T₂N₁M₁，治疗原则为",[["A","手术切除"],["B","手术切除，配合放疗"],["C","手术切除，配合化疗"],["D","放疗和化疗"],["E","手术切除，配合放疗和化疗"]],"D","肺癌的主要治疗方法主要有外科手术治疗、放射治疗、化学药物治疗、靶向治疗等。小细胞肺癌和非小细胞肺癌在治疗原则上有很大的不同。小细胞肺癌远处转移早，除早期（T₁₋₂N₀M₀）的病人适于手术治疗外，其他均应以非手术治疗为主。非小细胞肺癌则依据确诊时的TNM分期，选择不同的治疗方式。T代表原发肿瘤浸润范围，N代表区域淋巴结转移，M代表远处转移。M₁代表有远处转移，只要有远处转移，临床分期就为Ⅳ期。患者TNM分期为T₂N₁M₁，可知为肺癌Ⅳ期，治疗原则为：化疗，根据基因突变情况考虑靶向治疗。本题无此选项，故最佳答案为放疗和化疗（D对）。手术切除（A错）主要为Ⅰ期肺癌治疗原则。手术切除，配合化疗（C错）主要为Ⅱ期肺癌治疗原则。放疗和化疗主要为Ⅲ期肺癌治疗原则。","","N"],["1994-N75",55,"第二节 脊柱结核","脊柱肿瘤",1994,75,"A","","男性，60岁，腰痛3周，无明显外伤史，X线片示第三腰椎椎体破坏、压缩楔形变、椎间隙正常。最可能的诊断是",[["A","椎体结核"],["B","椎体嗜酸性肉芽肿"],["C","椎体巨细胞瘤"],["D","椎体转移性骨肿瘤"],["E","老年性骨质疏松症，椎体压缩骨折"]],"D","脊柱转移性骨肿瘤（D对）的癌细胞首先浸润椎弓根，后侵犯至椎体，有骨破坏，可形成压缩性骨折改变，而椎间盘很少受累，椎间隙正常，符合病人的X线表现。椎体结核（A错）主要表现为椎间隙狭窄，椎体破坏。椎体嗜酸性肉芽肿（十版外科学P745）（B错）多见于胸椎，以12岁以下儿童多见，整个椎体均匀性压扁呈线条状，椎间隙正常，无发热等全身症状。椎体骨巨细胞瘤（C错）为溶骨性破坏，偏心位，皮质膨胀变薄，肥皂泡样改变，并非压缩性改变。在一定外力伤害作用下，老年骨质疏松症可继发椎体压缩性骨折（E错），该病人无明显外伤史，骨质疏松继发压缩性骨折可能性不大。","","N"],["1994-N76",55,"第四节 膝关节结核","关节腔穿刺注药",1994,76,"A","","早期膝关节滑膜结核，除全身治疗外，局部治疗首选",[["A","滑膜切除术"],["B","关节融合术"],["C","关节腔连续抗结核药滴入冲洗吸引两周"],["D","关节腔抗结核药物注入，每周1～2次"],["E","局部物理治疗"]],"D","滑膜结核病人需卧床休息、局部制动，全身和局部应用抗结核药物。膝关节滑膜结核为渗出性病变，关节积液可扩展进入髌上囊、关节腔的两侧或腘窝，故关节腔用药十分重要，能够控制渗出、杀灭结核杆菌。关节腔内穿刺注药方法如下：髌上囊肿胀穿刺抽液后。将抗结核药物注入，每周1～2次，3个月为一个疗程（D对）。对于结核病灶，一般不使用插管冲洗吸引，否则引流管处可能形成长期不愈的窦道（C错）。早期膝关节结核病人膝关节功能尚存，关节融合术仅在关节功能完全丧失情况下采用（B错）。局部理疗无法治愈膝关节结核病（E错）。","","N"],["1994-N77",54,"第一节 化脓性骨髓炎","慢性血源性骨髓炎治疗",1994,77,"A","","患儿10岁，胫骨中上段慢性骨髓炎，一般情况好，体温不高，局部有流脓窦道，X线片有4cm长整段死骨，周围有不连续包壳。当前的主要治疗是",[["A","手术摘除死骨，肌瓣填塞消灭死腔"],["B","手术摘除死骨，填入庆大链霉素，三周后取出，松质骨植入"],["C","手术摘除死骨，植入细塑料管，每日经管滴入抗菌素"],["D","患肢长腿石膏管型固定，开窗换药"],["E","局部换药，保持引流通畅"]],"D","慢性骨髓炎的治疗，主要为手术治疗，行病灶清除术，原则是清除死骨、炎性肉芽组织和消灭死腔。但是对于该病人，4cm的整段死骨体积较大，包壳尚未充分生成，过早取掉大块死骨会造成长段骨缺损，不宜手术取出死骨，须等待包壳生成后再手术（ABC错）。正确的做法是以长腿石膏管型固定保护患肢，防止发生病理性骨折；患病部位所对石膏体开窗，自此给窦道换药（D对），保持引流通畅。本题E选项亦正确，但当年给出的答案为D。","","N"],["1994-N78",32,"第四节 胆石症","胆总管切开取石、T管引流术",1994,78,"A","","胆总管探查术后所置T形引流管拔除指征中，下列哪项不正确",[["A","术后一周"],["B","血胆红素正常"],["C","病人体温正常"],["D","病人无腹痛、腹胀等症状"],["E","T管造影示肝内外胆管显影正常"]],"A","胆道探查术后放置T管的主要目的是胆道减压引流、预防术后胆漏；减少胆汁对切口的刺激，有利于炎症的消退和胆道切口的愈合；作为支撑，预防胆管狭窄及术后经T管拔除后窦道处理胆道残余结石。胆总管T形引流管拔除的指征为：病人无腹痛、腹胀等症状（D对）；体温正常（C对）；肝功能正常、血胆红素正常（B对），无黄疸；T管造影示肝内外胆管显影正常（E对）；T管通畅则在术后4周左右拔除（A错，为本题正确答案）。过早拔除T管，可因管壁周围纤维组织包裹不严实，胆汁漏入腹腔，导致胆汁性腹膜炎等严重并发症。有关T管引流术相关内容，十版外科学有数据更新。","","N"],["1994-N79",29,"第一节 结、直肠与肛管解剖生理概要","结、直肠肛管的生理功能",1994,79,"A","","以下哪一项是直肠排便功能最重要的环节",[["A","直肠下段发生排便神经反射"],["B","结肠的蠕动，粪便下行"],["C","直肠能分泌粘液"],["D","外括约肌的自主松弛"],["E","腹压的增加"]],"A","直肠下段发生排便神经反射（A对）为直肠排便功能最重要的环节。其基本环节如下：当肠蠕动将粪便推入直肠时，可扩张直肠壁内的感受器，冲动逐级上传至大脑皮层引起便意。若条件许可，即可发生排便反射。此时冲动由盆神经传出，使降结肠、乙状结肠和直肠收缩，肛门内括约肌舒张。同时阴部神经的传出冲动减少，使肛门外括约肌舒张，粪便排出体外。结肠的蠕动，推动粪便下行（B）进入直肠，可引起排便反射，但并非最重要环节。直肠黏膜的杯状细胞等分泌黏液（C）起润滑粪便的作用，使得粪便在肠道中移动更加顺畅，但并非最重要环节。外括约肌的自主松弛（D）为排便反射引起的效应之一，但并非最重要环节。腹压的增加（E）可以促进粪便向下移动，有利于排便，但并非最重要环节。","","N"],["1994-N80",32,"第四节 胆石症","胆囊结石治疗",1994,80,"A","","下列哪项疾病不适合行胆囊切除术",[["A","胆囊结石"],["B","胆总管结石"],["C","胆囊癌"],["D","慢性胆囊炎、胆囊积水"],["E","胆囊息肉"]],"B","胆囊切除术手术用于治疗胆囊疾病，最常见的是胆囊结石（A对）和急、慢性胆囊炎、胆囊积水（D对）；胆囊息肉并非均需要治疗，但是若出现如下息肉恶变的危险因素，则需行胆囊切除术：直径超过1cm；单发病变且基底部宽大；息肉逐渐增大；合并胆囊结石和胆囊壁增厚等，特别是年龄超过50岁者。因此，部分胆囊息肉（E对）亦适合行胆囊切除术。NevinⅠ期及AJCC-UICC 0期胆囊癌（C对）可行单纯胆囊切除术。胆总管结石（B错，为本题正确答案）的常用术式为胆总管切开取石、T管引流术，而非胆囊切除术。","","N"],["1994-N81",13,"第一节 术前准备","肺功能障碍",1994,81,"A","","手术前后要了解病人肺通气情况的最佳方法是",[["A","动脉血气分析"],["B","测肺活量"],["C","血pH值"],["D","胸片"],["E","肺死腔测定"]],"A","测肺活量（B错）是肺功能代偿后的综合结果，不能直观反应病人肺通气情况。血pH值（C错）只能反映酸碱平衡综合代偿的结果。胸片（D错）只能提示肺部有无实质性病变。肺死腔测定（E错）也只能反映肺换气的部分情况。这些检查都不能全面反映病人肺通气情况。但是动脉血气分析可以测得血pH、PaCO₂、BE（碱剩余）、BB（缓冲碱）、AB（实际碳酸氢盐）、SB（标准碳酸氢盐）等数值，不仅有助于反应病人肺通气情况（A对），还有助于了解酸碱平衡的情况。","","N"],["1994-N82",6,"第二节 创伤的病理生理","影响创伤愈合的因素",1994,82,"A","","下列哪项不影响术后伤口的愈合",[["A","术中过多使用电灼止血"],["B","伤口的张力过大"],["C","止血不充分"],["D","留置引流"],["E","伤口边缘内翻"]],"D","术中电灼止血本身对组织是一种损伤，过多使用势必造成愈合负担加重；不必要的血管封闭使得局部血供下降，且电灼过多还有引起脂肪液化坏死的可能，这些均不利于伤口愈合（A错）。伤口的张力过大，则伤口两段组织贴合不紧密，细胞和基质增生填充所需时间较长，且新生的纤维蛋白等由于张力过大可能断裂，影响伤口愈合（B错）。止血不充分使得伤口处血液流失，血供变差，且血液是细菌良好的培养基，易增加感染的发生几率（C错）。伤口边缘内翻造成伤口的对合不整齐，加重愈合难度（E错）。留置引流的目的是将炎性渗出、脓液等引流出创口，为伤口愈合提供良好的愈合环境，有利于伤口的愈合（D对）。","","N"],["1994-N83",13,"第三节 术后并发症的防治","肺膨胀不全",1994,83,"A","","腹部大手术后，早期出现肺功能不全的最常见原因是",[["A","胃内容物误吸"],["B","支气管痉挛"],["C","肺不张"],["D","气胸"],["E","肺水肿"]],"C","上腹部手术的病人，肺膨胀不全（又称肺不张）发生率为25％，老年、肥胖、长期吸烟和有呼吸系统疾病的病人更常见。主要原因有：①腹部大手术后，病人因疼痛而被迫停止腹式呼吸，仅依靠胸式呼吸维持通气；②受限的呼吸运动无法有效排出呼吸道分泌物，腹部切口疼痛也使得病人不敢咳嗽，滞留分泌物阻塞支气管各分支，造成肺膨胀不全；③呼吸道分泌物滞留易诱发肺部炎症的发生，加重肺膨胀不全（C对）。胃内容物误吸（A错）是引起吸入性肺炎和窒息的常见原因，而非肺功能不全。腹部手术一般不会引起支气管痉挛（B错）和气胸（D错）。肺水肿（E错）通常是由于心衰、肺部弥漫性疾病或全身性疾病的肺部表现，一般与腹部手术无关。","","N"],["1994-N84",18,"第四节 乳腺癌","乳腺癌分期",1994,84,"A","","女性，46岁，左乳外上象限无痛性肿物3cm直径，与皮肤轻度粘连。左腋下可触及2个可活动的淋巴结。诊断为“乳腺癌”。按TNM分期，应为",[["A","T₁N₀M₀"],["B","T₁N₁M₀"],["C","T₂N₀M₀"],["D","T₂N₁M₀"],["E","T₂N₂M₀"]],"D","患者确诊为乳腺癌，根据国际抗癌协会建议的T（原发癌瘤）、N（区域淋巴结）、M（远处转移）分期法，患者左乳外上象限无痛性肿物3cm直径属于T₂（癌瘤长径﹥2cm，≤5cm），左腋下可触及2个可活动的淋巴结属于N₁（同侧腋窝有肿大淋巴结，尚可推动），未提及远处转移症状为M₀（无远处转移）。故T₂N₁M₀（D对为正确答案）。","","N"],["1994-N85",1,"第三节 钾代谢紊乱","高钾血症治疗",1994,85,"A","","下列哪一项不是术后必需紧急施行透析的指征",[["A","因体液超载而引起的充血性心衰"],["B","未能纠正的进行性酸中毒"],["C","经治疗无效的高血钾症"],["D","尿毒症性心包炎"],["E","血肌酐高达6mg/dl"]],"A","血肌酐超过442umol/L时，应紧急施行透析治疗，题中血肌酐高达6mg／dl（530umol/L），首选透析替代治疗（E对）。因体液超载而引起的充血性心衰的常规治疗方案为利尿剂、ACEI（或ARB）和β受体阻滞剂三类药物的联合使用，利尿剂治疗无效的顽固性心衰患者，才考虑施行透析治疗（A错，为本题正确答案）。","","N"],["1994-N86",23,"第一节 腹外疝概述","绞窄性疝",1994,86,"A","","由肠壁一部分构成了疝内容的疝，称为",[["A","滑疝"],["B","Richter疝"],["C","嵌顿疝"],["D","直疝"],["E","股疝"]],"B","几种特殊类型的嵌顿疝需要考生记忆，区别其不同主要看疝内容物的差别：①Richter疝（B对）：嵌顿的内容物仅为部分肠壁；②Littre疝：嵌顿的内容物为小肠憩室（通常是Meckel憩室）；③逆行性嵌顿疝：嵌顿的内容物包括几段肠袢，呈现W形。","","N"],["1994-N87",5,"第六节 有芽胞厌氧菌感染","破伤风预防",1994,87,"A","","注射破伤风类毒素主动免疫后，若无外伤，应隔多久再强化一次",[["A","每年"],["B","每2年"],["C","每3年"],["D","5～10年"],["E","不需再强化"]],"D","注射安全剂量的破伤风类毒素抗原，使人体抗体以达到免疫目的，当感染破伤风后，则因机体存在相应抗体，中和破伤风梭菌产生的毒素，从而使病人避免产生临床症状，称主动免疫。由抗原刺激机体产生的抗体，经过一定时间后可逐渐消失。若再次接触抗原的时间间隔过长，产生特异性抗体的记忆B细胞数量较低，再次侵入的抗原刺激机体产生的抗体的量不足以对抗大量的抗原，从而产生临床症状。故每隔一定时间需对主动免疫进行一次强化免疫。破伤风类毒素的强化免疫时间以每隔5～7年为佳（D对）。","","N"],["1994-N88",2,"第四节 血液成分制品","红细胞制品",1994,88,"A","","血液中各种成分的含量大多随贮存时间的延长而下降，只有下列哪一种例外",[["A","红细胞的生命力"],["B","钾离子浓度"],["C","pH"],["D","血小板的活性"],["E","红细胞携带氧的能力"]],"B","现有保存条件下，血液制品的有效期为21天。随着保存时间的增长，体外非适宜的生存环境，血液中细胞（主要为红细胞，也包括白细胞、血小板等其他细胞）的生命力逐渐下降（AD错），主要生理功能即红细胞携氧能力也逐渐降低（E错）；死亡的红细胞逐渐增多，这些红细胞裂解释放出胞内的钾离子，使得库存血中的钾离子浓度不断升高（B对）；红细胞无氧酵解产生乳酸，同时高钾是引起酸中毒的原因，两者均使得pH下降（C错）。","","N"],["1994-N89",10,"第五节 椎管内麻醉","常用局麻药和注药方法",1994,89,"A","","出现全脊髓麻醉时的处理要点是",[["A","静脉注射呼吸兴奋剂"],["B","经鼻管给氧吸入"],["C","静脉注射镇痛镇静剂"],["D","快速输液补充血容量"],["E","立即人工呼吸与支持循环"]],"E","硬膜外麻醉操作过程是通过麻醉针穿刺脊髓外结构（皮肤、皮下组织、棘上韧带、棘间韧带、黄韧带）到达硬膜外，将药物注入。由于操作为盲性，无法直观观察穿刺层次，故有穿刺突破硬脊膜到达蛛网膜下腔的可能，硬膜外麻醉所用局麻药大部分或全部意外注入蛛网膜下隙，使全部脊神经被阻滞，造成全脊椎麻醉，简称全脊麻。全脊麻病人几分钟内便发生呼吸困难、血压下降、意识模糊或消失，继而呼吸停止，严重危及生命。因为危及生命的主要原因是呼吸和循环障碍，故人工呼吸与支持循环为首要治疗（E对）；静脉注射呼吸兴奋剂（A错）、经鼻管给氧吸入（B错）、静脉注射镇痛镇静剂（C错）、快速输液补充血容量都仅仅是对症治疗（D错），无法迅速改善呼吸、循环状态，使病人失去抢救机会。","","N"],["1994-N90",12,"第二节 心肺脑复苏","尽早开始电除颤",1994,90,"A","","关于心脏复苏，以下哪项是正确的",[["A","房颤是心跳骤停的一种类型"],["B","心脏复苏时，首选心内注射给药"],["C","心脏复苏用药，首选去甲肾上腺素"],["D","胸外心脏按压的正确部位是胸骨中部（成人）"],["E","电除颤是治疗室颤最有效的方法"]],"E","心搏骤停是指心脏突然丧失其排血功能而导致周身血液循环停止和组织缺血、缺氧的状态。由心脏的功能状态来看，心搏骤停包括：心室纤颤，无脉性室性心动过速，无脉性心电活动和心搏停止，不包括房颤（A错）。突发情况而又急救设备不足情况下，应给予病人基本生命支持（BLS），主要包括三个尽早：①尽早识别心搏骤停和启动紧急医疗服务系统②尽早开始CPR：包括心脏按压和人工呼吸。胸外心脏按压位置为胸骨下1/2 或两乳头连线中点的胸骨上（十版外科学P161）（D选项有争议），频率为100～120次/分，成人按压深度至少5cm（避免超过6cm）, 儿童至少为胸廓前后径的1/3，青春期前的儿童约为5cm，1岁以内的婴儿约为4cm（九版外科学P78），每次按压后胸部充分回弹。③尽早电除颤：在心搏骤停中心室纤颤的发生率最高，电除颤是目前治疗室颤和无脉室速的最有效方法（E对）。由于心内注射引起的并发症较多，如张力性气胸、心脏压塞、心肌或冠状血管撕裂等，一般不采用。心脏复苏时给药途径首选为经静脉或骨内注射（B错）。心脏复苏用药，首选肾上腺素（C错），研究表明，在心脏按压时使用肾上腺素能使冠脉和心内膜的血流量明显增加，并可增加脑血流量。有关心胸外心脏按压相关数据，九版外科学有内容更新。","","N"],["1994-N92",27,"第四节 肠梗阻","按梗阻部位分类",1994,92,"A","","有关肠梗阻的叙述，下列哪项是正确的",[["A","切口疝常是引起肠梗阻的原因"],["B","肠壁颜色暗红、水肿、增厚、肠腔扩张，说明肠管已无生机"],["C","X线腹部平片未见液平面，就可排除肠梗阻的诊断"],["D","急性结肠完全梗阻为闭袢性肠梗阻，易引起肠绞窄"],["E","急性肠系膜上动脉血栓形成所致的肠梗阻，多见于青年人"]],"D","对于结肠来说，回盲瓣具有单向活瓣作用，即结肠的内容物不能反流回小肠，若出现结肠段的梗阻，则此梗阻段与回盲瓣之间形成两端闭塞的密闭肠腔，肠管张力极高，压迫供应该段肠管的动脉，导致血供下降甚至消失，因而急性结肠完全梗阻为闭袢性肠梗阻，易引起肠绞窄（D对）。切口疝是发生于腹壁手术切口处的疝，由于切口的存在，切口疝的疝环一般比较宽大，很少发生嵌顿影响肠内容物运行，因此，切口疝一般不会导致肠梗阻（A错）。肠壁颜色暗红、水肿、增厚、肠腔扩张，仅仅说明肠管失去活性（B错），若此时及时松解嵌顿，并用温热等渗盐水纱布覆盖该段肠管，或者暂时送回腹腔放置一段时间后，肠管活性有恢复可能；仅当肠管呈紫黑色，失去光泽和弹性，刺激后无蠕动和相应肠系膜内无动脉搏动者，可判定为肠坏死。一般X线腹部平片见气液平面（约50％患者可见），可辅助诊断肠梗阻，但未见气液平面并不能排除肠梗阻，可能梗阻时间过短，尚未发生肠液和气体的积聚（C错）。青年人多见小肠扭转，常由饱食后剧烈运动引起；急性肠系膜上动脉血栓形成所致的肠梗阻多见于有心脏疾患的老年患者（E错）。","","N"],["1994-N113",49,"第一节 骨盆骨折","骨盆骨折临床表现",1994,113,"B","","闭合性骨盆骨折可引起",[["A","骨筋膜室综合征"],["B","肾挫伤"],["C","脂肪栓塞"],["D","出血性休克"],["E","损伤性骨化（骨化性肌炎）"]],"D","骨盆由扁骨组成，内有造血能力旺盛的红骨髓，血运丰富，且骨盆骨折常容易合并髂内、髂外动静脉及其分支的断裂，容易引起大出血，导致出血性休克（D对），严重者可导致病人死亡。骨筋膜室综合征（A错）多见于前臂掌侧和小腿，常由创伤、骨折的血肿和组织水肿使骨筋膜室内内容物体积增加或外包扎过紧、局部压迫使骨筋膜室容积减小而导致骨筋膜室内压力增高所致，导致骨折远端肢体缺血坏死。肾挫伤（B错）多由外界钝性暴力撞击腰腹部所致，肾脏仅后方有肋骨这一骨性结构，肋骨骨折可能导致肾的挫伤。损伤性骨化（骨化性肌炎）（E错）特别多见于肘关节，如肱骨髁上骨折，反复暴力复位或骨折后肘关节伸屈活动受限而进行的强力反复牵拉，导致骨膜剥离形成骨膜下血肿，血肿机化并在关节附近软组织内广泛骨化，造成严重关节活动功能障碍。骨盆骨折可合并盆腔内静脉丛破裂，可导致脂肪栓塞，其发生率可高达35%～50%（十版外科学P688），因此本题C亦对，但当年给出的答案为D。","","N"],["1994-N114",44,"第三节 骨折的并发症","脂肪栓塞综合征",1994,114,"B","","闭合性成人股骨干骨折可引起",[["A","骨筋膜室综合征"],["B","肾挫伤"],["C","脂肪栓塞"],["D","出血性休克"],["E","损伤性骨化（骨化性肌炎）"]],"C","股骨干是人体最长的长骨，对于成人来说，除两端骨骺处外，股骨内造血组织退化，被大量脂肪组织填充，闭合性成人股骨干骨折可引起脂肪组织进入血管，可堵塞细小血管，形成脂肪栓塞（C对）。骨筋膜室综合征（A错）多见于前臂掌侧和小腿，常由创伤、骨折的血肿和组织水肿使骨筋膜室内内容物体积增加或外包扎过紧、局部压迫使骨筋膜室容积减小而导致骨筋膜室内压力增高所致，导致骨折远端肢体缺血坏死。肾挫伤（B错）多由外界钝性暴力撞击腰腹部所致，肾脏仅后方有肋骨这一骨性结构，肋骨骨折可能导致肾的挫伤。损伤性骨化（骨化性肌炎）（E错）特别多见于肘关节，如肱骨髁上骨折，反复暴力复位或骨折后肘关节伸屈活动受限而进行的强力反复牵拉，导致骨膜剥离形成骨膜下血肿，血肿机化并在关节附近软组织内广泛骨化，造成严重关节活动功能障碍。成人股骨干骨折的失血量可达2000ml以上，可引起出血性休克（十版外科学P616）。本题D亦正确，但当年给出的答案为C。","","N"],["1994-N115",29,"第九节 肛裂","肛裂临床表现",1994,115,"B","","肛裂",[["A","排便可加重肛门疼痛，伴大便带鲜血"],["B","肛周疼痛伴发热"],["C","反复发作的肛周红肿疼痛，窦道外口流出脓性分泌物"],["D","肛门疼痛，伴有局部暗紫色肿块"],["E","排便时出血、无痛"]],"A","肛裂的主要症状是排便时剧痛，典型表现为便时肛管刀割样或烧灼样疼痛，便后数分钟缓解，随后肛门括约肌痉挛，再次出现剧痛。若肛裂溃疡出血可粘于粪便表面，导致大便带鲜血（A对）。肛周疼痛伴发热（B错）为直肠周围脓肿的临床表现。反复发作的肛周红肿疼痛，窦道外口流出脓性分泌物（C错）为肛瘘的临床表现。肛门疼痛，伴有局部暗紫色肿块（D错）为血栓性外痔的临床表现。排便时出血、无痛（E错）为痔的临床表现。","","N"],["1994-N116",29,"第十节 肛周脓肿","肛周脓肿临床表现",1994,116,"B","","直肠周围脓肿",[["A","排便可加重肛门疼痛，伴大便带鲜血"],["B","肛周疼痛伴发热"],["C","反复发作的肛周红肿疼痛，窦道外口流出脓性分泌物"],["D","肛门疼痛，伴有局部暗紫色肿块"],["E","排便时出血、无痛"]],"B","直肠周围脓肿（B对）指直肠肛管周围软组织或其周围间隙发生的急性化脓性感染，并形成脓肿。主要症状为肛周持续性跳动性疼痛，病变处明显红肿，有硬结和压痛，脓肿形成可有波动感，可有一定的感染中毒症状如发热、乏力、食欲不振等。排便可加重肛门疼痛，伴大便带鲜血（A错）为肛裂的临床表现。反复发作的肛周红肿疼痛，窦道外口流出脓性分泌物（C错）为肛瘘的临床表现。肛门疼痛，伴有局部暗紫色肿块（D错）为血栓性外痔的临床表现。排便时出血、无痛（E错）为内痔的临床表现。","","N"],["1994-N117",34,"第一节 上消化道大出血的诊断和处理","胆道出血",1994,117,"B","","胆道出血多有",[["A","呕大量鲜血，可伴有血块"],["B","强烈呕吐，先胃液后鲜血与血块"],["C","呕血伴腹痛、寒战、高热与黄疸"],["D","柏油样大便"],["E","鲜血样大便"]],"C","不同原因引起的消化道出血可有不同的临床表现，各自均有其特点。呕大量鲜血，可伴有血块（A错）可见于食管或胃底曲张静脉破裂引起的出血，一次出血量常达500～1000ml，常可引起休克。强烈呕吐，先胃液后鲜血与血块（B错）见于贲门胃痛黏膜撕裂征（Mallory-Weiss综合征）， 因为强烈呕吐导致贲门黏膜撕裂出血，多由一些少见病如食管裂孔疝、胃息肉、胃和十二指肠良性肿瘤等引起。柏油样大便（D错），可见于慢性消化道溃疡出血、上消化道溃疡破裂出血等疾病，一般出血量达到50ml便可引起柏油样便。鲜血样大便（E错）主要出血部位一般位于肛管、直肠或乙状结肠，或肛周部位，如直肠癌、肛裂、内痔等，因出血位置较低，肠腔内血液尚未消化便排出体外。胆道出血的临床特点是周期性出血，每隔1-2周发作一次，多反复发作。当大量出血时，胆道压力骤然升高，引起Oddi括约肌痉挛，血凝块堵塞胆管，出现胆绞痛，继发黄疸，随后可出现呕血及便血。在部分胆道梗阻病人可继发胆道感染，患者可有寒战高热等中毒症状。综上，胆道出血多有呕血伴腹痛、寒战、高热与黄疸（C对）的表现。","","N"],["1994-N118",34,"第一节 上消化道大出血的诊断和处理","上消化道大出血临床分析",1994,118,"B","","贲门胃痛黏膜撕裂征（Mallory-Weiss综合征）可有",[["A","呕大量鲜血，可伴有血块"],["B","强烈呕吐，先胃液后鲜血与血块"],["C","呕血伴腹痛、寒战、高热与黄疸"],["D","柏油样大便"],["E","鲜血样大便"]],"B","不同原因引起的消化道出血可有不同的临床表现，各自均有其特点。贲门胃痛黏膜撕裂征（Mallory-Weiss综合征）， 因为强烈呕吐导致贲门黏膜撕裂出血，表现为强烈呕吐，先胃液后鲜血与血块（B对），多由一些少见病如食管裂孔疝、胃息肉、胃和十二指肠良性肿瘤等引起。呕大量鲜血，可伴有血块（A错）可见于食管或胃底曲张静脉破裂引起的出血，一次出血量常达500～1000ml，常可引起休克。呕血伴腹痛、寒战、高热与黄疸（C错）为胆道出血的表现，大量出血时，胆道压力骤然升高，引起Oddi括约肌痉挛，血凝块堵塞胆管，出现胆绞痛，继发黄疸，随后可出现呕血及便血。在部分胆道梗阻病人可继发胆道感染，患者可有寒战高热等中毒症状。柏油样大便（D错），可见于慢性消化道溃疡出血、上消化道溃疡破裂出血等疾病，一般出血量达到50ml便可引起柏油样便。鲜血样大便（E错）主要出血部位一般位于肛管、直肠或乙状结肠，或肛周部位，如直肠癌、肛裂、内痔等，因出血位置较低，肠腔内血液尚未消化便排出体外。","","N"],["1994-N135",17,"第一节 甲状腺疾病","甲状旁腺功能减退",1994,135,"C","","甲状旁腺损伤",[["A","喝水发呛"],["B","声音嘶哑"],["C","两者均有"],["D","两者均无"]],"D","甲状旁腺损伤可致血钙浓度下降至2.0mmol/L以下，神经肌肉的应激性显著增高，多数在术后1～3天出现手足抽搐。多数病人只有面部、唇部或手足部的针刺样麻木感或强直感，经过2～3周后，未受损的甲状旁腺增大，起到代偿作用，症状便可消失。严重者可出现面肌和手足伴有疼痛的持续性痉挛，每天发作多次，每次持续10～20分钟或更长，严重者可发生喉或膈肌痉挛，引起窒息死亡。喝水呛咳（A错）是因为手术损伤了喉上神经内支、咽喉部黏膜感觉障碍引起。声音嘶哑（B错）是由于手术损伤了喉返神经，导致声带瘫痪。本题AB均错，正确答案为D。","","N"],["1994-N136",17,"第一节 甲状腺疾病","喉上神经损伤",1994,136,"C","","喉上神经损伤",[["A","喝水发呛"],["B","声音嘶哑"],["C","两者均有"],["D","两者均无"]],"A","喉上神经损伤多发生于离断甲状腺上动脉时，由于远离甲状腺上极导致损伤到喉上神经。喉上神经分内（感觉）、外（运动）两支，若损伤外支会使环甲肌瘫痪，引起声带松弛，音调降低；内支损伤，则喉部黏膜感觉丧失，进食特别是饮水时，容易误咽发生呛咳（A对）。声音嘶哑（B错）是由于手术损伤了喉返神经，导致声带瘫痪。","","N"],["1994-N137",53,"第二节 腰椎退行性疾病","腰椎间盘突出症影像学及其他检查",1994,137,"C","","腰椎间盘突出症",[["A","直腿抬高试验阳性和加强试验阳性"],["B","X光片示腰椎生理前突消失和侧凸"],["C","两者均可有"],["D","两者均无"]],"C","病人仰卧，伸膝，被动抬高患肢，正常人神经根有4mm的滑动度，下肢抬高至60°～70°方有腘窝不适，腰椎间盘突出症患者神经根受压或粘连使滑动度减少或消失，抬高在60°以内即可出现坐骨神经痛，称为直腿抬高试验阳性。阳性时，缓慢降低患肢高度，待放射痛消失，再被动背曲踝关节以牵拉坐骨神经，可再次出现放射痛，称为加强试验阳性（A对）。腰椎间盘突出症病人，病人为减轻疼痛，可出现姿势性代偿畸形，X光片可见腰椎生理前突消失和侧凸（B对）。本题AB均对，正确答案为C。","","N"],["1994-N138",53,"第二节 腰椎退行性疾病","X线平片",1994,138,"C","","急性腰扭伤",[["A","直腿抬高试验阳性和加强试验阳性"],["B","X光片示腰椎生理前突消失和侧凸"],["C","两者均可有"],["D","两者均无"]],"B","直腿抬高试验和加强试验：病人仰卧，检查者一手托病人足跟，另一手保持膝关节伸直，缓慢抬高患肢，如在60°范围之内即出现疼痛坐骨神经的放射痛，称为直腿抬高试验阳性；此时，缓慢放低患肢高度，待放射痛消失后，再将踝关节被动屈曲，如再出现放射痛，则为加强试验阳性。急性腰扭伤病人由于棘上、棘间韧带受损，可出现直腿抬高实验阳性，但主要为肌肉、软组织损伤，不涉及神经根，故该实验加强试验阴性（A错）。急性腰扭伤疼痛可较严重，部分病人为减轻疼痛可出现姿势性代偿畸形，此时X光片示腰椎生理前突消失和侧凸（B对）。","","N"],["1994-N157",13,"第三节 术后并发症的防治","切口感染",1994,157,"X","","下肢静脉切开插管后一周，出现寒战、高热，静脉切开处伤口红肿，并有脓性分泌物，此时的处理原则应是",[["A","立即拔除导管"],["B","拆开缝线，保持切口引流通畅"],["C","取脓液进行细菌培养及药敏试验，使用抗生素"],["D","静脉内注射肝素以防静脉血栓形成"]],"ABC","下肢静脉切开插管后一周，静脉切开处伤口红肿，并有脓性分泌物，说明发生了切口感染；又病人有寒战、高热表现，说明感染灶细菌经静脉导管进入血液引起了导管相关性败血症。这样的病人首先要立即拔出导管（A对）并将切口切开引流脓性分泌物（B对），以防止感染的进一步恶化、扩散。因病人已经出现败血症表现，需取血培养及药敏实验筛选出效果最好的抗菌药物治疗（C对）。感染、败血症通常不会引起凝血功能的异常，无需静脉内注射肝素以防静脉血栓形成（D错），肝素冲管仅是为预防静脉插管血栓形成时方使用。","","N"],["1994-N158",26,"第三节 胃十二指肠溃疡的外科治疗","胃切除的范围",1994,158,"X","","关于胃十二指肠溃疡病手术治疗的叙述中，下列哪些是正确的",[["A","胃大部切除术是切除胃远侧的2/3～3/4"],["B","毕Ⅱ式胃大部切除术易使吻合口张力增加，术后溃疡复发率高"],["C","毕Ⅰ式胃大部切除术一般适用于十二指肠溃疡"],["D","高选择性胃迷走神经切断术不需附加引流手术"]],"AD","胃大部切除术切除范围包括胃远侧的2/3～3/4（A对）并包括幽门、近胃侧部分十二指肠球部。毕Ⅱ式胃大部切除术不需要牵拉两断端在原位进行吻合，因而吻合口张力低，此外毕Ⅱ式手术切除了溃疡的好发部位及泌酸的大部分胃体，因而溃疡复发率低；毕Ⅰ式胃大部切除术易使吻合口张力增加，术后溃疡复发率高（B错）。由于十二指肠溃疡常伴有高胃酸，因此手术中切胃范围要比胃溃疡大，行毕Ⅰ式胃大部切除术会导致吻合口张力过大，因此十二指肠溃疡宜行毕Ⅱ式胃大部切除术；胃溃疡胃酸增高程度不高，手术需切除的胃范围少，因此胃溃疡宜行毕Ⅰ式胃大部切除术（C错）。高选择性胃迷走神经切断术不需附加引流手术（D对），因其未切断支配胃窦部的迷走神经的鸦爪支，术后无排空障碍、无胃潴留。","","N"],["1994-N159",31,"门静脉高压","三腔二囊管压迫止血",1994,159,"X","","应用三腔管压迫治疗食管静脉曲张破裂出血，下列哪些处理是正确的",[["A","病人应取侧卧位或头部侧转"],["B","放置时间一般不宜持续超过3～5天"],["C","管端牵引重量约1kg"],["D","每隔12小时应将气囊放空10～20分钟"]],"ABD","三腔二囊管压迫止血是利用气囊分别压迫胃底和食管下段破裂的曲张静脉，以达到止血的目。该管有三腔，一通圆形气囊，充气150～200ml后压迫胃底；一通圆柱形气囊，充气100～150ml后压迫食管下段；一通胃腔，经此腔可行吸引、冲洗和注入药物、液体等。三腔二囊管放置有一定的程序：将三腔二囊管轻轻经鼻置入，直至插入50～60cm，抽出胃内容物为止；先充气胃囊，然后轻轻拉管，感到不再被拉出时，即悬以重量约0.25～0.5kg的物品（C错），作牵引压迫；接着经第三腔注入冷盐水洗胃，如无继续出血就说明出血部位在胃底，不需再充气食管囊，否则要再充气食管囊，以压迫食管下段止血。病人应侧卧或头侧转（A对），便于吐出唾液，吸尽病人咽喉部分泌物，以防发生吸入性肺炎。放置三腔管的时间不宜持续超过3～5天（B对）（补充说明：九版外科学认为充气压迫一般不超过24h，但无论是八版外科学还是八版黄家驷外科学P1568都认为放置持续时间不宜超过3～5天），否则，可使食管或胃底黏膜因受压迫太久而发生溃烂、坏死、食管破裂。因此，每隔12小时，应将气囊放空10～20分钟（D对）。","","N"],["1994-N160",44,"第七节 骨折的治疗原则","切开复位",1994,160,"X","","四肢新鲜闭合性骨折切开复位内固定的适应症是",[["A","骨折端间有软组织嵌夹，手法复位失败"],["B","关节内骨折，手法复位对位不好"],["C","并发主要血管损伤"],["D","并发主要神经损伤"]],"ABCD","骨折移位后的复位主要有两种方法：闭合复位和切开复位。闭合复位包括手法复位和牵引复位，该方法创伤小，复位成功则效果多满意。若闭合复位对周围组织结构损伤大或闭合复位难以成功者，或必须达到解剖复位方不会影响患肢功能者，则需行切开复位。骨折端间有软组织嵌夹，手法复位失败（A对），应切开复位，否则易导致骨折不愈合。关节内骨折，手法复位对位不好（B对），将导致外伤性关节炎，影响关节功能，须尽早手术治疗。并发主要血管损伤（C对），应立即手术处理，否则易导致肢体缺血坏死。骨折并发主要神经损伤（D对），须切开复位，尽可能保护神经功能，以提高患者的生活质量。","","N"],["1995-N75",43,"第一节 先天性畸形","手术疗法",1995,75,"A","","先天性肌性斜颈，最佳手术时间是",[["A","3个月以内"],["B","6个月以内"],["C","1岁以内"],["D","1岁以上"],["E","12岁以上"]],"D","对于先天性斜颈，非手术治疗适用于＜1岁的婴儿。对于＞1岁（D对）的患儿，应行手术治疗，手术方法为胸锁乳突肌切断术。","","N"],["1995-N76",44,"第三节 骨折的并发症","骨折的并发症概述",1995,76,"A","","关于骨折的合并症，下列哪项不对",[["A","肱骨中段骨折可伤及桡神经"],["B","肱骨内上髁骨折可伤及肱动脉"],["C","腓骨小头和颈部骨折，可同时伤及腓总神经"],["D","下胸壁肋骨骨折，可同时发生肝或脾破裂"],["E","股骨颈骨折可致股骨头缺血坏死"]],"B","一些骨的周围组织中存在有重要的周围神经、血管和器官，这些部位的骨折可能对周围组织造成由骨折断端移位引起的损伤。桡神经沿肱骨中、下1/3的桡神经沟下行，紧贴肱骨骨面，因此肱骨中段骨折可伤及桡神经（A对）。肱骨髁上的前方有正中神经和肱动脉经过，故在伸直型肱骨髁上骨折时，可能会引起这些血管、神经的损伤。而肱骨内上髁骨折不会损伤肱动脉（B错，为本题正确答案）。注意区分肱骨内上髁骨折和肱骨髁上骨折。在腓骨颈，有腓总神经经由腘窝后、外侧斜向下外方，经腓骨颈进入腓骨长、短肌及小腿前方肌群，因此腓骨小头和颈部骨折，可同时伤及腓总神经（C对）。胸骨骨折断端可向后戳伤后位的脏器，而肝脾分别位于右左季肋部，因此下胸壁肋骨骨折，可同时发生肝或脾破裂（D对）。股骨干滋养动脉升支是支配股骨头的主要血管之一，沿股骨颈进入股骨头，当股骨颈骨折时，可损伤该动脉，造成股骨头缺血坏死（E对）。","","N"],["1995-N77",44,"第六节 骨折的急救","骨折的急救概述",1995,77,"A","","骨折急救处理中哪项不恰当",[["A","凡有骨折可疑的病人，均按骨折处理"],["B","复位已戳出创口的骨折端"],["C","创口包扎，止血"],["D","妥善固定患肢，若有显著畸形，可手力牵引，使之挺直"],["E","迅速运往医院"]],"B","骨折急救的大原则是：抢救生命，创口包扎，妥善固定，迅速转运。对于任何怀疑发生骨折的病人，均应按照骨折处理（A对），以防止骨折发生移位等造成二次损伤。对于已经戳出伤口的骨折端，均视为受到了污染，若无必要，则不急于复位（B错，为本题正确答案），需清创术后再进行复位，以防止将污染带入伤口深处。创口包扎、止血（C对）是避免创口二次污染、防止失血的重要急救操作，需注意包扎并不等于复位，戳出创口的骨折端也可以用无菌纱布覆盖包扎，避免加重污染。妥善固定患肢，若有显著畸形，可手力牵引，使之挺直（D对），目的是恢复患肢的正常解剖位置，避免对周围组织的二次损伤。病人经初步处理，妥善固定后，应迅速运往医院（E对）以进行下一步治疗。","","N"],["1995-N78",13,"第一节 术前准备","一般准备",1995,78,"A","","如拟应用抗菌药物来预防手术后感染时，一般原则应是",[["A","术前应用三天，术后继续用三天"],["B","术前应用一天，术后继用一周"],["C","术前和术中各给一次，术后继用1～2日"],["D","术前不用，术后应用三天"],["E","术前不用，术后应用至伤口拆线"]],"C","外科手术预防用药目的：预防手术后切口感染，以及清洁-污染或污染手术后手术部位感染及术后可能发生的全身性感染。为保证手术过程中所用抗生素能达到最佳血药浓度，预防性抗生素的给药方法为：预防性抗生素的给药方法：应在切皮前30～60分钟输注完毕；手术时间超过3小时或术中出血量大于1500ml，术中可重复使用一次；预防用药时间一般不超过24小时，个别情况可延长至48小时（C对）。需注意，术前已经存在细菌性感染的手术，如腹腔脏器穿孔腹膜炎、脓肿切开引流术、气性坏疽截肢术等，属于抗菌药物治疗性应用，不属预防应用范畴。","","N"],["1995-N80",1,"第三节 钾代谢紊乱","低钾血症病因",1995,80,"A","","低钾性碱中毒可能出现于下列哪种情况",[["A","尿毒症"],["B","胃手术后"],["C","术后少尿"],["D","严重创伤"],["E","大量输血"]],"B","胃手术后（B对）须持续胃肠减压，丢失大量富含钾离子的消化液；且须禁食，导致钾的摄入不足，若不注意补充钾盐，容易导致低钾血症。钾离子主要通过肾脏排泄，尿毒症（A错）及术后少尿（C错），患者肾功能减退，肾脏排钾减少，容易导致高钾血症。严重创伤（D错）病人由于组织细胞的大量破坏，导致细胞内钾离子释放入血引起高钾血症。大量输血（E错），因血液抗凝剂为枸橼酸钾，此外长期储存的红细胞缺乏葡萄糖供应，能量代谢障碍，导致红细胞膜上的Na⁺/K⁺/ATP酶功能障碍，红细胞内钾释放入血，引起高钾血症。","","N"],["1995-N81",33,"第二节 胰腺炎","胰酶测定",1995,81,"A","","急性胰腺炎发病12小时以内，哪一项实验室检查诊断比较准确",[["A","血钙"],["B","血糖"],["C","血淀粉酶"],["D","血脂肪酶"],["E","尿淀粉酶"]],"C","诊断急性胰腺炎最重要的实验室指标是血、尿淀粉酶，其次为血清脂肪酶。血清淀粉酶在发病3～4小时升高，24小时达高峰，持续4～5天恢复正常；尿淀粉酶（E错）及血脂肪酶（D错）在24小时才开始升高，持续1～2周恢复正常。因此，12小时内采用血淀粉酶（C对）检查比较准确。血钙（A错）及血糖（B错）常用于辅助判断急性胰腺炎的病情严重程度。重型胰腺炎可导致腹腔内脂肪组织大量坏死，释放出的脂肪酸与钙离子结合，生成不溶性脂肪酸钙（钙皂），导致血钙降低（＜1.87mmol/L）。重型胰腺炎时，胰腺实质坏死严重，胰岛功能严重受损，导致胰岛素分泌骤降，血糖升高（＞11.1mmol/L）。","","N"],["1995-N82",18,"第四节 乳腺癌","转移途径",1995,82,"A","","下列哪项因素与决定女性乳癌患者预后关系最密切",[["A","原发肿瘤大小"],["B","肿瘤所处的象限"],["C","手术范围"],["D","腋窝有无淋巴结转移及数量"],["E","肿瘤激素受体状况"]],"D","肿瘤对于机体的危害，除了肿瘤本身的生长不受控制外，更加重要的一点是其具有浸润、转移的特点，且一旦发生转移，则会左右治疗方案的选择，并且严重影响预后。对于没有发生转移的肿瘤来说，完全的切除往往能取得较好的治疗效果；一旦发生了转移，则预后明显变差。原发肿瘤大小（A错）、肿瘤所处的象限（B错）、手术范围（C错）、肿瘤激素受体状况（E错）均对乳腺癌患者的预后产生一定的影响，但影响最为显著的是腋窝有无淋巴结转移及转移的数量（D对），一般来说，淋巴结阴性者预后好；因转移而肿大的淋巴结数量越多预后越差。","","N"],["1995-N83",34,"第一节 上消化道大出血的诊断和处理","应激性溃疡或急性糜烂性胃炎",1995,83,"A","","下述应激性溃疡的名称中哪个与烧伤有关",[["A","急性消化性溃疡"],["B","糜烂性胃炎"],["C","出血性胃炎"],["D","Curling溃疡"],["E","Cushing溃疡"]],"D","Curling溃疡又称柯林溃疡，是指不同程度烧伤后继发的应激性溃疡（D对），临床上早期除偶有腹部隐痛和黑便外，其他症状甚少，多在发生大出血或穿孔后被发现，出血和穿孔时间多在烧伤后1～3周。急性消化性溃疡（A错）与幽门螺杆菌感染、长期服用非甾体类抗炎药有关。糜烂性胃炎（B错）和出血性胃炎（C错）近年来统称为急性胃黏膜病变，与严重创伤、败血症等引起的强烈的应激反应、服用非甾体类抗炎药及饮酒等有关。Cushing溃疡（E错）是中枢神经系统病变（如严重脑外伤）所致的溃疡。","","N"],["1995-N84",3,"第一节 外科休克概述","微循环的变化",1995,84,"A","","关于休克的叙述中，下列哪项是错误的",[["A","休克的本质是血压下降"],["B","休克时机体有效循环血量急剧减少"],["C","休克时脑动脉和冠状动脉收缩不明显"],["D","休克时肾血流量减少、肾小球滤过率降低"],["E","休克抑制期微循环的病理改变是毛细血管容积增大"]],"A","休克是指机体有效循环血容量减少（B对）、组织灌注不足，细胞代谢紊乱和功能受损的病理过程。氧供给不足和需求增加是休克的本质（A错，为本题正确答案）。休克时因血压下降、儿茶酚胺分泌增加使肾的入球血管痉挛，肾血流量减少、肾小球滤过率降低（D对）。休克早期，交感神经兴奋，不重要脏器（如胃、肠、肾等）的血管收缩，重要器官的血管（如心、脑）的血管收缩不明显（C对）。休克抑制期乳酸等代谢产物的堆积，微动脉及毛细血管前括约肌对其敏感而舒张，毛细血管后的小静脉对其不敏感而仍处在收缩状态，微循环内“只进不出”，血液淤滞，从而使得毛细血管容积增大（E对）。","","N"],["1995-N85",4,"第一节 外科病人的代谢变化","机体能量需要量的确定",1995,85,"A","","卧床、无发热或异常消耗的成年男性病人每天最低热卡需要是",[["A","15～20大卡/公斤体重"],["B","25～30大卡/公斤体重"],["C","30～50大卡/公斤体重"],["D","50～60大卡/公斤体重"],["E","75大卡/公斤体重"]],"B","卧床、无发热或异常消耗的成年男性每天最低热卡需要时25～30 大卡/ 公斤体重（B对），有关正常人基础能量需要的相关内容，九版外科学有数据更新（十版外科学P38）。","","N"],["1995-N86",10,"第三节 全身麻醉","吗啡",1995,86,"A","","麻醉前用药中，使用麻醉性镇痛剂（吗啡等）的主要目的是下述的哪项",[["A","降低氧耗量"],["B","抑制肠管蠕动"],["C","稳定血压"],["D","止呕吐"],["E","镇静"]],"E","麻醉性镇痛剂包括吗啡和哌替啶，主要作用有：镇痛；镇静、致欣快作用；抑制呼吸；镇咳；缩瞳；减慢胃蠕动等。用于麻醉前的主要目的是镇痛和镇静（E对）。降低耗氧量（A错）、抑制肠管蠕动（B错）、稳定血压（C错）、止呕吐（D错）也是麻醉性镇痛剂的作用，但不是麻醉前用药的主要目的。","","N"],["1995-N87",5,"第三节 手、足部急性化脓性细菌感染","甲沟炎和脓性指（趾）头炎预防和治疗",1995,87,"A","","关于脓性指头炎的治疗措施中，下列哪项是错误的",[["A","局部热敷、理疗"],["B","抬高患肢、给止痛剂"],["C","应用磺胺药或抗生素"],["D","必需在局部出现波动时方可切开引流"],["E","疼痛剧烈，指腹张力显著增高时，马上切开减压"]],"D","脓性指头炎是手指末节掌面的皮下组织化脓性感染，多由刺伤引起。致病菌多为金黄色葡萄球菌。指头炎初发时，应悬吊前臂平置患手，避免下垂以减轻疼痛，可酌情应用磺胺药或抗生素（BC对）。经上述处理后炎症常可消退。如果一旦出现跳痛，指头的张力显著增高时，即应切开减压、引流（E对），切开后脓液虽然很少，或没有脓液，但可降低指头密闭腔的压力，减少痛苦和并发症，不能等待波动出现后才切开引流（D错，为本题正确答案）。脓性指头炎局部可进行外敷，但不能进行热敷。热敷可使局部组织缺氧、肿胀疼痛加重（A也为错误答案，本题AD均错）。","","N"],["1995-N88",35,"急腹症","选择性动脉造影",1995,88,"A","","某心脏病患者突发剧烈全腹痛，3小时不缓解，下列哪项检查应为首选",[["A","钡剂肠系造影"],["B","肠系膜血管造影"],["C","钡灌肠"],["D","腹腔镜"],["E","纤维结肠镜"]],"B","心脏病患者心腔内可形成附壁血栓，血栓脱落后可随血液循环进入肠系膜动脉，形成栓塞，导致相应节段肠管急性缺血，引起剧烈疼痛。肠系膜血管造影（B对）可以明确显示栓塞部位。钡剂肠系造影（A错）、钡灌肠（C错）、纤维结肠镜（E错）均不能确诊血管性疾病。腹腔镜（D错）检查创伤相对较大，一般不作为首选检查。","","N"],["1995-N89",17,"第一节 甲状腺疾病","甲状腺功能亢进手术治疗",1995,89,"A","","关于甲状腺功能亢进的叙述中，下列哪项是不正确的",[["A","继发甲亢是手术治疗适应征"],["B","青少年患者禁忌手术治疗"],["C","不准备手术治疗者，一律不应服用碘剂"],["D","手术中结扎、切断甲状腺上极血管时应远离甲状腺上极"],["E","甲状腺危象的发生多因术前准备不够所致"]],"D","继发甲亢是手术治疗适应证（A对）之一。甲状腺素是具有促进机体生长作用的重要激素，且能够促进个体的发育成熟，对于青少年病人，非恶性疾病情况下均应保留甲状腺组织（B对）。由于碘剂只抑制甲状腺素的释放，而不抑制其合成，因此一旦停服碘剂后，贮存于甲状腺滤泡内的甲状腺球蛋白大量分解，甲亢症状可重新出现，甚至比原来更严重，因此，凡不准备施行手术者，不要服用碘剂（C），但病人发生甲状腺危象时，可以用碘剂治疗（十版外科学P236),考虑到出题时间，因此C选项并不严谨。手术中结扎、切断甲状腺上极血管时应紧贴甲状腺上极，远离甲状腺下极，以免损伤喉上神经和喉返神经，简单记忆为“上贴下离”（D错，为本题正确答案）。临床上，甲状腺危象的发生多因术前准备不够（E对），导致术后甲状腺素过量释放，为甲亢术后的严重并发症。","","N"],["1995-N90",23,"第二节 腹股沟疝","嵌顿性和绞窄性疝的处理原则",1995,90,"A","","关于腹股沟嵌顿疝手法复位的叙述中下列哪项不正确",[["A","疝块大、腹壁缺损较大、疝环较松者可试行手法复位"],["B","年老体弱或伴其它严重疾病的嵌顿疝病人，估计肠管无绞窄者可试行手法复位"],["C","嵌顿时间在3～4小时以内，尚无腹膜刺激征者试行手法复位"],["D","手法复位后，仍需继续观察腹部情况"],["E","手法复位方法简便，避免了手术之苦，应该大力推荐"]],"E","疝块大者在手术分离疝囊时有伤及疝内容物的风险；腹壁缺损较大、疝环较松，说明对抗手法复位的阻力小，此种情况下，应试行手法复位（A对）。年老体弱或伴有其他严重疾病者（B对）难以耐受手术的创伤，估计肠管无绞窄可试行手法复位。在嵌顿时间在3～4小时以内，尚无腹膜刺激征者（C对），可试行手法复位。复位后还需严密观察腹部情况，嵌顿性疝若存在血运障碍，即使手法复位成功，也不能排除存在坏死肠管的可能，需对患者进行一段时间的观察，若患者出现腹膜炎症状，需紧急剖腹探查、切除坏死肠管（D对）。单纯手法复位后，疝并未得到根治，大部分病人迟早仍需手术修补，而手法复位本身又带有一定的危险性，所以要严格掌握手法复位的指征（E错，为本题正确答案）。","","N"],["1995-N91",5,"第六节 有芽胞厌氧菌感染","支持对症治疗",1995,91,"A","","在破伤风的治疗措施中，下列哪项最关键",[["A","彻底清创、引流伤口、消除毒素来源"],["B","使用破伤风抗毒素中和游离的毒素"],["C","控制和解除痉挛、预防窒息"],["D","给予大量青霉素、抑制破伤风杆菌"],["E","积极支持治疗"]],"C","破伤风的防治重在防，彻底清创、引流伤口、消除毒素来源，此为预防及初期清除可能感染的破伤风杆菌，从而避免了破伤风的发生（A错）。破伤风发生后，给予破伤风抗毒素能够中和游离毒素，可缩短病程、缓解病情，但只在疾病早期有效，毒素已与神经组织结合则难以奏效（B错）。破伤风的典型症状是在肌紧张性收缩（肌强直、发硬）的基础上，阵发性强烈痉挛，喉肌痉挛、持续的呼吸肌与膈肌痉挛可导致窒息；破伤风病人若能有效控制痉挛发作，多数可明显减少并发症而获得治愈，故此称为破伤风最关键的治疗措施（C对）。给予大量青霉素可以抑制破伤风杆菌生长，避免了疾病的恶化和持续，但无法治疗痉挛症状挽救生命（D错）。阵发性痉挛与抽搐造成机体严重耗损及水、电解质紊乱，维持营养困难，故给予支持治疗，但支持治疗同样需要在控制痉挛、疾病不再恶化的情况下才有意义（E错）。","","N"],["1995-N92",34,"第一节 上消化道大出血的诊断和处理","内镜检查",1995,92,"A","","上消化道出血时对病因诊断最有帮助的检查方法是",[["A","选择性腹腔动脉造影"],["B","内窥镜检查"],["C","X线钡餐检查"],["D","胃粘膜活检"],["E","核素检查"]],"B","对于上消化道出血，行纤维内镜（B对）检查，可迅速明确出血的部位和性质，是上消化道大出血首选的检查，可同时进行双极电凝、电灼、激光、喷注止血等内镜治疗，必要时并可同时钳取少量组织进行活检。选择性腹腔动脉造影（A错）对正在出血的病灶可有发现，无法对出血病变做定性判断。X线钡餐检查（C错）主要用于胃部肿瘤和溃疡的诊断，出血急性期不宜作该检查。胃黏膜活检（D错）主要用于胃癌和其他肿瘤的诊断，不用于对出血的诊断。核素扫描（E错）可用于诊断微量出血及间歇性出血，但只能显示出血在腹部某个区域，而不能判断确切的出血部位，亦不能明确病变的性质，一般不作上消化道大出血的首选检查。","","N"],["1995-N113",57,"第二节 良性骨肿瘤","骨软骨瘤",1995,113,"B","","骨软骨瘤",[["A","X线片示：骨端膨胀性溶骨性破坏"],["B","X线片示：短骨膨胀，有蜂窝状骨吸收区夹杂钙化斑块"],["C","X线片示：长骨干骺端骨破坏和日光射线现象，可有Codman三角"],["D","X线片示：骨膜板层状或“葱皮状”反应性骨形成和骨破坏"],["E","X线片示：自长骨干骺端突出的骨性病损"]],"E","骨软骨瘤属于骨的良性肿瘤，好发于长骨干骺端，X线表现为自长骨干骺端突出的骨性病损（E对），周围无反应性软组织肿胀，无骨膜反应。X线示骨端膨胀性溶骨性破坏（A错）者多为骨巨细胞瘤。X线示短骨膨胀，有蜂窝状骨吸收区夹杂钙化斑块（B错）者为内生软骨瘤（十版外科学P763）。长骨干骺端骨破坏和日光射线现象，可有Codman三角（C错）者为骨肉瘤。X线示骨膜板层状或“葱皮状”反应性骨形成和骨破坏（D错）者为Ewing肉瘤。","","N"],["1995-N114",57,"第四节 原发性恶性骨肿瘤","骨肉瘤影像学表现",1995,114,"B","","骨肉瘤",[["A","X线片示：骨端膨胀性溶骨性破坏"],["B","X线片示：短骨膨胀，有蜂窝状骨吸收区夹杂钙化斑块"],["C","X线片示：长骨干骺端骨破坏和日光射线现象，可有Codman三角"],["D","X线片示：骨膜板层状或“葱皮状”反应性骨形成和骨破坏"],["E","X线片示：自长骨干骺端突出的骨性病损"]],"C","骨肉瘤X线可表现为不同形态，密质骨和髓腔有成骨性、溶骨性和混合性骨质破坏，骨膜反应明显，呈侵袭性发展，可见Codman三角或呈“日光射线”形态”（C对）。X线示骨端膨胀性溶骨性破坏（A错）者多为骨巨细胞瘤。X线示短骨膨胀，有蜂窝状骨吸收区夹杂钙化斑块（B错）者为内生软骨瘤（十版外科学P763）。X线示骨膜板层状或\"葱皮状\"反应性骨形成和骨破坏（D错）者为Ewing肉瘤。X线示自长骨干骺端突出的骨性病损（E错）者为骨软骨瘤（十版外科学P763）。","","N"],["1995-N115",22,"第三节 动脉疾病","动脉栓塞临床表现",1995,115,"B","","下肢急性动脉栓塞可有",[["A","5“P”表现"],["B","Buerger试验阳性"],["C","测定静脉血氧含量明显增高"],["D","Perthes试验阳性"],["E","大隐静脉瓣膜功能试验阳性"]],"A","下肢急性动脉栓塞导致动脉远端肢体血供减少，远端肢体组织代谢功能障碍，导致代谢产物堆积以及神经功能障碍。5“P”表现（A对）是急性动脉栓塞的典型临床表现，即疼痛（Pain）、感觉异常（Paresthesia）、麻痹（Paralysis）、无脉（Pulselssness）、苍白（Pallor）。Buerger试验：又名体位性色泽改变，先抬高下肢70 ～80°，或高举上肢过头，持续60秒，正常肢体远端皮肤保持淡红或稍发白，如呈苍白或蜡白色，提示动脉供血不足；再将下肢下垂于床沿或上肢下垂于身旁，正常人皮肤色泽可在 10 秒内恢复，如恢复时间超过45秒，且色泽不均匀者，进一步提示动脉供血障碍。肢体持续下垂，正常人至多仅有轻度潮红，凡出现明显潮红或发绀者，提示为静脉逆流或回流障碍性疾病。Buerger试验阳性（B错）与下肢急性动脉栓塞无关。测定静脉血氧含量明显增高（C错）主要见于损伤性动静脉瘘和氰化物中毒等组织利用氧障碍的疾病。Perthes试验阳性：又名深静脉通畅试验，主要检查下肢深静脉是否通畅，Perthes试验阳性（D错）提示患者深静脉不通畅，为大隐静脉高位结扎的禁忌证。大隐静脉瓣膜功能试验：又名Trendelenburg试验，主要检查下肢静脉瓣膜功能是否良好，大隐静脉瓣膜功能试验阳性（E错）提示大隐静脉瓣膜功能不全。","","N"],["1995-N116",22,"第四节 静脉疾病","深静脉血栓形成检查",1995,116,"B","","下肢深静脉血栓形成可有",[["A","5“P”表现"],["B","Buerger试验阳性"],["C","测定静脉血氧含量明显增高"],["D","Perthes试验阳性"],["E","大隐静脉瓣膜功能试验阳性"]],"D","Perthes试验阳性：又名深静脉通畅试验，主要检查下肢深静脉是否通畅。具体操作为患者站立，在患肢大腿上1/3处扎止血带，阻断大隐静脉向心回流，然后嘱患者交替伸屈膝关节10～20次，以促进下肢血液从深静脉系统回流，若曲张的浅静脉明显减轻或消失，表示深静脉通畅；若曲张静脉不减轻，甚至加重，说明深静脉阻塞。下肢深静脉血栓形成时，深静脉血液回流障碍，Perthes试验阳性（D对），此时严禁行大隐静脉高位结扎。5“P”表现（A错）是急性动脉栓塞的典型临床表现，即疼痛（Pain）、感觉异常（Paresthesia）、麻痹（Paralysis）、无脉（Pulselssness）、苍白（Pallor），因为下肢急性动脉栓塞导致动脉远端肢体血供减少，远端肢体组织代谢功能障碍，导致代谢产物堆积以及神经功能障碍。Buerger试验：又名体位性色泽改变，先抬高下肢70 ～80°，或高举上肢过头，持续60秒，正常肢体远端皮肤保持淡红或稍发白，如呈苍白或蜡白色，提示动脉供血不足；再将下肢下垂于床沿或上肢下垂于身旁，正常人皮肤色泽可在10秒内恢复，如恢复时间超过45秒，且色泽不均匀者，进一步提示动脉供血障碍。肢体持续下垂，正常人至多仅有轻度潮红，凡出现明显潮红或发绀者，提示为静脉逆流或回流障碍性疾病。因此，Buerger试验阳性（B错）与下肢静脉血栓形成无关。测定静脉血氧含量明显增高（C错）主要见于组织利用氧障碍的疾病，如氰化物中毒。大隐静脉瓣膜功能试验：又名Trendelenburg试验，主要检查下肢静脉瓣膜功能是否良好，大隐静脉瓣膜功能试验阳性（E错）提示瓣膜功能不全。","","N"],["1995-N117",26,"第三节 胃十二指肠溃疡的外科治疗","术后肠梗阻",1995,117,"C","","胃大部切除术后，输出段梗阻可有",[["A","右上腹突发剧痛、局部有腹膜刺激征"],["B","上腹饱胀、呕吐食物和胆汁"],["C","上腹部突发剧痛、频繁呕吐、不含胆汁"],["D","进食后心悸、出汗、恶心、腹泻"],["E","剑突下持续烧灼痛，进食后加重，抗酸剂无效"]],"B","胃大部切除术后早期可有肠梗阻并发症，主要分为输入袢梗阻、输出袢梗阻和吻合口梗阻。输出段梗阻导致混合了胆汁的食物无法顺利通过梗阻端下行进入肠腔，表现为上腹饱胀、呕吐食物及胆汁（B对）。右上腹突发剧痛、局部有腹膜刺激征（A错）为十二指肠残端破裂的表现，因十二指肠残端处理不当或毕Ⅱ式输入袢梗阻，十二指肠内容物经断端进入腹腔，引起腹痛及腹膜刺激征。上腹部突发剧痛、频繁呕吐、不含胆汁（C错）为吻合口梗阻的表现，因食物下行受阻，而胆汁流出道畅通，腹压增高时出现不含胆汁的呕吐。进食后心悸、出汗、恶心、腹泻（D错）为早期倾倒综合征的表现，因高渗性胃内容物过快进入肠腔，使肠道内大量分泌血管活性物质，导致血容量相对不足。剑突下持续烧灼痛，进食后加重，抗酸剂无效（E错）为碱性反流性胃炎的典型表现，因碱性肠液反流至胃，导致胃黏膜充血糜烂，破坏了胃黏膜的屏障作用，与胃酸分泌关系较小，因而抗酸剂无效。","","N"],["1995-N118",26,"第三节 胃十二指肠溃疡的外科治疗","碱性反流性胃炎",1995,118,"C","","胃大部切除术后，碱性反流性胃炎可有",[["A","右上腹突发剧痛、局部有腹膜刺激征"],["B","上腹饱胀、呕吐食物和胆汁"],["C","上腹部突发剧痛、频繁呕吐、不含胆汁"],["D","进食后心悸、出汗、恶心、腹泻"],["E","剑突下持续烧灼痛，进食后加重，抗酸剂无效"]],"E","碱性反流性胃炎常发生于毕Ⅱ式手术后，原因是胃空肠吻合后，正常解剖结构改变，失去幽门—十二指肠的抗返流屏障，碱性胆汁、胰液、肠液流入胃中，破坏胃黏膜屏障，导致胃黏膜充血，水肿、糜烂等改变；临床主要表现为：上腹或胸骨后烧灼痛、呕吐胆汁样液和体重减轻；与胃酸分泌关系较小，因而抗酸剂无效，较为顽固（E对）。右上腹突发剧痛、局部有腹膜刺激征（A错）为十二指肠残端破裂的表现，因十二指肠残端处理不当或毕Ⅱ式输入袢梗阻，十二指肠内容物经断端进入腹腔，引起腹痛及腹膜刺激征。上腹饱胀、呕吐食物及胆汁（B错）为输出段梗阻的表现，因输出段梗阻导致混合了胆汁的食物无法顺利通过梗阻端而下行进入肠腔。上腹部突发剧痛、频繁呕吐、不含胆汁（C错）为吻合口梗阻的表现，因食物下行受阻，而胆汁流出道畅通，腹压增高时出现不含胆汁的呕吐。进食后心悸、出汗、恶心、腹泻（D错）为早期倾倒综合征的表现，因高渗性胃内容物过快进入肠腔，使肠道内大量分泌血管活性物质，导致血容量相对不足。","","N"],["1995-N135",55,"第二节 脊柱结核","X线平片",1995,135,"C","","脊柱结核",[["A","椎体破坏和压缩畸形"],["B","椎间隙狭窄"],["C","两者均有"],["D","两者均无"]],"C","中心型椎体结核的骨质破坏集中在椎体中央，很快出现椎体压缩成楔状，前窄后宽（A对）。边缘型的骨质破坏集中在椎体的上下缘或下缘，表现为进行性椎间隙狭窄（B对），并累及邻近两个椎体。本题AB均对，正确答案为C。","","N"],["1995-N136",55,"第二节 脊柱结核","脊柱肿瘤",1995,136,"C","","脊柱肿瘤",[["A","椎体破坏和压缩畸形"],["B","椎间隙狭窄"],["C","两者均有"],["D","两者均无"]],"A","脊柱肿瘤常先侵犯椎弓根，后累及椎体，可导致椎体破坏和压缩畸形（A对），一般不累及椎间盘，因而椎间隙高度正常（B错）。","","N"],["1995-N137",29,"第六节 结肠癌","结肠癌临床表现",1995,137,"C","","右侧结肠癌常有的临床表现",[["A","贫血、乏力、腹部肿块"],["B","肠梗阻、排便习惯与粪便性状改变"],["C","两组均有"],["D","两组均无"]],"A","右侧结肠为结肠的起始部位，接受来自于小肠消化过的食物残渣，肠内容物含水较多，呈糊状，此外右侧结肠以隆起型多见，肠腔狭窄不明显，因此右侧结肠癌肠梗阻不明显。癌块主要累及右侧结肠，末端结肠功能受影响较小，因此排便习惯与粪便性状改变不明显（B错）。局部癌块可发生远端缺血、坏死、破溃、出血和继发感染，临床上常表现为不明原因的贫血、乏力、腹部肿块（A对）等症状。","","N"],["1995-N138",29,"第六节 结肠癌","结肠癌临床表现",1995,138,"C","","左侧结肠癌常有的临床表现",[["A","贫血、乏力、腹部肿块"],["B","肠梗阻、排便习惯与粪便性状改变"],["C","两组均有"],["D","两组均无"]],"B","结肠具有重吸收水分的功能。肠内容物行至左侧结肠，含水量较少，多呈半固体状，此外左侧结肠癌以浸润型为主，肠腔狭窄明显，因此左侧结肠癌梗阻明显。癌块位于左侧结肠，可影响排便功能。局部癌块出现溃疡出血时，可引起便血。综上所述，左侧结肠癌常有的临床表现为肠梗阻、排便习惯与粪便性状改变（B对）。","","N"],["1995-N157",54,"第一节 化脓性骨髓炎","急性化脓性骨髓炎诊断依据",1995,157,"X","","急性血源性骨髓炎早期诊断根据是",[["A","起病急，全身感染中毒症状重"],["B","患部持续剧痛和深压痛，不愿活动患肢"],["C","局部分层穿刺抽出液检查，有脓细胞或细菌"],["D","X线片可见骨破坏和骨增生"]],"ABC","急性血源性骨髓炎系深部化脓性感染，起病急，寒战后高热，可达39℃以上，并有明显感染中毒症状（A对）。早期只有患区剧痛，患肢半屈曲状，周围肌痉挛，因疼痛不愿活动患肢（B对）。局部分层穿刺抽出液检查，有脓细胞或细菌（C对）可明确诊断。骨髓炎发病7-10天内，骨质改变常不明显，主要为软组织肿胀。一般认为，起病后14天内的X线检查往往无异常发现，X线无法发现骨破坏和骨增生的（D错）。","","N"],["1995-N158",3,"第三节 感染性休克","感染性休克概述",1995,158,"X","","下列哪些疾病常并发败血症休克",[["A","急性阑尾炎穿孔"],["B","急性梗阻性化脓性胆管炎"],["C","原发性腹膜炎"],["D","重症急性胰腺炎"]],"BD","阑尾附近组织及大网膜较多，穿孔后多引起局限性的腹膜炎，少引起败血症（A错）。急性化脓性梗阻性胆管炎时，胆管阻塞，管腔内压力增高，感染细菌逆流进肝内胆小管并易位入静脉系统，引起败血症（B对）。原发性腹膜炎致病菌多为溶血性链球菌、肺炎双球菌等革兰阳性球菌，并发败血症休克较少见（C错）。继发性腹膜炎多为大肠埃希菌、厌氧拟杆菌等革兰阴性杆菌，一般都是混合性感染，故毒性较强，常并发败血症休克。急性重症胰腺炎时，腹腔内组织坏死严重，血管壁通透性增高，胃肠道细菌易位进入血液，同时由于大量体液渗出、聚集于腹腔，造成脱水，易造成感染性休克（D对）。","","N"],["1995-N159",10,"第三节 全身麻醉","通气不足",1995,159,"X","","吸入麻醉过程中，病人出现二氧化碳蓄积的早期表现为",[["A","面色和甲床苍白"],["B","血压升高，脉搏增速"],["C","呼吸加深加快"],["D","肌肉紧张度增加"]],"BCD","二氧化碳蓄积早期，主要出现酸中毒的临床表现：酸中毒、代谢产物堆积使得毛细血管扩张，面色和甲床潮红，甚至出现紫绀，而非苍白（A错）；酸中毒刺激颈动脉体和主动脉体，使得心率增快、血压升高以加速血液流动，代偿机体组织缺氧状态（B对），呼吸加大加深，以排出过量的CO₂（C对）；CO₂蓄积、酸中毒使得机体处于应激状态，肌肉的紧张度增加（D对）。","","N"],["1995-N160",30,"第二节 肝脓肿","细菌性肝脓肿病因和病理",1995,160,"X","","细菌可经下列哪些途径进入肝脏引起细菌性肝脓肿",[["A","胆道"],["B","肝动脉"],["C","门静脉"],["D","开放性肝损伤的伤口"]],"ABCD","胆道（A对）感染时，细菌循胆管上行（胆总管→左右肝管→肝脏），可引起细菌性肝脓肿，此为最主要的感染途径，约占50%。肝脏有门静脉（C对）和肝动脉（B对）双重血供，细菌可随血流进入肝脏，引起细菌性肝脓肿。开放性肝损伤时，肝脏直接与外界相通，外界细菌可经开放性肝损伤的伤口（D对）侵入肝脏，形成细菌性肝脓肿。","","N"],["1996-N75",57,"第四节 原发性恶性骨肿瘤","骨肉瘤治疗",1996,75,"A","","单纯使用根治性切除手术治疗骨肉瘤，5年存活率不高，其主要原因是",[["A","早期髓腔内广泛蔓延"],["B","早期淋巴管内瘤栓形成"],["C","早期血液中发现瘤细胞"],["D","早期广泛侵犯软组织"],["E","多见于年轻人"]],"C","骨肉瘤是最常见的恶性骨肿瘤，恶性程度高。发生血行转移早（肺转移发生率极高），因此5年存活率不高。为了提高疗效，应常规行术前、术后化疗，可降低瘤负荷，减少转移，延长患者生存期。","","N"],["1996-N76",46,"第一节 手外伤","组织修复",1996,76,"A","","右手食指指腹切削伤，有较大皮肤缺损，创底组织血液循环良好，此伤口正确的处理方法是",[["A","拉拢缝合"],["B","切除末节指骨，缩短手指后直接缝合"],["C","中厚皮片移植"],["D","带蒂皮瓣移植"],["E","凡士林纱布覆盖包扎，定期换药"]],"C","病人为右手食指切割伤，食指指腹处皮肤有较大缺损。若采用拉拢缝合，其张力太大，可影响手指功能恢复（A错）。病人仅为食指指腹切割伤，若切除末节指骨，将使得手指长度缩短，将严重影响手指功能（B错）。血供良好部位不采用带蒂皮瓣移植，该方法多用于骨外露、组织血供情况差等情况下的植皮（D错）。仅以凡士林纱布覆盖包扎，定期换药，并不修复受损裸露的创面，不利于创面的愈合（E错）。创底组织血液循环良好，可行植皮术保护创面。全厚皮片 包括皮肤的全层。存活后色泽、弹性、功能接近正常皮肤、耐磨性好。适用于手掌、足底与面颈部的创面修复（C对）。中厚皮片多适用于关节、手背等功能部位的修复，而指腹属于手掌面，因此本题C选项亦不严谨。","","N"],["1996-N77",43,"第一节 先天性畸形","站立前期",1996,77,"A","","关于先天性髋脱位的检查，下列哪项在3岁患儿不宜用",[["A","弹进弹出试验"],["B","单足站立试验"],["C","“打气筒”样征"],["D","屈髋屈膝外展试验"],["E","Galeazzi征"]],"A","因此，弹入弹出实验仅适用于3个月以下的婴幼儿（A对），大于三个月的婴幼儿髋关节发育已较成熟，强行进行该实验容易造成损伤。其余方法可用于3个月以上的婴幼儿。单足站立实验（B错）：小孩站立，当健侧单腿站立，患腿上举，骨盆同侧向上升高；相反，当患肢单腿站立时，因患侧股骨头不在髋臼内，加上臀肌萎缩，髋关节不稳，致使骨盆向下垂，提示发育性髋关节脱位。先天性髋关节脱位病人股骨头可被动上下移动，称打气筒征阳性（C错）。屈髋屈膝外展试验（D错）：将小孩平卧，屈膝、屈髋90°，医师面向小孩臀部将两手抓住两膝同时外展，正常情况两膝可以放平而触及桌面。但髋脱位中一侧不能到达90°，往往是65°～70°之间，内收肌明显隆起，称做外展试验阳性提示发育性髋关节脱位。Galeazzi征（E错）：又称Allis征，患者仰卧，屈髋屈膝，两足平行置于床面，比较两膝高度，若不等高为阳性，提示较低一侧股骨或胫骨短缩，或髋关节后脱位。","","N"],["1996-N78",10,"第五节 椎管内麻醉","骶管麻醉",1996,78,"A","","关于骶椎麻醉（骶麻），下列哪项是正确的",[["A","是硬膜外麻醉"],["B","别名为鞍区阻滞"],["C","易引起马尾综合征"],["D","不易发生局麻药中毒"],["E","睾丸切除术可用这种麻醉方法"]],"A","骶椎麻醉是经骶裂孔将局麻药注入骶管腔内，阻滞骶脊神经，称骶管阻滞，是硬膜外麻醉（A对）的一种。鞍区阻滞（B错）阻滞肛门和会阴区，操作方法为病人取坐位，在L₄～₅间隙穿刺做蛛网膜下隙阻滞，以小量药液（约一般量的1/2）作缓慢注射，则局麻药仅阻滞骶尾神经，属于腰麻，而非硬膜外麻醉。马尾神经位于蛛网膜下，向两侧从椎孔发出，骶管阻滞为硬膜外麻醉，从骶骨裂孔进入的针头不会引起马尾综合征（C错）；马尾综合征是腰麻的术后并发症，因为腰麻时针头需刺入蛛网膜下隙，有可能损伤到马尾神经。骶管内有丰富的静脉丛，如穿刺时损伤血管，局麻药则吸收加快，可发生毒性反应（D错）。睾丸摘除术不宜采用骶管麻醉（E错），因为睾丸的神经支配是T₁₀，若需麻醉此处需采取第10、11胸椎间隙的硬膜外麻醉。","","N"],["1996-N79",2,"第四节 血液成分制品","红细胞制品",1996,79,"A","","一位术后贫血合并有心功能不全的老年病人，输入以何种血细胞制品最恰当",[["A","浓缩红细胞"],["B","洗涤红细胞"],["C","冰冻红细胞"],["D","少含白细胞红细胞"],["E","库存全血"]],"A","输入浓缩红细胞适应证：各种急性失血，慢性贫血及心功能不全者输血（A对）。对于贫血病人，主要以补充红细胞、提升血血红蛋白浓度为主。病人老龄，且心功能差，故在输注红细胞的同时，应保证血容量的变化较小。给予浓缩红细胞可以升高病人血细胞比容并使血容量增长不致过快，缓解循环压力，用于心功能不全者。输入洗涤红细胞（B错）适应证：对白细胞凝集素有发热反应者及肾功能不全不能耐受库存血中之高钾者。输入冰冻红细胞（C错）适应证：①同洗涤红细胞；②自身红细胞的储存。输入去白细胞的红细胞（D错）适应证：①多次输血后产生白细胞抗体者；②预期需要长期或反复输血者。输入库存全血（E错）适应证：失血量超过总血容量的30%。","","N"],["1996-N80",13,"第一节 术前准备","特殊准备",1996,80,"A","","术前准备中，下列哪项处理不正确",[["A","心力衰竭病人需控制3～4周后才施行手术"],["B","经常发作哮喘的病人，可每日三次口服地塞米松0.75mg"],["C","肝功能严重损害者，一般不宜施行任何手术"],["D","肾功能重度损害者，只要在有效的透析疗法处理下，仍能安全地耐受手术"],["E","糖尿病病人大手术前，必须将血糖控制到正常、尿糖阴性的水平，才能手术"]],"E","心力衰竭病人需控制3～4周后才施行手术是七版外科学的观点，如今的观点是：对于心脏疾病的病人，常用Goldman指数量化心源性死亡的危险性和危及生命的并发症，分数越高则发生心脏并发症和病人死亡率越高（A过去为正确答案，现已弃用）。经常发作哮喘的病人，可每日三次口服地塞米松0.75mg，地塞米松具有强大的抗炎作用，能够缓解呼吸道黏膜水肿及痉挛，有效预防哮喘的发作（B对）。肝功能严重损害者，通常伴有凝血障碍、低蛋白血症等一系列问题，手术耐受力差，死亡率极高，这种情况下，一般不宜施行任何手术（C对）。血液透析是急慢性肾功能衰竭患者肾脏替代治疗方式之一，如今血液透析已经能够代替肾的大部分功能让尿毒症终末期病人较好的存活，肾功能重度损害者，只要在有效的透析疗法处理下，才能安全地耐受手术（D对）。糖尿病病人手术时应维持血糖轻度升高状态（5.6～11.2mmol/L），以避免手术过程中血糖消耗过多导致低血糖（E错，为本题正确答案）。","","N"],["1996-N81",1,"第四节 镁、钙、磷代谢紊乱","低钙血症病因",1996,81,"A","","引起低钙血症的外科疾病中，不包括下述哪一种",[["A","急性重症胰腺炎"],["B","骨转移性癌"],["C","甲状旁腺功能低下"],["D","小肠瘘"],["E","急性肾功能衰竭"]],"B","急性重症胰腺炎（A对）患者，脂肪酶分解胰腺周围脂肪，产生大量脂肪酸，与机体中钙离子结合形成钙皂（脂肪酸钙）沉积，导致血钙降低，这也是重症胰腺炎的生化指标之一（血钙小于1.87mmol/L）。骨转移性癌（B错，为本题正确答案）患者，癌细胞浸润破坏骨组织，溶骨反应增强，骨钙释放，血钙升高。甲状旁腺功能低下（C对）患者，PTH分泌不足，PTH是调节钙磷代谢最重要的因素，有升血钙降血磷的作用，故甲状旁腺功能低下者血钙低于正常。小肠瘘（D对）患者对食物中钙的吸收存在障碍，血钙降低。急性肾功能衰竭（E对）患者，磷的排泄障碍，导致血磷升高，形成磷酸钙沉淀，导致血钙降低。","","N"],["1996-N82",12,"第四节 急性呼吸窘迫综合征","急性呼吸窘迫综合征诊断",1996,82,"A","","女，54岁，急性胰腺炎行胆囊造瘘、胰腺引流术后，行禁食、胃肠减压、输液及抗感染治疗，并吸入高浓度氧，动脉血气分析为pH7.46、PaO₂55mmHg、PaCO₂33mmHg，X线胸片示两肺有较广泛的点、片状阴影，心电图示窦性心动过速，此时提示病人可能存在",[["A","急性心力衰竭"],["B","阻塞性肺部病变"],["C","术后肺不张"],["D","肺部感染"],["E","ARDS"]],"E","54岁女性患者，急性胰腺炎（ARDS常见的危险因素之一）行胆囊造瘘、胰腺引流术。禁食、输液减压及抗感染治疗，并吸入高浓度氧（氧疗效果差），动脉血气分析为pH7.46（正常值约7.35～7.45）、PaO₂55mmHg、PaCO₂33mmHg（ARDS的典型动脉血气分析结果）。X线胸片示两肺有较广泛的点、片状阴影（提示双肺广泛渗出）。综合该患者病史、实验室检查及影像学检查，诊断考虑ARDS（E对）。急性心力衰竭（A错）X线表现为肺淤血，早期主要表现为肺门血管影增强，上肺血管影增多，部分患者可见KerleyB线。阻塞性肺部病变（B错）X线主要表现为肺纹理增粗、紊乱等非特异性改变，氧疗效果较好。术后肺不张（C错）典型X线表现为不张的肺组织透亮度降低，均匀性密度增高。肺部感染（D错）多表现为咳嗽、咳痰、发热等感染症状，部分患者X线片可见肺部浸润影。","","N"],["1996-N83",5,"第五节 脓毒症","脓毒症临床表现",1996,83,"A","","脓血症最具特征性的临床表现是",[["A","寒战后高热"],["B","白细胞计数达20～30×10⁹/L以上"],["C","可出现感染性休克"],["D","转移性脓肿"],["E","病情重而病程短"]],"D","病原菌进入血液随血液流经身体各处，可在多处形成脓肿，为脓毒症最具特征的临床表现（D对）。其余选项为脓毒症一般性的临床表现，也可出现于其他疾病的临床表现中。如寒战后高热（A错）除了出现在脓毒血症中，也可出现在溶血反应、肺炎等疾病中，主要原因是致热源作用于中枢体温调定点使其偏离正常温度上移引起；白细胞计数达20～30×10⁹/L以上（B错）不具有特异性，亦可见于白细胞增多症等。感染性休克（C错）是外科多见和治疗较困难的一类休克，可继发于以释放内毒素的革兰阴性杆菌为主的感染，如急性腹膜炎、胆道感染、绞窄性肠梗阻及泌尿系感染等，不是脓血症最具特征性的临床表现。","","N"],["1996-N84",5,"第七节 外科应用抗菌药的原则","抗菌药物合理应用的基本原则",1996,84,"A","","抗菌药物在外科疾病应用中，下列哪项叙述不正确",[["A","抗菌药物应用可减少术后并发症，增加手术安全性"],["B","严重创伤，大面积烧伤应预防性应用抗菌药物"],["C","全身情况不良的病人，应尽量选用杀菌性的抗生素治疗感染"],["D","严重感染者，在体温正常、全身情况和局部感染灶好转后3～4天即可停药，不需使用更长时间"],["E","肾功能中度减退者，首次给药后，每次应给正常剂量的1/2～1/5"]],"D","感染是最常见的术后并发症，抗菌药物在预防、控制与治疗外科感染中发挥显著作用，在增加手术安全性、减少术后并发症、扩大手术范围、提高治愈率上起了较大作用（A对）。严重创伤，大面积烧伤者失去了皮肤黏膜的屏障保护，伤口暴露于外界环境中，极易被感染，应预防性应用抗菌药物（B对）。抑菌药物的作用有赖于机体自身免疫力杀灭或排出已受到药物抑制的病原体，全身情况不良的病人，由于自身的抵抗力差，无法将病原体从身体中灭杀清除，使感染迁延不愈，应尽量选用杀菌性的抗生素直接杀灭病原菌（C对）。多数外科感染经有效抗生素治疗5～7天可控制。抗菌药物一般在体温正常、症状消退、全身及局部病灶情况好转后及时停药；严重感染如脓毒症等，疗程可适当延长以确保疗效（D错，为本题正确答案）。常用的多种抗菌药物（磺胺类、青霉素类、头孢菌素类、氨基糖苷类、四环素类），主要从尿中排出，肾功能中度减退者，首次给药后，血药浓度达到有效值，但由于排泄率下降，后续给药每次应给正常剂量的1/2～1/5即可达到有效血药浓度（E对）。","","N"],["1996-N85",7,"第一节 热力烧伤","现场急救",1996,85,"A","","烧伤现场急救时，下列哪种做法不正确",[["A","迅速脱离热源，用凉水浸泡或冲淋局部"],["B","剪去伤处衣、袜，用清洁被单覆盖"],["C","酌情使用安定、杜冷丁等药镇静止痛"],["D","呼吸道灼伤者，应在严重呼吸困难时方行切开气管、吸氧"],["E","有严重复合伤时，应先施行相应的急救处理"]],"D","现场抢救的目的是尽快去除致伤原因，脱离现场和对危及生命的情况采取救治措施。烧伤现场急救时，首先应迅速脱离热源、尽快扑灭火焰，脱去着火或沸液浸渍的衣服。一般来说，烧伤给予冷疗越早越好，有助于带走多余热量停止热损害，缓解疼痛和减少渗出，一般至冷疗停止后不再有剧痛为止（A对）。剪去伤处衣、袜，用清洁被单覆盖是为了除去着火或沸液浸渍的衣服，防止热力继续作用于创面，使创面加深，并可减少渗出和水肿（B对）。疼痛剧烈可酌情使用地西泮、哌替啶等，以防止因疼痛导致休克（C对）。对于严重复合伤患者，应遵循抢救生命第一的原则，优先处理致命伤（E对）。应保持呼吸道通畅，尤其是呼吸道灼伤者，应及时行气管切开，不要等到呼吸困难明显时才行气管切开，给予吸氧（D错，为本题正确答案）。","","N"],["1996-N86",17,"第一节 甲状腺疾病","术后呼吸困难和窒息",1996,86,"A","","甲状腺大部切除术后，呼吸困难和窒息的并发症与下列哪项因素无关",[["A","手术创伤的应激诱发危象"],["B","切口内出血压迫气管"],["C","气管软化塌陷"],["D","喉头水肿"],["E","喉返神经损伤，两侧声带麻痹"]],"A","甲状腺危象是甲亢手术后危及生命的并发症之一，是因甲状腺素过量释放引起的暴发性肾上腺素能兴奋现象，危象发生多数与术前准备不够，甲亢症状未能很好控制及手术应激有关；发生甲状腺危象（A错，为本题正确答案）时的临床表现主要为：高热、脉快，同时合并神经、循环及消化系统严重功能紊乱如烦躁、谵妄、大汗、呕吐、水泻等，但是无呼吸困难表现。甲状腺手术后，伤口引流不畅，切口内出血向后压迫气管（B对），可导致呼吸困难和窒息。手术创伤或气管插管可损伤气管黏膜，喉头黏膜水肿（D对），阻塞气道，引起呼吸困难和窒息。气管壁长期受肿大甲状腺压迫，发生软化，切除甲状腺体的大部分后软化的气管壁失去支撑而塌陷（C对），阻塞气道，引起呼吸困难和窒息。喉返神经含支配声带及喉部肌肉的运动神经纤维，双侧喉返神经损伤，则导致双侧声带麻痹（E对），喉肌瘫痪，引起失音或严重的呼吸困难，甚至窒息，需立即作气管切开。","","N"],["1996-N87",23,"第二节 腹股沟疝","腹股沟疝发病机制",1996,87,"A","","关于腹外疝的叙述，下列哪项不正确",[["A","腹外疝，斜疝嵌顿者最多"],["B","肠管壁疝发生于股管的较多"],["C","腹壁下动脉位于斜疝疝囊颈的内侧"],["D","直疝多见于老年人，极少嵌顿"],["E","最常发生切口疝的是经腹直肌切口"]],"A","虽然腹股沟斜疝远比股疝多见，但股疝发生嵌顿者比前者多出一倍（A错，为本题正确答案）。嵌顿的疝内容物是肠管壁的一部分者称为肠管壁疝，也称Richter疝，多见于股疝（B对）。腹壁下动脉位于斜疝疝囊颈的内侧（C对），位于直疝疝囊颈的外侧。直疝多见于老年人，因疝囊颈宽大，基本不对疝内容物回纳形成阻力，所以极少嵌顿（D对）。最常发生切口疝的是经腹直肌切口，切口疝最常见的病因是切口感染（E对）。","","N"],["1996-N88",26,"第三节 胃十二指肠溃疡的外科治疗","手术治疗",1996,88,"A","","胃十二指肠溃疡大出血合并下列何种情况不属必须积极进行手术治疗的范围",[["A","出血急剧，短期内出现休克"],["B","不久前曾发生过类似的大出血"],["C","伴有动脉硬化症的60岁以上老人"],["D","正在进行胃十二指肠药物治疗的病人"],["E","同时存在幽门括约肌反射性痉挛"]],"E","出血急剧，短期内出现休克（A对），此为危及病人生命的危重症，因出血量大，单纯靠补液扩容难以达到治疗效果，需积极手术治疗。不久前曾发生过类似的大出血（B对），说明患者胃部存在易发因素，即使本次出血停止仍有再出血可能，需积极手术消除再发隐患。对伴有动脉硬化症的60岁以上老人（C对），出血难以自发停止，且老年人耐受力差，故需积极手术治疗。正在进行胃十二指肠药物治疗的病人（D对），在药物的治疗下仍旧出血者，说明一般药物治疗无效，需选择手术治疗。胃溃疡出血伴瘢痕性幽门梗阻是手术治疗的指征，但对于幽门括约肌反射性痉挛（E错，为本题正确答案）导致的幽门梗阻，通过胃肠减压和引流，高渗盐水洗胃及补充液体及电解质等非手术治疗，多数病人的梗阻可以自行缓解，因而不属于外科手术适应证。","","N"],["1996-N89",27,"第四节 肠梗阻","是单纯性还是绞窄性梗阻",1996,89,"A","","急性持续性腹痛，阵发性加剧并伴休克，最大可能是",[["A","输尿管结石肾绞痛"],["B","绞窄性肠梗阻"],["C","急性阑尾炎"],["D","溃疡病急性发作"],["E","急性胆囊炎"]],"B","输尿管结石肾绞痛（A错），为阵发性剧烈绞痛，病人常辗转反侧，可向腹股沟或会阴部放射，有时可见血尿，但通常不伴有休克；急性阑尾炎（C错）的疼痛特点为转移性右下腹痛，且右下腹出现固定压痛，通常无阵发加剧表现，且阑尾周围大网膜丰富，穿孔后也少形成全腹腹膜炎和休克。溃疡病急性发作（D错）表现为上腹疼痛和轻压痛，通常不会出现休克，大出血时可出现休克，但是伴随呕血等症状。急性胆囊炎（E错）起病常在进油腻食物后，右上腹部阵发性剧烈绞痛，放射至右肩及右背部，也罕有休克表现。绞窄性肠梗阻的腹痛急发，初始即为持续性剧烈疼痛（因肠道血运降低，局部代谢产物淤积，刺激神经末梢），可有阵发性加剧（梗阻上端肠管间歇性痉挛性收缩），病情发展迅速，肠管缺血坏死、穿孔，早期出现休克（B对），抗休克治疗后改善不明显。","","N"],["1996-N90",29,"第七节 直肠癌","直肠癌病因和病理",1996,90,"A","","关于直肠癌，哪项是错误的",[["A","约占大肠癌的60%左右"],["B","常见部位为直肠壶腹部"],["C","大体类型以溃疡型多见"],["D","组织学分型中粘液癌多见，约占50%以上"],["E","淋巴转移是主要扩散途径"]],"D","直肠癌的组织学分型中，黏液腺癌占10%～20%（D错，为本题正确答案），最常见的为管状腺癌和乳头状腺癌，占75%～85%。国人直肠癌发生率约占大肠癌的60%（A对）。直肠癌常见部位为直肠壶腹部（B对），约占直肠癌的2/3。直肠癌大体类型可分为溃疡型、隆起型、浸润型，其中以溃疡型多见（C对），约占50%。直肠癌常见扩散途径包括：直接浸润、淋巴转移、血行转移、种植转移，其中淋巴转移是主要的扩散途径（E对）。","","N"],["1996-N91",32,"第四节 胆石症","胆囊结石概述",1996,91,"A","","关于胆石症，哪项是正确的",[["A","肝内胆管结石，右肝管多于左肝管"],["B","胆囊结石多为胆固醇结石或混合结石"],["C","胆色素结石的剖面，中心是放射状而外周呈层状"],["D","胆道蛔虫所致的结石多为混合结石"],["E","肝外胆管结石占全部胆石的10%，多位于肝总管或肝总管上段"]],"B","胆石症包括肝内胆管结石和肝外胆管结石，肝内胆管结石以左外叶和右后叶多见（A错）。胆囊结石大多数为多发，多为胆固醇类结石，在感染情况下可产生混合结石（B对）。胆色素结石形状不定，呈块状或呈泥样，也可为小砂砾样，较大结石的剖面可见年轮样层状结构（C错）。胆固醇结石包括纯胆固醇结石和混合性结石，后者剖面中心呈放射状而外周呈层状。胆道感染和胆汁淤滞是胆色素结石形成的主要原因，胆道蛔虫症是胆道感染的重要原因，蛔虫残体又可作为胆结石核心，在胆色素结石（D错）形成中起重要作用。肝外胆管结石是指发生在肝总管及胆总管内的结石，最多见的是胆总管结石，肝外胆管结石占全部胆石的20%～30%，胆汁排泄可带动结石下行，因而结石多位于肝总管或胆总管下段（E错）。","","N"],["1996-N92",33,"第四节 胰腺癌和壶腹周围癌","壶腹周围癌诊断",1996,92,"A","","壶腹周围癌的预后比胰头癌好，其原因是",[["A","肿瘤的恶性程度低"],["B","肿瘤居于十二指肠腔内，不易向周围侵犯"],["C","黄疸出现较早，较易早就医，早发现，早治疗"],["D","肿瘤居于肠腔内，易发生坏死脱落"],["E","不易向淋巴结及肝脏转移"]],"C","胰腺癌早期无特异性症状，多数仅表现为上腹部不适或隐痛、钝痛和胀痛等；多数病人出现黄疸时方才引起警觉而就医，已属中晚期，错过了最佳的治疗时机。而壶腹周围癌生长于十二指肠肝胰壶腹处，此为胆汁和胰液排出的通道。即使肿块很小，亦可阻碍胆汁的排泄，早期即出现阻塞性黄疸，患者就医较早，早发现，早治疗（C对），因而预后较好。","","N"],["1996-N111",53,"第二节 腰椎退行性疾病","感觉异常",1996,111,"B","","𧿹趾背伸乏力或不能，小腿前侧和足内侧皮肤感觉改变，出现在",[["A","腰2～3间盘后外侧突出"],["B","腰3～4间盘后外侧突出"],["C","腰4～5间盘后外侧突出"],["D","腰5骶1间盘后外侧突出"],["E","骶1～2间盘后外侧突出"]],"C","腰₂～₃间盘后外侧突出（A错）压迫腰₃神经，表现为股骨内髁感觉障碍，伸膝无力，膝反射减弱或消失。腰₃～₄间盘后外侧突出（B错）压迫腰₄神经，表现为小腿前内侧及足内侧感觉障碍、足背背伸障碍。腰₄～₅间盘后外侧突出（C对）压迫腰₅神经，表现为趾背伸乏力或不能，小腿前侧和足内侧皮肤感觉改变。腰₅骶₁间盘后外侧突出（D错）压迫骶₁神经，表现为小腿后外侧及外踝、足外侧感觉障碍，𧿹趾及足跖屈无力，踝反射下降。","","N"],["1996-N112",53,"第二节 腰椎退行性疾病","感觉异常",1996,112,"B","","踇趾跖屈乏力或不能，外踝部和足外侧皮肤感觉改变，出现在",[["A","腰2～3间盘后外侧突出"],["B","腰3～4间盘后外侧突出"],["C","腰4～5间盘后外侧突出"],["D","腰5～骶1间盘后外侧突出"],["E","骶1～2间盘后外侧突出"]],"D","腰₂～₃间盘后外侧突出（A错）压迫腰₃神经，表现为股骨内髁感觉障碍，伸膝无力，膝反射减弱或消失。腰₃～₄间盘后外侧突出（B错）压迫腰₄神经，表现为小腿前内侧及膝前感觉障碍，伸膝无力，膝反射减弱或消失。腰₄～₅间盘后外侧突出（C错）压迫腰₅神经，表现为小腿前外侧及足背内侧感觉障碍，足踇趾背伸乏力或不能。腰₅骶₁间盘后外侧突出（D对）压迫骶₁神经，表现为踇趾跖屈乏力或不能，外踝部和足外侧皮肤感觉改变。","","N"],["1996-N113",1,"第二节 水、钠代谢紊乱","低渗性脱水临床表现",1996,113,"B","","低渗性缺水引起体液容量的变化为",[["A","以血液浓缩为主"],["B","只有组织间液减少"],["C","血浆、组织间液、细胞内液都减少，以血浆减少为主"],["D","血浆、组织间液、细胞内液都减少，以细胞内液减少为主"],["E","血浆、组织间液、细胞内液都减少，以组织间液减少为主"]],"E","低渗性缺水失钠多于失水，细胞外液渗透压降低，抑制抗利尿激素分泌，水重吸收减少，尿量增多。结果细胞外液更加减少，为补偿血容量，组织间液进入血液循环，因此低渗性缺水的容量变化是血浆、组织间液、细胞内液都减少，但以组织间液减少为主（E对）；等渗性缺水水钠等比例丢失，由于丧失的液体为等渗液，基本上不改变细胞外液的渗透压，因此等渗性缺水的容量变化是血浆、组织间液、细胞内液都减少，血浆和组织间液等比例丢失（也称血液浓缩）（A错）；高渗性缺水时失水多于失钠，由于细胞外液渗透压高于正常，引起细胞内液流向细胞外，因此高渗性缺水的容量变化是血浆、组织间液、细胞内液都减少，但以细胞内液减少为主（D错）。","","N"],["1996-N114",1,"第二节 水、钠代谢紊乱","等渗性脱水临床表现",1996,114,"B","","等渗性缺水引起体液容量的变化为",[["A","以血液浓缩为主"],["B","只有组织间液减少"],["C","血浆、组织间液、细胞内液都减少，以血浆减少为主"],["D","血浆、组织间液、细胞内液都减少，以细胞内液减少为主"],["E","血浆、组织间液、细胞内液都减少，以组织间液减少为主"]],"A","等渗性缺水水钠等比例丢失，由于丧失的液体为等渗液，基本上不改变细胞外液的渗透压，因此等渗性缺水的容量变化是血浆、组织间液、细胞内液都减少，血浆和组织间液等比例丢失（也称血液浓缩）（A对）；低渗性缺水失钠多于失水，细胞外液渗透压降低，抑制抗利尿激素分泌，水重吸收减少，尿量增多。结果细胞外液更加减少，为补偿血容量，组织间液进入血液循环，因此低渗性缺水的容量变化是血浆、组织间液、细胞内液都减少，但以组织间液减少为主（E错）；高渗性缺水时失水多于失钠，由于细胞外液渗透压高于正常，引起细胞内液流向细胞外，因此高渗性缺水的容量变化是血浆、组织间液、细胞内液都减少，但以细胞内液减少为主（D错）。","","N"],["1996-N115",26,"第二节 胃癌及其他胃肿瘤","早期胃癌",1996,115,"C","","癌灶直径≦5mm",[["A","早期胃癌"],["B","小胃癌"],["C","微小胃癌"],["D","进展期胃癌"],["E","晚期胃癌"]],"C","胃癌的大体分型需掌握。早期胃癌指病变局限于黏膜或黏膜下层，而无论其是否有淋巴结转移。其中，直径≦5mm者为微小胃癌（C对），直径在5～10mm之间者为小胃癌。进展期胃癌指病变浸润深度超过黏膜下层，可分为息肉型（Ⅰ型）、溃疡局限型（Ⅱ型）、溃疡浸润型（Ⅲ型）、弥漫浸润型（Ⅳ型）。","","N"],["1996-N116",26,"第二节 胃癌及其他胃肿瘤","早期胃癌",1996,116,"C","","局限于黏膜或黏膜下层的胃癌",[["A","早期胃癌"],["B","小胃癌"],["C","微小胃癌"],["D","进展期胃癌"],["E","晚期胃癌"]],"A","胃癌的大体分型需掌握。早期胃癌（A对）指病变局限于黏膜或黏膜下层，而无论其是否有淋巴结转移。其中，直径≤5mm者为微小胃癌（C错），直径在5～10mm之间者为小胃癌。进展期胃癌（D错）指病变浸润深度超过黏膜下层，可分为息肉型（Ⅰ型）、溃疡局限型（Ⅱ型）、溃疡浸润型（Ⅲ型）、弥漫浸润型（Ⅳ型）。","","N"],["1996-N135",44,"第一节 骨折的定义、成因、分类及移位","疲劳骨折",1996,135,"C","","疲劳骨折可发生在",[["A","腓骨干下1/3"],["B","胫骨干下1/3"],["C","两者均可"],["D","两者均不可"]],"A","疲劳骨折指长期、反复、轻微的直接或间接外力导致的肢体某一特定部位的骨折，好发于第2、3跖骨及腓骨下1/3（A对）骨干骨折，常由远距离行军导致。胫骨下1/3（B错）骨折导致胫骨远端获得的血供骤减，易致骨折延迟愈合或不愈合。","","N"],["1996-N136",44,"第五节 影响骨折愈合的因素","骨折部位的血液供应",1996,136,"C","","骨折迟延愈合可发生在",[["A","腓骨干下1/3"],["B","胫骨干下1/3"],["C","两者均可"],["D","两者均不可"]],"B","对于胫骨骨折，笔者作如下总结：①腘动脉分胫前、胫后动脉，胫后动脉穿过比目鱼肌腱弓向下行走，此血管固定，胫骨干上1/3骨折易损伤该动脉，引起下肢严重缺血；②在胫骨干中1/3，小腿深筋膜与胫腓骨及骨间膜形成四个界限清楚的筋膜室，由于骨折后骨髓腔出血，或肌肉损伤出血或血管损伤出血，均可引起骨筋膜室综合征；③胫骨干下1/3（B对）骨折易损伤滋养动脉，导致胫骨下段骨折远端血液供应减弱，引起骨折的延迟愈合。","","N"],["1996-N137",18,"第三节 乳腺良性疾病","乳腺囊性增生病临床表现",1996,137,"C","","乳腺囊性增生病可有",[["A","乳头血性溢液"],["B","乳头黄绿色或浆液性溢液"],["C","两者均有"],["D","两者均无"]],"C","乳头溢液的性质对于判断疾病性质有帮助，常见液体性质与疾病需掌握。乳腺囊性增生病可有乳头溢液，表现为鲜红色血性（A对）、棕褐色、黄色或黄绿色、浆液性无色溢液（B对）等。根据最新版教材，已删去血性溢液，故本题应选B。","","N"],["1996-N138",18,"第三节 乳腺良性疾病","导管内乳头状瘤临床表现",1996,138,"C","","乳管内乳头状瘤可有",[["A","乳头血性溢液"],["B","乳头黄绿色或浆液性溢液"],["C","两者均有"],["D","两者均无"]],"A","乳头溢液的性质对于判断疾病性质有帮助，常见的溢液性质与疾病需掌握。乳管内乳头状瘤可有鲜红色血性溢液，若乳管阻塞可有乳头棕褐色溢液（A对）。","","N"],["1996-N157",48,"第一节 脊柱骨折","脊柱骨折分类",1996,157,"X","","脊柱骨折脱位引起脊髓损伤，可发生在",[["A","颈椎"],["B","胸椎"],["C","下腰椎"],["D","骶椎"]],"AB","由于成人脊髓和椎管的长度不一致，故脊髓各个节段与相应椎骨的高度并不完全对应。脊髓由延髓下行自C₁-L₁节为脊髓，下缘平L₁，其末端为圆锥，其下为马尾。颈椎（A对）及胸椎（B对）位置较高，其后的椎管内有脊髓存在，引起其骨折可并发脊髓损伤。下腰椎（C错）和骶椎（D错）位于L₁平面之下，因此其损伤不会损伤脊髓。","","N"],["1996-N158",10,"第四节 局部麻醉","吸收、分布、生物转化和清除",1996,158,"X","","关于局麻药，下述哪些是正确的",[["A","局麻药阻滞作用部位主要在细胞膜和轴浆内"],["B","酯类局麻药主要在肝内代谢"],["C","局麻药之BH⁺离子部分，阻塞Na⁺通道产生完全阻滞作用"],["D","酰胺类局麻药主要在肝外代谢"]],"AC","局麻药的水溶液含有未解离的碱基（B）和已解离的阳离子（BH⁺）两部分。碱基部分具有亲脂性，可以穿透细胞膜，作用于神经膜，与神经膜受体结合，抑制神经膜钠通道对钠离子的通透性，致使神经膜去极化速度减慢，去极化相延长，神经膜电位不能达到阈电位，破坏神经膜动作电位的传导，从而达到神经阻滞的作用。因此，局麻药阻滞作用部位主要在细胞膜和轴浆内（A对）。局麻药以非解离型（碱基B）进入神经细胞（脂溶性，透过细胞膜），再解离为解离型（阳离子BH⁺）作用在神经细胞膜内表面，与钠通道特异性结合位点结合产生钠通道阻断作用（C对）。酰胺类局麻药在肝内被线粒体酶所水解（D错）；酯类局麻药主要被血浆假性胆碱酯酶水解（B错）。","","N"],["1996-N159",24,"第二节 常见内脏损伤的特征和处理","肝损伤手术治疗",1996,159,"X","","腹部损伤手术治疗的处理，哪些是正确的",[["A","依受伤的部位选用就近切口或右侧经腹直肌切口探查"],["B","一般应先探查胃肠等空腔脏器及盆腔，然后探查肝、脾等实质性脏器"],["C","探查过程中，发现一处损伤就应立即修复一处，避免遗漏"],["D","肝破裂手术后，在肝周或创面应留置引流物"]],"D","由于外伤造成的腹部伤口为污染伤口，不应在此处操作，以防将污染扩散；且外伤形成的伤口有时可能位置较偏，操作性差（A错）。肝、脾、胰、肾等实质器官损伤主要表现为腹腔内（或腹膜后）出血及失血性休克；但对于胃肠道、胆囊等空腔脏器破裂，主要表现为弥漫性腹膜炎。故对于腹腔脏器的探查先探查实质性脏器，再探查胃肠等空腔脏器及盆腔（B错），因为失血性休克需快速抢救，否则易致命。探查过程中若发现一处损伤就立即修补一处（C错），则有可能使严重的损伤救治被延迟，从而使病情恶化，正确的做法是在完整探查和充分评估后，按照严重程度进行救治。肝破裂手术后，无论采用何种手术方式，在肝周或创面应留置引流物（D对）以引流流出的血液和胆汁，促进愈合。原X型题为不定项选择题，可有1～4个正确选项。","","N"],["1996-N160",23,"第二节 腹股沟疝","腹股沟疝发病机制",1996,160,"X","","腹股沟疝的发生，主要与下列哪些解剖因素有关",[["A","腹膜鞘状突未闭"],["B","精索（或圆韧带）由腹股沟管通过"],["C","腹内斜肌的弓状下缘发育不全或位置偏高"],["D","腹外斜肌在腹股沟区已形成腱膜"]],"ABC","腹膜鞘状突未闭（A对），鞘突就成为先天性斜疝的疝囊。腹腔内容物，尤其是小肠，易经此处突向阴囊。腹内斜肌的弓状下缘发育不全或位置偏高（C对），可降低腹股沟管前壁的强度，腹腔内容物易经海氏三角向前方突出，形成腹股沟直疝。精索（或圆韧带）由腹股沟管通过（B对）造成腹壁强度降低，是引起腹股沟疝的解剖学基础。腹外斜肌在腹股沟区已形成腱膜（D错）与腹股沟疝的发生无关。","","N"],["1997-N75",55,"第四节 膝关节结核","膝关节结核实验室检查",1997,75,"A","","女性，30岁，背痛1月余，劳累后加重，有消瘦、乏力和盗汗。检查胸椎7～8有压痛及叩痛。此时哪项检查不需要",[["A","血常规及血沉"],["B","胸椎正侧位X线片"],["C","胸大片"],["D","结核菌素试验"],["E","同位素骨扫描"]],"E","30岁女性患者，背痛1月余，劳累后加重，有消瘦、乏力和盗汗（结核中毒症状的表现）。检查胸椎7～8有压痛及叩痛（提示可能存在脊柱结核）。综合该患者的病史及体查，须考虑脊柱结核的诊断。胸椎正侧位片（B对）可以观察存在压痛和叩痛的脊椎节段的骨病变情况。胸大片（C对）用于判断病人是否存在肺结核病变，因为约80%骨与关节结核的原发灶在肺和胸膜。血常规及血沉（A对）、结核菌素试验（D对）可协助诊断脊柱结核。同位素骨扫描（E错，为本题正确答案）主要用于原发性及转移性骨肿瘤的诊断，对脊柱结核的诊断意义不大。","","N"],["1997-N76",47,"第一节 髋关节脱位","髋关节后脱位临床表现和诊断",1997,76,"A","","男性，25岁，车祸伤及右髋部，右髋痛，不敢活动右下肢，右下肢呈屈曲、内收、内旋和短缩畸形。最可能的诊断是",[["A","股骨颈骨折"],["B","股骨转子骨折"],["C","髋关节后脱位"],["D","髋关节前脱位"],["E","股内收肌扭伤"]],"C","25岁男性，右髋部外伤史。右髋痛，右下肢活动受限，右下肢呈屈曲、内收、内旋和短缩畸形，诊断考虑髋关节后脱位（C对）。股骨颈骨折（A错）表现为患肢缩短、髋关节疼痛、肿胀、活动受限，髋关节屈曲内收外旋畸形。股骨转子间骨折（B错）表现为患肢缩短、髋关节疼痛、肿胀、活动受限，髋关节外旋明显，可达90°。髋关节前脱位（D错）表现为患肢增长、髋关节疼痛、肿胀、活动受限，髋关节呈屈曲、外展、外旋畸形。股内收肌扭伤（E错）表现为患侧大腿上部疼痛，局部压痛明显，大腿内收，外展受限，患侧髋、膝关节呈稍屈外旋位。","","N"],["1997-N77",44,"第三节 骨折的并发症","骨折的并发症概述",1997,77,"A","","下列哪项不是骨折的并发症",[["A","休克"],["B","关节强直"],["C","脊髓损伤"],["D","损伤性骨化（骨化性肌炎）"],["E","脂肪栓塞"]],"B","关节强直（B错，为本题正确答案）是人体关节在病理状态下关节功能受限、发生纤维粘连所导致的屈伸不利，僵硬、发挺的一种状态，常由关节炎或骨结核引起。注意区分关节僵硬与关节强直。关节僵硬是由于患肢长期固定或未进行功能锻炼，静脉和淋巴回流不畅，组织中浆液纤维性渗出和纤维蛋白沉积，使得关节内、外组织发生纤维粘连，并伴有关节囊和周围肌肉挛缩，致使关节活动障碍。骨折的早期并发症包括休克（A对）、脂肪栓塞（E对）综合征、重要内脏器官损伤、重要周围组织损伤（重要血管损伤、周围神经损伤、脊髓损伤（C对））、骨筋膜室综合征。骨折的晚期并发症包括坠积性肺炎、压疮、下肢深静脉血栓形成、感染、损伤性骨化（D对）、创伤性关节炎、关节僵硬、急性骨萎缩、缺血性骨坏死、缺血性肌挛缩。","","N"],["1997-N78",10,"第五节 椎管内麻醉","麻醉平面与阻滞作用",1997,78,"A","","脊椎麻醉时，哪一种神经功能最后被阻断",[["A","随意运动"],["B","温度觉"],["C","深部感觉（本体感觉）"],["D","植物神经功能"],["E","痛觉"]],"C","神经纤维被阻滞的顺序依次为：自主神经（C类纤维传导的痛觉及交感神经）→感觉神经（Aδ纤维传导的温痛觉、Aβ纤维传导的触压觉）→运动神经（Aα纤维传导的躯体运动）→Aγ纤维传导的固有感觉（深部感觉和位置觉）。不难得出，最后被阻断的是深部感觉（本体感觉）（C对）。","","N"],["1997-N79",13,"第二节 术后处理","体位",1997,79,"A","","急性化脓性腹膜炎病人术后采取半卧位的目的，哪项是错误的",[["A","减少毒素吸收，防止感染性休克发生"],["B","增加肺活量，减少肺部并发症"],["C","渗出物流至盆腔，吸收快，避免形成盆腔脓肿"],["D","腹肌松弛，减少切口疼痛"],["E","减少膈下脓肿发生的机会"]],"C","手术后，应根据麻醉及病人的全身状况、术式、疾病的性质等选择体位，使病人处于既舒服又便于活动的体位。急性化脓性腹膜炎病人术后采取半卧位有以下优点：①使膈肌下移，有利于肺部通气的进行，达到增加肺活量，减少肺部并发症（B对）的目的；②使腹肌松弛，有利于切口愈合和减轻疼痛（D对）；③炎症积液可因体位引流至盆腔积聚，避免了腹腔其他部位的脓肿形成（E对），但相对增加了盆腔脓肿的形成几率（C错，为本题正确答案）；④由于盆腔的吸收能力差，对于各类毒素的吸收较少，因而可减少包括感染性休克在内的各类感染中毒症状发生（A对）。","","N"],["1997-N80",18,"第四节 乳腺癌","乳腺癌临床表现与转移途径",1997,80,"A","","下列有关乳腺癌的描述，哪项是错误的",[["A","乳房外上象限发生率最高，接近50%"],["B","骨转移的主要部位是肋骨"],["C","“橘皮征”是皮内和皮下淋巴管被癌细胞堵塞所致"],["D","Paget病的原发灶在乳头区的大乳管内"],["E","治疗方针应是尽早手术，辅以放、化疗等"]],"B","癌细胞直接侵犯静脉引起远处转移，最常见的为骨、肺、肝；由于乳腺组织层次厚，一般通过直接侵犯累及肋骨者少，而由于椎旁静脉系的存在，乳腺癌的骨转移最常见于椎体、骨盆及股骨（B错，为本题正确答案）。乳腺癌肿块发生于乳房外上象限者较多，接近50%（A对）。“橘皮样改变”是由于癌细胞浸润浅表组织淋巴管，使得淋巴管阻塞，淋巴液回流障碍，进而造成真皮水肿，由于皮肤毛囊与皮下组织粘连较紧密，在真皮水肿时毛囊处即会形成许多点状小孔，形成了凹凸不平的橘皮样改变（C对）。Paget病又称乳头湿疹样乳腺癌，是一种特殊类型的乳腺癌，原发灶在乳头区的大乳管内（D对），向上侵犯乳头，向下侵犯乳腺实质。虽然对于乳腺癌的治疗，近来提出了内分泌治疗、靶向治疗等新方法，但是对于大多数乳腺癌，手术仍旧是首选的治疗方案，术后配合放化疗和其他手段治疗可提高生存率（E对）。","","N"],["1997-N81",24,"第一节 腹部损伤概述","诊断性腹腔穿刺术",1997,81,"A","","诊断性腹腔穿刺和腹腔灌洗术，在诊断腹部损伤时，其阳性率可达",[["A","90%"],["B","80%"],["C","70%"],["D","60%"],["E","50%"]],"A","诊断穿刺适用于怀疑有腹腔内出血或空腔脏器穿孔者，方法简便、快速、经济、安全，准确率可达到90%（A对）以上；只要操作正确，阳性结果有肯定的诊断价值，阴性结果则不能完全排除内脏伤，必要时可变换部位再行穿刺，或间隔一段时间后重复检查。诊断性腹腔灌洗早期诊断阳性率比腹腔穿刺高，还能进行连续观察而不必多处反复穿刺，尤其对诊断空腔脏器破裂很有价值。","","N"],["1997-N82",6,"第四节 治疗原则","污染伤口的处理",1997,82,"A","","面颊部开放性损伤后12小时，局部的处理宜",[["A","按感染伤口对待，只换药，不清创"],["B","清创后不缝合"],["C","清创后延期缝合"],["D","清创后一期缝合"],["E","换药观察后，延期缝合"]],"D","正常情况下，伤后应尽早清创后一期缝合，最好在伤后6～8小时内进行。头面部伤口由于局部血运良好，抗感染能力强，且伤口多位于浅表部位，污染不易扩散至深层组织，限时可延长至10小时，甚至更长，本例面颊部开放性损伤后12小时，争取清创后一期缝合，这也有利于减少疤痕的产生（D对）。污染严重或一般伤口伤后超过8～12小时，但尚未明显感染的伤口（面颊部除外），应该清创后延迟缝合。感染伤口可放置引流，定期换药。","","N"],["1997-N83",0,"第一节 手术器械、物品的灭菌、消毒法","高压蒸汽灭菌法",1997,83,"A","","下列哪种方法不属于灭菌法",[["A","高压蒸气法"],["B","甲醛蒸气熏蒸法"],["C","煮沸一小时"],["D","火烧法"],["E","电离辐射法"]],"B","灭菌是指杀灭一切活的微生物，包括芽孢。消毒则是指杀灭病原微生物和其他有害微生物，但并不要求清除和杀灭所有微生物。高压蒸气灭菌法（A对）是目前医院内应用最多的灭菌法。低温甲醛蒸气法（B对），有效气体浓度3～11mg/L，灭菌温度为50～80℃，灭菌时间30～60分钟。将水煮沸15～20min，普通细菌即可被杀死。煮沸一小时（C对）可杀灭包括芽孢在内的一切微生物，达到灭菌效果。火烧法（D对）又称干热灭菌法，因火焰温度极高，一般均在200℃以上，可达到灭菌效果。电离辐射法（E对）属于工业化灭菌法，主要应用于无菌医疗耗材和某些药品，常用⁶⁰Co释放的γ射线或者加速器产生的电子射线起到灭菌作用。此题不严谨，按照十版教材没有正确选项，原答案选B，做题时应掌握知识点而不是题目本身。","","N"],["1997-N84",5,"第六节 有芽胞厌氧菌感染","破伤风预防",1997,84,"A","","三年前曾行破伤风自动免疫者，受伤后应作下列哪项处理即可预防破伤风",[["A","需再次注射破伤风类毒素0.5ml"],["B","需再次注射破伤风类毒素5ml"],["C","需再次注射破伤风抗毒素1500国际单位"],["D","需注射人体破伤风免疫球蛋白3000国际单位"],["E","严密观察，暂不注射"]],"A","破伤风是可以预防的疾患，预防措施包括正确处理伤口，注射破伤风类毒素主动免疫，以及在伤后采用被动免疫预防发病。三年前曾行破伤风自动免疫者，属于已经注射破伤风类毒素主动免疫者，仅需在伤后肌注0.5ml类毒素即可形成有效的免疫抗体（A对），不需注射破伤风抗毒素，但按照最新指南，类毒素注射五年内受伤后无需再次注射类毒素。","","N"],["1997-N85",7,"第一节 热力烧伤","深Ⅱ度烧伤",1997,85,"A","","深Ⅱ度烧伤，若无感染等并发症，通常愈合时间为",[["A","2～3日"],["B","1周"],["C","2周"],["D","3～4周"],["E","5周以上"]],"D","Ⅰ°烧伤：再生能力强，3～7天脱屑痊愈，短期内可有色素沉着；浅Ⅱ°烧伤：创面可于1～2周内愈合，一般不留瘢痕，但多数有色度沉着；深Ⅱ°烧伤：创面修复可赖其上皮增殖形成上皮小岛，如不感染，可融合修复，需时3～4周（D对）；Ⅲ°烧伤：又称焦痂型烧伤，由于皮肤及其附件全部被毁，3～4周后焦痂脱落。","","N"],["1997-N86",27,"第四节 肠梗阻","是单纯性还是绞窄性梗阻",1997,86,"A","","绞窄性肠梗阻的临床表现，哪项是错误的",[["A","出现腹膜刺激征"],["B","持续剧痛无缓解"],["C","呕吐血性或棕褐色液体"],["D","肠鸣音消失"],["E","X射线显示膨胀突出的孤立肠袢随时间改变位置"]],"E","绞窄性肠梗阻由于有肠管缺血，导致局部代谢产物淤积，刺激肠壁神经，引起持续剧痛无缓解（B对）；绞窄性肠梗阻可较早出现肠壁渗出、坏死、穿孔，腹腔内可发生感染、炎症，可出现腹膜刺激征（A对）；绞窄性肠梗阻可有肠系膜血管血运障碍，肠管壁血管损伤，肠腔内出血，呕吐物可为咖啡色、棕色的含血物，或出现呕血（C对）；绞窄性肠梗阻的肠管极易缺血坏死，不再有蠕动，故肠鸣音消失（D对），X射线显示膨胀突出的孤立肠袢位置固定，不随时间变化（E错，为本题正确答案）。","","N"],["1997-N87",28,"第二节 急性阑尾炎","腹腔脓肿",1997,87,"A","","急性阑尾炎发病已四天，腹痛稍减轻，但仍发烧，右下腹可触及有压痛的肿块，应",[["A","立即手术，切除阑尾"],["B","立即手术，切除肿块"],["C","立即手术，腹腔引流"],["D","暂不手术，用广谱抗菌素治疗"],["E","用广谱抗菌素治疗，不需手术"]],"D","急性阑尾炎发病已四天，腹痛稍减轻，但仍发烧，右下腹可触及有压痛的肿块，应诊断为阑尾周围脓肿，当急性阑尾炎已被延误诊断超过48小时，形成炎性肿块，表明病变局限，病情已有改善，应暂不手术，促进肿块吸收，再考虑择期切除阑尾，盲目手术会使炎症扩散。给予广谱抗生素治疗，可促进炎症的局限和吸收（D对）。立即手术、切除阑尾（A错）是急性阑尾炎的治疗原则。立即手术、切除肿块（B错），立即手术、腹腔引流（C错）及用广谱抗菌素治疗、不需手术（E错）都不是阑尾脓肿的首选治疗。","","N"],["1997-N88",33,"第四节 胰腺癌和壶腹周围癌","胰腺癌诊断",1997,88,"A","","男性，50岁，上腹不适，食欲不振三个月。一个月来出现黄疸进行性加重，有体重减轻，全身明显黄染，肝未触及，深吸气时可触到肿大胆囊底部，无触痛。化验血胆红素15mg/dl，尿检胆红素阳性。最可能是",[["A","肝炎"],["B","胆石症"],["C","胰头癌"],["D","慢性胰腺炎"],["E","肝癌"]],"C","50岁男性患者，上腹不适，食欲不振三个月（胰头癌常见消化道症状）。进行性黄疸1月，全身明显黄染（提示胆道梗阻），有体重减轻（提示慢性消耗性疾病可能）。肝未触及，深吸气时可触到肿大胆囊底部，无触痛（Courvoisier征阳性）。化验血胆红素15mg/dl（正常高值为1mg/dl），尿检胆红素阳性，提示梗阻性黄疸。综合该患者病史、体查及实验室检查，诊断考虑胰头癌（C对）。肝炎（A错）可引起肝细胞性黄疸，一般不出现胆囊肿大。胆石症（十版外科学P468）（B错）一般表现为阵发性上腹部剧烈疼痛，黄疸为波动性，并非进行性加重。慢性胰腺炎（十版外科学P491）（D错）典型临床表现为腹痛、体重下降、糖尿病、脂肪泻，仅少数病人可因胰头纤维增生，可压迫胆总管而出现黄疸。肝癌（十版外科学P448）（E错）引起的黄疸说明癌肿发展已压迫胆道，此时癌肿巨大，可在肋弓下缘触及体积增大的肝脏，而病人腹部触诊时肝未触及，故排除。","","N"],["1997-N89",32,"第二节 胆道疾病影像学检查","经皮肝穿刺胆管造影",1997,89,"A","","经皮肝穿胆道造影（PTC）的描述，哪项是错误的",[["A","PTC是一种胆管直接造影方法"],["B","肝内胆管扩张时，成功率可达90%左右"],["C","本检查不适合于黄疸较重、肝功能差的病人检查"],["D","PTC是一项损伤性检查技术"],["E","PTC可能会出现胆汁外漏、出血等合并症"]],"C","PTC是在X线电视或超声监视下，经皮穿入肝内胆管，再将造影剂直接注入胆道而使肝内外胆管迅速显影，是一种胆管直接造影方法（A对）。PTC自肝内小胆管开始，逐渐显示整个胆管的情况，通过测量胆管直径，能够准确反映胆管是否扩张，成功率可达90%左右（B对）。PTC是一项损伤性检查技术（D对），可能发生胆汁漏、出血、胆道感染等并发症（E对），故术前应检查凝血功能及注射维生素K 2～3天；必要时应用抗生素，特别是感染者；并做好剖腹探查的准备，以及时处理胆汁性腹膜炎，出血等紧急并发症；另外可通过造影管行胆管引流（PTCD）或置放胆管内支架用作治疗。PTC采用直接胆道注射显影剂，不受肝功能和血胆红素浓度的影响，故适用于黄疸较重、肝功能差的病人检查（C错，为本题正确答案）。","","N"],["1997-N90",26,"","",1997,90,"A","","下列哪项不是高选择性迷走神经切断术的优点",[["A","不需附加引流手术"],["B","消除神经性胃酸分泌，不引起胃滞留"],["C","保留了幽门括约肌功能"],["D","保留了正常的胃容积"],["E","手术效果稳定，术后无溃疡复发率"]],"E","高选择性迷走神经切断术的手术要点是切断支配胃近端、胃底、胃体壁细胞的迷走神经分支，以消除神经性胃酸分泌，保留了支配胃窦部的鸦爪支（控制胃窦运动和幽门排空）及支配远端肠道的迷走神经，因此保留了幽门括约肌的功能（C对）、不会发生胃潴留（B对），不需附加引流手术（A对），保留了胃的正常容积（D对）。高选择性迷走神经切断术后的复发率平均在10%～17%（E错，为本题正确答案），可能与迷走神经解剖变异、手术切除不彻底及迷走神经再生有关。","","N"],["1997-N91",29,"第十节 肛周脓肿","肛周脓肿概述",1997,91,"A","","最多见的直肠肛管周围脓肿是",[["A","肛门周围脓肿"],["B","坐骨直肠窝脓肿"],["C","骨盆直肠窝脓肿"],["D","直肠后间隙脓肿"],["E","直肠粘膜下脓肿"]],"A","肛管直肠周围软组织内或其周围间隙内发生急性化脓性感染，并形成脓肿，称肛管直肠周围脓肿。肛门周围脓肿（A对）即肛周皮下脓肿，是肛管直肠周围脓肿最常见类型，约占48%（七版黄家驷外科学P1604）。","","N"],["1997-N92",29,"第十一节 肛瘘","按瘘管与括约肌的关系分类",1997,92,"A","","临床上最常见的肛瘘类型是",[["A","经肛管括约肌型"],["B","肛管括约肌间型"],["C","肛管括约肌上型"],["D","肛管括约肌外型"],["E","骨盆直肠瘘"]],"B","根据瘘管与括约肌的关系，将肛瘘分为以下四类：①肛管括约肌间型（B对），最常见，约占肛瘘的70%；②经肛管括约肌型（A错），约占25%；③肛管括约肌上型（C错），较少见，约占4%；④肛管括约肌外型（D错），最少见，仅占0.5%。","","N"],["1997-N111",57,"第一节 骨肿瘤概论","骨肿瘤分类",1997,111,"B","","骨瘤",[["A","好发于颅骨和下颌骨"],["B","好发于手和足的管状骨"],["C","好发于骶尾椎和颅底蝶枕部"],["D","好发于股骨下端、胫骨或腓骨上端和肱骨上端"],["E","好发于下肢长骨骨干"]],"A","骨瘤是一种良性骨肿瘤，一般隆突于骨面，几乎全部局限于颅骨和下颌骨（A对）。","","N"],["1997-N112",57,"第二节 良性骨肿瘤","软骨瘤",1997,112,"B","","内生软骨瘤",[["A","好发于颅骨和下颌骨"],["B","好发于手和足的管状骨"],["C","好发于骶尾椎和颅底蝶枕部"],["D","好发于股骨下端、胫骨或腓骨上端和肱骨上端"],["E","好发于下肢长骨骨干"]],"B","软骨瘤是一种松质骨的、透明软骨组织构成的、软骨源性的良性肿瘤，好发于手和足的管状骨（B对），其中，位于骨干中心者称为内生软骨瘤。骨瘤好发于颅骨和下颌骨（A错）。脊索瘤（十版外科学P767）好发于骶尾椎和颅底蝶枕部。骨肉瘤（十版外科学P765）好发于股骨下端、胫骨或腓骨上端和肱骨上端（D错）。骨样骨瘤（十版外科学P762）好发于下肢长骨骨干（E错）。","","N"],["1997-N113",23,"第三节 股疝","股疝治疗",1997,113,"B","","股疝最恰当的手术方式是",[["A","疝囊高位结扎术"],["B","Bassini法修补术"],["C","Halsted法修补术"],["D","McVay法修补术"],["E","Ferguson法修补术"]],"D","McVay修补法是在精索后方把腹内斜肌下缘和联合腱缝至耻骨梳韧带上，能堵住股环而用于修补股疝（D对）。现临床上治疗腹外疝多采用无张力疝修补术或经腹腔镜疝修补术。","","N"],["1997-N114",23,"第二节 腹股沟疝","嵌顿性和绞窄性疝的处理原则",1997,114,"B","","绞窄性斜疝局部有感染者，应选的合理手术方式是",[["A","疝囊高位结扎术"],["B","Bassini法修补术"],["C","Halsted法修补术"],["D","McVay法修补术"],["E","Ferguson法修补术"]],"A","绞窄性疝局部感染者，若行疝修补术，则容易导致感染，引起持续的炎症反应使伤口延迟愈合、易于裂开，因此一般不行疝修补术。急症时，仅作坏死肠管切除及疝囊高位结扎术（A对）。","","N"],["1997-N115",33,"第二节 胰腺炎","急性胰腺炎临床表现",1997,115,"B","","急性胰腺炎可有",[["A","突发剑突下剧烈疼痛、阵发性伴钻顶感，间歇期不痛"],["B","上腹部或右上腹部阵发加剧的持续疼痛"],["C","上腹持续剧痛伴左肩、腰、背牵拉痛"],["D","食后上腹胀痛、伴呕吐"],["E","与饮食有关的慢性周期性节律性上腹痛"]],"C","急性胰腺炎为上腹持续剧痛伴左肩、腰、背牵拉痛（C对）。突发剑突下剧烈疼痛、阵发性伴钻顶感，间歇期不痛（A错）为胆道蛔虫症（十版外科学P477）的腹痛特点。上腹部或右上腹部阵发加剧的持续疼痛（B错）为急性胆囊炎（十版外科学P473）的腹痛特点。食后上腹胀痛、伴呕吐（D错）常见于幽门梗阻（十版外科学P381）或高位肠梗阻（十版外科学P394）。与饮食有关的慢性周期性节律性上腹痛（E错）为典型消化性溃疡的疼痛特点。","","N"],["1997-N116",32,"第五节 胆道感染","急性结石性胆囊炎临床表现",1997,116,"B","","急性胆囊炎可有",[["A","突发剑突下剧烈疼痛、阵发性伴钻顶感，间歇期不痛"],["B","上腹部或右上腹部阵发加剧的持续疼痛"],["C","上腹持续剧痛伴左肩、腰、背牵拉痛"],["D","食后上腹胀痛、伴呕吐"],["E","与饮食有关的慢性周期性节律性上腹痛"]],"B","急性胆囊炎可有上腹部或右上腹部阵发加剧的持续疼痛（B对）。突发剑突下剧烈疼痛、阵发性伴钻顶感，间歇期不痛（A错）为胆道蛔虫症（十版外科学P476）的疼痛特点。上腹持续剧痛伴左肩、腰、背牵拉痛（C错）为急性胰腺炎（十版外科学P487）的疼痛特点。食后上腹胀痛、伴呕吐（D错）常见于幽门梗阻（十版外科学P381）或高位肠梗阻（十版外科学P394）。与饮食有关的慢性周期性节律性上腹痛（E错）为典型消化性溃疡的疼痛特点。","","N"],["1997-N135",53,"第二节 腰椎退行性疾病","腰椎管狭窄症临床表现",1997,135,"C","","腰椎椎管狭窄",[["A","神经源性间歇性跛行"],["B","坐骨神经支配区的放射痛"],["C","两者均有"],["D","两者均无"]],"C","腰椎管狭窄是不同原因引起的椎管、神经根管或神经孔狭窄从而引发的一系列临床症状，由于造成脊髓、马尾神经或神经根的压迫，可以出现相应的临床表现，包括神经源性间歇性跛行（A对）、下腰痛、马尾神经受压症状、坐骨神经支配区的放射痛等（B对）。本题AB均对，正确答案为C。","","N"],["1997-N136",53,"第二节 腰椎退行性疾病","第三腰椎横突综合征",1997,136,"C","","第三腰椎横突综合征",[["A","神经源性间歇性跛行"],["B","坐骨神经支配区的放射痛"],["C","两者均有"],["D","两者均无"]],"D","第三腰椎横突综合征好发于青壮年体力劳动者，由于第三腰椎横突特别长，且水平位伸出，附近有血管、神经束经过，有较多的肌筋膜附着；在正位上第三腰椎处于腰椎生理前凸弧度的顶点，为力学传递的重要部位，易受外力作用的影响，容易受损伤。该处损伤可造成刺激、压迫症状，主要表现为腰痛，少数可沿骶棘肌向下放射。由于腰椎横突周围无神经根的通过，故无神经受累体征，不会出现神经源性间歇性跛行（A错）及坐骨神经支配区的放射痛（B错）。本题AB均错，正确答案为D。","","N"],["1997-N137",17,"第一节 甲状腺疾病","甲状腺癌临床表现",1997,137,"C","","短期内迅速增大的甲状腺肿物可能是",[["A","甲状腺癌"],["B","甲状腺囊性腺瘤"],["C","两者均可"],["D","两者均无"]],"C","甲状腺腺瘤可分为滤泡状腺瘤、乳头状囊性腺瘤两种，腺瘤生长缓慢，但当乳头状囊性腺瘤因囊壁血管破裂发生囊内出血时，肿瘤可在短期内迅速增大，局部出现胀痛（B对）；甲状腺癌为恶性肿瘤，若不及时治疗，肿瘤结节短期内可迅速增大（A对），并发生转移。本题AB均对，正确答案为C。","","N"],["1997-N138",17,"第一节 甲状腺疾病","甲状腺癌临床表现",1997,138,"C","","质硬而高低不平的甲状腺肿物可能是",[["A","甲状腺癌"],["B","甲状腺囊性腺瘤"],["C","两者均可"],["D","两者均无"]],"A","甲状腺内发现肿块，质地硬而固定、表面不平是各型甲状腺癌（A对）的共同表现；而甲状腺腺瘤（B错）多为单发，稍硬，表面光滑，无压痛，随吞咽上下移动。","","N"],["1997-N157",51,"第五节 与慢性损伤相关的其他疾病","粘连性肩关节囊炎临床特点",1997,157,"X","","关于肩周炎，下列哪些项不对",[["A","好发生于重体力劳动者，男性多于女性"],["B","系肩周肌、肌腱、滑囊和关节囊的慢性损伤性炎症"],["C","以活动时疼痛、功能受限为临床特点"],["D","本病能自愈，一般需一年左右，即使不进行功能锻炼，亦不遗留任何功能障碍"]],"AD","肩周炎又称冻结肩，本病好发于40岁以上的中老年，女性多于男性，左侧多于右侧（A错，为本题正确答案），为肩周、肌腱、肌肉、滑囊及关节囊的慢性损伤性炎症（B对）。以活动时疼痛、功能受限为其临床特点（C对）。肩周炎有其自然病程，有自愈倾向，可遗留不同程度的功能障碍（D错，为本题正确答案）。","","N"],["1997-N158",0,"第三节 手术进行中的无菌原则","手术进行中的无菌原则",1997,158,"X","","术中的无菌原则，下列哪些项是正确的",[["A","术者前臂一旦触及有菌物后，应即更换无菌手套"],["B","无菌巾湿透时，应加盖无菌单"],["C","不应越过头部或术者背后传递器械及手术用品"],["D","手术台边缘以下的布单认为是无菌地带，接触后不必更换无菌手套"]],"BC","术者前臂一旦触及有菌物后，更换无菌手套（A错）并不能解决问题，正确处理应为更换无菌手术衣或加套无菌袖套。如果无菌巾、布单等已被浸湿，其无菌隔离作用已不再完整，应加盖无菌单（B对）。手术时，无菌区域为手术台平面以上，术者肘上10公分以下，胸前为无菌区域，其余区域皆为有菌区域，因此不应越过头部或术者背后传递器械及手术用品（C对），手术台边缘以下的布单认为是有菌地带，接触后须更换无菌手套（D错）。关于手术过程中无菌范围等问题以及其他有关无菌操作注意事项的题目是外科的重点知识，外科医生需牢固树立无菌意识。","","N"],["1997-N159",4,"第四节 肠内营养","肠内营养适应证",1997,159,"X","","手术前后，外科病人补充营养的选择宜是",[["A","消化道功能正常者，以口服为主"],["B","昏迷或不能进食的病人可用管饲"],["C","结肠手术前准备和术后处理可用要素饮食"],["D","口服或管饲有困难或仍难提高营养者，可采用胃肠外营养"]],"ABCD","胃肠道功能正常者，营养支持时应首选肠内营养，且应该以口服为主（A对）。昏迷或不能进食的病人，若肠道功能无损害，则可用管饲给予流食（B对），以避免误吸导致吸入性肺炎。要素饮食是一种化学精制食物，与水混合后可以形成溶液或较为稳定的悬浮液，无需经过消化过程即可直接被肠道吸收和利用，为人体提供热能及营养。结肠术前准备和术后处理采用要素饮食可减少粪便残渣，以利于肠道清洁和避免术后吻合口瘘（C对）。口服或管饲有困难或仍难提高营养者，为保证病人的生命和疾病恢复，可采用胃肠外营养代替肠道吸收营养（D对）。","","N"],["1997-N160",10,"第四节 局部麻醉","常用局麻药",1997,160,"X","","关于局麻药的叙述，哪些是正确的",[["A","局麻药最多见的全身不良反应是过敏性休克"],["B","普鲁卡因主要被血浆假性胆碱脂酶水解"],["C","利多卡因主要在肝脏内被分解"],["D","普鲁卡因的成人一次限量为1g"]],"BCD","局麻药的不良反应包括毒性反应和过敏反应，其中毒性反应主要与用量超限、药物注射或渗入血液、病人耐受力差有关；过敏反应即变态反应，临床上多见于酯类局麻药，酰胺类极少见。过敏性休克仅见于极少部分患者（A错），为局麻药的严重不良反应。出现过敏性休克时，应注意呼吸管理，充分给氧，必要时应用镇静药（如巴比妥类药物）（七版黄家驷外科学P297）。酯类局麻药（包括普鲁卡因、丁卡因）主要被血浆假性胆碱酯酶水解（B对）；酰胺类局麻药（包括利多卡因、布比卡因、罗哌卡因）在肝内被微粒体酶所水解（C对）。普鲁卡因的成人一次限量为1g（D对）。","","N"],["1998-N75",4,"第三节 肠外营养","肠外营养适应证",1998,75,"A","","哪种病人不需使用全胃肠外营养",[["A","短肠综合征"],["B","溃疡性结肠炎长期腹泻"],["C","胆囊造瘘术后"],["D","坏死性胰腺炎"],["E","癌肿化疗致严重呕吐"]],"C","凡是需要营养支持，但又不能或不宜接受肠内营养支持的病人均为肠外营养支持的适应证。短肠综合征（A对）是由于不同原因造成小肠吸收面积减少而引起的一个临床症候群，在急性期（术后2个月）主要通过全胃肠外营养进行支持，此后的代偿期和维持期根据实际情况给与肠内营养、肠外营养支持或特殊的肠内营养（十版外科学P398），此部分内容九版外科学有更加明确的描述。溃疡性结肠炎长期腹泻者（B对），食物进入肠腔可加重病情，需使用全胃肠外营养；坏死性胰腺炎（D对）必须严格禁食，以避免食物对胰腺的刺激加重病情，需使用全胃肠外营养；癌肿化疗致严重呕吐（E对）使得患者无法正常进食，加重了病人的营养不良，需使用全胃肠外营养。胆囊造瘘术是一种较简单的急救手术，目的在于引流胆汁、降低胆压，消除胆道炎症，其不影响病人进食（C错，为本题正确答案）。","","N"],["1998-N76",5,"第一节 外科感染概述","外科感染分类",1998,76,"A","","有关外科感染，下列哪项不正确",[["A","约占外科疾病的1/3～1/2"],["B","疖、丹毒、急性阑尾炎等均属非特异性感染"],["C","病程在2个月之内者均属急性感染"],["D","医院内感染的主要病菌是条件性病原菌"],["E","外科感染病程中，常发展为混合感染"]],"C","外科感染一般是指需要手术治疗的感染性疾病和发生在创伤或手术后的的感染，在外科领域中最常见，约占所有外科疾病的1/3～1/2（A对）。常分为特异性和非特异性感染：非特异性感染主要由一般的细菌化脓性感染，由金葡菌、大肠杆菌等常见菌引起，常见疾病有疖、痈、丹毒、急性乳腺炎、急性阑尾炎等（B对）；特异性感染如结核、破伤风、气性坏疽、念珠菌病等，因致病菌不同于一般感染，可引起较为独特的病变。感染根据病程长短可分为急性、亚急性与慢性感染。病程在3周之内为急性感染，超出2个月为慢性感染，介于二者之间的为亚急性感染（C错，为本题正确答案）。院内感染是指住院病人在医院内获得的感染，包括在住院期间发生的感染和在医院内获得出院后发生的感染，但不包括入院前已开始或者入院时已处于潜伏期的感染，由于药物的使用，正常致病菌被抑制，而原先不致病的菌群得以繁殖并引起疾病，或由于病人抗感染能力下降，无法耐受原先不致病的微生物而造成感染，这些病原体称为“条件性病原菌”，故院内感染的主要致病菌是条件致病菌（D对）。外科感染可由单一病原体所致，但常随病程发展为由多种病原体所致形成的混合感染（E对）。","","N"],["1998-N77",1,"第五节 酸碱平衡失调","代谢性碱中毒治疗",1998,77,"A","","瘢痕性幽门梗阻病人术前纠正体液代谢和酸碱平衡失调时，选用的液体应为",[["A","1.25%碳酸氢钠液+林格氏液"],["B","1.25%碳酸氢钠液+5%葡萄糖液"],["C","5%葡萄糖液+1/6mol/L乳酸钠液"],["D","5%葡萄糖盐水+氯化钾液"],["E","1/6mol/L乳酸钠液"]],"D","瘢痕性幽门梗阻病人的症状主要为反复呕吐，导致脱水；钾摄入不足，且由于含有K⁺及Cl⁻的酸性胃液的大量丢失引起低钾低氯性碱中毒。补充5%葡萄糖盐水，既恢复了细胞外液量，又提供了患者必要的能量；补充氯化钾，既补充了Cl⁻，起到了纠正轻度碱中毒的作用，还补充了血钾（D对）。但应注意须在病人尿量超过40ml/h才可开始补K⁺。补碱会加重碱中毒（乳酸钠也为碱性液体）（ABCE错）。林格氏液为生理盐水中加入氯化钾及氯化钙，比生理盐水成分完全，可代替生理盐水使用，因其由英国生理学家“林格”所发明，所以称林格氏液，实际上就是通称的复方氯化钠注射液。","","N"],["1998-N78",13,"第二节 术后处理","引流管",1998,78,"A","","病人术后的处理中哪项不正确",[["A","胃肠道手术病人肛门排气后，可开始进食"],["B","腹部的减张缝线一般在术后2周左右拆除"],["C","伤口的乳胶片引流一般在术后4～7天拔除"],["D","一般性手术后的病人，应鼓励早期活动"],["E","术后尿潴留导尿量超过500ml者，应留置尿管1～2天"]],"C","胃肠道手术病人肠道功能受损，需待到肠道功能基本恢复后，可开始进食，肠道功能基本恢复的征兆是闻及肠鸣音或肛门已排气（A对）。对于缝合处组织张力大，全身情况较差时，为防止切口裂开可采用减张缝合，主要用于腹壁切口，一般在术后2周左右伤口基本愈合时可拆线（B对）。乳胶片通常用于浅表伤口的引流，一般在术后1～2日即拔除，时间过长有碍于伤口的愈合（C错，为本题正确答案）。一般性手术后的病人，应鼓励早期活动（D对），这有利于患者呼吸和运动功能的恢复，并防止坠积性肺炎、下肢深静脉血栓形成等疾病的发生。尿潴留时间过长，导尿时尿液量超过500ml者，应留置尿管1～2天（E对），有利于膀胱逼尿肌收缩力的恢复。","","N"],["1998-N79",10,"第四节 局部麻醉","神经阻滞",1998,79,"A","","神经阻滞麻醉时，局麻药100ml内加用肾上腺素的最佳剂量为",[["A","0.2mg"],["B","0.3mg"],["C","0.4mg"],["D","0.5mg"],["E","0.6mg"]],"D","在药液中增加肾上腺素，利用的是肾上腺素的缩血管作用，使得局麻药吸收速度减慢，延长作用时间，同时可减轻局麻药吸收所引起的毒性反应。临床上常选择1：20万的比例加入肾上腺素，则100ml的局麻药中加肾上腺素的最佳剂量为100×1/200000＝0.0005g＝0.5mg（D对）。","","N"],["1998-N80",10,"第五节 椎管内麻醉","麻醉平面的调节",1998,80,"A","","硬膜外麻醉时，下列影响麻醉平面的因素中哪项最不重要",[["A","病人体位"],["B","穿刺间隙"],["C","导管方向"],["D","注药方式"],["E","药物容积"]],"A","影响硬膜外麻醉平面的主要因素为考试重点，需掌握。对于硬膜外麻醉来说，局麻药注入硬膜外后，因为硬膜外腔为负压，无脑脊液，药液将通过虹吸现象吸附于黄韧带和硬脊膜间，药液流动能力小，故体位对麻醉平面的影响很小（A错，为本题正确答案）。穿刺间隙（B对）决定麻醉节段的上下平面的位置；导管方向（C对）可决定药液的扩散方向，导管向头端插入，药液向颈胸段扩散，向尾端插入，药液向腰骶段扩散；注药方式（D对）决定麻醉范围，在药物剂量相同的情况下，一次注射麻醉平面较广，分次注射范围较窄；药物容积（E对）大，则扩散快，麻醉范围广，反之麻醉范围窄。","","N"],["1998-N81",17,"第一节 甲状腺疾病","单纯性甲状腺肿病因",1998,81,"A","","下列哪项不是单纯性甲状腺肿的病因",[["A","碘的缺乏"],["B","甲状腺素合成障碍"],["C","甲状腺素分泌障碍"],["D","甲状腺素需求增多"],["E","长效甲状腺刺激素浓度增高"]],"E","环境缺碘是引起单纯性甲状腺肿的主要因素。碘的缺乏（A对），导致甲状腺无法合成足量的甲状腺激素，反馈性引起垂体TSH分泌增高并刺激甲状腺滤泡上皮细胞增生，产生代偿性肿大。此外，由于甲状腺素合成和分泌过程中某一环节的障碍，例如久食含有硫脲的萝卜、白菜等，可阻止甲状腺素的合成，或先天缺乏合成甲状腺素的酶，引起血中甲状腺素减少，反馈性引起垂体TSH分泌增高并刺激甲状腺滤泡上皮细胞增生，促使甲状腺肿大（BC对）。有些青春发育期、妊娠期或绝经期的妇女，由于对甲状腺素的需要量暂时性增高，也可发生轻度弥漫性甲状腺肿，也叫生理性甲状腺肿（D对）。长效甲状腺刺激素浓度增高（E错，为本题正确答案），导致甲状腺滤泡上皮细胞增生，为原发性甲亢的原因。","","N"],["1998-N82",23,"第三节 股疝","股疝病理解剖",1998,82,"A","","哪种腹外疝发生肠管壁疝的机会较多",[["A","斜疝"],["B","直疝"],["C","股疝"],["D","脐疝"],["E","白线疝"]],"C","肠管壁疝指嵌顿的内容物仅为部分肠壁，系膜侧肠壁及其系膜并未进入疝囊，肠腔并未完全梗阻。股管为上宽下窄的漏斗形结构，上端称股环，下端为卵圆窝，由于股疝都是垂直的，疝块在卵圆窝处向前转折时形成以锐角，且股环本身较小，周围多有坚韧的韧带，因此股管容易发生嵌顿，又因股环本身较小，肠管不易完全进入，因而股疝（C对）常发生肠管壁疝。","","N"],["1998-N83",24,"第二节 常见内脏损伤的特征和处理","脾损伤处理",1998,83,"A","","有关脾破裂，哪项是错误的",[["A","发病率占腹部损伤的40%～50%"],["B","真性破裂约占脾破裂的85%"],["C","脾破裂的治疗原则是紧急手术处理"],["D","成人脾切除术后，暴发型感染的发病率一般认为不超过1%"],["E","脾切除术后暴发型感染以大肠杆菌为主要病原菌"]],"E","脾是腹腔脏器最容易受损的器官之一，脾脏损伤发病率占腹部损伤的40%～50%（A对），其中真性破裂约占脾破裂的85%（B对）。脾是人体血供最丰富的器官之一，本身又质脆易受伤，多见真性破裂（破损累及被膜），损伤后大出血迅速导致休克危及生命，故需紧急手术治疗（C对）。因脾组织质脆难缝合，为挽救生命，常采用脾部分切除或脾全切。成人行脾切除术对免疫功能的影响轻微，暴发型感染的发病率不超过1%（D对）。脾切除后凶险性感染（OPSI）主要发生在婴幼儿，50%病人的致病菌为肺炎链球菌（E错，为本题正确答案）。脾作为腹部内脏最容易受损的器官，脾破裂的诊断和处理是腹部损伤一章中的常考点，部分数据考生需留意。","","N"],["1998-N84",25,"急性化脓性腹膜炎概述","腹膜解剖生理概要",1998,84,"A","","有关腹膜的叙述，哪项正确",[["A","腹膜是由上皮细胞组成的一层薄膜"],["B","网膜不是腹膜形成的"],["C","腹膜的面积约1m²"],["D","壁腹膜主要受肋间神经和腰神经支配，痛觉敏感，定位准确"],["E","盆腔腹膜较其它部位吸收力更强"]],"D","腹膜的表面是一层排列规则的扁平间皮细胞（A错）。脏腹膜将内脏器官悬垂或固定于膈肌、腹后壁或盆腔壁，形成网膜、肠系膜及韧带等解剖结构（B错）。腹膜有很多皱襞，其面积几乎与全身的皮肤面积相等，约为1.5m²（C错）。壁腹膜主要受体神经的支配，对各种刺激敏感，痛觉定位准确（D对）。许多腹部手术在术后均采取坐位或半卧位，其目的就是将渗出液引流至盆腔，利用盆腔的吸收能力差的特点，使渗出液局限，减轻腹腔对其的吸收（E错）。九版外科学有关腹膜面积的数据有更新（十版外科学P363）。","","N"],["1998-N85",26,"第三节 胃十二指肠溃疡的外科治疗","毕Ⅰ术式",1998,85,"A","","哪项是毕Ⅰ式胃大部切除术的优点",[["A","适用于各种情况的胃十二指肠溃疡"],["B","吻合口张力较小"],["C","即使十二指肠溃疡未能切除，术后也能愈合"],["D","术后胃肠道功能紊乱较少"],["E","术后溃疡复发率较低"]],"D","毕Ⅰ式是胃与十二指肠吻合，它比较符合原来的生理状况，术后胃肠道功能紊乱较少（D对）。毕Ⅰ式因其切胃量较毕Ⅱ式少，术后复发率相对高（E错），因此毕Ⅰ式只适用于低胃酸的胃溃疡的治疗（A错），毕Ⅱ式可用于胃溃疡及十二指肠溃疡，尤其是高胃酸的十二指肠溃疡治疗。毕Ⅰ式需牵拉断端在原位吻合，因而吻合口张力较大（B错）。行胃大部切除术后，胃酸降低，当十二指肠球部溃疡切除有困难时，可行溃疡旷置，术后未切除的溃疡仍可以愈合，此为Bancroft法，该法为毕Ⅱ式的优点（C错）。","","N"],["1998-N86",28,"第二节 急性阑尾炎","急性阑尾炎的并发症",1998,86,"A","","急性阑尾炎可发生的并发症不包括下列哪项",[["A","腹腔脓肿"],["B","腹腔内出血"],["C","内瘘形成"],["D","外瘘形成"],["E","门静脉炎"]],"B","腹腔内出血（B错，为本题正确答案）是阑尾切除术的并发症之一，是由阑尾系膜的结扎线松脱，引起系膜血管出血导致，而非急性阑尾炎的并发症。腹腔脓肿（A对），内瘘（C对）、外瘘形成（D对），门静脉炎（E对）都急性阑尾炎可发生的并发症。","","N"],["1998-N87",30,"第四节 原发性肝恶性肿瘤","肝细胞癌病因和病理",1998,87,"A","","原发性肝癌极易转移的脏器是",[["A","肝内"],["B","肺"],["C","骨"],["D","脑"],["E","胰腺周围、腹膜后"]],"A","肝细胞癌在发展过程中很容易侵犯门静脉分支，形成门静脉癌栓并在肝内转移（A对）。肝癌经淋巴转移者相对少见，这是肝癌和其他恶性肿瘤不同的地方，需考生注意。原发性肝癌的肝外转移最多见于肺（B错）、骨（C错）、脑（D错），其次为胰腺周围、腹膜后淋巴结（E错）等处。","","N"],["1998-N88",32,"第十节 胆囊息肉和良性肿瘤","胆囊息肉诊断",1998,88,"A","","下列哪种胆囊息肉的征象支持良性息肉的诊断",[["A","单发"],["B","多发"],["C","不规则状"],["D","﹥1cm"],["E","生长迅速"]],"B","胆囊息肉样变是指来源于胆囊壁并向胆囊腔内突出或隆起的病变，主要包括胆囊息肉、胆囊腺肌增生症和胆囊腺瘤三种。胆囊息肉恶变的危险因素包括：直径＞1cm（D错）、生长迅速（E错）；单发（A错）病变且基底部宽大；合并胆囊结石和胆囊壁增厚等，特别是年龄超过50岁；息肉外形不规则状（C错）及局部增厚者；息肉位于胆囊底部者。多发（B对）性胆囊息肉常支持良性息肉的诊断。有关胆囊息肉恶变危险因素的相关数据，十版外科学有更新（十版外科学P480）。","","N"],["1998-N89",33,"第二节 胰腺炎","急性胰腺炎全身并发症",1998,89,"A","","出血坏死性胰腺炎最常见的并发症是",[["A","化脓性腹膜炎"],["B","败血症"],["C","消化道出血"],["D","胰周围脓肿"],["E","休克"]],"E","出血坏死性胰腺炎可继发多种并发症，最常见的并发症为休克。早期休克时因为组织坏死、感染中毒等因素促进血管活性物质大量释放，大量液体渗出至血管外，导致低血容量性休克；晚期休克多因为坏死继发腹腔感染，导致感染性休克（E对）。化脓性腹膜炎发生率低（A错）。除非发生严重的腹腔感染，否则一般不会引起败血症（B错）。出血坏死性胰腺炎通常引起的是腹腔内的出血，而不是消化道出血（C错）。胰周围脓肿（D错）发生于重症急性胰腺炎的后期，发生率低。","","N"],["1998-N90",53,"第二节 腰椎退行性疾病","腰椎管狭窄症",1998,90,"A","","腰椎间盘突出症与腰椎椎管狭窄症的鉴别，最主要的根据是",[["A","腰痛的部位"],["B","腰痛的轻重程度"],["C","有无坐骨神经区的放射痛"],["D","有无神经源性间歇跛行"],["E","X线片、造影、CT、MRI等检查"]],"E","腰椎间盘突出、腰椎椎管狭窄是不同原因引起的椎管症，腰椎间盘突出的主要发病原因是椎间盘的退行性病变，椎间盘凸出正常部位，造成对神经根的压迫症状从而发病；腰椎椎管狭窄是多种原因所致椎管、神经根管、椎间孔的狭窄从而引发的一系列临床症状。两者均可出现不同程度的腰痛（AB错）、受累神经根支配区的放射痛（C错）以及运动感觉障碍等，因此ABCD四项均不能用于鉴别腰椎间盘突出症及腰椎椎管狭窄症。CT可显示椎间盘的形态、突出方向、大小以及椎管是否狭窄。MRI可了解椎管、髓核、脊髓、脊神经根之间的关系。因此，鉴别两者最好的方法是通过X线片、造影、CT、MRI等影像学检查（E对）。","","N"],["1998-N91",57,"第五节 转移性骨肿瘤","转移性骨肿瘤概述",1998,91,"A","","在转移性骨肿瘤中，下列原发病灶哪种最多见",[["A","乳腺癌"],["B","前列腺癌"],["C","肾癌"],["D","膀胱癌"],["E","甲状腺癌"]],"A","骨的转移瘤是经血或淋巴转移至骨的恶性肿瘤。七版黄家驷外科学P3108页认为不同系统原发肿瘤骨转移发生率如下：乳腺癌（A对）为47%～85%，前列腺癌为33%～85%，甲状腺癌为28%～60%，肺癌为30%～64%。骨转移瘤好发于椎体、骨盆及股骨。","","N"],["1998-N92",55,"第一节 骨与关节结核概论","病灶清除术",1998,92,"A","","下列哪种情况，不是骨关节结核病灶清除术的适应证",[["A","有明显死骨或较大脓肿不易自行吸收者"],["B","窦道流脓经久不愈者"],["C","单纯骨或滑膜结核，即将发展成全关节结核者"],["D","脊柱结核合并截瘫者"],["E","病人全身中毒症状重、抗结核药物效果不佳产生耐药者"]],"E","骨关节结核病灶清除术的适应证：①经非手术治疗效果不佳，病变仍有进展；②有明显的死骨或较大脓肿形成（A对）；③窦道流脓经久不愈（B对）；④脊柱结核有脊髓、马尾神经受压表现等（D对）；⑤单纯骨或滑膜结核，即将发展成全关节结核者（C对）。骨关节结核病灶清除术的禁忌证：①伴有其他脏器活动期结核者；②病情危重，全身情况差；③合并有其他疾病难以耐受手术者。在全身中毒症状重、抗结核药物效果不佳产生耐药的患者（E错，为本题正确答案），若实行手术，很可能会造成无法控制的结核菌的扩散，使得病情更加复杂和恶化。此时应积极采取支持治疗，更换敏感抗结核药，待一般情况改善后再作下一步治疗。","","N"],["1998-N111",17,"第一节 甲状腺疾病","髓样癌",1998,111,"B","","分泌大量降钙素的甲状腺癌是",[["A","乳头状腺癌"],["B","滤泡状腺癌"],["C","未分化癌"],["D","髓样癌"],["E","转移癌"]],"D","甲状腺髓样癌（D对）来源于甲状腺滤泡旁细胞（又称C细胞），恶性程度中等，可分泌降钙素等多种激素，病人可有腹泻、面部潮红和多汗等类癌综合征或其他内分泌失调的表现。","","N"],["1998-N112",17,"第一节 甲状腺疾病","乳头状癌",1998,112,"B","","最多见的甲状腺癌是",[["A","乳头状腺癌"],["B","滤泡状腺癌"],["C","未分化癌"],["D","髓样癌"],["E","转移癌"]],"A","甲状腺乳头状腺癌（A对）最常见，恶性度也最轻，镜下：乳头分枝多，乳头中心有纤维血管间质（真乳头），间质内常见呈同心圆状的钙化小体，即砂粒体，有助于诊断。甲状腺癌病理分型为：乳头状腺癌（最常见，约60%）、滤泡状腺癌（约20%）（B错）、髓样癌（约7%）（D错）和未分化癌（约15%）（C错）4类。","","N"],["1998-N113",13,"第一节 术前准备","术前准备概述",1998,113,"B","","属择期手术的是",[["A","嵌顿疝还纳修补术"],["B","胃癌根治术"],["C","甲状腺腺瘤切除术"],["D","脾破裂行脾切除术"],["E","十二指肠溃疡穿孔修补术"]],"C","病人的术前准备与疾病的轻重缓急、手术范围的大小有密切关系。在病情危急、病人随时有生命危险，只有手术治疗才能快速挽救病人生命情况下，需按照急诊手术处理；对于病情尚平稳，但疾病本身存在较大的潜在危险者，或已为恶性病情、需尽早进行手术治疗者，或已做好术前准备，延期手术将造成术前准备失效者，按照限期手术处理；对于病人身体状况尚可，短期内病变对患者无严重危害，手术时间可以不受期限的限制择日进行，手术前可以有足够的时间，行择期手术。本题中，嵌顿疝还纳修补术（A错）、脾破裂行脾切除术（D错）、十二指肠溃疡穿孔修补术（E错）都属于急症手术。胃癌为恶性肿瘤，需要尽早做好术前准备后行手术治疗，因此胃癌根治术为限期手术（B错）。甲状腺腺瘤为良性肿瘤，短期内不会对病人生命造成威胁，因此甲状腺腺瘤切除术（C对）属于择期手术。","","N"],["1998-N114",13,"第一节 术前准备","术前准备概述",1998,114,"B","","属限期手术的是",[["A","嵌顿疝还纳修补术"],["B","胃癌根治术"],["C","甲状腺腺瘤切除术"],["D","脾破裂行脾切除术"],["E","十二指肠溃疡穿孔修补术"]],"B","病人的术前准备与疾病的轻重缓急、手术范围的大小有密切关系。在病情危急、病人随时有生命危险，只有手术治疗才能快速挽救病人生命情况下，需按照急诊手术处理；对于病情尚平稳，但疾病本身存在较大的潜在危险者，或已为恶性病情、需尽早进行手术治疗者，或已做好术前准备，延期手术将造成术前准备失效者，按照限期手术处理；对于病人身体状况尚可，短期内病变对患者无严重危害，手术时间可以不受期限的限制择日进行，手术前可以有足够的时间，行择期手术。本题中，嵌顿疝还纳修补术（A错）、脾破裂行脾切除术（D错）、十二指肠溃疡穿孔修补术（E错）都属于急症手术。甲状腺腺瘤为良性肿瘤，短期内不会对病人生命造成威胁，因此甲状腺腺瘤切除术（C错）属于择期手术。胃癌为恶性肿瘤，需要尽早做好术前准备后行手术治疗，因此胃癌根治术为限期手术（B对）。","","N"],["1998-N115",47,"第二节 股骨近端骨折","内收型骨折",1998,115,"B","","股骨颈骨折内收型可有",[["A","患肢短缩、髋屈曲内收内旋畸形"],["B","患肢短缩、髋屈曲内收外旋畸形"],["C","患肢短缩、髋屈曲外展内旋畸形"],["D","患肢短缩、髋屈曲外展外旋畸形"],["E","患肢增长、髋伸直外展外旋畸形"]],"B","股骨颈内收型骨折为关节囊内骨折，骨折远端失去了关节囊及髂股韧带的稳定作用，可出现患肢缩短，髋屈曲内收外旋畸形（B对）。患肢缩短、髋屈曲内收内旋畸形（A错）为髋关节后脱位的典型临床表现。患肢增长、髋屈曲外展外旋畸形为髋关节前脱位（十版外科学P651）的典型临床表现。","","N"],["1998-N116",47,"第一节 髋关节脱位","髋关节后脱位临床表现和诊断",1998,116,"B","","髋关节后脱位可有",[["A","患肢短缩、髋屈曲内收内旋畸形"],["B","患肢短缩、髋屈曲内收外旋畸形"],["C","患肢短缩、髋屈曲外展内旋畸形"],["D","患肢短缩、髋屈曲外展外旋畸形"],["E","患肢增长、髋伸直外展外旋畸形"]],"A","髋关节后脱位指股骨头从髋关节囊的后下部薄弱区脱出，表现为患肢缩短，髋关节呈屈曲、内收、内旋畸形（A对）。患肢短缩、髋屈曲内收外旋畸形（B错）为股骨颈骨折（十版外科学P652）的典型临床表现。患肢增长、髋屈曲外展外旋畸形为髋关节前脱位（十版外科学P651）的典型临床表现。","","N"],["1998-N135",0,"第一节 手术器械、物品的灭菌、消毒法","高压蒸汽灭菌法",1998,135,"C","","橡胶类物品灭菌",[["A","高压蒸气灭菌法"],["B","煮沸灭菌法"],["C","两者均可"],["D","两者均不可"]],"C","高压蒸气灭菌法是使蒸气进入灭菌室内，积聚而使压力增高，室内温度也随之升高。当高压蒸气达到一定的温度和时间，即能杀灭包括具有顽强抵抗力的细菌芽孢在内的一切微生物。适用于大多数医用物品（包括橡胶类物品（A对）、玻璃类物品、金属类物品、布类敷料等）。煮沸灭菌法是将物品放于水中，煮沸至100℃，持续15～20分钟，可杀灭一般细菌；持续1小时，可杀灭带芽孢的细菌。适用于金属器械、玻璃制品及橡胶类（B对）物品。本题AB均对，正确答案为C。","","N"],["1998-N136",0,"第一节 手术器械、物品的灭菌、消毒法","高压蒸汽灭菌法",1998,136,"C","","玻璃类物品灭菌",[["A","高压蒸气灭菌法"],["B","煮沸灭菌法"],["C","两者均可"],["D","两者均不可"]],"C","高压蒸气灭菌是使蒸气进入灭菌室内，积聚而使压力增高，室内温度也随之升高。当高压蒸气达到一定的温度和时间，即能杀灭包括具有顽强抵抗力的细菌芽孢在内的一切微生物。适用于大多数医用物品（包括橡胶类物品、玻璃类物品（A对）、金属类物品、布类敷料等）。煮沸法是将物品放于水中，煮沸至100℃，持续15～20分钟，可杀灭一般细菌；持续1小时，可杀灭带芽孢的细菌。适用于金属器械、玻璃制品（B对）及橡胶类物品。本题AB均对，正确答案为C。","","N"],["1998-N137",44,"第五节 影响骨折愈合的因素","影响骨折愈合的因素概述",1998,137,"C","","骨折不愈合",[["A","骨折经治疗后，已超过一般愈合所需时间，骨折处仍有反常活动"],["B","X线片示两骨折端被浓密硬化骨质封闭"],["C","两者均有"],["D","两者均无"]],"C","骨折不愈合指骨折经过治疗，超过一般愈合时间（9个月），且经再度延迟治疗（时间3个月），仍达不到骨性愈合（十版外科学P628）骨折处仍有反常活动（A对）。X线表现为骨折线清晰，两骨折端间隙宽，两断端萎缩光滑、硬化，骨髓腔被致密硬化的骨质所封闭。常见原因包括骨折断端嵌夹较多软组织；骨块丢失或清创时去除的骨片较多；严重损伤或治疗不当对骨的血供破坏较大；感染等。A为延迟愈合的标准，题目不够严谨存在争议，参考答案为C。","","N"],["1998-N138",44,"第五节 影响骨折愈合的因素","骨折部位的血液供应",1998,138,"C","","骨折延迟愈合",[["A","骨折经治疗后，已超过一般愈合所需时间，骨折处仍有反常活动"],["B","X线片示两骨折端被浓密硬化骨质封闭"],["C","两者均有"],["D","两者均无"]],"A","骨折经过治疗，超过通常愈合所需时间（4-8个月），骨折处仍有反常活动（A对）。X线表现为骨折端骨痂少，呈云雾状；骨折线明显；无骨硬化表现。常见病因包括：营养不良及全身性疾病；骨折固定不确实；骨折端存在剪切力或旋转力；牵引过度等。","","N"],["1998-N157",48,"第二节 脊髓损伤","脊髓损伤并发症",1998,157,"X","","颈椎骨折脱位合并截瘫的严重并发症有",[["A","呼吸道感染"],["B","心血管系统紊乱"],["C","泌尿系感染"],["D","褥疮"]],"ACD","颈椎骨折脱位合并截瘫，属于高位截瘫。截瘫和四肢瘫病人，一般不直接危及生命，但它的并发症则是导致截瘫病人死亡的主要原因。截瘫平面以下，皮肤失去感觉，下肢不能活动，迫使病人卧于一个体位不动，受压的皮肤缺血缺氧而坏死，形成压疮或褥疮（D对），最常发生于骶部、股骨大转子、髂嵴和足跟等处。S₂～S₄段脊髓为排尿的脊髓反射中枢，圆锥以上脊髓损伤的截瘫病人，尿道外括约肌失去高级神经支配，不能自主放松，因而出现尿潴留；在圆锥损伤病人，阴部神经中枢受损，尿道外括约肌放松，出现尿失禁。这些排尿障碍均导致患者泌尿道的天然防御能力降低，极易引起泌尿系统感染（C对）。高位截瘫病人肋间呼吸肌已麻痹，如果损伤达到C₄以上，膈肌亦麻痹。由于呼吸肌力量不足，呼吸非常费力，使呼吸道的阻力相应增加，分泌物难以排出，极易引起呼吸困难和呼吸道感染（A对），甚至呼吸衰竭。但截瘫一般不累及心血管系统（B错）。","","N"],["1998-N158",7,"第一节 热力烧伤","Ⅲ度烧伤",1998,158,"X","","Ⅲ度烧伤的特点为",[["A","深度可达皮肤全层，甚至皮下、肌肉、骨骼"],["B","创面无水泡，呈蜡白或焦黄色"],["C","创面上看不到树枝状栓塞血管"],["D","病人有剧痛和感觉过敏"]],"AB","Ⅲ°烧伤伤及全层皮肤，可深达肌肉甚至骨骼、内脏器官等（A对）。创面蜡黄或焦黄，甚至炭化（B对）。硬如皮革，干燥，无渗液，发凉，针刺或拔毛无痛觉（D错）。可见粗大栓塞的树枝状血管网（真皮下血管丛栓塞）（C错）。","","N"],["1998-N160",27,"第四节 肠梗阻","按梗阻部位分类",1998,160,"X","","哪几种疾病所致的肠梗阻属闭袢性肠梗阻",[["A","肠蛔虫堵塞"],["B","乙状结肠扭转"],["C","横结肠癌"],["D","小肠套叠"]],"BC","一段肠管两侧完全阻塞的肠梗阻称为闭袢性肠梗阻，由于支配肠管的血管受压，闭袢容易发生缺血、绞窄坏死。对于结肠来说，回盲瓣具有单向活瓣作用，即结肠的内容物不能反流回小肠，若出现结肠段的梗阻，则此梗阻段与回盲瓣之间形成两端闭塞的密闭肠腔，因此横结肠癌（C对）在其发生部位若形成梗阻，便会形成闭袢性肠梗阻。乙状结肠扭转（B对）形成O形受累肠段，扭转部位之间形成密闭肠腔，即发生闭袢性肠梗阻。肠蛔虫堵塞（A错）、小肠套叠（D错）均为肠梗阻原因，但不会造成闭袢性梗阻。","","N"],["1999-N63",34,"第一节 上消化道大出血的诊断和处理","应激性溃疡或急性糜烂性胃炎",1999,63,"A","","Cushing ulcer是指由下列哪种原因引起者",[["A","严重的脏器疾病"],["B","大手术"],["C","大面积烧伤"],["D","休克"],["E","中枢神经病变"]],"E","Cushing溃疡又称库欣溃疡，是指在颅脑损伤、脑病变或颅内手术后发生的应激性溃疡（E对）。Curling溃疡是指不同程度烧伤后继发的应激性溃疡（C错）。","","N"],["1999-N75",55,"第二节 脊柱结核","脊柱结核病理",1999,75,"A","","关于脊柱结核，下列哪项不正确",[["A","颈椎和骶尾段发病最少"],["B","绝大多数的椎体病灶只有一处，少数可呈跳跃性"],["C","小儿椎体结核多从椎体边缘开始"],["D","颈、胸椎椎体结核可合并截瘫"],["E","造成截瘫的原因，在病变活动期，多由于结核坏死物质压迫脊髓所致"]],"C","脊柱结核发病率占骨与关节结核的首位，约占50%，绝大多数发生于椎体。脊柱结核以腰椎结核发生率最高，其次是胸椎，颈椎和骶尾段发病最少（A对）。骨与关节结核一般多为单发病灶，少数可呈跳跃性（B对）。小儿椎体结核多为中心型，从椎体中心开始，一般只侵犯一个椎体（C错，为本题正确答案）。成人椎体结核多起自椎体边缘。脊椎结核病人中约10%～30%并发截瘫，其中病变在胸椎中下段居多，约80%，其次为颈椎、颈胸椎和胸腰椎结核，第一腰椎以下极少见（D对）。造成截瘫的原因，在病变活动期，多由脓液、结核性肉芽组织、干酪样坏死物质和死骨进入椎管内压迫脊髓所致（E对）。","","N"],["1999-N76",44,"第四节 骨折愈合过程","骨折临床愈合标准概述",1999,76,"A","","骨折临床愈合的标准，下列哪项不正确",[["A","局部无压痛"],["B","局部无纵向叩击痛"],["C","局部无反常活动"],["D","局部无畸形"],["E","X线片示骨折线模糊，并有连续性骨痂通过"]],"D","骨折愈合包括畸形愈合，故愈合标准中并不包含局部无畸形（D错，为本题正确答案）。局部有畸形、塑型差称为畸形愈合，亦属于骨折愈合。骨折临床愈合的标准为①局部无压痛（A对）及纵向叩击痛（B对）；②局部无异常活动（C对）；③X线平片显示骨折处有连续性骨痂，骨折线已模糊（E对）。记忆技巧：对于骨折愈合标准，可概括为几个字：不痛、不动、看不清、负重不变形。需注意，过去的教材中还有一条标准：解除外固定后，上肢向前平举1kg重量达1分钟；下肢能不扶拐在平地连续步行3分钟，不少于30步，连续观察两周骨折处不变形。由于影像学技术的发展和负重实验本身所具有的一定危险性，负重试验已渐渐淡出临床，但是在老题目中出现相关选项时，仍旧可以作为备选答案。","","N"],["1999-N77",46,"第一节 手外伤","手外伤治疗原则",1999,77,"A","","关于手外伤清创术的处理原则，下列哪项不正确",[["A","力争在6～8小时内进行"],["B","最好在气囊止血带下进行"],["C","不能在有张力的情况下，勉强缝合伤口"],["D","创口方向纵行越过关节或与指蹼边缘平行时，应采用“Z”字成形术"],["E","软组织缺损较大有骨外露时，最好用游离植皮术"]],"E","清创应力争在6～8 小时内进行，可减少组织损伤，在细菌大量繁殖并入侵机体前清除其存在场所，将污染伤口变为清洁伤口。最好在气囊止血带下进行（B对），可减少手部创面的出血，使创面清楚易于清创。不能在有张力的情况下，勉强缝合伤口（C对），否则可能导致伤口的愈合缓慢甚至缝合处裂开，创口方向纵行穿过关节或与指蹼边缘平行时，应采用“Z”字成形术（D对），可预防后期环状瘢痕挛缩，避免影响手指的伸屈功能。软组织缺损较大有骨外露时，该处的血供往往不好，采用游离皮瓣移植（E错，为本题正确答案），皮瓣不易存活；正确的方法是采用皮瓣转移修复，即带蒂皮瓣移植。","","N"],["1999-N78",2,"第三节 自体输血和大量输血","自体输血",1999,78,"A","","关于自体输血，下列哪种说法是错误的",[["A","自体输血不会发生溶血、发热和过敏反应"],["B","当应用血液稀释回输的方法输血时，最好是先采的先输，后采的后输"],["C","脾破裂或异位妊娠破裂出血手术时，可采用自体失血回输"],["D","预存自体库血的输入时间一般不宜超过10日"],["E","胸、腹腔开放性损伤，超过4小时以上者，被认为自体输血的禁忌"]],"B","自体输血是指收集病人自身的血液或术中失血，然后回输本人的方法。优点是简便、安全、有效。由于是自身血液回输，因此无需检测血型和交叉配血，也不会发生溶血、发热和过敏反应（A对）。对于外伤性脾破裂、异位妊娠破裂造成的腹腔内出血，可收集血液，经抗凝、过滤后回输给病人（C对）。预存式自体输血可根据所需的预存血量，从择期手术前的一个月开始采血，每3～4天一次，每次300～400ml，直到手术前三天为止，本题D选项：预存自体库血的输入时间一般不宜超过10日也算正确（D对）。如是胸、腹开放性损伤超过4小时，发生污染的机会很大，应视为自体输血的禁忌证（E对）。对于自体输血来说，由于先采的血液中红细胞和凝血因子、纤维蛋白原等成分浓度均较高，随着自身补液使得后采血液相对稀薄；当回输入机体时，若将先采血液先回输，则会由于血液中各种成分浓度均高而可能引起循环内凝血机制激活，严重时甚至造成DIC，故自体输血应遵循“先采血后输，后采血先输”的原则（B错，为本题正确答案）。","","N"],["1999-N79",10,"第三节 全身麻醉","气管内插管",1999,79,"A","","关于气管内插管，下列哪项是不正确的",[["A","气管内插管插入过深时，极易插入左支气管"],["B","昏迷病人经口气管内插管，一般以维持24～28小时为限，超过此限应行气管切开"],["C","婴幼儿一般不用带套囊的导管"],["D","下颌发育不全的病人，通常经口腔明视插管操作是困难的"],["E","口腔内手术，经鼻腔插管手术方便"]],"A","主支气管向下分为左、右支气管，左侧支气管因心脏的影响，位置稍抬高，右侧支气管较陡直，故气管插管若操作不当，插入过深易进入右侧支气管（A错，为本题正确答案）。昏迷病人经口气管内插管，因插管及前部膨胀的气囊压迫局部气管壁，可能导致局部缺血损害，故一般以维持24～28小时为限，超过此限应行气管切开（B对）。经典认为年龄较小的儿童最好是采用无套囊的气管导管，以防止发生拔管后喘鸣；近年来的许多研究发现，应用带套囊的气管导管并未增加小儿拔管后喘鸣合并症的发生率，尤其是低压套囊导管的出现，另外，小儿声门下形状的变异亦相当明显。因此，目前这些观点已经不适用于现代临床（过去认为C正确，现该观点存在争议）。下颌发育不全的病人，因无法将口开合较大，通常经口无法直接观察声门，故此类病人口腔直视气管插管操作是困难的（D对）。口腔内手术，经鼻腔插管可为口腔内操作提供足够的空间和良好的视线，并防止异物进入气管，利于手术的进行（E对）。","","N"],["1999-N80",0,"第四节 手术室的管理","手术室的管理相关制度",1999,80,"A","","乙型肝炎表面抗原阳性病人所用的手术器械，术后使用哪种处理正确",[["A","2%戊二醛水溶液浸泡1小时"],["B","1：100新洁尔灭溶液浸泡2小时"],["C","0.2%过氧乙酸溶液泡30分钟"],["D","1：1000洗必泰溶液浸泡1小时，煮沸10分钟"],["E","1：1000新洁尔灭溶液浸泡2小时，煮沸20分钟"]],"A","老版教材里写明乙肝阳性病人手术后器械消毒可用2％戊二醛水溶液或0.2％过氧乙酸溶液浸泡1小时（A对C错）。1：1000新洁尔灭溶液浸泡2小时，煮沸20分钟（E错）为化脓性感染手术后器械的灭菌方法。该知识点已过时，正确操作应按照十版外科学所述。","","N"],["1999-N81",3,"第一节 外科休克概述","中心静脉压",1999,81,"A","","下列哪项关于中心静脉压的叙述是不正确的",[["A","中心静脉压的正常值是0．49～0．98kPa（5～10cmH₂O）"],["B","中心静脉压的变化一般比动脉压变化较晚"],["C","中心静脉压低于0．49kPa（5cmH₂O）时，表示血容量不足"],["D","中心静脉压高于1．47kPa（15cmH₂O）时，提示有肺循环阻力增加，心功能不全"],["E","中心静脉压受血容量、静脉血管张力等因素的影响"]],"B","中心静脉压（CVP）的正常值为5～10cm H₂O（A对）。当CVP﹤5cm H₂O时，表示血容量不足（C对）；当CVP＞15cmH₂O时，则提示心功能不全、静脉血管床过度收缩或肺循环阻力升高（D对）。血容量、静脉血管张力均可影响静脉回心血量，从而影响中心静脉压（E对）。在休克代偿期，机体有效循环血容量减少，回心血量减少，中心静脉压降低。但由于交感神经兴奋，心脏收缩增强，全身血管收缩，血压可维持正常。可见中心静脉压的变化一般比动脉压变化早（B错，为本题正确答案）。","","N"],["1999-N82",12,"第四节 急性呼吸窘迫综合征","急性呼吸窘迫综合征症状与体征",1999,82,"A","","下列哪项不是ARDS初期的临床表现",[["A","呼吸加快"],["B","呼吸窘迫感，用一般的吸氧法不能得以缓解"],["C","呼吸道分泌物增多，肺部有啰音"],["D","X线胸片一般无明显异常"],["E","PaO₂降至8.0kPa（60mmHg）"]],"C","急性呼吸窘迫综合征（ARDS）是指由各种肺内和肺外致病因素所导致的急性弥漫性肺损伤和进而发展的急性呼吸衰竭。ARDS早期的主要临床表现有：①咳嗽咳痰：咳出血水样痰是ARDS的典型表现；②呼吸频率增快（A对），呼吸做功增加和顽固性低氧血症，有呼吸窘迫感，用一般的吸氧法不能得以缓解（B对），PaO₂降至8.0kPa（60mmHg）（E对）；③无明显的呼吸困难，肺部听诊无啰音（C错，为本题正确答案），X线胸片一般无明显异常（D对）。ARDS继续发展可出现严重呼吸困难和听诊出现干性或湿性啰音。","","N"],["1999-N83",6,"第二节 创伤的病理生理","影响创伤愈合的因素",1999,83,"A","","下列哪项因素有利于创伤修复和伤口愈合",[["A","细菌感染"],["B","血流循环障碍"],["C","异物存留"],["D","局部制动"],["E","服用皮质激素类药物"]],"D","细菌感染可损害细胞和基质，导致局部炎症持久不易消退，甚至形成化脓性病灶等，对创伤愈合产生不利影响（A错）。血流循环障碍，创伤部分得不到足够的血流灌溉，组织细胞增生、分化缺乏足够的营养及氧供，不利于愈合（B错）。异物存留，伤缘往往不能直接对合，且被新生细胞和基质连接阻隔，必然影响修复（C错）。皮质激素类药物有伤口愈合延缓的副作用，属于细胞增生抑制剂（E错）。正确的局部制动，使得愈合中的伤口避免了因运动导致的新生组织的再度损伤，有利于创伤的愈合（D对）。","","N"],["1999-N84",11,"第四节 慢性疼痛的诊断和治疗","药物治疗",1999,84,"A","","下列哪项不符合世界卫生组织提出癌症三阶梯止痛治疗方案的原则",[["A","最初用非吗啡类药，效果不好时，追用吗啡类药"],["B","从小剂量开始"],["C","痛时给药"],["D","吗啡类药物效果不好时，考虑药物以外的治疗"],["E","口服为主"]],"C","世界卫生组织推荐的癌症三阶梯止痛疗法：①按药效的强弱依阶梯方式顺序使用：非阿片类药物（如阿司匹林）→弱阿片类药（如可待因）→强阿片类药（如吗啡）+辅助用药（如安定、氯丙嗪等）（A对）；②尽量使用口服给药（E对）。口服给药→直肠给药→注射给药；③按时给药（C错，为本题正确答案）；④用药剂量个体化，应用时从小剂量开始，逐渐加大剂量（B对）。吗啡类药物不再有效时，便需考虑药物以外的治疗，主要包括椎管内注药和放、化疗及激素疗法（D对）。椎管内注药主要是硬膜外注射吗啡麻醉神经根，或蛛网膜下隙内注射神经损毁性药物（苯酚、无水乙醇等），彻底毁坏痛觉传导神经，缓解疼痛；放化疗及激素疗法针对的是对此种治疗敏感的癌症细胞引起的疼痛，本身也是治疗癌症的方法。","","N"],["1999-N85",17,"第一节 甲状腺疾病","甲亢手术指征",1999,85,"A","","女性，30岁，妊娠6周发生甲状腺机能亢进，甲状腺肿大伴有局部压迫症状，选择下列哪项治疗最恰当",[["A","服用抗甲状腺药物"],["B","终止妊娠后，服用抗甲状腺药物"],["C","终止妊娠后，手术治疗"],["D","终止妊娠后，¹³¹I治疗"],["E","不终止妊娠，手术治疗"]],"E","甲亢手术指征为：①继发性甲亢或高功能腺瘤；②中度及中度以上的原发性甲亢；③腺体较大，伴有压迫症状，或胸骨后甲状腺肿等类型甲亢；④抗甲状腺药物或¹³¹I治疗后复发者或坚持长期用药有困难者；⑤怀疑或证实合并甲状腺恶性肿瘤。老年病人或有严重器质性疾病不能耐受手术为手术绝对禁忌证，而妊娠早、晚期为手术相对禁忌证。该患者为妊娠6周发生的甲亢，属于妊娠早期甲亢，且存在压迫症状，应及时手术治疗（E对），否则可能会导致流产、早产、胎儿宫内死亡以及妊高症等，而妊娠又可能加重甲亢，因此在妊娠早中期，仍应考虑手术治疗；到妊娠晚期，甲亢与妊娠之间的相互影响已经不大，则可待分娩后再行手术。","","N"],["1999-N86",18,"第四节 乳腺癌","临床表现",1999,86,"A","","乳癌局部检查中，下列哪项体征提示预后最差",[["A","乳头抬高、内陷"],["B","癌块表面皮肤凹陷"],["C","局部皮肤充血、发红，呈现急性炎症改变"],["D","乳头、乳晕湿疹样改变"],["E","局部皮肤“桔皮样”改变"]],"C","本例已确诊乳腺癌，检查时局部皮肤充血、发红，呈现急性炎症改变，此为炎性乳癌的征象，此病并不多见，特点是发展迅速、预后差（C对）。乳头抬高、内陷（A错）为乳头深部肿块累及乳头下乳管所致。癌块表面皮肤凹陷（B错）称酒窝征，为癌肿累及Cooper韧带所致。乳头、乳晕湿疹样改变（D错）为乳头湿疹样乳腺癌（Paget病）的特征性病变，此病恶性程度低，发展慢。局部皮肤“橘皮样”改变（E错）为乳癌累及表浅淋巴管所致。","","N"],["1999-N87",23,"第四节 其他腹外疝","其他腹外疝切口疝",1999,87,"A","","发生切口疝最主要的病因是",[["A","腹部手术切口为纵行切口"],["B","切口过长，缝合不够严密，对合差"],["C","引流物放置过久"],["D","切口发生感染"],["E","病人术后腹胀"]],"D","切口疝是发生于腹壁手术切口处的疝，比较常见，占腹外疝的第3位。腹部手术后切口获得一期愈合者，切口疝的发病率通常在1%以下，如切口发生感染，则发病率可达10%。切口感染导致腹壁组织破坏，腹壁强度明显减退。因此切口发生感染（D对）是发生切口疝的最主要原因。腹部纵行切口（A错）；切口过长，缝合不够严密，对合差（B错）；引流物放置过久（C错）；术后腹胀均可造成缝合线张力大、伤口愈合差，而使得切口疝易于产生，但并不是最常见的原因。","","N"],["1999-N89",28,"第二节 急性阑尾炎","急性阑尾炎体征",1999,89,"A","","下列可协助诊断急性阑尾炎的体征中，哪项不正确",[["A","右下腹固定压痛是阑尾炎的主要体征"],["B","右下腹腹膜刺激征提示阑尾炎症已不是早期阶段"],["C","腰大肌试验阳性提示阑尾位置较深"],["D","闭孔内肌试验阳性提示阑尾位置较低"],["E","结肠充气试验阴性可排除阑尾炎诊断"]],"E","结肠充气试验是急性阑尾炎的辅助诊断的体征，检查时检查者先用一手压降结肠，再以另一手压近侧结肠，并逐步向近侧结肠移动，将结肠内气体赶向盲肠和阑尾，引起右下腹痛者为阳性，可提示为急性阑尾炎，但阴性也不能排除诊断（E错，为本题正确答案）。右下腹固定压痛是阑尾炎的主要体征（A对），急性阑尾炎典型的腹痛发作始于上腹，逐渐移向脐部，数小时（6～8 小时）后转移并局限在右下腹。此过程的时间长短取决于病变发展的程度和阑尾位置。腹膜刺激征是指病人出现腹部压痛、反跳痛和腹肌紧张，这是壁层腹膜受炎症刺激的防卫性反应，提示阑尾炎症加重，出现化脓、坏疽或穿孔等病理改变，已不再属于早期阶段（B对）。腰大肌征阳性是嘱患者左侧卧位，使右大腿后伸，引起右下腹疼痛者。说明炎症阑尾可能位于腰大肌前方，盲肠后位或腹膜后位，位置较深（C对）。闭孔内肌试验阳性是病人仰卧位，使右髋和右大腿屈曲，然后被动向内旋转，引起右下腹疼痛者。提示阑尾炎位置靠近腹腔内较低位置的闭孔内肌（D 对）。","","N"],["1999-N90",30,"第二节 肝脓肿","细菌性肝脓肿病因和病理",1999,90,"A","","关于细菌性肝脓肿，下列哪项叙述正确",[["A","大部分是胆源性肝脓肿"],["B","致病菌多为革兰氏阴性球菌"],["C","脓液多为棕褐色，涂片可能无细菌"],["D","多见于右叶，单发"],["E","手术引流是唯一有效的方法"]],"A","（七版黄家驷外科学P1685）胆囊炎、胆管炎及各种原因引起的胆道（A对）感染诱发的细菌性肝脓肿约占肝脓肿的21.6%-51.5%，可以认为，细菌性肝脓肿大部分是胆源性肝脓肿。细菌性肝脓肿的最常见致病菌为大肠杆菌（革兰氏阴性杆菌）、厌氧链球菌及葡萄球菌（B错）。细菌性肝脓肿的脓液多为黄白色脓液，涂片和培养可发现细菌。脓液多为棕褐色，涂片可能无细菌（C错）为阿米巴性肝脓肿的特征。细菌性肝脓肿脓腔较小，常为多发性。多见于右叶，单发（D错）为阿米巴性肝脓肿的特征。手术切开引流具有其适应证（十版外科学P458）：适用于较大脓肿，估计有穿破可能，或已穿破胸腔或腹腔；胆源性肝脓肿；位于肝左外叶脓肿，穿刺易污染腹腔；以及慢性肝脓肿。经及时抗感染治疗，小脓肿多能吸收消失。经皮肝穿刺脓肿置管引流术适用于单个较大的脓肿。可见，手术并非唯一有效的方法（E错）。","","N"],["1999-N91",31,"门静脉高压","断流手术",1999,91,"A","","门脉高压症行分流术或断流术的主要目的是",[["A","改善肝功能"],["B","预防和控制食管胃底曲张静脉破裂大出血"],["C","治疗腹水"],["D","治疗肝性脑病"],["E","治疗脾功能亢进"]],"B","门脉高压症行分流术或断流术的主要目的是预防和控制食管胃底曲张静脉破裂大出血（B对）。门体分流术可降低门静脉压力，减少甚至消除交通支静脉的曲张；断流术可阻断门奇静脉间的反常血流，以达到止血目的。分流术导致进入肝脏的血流减少，可加重肝功能损害（A错），而断流术对进入肝脏的的血流影响较小，对肝功影响较小；对潴水类激素的灭活进一步减少，白蛋白生成降低，可加剧腹水形成（C错）。分流术后，含致肝性脑病物质（肠道内的氨、部分蛋白质的代谢产物）的大量血液未经肝脏的解毒作用，直接进入体循环，影响脑功能，可引起或加重肝性脑病，而断流术术后肝性脑病的发生率变化不大（D错）。分流术或断流术均不能治疗脾功能亢进（E错），脾功能亢进的治疗措施为脾切除术。","","N"],["1999-N92",22,"第三节 动脉疾病","血栓闭塞性脉管炎检查",1999,92,"A","","下述哪种表现不是血栓闭塞性脉管炎的特点",[["A","病人多为男性青壮年"],["B","病变主要侵袭四肢中、小动静脉"],["C","肢体缺血症状多是周期性发作"],["D","反复发作游走性浅静脉炎"],["E","X线检查显示动脉有钙化斑"]],"E","血栓闭塞性脉管炎，是一种慢性、非粥样硬化性、节段性、炎性、闭塞性、与吸烟相关的血管疾病。主要侵袭腘动脉以及肱动脉以远的中、小动静脉（B对），本病常侵及邻近的或表浅的静脉或神经，病人多为男性青壮年（A对），多有长期吸烟史。其主要病理特点是动脉血栓形成及受累动静脉的非化脓性炎症。发病前或发病过程中出现复发性游走性浅静脉炎（D对），肢体缺血症状多是周期性发作（C对），可由寒冷潮湿环境诱发，肢体复温后可稍缓解。在影像学检查中，受累血管壁的钙化在X片中往往显示不清。X线检查显示动脉有钙化斑（E错，为本题正确答案）常见于动脉硬化性闭塞症，钙盐可沉积于发生粥样硬化的动脉壁内，属于营养不良性钙化。","","N"],["1999-N111",57,"第三节 骨巨细胞瘤","骨巨细胞瘤概述",1999,111,"B","","骨巨细胞瘤好发于",[["A","骨干"],["B","骨干骺端"],["C","骨骺"],["D","骨端"],["E","骨髓"]],"B","骨巨细胞瘤好发于20～40岁，女性略多，好发部位为长骨干骺端（B对）和椎体，特别是股骨远端和胫骨近端，这是十版外科学的最新观点。按照旧版本教材，该题D选项正确。","","N"],["1999-N112",57,"第二节 良性骨肿瘤","骨软骨瘤",1999,112,"B","","骨软骨瘤好发于",[["A","骨干"],["B","骨干骺端"],["C","骨骺"],["D","骨端"],["E","骨髓"]],"B","骨软骨瘤好发于长骨干骺端（B对），如股骨远端、胫骨近端和肱骨近端。常考好发部位总结如下：骨瘤好发于颅骨和下颌骨；内生软骨瘤好发于手足的短管状骨；骨样骨瘤好发于长骨；最常见于股骨、胫骨和肱骨的骨干和骨骺端；骨巨细胞瘤好发于长骨末端如股骨下端、胫骨上端；骨肉瘤好发于四肢长骨，尤其是股骨远端、胫骨近端和肱骨近端；软骨肉瘤好发于骨盆，以髂骨最常见；Ewing肉瘤好发于长骨骨干和干骺端、盆骨、肋骨；骨纤维肉瘤好发于四肢长骨干骺端偏骨干，以股骨多见。","","N"],["1999-N113",8,"","",1999,113,"B","","华支睾吸虫",[["A","与大肠癌有关"],["B","与宫颈癌有关"],["C","与肝癌有关"],["D","与鼻咽癌有关"],["E","与白血病有关"]],"C","华支睾吸虫主要寄生部位为次级胆管，可引起胆管内膜及胆管周围的超敏反应及炎性反应，长期慢性刺激可引起胆管上皮细胞异形增生而致癌变，主要为腺癌（C对）。华支睾吸虫引起的原发性肝癌以胆管细胞癌为主。与大肠癌有关（A错）的是日本血吸虫感染；与宫颈癌有关（B错）的是单纯疱疹病毒感染；与鼻咽癌有关（D错）的是EB病毒感染；与白血病有关（E错）的C型RNA病毒感染或者丙种球蛋白缺乏。","","N"],["1999-N114",8,"","",1999,114,"B","","单纯疱疹病毒反复感染",[["A","与大肠癌有关"],["B","与宫颈癌有关"],["C","与肝癌有关"],["D","与鼻咽癌有关"],["E","与白血病有关"]],"B","单纯疱疹病毒（HSV-2型）（B对）反复感染是宫颈癌的潜在致癌因子。患过生殖器单纯疱疹的妇女比未患过者得宫颈癌的危险性高5～10倍。研究表明，宫颈癌组织，剥脱细胞或癌前期细胞中均可检测出HSV-2特异性抗原。与大肠癌有关（A错）的是日本血吸虫感染；与肝癌有关（C错）的是华支睾吸虫感染和乙肝病毒感染；与鼻咽癌有关（D错）的是EB病毒感染；与白血病有关（E错）的C型RNA病毒感染或者丙种球蛋白缺乏。","","N"],["1999-N115",27,"","",1999,115,"B","","发生炎性息肉最多见于",[["A","溃疡性结肠炎"],["B","肠阿米巴病"],["C","肠结核"],["D","肠克罗恩病"],["E","血吸虫病"]],"A","小肠内各种疾病有其各自的特点，抓住这些特点往往是解题的关键。溃疡性结肠炎（A对）为发生在结直肠黏膜和黏膜下的弥漫性炎症性改变，以直肠和乙状结肠最为常见。表现为黏膜大片水肿、充血、糜烂和溃疡形成，长期慢性炎症刺激易导致炎性息肉的产生，为几种疾病中炎性息肉发生最多见的疾病；肠阿米巴病（B错）是由溶组织内阿米巴所引起的疾病，好发部位依次为盲肠、升结肠、乙状结肠和直肠，典型病变为烧瓶样溃疡；肠结核（C错）多继发于肺结核之后，病变主要发生于回盲部，病变开始于肠壁淋巴结，有溃疡型和增生型两种。溃疡型可表现为腹泻，增生型可表现为便秘，也可腹泻和便秘交替出现，肠鸣音多亢进，溃疡急性穿孔少，慢性穿孔可形成局限性脓肿，甚至形成瘘；肠克罗恩病（D错）的特征是肠壁全层受累，为非特异性肉芽肿性疾病，表现为裂沟状深溃疡，黏膜呈鹅卵石样形状，病变呈跳跃式，肠腔狭窄、管壁僵硬，近端肠管扩张，而狭窄部呈线状征，溃疡穿孔可形成内瘘或外瘘，具有潜在恶变可能；慢性血吸虫病（E错）时，大肠黏膜下常有血吸虫卵沉着，其周围伴纤维组织增生，或形成虫卵结节，具有很大恶变倾向。肠阿米巴病、肠克罗恩病、肠结核、血吸虫病一般不引起炎性息肉。","","N"],["1999-N116",27,"第三节 非感染性肠疾病","克罗恩病病理",1999,116,"B","","发生肠内瘘可见于",[["A","溃疡性结肠炎"],["B","肠阿米巴病"],["C","肠结核"],["D","肠克罗恩病"],["E","血吸虫病"]],"D","小肠内各种疾病有其各自的特点，抓住这些特点往往是解题的关键。肠克罗恩病（D对）的特征是肠壁全层受累，为非特异性肉芽肿性疾病，表现为裂沟状深溃疡，黏膜呈鹅卵石样形状，病变呈跳跃式，肠腔狭窄、管壁僵硬，近端肠管扩张，而狭窄部呈线状征，溃疡穿孔可形成内瘘或外瘘，具有潜在恶变可能；溃疡性结肠炎（A错）为发生在结直肠黏膜和黏膜下的弥漫性炎症性改变，以直肠和乙状结肠最为常见。表现为黏膜大片水肿、充血、糜烂和溃疡形成，长期慢性炎症刺激易导致炎性息肉的产生，为几种疾病中炎性息肉发生最多见的疾病；肠阿米巴病（B错）是由溶组织内阿米巴所引起的疾病，好发部位依次为盲肠、升结肠、乙状结肠和直肠，典型病变为烧瓶样溃疡；肠结核（C错）多继发于肺结核之后，病变主要发生于回盲部，病变开始于肠壁淋巴结，有溃疡型和增生型两种。溃疡型可表现为腹泻，增生型可表现为便秘，也可腹泻和便秘交替出现，肠鸣音多亢进，溃疡急性穿孔少，慢性穿孔可形成局限性脓肿，甚至形成瘘；慢性血吸虫病（E错）时，大肠黏膜下常有血吸虫卵沉着，其周围伴纤维组织增生，或形成虫卵结节，具有很大恶变倾向；肠结核、克罗恩病均可形成内瘘，而常见者为克罗恩病，此题若改为“发生肠内瘘多见于”为妥。溃疡性结肠炎和克罗恩病共称为非特异性炎症性肠病。","","N"],["1999-N135",53,"","",1999,135,"C","","颈椎病脊髓型",[["A","颏枕带牵引"],["B","推拿按摩"],["C","两者均可用"],["D","两者均不可用"]],"D","脊髓型颈椎病容易引起肢体不同程度的残疾，脊髓长期受压迫及反复刺激后手术治疗效果不良，故一旦诊断明确，应早期手术治疗。脊髓型颈椎病禁用颌枕带牵引（A错）和推拿按摩（B错），否则可能导致脊髓损伤引起瘫痪。本题AB均错，正确答案为D。","","N"],["1999-N136",53,"第一节 颈椎退行性疾病","颈椎病非手术治疗",1999,136,"C","","颈椎病神经根型",[["A","颏枕带牵引"],["B","推拿按摩"],["C","两者均可用"],["D","两者均不可用"]],"C","神经根、交感、椎动脉型颈椎病首选保守治疗，包括颈椎牵引、理疗、改善不良工作体位和睡眠姿势。颏枕带牵引（A对）可解除肌痉挛，增大椎间隙，减小椎间盘压力，减少对神经根的刺激。推拿按摩（B对）亦可减轻肌痉挛，改善局部血运，缓解症状。颈椎病手术指征为：①经合理的保守治疗，半年以上无效，或反复发作，并影响正常正常生活或工作，而且同意手术治疗；②神经根性疼痛剧烈，严重地影响生活，保守治疗2周仍不减轻；③上肢某些肌肉，尤其是手内肌无力、萎缩，保守治疗4～6周仍有发展趋势。本题AB均对，正确答案为C。","","N"],["1999-N137",5,"第二节 浅部组织细菌性感染","急性蜂窝织炎病因和病理",1999,137,"C","","急性蜂窝织炎的致病菌为",[["A","溶血性链球菌"],["B","厌氧性细菌"],["C","两者均可"],["D","两者均不可"]],"C","通常，急性蜂窝织炎为非特异性感染，主要由溶血性链球菌、金葡菌等引起；但是对于产气性皮下蜂窝织炎来说，以厌氧菌感染为主，如肠球菌、兼性大肠埃希菌、变形杆菌、拟杆菌或产气荚膜梭菌等，多见于下腹与会阴部。故急性蜂窝织炎的致病菌为溶血性链球菌、厌氧性细菌均可。本题AB均对，正确答案为C。","","N"],["1999-N138",5,"第二节 浅部组织细菌性感染","急性淋巴管炎和淋巴结炎病因和病理",1999,138,"C","","急性淋巴管炎和急性淋巴结炎的致病菌为",[["A","溶血性链球菌"],["B","厌氧性细菌"],["C","两者均可"],["D","两者均不可"]],"A","溶血性链球菌是常见的非特异性感染致病菌，可引起急性蜂窝织炎、急性淋巴管炎和淋巴结炎等多种浅表感染性疾病；急性淋巴管炎和淋巴结炎极少由厌氧菌感染引起，可能是因为位置较为表浅，以及厌氧菌的侵袭力在浅表组织不强的原因有关（A对）。","","N"],["1999-N157",44,"第五节 影响骨折愈合的因素","不当的治疗方法影响骨折愈合",1999,157,"X","","因治疗不当，影响骨折正常愈合过程的因素有",[["A","反复多次的手法复位"],["B","复位不满意，对线差"],["C","固定不确实"],["D","过早的和不恰当的功能锻炼"]],"ACD","反复多次的手法复位（A对）可损伤局部软组织和骨外膜，影响骨组织血供，不利于骨折愈合。固定不确实（C对），骨折仍可受到剪切力和旋转力的影响，干扰骨痂生长，不利于骨折愈合。过早的和不恰当的功能锻炼（D对）可能妨碍骨折部位的固定，影响骨折的愈合。复位不满意，对线差（B错）可导致骨折畸形愈合、塑型差，但亦属正常愈合过程。","","N"],["1999-N158",3,"第一节 外科休克概述","炎症介质释放和缺血再灌注损伤",1999,158,"X","","下列哪些疾病易继发多系统器官衰竭",[["A","心肺复苏术后"],["B","大面积烧伤并感染"],["C","急性出血坏死性胰腺炎"],["D","肝硬化门脉高压症"]],"ABC","多器官功能障碍综合征（MODS），是指在严重创伤、感染和休克时，原无器官功能障碍的患者同时或者在短时间内相继出现两个以上器官系统的功能障碍以致机体内环境的稳定必须靠临床干预才能维持的综合征。MODS的病因有：①各种外科引起的脓毒症；②严重的创伤、烧伤（B对）或大手术致失血、缺水；③各种原因的休克，心跳、呼吸骤停复苏后（A对）；④各种原因导致肢体、大面积的组织或器官缺血-再灌注损伤；⑤合并脏器坏死或感染的急腹症（C对）；⑥输血、输液、药物或机械通气；⑦患某些疾病的病人更容易发生MODS，如心脏、肝、肾的慢性疾病，糖尿病，免疫功能低下。","","N"],["1999-N159",32,"第四节 胆石症","胆囊结石治疗",1999,159,"X","","腹腔镜胆囊切除术的适应证是",[["A","急性胆囊炎"],["B","慢性胆囊炎、胆囊结石"],["C","胆囊息肉"],["D","胆管结石"]],"BC","以前的观点认为急性胆囊炎（A错）因局部充血、肿胀明显，不适宜腹腔镜胆囊切除，但按照现在的观点来看，急性胆囊炎早期可以行腹腔镜胆囊切除术，故A选项存在争议。慢性胆囊炎、胆囊结石（B对）及胆囊息肉（C对）的患者须及早手术治疗，否则有癌变可能，常见术式为经腹腔镜胆囊切除术。胆管结石（D错）需行胆总管切开取石、T管引流术，可采用开腹或腹腔镜手术，若患者合并胆囊结石，才行腹腔镜胆囊切除术。","","N"],["1999-N160",31,"门静脉高压","腹水",1999,160,"X","","下列哪些是门脉高压症腹水形成的因素",[["A","门静脉毛细血管床的滤过压增加"],["B","肝内淋巴液回流不畅，自肝表面漏入腹腔"],["C","肝功能减退，血浆白蛋白合成障碍，致血浆胶体渗透压降低"],["D","肾上腺皮质的醛固酮和垂体后叶的抗利尿激素增多，致钠和水的潴留"]],"ABCD","门静脉压力增高，使门静脉毛细血管床的有效滤过压增高，组织液回收减少并漏入腹腔而形成腹水（A对）。肝硬化结节在肝窦和窦后造成阻塞时，肝内淋巴的产量增多，但回流不畅，大量肝内淋巴自肝包膜表面漏入腹腔（B对）。但造成腹水生成更主要原因是肝功能的损害，血浆白蛋白的合成减少，引起血浆胶体渗透压降低（C对），而促使血浆外渗。门静脉高压时，大量液体外渗，中心血流量却是减少的，继发刺激醛固酮分泌过多，导致钠、水潴留而加剧腹水形成。此外，肝功能减退使肾上腺皮质分泌的醛固酮和神经垂体释放的抗利尿激素在肝内分解减少，血内水平升高，促进肾小管对钠和水的重吸收，因而引起钠水潴留（D对）。","","N"],["2000-N62",34,"第一节 上消化道大出血的诊断和处理","应激性溃疡或急性糜烂性胃炎",2000,62,"A","","Curling ulcer是指下列哪些原因引起者",[["A","大手术"],["B","休克"],["C","大面积烧伤"],["D","颅内病变"],["E","严重的脏器疾病"]],"C","Curling溃疡又称柯林溃疡，是指不同程度烧伤后继发的应激性溃疡（C对），临床上早期除偶有腹部隐痛和黑便外，其他症状甚少，多在发生大出血或穿孔后被发现，出血和穿孔时间多在烧伤后1～3周。颅内病变（D错）为Cushing溃疡的病因。","","N"],["2000-N75",12,"第二节 心肺脑复苏","胸外按压",2000,75,"A","","成人心肺复苏时，胸外心脏按压的频率应为",[["A","50～60次/分"],["B","60～80次/分"],["C","80～100次/分"],["D","100～120次/分"],["E","120～140次/分"]],"D","心肺复苏（CPR）是指针对呼吸和心搏骤停所采取的紧急医疗措施，以人工呼吸代替病人的自主呼吸，以心脏按压形成暂时的人工循环并诱发心脏的自主搏动，胸外按压频率为100～120 次/分（D对）。现在认为，仅仅恢复自主呼吸和心跳是不够的，更重要的是恢复中枢神经系统功能，心肺复苏扩展为心肺脑复苏（CPCR）。有关心胸外心脏按压相关数据（十版外科学：按压位置为胸骨下1/2处，即两乳头连线中点的胸骨上，按压频率为100～120次/分）。本题原答案根据旧版教材数据（5版外科学80～100次/分）选择C。","","N"],["2000-N76",10,"第四节 局部麻醉","锁骨上径路",2000,76,"A","","锁骨上神经阻滞是阻滞了臂丛神经的哪一部分",[["A","根"],["B","干"],["C","股"],["D","束"],["E","支"]],"B","臂丛神经来源于颈5-8及胸1脊神经根的前支组成，主要支配上肢的感觉和运动。这些脊神经自椎间孔发出后，经过前、中斜角肌之间的肌间沟，在此相互合并形成臂丛神经干，后从锁骨上方第一肋骨面上横过而进入腋窝，并在腋窝形成主要终末神经，即正中神经、桡神经、尺神经和肌皮神经。锁骨上径路阻滞的穿刺点位于锁骨中点上方1cm，根据局部解剖知识可知，锁骨上神经阻滞主要阻滞的是臂丛神经干（B对）。","","N"],["2000-N77",3,"第一节 外科休克概述","心血管活性药物的应用",2000,77,"A","","病人休克，血压低，脉搏130次/分，尿量20ml/h，选用哪种血管活性药物最适宜",[["A","多巴胺"],["B","去甲肾上腺素"],["C","异丙肾上腺素"],["D","肾上腺素"],["E","苯肾上腺素（新福林）"]],"A","多巴胺是最常用的血管收缩剂，具有兴奋α、β₁和多巴胺受体的作用。小剂量多巴胺主要兴奋β₁和多巴胺受体，增加心肌收缩力、增加心排出量，并扩张肾脏及胃肠道血管，有保护肾功能的作用，故作为治疗休克的首选（A对），尤其适用于合并肾功能不全者。在使用多巴胺血压无法上升时才选择联用其他血管活性药物如去甲肾上腺素（B错）、异丙肾上腺素（C错）等，而不加大多巴胺的剂量，因可使全身血管收缩、血压上升的同时保护心脏、肾脏的基本血供。休克早期，微循环处于收缩状态，临床上较少使用血管收缩剂（如去甲肾上腺素、肾上腺素（D错）、新福林（E错）等）。异丙肾上腺素为β受体兴奋剂，可增加心肌收缩力、加快心率，且易导致心律失常，更应慎用。","","N"],["2000-N78",0,"第三节 手术进行中的无菌原则","手术进行中的无菌原则",2000,78,"A","","甲状腺手术后，术者手套有破口，接连施行手术时，术者双手应如何消毒",[["A","加戴无菌手套、穿无菌衣"],["B","仅更换手套"],["C","更换手套，更换手术衣"],["D","重新洗手，时间缩短为1分钟"],["E","重新洗手"]],"E","此题书本上无统一叙述，通常在无菌手术后手套未破，连续施行一手术时不必重新刷手，仅浸泡酒精5分钟穿手术衣、戴手套。仅对于无菌手术采取此法，对于有可能被污染的手术（如感染灶的处理或胃肠道手术），进行下一台手术时需重新洗手并进行手消毒。手术过程中若手套有破损，则无论是否为无菌手术都要重新进行洗手、消毒。本题甲状腺手术后，术者手套有破口，接连施行手术时，为上述第三种情况，只要有破损就要重新洗手（E对）、消毒并更换手套。","","N"],["2000-N79",1,"第一节 水、电解质代谢紊乱和酸碱平衡失调概述","细胞内液",2000,79,"A","","下列有关体液的叙述，哪项是正确的",[["A","成年女性的体液量约占体重的60%"],["B","细胞内液量在男性约占体重的40%，绝大部分存在于骨骼肌中"],["C","血浆约占体重的10%"],["D","脑脊液、关节液、消化液等都属功能性细胞外液"],["E","细胞外液和细胞内液的渗透压一般为260～280mmol/L"]],"B","上述知识点整合如下：成年男性体液量占体重60%，女性占50%（A错）。细胞内液，男性占体重40%，女性占35%，绝大部分存在于骨骼肌中（B对）。细胞外液，男女均占体重20%。在细胞外液中，血浆占体重5%（C错），组织液占体重15%。还有极小部分的无功能性细胞外液，包括脑脊液、关节液、消化液和结缔组织液等（D错）。细胞外液和细胞内液的渗透压一般为280～310mOsm/L（E错）。","","N"],["2000-N80",4,"第三节 肠外营养","肠外营养制剂",2000,80,"A","","下列哪项不符合全胃肠外营养所用的营养液的要求",[["A","每日供氮应达0.2～0.24g/kg体重"],["B","氮（g）和热量（kcal）之比为1：100"],["C","含有适量的电解质、维生素和微量元素"],["D","适量补充胰岛素和脂肪乳剂"],["E","所补充的必需氨基酸和非必需氨基酸的含量一般应为1：2"]],"B","肠外营养是指通过胃肠道以外途径（即静脉途径）提供营养支持的方式。凡是需要营养支持，但又不能或不宜接受肠内营养支持的病人均为肠外营养支持的适应证。正常状态下所需要的热量为25～30kcal/（kg·d），氨基酸为1.2～2.0（折合供氮量0.19～0.32g/kg）（A对），氮（g）和热量（kcal）之比约为1:100～150（B错，为本题正确答案），含有适量的电解质、维生素和微量元素的肠外营养液能够补充多种人体所需的非能量供应物质（C对）。葡萄糖是肠外营养主要的能量来源，但是葡萄糖的代谢必须依赖胰岛素；且使用大量高渗葡萄糖作为单一的能源会产生某些有害的结果，脂肪乳剂可提供能量、生物合成碳原子及必须脂肪酸，适量补充胰岛素和脂肪乳剂十分必要（D对）。复方氨基酸溶液是提供生理性氮源的制剂，由于各种蛋白质由特定的氨基酸组成，因此输入的氨基酸溶液中各种氨基酸的配比应该合理，必需氨基酸和非必需氨基酸的含量一般为1：2（E对）。","","N"],["2000-N81",17,"第四节 颈部肿块","颈部肿块概述",2000,81,"A","","下列关于颈部肿块的叙述，哪项不正确",[["A","甲状腺腺瘤是颈部原发性肿瘤之一"],["B","甲状腺舌管囊肿是先天性畸形"],["C","颈部恶性肿瘤的3/4是转移性肿瘤"],["D","颈部肿块发生坏死、溃破、感染时是颈部淋巴结结核"],["E","囊状淋巴管瘤是位于颈侧区的单发性肿物"]],"D","颈部肿块按病因可分为先天性疾病、炎性肿块、肿瘤三类。甲状腺腺瘤是起源于甲状腺滤泡细胞的良性肿瘤（A对），是甲状腺最常见的良性肿瘤，患者多为女性，年龄常在40岁以下，一般为甲状腺体内的单发结节。甲状舌管囊肿是指在胚胎早期甲状腺发育过程中甲状舌管退化不全、不消失而在颈部遗留形成的先天性囊肿，为一种先天性畸形（B对），以男性居多，好发于儿童和青少年，约50%的病例发生于20岁之前。绝大多数患者可见颈前肿物，但以舌骨上、下部位为最常见。转移性肿瘤约占颈部恶性肿瘤的3/4（C对），以鼻咽癌和甲状腺癌转移最常为多见。囊状淋巴管瘤又称囊状水瘤，多在出生时即可见到颈部肿物，多发生于胸锁乳突肌后缘的锁骨上窝处，颈后三角（颈侧区）为好发部位，多为单发（E对），触之柔软，有囊状感，波动感明显，无触痛，边缘多不清楚。颈部肿块发生坏死、溃破、感染不一定只是颈部淋巴结结核，肿瘤、淋巴结炎亦可（D错，为本题正确答案）。","","N"],["2000-N83",17,"第一节 甲状腺疾病","病史",2000,83,"A","","甲状腺单发结节最应警惕恶性的年龄段为",[["A","儿童"],["B","年轻男性"],["C","妊娠妇女"],["D","40岁以下妇女"],["E","老年人"]],"A","一旦发现甲状腺结节，应仔细地从病史和体检来分析是否有恶性的可能。多数甲状腺结节隐匿生长，被发现时并无症状，但不能以此除外恶性。病史中应注意询问肿块生长速度，结节在数月内持续增长，应怀疑恶性。若短期内明显增大，老年病人应考虑有未分化癌的可能。如果结节肿大不明显，但合并声音嘶哑，吞咽困难，咳嗽气短者，或既往有甲状腺癌病史，又出现结节者，则高度提示为恶性。一般来讲，对于甲状腺结节，男性更应得到重视。体检的重点在甲状腺结节的特性和颈部淋巴结的情况。如果甲状腺结节质地坚硬，边界不清，活动度差，应怀疑为恶性，质地硬是最主要的特点。如伴有同侧的颈部淋巴结肿大或声带麻痹，则应高度怀疑为恶性。儿童（A对）甲状腺的单发结节尤其应警惕恶性可能，恶变率约50%。","","N"],["2000-N84",24,"第一节 腹部损伤概述","腹部损伤分类",2000,84,"A","","下列哪项关于腹部损伤的叙述是正确的",[["A","因多数腹部损伤涉及内脏而伤情严重，死亡率一般在30%以上"],["B","有腹膜破损者为穿透伤（多伴内脏损伤）"],["C","涉及内脏的开放性损伤，诊断常较困难"],["D","穿透伤的入、出口与伤道呈一条直线"],["E","伤口大小与伤情严重程度成正比"]],"B","腹部损伤可分为开放性损伤和闭合性损伤两类。其中，有腹膜破损者为穿透伤（多伴内脏损伤）（B对）（腹膜为腹腔表层的膜性组织，穿透后便意味着外界致伤物进入腹腔，腹腔内脏器均易受损伤）；无腹膜破损者为非穿透伤（偶伴内脏损伤）。近年来在伤员运送、复苏、监护及器官功能支持以及处理某些特殊脏器损伤方面取得了进展，使得腹部损伤的死亡率不断下降。A选项各类教材均无明确数值，但经过现代医疗救治的病人，其死亡率一般不会达到30％以上（A错）。腹部开放伤，由于伤口比较明显，一般都能得到及时的诊断和处理（C错）。不能把伤道想象为连接入、出口的直线来估计有无以及哪些脏器受伤，投射物常在行进中改变方向，病人在受伤瞬间的姿势也对伤道的走行产生很大影响，因此穿透伤的入、出口与伤道多呈不规则走行（D错）。创口的部位比起大小更有诊断意义，细小的创口可能由很长的锐器造成，引起严重的内脏伤；特别是体积小的高速投射物可引起很严重的内脏损伤，因此伤口大小与伤情严重程度不成正比（E错）。","","N"],["2000-N85",26,"第三节 胃十二指肠溃疡的外科治疗","胃十二指肠溃疡概述",2000,85,"A","","根据部位，下列哪种胃溃疡最为多见",[["A","高位溃疡"],["B","小弯溃疡"],["C","后壁溃疡"],["D","幽门前溃疡"],["E","复合溃疡"]],"B","胃溃疡多为小弯溃疡（B对）（约95%），常见于胃角处；也见于胃窦和胃体，大弯侧溃疡较为少见。老年人溃疡又称胃高位溃疡（A错），溃疡病灶多位于胃体上部，溃疡常较大，易误认为胃癌，临床表现不典型，疼痛无规律，常见体重减轻和贫血。幽门前溃疡（D错）即幽门管溃疡，溃疡发生于幽门管，餐后很快发生疼痛，早期出现呕吐，易出现幽门梗阻、出血和穿孔等并发症。复合溃疡（E错）指胃和十二指肠均有活动性溃疡，幽门梗阻发生率较高。后壁溃疡（C错）常发生出血及慢性穿孔，但多发于十二指肠溃疡。","","N"],["2000-N86",28,"第三节 特殊类型阑尾炎","小儿急性阑尾炎",2000,86,"A","","下列哪项叙述不符合小儿急性阑尾炎的临床特点",[["A","有右下腹明显压痛和肌紧张的典型体征"],["B","病情发展快且较重，早期即出现高热、呕吐等症状"],["C","穿孔率可达30%"],["D","并发症和死亡率较高"],["E","治疗原则是早期手术"]],"A","小儿大网膜发育不全，不能起到足够的保护作用；腹肌发育欠缺，力量较小，无法产生明显的肌紧张表现；患儿也不能清楚的提供病史，故小儿急性阑尾炎没有右下腹明显压痛和肌紧张的典型体征（A错，为本题正确答案）。由于缺乏大网膜的保护，加上小儿自身的免疫系统尚不健全，阑尾处炎症反应产物和细菌感染易于扩散，故小儿病情发展快且较重，早期即出现高热、呕吐等症状（B对），阑尾穿孔率也较高，可达30%（C对），并发症和死亡率较高（D对）。小儿急性阑尾炎治疗原则是早期手术（E对），并配合输液、纠正脱水、应用广谱抗生素等。","","N"],["2000-N87",29,"第六节 结肠癌","结肠癌分期",2000,87,"A","","结肠癌Dukes分期中B期是指",[["A","癌达粘膜下层"],["B","癌累及肠壁肌层"],["C","癌穿透肠壁，无淋巴结转移"],["D","有淋巴结转移，仅局限于结肠旁淋巴结"],["E","有淋巴结转移，至系膜和系膜根部淋巴结"]],"C","Dukes分期自1932年提出后几经改良修正已与原始含义有很大的出入，如不注明何种改良已无法判断其含义，现八版教材已将该知识点删除。七版外科学根据我国对Dukes法的补充，分为：癌仅限于肠壁内为DukesA期。穿透肠壁侵入浆膜或/及浆膜外（C对），但无淋巴结转移者为DukesB期。有淋巴结转移者为DukesC期，其中淋巴结转移仅限于癌肿附近如结肠壁或结肠旁淋巴结者为DukesC₁期；转移至系膜和系膜根部淋巴结者为DukesC₂期。已有远处转移或腹腔转移，或广泛侵及邻近脏器无法切除者为DukesD期”。Dukes分期在十版外科学未明确说明。","","N"],["2000-N88",29,"第十二节 痔","内痔",2000,88,"A","","由于内痔的动脉供应，其好发部位多在截石位的",[["A","3、5、10点"],["B","1、5、9点"],["C","3、7、9点"],["D","1、6、11点"],["E","3、7、11点"]],"E","原发性内痔好发部位有三个，位于齿状线上方的右前、右后、左正中，即为截石位3、7、11点（E对）。这与血管的分支有关，直肠上动脉的终末支主要分布在右前、右后、左正中的肛柱内，与该动脉伴行的静脉首先在齿状线上方形成右前、右后、左正中三个主要的痔内静脉丛，然后汇集肛周其他方位的静脉，再汇集成直肠上静脉，注入肠系膜下静脉。由于直肠上静脉无静脉瓣，在直肠压力增高等因素影响下，痔内静脉丛容易淤血、扩张、迂曲称为原发性内痔。","","N"],["2000-N89",32,"第十一节 胆道恶性肿瘤","胆管癌病理",2000,89,"A","","关于胆管癌，下列哪项叙述不正确",[["A","上段胆管癌比下段发病率高"],["B","病理组织大多是腺癌"],["C","局限型生长较多"],["D","主要转移方式是血行转移"],["E","先天性胆管扩张症发生癌变机会较高"]],"D","胆管癌一般是指原发于左、右肝管至胆总管下段的肝外胆管癌，不包括肝内的胆管细胞癌、胆囊癌和壶腹部癌。其发病可能与下列因素有关：肝胆管结石，约1/3的胆管癌合并胆管结石，而胆管结石5%～10%发生胆管癌；原发性硬化性胆管炎；先天性胆管囊性扩张（E对），胆管囊肿空肠吻合术后；肝吸虫感染，慢性伤寒带菌者，溃疡性结肠炎等。根据肿瘤生长的位置，胆管癌又分为上段胆管癌、中段胆管癌、下段胆管癌。上段胆管癌比下段发病率高（A对），分别约占50%～75%及10%～20%。胆管癌以上段胆管癌最为多见，而胆总管结石以下段最为多见，需注意区分。胆管癌特征总结如下：病理组织大多是腺癌（B对），分化好，肿瘤生长缓慢，多呈小灶性，并直接浸润相邻组织，即局限型生长较多（C对）；或沿肝内、外胆管及其淋巴分布和流向转移，并沿肝十二指肠韧带内神经鞘浸润是其转移的特点；亦可发生腹腔种植转移，血行转移较少见（D错，为本题正确答案）。","","N"],["2000-N90",50,"第二节 上肢神经损伤","正中神经损伤",2000,90,"A","","腕管综合征是因为下列哪项在腕管内受压所致",[["A","尺神经"],["B","尺动脉"],["C","桡神经"],["D","桡动脉"],["E","正中神经"]],"E","腕管综合征是正中神经（E对）在腕管内受压而表现出的一组症状和体征，表现为拇、示、中指感觉过敏或迟钝，鱼际肌萎缩，拇对掌无力，腕部正中神经Tinel征阳性。肘管综合征（十版外科学P697）是指尺神经在肘部尺神经沟内因慢性损伤而产生的一组症状和体征，表现为手背尺侧、小鱼际、小指及环指尺侧半感觉异常，小指收展无力及手指收、展不灵活，环小指可呈爪形手畸形。梨状肌综合征（十版外科学P698）是指坐骨神经在臀部受到卡压出现的一组症状和体征，表现为坐骨神经痛，体查可发现小腿轻度萎缩，小腿以下皮肤感觉异常。","","N"],["2000-N91",44,"第七节 骨折的治疗原则","石膏绷带",2000,91,"A","","长腿石膏管型可用于下列哪种骨折的治疗",[["A","股骨干上段骨折"],["B","股骨干中段骨折"],["C","胫腓骨骨干骨折"],["D","内外踝骨折"],["E","跖骨骨折"]],"C","石膏管型是骨折复位后常用的固定方法之一，其优点是能根据肢体的形状塑形，固定作用确实可靠。缺点是无弹性，不能随时调节，不适于使用固定垫。所以固定范围应较大，须超过骨折部的上下关节，固定作用才能确实可靠。长腿石膏管型固定范围包括膝踝两个关节，所以适用于胫腓骨骨干骨折（C对）。而股骨干上段或中段骨折（AB错），长腿石膏管型不能确实固定骨折，临床上多采用持续胫骨结节牵引或股骨髁上牵引，部分患者需手术治疗。内外踝骨折（D错）不需要固定膝关节，跖骨骨折（E错）膝踝两个关节均不需固定，所以均不适用。","","N"],["2000-N92",53,"第二节 腰椎退行性疾病","腰椎间盘突出症病因",2000,92,"A","","关于腰间盘突出症的叙述，下列哪项是错误的",[["A","本病是髓核突出刺激或压迫了神经根、马尾神经所表现的一种综合征"],["B","椎间盘退行性变是发病的基本因素"],["C","积累性伤力是间盘变性的主要原因"],["D","高处坠落的一次性暴力，也是造成本病的常见原因"],["E","妊娠增加椎间盘损害的机会"]],"D","腰椎间盘突出症是椎间盘变性、髓核突出压迫神经根、马尾所致的一种综合征（A对）。腰椎间盘突出症是腰腿痛常见及重要的原因。由于椎间盘组织承受人体躯干及上肢的重量，在日常生活及劳动中，劳损较其他的组织为重，此为椎间盘变性的主要原因（C对）；又因椎间盘纤维环仅有少量血供，营养依靠软骨终板有限的渗透，因而极易退变，这是发病的基本因素（B对）。高处坠落伤主要可引起脊柱的骨折和脊神经的损害，腰椎间盘突出症属于慢性退行性病变，极少因强烈暴力致病（D错，为本题正确答案）。妊娠时期孕妇存在特有的妊娠体位，即腰椎过度前驱，且妊娠期间整个韧带系统松弛，失去固定椎间盘功能，这些因素均造成椎间盘损害的机会增加（E对）。","","N"],["2000-N111",29,"第七节 直肠癌","低位前切除术",2000,111,"B","","直肠癌块下缘距肛门12cm适用",[["A","腹会阴联合直肠癌根治术"],["B","经腹腔直肠癌切除术"],["C","经腹直肠癌切除、人工肛门、远端封闭术"],["D","拉下式直肠癌切除术"],["E","乙状结肠造口术"]],"B","直肠癌的手术方式取决于肿块下缘距离肛缘的距离或肿块下缘距离齿状线的距离。七版黄家驷外科学认为，Miles手术（腹会阴联合直肠癌根治术）（A错）适用于肿块下缘距肛缘小于5cm患者，在部分肿瘤大、浸润明显患者，肿块下缘距离肛缘7cm者亦可行Miles手术。Dixon手术（经腹腔直肠癌切除术）适用于距离肛缘5～7cm以上患者。该患者直肠癌块下缘距离肛门12cm，用经腹腔直肠癌切除术（B对）可以保留患者的肛门，术后生活质量较高。经腹直肠癌切除、近端造口、远端封闭手术（Hartmann手术）（C错）适用于因全身一般情况很差，不能耐受Miles手术或急性肠梗阻不宜行Dixon手术的直肠癌病人。拉下式直肠癌切除术（D错）适用于直肠癌块下缘距肛缘7～10cm患者。乙状结肠造口术（E错）用于解除远端梗阻，并保护远端肠管的吻合或损伤，促进肠道愈合。","","N"],["2000-N112",29,"第七节 直肠癌","Hartmann手术",2000,112,"B","","直肠癌病人发生急性肠梗阻时适用",[["A","腹会阴联合直肠癌根治术"],["B","经腹腔直肠癌切除术"],["C","经腹直肠癌切除、人工肛门、远端封闭术"],["D","拉下式直肠癌切除术"],["E","乙状结肠造口术"]],"C","一般情况下，直肠癌的手术方式取决于肿块下缘距离肛缘的距离或肿块下缘距离齿状线的距离，八版黄家驷外科学认为，Miles手术（腹会阴联合直肠癌根治术）（A错）适用于肿块下缘距肛缘小于5cm患者，在部分肿瘤大、浸润明显患者，肿块下缘距离肛缘7cm者亦可行Miles手术。Dixon手术（经腹腔直肠癌切除术）（B错）适用于距离肛缘5～7cm以上患者。拉下式直肠癌切除术（D错）适用于直肠癌块下缘距肛缘7～10cm患者。Hartmann手术，即经腹直肠癌切除、人工肛门、远端封闭术（C），该术式避免了肛门部操作，手术时间缩短，适用于一般情况很差，不能耐受Miles手术或急性梗阻不宜行Dixon手术的病人。故本题正确答案为C，但当年官方给出的参考答案为E，而乙状结肠造口术（E）适用于晚期直肠癌患者，主要以解除痛苦和处理并发症为目的。","","N"],["2000-N113",8,"第一节 肿瘤概述","放射性核素显像",2000,113,"B","","放射性核素显像检查诊断阳性率较高的是",[["A","肝肿瘤"],["B","甲状腺肿瘤"],["C","大肠癌"],["D","骨肿瘤"],["E","脑肿瘤"]],"D","放射性核素显像是利用放射性核素及其标记化合物对疾病进行诊断和研究的一类方法。通过口服或注射等方式将含放射性核素标记的药物导入人体，与人体作用一段时间后，再通过体外计算机成像技术追踪放射性药物在体内分布情况，从而进行相关疾病的诊断。在肿瘤学诊断中应用最多的为氟化脱氧葡萄糖（¹⁸F-FDG），能根据肿瘤与正常组织对葡萄糖利用率的变化和差异进行显像。骨肿瘤（D对）代谢率高，对含有放射性核素的¹⁸F-FDG摄取量大，显像清晰，阳性率可高达90％左右。","","N"],["2000-N114",8,"第一节 肿瘤概述","放射性核素显像",2000,114,"B","","放射性核素显像检查诊断阳性率较低的是",[["A","肝肿瘤"],["B","甲状腺肿瘤"],["C","大肠癌"],["D","骨肿瘤"],["E","脑肿瘤"]],"C","放射性核素显像是利用放射性核素及其标记化合物对疾病进行诊断和研究的一类方法。通过口服或注射等方式将含放射性核素标记的药物导入人体，与人体作用一段时间后，再通过体外计算机成像技术追踪放射性药物在体内分布情况，从而进行相关疾病的诊断。在肿瘤学诊断中应用最多的为氟化脱氧葡萄糖（¹⁸F-FDG），能根据肿瘤与正常组织对葡萄糖利用率的变化和差异进行显像。消化道肿瘤（C对）相对其他肿瘤来说对¹⁸F-FDG的摄取量低，阳性诊断率较低。","","N"],["2000-N115",44,"第一节 骨折的定义、成因、分类及移位","压缩骨折",2000,115,"B","","高处坠落发生的椎体骨折是",[["A","压缩骨折"],["B","横骨折"],["C","斜骨折"],["D","粉碎骨折"],["E","嵌插骨折"]],"A","压缩性骨折多指松质骨受外力作用而被压缩变形引起的骨折，常见于椎体和跟骨。高空坠落由于强大惯性和地面向上的反作用力之间的冲击，导致椎体承受相当于数倍于体重的重力压迫，引起的椎体骨折通常为压缩骨折（A对）。","","N"],["2000-N116",44,"第一节 骨折的定义、成因、分类及移位","粉碎性骨折",2000,116,"B","","骤然跪倒髌骨着地发生的髌骨骨折是",[["A","压缩骨折"],["B","横骨折"],["C","斜骨折"],["D","粉碎骨折"],["E","嵌插骨折"]],"D","对于髌骨骨折，有两种情况，直接暴力常致髌骨粉碎性骨折；肌肉牵拉暴力常致髌骨横行骨折。骤然跪倒时髌骨着地属于直接暴力损伤，常导致髌骨粉碎性骨折（D对）。","","N"],["2000-N135",23,"第二节 腹股沟疝","腹股沟疝非手术治疗",2000,135,"C","","一岁以内婴儿腹股沟斜疝的治疗",[["A","疝囊高位结扎术"],["B","疝修补术"],["C","二者均需"],["D","二者均不需"]],"D","腹股沟疝一般均应尽早施行手术，但有两个特例：①一岁以下婴儿；②年老体弱或伴有其他严重疾病而禁忌手术者。一岁以下的婴儿腹肌可随躯体生长逐渐强壮，疝有自行消失的可能。可采用棉线束带或绷带压住腹股沟管深环，防止疝块突出并给发育中的腹肌以加强腹壁的机会（D对）。年老体弱或伴有其他严重疾病而禁忌手术者，可在疝内容物回纳之后，将医用疝带一端的软压垫对着疝环顶住，阻止疝块突出。","","N"],["2000-N136",23,"第三节 股疝","股疝治疗",2000,136,"C","","中、老年妇女股疝的治疗",[["A","疝囊高位结扎术"],["B","疝修补术"],["C","二者均需"],["D","二者均不需"]],"C","对于中、老年妇女的股疝，因股疝极容易发生嵌顿，故应早期手术治疗，若无特殊情况，给予传统疝修补术即可。最常用的手术是McVay修补法，包括疝囊高位结扎术及疝修补术（C对）。若采用无张力疝修补术（使用高分子补片）则无须进行疝囊高位结扎术。","","N"],["2000-N137",57,"第一节 骨肿瘤概论","骨肿瘤临床表现",2000,137,"C","","良性骨肿瘤可发生",[["A","远隔转移"],["B","病理骨折"],["C","二者均可有"],["D","二者均无"]],"B","由于肿瘤细胞的生长，良性骨肿瘤和恶性骨肿瘤均存在骨质破坏，故均能够发生病理骨折（B对）；但远隔转移（A错）是恶性的表现，良性肿瘤无此现象。","","N"],["2000-N138",57,"第一节 骨肿瘤概论","骨肿瘤临床表现",2000,138,"C","","恶性骨肿瘤可发生",[["A","远隔转移"],["B","病理骨折"],["C","二者均可有"],["D","二者均无"]],"C","恶性骨肿瘤可破坏骨质，导致骨强度降低，受到轻微外力即可发生骨折，称为病理骨折（B对）。恶性肿瘤可出现远隔转移（A对），以血行转移为主，偶见淋巴转移。本题AB均对，正确答案为C。","","N"],["2000-N157",31,"门静脉高压","食管胃底曲张静脉破裂出血手术治疗",2000,157,"A","","对肝炎和肝硬化病人手术耐受力的估计，哪项是不正确的",[["A","肝轻度损害，不影响手术耐受力"],["B","肝功能损害较严重或濒于失代偿者，必须经过长时间严格准备后方可择期手术"],["C","肝功能严重损害，有营养不良、腹水、黄疸者，一般不宜施行任何手术"],["D","急性肝炎者，不宜施行包括急诊抢救在内的任何手术"]],"D","肝炎和肝硬化是最常见的肝疾病。鉴于肝病病人可以无明确的肝病史，亦无明显的临床表现，因此病人术前都应做各项肝功能检查，以了解或发现事实上存在的肝功能损害。一般来说，肝轻度损害者不影响手术耐受力（A对）；肝功能损害较严重或濒临失代偿者，手术耐受力则显著减弱，必须经过较长时间的严格准备，方可实行择期手术（B对）；肝功能严重损害者，如有明显营养不良、腹水、黄疸等，一般仅进行护肝及保守治疗，否则病人遭受手术打击，容易发生肝性脑病（C对）。但作为医疗原则，抢救生命是第一位的，因此即使合并急性肝炎，仍然要施行急诊抢救手术（D错，为本题正确答案）。","","N"],["2000-N158",29,"第一节 结、直肠与肛管解剖生理概要","动脉",2000,158,"X","","内痔的主要供应血管是",[["A","直肠上动脉"],["B","直肠下动脉"],["C","肛管动脉"],["D","骶中动脉"]],"A","内痔的主要供应血管是直肠上动脉（A对）。直肠上动脉的终末支主要分布在右前、右后、左正中的肛柱内，与该动脉伴行的静脉首先在齿状线上方形成右前、右后、左正中三个主要的痔内静脉丛，然后汇集肛周其他方位的静脉，再汇集成直肠上静脉，注入肠系膜下静脉。由于直肠上静脉无静脉瓣，在直肠压力增高等因素影响下，痔内静脉丛容易淤血、扩张、迂曲称为原发性内痔。直肠下动脉（B错）、骶（正）中动脉（D错）为齿状线以上直肠的次要供血动脉。肛管动脉（C错）为齿状线以下直肠的供血动脉。原X型题为不定项选择题，可有1-4个正确答案。","","N"],["2000-N159",32,"第四节 胆石症","胆囊结石临床表现",2000,159,"X","","关于胆囊结石症，下列叙述哪些是正确的",[["A","可继发感染，引起急性胆囊炎"],["B","可导致胆囊积液"],["C","可导致急性化脓性胆管炎和全身感染"],["D","静止性胆囊结石可无需处理"]],"ABCD","胆囊结石早期通常无明显临床表现，常于查体或行上腹部其他手术而被发现。部分单发或多发的胆囊结石，在胆囊内自由移动，不易发生嵌顿，很少产生症状，被称为无症状胆囊结石（静止性胆囊结石），无症状的胆囊结石一般不需预防性手术治疗，可观察和随诊（D对）。当胆石嵌顿于胆囊颈部时，造成急性梗阻，导致胆囊内压力增高，胆汁不能通过胆囊颈和胆囊管排出，从而引起临床症状，通常表现为胆绞痛；如果结石嵌顿持续不缓解，可损伤受压部位胆囊黏膜，继发感染，引起急性胆囊炎（A对）。胆囊结石长期嵌顿或阻塞胆囊管但未合并感染时，胆囊黏膜吸收胆汁中的胆色素，并分泌黏液样物质，导致胆囊积液（B对），积液呈透明无色，又称白胆汁。若胆囊结石脱落进入胆总管引起梗阻，炎症感染的胆囊内胆汁进入梗阻胆管，或肠道内逆行进入胆管的细菌在胆汁无法排泄而积聚于胆管中时大量繁殖，则可导致急性梗阻性化脓性胆管炎，梗阻越完全，管腔内压越高，病情越重；当胆管内压升高到一定程度时，胆汁中的细菌和毒素即可逆行进入肝窦，产生严重的脓毒血症，引起全身感染（C对），称为胆血反流。","","N"],["2000-N160",45,"第三节 肩关节脱位","手法复位",2000,160,"X","","关于肩关节前脱位的治疗，下列哪些不对",[["A","应首选手法复位，一般可在局麻下进行"],["B","常采用Bigelow法复位"],["C","复位成功，Dugas由阳性转为阴性"],["D","复位后次日，应立即开始活动肩关节，以防粘连形成肩周炎"]],"BD","肩关节脱位多由外界暴力引起，故又称创伤性肩关节脱位。对于肩关节脱位，应首选手法复位，一般可在局麻下进行（A对），可使病人肌肉放松易于复位，同时减轻疼痛。肩关节前脱位约占肩关节复位的95%，最常用的复位方法为Hippocrates法，即足蹬法：伤员平卧，术者立于伤侧，以与伤者伤侧相同的足跟部蹬于伤者腋下并向上外方蹬推肱骨头，同时术者双手握住伤者腕部持续牵引，并轻轻内收内旋患者上臂，即可感知复位时的响声和滑动。Bigelow法复位（又称问号法复位）（B错，为本题正确答案）为髋关节后脱位的复位方法。将肩关节前脱位病人伤肢肘部接触胸前部，则手部不能触及健肩；反之将伤肢手部触及健肩时，其肘部不能接触胸前部，此为Dugas征，是肩关节前脱位的特征性体征，阳性表现为将患侧肘部紧贴胸壁时，手掌搭不到健侧肩部，或手掌搭在健侧肩部时，肘部无法贴近胸壁，复位成功，Dugas由阳性转为阴性（C对）。对于复位成功的病人，应将上臂固定于胸壁3-4周（D错，为本题正确答案），以利于损伤组织的修复并减少复发性脱位的机会；除去制动后再循序练习肩关节活动。","","N"],["2001-N70",13,"第三节 术后并发症的防治","泌尿系感染",2001,70,"A","","一般留置导尿管3～4天后，细菌尿的发生率达",[["A","50%"],["B","60%"],["C","70%"],["D","80%"],["E","90%以上"]],"E","此处外科学与内科学略有出入。即使严格消毒，单次导尿后，尿路感染发生率约为1～2%，留置导尿一天感染率约为50%，超过3天者，感染发生率可达90%以上（十版内科学P500），因此可得留置导尿管3～4天后，细菌尿的发生率可达90%以上（E对）。","","N"],["2001-N75",10,"第四节 局部麻醉","脂溶性",2001,75,"A","","局麻药的麻醉效能主要决定于",[["A","pKa（解离常数）"],["B","相对分子质量"],["C","浓度"],["D","脂溶性（分配系数）"],["E","蛋白结合率"]],"D","对于局麻药，其理化性质决定了药物的效能和作用持续时间。局麻药的解离常数（pKa）（A错）越大，对于生物膜穿透功能越差（离子难以穿透生物膜），起效时间延长、弥散性越差。局麻药的麻醉效能主要决定于脂溶性，脂溶性（D对）越强，则亲细胞能力越强，麻醉效能越强；局麻药的麻醉效能也与蛋白结合率（E错）有关，蛋白结合率越高，则排泄率越低，作用时间越长。麻醉效能与相对分子质量（B错）和浓度（C错）没有关系。","","N"],["2001-N76",10,"第五节 椎管内麻醉","常用局麻药和注药方法",2001,76,"A","","当使用硬膜外麻醉时，能加速局麻药起效和延长作用持续时间，并提供最大的感觉和运动阻滞深度的做法是",[["A","1：200000加入肾上腺素"],["B","增加局麻药的容量"],["C","增加局麻药的浓度"],["D","增加局麻药的剂量"],["E","病人头低位"]],"D","在药液中增加1：200000的肾上腺素（A错），利用的是肾上腺素的缩血管作用，使得局麻药吸收速度减慢，延长作用时间，同时可避免或减轻局麻药的毒性反应，但此方法无法加速局麻药的起效时间及达到最大麻醉效果。增加局麻药的容量可以扩大局麻药在硬膜下间隙的扩散范围，增加局麻药的浓度可以使起效时间缩短和作用时间增长，增加局麻药的剂量（D对）时，局部药物的容量和浓度均增加（BC错），故能更大程度加速局麻药起效和延长作用持续时间，并提供最大的感觉和运动阻滞深度。病人体位（E错）对硬膜外麻醉无影响。硬膜外麻醉的影响因素是常考点，考生可结合本章各相关答案解析理解记忆。","","N"],["2001-N77",0,"第一节 手术器械、物品的灭菌、消毒法","高压蒸汽灭菌法",2001,77,"A","","经高压蒸气灭菌的物品一般可保留",[["A","5天"],["B","7天"],["C","10天"],["D","14天"],["E","21天"]],"D","以下有关时间的知识点要牢记：经高压蒸气灭菌的物品一般可保留14天（D对）；环氧乙烷气体法灭菌后物品以专用纸袋密封后放入灭菌室，灭菌有效期为半年。","","N"],["2001-N78",1,"第二节 水、钠代谢紊乱","等渗性脱水临床表现",2001,78,"A","","当病人出现血容量不足的症状时，说明在短期内体液丧失至少已达体重的",[["A","3%"],["B","5%"],["C","7%"],["D","10%"],["E","15%"]],"B","若在短期内体内丧失的液体量达到体重的5%（B对），即丧失25%的细胞外液，病人则会出现脉搏细速、肢端湿冷、血压不稳定或下降等血容量不足之症状。当体液继续丧失达体重的6～7%时（相当于丧失细胞外液的30～35%），则有更严重的休克表现。对于已经有脉搏细速和血压下降等症状患者，需从静脉快速补液3000ml（按体重60kg计算）以恢复其血容量，以平衡盐溶液或复方氯化钠为宜。单纯应用生理盐水有导致高氯性酸中毒的风险（生理盐水中的Cl⁻含量比血清Cl⁻含量高50mmol/L）。以上数据以及处理方法需牢记。","","N"],["2001-N79",1,"第三节 钾代谢紊乱","低钾血症临床表现",2001,79,"A","","下列哪项不符合低钾血症的临床表现",[["A","肌无力，腱反射减退"],["B","腹胀，肠麻痹"],["C","心率快，心律异常"],["D","代谢性碱中毒"],["E","尿量少，呈碱性"]],"E","钾离子作为维持细胞内外电平衡重要的离子，过高或过低必然引起细胞的不稳定，对肌肉的活动、心脏节律等造成严重影响。低钾血症的临床表现主要分为运动系统表现、消化系统表现、心律失常以及代谢性碱中毒（低钾低氯均可引起碱中毒）。运动系统主要表现为肌无力，还可有软瘫、腱反射减退或消失（A对）。消化系统主要表现为厌食、恶心、呕吐和腹胀、肠蠕动消失等肠麻痹表现（B对）。心律失常主要表现为早期心肌应激性增强，心动过速，可有房性、室性期前收缩，晚期由于传导阻滞可导致心动过缓（C对）。低钾引起代谢性碱中毒（D对）的原因，一方面钾离子由细胞内移出，与钠、氢离子交换增加，使细胞外氢离子浓度降低；另一方面远曲肾小管钠、钾离子交换减少，钠、氢离子交换增加，使排氢增多，这两方面的作用即可使病人发生低钾性碱中毒。此时，尿中氢离子增多呈酸性，出现反常性酸性尿（E错，为本题正确答案）。","","N"],["2001-N80",1,"第五节 酸碱平衡失调","代谢性酸中毒诊断",2001,80,"A","","下列关于代谢性酸中毒的叙述，哪项是错误的",[["A","是由体内[HCO₃⁻]减少引起的"],["B","最突出的表现是呼吸变慢、变浅"],["C","呼气中可有酮味"],["D","血清pH值降低"],["E","症状较轻者，一般不需应用碱剂治疗"]],"B","代谢性酸中毒是临床上最常见类型的酸碱平衡失调。由体内酸性物质的积聚或产生过多，或HCO₃⁻丢失过多引起，表现为血清pH值降低（D对），体内[HCO₃⁻]减少（A对）。由于外周H⁺浓度增加，刺激外周呼吸感受器，反射性引起呼吸加快、加深（B错，为本题正确答案），又名Kussmaul呼吸。同时，病人可出现呼气有酮味（C对）。对于症状较轻的病人，只要消除病因，再辅以补充液体等对症治疗，酸中毒常可自行纠正，一般不需要应用碱剂（E对）。仅在血浆HCO₃⁻低于10mmol/L的重症酸中毒病人才应用少量碱剂治疗。","","N"],["2001-N81",32,"第四节 胆石症","其他结石",2001,81,"A","","下列哪类胆囊结石在行X线腹部平片检查时常显影",[["A","胆固醇结石"],["B","胆色素结石"],["C","混合性结石"],["D","泥沙样结石"],["E","黑结石"]],"C","胆固醇结石（A错）组成成分以胆固醇为主（约占90%以上），80%在胆囊内形成，X线检查多不显影。胆色素结石（B错）含胆色素为主，主要发生在肝内、外胆管内，胆道感染和胆汁淤积是胆色素结石形成的主要因素，X线检查多不显影。混合性结石（C对）由胆红素、胆固醇、钙盐等多种成分混合组成，60%发生在胆囊内，40%在胆管内，X线检查常可显影。中华外科学会全国胆石病研究组推荐，由上海瑞金医院提出的根据结石剖面特征分成八类的方法：①放射状石；②放射年轮状石；③岩层状叠层石（此三类是以胆固醇为主的结石）；④铸型无定形石；⑤沙层状叠层石；⑥泥沙状石（D错）（4～6型主要是以胆红素为主的结石）；⑦黑结石（E错）（纯胆色素结石，均发生在胆囊内）；⑧复合结石。上述八类结石均由胆固醇或/和胆色素为主构成的，含钙盐量少，故X线不显影。","","N"],["2001-N82",5,"第七节 外科应用抗菌药的原则","选择最佳的抗菌药物",2001,82,"A","","下列哪种疾病不需应用抗菌药物",[["A","毛囊炎"],["B","丹毒"],["C","开放性骨折"],["D","结肠手术前"],["E","人工关节术后"]],"A","毛囊炎为皮肤浅表局限性感染，除局部皮肤红肿热痛外无不良全身表现，一般无需使用抗生素，仅需要通过保持皮肤清洁、外用中药及理疗即可治愈（A对）。丹毒为皮肤和黏膜网状淋巴管的急性炎症，特点是蔓延很快，很少有组织坏死或化脓，伴有全身反应，治愈后极易复发。治疗时除了休息、抬高患肢、局部皮肤硫酸镁热敷或3%碘酊涂擦外，需全身应用磺胺药或青霉素，并在全身和局部症状消失后继续应用3～5天，以免再发（B错）。以下情况需预防性应用抗生素：①严重创伤，如大面积烧伤、开放性骨折（C错）、火器伤、腹部脏器穿孔，以及有严重污染及软组织破坏的损伤；②进入胃肠道、呼吸道、女性生殖道的手术，结肠手术前肠道准备（D错）；③人造物留置手术（E错）；④病人有感染高危因素，如高龄、营养不良、糖尿病、粒细胞减少症等；或是接受类固醇、免疫抑制剂、抗癌药物治疗，免疫功能低下而需手术治疗者；⑤手术时间长、创伤大，或一旦感染后果严重者，如颅脑、心脏和大血管手术，器官移植手术等。","","N"],["2001-N83",6,"第二节 创伤的病理生理","组织修复的基本过程",2001,83,"A","","下列关于创伤修复的叙述，哪项是不正确的",[["A","创伤修复的基本方式是增生的细胞和细胞间质充填、连接或代替缺损的组织"],["B","现代外科已把利用异体组织或人造材料修复创伤作为创伤治愈的基础"],["C","组织修复前期以合成代谢为主"],["D","组织修复中，巨噬细胞和多种介质参与这个过程"],["E","酶类在创伤修复中起着重要的催化作用"]],"B","现代外科常利用异体组织或人造材料修复创伤，但人造材料不具有生物活性，最终的创伤修复需依靠自身细胞的增殖与修复，人造材料仅起到辅助作用（B错，为本题正确答案）。组织修复前期大量生成新细胞、基质等填充缺损，合成代谢占主导地位（C对）。组织修复过程中伴随着炎症反应，巨噬细胞和多种介质参与清除损伤或坏死的组织，为组织再生和修复奠定基础（D对）。酶类在创伤修复中起着重要的催化作用，如溶菌酶对细菌的杀伤、自溶酶对自身坏死组织的溶解、胶原蛋白酶溶解多余的胶原纤维等（E对）。","","N"],["2001-N84",8,"","",2001,84,"A","","恶性肿瘤的淋巴道转移方式中，以下列哪种最多见",[["A","区域淋巴结转移"],["B","穿过或绕过淋巴结的“跳跃式”转移"],["C","经皮肤真皮层淋巴管的转移"],["D","在毛细淋巴管内形成癌栓"],["E","经皮肤淋巴管转移"]],"A","以侵袭性方式生长的恶性肿瘤，不仅可以在原发部位继续生长、蔓延，还可以通过多种途径扩散到身体其他部位（转移）。恶性肿瘤容易发生转移，其方式有四种：①直接蔓延②淋巴转移③血行转移④种植转移。淋巴道转移（A对）是上皮性恶性肿瘤（癌）的首要转移方式，肉瘤也可以淋巴道转移。恶性肿瘤内部一般都没有功能性淋巴管，淋巴道转移只能通过肿瘤旁的引流淋巴结。瘤细胞侵入淋巴管后，随淋巴液首先到达局部引流淋巴结。值得注意的是，有的肿瘤可以逆行转移，或者越过相应的引流淋巴结发生跳跃式转移，但这些都较为少见，最多见的转移方式还是区域淋巴结转移。","","N"],["2001-N85",17,"第一节 甲状腺疾病","单纯性甲状腺肿治疗",2001,85,"A","","预防甲状腺肿的碘化食盐，常用剂量为每10～20kg食盐中均匀地加入碘化钾或碘化钠",[["A","1.0g"],["B","2.0g"],["C","3.0g"],["D","4.0g"],["E","5.0g"]],"A","在甲状腺肿多发地区，集体预防极为重要，一般多用碘化食盐。常用剂量为每10～20kg食盐中均匀地加入碘化钾或碘化钠1.0g，此量足够满足人体每日的需碘量（A对）（八年制外科学P379）。","","N"],["2001-N86",26,"第二节 胃癌及其他胃肿瘤","胃癌根治性手术",2001,86,"A","","行胃癌根治术时，手术切除最少应离肿瘤边缘多远才算足够",[["A","1～2cm"],["B","2～4cm"],["C","4～6cm"],["D","6～8cm"],["E","8～10cm"]],"D","行胃癌根治性手术时，胃切除范围：胃切断线要求距肿瘤边缘5cm以上；远侧部癌应切除十二指肠第一部3～4cm，近侧部应切除食管下端3～4cm。题目数据与第十版外科学有出入，不必深究。","","N"],["2001-N87",29,"第九节 肛裂","肛裂临床表现",2001,87,"A","","下列关于肛裂的叙述，哪项是正确的",[["A","肛裂是肛管部深达肌层的小溃疡"],["B","肛裂、前哨痔和齿状线上相应的乳头肥大称为肛裂“三联征”"],["C","主要症状是排便时出血"],["D","绝大多数发生在肛管前正中部"],["E","手术切除肛裂是治疗急性肛裂唯一有效的方法"]],"B","肛裂时，慢性裂口上端的肛门瓣和肛乳头水肿，形成肥大乳头；下端皮肤因炎症、水肿及静脉、淋巴回流受阻，形成袋状皮垂向下突出于肛门外，称为前哨痔。肛裂、前哨痔和齿状线上相应的乳头肥大称为肛裂“三联征”（B对）。肛裂是齿状线下肛管皮肤层裂伤后形成的小溃疡，并不累及深部肌层（A错）。肛裂的主要症状是排便时剧痛（C错），典型表现为便时肛管刀割样或烧灼样疼痛，便后数分钟缓解，随后肛门括约肌痉挛，再次出现剧痛。排便时出血为痔的主要症状。肛裂绝大多数发生在肛管后正中部（D错），原因是：①肛管外括约肌浅部在肛门后正中形成的肛尾韧带伸缩性差、坚硬且血供较差；②肛管与直肠成角相延续，排便时，肛管后壁承受的压力最大。肛裂的治疗包括非手术治疗（保持局部清洁；通畅润滑大便；局麻解除括约肌痉挛等）及手术治疗（E错），只有迁延不愈、保守治疗无效以及症状严重患者才考虑手术治疗。","","N"],["2001-N88",30,"第四节 原发性肝恶性肿瘤","肝细胞癌诊断与鉴别诊断",2001,88,"A","","肝癌实验室检查项目中，诊断意义最大的是",[["A","癌胚抗原"],["B","γ-谷氨酰转肽酶"],["C","甲胎蛋白"],["D","碱性磷酸酶"],["E","乳酸脱氢酶同工酶"]],"C","甲胎蛋白（C对）（以下简称AFP）是诊断肝细胞癌特异性的标志物，阳性率约70%，现已广泛用于肝癌的普查、诊断、判断治疗效果及预测复发。在排除妊娠和生殖腺胚胎瘤的基础上，血清AFP≥400ng/ml 为诊断肝癌的条件之一；随着肝癌高危人群的定期筛查，部分患者AFP 处于轻度升高阶段，动态观察其变化显得尤为重要。血液酶学及其他肿瘤标记物检查肝癌病人血清中y-谷氨酰转肽酶（B错）及其同工酶、异常凝血酶原、碱性磷酸酶（D错）、乳酸脱氢酶同工酶（E 错）等可高于正常。但由于缺乏特异性，多用于与AFP， AFP 异质体等联合检测，结合AFP 分析，有助于提高肝癌的确诊率。癌胚抗原（A错）是胎儿胃肠道产生的一组糖蛋白，在结肠癌、胃癌、肺癌、乳癌均可增高，也可用于大肠癌的术后复发的监测。","","N"],["2001-N89",22,"第三节 动脉疾病","血栓闭塞性脉管炎一般疗法",2001,89,"A","","下列关于疾病与疼痛类型关系的叙述，哪项是错误的",[["A","血栓闭塞性脉管炎早期有运动性疼痛"],["B","动脉硬化性闭塞症，下垂患肢可缓解疼痛"],["C","下肢动脉闭塞病变严重者，高温热敷能缓解疼痛"],["D","下肢静脉曲张时，下垂患肢可加重胀痛"],["E","动脉性溃疡比静脉性溃疡的静息痛严重"]],"C","血栓闭塞性脉管炎早期出现运动性疼痛（A对）是因为运动时组织代谢旺盛，需氧量增加，加重了闭塞部位以下组织的缺血缺氧从而造成疼痛感。动脉硬化性闭塞症，下垂患肢可缓解疼痛（B对），因为下垂患肢可以促进动脉血流向远端，增加血供从而缓解疼痛。下肢静脉曲张时，下垂患肢可加重胀痛（D对），因为下垂患肢时，下肢静水压增加，静脉回流阻力增大，代谢物堆积。一般来说动脉性溃疡的静息痛比静脉性溃疡的严重（E对），因为动脉因素导致的缺血程度更加严重。下肢动脉闭塞病变患肢，高温热敷不但不能缓解疼痛，反而加重组织的缺血缺氧，加重疼痛（C错，为本题正确答案），因为高温热敷加快局部新陈代谢，组织耗氧量增加，超过血管扩张的代偿能力，导致局部代谢产物（钾离子、氢离子等）增加。","","N"],["2001-N90",56,"第三节 类风湿关节炎","类风湿关节炎概述",2001,90,"A","","关于类风湿性关节炎的描述，下列哪项不正确",[["A","是一种非特异性炎症"],["B","其发生与免疫机制和HLA-DR4抗原有关"],["C","临床表现为多发性和对称性关节炎"],["D","病程发展缓慢但常有急性发作，逐渐形成关节畸形"],["E","与风湿性关节炎是同一疾病，只是好发年龄不同"]],"E","类风湿性关节炎是一种病因尚未明了的以关节病变为主的非特异性炎症（A对），通常缓慢起病，好发于手、腕、足等小关节，表现为多发性和对称性关节炎（C对）。该疾病发展缓慢，但常有急性发作，急性炎症期关节红肿热，大关节有积液，可缓解，反复发生关节囊、韧带及骨的破坏使出现多种畸形（D对）。其发生与免疫机制和HLA-DR4抗原有关（B对），需明确，类风湿性关节炎与风湿性关节炎是两种截然不同的疾病（E错，为本题正确答案），鉴别要点是风湿性关节炎的关节病变呈游走性，且一般不引起关节破坏和畸形。","","N"],["2001-N91",54,"第一节 化脓性骨髓炎","急性化脓性骨髓炎治疗",2001,91,"A","","关于急性血源性骨髓炎的治疗，下列哪项是错误的",[["A","立即开始联合应用足量广谱抗生素"],["B","抗生素治疗48～72小时后，局部症状仍不能控制，应手术治疗"],["C","手术行软组织切开引流术"],["D","少量多次输血，增加病人的抵抗力"],["E","患肢可用皮牵引或石膏托固定"]],"C","急性血源性骨髓炎系通过血源性传播，故早期便有严重的全身症状，起病急骤，明显毒血症症状，故必须立即给予足量抗生素治疗（A对）。若抗生素治疗48～72小时后，局部症状仍不能控制，甚至加重，说明抗生素不能消灭骨脓肿，此时手术可引流脓液，缓解感染中毒症状，并可阻止急性骨髓炎转化为慢性骨髓炎（B对）。手术的目的是引流骨脓肿，无需行组织切开，钻孔引流和开窗减压可以很好的引流和冲洗，创口小且治疗效果好，小创口也限制了脓液的扩散。单纯行软组织切开引流术（C错，为本题正确答案）并不能引流髓腔内脓肿，无法达到理想的治疗效果。皮牵引或石膏托固定属于辅助治疗，其作用是止痛、防止关节挛缩畸形和病理性骨折的发生（E对）。","","N"],["2001-N92",53,"第二节 腰椎退行性疾病","腰椎间盘突出症治疗",2001,92,"A","","某患者，男性，36岁，10天前抬重物扭伤腰部，腰痛伴右下肢后外侧放射痛，无大小便功能障碍。经检查诊断为腰椎间盘突出症，下列的治疗措施目前哪项不宜采用",[["A","卧床休息"],["B","骨盆牵引"],["C","理疗和按摩"],["D","皮质类固醇硬膜外注射"],["E","立即手术治疗，行髓核摘除术"]],"E","36岁男性患者，初发腰椎间盘突出症，病程较短，考虑非手术治疗。卧床休息（A对）可以减少椎间盘承受的压力，缓解对神经根的压迫，以减轻或者消除临床症状。骨盆牵引（B对）可以使椎间隙增大及后纵韧带紧张，有利于突出的髓核部分还纳。理疗、按摩（C对）可缓解肌肉痉挛，松解神经根粘连，或改变突出髓核与神经根的对应关系，减轻对神经根的压迫。皮质类固醇硬膜外注射（D对）可抑制神经末梢的兴奋性，同时改善局部血运，减轻局部酸中毒，从而起到消炎作用，阻断疼痛恶性循环。腰椎间盘突出症手术治疗适应证为：①腰腿痛症状严重，反复发作，经半年以上非手术治疗无效，且病情逐渐加重，影响工作和生活者；②中央型突出有马尾综合征，括约肌功能障碍者，应按急诊进行手术；③有明显的神经受累表现者。该患者目前尚无手术指征，不考虑立即手术治疗（E错，为本题正确答案）。","","N"],["2001-N111",7,"第一节 热力烧伤","消化道应激性溃疡",2001,111,"B","","大面积烧伤后，突然出现上消化道出血或急腹痛和腹膜炎症状，可能是并发了",[["A","Cushing溃疡"],["B","十二指肠溃疡"],["C","Curling溃疡"],["D","复发性溃疡"],["E","吻合口溃疡"]],"C","Curling溃疡（C对）又称柯林溃疡，是指不同程度烧伤后继发的应激性溃疡，主要发生于胃体及胃底，发生于十二指肠者少（B错）。临床上早期除偶有腹部隐痛和黑便外，其他症状甚少，多在大出血或穿孔后被发现。发病机制可能与严重应激状态下，交感神经兴奋，肾上腺髓质分泌大量儿茶酚胺类激素，导致胃黏膜血管发生痉挛，组织灌流量骤降，导致胃黏膜缺血缺氧，产生溃疡，严重者可表现为上消化道出血，在部分穿孔病人可出现腹痛和腹膜炎症状。Cushing溃疡是中枢神经系统病变（如严重脑外伤）所致的溃疡（A错）。发病机制同Curling溃疡类似。复发性溃疡（D错）需要有溃疡病史方可诊断，本题无此相关信息。胃大部切除术从多种途径消除了消化道溃疡的发生因素，通常不会再次复发溃疡，若出现溃疡症状，则一般为吻合口溃疡（E错），但与烧伤无相关性。","","N"],["2001-N112",34,"第一节 上消化道大出血的诊断和处理","上消化道大出血临床分析",2001,112,"B","","胃大部切除术后，经常上腹痛、黑便，药物治疗无效，可能是并发了",[["A","Cushing溃疡"],["B","十二指肠溃疡"],["C","Curling溃疡"],["D","复发性溃疡"],["E","吻合口溃疡"]],"E","胃大部切除术的吻合口通常为空肠与胃直接相连，此段空肠直接接受来自残胃的酸性胃内容物，但缺乏正常十二指肠的保护机制（碱性消化液中和），长期侵蚀下，容易发生吻合口溃疡（E对），可出现上腹痛、黑便，常规药物疗效较差。Cushing溃疡（A错）是中枢神经系统病变（如严重脑外伤）所致的溃疡。发病机制可能与严重应激状态下，交感神经兴奋肾上腺髓质分泌大量儿茶酚胺类激素，导致胃黏膜血管发生痉挛，组织灌流量骤降，导致胃黏膜缺血缺氧，产生溃疡。Curling溃疡（C错）又称柯林溃疡，是指不同程度烧伤后继发的应激性溃疡，主要发生于胃体及胃底。临床上早期除偶有腹部隐痛和黑便外，其他症状甚少，多在发生大出血或穿孔后被发现。发病机制同Cushing溃疡类似。胃大部切除术切除范围包括了十二指肠的好发部位，即十二指肠的球部，因而术后不会再发生十二指肠溃疡（B错）。胃大部切除术不仅切除了泌酸的胃体，亦切除了溃疡的好发部位，因而术后复发性溃疡（D错）发生率低。","","N"],["2001-N113",27,"第四节 肠梗阻","机械性肠梗阻",2001,113,"B","","常以单纯机械性不完全性肠梗阻为表现的是",[["A","嵌顿性股疝"],["B","肠蛔虫团堵塞"],["C","急性乙状结肠扭转"],["D","急性肠套叠"],["E","肠系膜上动脉栓塞"]],"B","本题主要考查与肠道相关的疾病特点。蛔虫团堵塞（B对）在肠腔内引起梗阻是单纯的机械性梗阻，无血运障碍和肠道坏死，由于蛔虫自身存在运动，以及未受损的肠壁有一定的运动能力，故通常为不完全肠梗阻。嵌顿性股疝（A错）是由于部分肠腔嵌顿于疝环中，导致肠内容物无法通过，属于完全性肠梗阻，此外，因股疝疝环狭小，常导致嵌顿肠管血供受影响，容易发展为绞窄性肠梗阻；急性乙状结肠扭（C错）转形成O形受累肠段，扭转部位之间形成密闭肠腔，即发生闭袢性肠梗阻，属于完全性肠梗阻，扭转肠段肠系膜亦随之扭转，导致其血供减少，易发生肠缺血坏死；急性肠套叠（D错）是儿童常见的急腹症，患病处肠道套叠，发生梗阻和血运障碍，属于绞窄性肠梗阻。上述三种疾病，都存在严重的肠道血供障碍和完全阻塞，可引起严重的腹痛，同时炎症渗出可导致明显的腹膜刺激征，症状和体征均十分明显。肠系膜上动脉栓塞（E错）属于缺血性肠病，好发于老年人，由于血栓形成或继发性血栓栓塞导致部分肠段血供缺乏引起，该病以剧烈腹痛为主要表现，广义上属于血运性肠梗阻/绞窄性肠梗阻。","","N"],["2001-N114",27,"第五节 肠系膜血管缺血性疾病","肠系膜上动脉栓塞",2001,114,"B","","以严重的症状和轻微的腹部体征不相称为其特点的是",[["A","嵌顿性股疝"],["B","肠蛔虫团堵塞"],["C","急性乙状结肠扭转"],["D","急性肠套叠"],["E","肠系膜上动脉栓塞"]],"E","肠系膜上动脉栓塞（E对）属于缺血性肠病，好发于老年人，由于血栓形成或继发性血栓栓塞导致部分肠段血供缺乏引起，该病以剧烈腹痛为主要表现，广义上属于血运性肠梗阻/绞窄性肠梗阻，但早期常无明显的腹部阳性体征，表现为严重的症状和轻微的腹部体征不相称，即症征不符。嵌顿性股疝（A错）是由于部分肠腔嵌顿于疝环中，导致肠内容物无法通过，属于完全性肠梗阻，此外，因股疝疝环狭小，常导致嵌顿肠管血供受影响，容易发展为绞窄性肠梗阻，体查可在腹股沟韧带下方卵圆窝处触及半球形突起；蛔虫团堵塞（B错）在肠腔内引起梗阻是单纯的机械性梗阻，腹部体查可见肠型，部分病人可触及腹部肿块（蛔虫团）；急性乙状结肠扭（C错）转形成O形受累肠段，扭转部位之间形成密闭肠腔，即发生闭袢性肠梗阻，属于完全性肠梗阻，扭转肠段肠系膜亦随之扭转，导致其血供减少，易发生肠缺血坏死，体查可见左腹明显膨胀及肠型；急性肠套叠（D错）是儿童常见的急腹症，患病处肠道套叠，发生梗阻和血运障碍，属于绞窄性肠梗阻，表现为腹痛、血便、腹部肿块。","","N"],["2001-N115",57,"第四节 原发性恶性骨肿瘤","骨肉瘤治疗",2001,115,"B","","骨肉瘤采用的治疗方法是",[["A","化疗"],["B","放疗"],["C","根治性手术"],["D","化疗和根治性手术"],["E","放疗和根治性手术"]],"D","骨肉瘤是典型的恶性肿瘤，应采取手术治疗。但单纯根治性手术（C错）5年存活期不足20%（参阅七版黄家驷外科学P3080）。由于对化疗敏感，因此术前、术后可给予大剂量化疗，可降低瘤负荷，延长患者生存期，因此最佳治疗方法为化疗和根治性手术（D对）。除少数血液系统肿瘤及滋养层细胞肿瘤、睾丸精原细胞瘤、胚胎性横纹肌肉瘤可单独应用化疗（A错）以外，多数恶性肿瘤应采取手术治疗为主的综合治疗。骨肉瘤对于放射治疗（BE错）通常不敏感。","","N"],["2001-N116",57,"第四节 原发性恶性骨肿瘤","软骨肉瘤治疗",2001,116,"B","","软骨肉瘤采用的治疗方法是",[["A","化疗"],["B","放疗"],["C","根治性手术"],["D","化疗和根治性手术"],["E","放疗和根治性手术"]],"C","软骨肉瘤为骨的恶性肿瘤，对于放疗和化疗均不敏感，只能根据外科分期和肿瘤部位来制定手术方法，低度恶性软骨肉瘤可行广泛或根治性切除及保肢手术（C对）。","","N"],["2001-N135",28,"第二节 急性阑尾炎","急性阑尾炎的并发症",2001,135,"C","","急性阑尾炎时可并发",[["A","门静脉炎"],["B","细菌性肝脓肿"],["C","二者均可"],["D","二者均不可"]],"C","化脓性门静脉炎为急性阑尾的并发症之一。阑尾静脉属于回、结肠静脉终末支，其血流经回结肠静脉、肠系膜上静脉、门静脉入肝。急性阑尾炎时，阑尾静脉中的感染性血栓，可沿肠系膜上静脉至门静脉，导致化脓性门静脉炎症；如病情加重会产生感染性休克和脓毒症，治疗延误可发展为细菌性肝脓肿（C对）。本题AB均对，正确答案为C。","","N"],["2001-N136",32,"第五节 胆道感染","急性梗阻性化脓性胆管炎临床表现",2001,136,"C","","急性化脓性胆管炎时可并发",[["A","门静脉炎"],["B","细菌性肝脓肿"],["C","二者均可"],["D","二者均不可"]],"B","急性化脓性胆管炎若胆道内压力过高，胆汁中的感染性物质可通过毛细胆管的肝细胞屏障直接进入肝组织中，从而引起细菌性肝脓肿（B对）；胆道与门静脉分属两个管腔系统，并无直接交叉，因而急性化脓性胆管炎一般不会直接并发门静脉炎（A错）。","","N"],["2001-N137",45,"第六节 肱骨髁上骨折","伸直型肱骨髁上骨折并发症",2001,137,"C","","伸直型肱骨髁上骨折可并发",[["A","重要动脉损伤"],["B","重要神经损伤"],["C","二者均可"],["D","二者均不可"]],"C","肱骨髁内、前方，有肱动脉、正中神经经过，血管神经束的浅面有坚韧的肱二头肌腱膜，后方为肱骨，导致肱动脉、正中神经活动度较小。伸直型肱骨髁上骨折由于近折端向前下移位，极易损伤前方的肱动脉（A对）及正中神经（B对）。本题AB均对，正确答案为C。","","N"],["2001-N138",47,"第二节 股骨近端骨折","股骨颈骨折临床表现与诊断",2001,138,"C","","股骨下1/3骨折可并发",[["A","重要动脉损伤"],["B","重要神经损伤"],["C","二者均可"],["D","二者均不可"]],"C","股骨下1/3骨折，远折端受腓肠肌牵拉及肢体重力作用，向后方移位，常常损伤腘动脉（A对）、腘静脉、胫神经、腓总神经（B对）。本题AB均对，正确答案为C。","","N"],["2001-N157",1,"第三节 钾代谢紊乱","高钾血症治疗",2001,157,"X","","治疗高钾血症时，静脉注射高渗碱性溶液（5%碳酸氢钠）的作用是",[["A","增加血容量，K⁺得到稀释"],["B","使K⁺移入细胞内或由尿排出，减轻酸中毒"],["C","Na⁺可对抗K⁺的作用"],["D","对抗心律失常"]],"ABC","高钾血症有导致病人心搏突然停止的危险，故一经诊断需积极治疗。治疗方法主要概括为以下几点：1.停止一切含钾离子药物使用；2.静脉注射5％碳酸氢钠；3.使用葡萄糖溶液及胰岛素（又称“极化液”）；4.口服阳离子交换树脂；5.对于血钾高于6.5mmol/L或上述降钾治疗无效者，予透析治疗快速降钾；6.10%葡萄糖酸钙20ml缓慢静脉注射可用于拮抗高钾的心脏毒性作用，用于对抗心律失常。高钾血症的急救是临床医生必须掌握的知识。其中静脉注射5％碳酸氢钠的作用是：①注射的高渗溶液可使血容量增加，使血清K⁺得到稀释（A对）；②注射碳酸氢钠溶液造成的碱血症可促进K⁺移入细胞内，降低细胞外K⁺的浓度；③增加肾远曲小管中Na⁺含量，增加Na⁺、K⁺交换，使K⁺由尿排出，减轻酸中毒（B对）。此外，碳酸氢钠溶液可以升高血钠，促进去极化时钠离子内流，改善高血钾引起的心肌传导性下降，进而起到对抗K⁺的作用（C对）。钙离子能缓解K⁺对心肌的毒性作用，可对抗心律失常，而钠离子无抗心律失常的作用（D错）。","","N"],["2001-N158",18,"第三节 乳腺良性疾病","急性乳腺炎治疗",2001,158,"X","","急性乳腺炎脓肿形成切开引流时应注意",[["A","一般做放射状切口"],["B","将脓腔间隔打开"],["C","切口在脓腔的最低位"],["D","做对口引流使引流通畅"]],"ABCD","急性乳腺炎的治疗原则是消除感染、排空乳汁。早期呈蜂窝织炎表现而未形成脓肿之前，应用抗生素可获得良好的效果。当脓肿形成时，单纯保守治疗则易导致更多的乳腺组织受累，故此时主要治疗措施是及时作脓肿切开引流。手术时要有良好的麻醉，为避免损伤乳管而形成乳瘘，一般做放射状切口（A对），切开后以手指轻轻分离脓肿的多房间隔（B对），以利引流。脓腔较大时，可在脓腔的最低部位另加切口作对口引流（CD对），以利引流。","","N"],["2001-N159",26,"第三节 胃十二指肠溃疡的外科治疗","碱性反流性胃炎",2001,159,"X","","胃大部切除术后碱性反流性胃炎的典型临床表现是",[["A","剑突下持续烧灼痛，进食后加重，抗酸剂无效"],["B","胆汁性呕吐，呕吐后疼痛依旧"],["C","脂肪泻"],["D","体重减轻"]],"ABD","碱性反流性胃炎常发生于毕Ⅱ式手术后，原因是胃空肠吻合后，正常解剖结构改变，失去幽门-十二指肠的抗返流屏障，碱性胆汁、胰液、肠液流入胃中，破坏胃黏膜屏障，导致胃黏膜充血，水肿、糜烂等改变；临床主要表现为，上腹或胸骨后烧灼痛、呕吐胆汁样液（B对）和体重减轻（D对）；抑酸剂治疗无效，较为顽固（A对）。脂肪泻主要见于慢性胰腺炎，胆汁排泄不畅相关疾病也可引起，但碱性反流性胃炎不见此症状（C错）。","","N"],["2001-N160",55,"第一节 骨与关节结核概论","骨与关节结核发病特点",2001,160,"X","","骨关节结核好发于",[["A","负重大的部位"],["B","活动多、易遭受慢性或积累性劳损的部位"],["C","肌肉附着少的部位"],["D","易受急性外伤的部位"]],"ABC","骨关节结核好发于脊椎，约占全部病例的50%，其次是髋关节、膝关节和肘关节等。这些部位大多在负重大（A对）、活动多、易遭受慢性劳损（B对）以及肌肉附着少（C对）的部位。急性外伤通常造成非特异性感染，极少引起结核杆菌的感染（D错）。","","N"],["2002-N75",10,"第四节 局部麻醉","适应证和并发症",2002,75,"A","","锁骨上臂丛神经阻滞最常见的并发症是",[["A","膈神经麻痹"],["B","椎动脉内注射"],["C","脊髓阻滞"],["D","喉返神经阻滞"],["E","气胸"]],"E","锁骨上臂丛神经阻滞的并发症包括：膈神经麻痹（A）、脊髓阻滞（C）、喉返神经阻滞（D）、霍纳综合征、气胸。锁骨上臂丛神经阻滞进针位置邻近胸膜顶部，因操作不当而穿破胸膜的概率远比损伤神经大，因此锁骨上臂丛神经阻滞最常见的并发症是气胸（E对）。","","N"],["2002-N76",12,"第二节 心肺脑复苏","胸外按压",2002,76,"A","","心肺复苏心脏按摩时，按压与放松时间之比应为",[["A","70%：30%"],["B","60%：40%"],["C","50%：50%"],["D","40%：60%"],["E","30%：70%"]],"C","心脏胸外按压是CPR非常重要的一部分，关于胸外按压需注意（十版外科学P161）：按压位置为胸骨下1/2，即两乳头连线中点的胸骨上；频率100次～120次/分；深度至少5cm（避免超过6cm）；再次按压前应给予胸廓回弹充分的时间；维持胸外按压的连续性，尽量避免或减少因人工呼吸或电除颤而使胸外按压中断的时间。","","N"],["2002-N77",1,"第四节 镁、钙、磷代谢紊乱","钙、磷代谢紊乱概述",2002,77,"A","","关于体内钙的叙述，下列哪项不正确",[["A","血清钙的浓度一般相当稳定"],["B","血清钙浓度为2.25～2.75mmol/L"],["C","不少外科病人可发生不同程度的钙代谢紊乱"],["D","机体内的钙99%以磷酸钙和碳酸钙的形式贮存于骨骼中"],["E","血清中的非离子化钙不到半数，但却起着维持神经肌肉稳定性的作用"]],"E","正常人血清钙浓度接受甲状旁腺激素、降钙素、活性维生素D等多种激素的调节，因而血清钙的浓度一般相当稳定（A对），血清钙浓度在2.25～2.75mmol/L（B对）之间小幅度波动。不少外科病人可发生不同程度的钙代谢紊乱（C对），尤以低钙血症为多，常见于急性重症胰腺炎、坏死性筋膜炎、肾衰竭、消化道瘘和甲状旁腺功能受损的患者。机体内的钙99%以磷酸钙和碳酸钙的形式贮存于骨骼中（D对），细胞外钙仅占总钙量的0.1%，其中45%为离子化钙，它有维持神经肌肉稳定性的作用（E错，为本题正确答案）。","","N"],["2002-N78",2,"第一节 输血的适应证和注意事项","输血注意事项",2002,78,"A","","关于输血技术和注意的问题中，下列哪项不正确",[["A","我国目前的抗凝血最长保存14天"],["B","一般速度下输入1～2L冷藏血时不需要预热"],["C","不应向输入的血液中加任何药物，以免发生凝血或溶血"],["D","一次输血不应超过4小时，以避免室温下引起细菌繁殖"],["E","应使用带有过滤器的输血器，以便滤出细胞聚集物和纤维蛋白块"]],"A","我国目前使用的抗凝剂为枸橼酸盐磷酸盐葡萄糖和酸性枸橼酸盐葡萄糖，在2～8℃，抗凝血可保存21天，如果在前者中加入腺苷，可保存35天（A错，为本题正确答案）。BCDE项都是输血的基本原则。","","N"],["2002-N79",3,"第一节 外科休克概述","微循环的变化",2002,79,"A","","人体的微循环约占总循环量的",[["A","5%"],["B","10%"],["C","15%"],["D","20%"],["E","25%"]],"D","微循环是指微动脉和微静脉之间的血液循环。典型的微循环由微动脉、后微动脉、毛细血管前括约肌、真毛细血管、通血毛细血管（或称直捷通路）、微静脉和动-静脉吻合支等部分组成。人体的微循环约占总循环量的20%（D对）。","","N"],["2002-N80",13,"第三节 术后并发症的防治","肺膨胀不全",2002,80,"A","","下列预防和治疗术后肺不张的措施中，哪项是不恰当的",[["A","鼓励咳痰"],["B","防止呕吐"],["C","术前锻炼深呼吸"],["D","术后胸、腹部切口应紧紧固定或绑扎"],["E","减少肺泡和支气管内分泌物增多，如术前4周应禁烟"]],"D","鼓励咳嗽咳痰（A对）有利于肺部分泌物排出，保持呼吸道通畅；防止呕吐（B对）的目的是避免呕吐物被吸入呼吸道引起吸入性肺炎；术前锻炼深呼吸（C对），增加肺通气量，对术后保持较高通气量有帮助，且深呼吸可以促使肺泡膨胀，减少肺不张的发生几率；香烟烟雾中含有的焦油、尼古丁和镉等有害物质能损伤呼吸道黏膜，降低局部抵抗力，烟雾还会刺激小气道产生痉挛，从而增加气道阻力，术前必须戒烟，有利于呼吸道功能的恢复，减少肺泡和支气管内分泌物（E对）。术后胸、腹部切口的固定或绑扎限制了胸廓或膈肌的活动度，使得肺通气量减少，不利于肺膨胀不全的预防和治疗，且增加了肺部感染的几率（D错，为本题正确答案）。","","N"],["2002-N81",5,"第七节 外科应用抗菌药的原则","围手术期预防用药的原则",2002,81,"A","","外科应用抗菌药物时，正确的是",[["A","抗菌药物的剂量一般按年龄计算"],["B","应用抗菌药物后，可以减免一些外科处理"],["C","所有的外科感染均需应用抗菌药物"],["D","外科感染时，一般情况下首选广谱抗生素并联合用药"],["E","手术的预防用药应在术前1小时或麻醉开始时静脉滴入，一般均在术后24小时内停药"]],"E","抗菌药物的剂量一般按药物本身的安全剂量范围来给药（A错），而抗菌药物种类的选择与年龄、身体状况、体重等相关。应用抗菌药物后，不可以减免一些外科处理（B错），因为去除感染灶、通畅引流是外科治疗的基本原则，任何一种抗菌药物都不能取代引流等外科处理。一般来说，抗菌药物在外科感染治疗中仅起到辅助作用。并非所有的外科感染均需应用抗菌药物（C错），例如疖和痈未引起全身症状时，仅需要通过保持皮肤清洁、外用中药及理疗即可治愈，无需使用抗生素；抗生素的使用有其严格的指征。广谱抗生素并联合用药具有广泛的抑菌作用，除了抑制致病菌外，同时抑制正常菌群，有可能造成菌群失调甚至二重感染的可能，故对于抗生素的使用尽可能选用病原菌敏感的抗生素，非必要情况不采用联合用药（D错）。手术预防性抗生素的给药方法：应在术前0.5～2小时或麻醉开始时首次给药；手术时间超过3小时或失血量大于1500ml，术中可给予第二剂；总预防用药时间一般不超过24小时，个别情况可延长至48小时（E对）。","","N"],["2002-N82",17,"第一节 甲状腺疾病","甲状旁腺功能减退",2002,82,"A","","甲状腺次全切除术后，病人出现手足抽搐发作时，最便捷而有效的治疗是",[["A","静脉注射10%葡萄糖酸钙或氯化钙10～20ml"],["B","口服葡萄糖酸钙或乳酸钙2～4g"],["C","口服维生素D₃5万～10万U"],["D","口服双氢速变固醇油剂"],["E","停食肉类、乳品和蛋类食品"]],"A","甲状旁腺激素（PTH）是调节钙代谢最重要的激素，有升血钙降血磷的作用。甲状旁腺损伤后，PTH分泌不足，故甲状旁腺损伤者血钙下降，表现为面部、口周或肢端发麻，严重者有手足抽搐。发生甲状旁腺损伤后，立即静脉注射10%葡萄糖酸钙或氯化钙10～20ml（A对），可迅速提高血钙，为最便捷而有效的方法。口服葡萄糖酸钙或乳酸钙2～4g（B错），每日3次，适用于症状轻者；口服维生素D₃5万～10万U（C错），适用于症状较重或长期不能恢复者，可促进钙在胃肠内的吸收，起效缓慢。口服双氢速变固醇油剂（D错）能明显提高血中钙含量，降低神经肌肉的应激性，药效缓慢而持久。肉类、乳品和蛋类食品（E错）因含磷较高，可影响钙的吸收，停食这些食品，可有助于缓慢升高血钙。BCDE所述四种方法虽都可使血钙升高，但都不适合急救。","","N"],["2002-N83",23,"第一节 腹外疝概述","难复性疝",2002,83,"A","","关于腹外疝的叙述，下列哪项是正确的",[["A","滑疝多见于左侧"],["B","滑疝也属难复性疝"],["C","疝内容物以大网膜最多见"],["D","直疝多见于中年肥胖者"],["E","儿童的嵌顿疝易发生绞窄"]],"B","少数病程较长的疝，因疝的长期移动，导致疝囊颈周围结构松弛，以致盲肠、乙状结肠或膀胱随之下移而形成疝囊壁的一部分，这种疝称为滑疝，多见于右侧腹股沟，属于难复性疝（B对），滑动疝多见于右侧（A错），左右发病率之比约为1：6。难复性疝疝内容物以大网膜最多见，腹外疝疝内容物以小肠最多见（C错）。腹股沟直疝常见于年老体弱者（D错），股疝多见于中年肥胖妇女。儿童的疝，因为疝环组织比较柔软，虽易嵌顿但不易绞窄（E错）。","","N"],["2002-N84",25,"第一节 急性弥漫性腹膜炎","腹痛",2002,84,"A","","继发性腹膜炎时，腹痛的特点是",[["A","疼痛剧烈而持续"],["B","阵发性腹痛，逐渐加重"],["C","改变体位可使腹痛缓解"],["D","原发病变部位疼痛不明显"],["E","先发热后腹痛"]],"A","根据病因不同，腹膜炎的症状可以是突然发生，也可能是逐渐出现的。如空腔脏器损伤破裂或穿孔引起的腹膜炎发病较突然；而阑尾炎、胆囊炎等引起的腹膜炎多先有原发病症状，以后才逐渐出现腹膜炎表现。腹痛是腹膜炎最主要的临床表现。疼痛的程度与发病的原因、炎症的轻重、年龄、身体素质等有关。继发性腹膜炎的疼痛一般都很剧烈，难以忍受，呈持续性（A对B错）。深呼吸、咳嗽、转动身体时疼痛加剧（C错）。病人多不愿改变体位。疼痛先从原发病变部位开始，随炎症扩散而延及全腹，而以原发病变部位为著（D错）。发热作为全身症状，往往在局部症状发展到一定程度、伴随炎症的扩散及毒素的吸收逐步体现出来，故通常为先腹痛后发热（E错）。","","N"],["2002-N85",26,"第二节 胃癌及其他胃肿瘤","胃癌淋巴转移",2002,85,"A","","关于胃癌的淋巴转移，下列哪项是正确的",[["A","胃癌浸润深度与淋巴结转移无相关关系"],["B","淋巴转移不是胃癌的主要转移途径"],["C","无跳跃式淋巴结转移"],["D","恶性程度较高或较晚期的胃癌可转移至锁骨上淋巴结"],["E","区域淋巴结转移部位与原发肿瘤的部位无关"]],"D","终末期胃癌可经胸导管向左锁骨上淋巴结转移（D对）或经肝圆韧带转移至脐部。胃部的淋巴组织丰富，淋巴转移是胃癌的主要转移途径（B错），进展期胃癌的淋巴转移率高达70%左右，侵及黏膜下层的早期胃癌淋巴转移率近20%，由此不难得出胃癌浸润深度与淋巴结转移有一定关系（A错）。胃癌的淋巴结转移通常是循序渐进，但也可发生跳跃式淋巴转移（C错），即第一站无转移而第二站有转移。不同部位的胃肿瘤其淋巴回流途径不同，因而区域淋巴结转移部位与原发肿瘤的部位相关（E错）。常见的不同部位胃癌各站淋巴结划分参考（P371表38-3）。","","N"],["2002-N86",28,"第三节 特殊类型阑尾炎","妊娠期急性阑尾炎",2002,86,"A","","处理妊娠期急性阑尾炎的措施，下列哪项不正确",[["A","以非手术治疗为主"],["B","妊娠后期应及早手术"],["C","围手术期加用黄体酮"],["D","手术切口需偏高，以减少对子宫的刺激"],["E","术后使用广谱抗生素"]],"A","妊娠期阑尾炎若不及时治疗，炎症发展易导致流产或早产，威胁母子生命安全，治疗以手术治疗为主（A错，为本题正确答案），妊娠早期以阑尾切除术为主，后期的腹腔感染难以控制，更应早期手术（B对）；围术期加用黄体酮（C对），因为黄体酮可以抑制子宫的收缩，从而起到保胎的作用。手术切口须偏高，操作要轻柔，以减少对子宫的刺激（D对），因为妊娠时子宫逐渐增大，将盲肠和阑尾推挤向右上腹移位。妊娠是一个特殊阶段，孕妇一旦发生术后感染，则严重威胁母子生命，故需预防性术后使用广谱抗生素（E对）。","","N"],["2002-N87",29,"第二节 结、直肠及肛管检查方法","直肠指诊",2002,87,"A","","直肠指检不易发现的病变是",[["A","肛瘘"],["B","直肠息肉"],["C","内痔"],["D","肛管直肠癌"],["E","盆腔脓肿"]],"C","肛垫的支持结构、静脉丛及动静脉吻合支发生病理性改变或移位为内痔，本质是肥大、移位的肛垫；临床上最为多见，位于齿状线上方，表面被直肠黏膜所覆盖，质地多较柔软，故直肠指检不易发现（C对）。肛瘘（十版外科学P415）（A错）患者行直肠指检，在瘘道内口处可有轻度压痛，双指合诊可扪及瘘内口处小硬结或条索样瘘管。直肠息肉（十版外科学P415）（B错）患者行直肠指检，可扪及质软可推动的圆形肿块，多发息肉则可扪及大小不等的质软肿块，移动度大的息肉多可扪及蒂部。肛管直肠癌（十版外科学P415）（D错）患者行直肠指检，可扪及高低不平的硬结、溃疡、菜花样肿物，肠腔可有狭窄，指套上常有脓血和黏液。盆腔脓肿（E错）患者行直肠指检，可在直肠前壁触及波动感。","","N"],["2002-N88",32,"第五节 胆道感染","急性梗阻性化脓性胆管炎治疗原则",2002,88,"A","","急性梗阻性化脓性胆管炎的治疗原则，最主要的是",[["A","纠正水、电解质紊乱"],["B","使用足量有效的广谱抗生素"],["C","恢复血容量"],["D","改善和维持主要脏器功能"],["E","紧急手术"]],"E","重症胆管炎的严重临床表现与导管内高压导致胆汁及细菌向血液反流有关。重症急性胆管炎进展迅速，须早期采取积极的措施。原则是紧急手术（E对），切开胆总管减压，去除结石解除梗阻和通畅引流胆道。纠正水、电解质紊乱（A）、使用足量有效的广谱抗生素（B）、恢复血容量（C）及改善和维持主要脏器功能（D）仅为一般性对症保守治疗措施。保守治疗，胆管内压力得不到缓解，压力持续增高引起胆血反流，造成严重的全身感染症状、甚至出现感染性休克，故AOSC决不能保守治疗。","","N"],["2002-N89",33,"第二节 胰腺炎","胰酶测定",2002,89,"A","","急性胰腺炎时，血清淀粉酶变化的特点，下列哪项不正确",[["A","发病24小时内即可被测得"],["B","淀粉酶﹥500U/dl（索氏法）可诊断"],["C","尿淀粉酶升高持续时间比血淀粉酶长"],["D","淀粉酶值的高低与病变程度成正比"],["E","淀粉酶的测值越高，诊断的准确率也越高"]],"D","血清淀粉酶在发病数小时开始升高，24小时达高峰（A对）。血清淀粉酶的正常值为40～180U/dl，其值超过500U/dl有诊断价值（B对）。尿淀粉酶下降缓慢，1～2周后恢复正常，而血清淀粉酶在发病4～5天后逐渐降至正常，由此可见尿淀粉酶升高持续时间比血淀粉酶长（C对）。淀粉酶是自损伤的胰腺中释放出来，淀粉酶的测值越高，说明损伤的可能性越大，诊断的准确率也就越高（E对）。重症急性胰腺炎时，胰腺出血坏死广泛，胰腺细胞大量坏死，不再产生和释放淀粉酶，血尿淀粉酶可不升高甚至出现降低，故淀粉酶的高低与病变程度不成正比（D错，为本题正确答案）。","","N"],["2002-N90",50,"第一节 周围神经损伤概论","叩击试验（Tinel征）",2002,90,"A","","下列哪项检查用于周围神经损伤的诊断",[["A","Thomas征"],["B","Tinel征"],["C","Hoffmann征"],["D","Babinski征"],["E","Dugas征"]],"B","Tinel征（B对），即叩击试验，即可帮助判断神经损伤的部位，也可用于检查神经修复后神经纤维的再生情况。判断神经损伤的方法为局部按压或叩击神经干，局部出现针刺性疼痛，并有疼痛感向该神经支配区放射为阳性，表示为神经损伤部位。Thomas征（十版外科学P746）（A错），病人仰卧，充分屈曲健侧髋和膝，并使腰部贴于床，若患肢自动抬高离开床面或迫使患肢与床面接触则腰部前突，为托马斯征阳性，见于髋部病变和腰肌挛缩。Hoffmann征（C错）和Babinski征（D错）属于病理反射，见于锥体束损伤患者。Dugas征（十版外科学P631）（E错）用于检测是否存在肩关节脱位，操作为将肩关节前脱位病人伤肢肘部接触胸前部，则手部不能触及健肩；反之将伤肢手部触及健肩时，其肘部不能接触胸前部，此为Dugas征阳性，是肩关节前脱位的特征性体征。","","N"],["2002-N91",47,"第二节 股骨近端骨折","股骨颈解剖概要",2002,91,"A","","下列各项中，哪项更有助于鉴别股骨颈骨折与股骨粗隆间骨折",[["A","髋关节压痛"],["B","患肢轻度内收"],["C","Bryant三角底边短缩"],["D","患肢外旋角度"],["E","患肢短缩程度"]],"D","股骨粗隆间骨折即股骨转子间骨折。股骨颈骨折与股骨粗隆间骨折均会出现髋关节压痛（A错）、Bryant三角底边短缩（C错）、患肢短缩（E错），故不能用上述三点来鉴别两者。两种骨折均可出现患肢外旋（B错），但股骨粗隆间骨折外旋可达到甚至超过90°，而股骨颈骨折外旋一般在45°～60°之间。因此，可根据患肢外旋角度（D对）鉴别股骨颈骨折与股骨粗隆间骨折。","","N"],["2002-N92",57,"第三节 骨巨细胞瘤","骨巨细胞瘤临床表现",2002,92,"A","","关于骨巨细胞瘤，下列哪项是错误的",[["A","多发于20～40岁的青壮年"],["B","好发于胫骨上端、股骨下端及桡骨远端"],["C","可有复发及转移"],["D","早期局部彻底切刮术加灭活处理是治疗的关键"],["E","Codman三角为其X线特点"]],"E","骨巨细胞瘤好发于20～40岁（A对）的青壮年，女性略多，好发部位为长骨干骺端和椎体，特别是胫骨上端、股骨下端及桡骨远端（B对）。骨巨细胞瘤为良性肿瘤，但是具有局部侵袭性，也有人将其归类为交界性肿瘤，存在一定的复发和转移可能（C对）。早期局部彻底切刮术加灭活处理是治疗的关键（D对），其目的是在完全切除肿瘤组织的同时，清除可能存在的浸润灶。骨巨细胞瘤的典型X线表现为骨端偏心性、溶骨性、囊性破坏而无骨膜反应，病灶膨胀生长，骨皮质变薄，呈肥皂泡样改变。Codman三角为骨肉瘤的X线特点（E错，为本题正确答案）。肿瘤生长迅速，将骨膜顶起，骨膜下产生新生骨，出现三角形的骨膜反应，即Codman三角。","","N"],["2002-N111",29,"第六节 结肠癌","结肠癌诊断",2002,111,"B","","可经门脉系统转移到肝的肿瘤是",[["A","肺癌"],["B","乳腺癌"],["C","结肠癌"],["D","皮肤癌"],["E","四肢肉瘤"]],"C","门脉系统接受的主要是来自于消化道回流的静脉血，故发生于消化道的肿瘤易经静脉系统从门静脉入肝发生转移，上述选项中只有结肠癌位于消化道，故选项中只有结肠癌可经门脉系统转移到肝的肿瘤（C对）。","","N"],["2002-N112",18,"第四节 乳腺癌","转移途径",2002,112,"B","","可经椎旁静脉系统转移到骨的肿瘤是",[["A","肺癌"],["B","乳腺癌"],["C","结肠癌"],["D","皮肤癌"],["E","四肢肉瘤"]],"B","椎旁静脉系统由椎内、外静脉丛及连接其间的椎体静脉和椎间静脉组成，该静脉系统缺乏静脉瓣膜，除在本系统内广泛吻合外，还与颅、颈、胸、腰、骶部的静脉交通，且本身压力较低，肿瘤易于通过此途径转移，通过此途径转移的肿瘤常见的有三种，自上而下分别是甲状腺癌、乳腺癌（B对）、前列腺癌。此知识点常考，需牢记。","","N"],["2002-N113",29,"第六节 结肠癌","结肠癌并发急性肠梗阻的手术",2002,113,"B","","女性，51岁，腹胀便血3个月，停止排便排气1周，查体消瘦、贫血、腹胀、移动性浊音（+），纤维结肠镜检见乙状结肠环形缩窄肿物，固定。目前恰当的治疗方法是",[["A","肠粘连松解术或肠扭转、肠套叠复位术"],["B","肠切除吻合术"],["C","短路手术"],["D","肠造口术"],["E","肠外置术"]],"D","51岁女性（中老年患者），腹胀便血3个月，停止排便排气1周（肠梗阻典型临床表现），消瘦、贫血（恶病质），纤维结肠镜见乙状结肠环形缩窄肿物，诊断考虑乙状结肠肿瘤。患者为低位结肠癌，肠梗阻一周，此时全身及肠道局部情况较差，不宜行一期肠切除吻合术（B错），否则可能引起术后肠瘘，宜选用肠造口术（D对）以解除肠梗阻，待全身及肠道状况好转后二期切除肿瘤。肠粘连松解术或肠扭转、肠套叠复位术（A错）分别适用于粘连性单纯性肠梗阻、无坏死的肠扭转、无坏死的儿童肠套叠。短路手术（C错）常用于晚期肿瘤无法切除时的姑息性治疗，或用于严重粘连而无法分离的肠管处置，可有效解除肠道梗阻。肠外置术（E错）指在术中难以准确判断某段肠管是否有生机时，可将该肠段拖出置于腹腔外，术后严密观察肠管情况以决定后续治疗方法。","","N"],["2002-N114",27,"第四节 肠梗阻","肠扭转治疗",2002,114,"B","","男性，45岁，因急性肠梗阻开腹探查，发现小肠肿物致部分小肠扭转。选择治疗的方法是",[["A","肠粘连松解术或肠扭转、肠套叠复位术"],["B","肠切除吻合术"],["C","短路手术"],["D","肠造口术"],["E","肠外置术"]],"B","肠扭转是一种较严重的机械性肠梗阻，可在短时期内发生绞窄、坏死；若不能得到及时正确的处理，将有较高的死亡率；及时手术治疗，将扭转的肠袢回转复位，可降低死亡率。对于该病人，肿物致小肠扭转，可当机立断，在病人病情尚未恶化时，行肠切除吻合术（B对），将肿块切除、扭转小肠复位，或将肿物与扭转小肠共同切除。及时复位（A错）可减低死亡率，但患者有梗阻，不宜采取（注：小肠扭转一般采用Ⅰ期肠切除吻合术，结肠扭转一般采用Ⅰ期切除造瘘，Ⅱ期肠手术吻合）。","","N"],["2002-N115",56,"第三节 类风湿关节炎","类风湿关节炎病理",2002,115,"B","","类风湿性关节炎病变始于",[["A","滑膜"],["B","肌肉及肌腱"],["C","软骨"],["D","骨"],["E","关节囊"]],"A","类风湿关节炎病变始于滑膜（A对）。其基本病理变化为关节滑膜的慢性炎症。早期滑膜充血、水肿，单核细胞、淋巴细胞浸润；滑膜边缘部分增生形成肉芽组织血管翳，并逐渐覆盖于关节软骨表面，软骨下骨，使骨小梁减少，骨质疏松。后期关节面间肉芽组织逐渐纤维化，形成纤维性关节僵直，进一步影响关节功能。","","N"],["2002-N116",52,"股骨头坏死","股骨头坏死病理",2002,116,"B","","人股骨头无菌坏死病变始于",[["A","滑膜"],["B","肌肉及肌腱"],["C","软骨"],["D","骨"],["E","关节囊"]],"D","股骨头无菌性坏死多见于股骨颈骨折病人，由于股骨头血运受损而发生缺血性无菌性坏死，该病变自然起始于骨（D对）。","","N"],["2002-N137",53,"第二节 腰椎退行性疾病","感觉异常",2002,137,"C","","腰3～4椎间盘突出症的临床表现可有",[["A","下肢放射性疼痛"],["B","小腿外侧感觉障碍，拇趾背伸力弱"],["C","二者均有"],["D","二者均无"]],"A","下肢放射性痛多由病变累及坐骨神经所致，而坐骨神经源自腰₄、₅骶₁～₃神经，只要椎间盘突出时累及这些神经根，均可引起下肢放射性痛（A对）。小腿外侧感觉障碍，拇趾背伸力弱（B错）为腰₄～₅椎间盘突出压迫腰5神经的临床表现。","","N"],["2002-N138",53,"第二节 腰椎退行性疾病","感觉异常",2002,138,"C","","腰4～5椎间盘突出症的临床表现可有",[["A","下肢放射性疼痛"],["B","小腿外侧感觉障碍，拇趾背伸力弱"],["C","二者均有"],["D","二者均无"]],"C","下肢放射性痛多由病变累及坐骨神经所致，而坐骨神经源自腰₄、₅骶₁～₃神经，只要椎间盘突出时累及这些神经根，均可引起下肢放射性痛（A对）。腰₄～₅椎间盘突出压迫腰5神经，表现为小腿前外侧及足背内侧感觉障碍，𧿹趾背伸乏力或不能（B对）。本题AB均对，正确答案为C。","","N"],["2002-N157",3,"第三节 感染性休克","感染性休克临床表现",2002,157,"X","","下列哪些是感染性休克病人具有的全身炎症反应综合征（SIRS）的表现",[["A","体温﹥38摄氏度或﹤36摄氏度"],["B","心率﹥90次/分"],["C","呼吸急促﹥20次/分或过度通气，PaCO₂﹤4.3kPa"],["D","白细胞计数﹥12×10⁹/L或﹤4×10⁹/L，或未成熟白细胞﹥0.1%"]],"ABC","在确诊为感染性休克的病人中，可能未见明显的感染病灶，但具有全身炎症反应综合征（SIRS）：①体温﹥38℃或﹤36℃（A对）；②心率﹥90次/分（B对）；③呼吸急促﹥20次/分或过度通气，PaCO₂﹤32.3mmHg（C对）；④白细胞计数﹥12×10⁹/L或﹤4×10⁹/L，或未成熟白细胞﹥10%。原真题答案给出D也为正确选项，可能是未注意到“未成熟白细胞﹥0.1%”为数据错误。","","N"],["2002-N158",4,"第二节 营养评价、营养风险筛查及营养不良诊断","营养评价",2002,158,"X","","临床工作中，评价外科病人营养状况的指标有",[["A","体重测量"],["B","淋巴细胞计数"],["C","氮平衡试验"],["D","血清白蛋白测定"]],"ABCD","评定外科病人的营养状况主要通过临床检查、人体测量、生化及实验室检查来进行。其中常用的指标有：理想体重（A对）；体重指数（BMI）；三头肌皮皱厚度；上臂周径测量；握力测定；血浆蛋白（D对）；氮平衡试验（C对）；总淋巴细胞计数（B对）等。","","N"],["2002-N159",18,"第四节 乳腺癌","转移途径",2002,159,"X","","下列哪些皮肤改变是乳腺癌经淋巴道转移的表现",[["A","局部的可凹性改变"],["B","“橘皮样”改变"],["C","卫星结节"],["D","湿疹样改变"]],"BC","乳腺癌随着病情发展，会出现一些由癌细胞浸润引起的肉眼可见的乳房表现，包括“酒窝征”、“橘皮样改变”和“卫星结节”。局部的可凹性改变（A错）即“酒窝征”，是由于癌细胞累及Cooper韧带，使其缩短导致的皮肤凹陷。“橘皮样改变”（B对）是由于癌细胞浸润浅表组织淋巴管，使得淋巴管阻塞，淋巴液回流障碍，进而造成真皮水肿，由于皮肤毛囊与皮下组织粘连较紧密，在真皮水肿时毛囊处即会形成许多点状小孔，形成了凹凸不平的橘皮样改变。“卫星结节”（C对）虽然在教科书中未提及，但常常出现在考题中，其是由癌细胞沿皮下淋巴管广泛扩散到乳腺及其周围皮肤，形成小结节，甚至彼此融合，称为卫星结节。湿疹样改变（D错）是指乳头湿疹样乳腺癌，此病少见，恶性程度低，发展慢。乳头有瘙痒、烧灼感，以后出现乳头和乳晕的皮肤变粗糙、糜烂如湿疹样，进而形成溃疡。因此，“橘皮样”改变、卫星结节是乳腺癌经淋巴道转移的皮肤改变。","","N"],["2002-N160",50,"第二节 上肢神经损伤","桡神经损伤",2002,160,"X","","桡骨小头脱位伤及桡神经，可以出现下列哪些症状",[["A","不能背伸腕关节"],["B","拇指不能背伸"],["C","2～5指不能背伸"],["D","虎口区感觉障碍"]],"BC","桡骨小头半脱位常损伤桡神经深支，由于深支支配拇指背伸的肌肉群，故会出现拇指不能背伸（B对）、2～5指不能背伸（C对），但此时桡侧腕长伸肌功能完好（因为支配该肌肉的神经纤维在肘上已从桡神经分出），伸腕功能基本正常，而仅有伸拇、伸指障碍。不能背伸腕关节（A错）多见于桡神经在肱骨中下段（桡神经沟处）受损，此时支配伸腕功能的肌肉全部瘫痪。虎口区感觉障碍（D错）多见于桡神经浅支损伤及桡神经主干损伤，因为浅支支配感觉功能。本题解答时应注意题干要求，准确判断出为桡神经深支而不是桡神经干损伤，这对准确解答至关重要。","","N"],["2003-N75",10,"第三节 全身麻醉","依托咪酯",2003,75,"A","","下列哪一种静脉麻醉药更适合用于冠心病病人的麻醉诱导",[["A","硫喷妥钠"],["B","氯胺酮"],["C","依托咪酯"],["D","异丙酚"],["E","咪唑安定"]],"C","常用静脉麻醉药中，硫喷妥钠（A错）除全麻诱导和小儿基础麻醉作用外，可用于控制惊厥，但易引起喉痉挛及支气管痉挛，故哮喘等病人慎用；氯胺酮（B错）亦可用于全麻诱导和小儿基础麻醉，但其可使眼内压和颅内压升高，故青光眼和高颅压患者禁用；依托咪酯不增加心脏负担，对心脏无抑制，适用于年老体弱和危重病人的麻醉，且依托咪酯（C对）有轻微扩张冠状动脉作用，因而适合用于冠心病病人的麻醉诱导；异丙酚（丙泊酚）（D错）用于门诊手术的麻醉具有较大优越性，但是其对心血管系统、呼吸系统抑制作用较强。根据病人的不同情况，选择合适的麻醉药。咪唑安定（咪达唑仑）（E错）为苯二氮䓬类药物，有安定镇静、催眠、抗焦虑、抗惊厥的作用，为常用的麻醉前用药。","","N"],["2003-N76",3,"第三节 感染性休克","感染性休克概述",2003,76,"A","","下列关于休克的叙述，哪项是正确的",[["A","通常在迅速失血超过全身总血量的10%时即出现休克"],["B","失血性休克时，应首先快速输入10%-50%葡萄糖溶液，继之大量输血"],["C","损伤性休克不属于低血容量性休克"],["D","感染性休克多是革兰阴性杆菌所释放的内毒素引起的内毒素性休克"],["E","感染性休克的治疗原则是首选控制感染"]],"D","失血超过全身总量的20%时，即出现休克（A错）；输液扩容时，首先可静脉快速滴注平衡盐溶液和人工胶体液。因为平衡盐溶液可迅速补充血容量，人工胶体液中含有胶体成分，能够提高血浆胶体渗透压，有利于水分的保持。超过10%的葡萄糖溶液为高渗液，不适于一般休克的扩容（B错）。低血容量性休克包括失血性休克和创伤性休克（C错），由大血管破裂或脏器出血引起的称失血性休克，各种损伤或大手术同时具有失血及血浆丢失而发生的休克称创伤性休克。感染性休克主要由革兰氏阴性菌感染、释放内毒素（LPS）引起，革兰氏阳性菌较少见（D对）。无论何种休克，补充血容量是纠正休克引起的组织低灌注和缺氧的关键（E错），血容量不足处理后再考虑其他治疗。","","N"],["2003-N77",5,"第五节 脓毒症","脓毒症病因",2003,77,"A","","下列关于全身性外科感染的叙述，哪项是错误的",[["A","菌血症是脓毒症的一种"],["B","当代外科感染中，革兰阴性杆菌感染已超过革兰阳性球菌感染"],["C","外科真菌感染属条件性感染"],["D","真菌感染时血培养易发现"],["E","伴有厌氧菌感染时易形成脓肿"]],"D","外科感染合并全身炎症反应的表现，如体温、呼吸、循环改变时称为脓毒症。临床上将细菌侵入血液循环，血培养阳性称为菌血症，菌血症是脓毒症的一种（A对）。当代外科感染中革兰阴性杆菌感染已超越革兰阳性球菌（B对）。人体与外界相通的部分（如呼吸道、消化道）定植一部分真菌，正常情况下不会导致机体致病，在机体抵抗力下降或菌群失调等情况下致病，属于条件感染（C对）。真菌属于真核生物，与细菌不同，虽然真菌也可通过血行传播，但是一般血培养使用的培养基主要用于培养细菌，并非真菌的适宜培养基，故真菌感染时血培养不易发现（D错，为本题正确答案）。厌氧菌感染时常伴有需氧菌感染，因为两类细菌有协同作用，能使坏死组织增多，易于形成脓肿（E对）。","","N"],["2003-N78",5,"第六节 有芽胞厌氧菌感染","破伤风临床表现",2003,78,"A","","下列关于破伤风的叙述，哪项是正确的",[["A","是非特异性感染"],["B","临床症状和体征主要是溶血毒素所致"],["C","典型症状是肌紧张性收缩"],["D","伤口的厌氧菌培养是诊断依据"],["E","注射破伤风抗毒素是预防破伤风的最可靠方法"]],"C","破伤风是常和创伤相关联的一种特异性感染（A错），类似结核病、气性坏疽、念珠菌病等，因致病菌不同于一般感染，可引起较为独特的病变。破伤风病菌是破伤风梭菌，为专性厌氧菌，在缺氧环境中，该菌的芽胞发育为增殖体，迅速繁殖并产生大量外毒素，主要是痉挛毒素（B错），导致病人一系列临床症状和体征，其典型症状是肌紧张性收缩（C对）。依据受伤史、典型临床表现以及无破伤风预防免疫注射史，破伤风一般均可及时作出诊断，伤口厌氧菌培养也难发现该菌（D错）。破伤风抗毒素能够中和游离毒素，只在疾病早期有效，毒素已与神经组织结合则难以收效（E错）；创伤后早期彻底清创，改善局部循环才是预防破伤风的最可靠方法。","","N"],["2003-N79",7,"第一节 热力烧伤","烧伤面积",2003,79,"A","","成人双膝以下烧伤，烧伤面积约占体表面积的",[["A","10%"],["B","15%"],["C","20%"],["D","25%"],["E","30%"]],"C","成人双膝以下烧伤，包括双小腿（13%）和双足（7%），总共有20%（C对）。关于成年男性烧伤面积估算（九分法）：头颈部一九；双上肢二九；躯干部三九；双下肢五九再加一。关于具体部位面积估算可用口诀来记忆：3、3、3、5、6、7（分别对应发部、面部、颈部、双手、双前臂、双上臂）；13、13、再加1（分别对应躯干前、躯干后、会阴）；5、7、13、21（分别对应双臀、双足、双小腿、双大腿）。","","N"],["2003-N80",7,"第一节 热力烧伤","烧伤休克的防治",2003,80,"A","","治疗烧伤休克的主要措施是",[["A","止痛"],["B","补液"],["C","吸氧"],["D","抗感染"],["E","正确处理创面"]],"B","大面积烧伤早期最严重的症状是烧伤性休克，属于低血容量休克。烧伤早期大量体液自创面渗出，且体液丧失量多可以从烧伤严重程度进行预测，若给予及时适当的处理，可预防其发生或减轻其严重程度。补液是补充血容量最有效的方式，可有效预防和治疗烧伤性休克（B对）。镇静、止痛（A错）属于对症治疗。患者若合并一氧化碳中毒或吸入性损伤，则应给予吸氧（C错）治疗。烧伤后3～10天，烧伤病人的渗出液回吸收，过程中会带入毒素等，加之前期渗出体液丢失大量营养物质，使得病人面临巨大的感染可能，此时处理创面（D错）、控制感染（E错）为主要措施。","","N"],["2003-N81",9,"第一节 器官、组织和细胞移植概述","移植分类",2003,81,"A","","关于移植，下列哪项说法是错误的",[["A","植皮属于组织移植"],["B","输全血属于细胞移植"],["C","骨髓移植属于细胞移植"],["D","肝移植属于器官移植"],["E","皮肌瓣移植属于器官移植"]],"E","细胞移植是指将适量游离的具有某种功能的活细胞输注到受体的血管、体腔或组织器官内的技术，例如：输注全血（B对）、骨髓移植（C对）、同种胰岛细胞移植。组织移植是指某一种组织如角膜、皮肤（A对）、筋膜、肌腱、软骨、骨、血管等，或整体联合几种组织如皮肌瓣（E错，为本题正确答案）等的移植术。器官移植主要是指实体器官整体或部分的、并需要进行器官所属血管及其他功能性管道结构重建的移植，例如：肾移植、肝移植（D对）、心脏移植等。","","N"],["2003-N82",17,"第一节 甲状腺疾病","甲亢手术和术后注意事项",2003,82,"A","","关于甲亢手术治疗，下列哪项叙述是正确的",[["A","通常需切除双侧腺体的60%～70%"],["B","处理甲状腺上血管时应远离甲状腺上极"],["C","结扎甲状腺下动脉要尽量离开腺体背面靠近颈总动脉处"],["D","甲状腺峡部应予保留"],["E","止血充分时，术野可不放置引流"]],"C","甲状腺的大部分切除术对于中度以上的甲亢仍是目前最常用而有效的疗法。手术应轻柔，细致，按解剖层次进行，严密止血，避免损伤喉返神经、喉上神经，保护甲状旁腺。切除腺体的数量，应根据腺体大小或甲亢程度决定，通常需切除腺体的80%～90%（A错），同时切除峡部（D错），保留6～8g甲状腺组织（成人拇指末节大小甲状腺组织相当于3～4g，两侧均需保留）。术后出血及血肿压迫气管可导致呼吸困难和窒息，故术野常规放置引流管24～48小时（E错）。在处理供应甲状腺的动脉时，为避免损伤喉上神经，手术中结扎、切断甲状腺上极血管时应紧贴甲状腺上极（B错）；为避免损伤喉返神经，手术中结扎、切断甲状腺下极血管时应远离甲状腺下极，要尽量离开腺体背面靠近颈总动脉（C对）。","","N"],["2003-N83",17,"第一节 甲状腺疾病","乳头状癌",2003,83,"A","","下列哪项不是甲状腺乳头状癌的常见特征",[["A","约占成人甲状腺癌的60%"],["B","占儿童甲状腺癌的全部"],["C","肿瘤大部分为单发病灶"],["D","可较早出现颈淋巴结转移"],["E","术后五年治愈率可达90%"]],"C","甲状腺癌是最常见的甲状腺恶性肿瘤，按病理类型可分为乳头状癌、滤泡状腺癌、未分化癌、髓样癌。其中乳头状癌最常见，约占成人甲状腺癌的60%（A对）和儿童甲状腺癌的全部（B对）。多见于30～45岁女性。此型分化好，恶性程度低。虽常有多中心病灶（C错，为本题正确答案），约1/3累及双侧甲状腺，且较早便出现颈淋巴结转移（D对），但预后较好，术后五年治愈率可达90%（E对）。","","N"],["2003-N84",26,"第二节 胃癌及其他胃肿瘤","胃癌病因",2003,84,"A","","下列哪种疾病与胃癌发病无关",[["A","萎缩性胃炎"],["B","胃溃疡"],["C","胃息肉"],["D","胃平滑肌瘤"],["E","胃大部切除术后残胃"]],"D","胃平滑肌瘤是胃比较常见的良性肿瘤，由于其组织来源为间叶组织，因此不会发生癌（D错，为本题正确答案），仅可以恶变为胃平滑肌肉瘤。考生应注意鉴别癌和肉瘤的区别。萎缩性胃炎（A对）、胃溃疡（B对）、胃息肉（C对）、胃大部切除术后残胃（E对）均可发生的慢性炎症反应，由于炎症因子的长期慢性刺激，可导致个别细胞增长繁殖及分化失去正常的调控，产生癌变，导致胃癌。","","N"],["2003-N86",31,"门静脉高压","门静脉解剖概要",2003,86,"A","","下列关于门静脉的描述，哪项是错误的",[["A","未阻断的情况下，门静脉压的正常值约在13～24cmH₂O之间"],["B","门静脉压力增高时首先出现的是交通支扩张"],["C","门静脉主干是由肠系膜上静脉和脾静脉汇合而成"],["D","门静脉与腔静脉之间的交通支最主要的是胃底-食管下段交通支"],["E","门静脉无瓣膜"]],"B","未阻断的情况下，门静脉压的正常值约在13～24cmH₂O之间（A对）。门静脉主干是由肠系膜上静脉和脾静脉汇合而成（C对）。十版外科学认为门静脉主干是由肠系膜上、下静脉和脾静脉汇合而成，这种说法是不严谨的，因为多数患者肠系膜下静脉在胰腺后方注入脾静脉或肠系膜上静脉。门静脉与腔静脉系统间存在四个交通支，其中最主要的是胃底-食管下段交通支（D对）。门静脉无瓣膜（E对），其压力通过流入的血量和流出阻力形成并维持。门静脉压力升高时，首先出现充血性脾大（B错，为本题正确答案），当压力进一步升高时，可出现交通支扩张。","","N"],["2003-N87",31,"门静脉高压","顽固性腹水",2003,87,"A","","对于肝硬化引起的顽固性腹水，最有效的治疗方法是",[["A","腹腔穿刺抽水"],["B","腹腔置管引流"],["C","肝内门体分流术"],["D","腹腔-静脉转流术"],["E","肝移植"]],"E","肝移植（E对）既替换了病肝，又使门静脉系统血流动力学恢复到正常，是理想的治疗方法。但肝脏供体缺乏，费用昂贵，需终身服用免疫抑制剂、手术风险限制了肝移植的临床推广。肝硬化并发顽固性腹水时，腹腔穿刺抽水（A错）及腹腔置管引流（B错）属于治标不治本的方法，穿刺腹水带走大量蛋白质，腹水可迅速再生。采用经颈静脉肝内门体分流术（C错）治疗，近期效果较好，远期效果不够理想，主要问题是支撑管可进行性狭窄和并发肝功能衰竭、肝性脑病。腹腔-静脉转流术（D错）可导致进入肝脏的血流减少，可加重肝功能损害，亦可以导致肝性脑病的发生。","","N"],["2003-N88",32,"第十一节 胆道恶性肿瘤","胆囊癌病理",2003,88,"A","","关于胆囊癌的叙述，下列哪项是正确的",[["A","约1/3胆囊癌并存胆囊结石"],["B","多发生在胆囊颈部"],["C","以硬性腺癌较多见"],["D","男性多发"],["E","预后较好"]],"C","腹腔内的肿瘤一般均以腺癌多见。胆囊癌病例中，腺癌约占82%，其中又以硬性腺癌较多见（C对）。胆囊癌的病因尚不清楚，临床观察胆囊癌常与胆囊良性疾患同时存在，最常见是与胆囊结石共存，胆结石越大胆囊癌的危险性越高，约70%胆囊癌并存胆囊结石（A错）。胆囊癌好发于胆囊体部及胆囊底部（B错）。胆道疾病多见于女性，胆囊癌亦不例外，男女比例约1：3～4（D错）。总体来讲，胆囊癌手术预后较差（E错），后期生存率仍然较低，术后患者很少生存半年以上。","","N"],["2003-N89",32,"第四节 胆石症","胆囊结石治疗",2003,89,"A","","治疗胆囊结石，方法正确又效果确切的是",[["A","药物溶石疗法"],["B","体外震波碎石术"],["C","经皮胆囊取石术"],["D","胆囊切除术"],["E","胆囊切除、胆总管探查引流术"]],"D","胆囊结石的治疗历史较长，方法较多，但仍以外科手术治疗为主。药物溶石疗法（A错）通过口服鹅脱氧胆酸或熊脱氧胆酸，通过改变胆汁的成分促进结石的自我溶解，但总体而言其疗效差、肝毒性大、服药时间长、复发率高。 体外震波碎石术（B错）常用于肾结石及上段输尿管结石的治疗，在胆囊结石中用之甚少，且可导致胆管结石形成；碎石后若残留较大结石，需再次碎石治疗。经皮胆囊取石术（C错）术后复发率高，且引起胆汁性腹膜炎的可能性较大。胆囊结石的外科治疗最常用的手术方法仍然是胆囊切除术（D对）。胆囊结石患者75%～90%可合并慢性胆囊炎，胆囊可发生不同程度的萎缩，此时胆囊已失去浓缩及排泄胆汁的生理功能，只有手术切除胆囊，才能彻底消除结石的产生。行胆囊切除术时，只有具有胆总管探查指征时，才行胆总管探查术（E错）。胆总管探查指征为：胆总管存在梗阻；术中证实胆总管存在病变；胆总管扩张，直径超过1cm，胆囊壁明显增厚，发现胰头肿物；胆囊结石小，有可能通过胆囊管进入胆总管。","","N"],["2003-N90",44,"第一节 骨折的定义、成因、分类及移位","螺旋形骨折",2003,90,"A","","下列骨折中，最不稳定的是",[["A","L₂椎体1/4压缩骨折"],["B","股骨干螺旋形骨折"],["C","肱骨干青枝骨折"],["D","胫骨上端横形骨折"],["E","肩胛骨裂纹骨折"]],"B","股骨干螺旋形骨折（B对）时，由于重力的存在，应力在螺旋形接触面上发生分解，两端骨易发生相互交错，故属于不稳定骨折。L₂椎体1/4压缩骨折（A错）因质密骨质、相互嵌插，两段骨不易发生相对移位，属于稳定性骨折。肱骨干青枝骨折（C错）好发于儿童，骨折与青嫩树枝被折时的情况相似，因骨质柔韧不易完全断裂，属于稳定性骨折。胫骨上端横行骨折（D错）接触面与躯体重力应力方向垂直，不产生水平方向的应力，属于稳定骨折。肩胛骨裂纹骨折（E错）仅为肩胛骨骨质上出现部分裂缝，并未破坏整块骨的连接，属于稳定骨折。","","N"],["2003-N91",53,"第二节 腰椎退行性疾病","感觉异常",2003,91,"A","","L₄₋₅椎间盘突出，最常受累的神经根是",[["A","L₂"],["B","L₃"],["C","L₄"],["D","L₅"],["E","S₁"]],"D","L₄～₅椎间盘突出最常受累的神经根是L₅（D对）。L₂（A错）为L₁～₂椎间盘突出最常受累的神经根。L₃（B错）为L₂～₃椎间盘突出最常受累的神经根。L₄（C错）为L₃～L₄椎间盘突出最常受累的神经根。S₁（E错）为L₅～S₁椎间盘突出最常受累的神经根。","","N"],["2003-N92",44,"第七节 骨折的治疗原则","手法复位",2003,92,"A","","肱骨干中段骨折反复手法复位易导致",[["A","桡神经损伤"],["B","正中神经损伤"],["C","尺神经损伤"],["D","腋神经损伤"],["E","肌皮神经损伤"]],"A","在肱骨干中下1/3段后外侧有桡神经沟，有由臂丛神经后束发出的桡神经经内后方紧贴骨面斜向外前方进入前臂，因此此处骨折反复手法复位易损伤桡神经（A对）。伸直型肱骨髁上骨折易损伤正中神经（B错）。肱骨内上髁骨折易损伤尺神经（C错）。肱骨上段骨折易损伤腋神经（D错）。肱骨上中段骨折易损伤肌皮神经（E错）。","","N"],["2003-N107",26,"第二节 胃癌及其他胃肿瘤","胃癌腹膜种植转移",2003,107,"B","","胃癌的盆腔转移是",[["A","淋巴道转移"],["B","直接蔓延"],["C","种植性转移"],["D","血道转移"],["E","椎旁静脉系统的转移"]],"C","胃癌的转移途径中，种植性转移（C对）是十分特殊的一种转移方式，是由于癌细胞突破胃的浆膜层，部分癌细胞脱落进入腹腔，贴附于腹腔其他脏器上继续生长而引起；若是掉落于女性卵巢形成的种植性转移则称为库肯勃氏瘤。淋巴道转移（A错）、直接蔓延（B错）、血道转移（D错）为肿瘤最常见的转移方式。椎旁静脉系统的转移（E错）为前列腺癌、乳腺癌、甲状腺癌骨转移的转移方式。","","N"],["2003-N108",42,"第三节 前列腺癌","前列腺癌临床表现",2003,108,"B","","前列腺癌的骨盆转移是",[["A","淋巴道转移"],["B","直接蔓延"],["C","种植性转移"],["D","血道转移"],["E","椎旁静脉系统的转移"]],"E","椎旁静脉系统由椎内、外静脉丛及连接其间的椎体静脉和椎间静脉组成，该静脉系缺乏静脉瓣膜，除在本系统内广泛吻合外，还与颅、颈、胸、腰、骶部的静脉交通，且本身压力较低，肿瘤易于通过此途径转移，通过椎旁静脉系统的转移（E对）的肿瘤常见的有三种，自上而下分别是甲状腺癌颅骨转移、乳腺癌椎体转移、前列腺癌骨盆转移。此知识点常考，需牢记。","","N"],["2003-N109",55,"第二节 脊柱结核","结核全身中毒症状",2003,109,"B","","脊柱结核的临床表现是",[["A","多见于老年，膝关节病变常见，疼痛与关节活动关系密切"],["B","好发于青壮年，发病部位多为骶髂关节、脊柱及髋、膝关节，无化脓及死骨形成"],["C","各年龄组均有发病，儿童多见，病变多位于腰椎，且常有椎间盘受累，有低热、消瘦等全身症状"],["D","多发于女性，手足等小关节先受累，关节发病有对称性"],["E","多见于中老年，病变先侵袭椎弓根，后累及椎体，椎间盘较少受累"]],"C","脊柱结核中腰椎结核发生率最高，其次是胸椎、颈椎。儿童成人均可发生，儿童多见。常有全身结核中毒症状，如低热、盗汗、消瘦等（C对）。多见于老年，膝关节病变常见，疼痛与关节活动关系密切（A错）为原发性骨性关节炎（十版外科学P750）的临床表现。好发于青壮年，发病部位多为骶髂关节、脊柱及髋、膝关节，无化脓及死骨形成（B错）为强直性脊柱炎（十版外科学P753）的临床表现。多发于女性，手足等小关节先受累，关节发病有对称性（D错）为类风湿性关节炎（十版外科学P755）的临床表现。多见于中老年，病变先侵袭椎弓根，后累及椎体，椎间盘较少受累（E错）为脊柱肿瘤的临床表现。","","N"],["2003-N110",55,"第二节 脊柱结核","脊柱肿瘤",2003,110,"B","","转移癌的临床表现是",[["A","多见于老年，膝关节病变常见，疼痛与关节活动关系密切"],["B","好发于青壮年，发病部位多为骶髂关节、脊柱及髋、膝关节，无化脓及死骨形成"],["C","各年龄组均有发病，儿童多见，病变多位于腰椎，且常有椎间盘受累，有低热、消瘦等全身症状"],["D","多发于女性，手足等小关节先受累，关节发病有对称性"],["E","多见于中老年，病变先侵袭椎弓根，后累及椎体，椎间盘较少受累"]],"E","多见于老年，膝关节病变常见，疼痛与关节活动关系密切（A错）为骨关节炎（十版外科学P750）的临床表现。原发性骨性关节炎受累关节依次为膝、脊柱、髋、指、腕等，疼痛与关节活动关系密切，表现为晨起或久坐关节僵硬，初走动时剧烈疼痛伴跛行，一段时间疼痛逐渐缓解，但行走过多疼痛再度发生。好发于青壮年，发病部位多为骶髂关节、脊柱及髋、膝关节，无化脓及死骨形成（B错）为强直性脊柱炎（十版外科学P753）的临床表现。强直性脊柱炎好发于青壮年，发病部位多为骶髂关节、脊柱及髋、膝关节，无化脓及死骨形成。各年龄组均有发病，儿童多见，病变多位于腰椎，且常有椎间盘受累，有低热、消瘦等全身症状（C错）为脊柱结核（十版外科学P742）的临床表现（儿童脊柱结核好发于胸椎，成人脊柱结核好发于腰椎）。而多发于女性，手足等小关节先受累，关节发病有对称性（D错）为类风湿性关节炎（十版外科学P755）的临床表现。脊柱转移癌（原试题叙述有误）多见于中老年，病变先侵袭椎弓根，后累及椎体，椎间盘较少受累（E对），早期椎间隙正常。","","N"],["2003-N125",57,"第一节 骨肿瘤概论","骨肿瘤影像学检查",2003,125,"C","","良性骨肿瘤的X线表现是",[["A","骨质破坏"],["B","边缘不清，骨膜反应"],["C","二者均有"],["D","二者均无"]],"A","X线检查对明确骨肿瘤的性质、种类、范围及决定治疗方案均有重要价值，是骨肿瘤重要的检查方法。良性骨肿瘤形态规则，与周围正常骨组织界限清楚，以硬化边为界，骨皮质因膨胀而变薄，但仍保持完整，无骨膜反应（B错）。骨肿瘤无论良恶性，均可因肿瘤细胞的生长而导致骨质破坏（A对）。","","N"],["2003-N126",57,"第一节 骨肿瘤概论","骨肿瘤影像学检查",2003,126,"C","","恶性骨肿瘤的X线表现是",[["A","骨质破坏"],["B","边缘不清，骨膜反应"],["C","二者均有"],["D","二者均无"]],"C","X线检查对明确骨肿瘤的性质、种类、范围及决定治疗方案均有重要价值，是骨肿瘤重要的检查方法。恶性骨肿瘤X线可见虫蛀样或筛孔样、密度不均、界限不清的骨质破坏（A对）。恶性骨肿瘤生长快，可将骨膜掀起，骨膜下可产生新骨，出现骨膜反应（B对）。三角形的骨膜反应阴影称Codman三角，多见于骨肉瘤；板层状或同心圆状骨膜反应多见于尤因肉瘤。本题AB均对，正确答案为C。","","N"],["2003-N127",10,"第四节 局部麻醉","适应证和并发症",2003,127,"C","","臂丛神经阻滞肌间沟径路，可能发生的并发症有",[["A","膈神经麻痹"],["B","气胸"],["C","二者均有"],["D","二者均无"]],"A","肌间沟径路进针位置邻近膈神经、颈部神经节以及喉返神经，操作不当可引起膈神经麻痹（A对）、喉返神经麻痹、霍纳综合征和全脊髓麻痹。肌间沟径路穿刺位点高，远离肺尖，因此一般无气胸（B错）。","","N"],["2003-N128",10,"第四节 局部麻醉","适应证和并发症",2003,128,"C","","臂丛神经阻滞锁骨上径路，可能发生的并发症有",[["A","膈神经麻痹"],["B","气胸"],["C","二者均有"],["D","二者均无"]],"C","锁骨上径路在锁骨中点上1cm处进针，进针位置邻近胸膜顶部，若操作不当，则有穿破胸膜，导致气胸（B对）的可能。此外，锁骨上径路进针位置邻近膈神经、颈部神经节和喉返神经，操作不当可引起膈神经麻痹（A对）、霍纳综合征以及喉返神经麻痹。（本题AB均对，正确答案为C）","","N"],["2003-N147",23,"第二节 腹股沟疝","嵌顿性和绞窄性疝的处理原则",2003,147,"X","","下列哪些腹外疝应行紧急手术治疗",[["A","Littre疝"],["B","Richter疝"],["C","难复性疝"],["D","嵌顿性股疝"]],"ABD","几种特殊类型的嵌顿疝需要考生记忆，区别其不同主要看疝内容物的差别：①Richter疝（B对）：嵌顿的内容物仅为部分肠壁；②Littre疝（A对）：嵌顿的内容物为小肠憩室（通常是Meckel憩室）；③逆行性嵌顿疝：嵌顿的内容物包括几段肠袢，呈现W形。嵌顿疝发生后，由于疝囊颈的相对狭窄，使得疝内容物（多数为肠管）的血供存在障碍，若长时间如此，势必发生肠内容物的缺血坏死，形成严重的并发症。故嵌顿性疝需紧急手术治疗，以防止疝内容物坏死并解除伴发的肠梗阻（D对）。难复性疝（C错）在临床表现方面除了胀痛稍重以外，主要特点是疝块不能完全回纳，并不存在血运障碍，不需要紧急手术治疗。","","N"],["2003-N148",49,"第一节 骨盆骨折","骨盆骨折临床表现",2003,148,"X","","骨盆骨折可能出现下列哪些临床表现",[["A","失血性休克"],["B","尿道损伤"],["C","直肠损伤"],["D","高位截瘫"]],"ABC","骨盆由扁骨组成，内有造血能力旺盛的红骨髓，血运丰富，且骨盆骨折常容易合并髂内、髂外动静脉及其分支的断裂，容易引起大出血，导致失血性休克（A对），严重者可导致病人死亡。尿道和直肠均位于盆腔内，耻骨下支和坐骨支骨折可刺破盆腔内软组织，导致尿道损伤（B对）及直肠损伤（C对）。由于成人脊髓和椎管的长度不一致，脊髓的末端大约终止于脊柱L₁水平，故骨盆骨折不会损伤脊髓，也就无法造成高位截瘫（D错）。","","N"],["2003-N149",5,"第五节 脓毒症","脓毒症病因",2003,149,"X","","全身性感染时，下列哪些因素可造成对机体的损害",[["A","内毒素"],["B","外毒素"],["C","病原菌"],["D","炎性介质"]],"ABCD","感染实质上是微生物入侵而引起的炎症反应，众多宿主防御机制参与炎症的过程，以使入侵的病原微生物局限化或被清除。革兰氏阴性菌的主要致病因素为内毒素（A对）；部分革兰氏阳性菌还能分泌外毒素（B对），破坏机体正常组织和功能。此外，病原菌本身的侵袭、破坏或吞噬作用等也对机体产生损伤（C对）。当病原菌侵入机体，免疫系统对病原菌本身及其产物作出反应，而这些反应除杀伤病原菌及其产物外，对正常细胞、组织也具有破坏作用（D对）。","","N"],["2003-N150",17,"第一节 甲状腺疾病","甲状腺结节诊断",2003,150,"X","","下列哪些表现有助于甲状腺恶性结节的诊断",[["A","结节突发，生长迅速"],["B","单发孤立结节"],["C","结节随吞咽移动度大"],["D","核素扫描为冷结节"]],"ABD","甲状腺恶性结节的诊断主要根据临床表现和病理，若甲状腺肿块质硬、固定，腺体在吞咽时上下移动度小（C错），颈淋巴结肿大，或有压迫症状者，或非突发结节（A错），在短期内迅速增大者，均应怀疑为甲状腺癌。甲状腺单发孤立结节（B 对）恶性可能性大，甲状腺多发结节良性可能性大。甲状腺冷结节是指用放射性元素作甲状腺扫描时，结节所在位置的放射性比附近正常甲状腺组织明显降低或接近无放射性，结节见于多种疾病，既可以是甲状腺癌，也可以是各种良性病变（如囊肿、出血及纤维坏死等)。但是，如果冷结节较大，与周围甲状腺组织分界不清楚，而且是单一性结节，则甲状腺癌的可能性较大（D对）。本题答案应为BD，原参考答案为ABD。","","N"],["2004-N75",10,"第五节 椎管内麻醉","骶管麻醉",2004,75,"A","","下列选项中，不属于局部麻醉的是",[["A","表面麻醉"],["B","局部浸润麻醉"],["C","区域阻滞"],["D","骶管阻滞"],["E","神经阻滞"]],"D","局部麻醉是用局部麻醉药暂时阻断某些周围神经的冲动传导，使这些神经所支配的区域产生麻醉作用，简称局麻。常用的局麻方法包括：①表面麻醉（A对）；②局部浸润麻醉（B对）；③区域阻滞（C对）；④神经阻滞（E对）。骶管阻滞（D错，为本题正确答案）为硬膜外阻滞的一种，属于椎管内麻醉，而广义的局麻包括椎管内麻醉，故此题不严谨。","","N"],["2004-N76",10,"第五节 椎管内麻醉","硬脊膜穿破后头痛",2004,76,"A","","对蛛网膜下腔阻滞麻醉（腰麻）术后并发低压性头痛的处理，下列哪项是不恰当的",[["A","去枕平卧，大量输液"],["B","使用腹带，捆紧腹部"],["C","硬膜外腔自家血充填"],["D","静脉注射高张葡萄糖或甘露醇"],["E","硬膜外腔注入生理盐水或右旋糖酐"]],"D","腰麻后头痛为低颅压性头痛，是由于腰麻后脑脊液流失引起。去枕平卧，可降低脊髓内静水压，减少脑脊液漏；大量补液目的是增加血容量，从而增加脑脊液的生成，提高颅内压（A对）。使用腹带捆扎腹部后，腹内压增高，压力经椎间孔向椎管传递，减轻颅内低压症状（B对）。硬膜外腔自家血充填（C对）以及硬膜外腔注入生理盐水或右旋糖酐（E对）可对穿刺孔有轻度压迫作用，减少脑脊液漏，减轻疼痛。静脉注射高张葡萄糖或甘露醇（D错，为本题正确答案）为脑水肿、颅内高压的脱水治疗方案，给予低颅压性头痛者反而使得症状更加严重。","","N"],["2004-N77",7,"第一节 热力烧伤","入院早期治疗",2004,77,"A","","大面积烧伤24小时内的病人，首选的主要治疗措施是",[["A","处理创面"],["B","镇静止痛"],["C","液体复苏"],["D","控制感染"],["E","补充营养、增强免疫"]],"C","烧伤24小时内，机体发生的最主要的变化是体液渗出，极易发生低血容量性休克。因此首选的主要治疗措施是液体复苏（C对）。镇静止痛（B错）、补充营养、增强免疫（E错）属于对症治疗，不属于主要治疗措施。处理创面（A错）、控制感染（D错）都是烧伤急性感染期治疗的主要措施，多在伤后3～10天进行，并非在24小时内。","","N"],["2004-N79",9,"第一节 器官、组织和细胞移植概述","器官移植",2004,79,"A","","下列关于器官移植的叙述，错误的是",[["A","心脏移植后长期存活的主要障碍是植入心脏的冠脉硬化"],["B","肾移植是临床各类器官移植中疗效最稳定和最显著的"],["C","胰腺移植的适应证是药物治疗无效的I型糖尿病"],["D","肺移植后近期主要死亡原因是肺部感染"],["E","小肠移植后预防排斥反应较容易"]],"E","临床上常用的器官移植术为同种异体间移植，免疫排斥反应是影响移植效果的主要障碍，而免疫排斥反应的本质是针对供者特异性的免疫应答。由于慢性排斥反应，心脏移植后，在一段时间内会出现冠脉硬化，且目前免疫抑制剂对慢性排斥反应无效，慢性排斥反应也是目前器官移植的最大障碍之一（A对）。肾移植术式已基本定型，术后终身服用免疫抑制剂能够很好的控制排斥反应，绝大多数患者可耐受，是临床各类器官移植中疗效最稳定和最显著的（B对）。Ⅰ型糖尿病的病因是自身胰岛细胞无法产生胰岛素、引起胰岛素的完全缺乏而致病，移植具有正常功能的胰腺细胞可以为机体提供所必须的胰岛素，故胰腺移植可治疗无效的Ⅰ型糖尿病（C对）。肺移植后需服用免疫抑制药物来抑制排斥反应，无法避免的降低了患者的抵抗力，肺部是与外界直接相通的器官，必定会接触外界病原微生物，在免疫抑制情况下易发严重的肺部感染危及生命（D对）。小肠属于高免疫源性器官，其黏膜固有层及肠系膜淋巴结均含有大量的淋巴组织，导致排斥反应发生率极高，移植后预防排斥反应较困难（E错，为本题正确答案）。","","N"],["2004-N80",17,"第一节 甲状腺疾病","药物准备",2004,80,"A","","下列关于甲亢术前的药物准备，正确的是",[["A","普奈洛尔不能与碘剂合用"],["B","硫脲类药物和碘剂不能合并应用"],["C","服用硫脲类药物控制甲亢症状后再进行手术"],["D","使用碘剂2～3周后，甲亢症状基本控制便可进行手术"],["E","服用普奈洛尔时应每8小时给药一次，术后应继续服用2～3周"]],"D","根据十版外科学（P235），术前准备的药物准备已经删除“单用碘剂”，所以根据最新教材D选项使用碘剂2～3周存在争议。使用硫脲类药物进行术前准备需注意，由于硫脲类药物能使甲状腺肿大和动脉性充血，手术时极易发生出血，增加了手术的困难和危险，因此服用硫脲类药物后必须加用碘剂2周待甲状腺缩小变硬，血管数减少后手术，此为常考点（BC错）。普萘洛尔是一种β受体阻断剂，能控制甲亢的症状（阻断T₄在外周组织向T₃的转化），缩短术前准备时间，且用药后不引起腺体充血，有利于手术操作，对硫脲类药物效果不好或反应严重者可改用此药，也可与碘剂合用作术前准备（A错）；剂量从60mg/d开始，每6小时/次，一般4～7日后心率降至正常水平时，便可施行手术；由于普萘洛尔在体内半衰期不到8小时，故术前1～2小时必须再口服一次，术后继续服用4～7天即可（E错）。","","N"],["2004-N81",18,"第四节 乳腺癌","乳腺癌筛查与预防",2004,81,"A","","目前认为乳腺癌最有效的检出方法是",[["A","防癌普查体检"],["B","红外线"],["C","B超"],["D","钼钯摄片"],["E","核磁共振"]],"D","五个备选项都可以用于乳腺癌的检查，各有其特点和优缺点，可以互相弥补。对于乳腺肿块的影像学检查，常用钼靶X线摄片，适用于观察软组织结构，恶性肿瘤的图像呈形态不规则、分叶、和毛刺的阴影，密度较高，还可以显示小钙化点，目前认为钼靶X线摄片是乳腺癌最有效的检出方法（D对）。防癌普查体检（A错）在本题中主要是指查体，即通过乳房触诊来发现乳腺包块，但是无法确认是否为乳腺癌；红外线热图像（B错）通过显示肿瘤组织的高代谢高热表现，从而有助于乳腺癌的诊断，但其仅仅通过热图像反应局部状况，对于病变的性质确定仍旧存在困难，无法排除乳腺炎等情况，临床上并不常用；乳房组织脂肪多，层次不明显，B超（C错）B超是一种无创、无辐射的检查方法，能够显示乳腺内的结构，对于囊肿等液性病变有较好的识别能力，但对于某些微小的、实性的乳腺癌病变，B超的检出率不如钼靶；核磁共振（E错）对于淋巴结及周围血管的显影佳，可用于判断乳腺癌的转移情况，但是对乳腺癌本身的显影效果欠佳。","","N"],["2004-N82",23,"第三节 股疝","股疝临床表现",2004,82,"A","","下列哪项不是股疝的常见特点",[["A","多见于中老年妇女"],["B","疝块较小"],["C","疝块呈半球形"],["D","咳嗽冲击感明显"],["E","易嵌顿、易绞窄"]],"D","女性骨盆较宽大、联合肌腱和腔隙韧带较薄弱，以致股管上口宽大松弛而易发病，老年人尤甚，因此股疝多见于中老年妇女（A对）。因为疝囊颈较小，所以疝块较小（B对），常在腹股沟韧带下方卵圆窝处表现为一半球形（C对）的突起，咳嗽冲击感也不明显（D错，为本题正确答案）（因冲击力被狭窄的疝囊颈吸收）。股管为上宽下窄的漏斗形结构，上端为股环，下端为卵圆窝，由于股疝都是垂直的，疝块在卵圆窝处向前转折时形成锐角，且股环本身较小，周围多有坚韧的韧带，因此股管容易发生嵌顿，嵌顿后很快便会发生绞窄（E对）。","","N"],["2004-N83",24,"第二节 常见内脏损伤的特征和处理","脾损伤处理",2004,83,"A","","下列关于脾破裂的叙述，错误的是",[["A","有慢性病理改变的脾更易破裂"],["B","通常采用脾切除术"],["C","85%有脾包膜及脾实质破裂"],["D","治疗原则是紧急手术"],["E","成人脾切除术后，暴发型感染发病率高"]],"E","存在慢性病理改变的脾质地脆，因而在外力打击下更容易破裂（A对）。脾是人体血供最丰富的器官之一，本身又质脆易受伤，约85%有脾包膜及脾实质破裂（C对），即为脾真性破裂。脾损伤后大出血迅速导致休克危及生命，故需紧急手术治疗（D对）。因脾组织质脆、难缝合，为挽救生命，常采用脾部分切除或脾全切（B对）。成人行脾切除术对免疫功能的影响轻微，暴发型感染的发病率不超过1%（E错，为本题正确答案）。脾切除后凶险性感染（OPSI）主要发生在婴幼儿，50%病人的致病菌为肺炎链球菌。脾作为腹部内脏最容易受损的器官，脾破裂的诊断和处理是腹部损伤一章中的常考点，部分数据考生需要留意。","","N"],["2004-N85",27,"第四节 肠梗阻","是单纯性还是绞窄性梗阻",2004,85,"A","","下列哪项不是绞窄性肠梗阻的临床表现",[["A","便隐血阳性"],["B","腹痛剧烈而持续"],["C","腹部有固定压痛和腹膜刺激征"],["D","移动性浊音阳性或腹穿有血性液体"],["E","呕吐呈反射性，吐出物为食物或胃液"]],"E","呕吐呈反射性，吐出物为食物或胃液（E错，为本题正确答案）为早期高位肠梗阻或急性胃肠炎的表现。绞窄性肠梗阻由于有肠管缺血，导致局部代谢产物淤积，刺激肠壁神经，引起的腹痛剧烈而持续（B对）；可发生肠坏死、穿孔和腹膜炎，在原发病部位为著，表现为固定压痛和腹膜刺激征（C对）；血运障碍致肠管坏死和血管壁损伤，血性渗出进入肠腔，粪便隐血阳性（A对）；坏死肠管引发炎症反应，以及穿孔后肠内容物流出激发炎症反应都会引起腹腔内积液，血管损伤血液外渗，移动性浊音阳性或腹穿有血性液体（D对）。","","N"],["2004-N86",28,"第一节 阑尾解剖生理概要","阑尾疾病概述",2004,86,"A","","下列与阑尾相关的叙述，错误的是",[["A","阑尾动脉是终末动脉"],["B","阑尾组织中含有丰富的淋巴滤泡"],["C","阑尾炎发病时的脐周痛属内脏性疼痛"],["D","成人切除阑尾将损害机体的免疫功能"],["E","阑尾黏膜深部有嗜银细胞，与类癌发生有关"]],"D","阑尾动脉是回结肠动脉的分支，属于终末动脉（A对）。阑尾组织中含有丰富的淋巴滤泡（B对），但以后逐渐减少，30岁后滤泡明显减少，60岁后完全消失，因此成人切除阑尾不会损害机体的免疫功能（D错，为本题正确答案）。阑尾的神经由交感神经纤维经腹腔丛和内脏小神经传入，传入的脊髓节段在第10、11胸节，此感觉节段位于脐水平附近，所以当急性阑尾炎发病开始时，常表现为脐周的牵涉痛，属内脏性疼痛（C对）。阑尾黏膜深部有嗜银细胞，与类癌的发生有关（E对）。","","N"],["2004-N87",26,"第三节 胃十二指肠溃疡的外科治疗","碱性反流性胃炎",2004,87,"A","","男性，42岁，毕Ⅱ式胃大部切除术后两年，上腹部有烧灼痛，抗酸剂治疗无效，有时呕吐，内含胆汁，吐后腹痛无缓解，体重减轻，胃镜下黏膜充血、水肿、易出血。最可能的诊断是",[["A","输入段综合征"],["B","输出段梗阻"],["C","碱性反流性胃炎"],["D","吻合口梗阻"],["E","吻合口溃疡"]],"C","男性，42岁，毕Ⅱ式胃大部切除术后两年（提示可能存在胃大切术后远期并发症），上腹部有烧灼痛（提示有消化液反流），抗酸剂治疗无效（提示反流液为碱性），有时呕吐，内含胆汁，吐后腹痛无缓解，体重减轻，胃镜下黏膜充血、水肿、易出血。诊断为碱性反流性胃炎（C对）。碱性反流性胃炎常发生于毕Ⅱ式手术后，原因是胃空肠吻合后，正常解剖结构改变，失去幽门-十二指肠的抗返流屏障，碱性胆汁、胰液、肠液流入胃中，破坏胃黏膜屏障，导致胃黏膜充血，水肿、糜烂等改变。临床主要表现为，上腹或胸骨后烧灼痛、呕吐胆汁样液和体重减轻。因炎症主要由胆汁反流引发，因此针对胃酸的抗酸剂治疗无效。输入段综合征（A错）、输出段梗阻（B错）、吻合口梗阻（D错）均为术后早期并发症，多与术中操作不当或术前准备不足有关，一般不会发生于毕Ⅱ式胃大部切除术后两年；吻合口溃疡（E错）多发生在术后2年内，属于术后远期并发症，原因为术后胃液仍处于高酸状态，从而易发溃疡，抗酸治疗有效。","","N"],["2004-N88",32,"第一节 胆道系统解剖生理概要","胆汁的生成、分泌和代谢",2004,88,"A","","下列关于胆道系统的叙述，错误的是",[["A","胆汁全部由肝细胞分泌"],["B","胆囊24小时可接纳胆汁500ml"],["C","促进胆汁分泌最强的是促胰液素"],["D","成人每日分泌胆汁约800ml～1200ml"],["E","毛细胆管在调节胆汁流量和成分方面起关键作用"]],"A","成人每日分泌胆汁800～1200ml（D对），胆汁主要由肝细胞分泌，约占胆汁分泌量的3/4，胆管细胞分泌的黏液物质约占1/4，因此胆汁并非全部由肝细胞分泌（A错，为本题正确答案）。胆汁的分泌受到神经内分泌的调节，促胰液素、胃泌素、胰高血糖素、肠血管活性肽等均可促进胆汁分泌，但属促胰液素的作用最强（C对）。胆囊具有浓缩及吸收功能，胆囊容积虽然只有30～60ml，但24小时内能接纳约500ml胆汁（B对）。胆道系统具有分泌、贮存、浓缩和输送胆汁的功能，对胆汁排入十二指肠有重要的调节作用。其中，毛细胆管在调节胆汁流量和成分方面起关键作用（E对）。有关胆囊的解剖学数据，九版外科学有数据更新（十版外科学P463）。","","N"],["2004-N89",33,"第二节 胰腺炎","胆道疾病",2004,89,"A","","在我国，急性胰腺炎的原因主要是",[["A","胆结石"],["B","过量饮酒"],["C","暴饮暴食"],["D","高脂血症"],["E","高钙血症"]],"A","在我国引起急性胰腺炎最主要的病因为胆道疾病（A对），称胆源性胰腺炎，约占50% 以上。酒精中毒/酗酒（B错）是西方国家引起急性胰腺炎的主要原因。暴饮暴食（C错）、高脂血症（D错）、高钙血症（E错）均为急性胰腺炎的致病危险因素，其中暴饮暴食常作为急性胰腺炎的诱因存在（九版内科学P429）。","","N"],["2004-N90",45,"第十节 桡骨远端骨折","桡骨远端骨折屈曲型骨折",2004,90,"A","","Smith骨折桡骨远端的移位畸形是",[["A","向尺侧及背侧移位"],["B","向桡侧及背侧移位"],["C","向尺侧及掌侧移位"],["D","向桡侧及掌侧移位"],["E","只向掌侧移位"]],"D","Smith骨折常由跌倒时，腕关节屈曲、手背着地受伤引起。其典型位移改变如下：近折端向背侧移位，远折端向掌侧、桡侧移位（D对）。解答该类骨折如何移位的问题时，可模拟着地方式（分析着地点及受力方向），即可推理出正确答案。","","N"],["2004-N91",54,"第二节 化脓性关节炎","化脓性关节炎治疗",2004,91,"A","","早期治疗膝关节化脓性关节炎最好的方法是",[["A","合理有效抗生素加石膏固定"],["B","足量有效抗生素加支持疗法"],["C","足量有效抗生素加关节切开引流"],["D","足量有效抗生素加功能锻炼及理疗"],["E","足量有效抗生素加关节穿刺抽液并注入抗生素"]],"E","急性化脓性关节炎多早期便有严重的全身症状，起病急骤，明显毒血症症状，故必须立即给予足量抗生素治疗，需强调足量有效（A错）。仅仅足量抗生素加上支持疗法无法迅速缓解化脓性膝关节炎症状（B错）。关节切开引流适用于髋关节等深部大关节，膝关节属于表浅关节（C错）。早期治疗膝关节化脓性关节炎最好的方法是足量有效抗生素全身应用、关节腔穿刺灌洗抽出脓液加抗生素膝关节腔局部注入（E对）。功能锻炼及理疗应在化脓性关节炎治疗稳定、感染消失后考虑进行（D错）。","","N"],["2004-N92",57,"第四节 原发性恶性骨肿瘤","骨肉瘤治疗",2004,92,"A","","男性，14岁，8个月前开始左上臂肿胀、疼痛，入院诊断为左肱骨上端骨肉瘤，优选的治疗方案是",[["A","左肩关节离断术"],["B","肿瘤刮除术"],["C","术前化疗-根治性切除-术后化疗"],["D","化疗"],["E","化疗加放疗"]],"C","骨肉瘤是典型的恶性肿瘤，应采取手术治疗为主的综合治疗。骨肉瘤对化疗敏感，术前、术后可给予大剂量化疗，可降低瘤负荷，延长患者生存期，因此最佳治疗方法为术前化疗-根治性切除-术后化疗（C对）。骨肉瘤属于恶性骨肿瘤，治疗时需考虑原发灶的清除和可能存在转移灶的消灭。单纯的左肩关节离断术（A错）或者肿瘤刮除术（B错）无法清除可能存在的浸润和转移。除少数血液系统肿瘤及滋养层细胞肿瘤、睾丸精原细胞瘤、胚胎性横纹肌肉瘤可单独应用化疗（D错）以外，多数恶性肿瘤应采取手术治疗为主的综合治疗。骨肉瘤对于放射治疗通常不敏感，因此不考虑化疗加放疗（E错）。","","N"],["2004-N107",13,"第二节 术后处理","体位",2004,107,"B","","食管癌手术全麻清醒后，病人应采取的体位是",[["A","头低卧位"],["B","高半坐位"],["C","低半坐位"],["D","侧卧位"],["E","平卧位"]],"B","手术后，应根据麻醉及病人的全身状况、术式、疾病的性质等选择体位，使病人处于既舒服又便于活动的体位。食管癌手术全麻清醒后，高半坐位（B对）可使膈肌下移，增加通气量；同时有利于胸腔内渗血渗液向下引流，经胸腔闭式引流导管排出体外。","","N"],["2004-N108",13,"第二节 术后处理","体位",2004,108,"B","","胃大部切除术全麻清醒后，病人应采取的体位是",[["A","头低卧位"],["B","高半坐位"],["C","低半坐位"],["D","侧卧位"],["E","平卧位"]],"C","手术后，应根据麻醉及病人的全身状况、术式、疾病的性质等选择体位，使病人处于既舒服又便于活动的体位。胃大部切除术全麻清醒后，采用低半坐位的体位，使得腹肌处于松弛状态，有利于切口愈合和减轻疼痛（C对）。","","N"],["2004-N109",44,"第三节 骨折的并发症","创伤性关节炎",2004,109,"B","","踝部骨折易造成",[["A","创伤性关节炎"],["B","骨筋膜室综合征"],["C","外伤性移位"],["D","关节僵硬"],["E","关节积液"]],"A","踝关节由胫骨、腓骨远端和距骨组成，三者相互接触共同形成一个关节结构，此处骨折可损伤关节面，造成关节面的不平整，关节软骨在活动时易磨损剥脱，易引起创伤性关节炎（A对）。小腿深筋膜与胫腓骨及骨间膜形成四个界限清楚的筋膜室，又胫骨上1/3处是滋养动脉进入骨髓腔营养胫骨的部位，血供丰富，此处骨折易引起大量出血，血液积于骨筋膜室造成室内压过高，进而引起骨筋膜室综合征（十版外科学P618）（B错）。外伤性移位（C错）概念较广，并不仅仅局限于骨骼关节，身体其他部位器官如晶状体等因外伤引起的移位也称为外伤性移位，并不属于骨折的并发症。关节僵硬（十版外科学P618）（D错）是由于关节处长期固定引起，故题中多有“长期固定”的叙述方选择。关节积液（E错）多见于膝关节的慢性损伤、化脓性感染、结核以及关节炎和肿瘤等，骨折较少引起关节积液。","","N"],["2004-N110",44,"第三节 骨折的并发症","骨筋膜隔室综合征",2004,110,"B","","胫骨上1/3骨折易造成",[["A","创伤性关节炎"],["B","骨筋膜室综合征"],["C","外伤性移位"],["D","关节僵硬"],["E","关节积液"]],"B","该题叙述欠准确，一般认为：①腘动脉分胫前、胫后动脉，胫后动脉穿过比目鱼肌腱弓向下行走，此血管固定，胫骨上1/3骨折易损伤该动脉，引起下肢严重缺血；②在小腿中1/3，小腿深筋膜与胫腓骨及骨间膜形成四个界限清楚的筋膜室，由于骨折后骨髓腔出血，或肌肉损伤出血或血管损伤出血，均可引起骨筋膜室综合征（B对）；③胫骨下1/3骨折易损伤滋养动脉，导致胫骨下段骨折缺乏血供，引起骨折的延迟愈合。创伤性关节炎（A错）多发生于关节内骨折，因为骨折使得关节面的正常结构丧失，不再平整，长期活动磨损，致使关节活动时出现疼痛。外伤性移位（C错）概念较广，并不仅仅局限于骨骼关节，身体其他部位器官如晶状体等因外伤引起的移位也称为外伤性移位，并不属于骨折的并发症。关节僵硬（十版外科学P618）（D错）是由于关节处长期固定引起，故题中多有“长期固定”的叙述方选择。关节积液（E错）多见于膝关节的慢性损伤、化脓性感染、结核以及关节炎和肿瘤等，骨折较少引起关节积液。","","N"],["2004-N125",22,"第三节 动脉疾病","血栓闭塞性脉管炎临床表现",2004,125,"C","","血栓闭塞性脉管炎可出现",[["A","患肢动脉搏动减弱或消失"],["B","患肢血管杂音"],["C","二者均有"],["D","二者均无"]],"A","血栓闭塞性脉管炎，是一种慢性、非粥样硬化性、节段性、炎性、闭塞性、与吸烟相关的血管疾病。血管杂音多由大血管血流改变导致，而血栓闭塞性脉管炎主要侵袭腘动脉以远及肱动脉以远的中、小动静脉，因此无血管杂音的存在（B错）。血栓闭塞性脉管炎导致血管发生节段性闭塞，导致病变远端缺血，患肢动脉搏动减弱或消失（A对）。","","N"],["2004-N126",22,"第三节 动脉疾病","雷诺综合征临床表现",2004,126,"C","","雷诺综合征可出现",[["A","患肢动脉搏动减弱或消失"],["B","患肢血管杂音"],["C","二者均有"],["D","二者均无"]],"D","血管杂音多为大血管血流动力学改变导致。雷诺综合征是小动脉的阵发性痉挛，受累部位依次出现苍白、发冷、青紫及疼痛、潮红后复原的典型症状，因此无患肢血管杂音（B错）。常于寒冷刺激或情绪波动时发病，为一过性改变，每次发作时间仅持续数分钟至几十分钟。本病也无患肢动脉搏动的减弱或消失（A错）。本题AB均错，正确答案为D。","","N"],["2004-N127",50,"第二节 上肢神经损伤","臂丛抻经损伤",2004,127,"C","","臂丛神经根性损伤时可出现",[["A","前锯肌功能丧失，双手推墙时出现翼状肩胛"],["B","伸腕、伸指功能丧失，出现腕下垂"],["C","二者均有"],["D","二者均无"]],"C","臂丛由第C₅-₈颈神经和第1胸神经前支的大部分组成。这五条神经根经斜角肌间隙，颈5、6的前支合成上干，颈7前支延为中干，颈8神经前支和胸1神经前支的大部分合成下干。出斜角肌间隙后每个干又分为前后两股，由上、中干的前股合成外侧束，下干的前股延为内侧束，三干的后股汇合成后束。各束再分出神经至上肢。胸长神经起自神经根（C₅-C₇），支配前锯肌，此神经损伤后可造成前锯肌瘫痪，肩胛骨脊柱缘翘起出现翼状肩（A对）。桡神经是臂丛后束发出的最粗大神经（C₅-T₁），损伤后表现为前臂伸肌瘫痪，出现垂腕畸形，伸腕、伸指功能丧失。臂丛神经根损伤，可导致前锯肌功能丧失，双手推墙时出现翼状肩胛；同时远端的桡神经功能亦出现障碍，出现伸腕、伸指功能丧失，出现腕下垂（B对）。本题AB均对，正确答案为C。","","N"],["2004-N128",50,"第二节 上肢神经损伤","臂丛抻经损伤",2004,128,"C","","臂丛神经束支损伤时可出现",[["A","前锯肌功能丧失，双手推墙时出现翼状肩胛"],["B","伸腕、伸指功能丧失，出现腕下垂"],["C","二者均有"],["D","二者均无"]],"B","臂丛由第C₅-₈颈神经和第1胸神经前支的大部分组成。这五条神经根经斜角肌间隙，颈5、6的前支合成上干，颈7前支延为中干，颈8神经前支和胸1神经前支的大部分合成下干。出斜角肌间隙后每个干有分为前后两股，由上、中干的前股合成外侧束，下干的前股延为内侧束，三干的后股汇合成后束。各束再分出神经至上肢。胸长神经起自神经根（C₅-C₇），支配前锯肌，此神经损伤后可造成前锯肌瘫痪，肩胛骨脊柱缘翘起出现翼状肩。桡神经是臂丛后束发出的最粗大神经（C₅-T₁），损伤后表现为前臂伸肌瘫痪，出现垂腕畸形，伸腕、伸指功能丧失。臂丛神经束支损伤时，可导致桡神经功能出现障碍，出现伸腕、伸指功能丧失，出现腕下垂（B对）。因胸长神经起自神经根，因此束支损伤并不影响其功能，因而不会出现前锯肌功能丧失，双手推墙时出现翼状肩胛（A错）。前锯肌功能是否障碍是判断臂丛神经是否“根”性损伤的重要依据，如为“根”性损伤，远端神经一定产生障碍。臂丛神经损伤如只出现伸腕、伸指功能丧失、腕下垂，说明损伤部位在束支。","","N"],["2004-N147",17,"第一节 甲状腺疾病","甲状腺功能亢进诊断",2004,147,"X","","下列检查结果，哪些支持“甲亢”的诊断",[["A","基础代谢率为20％"],["B","24小时甲状腺摄取¹³¹I量为人体总量的40％"],["C","2小时内甲状腺摄取的¹³¹I量为人体总量的30％"],["D","血清T₃高于正常值4倍，T₄高于正常值2倍"]],"ACD","甲亢的诊断主要是依靠临床表现，结合辅助检查来确定。主要通过测基础代谢率、¹³¹I摄取率与血清中T₃（三碘甲状腺原氨酸）、T₄（甲状腺素）含量。测基础代谢率时，超过正常值20%及以上，即可考虑为甲亢（A对）。¹³¹I摄取率测定时，2小时内摄取率超过人体总量的25%（C对）以上或24小时内超过人体总量的50%（B错）以上即可诊断为甲亢。在测定T₃和T₄含量时，血清中T₃含量>正常4倍左右或T₄含量>正常的2.5倍则考虑为甲亢（D对）。","","N"],["2004-N148",1,"第一节 水、电解质代谢紊乱和酸碱平衡失调概述","体液酸碱度的调节",2004,148,"X","","对维持与调节机体酸碱平衡起重要作用的脏器有",[["A","肺"],["B","胃肠道"],["C","肝"],["D","肾"]],"AD","酸碱平衡是人体维持内环境稳定的重要条件，体液的缓冲系统、肺的呼吸、肾的排泄为人体调节自身酸碱平衡最重要的三种方式。肺通过深大的呼吸将血液中的H₂CO₃以CO₂形式排出，调节较缓慢，以调节挥发酸为主（A对）；肾通过对尿中H⁺和HCO₃⁻的分泌和重吸收来调节酸碱平衡，主要对长期酸碱平衡进行调节，以调节固定酸为主（D对）；血液中存在多种缓冲系统，以HCO₃⁻/H₂CO₃最为重要，可以缓冲体液的小幅度酸碱改变，调节迅速。肝和胃肠道对酸碱平衡的调节无明显作用（BC错）。","","N"],["2004-N149",34,"第一节 上消化道大出血的诊断和处理","上消化道大出血临床分析",2004,149,"X","","上消化道大出血时，表现是呕血还是便血，取决于",[["A","出血部位"],["B","出血速度"],["C","出血量"],["D","出血时间"]],"ABC","呕血和黑便（血便）是上消化道出血的基本表现。呕血还是便血以及血的颜色主要取决于出血部位（A对）、出血速度（B对）、出血量（C对），其中以后两者最重要，与出血时间无明显关系。①食管胃底出血，出血量大、速度快，主要表现为呕血，单纯便血者少见；②胃及溃疡出血，出血量中等，出血速度快，主要以呕血为主，亦可出现便血；③球部以下出血，出血量少，主要以便血为主。","","N"],["2004-N150",56,"第三节 类风湿关节炎","类风湿关节炎概述",2004,150,"X","","下列关于类风湿关节炎的叙述，正确的有",[["A","属全身性疾病，病因不明"],["B","受累关节以踝、肘关节最为常见"],["C","80%患者的类风湿因子呈阳性"],["D","受累关节以近侧指间关节常见"]],"ACD","类风湿性关节炎属于自身免疫性全身性疾病，病因不明（A对），以慢性、对称性、多滑膜关节炎和关节外病变为主要临床表现。受累关节以近侧指间关节（D对）、腕、肘、肩、膝和足趾关节多见。最常累及小关节，踝关节等大关节相对较少累及（B错）。大约70%～80%的病例类风湿因子阳性（C对），并可有血沉加快，C反应蛋白增高，血清IgG、IgA、IgM增高。","","N"],["2005-N85",24,"第一节 腹部损伤概述","腹部损伤处理",2005,85,"A","","腹部闭合性损伤合并出血性休克时的处理原则是",[["A","立即手术探查"],["B","输血并给止血药"],["C","输血并给抗生素"],["D","积极抗休克，休克纠正后手术探查"],["E","积极抗休克的同时手术探查"]],"E","腹部闭合性损伤如肝脾破裂等，常合并出血性休克，由于休克的原因是实质性脏器破裂出血或大血管损伤，因此必需积极抗休克的同时手术探查（E对）。如不经术前补液、立即手术探查（A错），手术风险很大；如只行补液、输血并给止血药（B错）或输血并给抗生素（C错）等保守治疗，有许多病人出血并不能自止，从而失去抢救机会。有些病人出血量大、病情凶险，只有手术治疗才能彻底止血，使休克纠正，所以不能待休克纠正后再手术治疗（D错）。","","N"],["2005-N86",17,"第一节 甲状腺疾病","甲状腺结节诊断",2005,86,"A","","在判断甲状腺结节良恶性时，下列哪项不正确",[["A","单发结节恶性机会较多发结节大"],["B","囊性结节也可能是恶性的"],["C","“冷结节”都是恶性的"],["D","实性结节的恶性率较高"],["E","儿童单发结节的恶性机会较大"]],"C","甲状腺结节分4类，凉结节、热结节、温结节和冷结节。甲状腺冷结节是指用放射性元素作甲状腺扫描时，结节所在位置的放射性比附近正常甲状腺组织明显降低或接近无放射性，多见于甲状腺癌，但甲状腺囊肿、腺瘤、出血、纤维化、钙化、甲状腺炎等都可以见到冷结节（C错，为本题正确答案）。甲状腺单发结节恶性可能性大，多发结节恶性可能性较低（A对）。约4/5分化型甲状腺癌及2/3未分化癌表现为单发结节，但亦有少部分甲状腺癌表现为多发结节。实性结节的恶性率较高（D对），相比而言囊性结节则低得多，但囊性结节也可能是恶性的（B对）。儿童单发结节恶性机会较大（E对），约50%为恶性。","","N"],["2005-N87",10,"第四节 局部麻醉","利多卡因",2005,87,"A","","利多卡因用于局部浸润麻醉或神经阻滞时，成人一次限量为",[["A","100mg"],["B","200mg"],["C","300mg"],["D","400mg"],["E","500mg"]],"D","利多卡因成人一次限量表面麻醉为100mg，局部浸润麻醉和神经阻滞为400mg（D对）。普鲁卡因的成人一次限量为1g。丁卡因成人一次限量表面麻醉为40mg，局部浸润麻醉和神经阻滞为80mg。布比卡因和罗哌卡因的成人一次限量为150mg。","","N"],["2005-N88",23,"第二节 腹股沟疝","嵌顿性和绞窄性疝的处理原则",2005,88,"A","","男性，50岁，右阴囊可复性肿物14年，不能还纳1天，伴呕吐，停止排气排便。查体：心率108次/分，血压150/100mmHg，右阴囊肿大，压痛明显，腹膨隆，肠鸣音亢进，白细胞14×10⁹/L，中性85%。对该患者的最佳处理是",[["A","立即剖腹探查"],["B","急诊室留观"],["C","止痛，抗炎"],["D","胃肠减压，择期行修补术"],["E","急作腹股沟疝手术，并作肠切除准备"]],"E","“男性，50岁，右阴囊可复性肿物14年”说明患者患有腹股沟斜疝。“不能还纳1天，伴呕吐、停止排便排气”说明腹股沟斜疝嵌顿。“腹膨隆，肠鸣音亢进”说明嵌顿物为肠管可能性大。“不能还纳1天”，且出现腹膜刺激征，说明嵌顿的肠管已出现绞窄及坏死。因此，治疗首先考虑急作腹股沟疝手术，并作肠切除准备（E对）。肠绞窄为外科急症之一，须紧急手术，因此不可急诊室留观（B错），亦不可单纯进行胃肠减压，择期行修补术（D错）。止痛，抗炎（C错）为一般性对症治疗，不能从根本上解除病因。此题不严谨，肠管探查属于剖腹探查手术，A选项不完全错误，但E项更具体。","","N"],["2005-N89",25,"第二节 腹腔脓肿","盆腔脓肿诊断",2005,89,"A","","女性，34岁，溃疡病穿孔行修补术后10天，体温38℃，黏液便4～6次/天，伴有里急后重及尿频、排尿困难，直肠指诊前壁有肿物。此患者应考虑是",[["A","细菌性痢疾"],["B","肠道功能紊乱"],["C","膀胱炎"],["D","盆腔脓肿"],["E","直肠癌"]],"D","腹腔脓肿一般均继发于急性腹膜炎或腹腔内手术，原发性感染少见。急性腹膜炎治疗过程中，如阑尾穿孔或结直肠手术后，出现体温升高、典型的直肠或膀胱刺激症状，里急后重、大便频而量少、有黏液便、尿频、排尿困难等，应想到可能有本病。腹部检查多无阳性发现。直肠指检可发现肛管括约肌松弛，在直肠前壁可触及向直肠腔内膨起、有触痛、有时有波动感的肿物。题中“溃疡病穿孔行修补术后10天”“体温38℃，黏液便4～6次/天，伴有里急后重及尿频、排尿困难”“ 直肠指诊前壁有肿物”均符合盆腔脓肿的表现（D对）。细菌性痢疾（A错）可有腹泻、直肠刺激征与里急后重，但与手术无关，直肠指诊也不会触到前壁肿物。肠道功能紊乱（B错）可有腹泻，但一般无直肠刺激症状。膀胱炎（C错）仅有尿频、尿急、尿痛，也无直肠刺激症状。直肠癌（E错）可以有直肠刺激症状及尿频尿急，也可有直肠肿物，但无发热，也与手术无关。","","N"],["2005-N90",13,"第一节 术前准备","术前准备概述",2005,90,"A","","手术前准备的最根本目的是",[["A","促进切口愈合"],["B","防止切口感染"],["C","提高患者对手术的耐受力"],["D","预防术中各种并发症"],["E","促进术后康复"]],"C","促进切口愈合、防止切口感染主要依靠术者的技术以及病人术后的营养和护理水平，术者手术中对病人造成的损伤少、术后病人营养休息好、护理工作可靠，均有助于伤口愈合和感染的预防（AB错），后者还是促进术后康复的有效方法（E错）。术中并发症的预防主要靠术中监测和药物的使用，以及高超的手术及麻醉水平（D错）。术前准备的目的是保障手术病人在手术期间的安全，提高患者对于手术和麻醉的耐受能力（C对），避免或减少围手术期并发症。","","N"],["2005-N91",33,"第二节 胰腺炎","急性胰腺炎致病危险因素",2005,91,"A","","下列关于急性胰腺炎病因的叙述，错误的是",[["A","胆汁逆流入胰管"],["B","乙醇对胰腺有直接毒性作用"],["C","ERCP检查可引发胰腺炎"],["D","与高脂血症关系不清"],["E","消化性溃疡易导致胰腺炎"]],"E","急性胰腺炎有多种致病因素：胆道疾病是国内最主要的原因，占50%，发病原因就是“共同通道”受阻，胆汁逆流入胰管，动物实验显示胆盐可直接导致腺泡细胞质钙离子增高，引起腺泡细胞坏死或胰管内高压诱发急性胰腺炎（A对）。在西方国家，酒精中毒是急性胰腺炎的主要原因，乙醇能直接损伤胰腺（B对），还可刺激胰液分泌、引起十二指肠乳头水肿和Oddi括约肌痉挛。ERCP检查可引发胰腺炎（C对），因为其需要经过共同通道逆行检查，为有创检查，可致十二指肠乳头水肿，壶腹部排出不畅，引起胆汁及胰液反流入腺泡，损伤胰腺实质，导致急性胰腺炎。高脂血症（D）诱发急性胰腺炎的机制可能是甘油三酯在胰脂酶的作用下生成游离脂肪酸，对腺泡有直接损害作用，而高脂血症导致血液黏度上升也可能加重胰腺病变和其他器官功能损害，因此高脂血症属于急性胰腺炎的病因之一，但机制尚不能完全确定，本题D选项表述易产生歧义，故需掌握相关知识点。消化性溃疡只有在后壁穿孔并累及胰腺时才可能引起胰腺炎，极为少见（E错，为本题正确答案）。","","N"],["2005-N92",32,"第八节 胆道疾病常见并发症","胆源性急性胰腺炎",2005,92,"A","","女性40岁，有胆囊结石病史。2小时前，无诱因突发上腹剧痛，向腰背部放射。伴恶心，呕吐。查体：体温37.5℃，巩膜无黄染，上腹部压痛，反跳痛，以中腹偏左为重。血淀粉酶1024U/L。尿胆红素（++）。B超示：胆囊3cm×7cm大小，多发强回声影，0.5～0.8cm大小，胆总管直径0.9cm，胰腺增大，胰周渗出。入院后非手术治疗3日，腹痛缓解。复查B超示：胆总管直径0.5cm，尿胆红素（-），尿淀粉酶64U/L。最可能的原因是",[["A","胆囊结石在颈部嵌顿"],["B","胆总管结石下段嵌顿"],["C","十二指肠憩室炎"],["D","急性胆囊炎"],["E","结石一过性通过胆总管下段"]],"E","40岁女性，有胆囊结石病史（可坠落至胆道，引起胆道梗阻）。突发上腹剧痛，以中腹偏左为重，向腰背部放射，伴恶心、呕吐（急性胰腺炎的典型临床表现），血淀粉酶1024 U/L（正常值约35～135 U/L，提示胰腺炎），尿胆红素（++）（提示胆道梗阻）。B超示：胰腺增大，胰周渗出（胰腺炎典型B超表现）。经治疗，胆总管直径由0.9cm降至0.5cm（提示先前可能存在梗阻）。综上，诊断考虑胆源性胰腺炎，最可能的原因为结石一过性通过胆总管下段（E对）。胆囊结石在胆囊颈嵌顿（A错）主要引起的是胆囊积液或急性胆囊炎，而急性胆囊炎（D错）同样在正常情况下不引起急性胰腺炎。十二指肠憩室炎（C错）主要的是黏膜突出，憩室壁主要有黏膜、黏膜下层和浆膜层，而无肌层。多数无症状和特殊体征。若憩室位于十二指肠乳头附近或乳头内时，则可引起梗阻诱发胆道感染，胆管炎，急、慢性胰腺炎等；憩室无法自然消除，仅手术可治疗，与题目中后期胆道梗阻解除相矛盾。胆总管结石下段嵌顿（B错）可使病情不断恶化，也与题目中后期胆道梗阻解除相矛盾。","","N"],["2005-N93",4,"第三节 肠外营养","导管相关并发症",2005,93,"A","","施行肠外营养最严重的并发症是",[["A","气胸"],["B","空气栓塞"],["C","低钾血症"],["D","高血糖致高渗性非酮性昏迷"],["E","导管性脓毒症"]],"B","空气栓塞（B对）为危急症，空气经静脉导管进入血液循环至肺，阻塞肺动脉主要通路，引起严重休克，尚无有效抢救办法，若进入血管的空气过多，可直接导致死亡，故为施行肠外营养最严重的并发症。肠外营养的并发症主要有静脉导管相关并发症、代谢性并发症、脏器功能损害及代谢性骨病等。气胸（A错）的发生是由于深静脉置管时切口不慎破坏了壁胸膜、空气进入胸膜腔引起，为最常见并发症，但不是最严重并发症，切口封闭及胸腔穿刺抽气或闭式引流可治疗；低钾血症（C错）发生的原因是营养液中电解质含量不足，血液遭营养液稀释引起，在营养液中增加电解质比例即可纠正；高血糖致高渗性非酮性昏迷（D错）属于危急症，大量补液和给予胰岛素快速降血糖可治疗；导管性脓毒症（E错）是由于操作或护理不当使导管处发生细菌感染并入血引起败血症，应立即拔除导管、拆开缝线，保持切口引流通畅。取脓液进行细菌培养及药敏试验，使用细菌敏感的抗生素治疗。","","N"],["2005-N94",33,"第四节 胰腺癌和壶腹周围癌","胰腺癌影像学检查",2005,94,"A","","下列CT影像中，最支持胰腺癌诊断的是",[["A","胰周及腹腔渗出，胰腺实质内有不规则低密度区，强化后低密度区增强不明显"],["B","胰头有3cm×4cm不均匀低密度区，强化后有不均匀增强"],["C","胰头部增大，密度与其他部位胰腺组织密度一致，胰周界限模糊"],["D","胰头均匀低密度区，CT值10HU，不被强化，胰体尾萎缩，胰管扩张"],["E","胆管扩张明显，胆总管下端可见2cm×lcm的极强密度区"]],"B","胰腺癌好发于胰头部，典型CT征象为胰头部占位性病变，强化不均匀，因此，胰头有3cm×4cm不均匀低密度区，强化后有不均匀增强（B对）最支持胰腺癌诊断。胰周及腹腔渗出，胰腺实质内有不规则低密度区，强化后低密度区增强不明显（A错）为急性胰腺炎的CT表现。胰头部增大，密度与其他部位胰腺组织密度一致，胰周界限模糊（C错）为胰腺增生的CT表现。胰头均匀低密度区，CT值10HU，不被强化，胰体尾萎缩，胰管扩张（D错）为胰腺囊肿的CT表现。胆管扩张明显，胆总管下端可见2cm×1cm的极强密度区（E错）为胆总管下段结石的CT表现。","","N"],["2005-N95",32,"第二节 胆道疾病影像学检查","胆道疾病超声检查",2005,95,"A","","B超诊断梗阻性黄疸的最直接证据是",[["A","肝内胆管普遍扩张，胆总管直径1.5cm，肝内多发中低回声"],["B","胰头部有3cm×4cm×5cm大小的中低回声区"],["C","胆囊大小3.5cm×6.5cm"],["D","胆囊内强回声伴声影"],["E","胰管直径0.4cm"]],"A","超声诊断是极有用的诊断方法，诊断胆囊结石、胆囊息肉样病变、急性胆囊炎、慢性胆囊炎及胆囊癌、胆管结石等病变，诊断准确率可达95%～98%。超声探查肝内胆管（＞4mm）、肝外胆管（＞10mm）有无扩张，可判定胆道梗阻部位及原因。超声显示肝内胆管普遍扩张，胆总管直径1.5cm（正常值0.6～0.8cm），肝内多发中低回声是梗阻性黄疸最直接的证据（A对）。胰头部有3cm×4cm×5cm大小的中低回声区（B错），提示胰头部有占位性病变，为梗阻性黄疸的间接性证据。胆囊大小3.5cm×6.5cm（C错）为正常胆囊的B超征象（正常胆囊大小为宽3～5cm，长5～8cm）。胆囊内强回声伴声影（D错）为胆囊结石的B超征象。胰管直径0.4cm（正常胰管直径为0.2～0.3cm）（E错）说明胰管梗阻扩张，并非梗阻性黄疸的直接证据，亦可由Vater壶腹梗阻引起。","","N"],["2005-N96",27,"第四节 肠梗阻","肠套叠临床表现",2005,96,"A","","肠套叠的三大典型症状是",[["A","腹痛、发热、黄疸"],["B","腹痛、脓血便、发热"],["C","腹痛、血便、里急后重"],["D","腹痛、血便、腹部肿块"],["E","血便、腹部肿块、发热"]],"D","肠套叠的三大典型症状是腹痛、血便和腹部肿块（D对）。此外，关于肠套叠尚须掌握以下知识点：肠套叠绝大多数发生于2岁以内小儿；多见回结肠套叠，钡剂灌肠可见受阻端钡影呈“杯口”状或“弹簧状”阴影；应用空气、氧气或钡剂灌肠不仅是诊断方法，也是一种有效的治疗方法，适用于回盲型或结肠型的早期。腹痛、发热、黄疸（A错）为Charcot三联征，见于急性胆管炎。腹痛、脓血便、发热（B错）可见于肠阿米巴病。腹痛、血便、里急后重（C错）可见于痢疾以及溃疡型结肠炎。血便、腹部肿块、发热（E错）可见于部分肠道肿瘤患者。","","N"],["2005-N97",18,"第三节 乳腺良性疾病","乳腺囊性增生病治疗",2005,97,"A","","乳腺囊性增生病的主要处理措施是",[["A","服药"],["B","手术"],["C","定期复查"],["D","激素治疗"],["E","理疗"]],"C","乳腺囊性增生病又称乳腺病，是中年妇女的多发病。本病典型的临床症状是乳房胀痛和肿块，该病通常与月经周期有关，可自行缓解，主要治疗是对症治疗。乳房囊性增生病的接诊多以宣传教育为主，绝大部分无需治疗，疼痛明显时可使用中药疏肝理气及调和冲任等方法可以缓解疼痛，但该病与乳腺癌的关系尚不明确，流行病学研究提示囊性增生病病人以后发生乳腺癌的机会为正常人的2～4倍，故需要定期复查，了解病变情况（C对）。","","N"],["2005-N98",27,"第四节 肠梗阻","机械性肠梗阻",2005,98,"A","","下列哪项不是引起机械性肠梗阻的原因",[["A","肠管扭转"],["B","肿瘤"],["C","肠道闭锁"],["D","铅中毒"],["E","嵌顿疝"]],"D","肠梗阻是常见的外科急腹症，任何引起肠内容物通过障碍，并有腹胀、腹痛等临床表现的原因均可认为是肠梗阻病因。一般病因可分为三类，机械性肠梗阻、动力性肠梗阻和血运性肠梗阻，另还提出原因不明的假性肠梗阻分类。任何可以导致肠腔通道变窄、肠内容物通过障碍的疾病均称为机械性肠梗阻。肠管扭转（A对）使得肠腔闭锁；肿瘤（B对）膨胀性及浸润性生长使得肠腔变窄僵硬；肠道闭锁（C对）属于先天性疾病，由于肠道发育异常引起婴儿出生时便存在肠腔部分关闭不通；疝嵌顿（E对）是由于部分肠腔嵌顿于疝环中，导致肠内容物无法通过；这些都是典型的机械性肠梗阻。铅中毒（D错，为本题正确答案）可导致病人肠道肌肉痉挛，肠腔虽然仍旧保持通畅，但是失去了推动肠内容物前进的肠蠕动，从而导致肠内容物无法通过肠腔，此属于动力性肠梗阻。","","N"],["2005-N99",29,"第七节 直肠癌","直肠癌病因",2005,99,"A","","目前认为与直肠癌发生无关的因素是",[["A","痔"],["B","日本血吸虫病"],["C","溃疡性结肠炎"],["D","高蛋白高脂肪饮食"],["E","直肠腺瘤"]],"A","痔可分为内痔及外痔。内痔本质上是肛垫的支持结构、静脉丛及动静脉吻合支发生病理性改变或移位；外痔是齿状线远侧皮下静脉丛的病理性扩张或血栓形成。无论内痔或外痔（A错，为本题正确答案）均与直肠癌的发生无关。一般认为结直肠癌的发生与下列因素有关：①饮食因素：长期高脂肪、高蛋白（可能与该类饮食可增加粪便中的甲基胆蒽含量有关）（D对）、低纤维素饮食；②直肠腺瘤（E对）可演变为直肠癌，尤以绒毛状腺瘤的癌变率高；③遗传性非息肉病性结直肠癌和家族性结肠息肉病；④直肠慢性炎症性疾病：日本血吸虫病（B对）、溃疡型结肠炎（C对）、和克罗恩病，因为黏膜反复破坏感染和修复过程中容易发生原癌基因过度激活，产生癌变。","","N"],["2005-N100",29,"第三节 乙状结肠扭转","乙状结肠扭转临床表现",2005,100,"A","","乙状结肠扭转时钡灌肠X线检查可见扭转部位钡剂受阻，呈现",[["A","“中断”"],["B","“杯口”"],["C","“鸟嘴”"],["D","“线状”"],["E","“倒3征”"]],"C","乙状结肠扭转钡剂灌肠X线检查见扭转部位钡剂受阻，钡影尖端呈“鸟嘴”形（C对）；不同疾病的钡剂灌肠X线表现需掌握：“中断”多见于早期食管癌，表现为局限性食管黏膜皱襞增粗、中断（A错）；回结肠套叠，钡剂灌肠可见受阻端钡影呈“杯口”（B错）状或“弹簧”状阴影；克罗恩病的X线钡餐表现为裂沟状深溃疡，黏膜呈鹅卵石样，病变呈跳跃式，而狭窄部呈线状征（D错）；胰头癌行低张十二指肠钡剂造影患者可见“倒3征”（E错）。","","N"],["2005-N101",31,"门静脉高压","食管胃底曲张静脉破裂出血手术治疗",2005,101,"A","","门脉高压症食管静脉曲张手术治疗的最主要目的是",[["A","减少腹水"],["B","提高机体免疫力"],["C","防止肝癌发生"],["D","治疗及预防曲张静脉破裂出血"],["E","改善肝功能"]],"D","门脉高压症食管静脉曲张手术治疗的术式包括分流术或断流术两大类，其主要目的均为治疗及预防曲张静脉破裂出血（D对）。分流术是使门静脉系统的血液全部或部分不经过肝而流入体静脉系统，降低门静脉压力，从而达到止血的目的。断流术是通过阻断门、奇静脉之间的反常血流，达到止血的目的。与分流术相比，断流术术后门静脉压力不降反升，增加了门静脉向肝血流；术后并发症少，肝功能损害轻。分流术和断流术均可导致肝血流异常，从而加重肝功能损害（E错），对潴水类激素的灭活进一步减少，白蛋白生成降低，可加剧腹水形成（A错）。任何外科手术都不具有提升病人免疫力的能力，免疫力的提高需通过加强营养和锻炼、注意休息、使用内科药物（如升白药）等方式（B错）。门静脉高压并非肝癌的诱发因素，防止肝癌发生需要针对引起门脉高压的基础疾病（如病毒性肝炎）进行治疗（C错）。","","N"],["2005-N102",47,"第二节 股骨近端骨折","股骨头下骨折",2005,102,"A","","由于外伤破坏局部血供，导致不利于愈合的骨折是",[["A","肋骨骨折"],["B","椎弓根骨折"],["C","内踝骨折"],["D","股骨转子间骨折"],["E","股骨颈头下型骨折"]],"E","成人股骨头的血液供应有多种来源：①股骨头圆韧带内的小凹动脉，提供股骨头凹部的血液循环；②股骨干滋养动脉升支，沿股骨颈进入股骨头；③旋股内、外侧动脉的分支，是股骨头、颈的重要营养动脉。股骨颈头下型骨折（E对）的骨折线位于股骨头下，可损伤旋股内侧动脉，此时股骨头仅有小凹动脉很少量的供血，致使股骨头严重缺血，故发生股骨头缺血坏死的机会很大。常考的易发生缺血性骨坏死或不易愈合的骨折包括：胫骨下1/3段骨折、股骨颈头下型骨折、手部腕舟骨骨折等。","","N"],["2005-N103",50,"第二节 上肢神经损伤","臂丛抻经损伤",2005,103,"A","","臂丛神经的组成是",[["A","颈5、6、7、8和胸1"],["B","颈1、2、3、4"],["C","颈7、8和胸1、2、3"],["D","颈3、4、5、6、7"],["E","胸1、2、3、4"]],"A","臂丛由第C₅-₈颈神经和第1胸神经前支的大部分组成（A对）。这五条神经根经斜角肌间隙，颈5、6的前支合成上干，颈7前支延为中干，颈8神经前支和胸1神经前支的大部分合成下干。出斜角肌间隙后每个干有分为前后两股，由上、中干的前股合成外侧束，下干的前股延为内侧束，三干的后股汇合成后束。即臂丛的构成可概括为五根三干六股。","","N"],["2005-N104",44,"第一节 骨折的定义、成因、分类及移位","螺旋形骨折",2005,104,"A","","下列骨折中，最不稳定的是",[["A","裂缝骨折"],["B","横形骨折"],["C","螺旋骨折"],["D","青枝骨折"],["E","嵌插骨折"]],"C","裂缝骨折（A错）和横行骨折（B错）在重力作用下不受到来自骨折线方向的应力而不易移位。青枝骨折（D错）好发于儿童、因骨质柔韧不易完全断裂而属于稳定性骨折。压缩性骨折和嵌插骨折（E错）因骨质相互嵌插，不易发生相对移位，均为稳定性骨折。螺旋骨折（C对）和斜行骨折受到的应力会分解向不同的方向，易引起骨折处的移位；粉碎性骨折则无法承受应力，此三者为不稳定骨折。","","N"],["2005-N105",54,"第二节 化脓性关节炎","化脓性关节炎诊断",2005,105,"A","","化脓性关节炎早期诊断中，最有价值的方法是",[["A","关节活动度检查"],["B","X线平片"],["C","MRI检查"],["D","关节液检查"],["E","手术探查"]],"D","对于化脓性关节炎的早期诊断，最有价值的方法是关节穿刺和关节液检查（D对），若关节液呈脓性或镜检发现细菌，则诊断需考虑化脓性关节炎可能。化脓性关节炎虽然会导致关节活动度下降，但是该项检查不具有特异性（A错）。化脓性关节炎早期以浆液性渗出为主，暂没有骨质的破坏，X线平片（B错）无特异性表现。MRI（C错）为急性化脓性骨髓炎的早期诊断方法。手术探查（E错）适用于髋关节等位置较深的大关节化脓性关节炎的诊断。","","N"],["2005-N106",47,"第二节 股骨近端骨折","股骨转子间骨折临床表现和诊断",2005,106,"A","","女性，70岁，行走时不慎滑倒，即感右髋部疼痛，2小时后来院，查体右髋部有皮下瘀血、局部压痛、右下肢较左下肢短缩3cm，右下肢外旋80°畸形。最可能的诊断是",[["A","髋关节脱位"],["B","股骨转子间骨折"],["C","髋臼骨折"],["D","股骨大转子骨折"],["E","骨盆骨折"]],"B","70岁女性患者，行走时不慎滑倒。右髋部疼痛，查体右髋部有皮下瘀血（考虑存在髋关节损伤）、局部压痛、右下肢较左下肢短缩3cm，右下肢外旋80°畸形（外旋角度大）。综合该患者病史及体查，诊断考虑为股骨转子间骨折（B对）。髋关节前脱位表现为髋关节屈曲、外展、外旋畸形；髋关节后脱位表现为髋关节屈曲、内收、内旋畸形（A错）。股骨大转子骨折（D错）不会出现患肢缩短。髋臼骨折（C错）及骨盆骨折（E错）可出现两侧肢体长度不对称，但多存在骨盆分离及挤压试验阳性，与该患者临床表现不符。","","N"],["2005-N125",2,"第三节 自体输血和大量输血","电解质、酸碱平衡紊乱",2005,125,"B","","短期内输库存血5000ml，患者容易发生的酸碱平衡紊乱是",[["A","代谢性酸中毒"],["B","代谢性碱中毒"],["C","呼吸性酸中毒"],["D","呼吸性碱中毒"],["E","代谢性酸中毒合并代谢性碱中毒"]],"B","短期内输入库存血5000ml，属大量输血，库存血中的抗凝剂枸橼酸钠在肝脏转化为碳酸氢钠，从而导致代谢性碱中毒（B对）。不要错误的认为：大量输库存血一方面引起血钾升高发生代谢性酸中毒，另一方面库存血中的枸橼酸钠在肝转化为碳酸氢钠，导致代谢性碱中毒，从而将答案误为代谢性酸中毒（A错）或代谢性酸中毒合并代谢性碱中毒（E错）。","","N"],["2005-N126",1,"第五节 酸碱平衡失调","代谢性碱中毒病因",2005,126,"B","","幽门梗阻的患者最易发生的酸碱平衡紊乱是",[["A","代谢性酸中毒"],["B","代谢性碱中毒"],["C","呼吸性酸中毒"],["D","呼吸性碱中毒"],["E","代谢性酸中毒合并代谢性碱中毒"]],"B","幽门梗阻病人的症状主要为无法进食水、反复呕吐导致胃液丧失过多。酸性胃液大量丢失，可丧失大量的氢离子和氯离子。肠液中的碳酸氢根离子未能被胃液的氢离子所中和，碳酸氢根离子被重吸收入血，使血浆碳酸氢根离子增高。另外，胃液中氯离子的丢失使肾近曲小管的氯离子减少，为维持离子平衡，代偿性地重吸收碳酸氢根离子增加，导致碱中毒。大量的胃液丢失也丢失了钠离子，在代偿过程中，钾离子和钠离子的交换、氢离子和钠离子的交换增加，即保留了钠离子，但排除了钾离子及氢离子，造成低钾血症和代谢性碱中毒（B对）。","","N"],["2005-N127",53,"第二节 腰椎退行性疾病","肌力下降",2005,127,"B","","导致足拇趾背伸力弱的是",[["A","L₁～₂椎间盘突出"],["B","L₂～₃椎间盘突出"],["C","L₃～₄椎间盘突出"],["D","L₄～₅椎间盘突出"],["E","L₅～S₁椎间盘突出"]],"D","L₄～₅椎间盘突出（D对）压迫L₅神经根，表现为小腿前外侧及足背内侧感觉障碍，足拇趾背伸乏力或不能。L₁～₂椎间盘突出（A错）压迫L₂神经根，表现为大腿前中部感觉障碍，屈髋无力。L₂～₃椎间盘突出（B错）压迫L₃神经根，表现为股骨内髁感觉障碍，伸膝无力，膝反射减弱或消失。L₃～₄椎间盘突出（C错）压迫L₄神经根，表现为小腿前内侧及膝前感觉障碍，伸膝无力，膝反射减弱或消失。L₅～S₁椎间盘突出（E错）压迫S₁神经根，表现为小腿后外侧及外踝、足外侧感觉障碍，趾及足跖屈无力，踝反射下降。","","N"],["2005-N128",53,"第二节 腰椎退行性疾病","肌力下降",2005,128,"B","","导致足趾跖屈力弱的是",[["A","L₁～₂椎间盘突出"],["B","L₂～₃椎间盘突出"],["C","L₃～₄椎间盘突出"],["D","L₄～₅椎间盘突出"],["E","L₅～S₁椎间盘突出"]],"E","L₁～₂椎间盘突出（A错）压迫L₂神经根，表现为大腿前中部感觉障碍，屈髋无力。L₂～₃椎间盘突出（B错）压迫L₃神经根，表现为股骨内髁感觉障碍，伸膝无力，膝反射减弱或消失。L₃～₄椎间盘突出（C错）压迫L₄神经根，表现为小腿前内侧及膝前感觉障碍，伸膝无力，膝反射减弱或消失。L₄～₅椎间盘突出（D错）压迫L₅神经根，表现为小腿前外侧及足背内侧感觉障碍，足趾背伸乏力或不能。L₅S₁椎间盘突出（E对）压迫S₁神经根，表现为小腿后外侧及外踝、足外侧感觉障碍，趾及足跖屈无力，踝反射下降。","","N"],["2005-N147",26,"第三节 胃十二指肠溃疡的外科治疗","胃十二指肠溃疡瘢痕性幽门梗阻治疗",2005,147,"X","","十二指肠球部溃疡并幽门梗阻患者可选择的手术方式有",[["A","胃大部切除术"],["B","高选迷走神经切断术"],["C","胃空肠吻合术"],["D","迷走神经干切断术加胃窦部切除术"]],"AD","选择的手术方式须能同时解决患者存在十二指肠球部溃疡及幽门梗阻症状。胃大部切除术（A对）切除范围包括胃远侧的2/3～3/4并包括幽门、近胃侧部分十二指肠球部，切除产生溃疡部位的同时解决了梗阻问题。高选迷走神经切断术（B错）切断了支配胃体的迷走神经，保留了支配胃窦部的鸦爪支，可部分解决溃疡问题，但无法解决幽门梗阻，且迷走神经切断术现在已很少应用。胃空肠吻合术（C错）仅能解除梗阻问题，术后溃疡仍存在，且胃空肠吻合口处可发生顽固性溃疡。迷走神经干切断术加胃窦部切除术（D对）不仅降低了胃酸分泌，且消除了梗阻部位，但现在临床应用较少。","","N"],["2005-N148",34,"第一节 上消化道大出血的诊断和处理","内镜检查",2005,148,"X","","消化道出血患者，下列哪些检查可能对诊断和治疗有帮助",[["A","急诊胃镜检查"],["B","急诊肠镜检查"],["C","选择性血管造影"],["D","核素扫描"]],"ABC","急诊胃镜检查（A对）可迅速明确出血的部位和性质，是诊断上消化道出血的首选方法，同时可进行双极电凝、电灼、激光、喷注止血等内镜治疗，对诊断和治疗均有帮助。急诊肠镜检查（B对）主要有直肠镜、乙状结肠镜、纤维结肠镜和小肠镜检查，能直视观察病变范围、性质、程度，在检查过程可取活组织病理检查，对息肉、早期直肠癌可予以切除，并可进行电灼止血等，是目前结直肠病变主要的诊断和治疗手段之一。选择性血管造影（C对）是将造影剂注入血管，出血速度在0.5ml/min以上就能见到造影剂从血管破口外溢进入肠腔的影像，发现出血病变和部位的阳性率较高；还能通过导管滴入血管收缩药物或注入栓塞剂进行止血治疗。核素扫描（D错）可用于诊断微量出血及间歇性出血，但只能显示出血在腹部某个区域，而不能判断确切的出血部位，亦不能明确病变的性质，且无法治疗出血。","","N"],["2005-N150",57,"第一节 骨肿瘤概论","骨肿瘤诊断",2005,150,"X","","诊断恶性骨肿瘤的依据是",[["A","X线平片见骨质破坏、骨膜增生"],["B","肿物生长快"],["C","血清酸性磷酸酶增高"],["D","局部软组织侵袭明显"]],"ABD","恶性骨肿瘤的X线可见骨质破坏、骨膜增生（A对）。临床表现可见肿物生长快（B对），局部软组织侵袭明显（D对）。酸性磷酸酶增高（C错），多作为前列腺癌和前列腺癌发生骨转移的辅助诊断。血清碱性磷酸酶反应成骨活动，在成骨性肿瘤如骨肉瘤中，患者血清碱性磷酸酶明显升高。","","N"],["2006-N70",31,"门静脉高压","经颈静脉肝内门体静脉分流术",2006,70,"A","","近年来开展的经颈静脉肝内门体分流术治疗肝硬化门脉高压症，其最大副作用是易诱发",[["A","肝肾综合征"],["B","肝肺综合征"],["C","肝性脑病"],["D","感染"],["E","电解质和酸碱平衡紊乱"]],"C","经颈静脉肝内门体分流术（TIPS）是使用可扩张性金属支架建立肝内门体静脉分流的治疗方法，采用介入手段，经颈静脉途径在肝内静脉与门静脉主要分支间建立通道，置入支架以实现门体分流。术后大量血液未经肝脏的解毒作用，直接进入体循环，影响脑功能，可引起或加重肝性脑病（九版内科学P408）（C对）。肝肾综合征（九版内科学P409）（A错）是指在严重肝病时发生的功能性急性肾功能衰竭，TIPS一般不引起肝肾综合征。肝肺综合征（九版内科学P410）是指慢性肝病和/或门脉高压的基础上出现肺内血管异常扩张、气体交换障碍、动脉血氧合作用异常，导致的低氧血症及一系列病理生理变化和临床表现。（七版黄家驷外科学P1777）TIPS可改善肝肺综合征患者的氧合作用（B错）。TIPS可增加钠排泄并消除腹水，可改善电解质和酸碱平衡紊乱（E错）。","","N"],["2006-N85",17,"第一节 甲状腺疾病","术后呼吸困难和窒息",2006,85,"A","","一个患有结节性甲状腺肿的病人在硬膜外麻醉下行双侧甲状腺大部切除术，术后当晚出现呼吸困难、烦躁、发绀，脉率130次/分，血压146/90mmHg，伤口敷料引流血少。最可能的原因是",[["A","甲状腺危象"],["B","气管塌陷"],["C","喉头水肿"],["D","切口内出血压迫"],["E","双侧喉返神经损伤"]],"D","患者甲状腺大部切除术后当晚出现呼吸困难、烦躁、脉快，伤口敷料引流血少，考虑引流不畅，切口内血肿出血压迫（D对）气道，引起的呼吸困难。甲状腺危象（A错）的主要临床表现是高热（﹥39℃），心率增快（﹥120次/分），同时合并神经、循环及消化系统严重功能紊乱如烦躁、谵妄、大汗、呕吐、水泻等，但无呼吸困难表现。气管塌陷（B错），是气管壁长期受肿大甲状腺压迫，发生软化，切除甲状腺的大部分后，软化的气管壁失去支撑的结果，常于术后立即发生，一般不会等到术后当晚。喉头水肿（C错）多发生于婴幼儿及气管内插管困难者，也可因手术牵拉或刺激喉头引起，术前服用抗甲状腺药物过度，合并有甲状腺功能减退者容易发生。双侧喉返神经损伤（E错）引起的呼吸困难和窒息，是于手术中损伤喉返神经后会立即出现，不会等到术后当晚才发生。","","N"],["2006-N86",10,"第二节 麻醉前评估和准备","麻醉前准备",2006,86,"A","","下列关于麻醉前病人准备的叙述，错误的是",[["A","合并高血压者应控制在180/100mmHg以下较为安全"],["B","合并急、慢性肺部感染者，应用有效抗生素3～5天"],["C","有心衰史、房颤或心脏明显扩大者，术前3天应停用洋地黄类药物"],["D","糖尿病者空腹血糖不高于8.3mmol/L"],["E","小儿术前应禁食4～8小时，禁水2～3小时"]],"AC","麻醉前准备包括：①为避免发生胃内容物反流、呕吐或误吸导致窒息和吸入性肺炎，择期手术前应保证胃排空。成人应禁食12小时，禁水4小时。小儿应禁食4～8小时，禁水2～3小时（E对）；②合并高血压者，应经严格内科治疗，维持血压在140/90mmHg以下较为安全（A错，为本题正确答案）；③凡有心衰史、房颤或心脏明显扩大者，应以洋地黄类药物治疗，并于手术当天停药（C错，为本题正确答案）；④合并呼吸系统疾病者，应停止吸烟至少2周，并进行呼吸功能训练，雾化吸入，应用有效抗生素3～5天以控制肺部感染（B对）；⑤合并糖尿病者，应控制血糖不高于8.3mmol/L（D对）。","","N"],["2006-N87",13,"第二节 术后处理","胃肠道功能",2006,87,"A","","下列关于术后病人的饮食处理，错误的是",[["A","非腹部局麻下的手术，术后即可进食"],["B","非腹部腰麻或硬膜外麻醉下的手术，一般术后2～3天即可进食"],["C","非腹部全麻下的手术，病人清醒，无呕吐时可进食"],["D","择期胃肠道手术，肠蠕动恢复后，可开始饮水，进少量流食"],["E","腹部手术需禁食时间较长者，应给予胃肠外营养"]],"B","局麻作用于局部的神经使其麻痹，对整个身体的生理机能无明显影响，非腹部局麻下的手术，无局麻药中毒表现，术后即可进食（A对）。非腹部全麻下的手术，全麻过程中因病人意识消失，咽喉部反射消失，一旦有反流物易发生误吸；当病人清醒后，各种感觉和神经反射恢复，可自行控制进食活动，无呕吐时即可进食（C对）。择期胃肠道手术，由于手术损伤消化道，胃肠道功能暂时丧失，术后不能立即进食，需待到肠蠕动恢复后，或肛门排气后，可开始饮水，进少量无渣流食（D对），逐步过度到全量流食、半流食，第7～9天可以恢复普通饮食。腰麻或硬膜外麻醉属于椎管内麻醉，只要为非腹部手术，当麻醉效果消退后（一般为术后3～6小时）对消化道残存的影响较小，恢复后即可进食（B错，为本题正确答案）。腹部手术需禁食时间较长者，应给予胃肠外营养（E对），以免内源性能量和蛋白质过度消耗，影响患者预后。","","N"],["2006-N88",32,"第四节 胆石症","胆囊结石治疗",2006,88,"A","","女性，60岁，因突发性右上腹痛8小时入院。查体：体温38．5摄氏度，心率90次/分，血压110/80mmHg，右上腹压痛，肌紧张、反跳痛，WBC16×10⁹/L。B超提示胆囊增大壁厚，内有结石多个，胆总管直径1.2cm，拟行急诊手术。此病人应选择的手术方式是",[["A","胆囊切除术"],["B","胆囊切除加总胆管探查术"],["C","胆囊造瘘术"],["D","胆肠吻合术"],["E","PTCD"]],"B","60岁女性患者（老年女性），右上腹压痛、肌紧张、反跳痛（腹膜刺激征），WBC 16×10⁹/L（提示存在炎症感染）。B超提示胆囊增大壁厚，内有结石多个（可坠入胆道引起胆道梗阻），胆总管直径1.2cm（直径＞1cm，胆总管增粗，提示存在胆道梗阻）。该患者诊断考虑胆囊结石、慢性胆囊炎急性发作、胆管结石，应行胆囊切除术加胆总管探查术（B对A错）。临床上行胆囊切除时，胆总管探查指征为：胆总管存在梗阻；术中证实胆总管存在病变；胆总管扩张，直径超过1cm，胆囊壁明显增厚，发现胰头肿物；胆囊结石小，有可能通过胆囊管进入胆总管。胆囊造瘘术（C错）及PTCD（E错）仅能部分减轻胆道压力，达不到根治胆总管结石的目的。单纯行胆肠吻合术（D错）未能处理病变的胆囊。","","N"],["2006-N89",27,"第四节 肠梗阻","是单纯性还是绞窄性梗阻",2006,89,"A","","男性，26岁，餐后打篮球，半小时后剧烈腹痛，6小时后来院，伴恶心呕吐。查体：全腹腹膜炎体征，以中腹部明显，肠鸣音弱。血淀粉酶64U/dl，腹穿抽出淡血性液，淀粉酶为64U/dl，考虑诊断为",[["A","急性出血坏死性胰腺炎"],["B","急性胆囊炎"],["C","急性阑尾炎"],["D","上消化道穿孔"],["E","绞窄性肠梗阻"]],"E","青年男性患者，饱食后剧烈运动，出现腹痛、恶心、呕吐以及腹膜炎体征。血淀粉酶及腹穿淀粉酶均未见明显升高，腹穿有血性液，诊断考虑绞窄性肠梗阻。饱食后肠袢重量增加，剧烈运动中的体位突然改变使肠袢产生不同步的运动，使已有轴心固定位置且有一定重量的肠袢发生扭转，扭转肠段肠系膜亦随之扭转，导致其血供减少，易发生肠缺血坏死，即出现绞窄性肠梗阻（E对）。急性出血坏死性胰腺炎（A错）为左上腹疼痛，伴左肩、左腰部放射痛，血清及腹穿淀粉酶一般增高（正常值约40～180 U/dL）。急性胆囊炎（B错）多为右上腹阵发性绞痛，且腹膜刺激征一般也位于右上腹。急性阑尾炎（C错）为转移性右下腹痛，右下腹压痛及反跳痛。上消化道穿孔（D错）为上腹持续性剧烈疼痛，后由于胃肠内容物沿右结肠旁沟流入右下腹，临床表现为上腹部痛扩散至右下腹甚至全腹。","","N"],["2006-N90",9,"第二节 移植免疫","超急性排斥反应",2006,90,"A","","将猪的肝脏移植给人，目前需要解决的主要问题是",[["A","超急性排斥反应"],["B","急性排斥反应"],["C","慢性排斥反应"],["D","病人不愿接受"],["E","手术技术尚不成熟"]],"A","根据供者和受者在遗传基因上的差异程度，异体移植术可分为三类：①同质移植：即供、受体基因型完全相同的个体间的移植。②同种移植术，即供、受体属于同一种属但遗传基因不相同的个体间的移植。③异种移植：即不同种属间的移植，如猪与人之间的器官移植。其中，供体与受体基因表型越接近，则越容易被受体本身接受，如同卵双生双胞胎个体间的移植不发生排斥反应。异种移植将引起极为强烈的超急性排斥反应（A对）。其发生机制与ABO血型配伍障碍的同种异基因移植的超急性排斥反应很相似。到目前为止，尚无法有效对抗参与这种排斥反应的NK细胞活性。","","N"],["2006-N91",25,"第一节 急性弥漫性腹膜炎","继发性腹膜炎",2006,91,"A","","继发性化脓性腹膜炎病情重的主要原因是",[["A","大肠杆菌感染"],["B","厌氧菌感染"],["C","链球菌感染"],["D","变形杆菌感染"],["E","混合性感染"]],"E","急性腹膜炎绝大多数为继发性的，其感染菌种多为胃肠道内正常存在的菌群，以大肠杆菌最为常见，此外还有克雷伯杆菌、粪链球菌等，一些厌氧菌如脆弱类杆菌也会参与其中。由于胃肠道内菌群复杂，所以继发性腹膜炎常为多种细菌的混合感染，故毒性较强（E对）。有些细菌如粪链球菌、脆弱杆菌等致病性不强，但是在混合感染时，相互之间协同作用往往使毒性增强。","","N"],["2006-N92",23,"第二节 腹股沟疝","腹股沟疝临床表现",2006,92,"A","","下列关于腹股沟疝的叙述，错误的是",[["A","滑疝多见于右侧"],["B","嵌顿性疝多发生在斜疝"],["C","直疝的疝内容物多为小肠和大网膜"],["D","难复性疝的主要特点是疝块不能完全还纳"],["E","绞窄性疝疼痛减轻，但肿块仍在，说明病情好转"]],"E","滑动性疝多见于右侧（A对），左右发病率之比约为1：6。斜疝的疝囊颈比直疝狭小，因此嵌顿性疝多发生在斜疝（B对）。直疝多发生于年老体弱病人，腹内压增高时，易推挤腹腔前方的小肠和大网膜（C对）经直疝三角突出。难复性斜疝在临床表现方面除胀痛稍重外，其主要特点是疝块不能完全回纳（D对）。绞窄性疝若时间较长或疝囊内压力过高以及不当的手法复位，可导致疝囊内肠袢穿孔，疼痛可因疝块压力骤降而暂时有所缓解，病情因肠穿孔及腹膜炎反而更加严重，因此，疼痛减轻而肿块仍然存在者，不可认为是病情好转（E错，为本题正确答案）。","","N"],["2006-N93",18,"第三节 乳腺良性疾病","纤维腺瘤概述",2006,93,"A","","下列关于乳房疾病的叙述，错误的是",[["A","乳腺纤维腺瘤为良性肿物，无恶变可能"],["B","乳管内乳头状瘤恶变率为6%～8%"],["C","慢性囊性乳腺病常为多发性病变"],["D","急性乳腺炎患者几乎都是产妇"],["E","乳房内间质也可以发生恶性肿瘤"]],"A","乳房纤维腺瘤是女性常见的乳腺肿瘤，通常视为良性肿瘤，但本病有无恶变尚有争议，需定期复查以排除恶变可能（A错，为本题正确答案）。乳管内乳头状瘤一般属良性，恶变率为6%～8%（B对），尤其对起源于小乳管的乳头状瘤应警惕其恶变的可能。慢性囊性乳腺病是乳腺囊性增生病，又名小叶增生、乳腺结构不良症、纤维囊性病等，体检发现一侧或双侧乳房内可有大小不一，质韧的单个或为多个的结节，可有触痛，与周围分界不清，亦可表现为弥漫性增厚，为多发性病变（C对）。急性乳腺炎是乳腺的急性化脓性感染，多为产后哺乳的妇女，尤以初产妇更为多见，往往发生在产后3～4周（D对）。乳房内间质也可以发生恶性肿瘤（E对），称乳腺肉瘤。","","N"],["2006-N94",24,"第一节 腹部损伤概述","剖腹探查",2006,94,"A","","下列哪项不是腹部损伤后手术探查的可靠指征",[["A","腹痛"],["B","肠鸣音消失"],["C","膈下有游离气体"],["D","血压有下降趋势"],["E","脉搏增快，体温升高"]],"A","注意手术探查指征中“腹痛或腹膜刺激征有进行性加重或范围扩大者”。仅仅提到“腹痛”（A错，为本题正确答案）不属于手术探查指征，腹痛作为腹部损伤最常见的症状，出现腹痛就要行手术探查显然不合理。肠鸣音消失（B对），提示可能存在腹膜炎导致的麻痹性肠梗阻，亦或是腹膜后血肿压迫腹腔神经节；膈下有游离气体（C对）为消化道穿孔的可靠征象；血压有下降趋势（D对）提示存在进行性出血；脉搏增快，体温升高提示全身情况有恶化趋势，以上情况均提示病情较重，须进行剖腹探查。只要严格掌握考点还原中所述指征，剖腹探查术所付出的代价是值得的。","","N"],["2006-N95",27,"第四节 肠梗阻","是单纯性还是绞窄性梗阻",2006,95,"A","","急性持续性腹痛阵发性加剧并休克，最可能的疾病是",[["A","急性阑尾炎"],["B","绞窄性肠梗阻"],["C","泌尿系结石，肾绞痛"],["D","外伤性肝破裂"],["E","急性单纯性肠梗阻"]],"B","绞窄性肠梗阻（B对）由于有肠管缺血，导致局部代谢产物淤积，刺激肠壁神经，引起的腹痛剧烈而持续，可有阵发性加剧，病情发展迅速，肠管缺血坏死、穿孔，早期出现休克，抗休克治疗后改善不明显。急性阑尾炎（A错）的疼痛特点为转移性右下腹痛，且右下腹出现固定压痛，通常无阵发加剧表现，且阑尾周围大网膜丰富，穿孔后因腹膜包裹，也少形成全腹腹膜炎和休克。泌尿系结石，肾绞痛（C错）多为阵发性剧烈绞痛，病人常辗转反侧，可向腹股沟或会阴部放射，有时可见血尿，但通常不伴有休克。外伤性肝破裂（D错）时，由于肝脏血供丰富，破裂可致大量出血引起休克，且溢出的胆汁可强烈刺激腹膜，可引起严重的腹膜刺激征，疼痛持续，无阵发加剧表现。急性单纯性肠梗阻（E错）的主要表现为腹痛，多为阵发性，并可有腹胀，可闻及肠鸣音亢进等表现，但是通常无休克表现。","","N"],["2006-N96",29,"","",2006,96,"A","","在直肠息肉中，下列哪种癌变率最高",[["A","管状腺瘤"],["B","儿童性息肉"],["C","炎性息肉"],["D","绒毛状腺瘤"],["E","混合性腺瘤"]],"D","直肠息肉是一类从直肠黏膜表面突出到直肠腔内的隆起状病变。直肠息肉可分为：①肿瘤性息肉，包括管状腺瘤（A）、绒毛状腺瘤、混合性腺瘤（E），有恶变倾向；②非肿瘤性息肉，包括增生性息肉、炎性息肉（C错）、儿童性息肉（B错）等，无恶变倾向。一般认为，绒毛状腺瘤（D对）的癌变率最高。","","N"],["2006-N97",30,"第六节 肝良性肿瘤","肝良性肿瘤诊断与鉴别诊断",2006,97,"A","","ALT增高的病人，在鉴别诊断时，下列哪种情况可以不必考虑",[["A","病毒性肝炎"],["B","化脓性胆管炎"],["C","急性胆囊炎"],["D","肝血管瘤"],["E","心肌梗死"]],"D","ALT即谷丙转氨酶，主要分布在肝脏，其次是骨骼肌、肾脏、心肌等组织中。肝血管瘤（D对）为良性肿瘤，多为海绵状血管瘤，生长缓慢，不损伤肝细胞，不会引起ALT升高，也不会引起肝的生化功能的改变。病毒性肝炎（A错）时，肝细胞大量坏死，释放出ALT，导致血ALT升高。化脓性胆管炎（十版外科学P474）（B错）及急性胆囊炎（十版外科学P472）（C错）属于胆道疾病，炎症反应波及至肝，或感染经胆道逆行至肝均可引起包括ALT在内的肝酶的升高。ALT在心肌细胞内含量也较高，心肌梗死（E错）时心肌细胞损伤可释放，使血ALT升高。","","N"],["2006-N98",29,"第六节 结肠癌","结肠癌并发急性肠梗阻的手术",2006,98,"A","","患者因急性肠梗阻开腹探查证实为降结肠肿物所致，发现近端肠管充血水肿严重。下列哪种术式不宜采用",[["A","横结肠造瘘，二期肠切除吻合"],["B","左半结肠切除，一期吻合"],["C","肿瘤不能切除时行横结肠双腔造瘘"],["D","肿瘤切除后近端造瘘，远端封闭"],["E","盲肠造瘘，二期左半结肠切除"]],"B","患者肠梗阻系降结肠肿物导致，此时近端肠管充血水肿严重，不宜行一期根治术，否则由于肠道准备不充分，肠管血运较差，术后容易出现吻合口愈合不良，甚至出现吻合口瘘。因此，该患者不宜采用左半结肠切除，一期吻合（B错，为本题正确答案）。正确的处理方法为一期解除梗阻，待病人全身状况及肠道状况好转后，在充分肠道准备的情况下进行二期病灶切除术或根治术。","","N"],["2006-N99",31,"门静脉高压","断流手术",2006,99,"A","","男性，40岁，血吸虫性肝硬化伴严重脾肿大及血小板减少，有上消化道出血史，胃镜示食管静脉重度曲张。该病人的最佳治疗方法是",[["A","单纯脾切除术"],["B","门腔静脉分流术"],["C","脾肾静脉分流术"],["D","脾切除加贲门周围血管离断术"],["E","曲张静脉套扎术"]],"D","本例患者为晚期血吸虫病肝硬化、脾肿大伴有明显的食管胃底静脉曲张，无论是否发生过大出血，都应考虑在脾切除的同时行贲门周围血管离断术（D对）。该术式对病人打击小，在解决脾功能亢进的同时达到防治曲张静脉破裂出血的目的，保存了门静脉入肝血流，对肝功能影响较小，术后并发症发生率较低，病人术后生存质量高。单纯脾切除（A错）仅解除了脾功能亢进，不能降低食管静脉曲张出血的风险。门腔静脉分流术（B错）和脾肾静脉分流术（C错），手术复杂，创伤大，术后肝性脑病风险大，故临床一般情况下不建议采用。曲张静脉套扎术（E错）仅能防治食管下段静脉曲张破裂出血，并不能治疗脾大及脾功能亢进。","","N"],["2006-N100",33,"第二节 胰腺炎","胰酶测定",2006,100,"A","","男性，50岁，突发上腹痛8小时，剧烈，伴恶心呕吐。查体：末梢循环差，血压95/60mmHg，巩膜无黄染，全腹腹膜刺激征（+），以上腹为重，移动性浊音（+），肠鸣音弱，腹穿抽出血性液。为明确诊断，哪项检查最有效",[["A","B超"],["B","CT"],["C","MRI"],["D","ERCP"],["E","腹穿液淀粉酶"]],"E","由“突发上腹痛8小时”，判断发生急腹症；病人全腹腹膜刺激征阳性，以上腹为重，可推断上腹部某器官（肝、脾、胃、肠道、胰腺）为原发病灶。若为肝破裂时，腹穿液应含有胆汁；若为脾破裂，则由于血液的刺激性弱，不会有全腹明显的刺激征；且肝脾通常不会自发破裂，多由外力引起；胃穿孔可引起体重减轻症状，但是穿刺抽出液应含有胃液及食物残渣；肠道破裂则腹穿液含有食物残渣或粪便。排除上述疾病后，可判断该病人为急性重型胰腺炎。急性胰腺炎时，最有诊断价值的检查是血淀粉酶测定。答案无此选项。患者移动性浊音（+），腹穿抽出血性液，因此腹穿液淀粉酶测定对诊断最有价值（E对）。MRI（C错）和ERCP（D错）对诊断帮助不大，且患者难以忍受。B超（A错）对诊断虽有帮助，但价值不如腹穿液淀粉酶测定。注意：虽然急性胰腺炎最具有诊断价值的影像学检查是增强CT，本题最佳答案不能选B，因为该患者腹穿已经抽出血性液体，且合并休克，临床上应选用一种最简单有效的方法尽快确诊，即将腹穿液送检查淀粉酶。","","N"],["2006-N101",22,"第四节 静脉疾病","原发性下肢深静脉瓣膜功能不全诊断",2006,101,"A","","Pratt试验可了解",[["A","下肢深静脉瓣膜的状况"],["B","下肢深静脉通畅的状况"],["C","大隐静脉瓣膜的状况"],["D","深静脉交通支瓣膜的状况"],["E","肢体动脉供血状况"]],"D","Pratt试验也称交通静脉瓣膜功能试验：病人仰卧，抬高患肢，在大腿根部扎止血带，然后从足趾向上至腘窝缠绕第一根弹力绷带，再自止血带向下，扎上第二根弹力绷带。嘱病人站立，一边向下解开第一根弹力绷带，一边向下缠绕第二根弹力绷带，如果在两根弹力绷带之间的间隙内出现曲张静脉，即提示该处存在功能不全的交通静脉，因此，Pratt试验可了解深静脉交通支瓣膜的状况（D对）。下肢深静脉瓣膜功能状况（A错）可以通过静脉造影或超声检查来判断。下肢深静脉的通畅状况（B错），可以通过Perthes试验来判断。深静脉交通支瓣膜的情况可以通过Pratt试验来判断。大隐静脉瓣膜的状况（C错）可通过静脉造影来判断。肢体动脉供血状况（E错）可以参考肢体皮肤的颜色温度等指标了解。","","N"],["2006-N102",55,"第二节 脊柱结核","脊柱结核临床表现",2006,102,"A","","下列关于脊椎结核的叙述，错误的是",[["A","多有局部红、肿、热、痛及高热"],["B","边缘型椎体结核多见于成人，好发于腰椎"],["C","中心型椎体结核多见于儿童，好发于胸椎"],["D","X线平片表现为骨质破坏和椎间隙狭窄"],["E","以椎体结核占多数"]],"A","局部红、肿、热、痛及高热（A错，为本题正确答案）为急性非特异性感染的症状。结核病变进展，可导致病灶部位积聚大量脓液，结核肉芽组织、死骨，但无红、热等急性炎症反应表现，又称‘冷脓肿’或‘寒性脓肿。脊柱结核发病率占骨与关节结核的首位，约占50%，绝大多数发生于椎体（E对）。边缘型椎体结核多见于成人，腰椎为好发部位（B对），病变局限于椎体上下缘，很快侵犯至椎间盘及相邻的椎体。中心型椎体多见于10岁以下儿童，好发于胸椎（C对），病变进展快，整个椎体被压缩为楔形。X线摄片早期征象有椎间隙变窄、椎体骨质稀疏、破坏，随后有死骨和椎旁阴影扩大等表现（D对）。","","N"],["2006-N103",45,"第十节 桡骨远端骨折","桡骨远端骨折桡骨远端关节面骨折伴腕关节脱位",2006,103,"A","","桡骨远端骨折，骨折线经关节面，远端骨折片向背侧移位，该骨折诊断为",[["A","Colles骨折"],["B","Smith骨折"],["C","Barton骨折"],["D","Monteggia骨折"],["E","Galeazzi骨折"]],"C","Colles骨折（A错）为桡骨远端伸直型骨折，发生于桡骨远端骨松质，并向背侧移位的骨折。Smith骨折（B错）为桡骨远端屈曲型骨折，发生于桡骨远端骨松质，并向掌侧移位的骨折。Barton骨折（C对）为伴有腕关节半脱位的桡骨远端关节面骨折。Monteggia骨折（D错）为尺骨上1/3骨折合并桡骨头脱位。Galeazzi骨折（E错）为桡骨下1/3骨折合并尺骨小头（下尺桡关节）脱位。","","N"],["2006-N104",50,"第三节 下肢神经损伤","腓总神经损伤",2006,104,"A","","胫骨平台及腓骨上端骨折，出现足背伸外翻无力，小腿外侧感觉消失。提示哪个神经受损",[["A","胫神经"],["B","腓肠神经"],["C","股神经"],["D","坐骨神经"],["E","腓总神经"]],"E","在腓骨颈，有腓总神经由腘窝后、外侧斜向下外方，经腓骨颈进入腓骨长、短肌及小腿前方肌群。因此，腓骨胫上段骨折合并移位，常导致腓总神经（E对）损伤，导致小腿前外侧伸肌麻痹，出现踝背伸、外翻功能障碍，呈足内翻下垂畸形。伸拇、伸趾功能丧失，小腿前外侧和足背前、内侧感觉障碍。胫神经（A错）损伤引起小腿后侧屈肌群及足底内在肌麻痹，出现足跖屈、内收、内翻，足趾跖屈、外展和内收障碍，小腿后侧、足背外侧、跟外侧和足底感觉障碍。在腘窝内腓总神经发出的腓肠外侧皮神经，和发自胫神经的腓肠内皮神经汇合成腓肠神经（B错），分布于小腿后区，为感觉神经，损伤主要引起相应部位的感觉异常，无运动障碍。股神经（C错）支配股四头肌，损伤后可导致站立或行走时的膝关节伸直障碍。坐骨神经（D错）损伤，可导致膝关节的屈肌、小腿和足部全部肌肉均瘫痪，大腿后侧、小腿后侧、外侧及足部感觉消失。","","N"],["2006-N105",47,"第二节 股骨近端骨折","经股骨颈骨折",2006,105,"A","","下列哪种骨折发生后，容易发生缺血性骨坏死",[["A","股骨颈骨折"],["B","股骨转子间骨折"],["C","股骨干骨折"],["D","股骨远端骨折"],["E","胫骨平台骨折"]],"A","成人股骨头的血液供应有多种来源：①股骨头圆韧带内的小凹动脉，提供股骨头凹部的血液循环；②股骨干滋养动脉升支，沿股骨颈进入股骨头；③旋股内、外侧动脉的分支，是股骨头、颈的重要营养动脉。股骨颈骨折（A对）可损伤旋股内、外侧动脉，此时股骨头仅有小凹动脉很少量的供血，致使股骨头严重缺血，故发生股骨头缺血坏死的机会很大。其他四项发生后，由于周围有较为丰富的肌肉和血管提供血供，因此较为容易愈合。常考的易发生缺血性骨坏死的骨折包括：股骨颈头下型骨折、手部腕舟骨骨折等。","","N"],["2006-N106",57,"第二节 良性骨肿瘤","骨软骨瘤",2006,106,"A","","男性，22岁，右膝内侧肿块8年，生长较慢，无明显疼痛，X线平片显示股骨下端内侧干骺端杵状肿块，边缘清楚。应首先考虑为",[["A","骨肉瘤"],["B","骨巨细胞瘤"],["C","软骨肉瘤"],["D","骨软骨瘤"],["E","骨样骨瘤"]],"D","22岁男性患者，右膝内侧肿块8年。生长较慢，无明显疼痛（生长慢，症状不明显，提示为良性病变）。X线平片示股骨下端内侧干骺端杵状肿块，边缘清楚（骨软骨瘤的典型X线表现）。综合该患者的病史及影像学检查，诊断考虑骨软骨瘤（D对）。骨肉瘤（十版外科学P765）（A错）为最常见的恶性骨肿瘤，病变局部皮温升高、静脉怒张、疼痛明显，疾病进展较快，X线可呈不同形态，密质骨和髓腔有成骨性、溶骨性和混合性骨质破坏，骨膜反应明显，呈侵袭性发展，可见Codman三角或呈日光射线形态。骨巨细胞瘤（十版外科学P764）（B错）又称破骨细胞瘤，主要症状为疼痛和肿胀，X线片呈偏心、溶骨、膨胀生长，无骨膜反应，病灶膨胀生长、骨皮质变薄，呈肥皂泡样改变，与病人表现不符。软骨肉瘤（十版外科学P766）（C错）发病缓慢，以疼痛和肿胀为主，X线表现为一密度减低的溶骨性破坏，边界不清，病灶内有散在的钙化斑点或絮状骨化影，典型者可有云雾状改变。骨样骨瘤（E错）疼痛是常见症状，典型症状为持续性钝痛，夜间加重，服用水杨酸制剂可缓解，这是重要的鉴别点。","","N"],["2006-N127",48,"第一节 脊柱骨折","脊柱骨折体征",2006,127,"B","","脊柱胸₂水平损伤可引起",[["A","四肢硬瘫"],["B","四肢软瘫"],["C","上肢软瘫，下肢硬瘫"],["D","上肢完好，下肢软瘫"],["E","上肢完好，下肢硬瘫"]],"E","由于成人脊髓和椎管的长度不一致，故脊髓各个节段与相应椎骨的高度并不完全对应。脊髓由延髓向下自C₁-L₁节为脊髓，余下为马尾，其末端为圆锥，发出终丝，终止于骶骨。在发育过程中，脊柱的增长速度快于脊髓，因此多数脊髓的位置均高于相应脊柱序数，具体为：脊髓C₁-₄对应不变，脊髓C₅-T₄应-1，对应脊柱C₄-T₃；脊髓T₅-T₈应-2，对应脊柱T₄-T₆；脊髓T₉-T₁₂约应-3，对应脊柱T₇-T₉；脊髓L₁-L₅对应脊柱T₁₀-T₁₂；脊髓S₁-₅、C₀对应脊柱L₁。脊髓对肌的节段性支配，概括来说，C₁-₄支配颈肌及膈肌，C₅-T₁支配上肢肌，T₂-L₁支配躯干肌，L₂-S₂支配下肢肌，S₃-₅及尾节主要支配会阴肌。硬瘫也称痉挛性瘫痪，是指支配肢体的上运动神经元（椎体系统，控制支配下运动神经元的活动）损伤，表现为肢体肌张力增高、腱反射亢进、病理反射阳性。软瘫也称迟缓性瘫痪，是指支配肢体的下运动神经元（受高级中枢控制，到达骨骼肌的唯一通路）损伤，表现为肢体肌张力下降、腱反射减弱，病理反射阴性。本例患者脊柱T₂水平损伤，对应脊髓T₃节段损伤。而上肢肌由C₅-T₁支配，患者该截段脊髓未受损，故该病人的上肢功能完好；又因下肢（L₂-S₂）的上运动神经元位于损伤节段以下的脊髓内，故发生的为硬瘫（E对）。","","N"],["2006-N128",48,"第一节 脊柱骨折","脊柱骨折体征",2006,128,"B","","脊柱腰₃水平损伤可引起",[["A","四肢硬瘫"],["B","四肢软瘫"],["C","上肢软瘫，下肢硬瘫"],["D","上肢完好，下肢软瘫"],["E","上肢完好，下肢硬瘫"]],"D","由于成人脊髓和椎管的长度不一致，故脊髓各个节段与相应椎骨的高度并不完全对应。脊髓由延髓下行自C₁-L₁节为脊髓，其末端为圆锥，大约终止于L₁，其下为马尾。脊髓对肌的节段性支配，脊髓对肌的节段性支配，概括来说，C₁-₄支配颈肌及膈肌，C₅-T₁支配上肢肌，T₂-L₁支配躯干肌，L₂-S₂支配下肢肌，S₃-₅及尾节主要支配会阴肌。硬瘫也称痉挛性瘫痪，是指支配肢体的上运动神经元损伤后，表现为肢体肌张力增高、腱反射亢进、病理反射阳性。软瘫也称迟缓性瘫痪，是指支配肢体的下运动神经元损伤后，表现为肢体肌张力下降、腱反射减弱，病理反射阴性脊髓由延髓下行自C₁-L₁节为脊髓，其末端为圆锥，大约终止于L₁，其下为马尾。L₃水平损伤已不会再损伤到脊髓，但可损伤自脊髓向下发出支配下肢运动的神经元，造成下肢的瘫痪；由于损伤位于脊髓外，支配下肢运动的上运动神经元均位于脊髓内未受损，损伤的是下肢的下运动神经元，故发生的为软瘫（D对）。","","N"],["2006-N147",34,"第一节 上消化道大出血的诊断和处理","应激性溃疡或急性糜烂性胃炎",2006,147,"X","","应激性溃疡的发病部位主要有",[["A","胃底"],["B","胃体"],["C","幽门部"],["D","胃窦部"]],"AB","应激性溃疡又称Stress ulcer，是继发于严重创伤、烧伤、休克等严重应激性状态下的一种急性胃、十二指肠黏膜病变，可表现为黏膜急性炎症、糜烂或溃疡。应激性溃疡的发生与胃肠黏膜缺血和胃酸存在有关，病变主要位于胃底（A对）及胃体部（B对），胃窦部亦可受累；一部分病变侵及十二指肠，少数可累及食管。","","N"],["2006-N148",2,"第三节 自体输血和大量输血","大量输血并发症",2006,148,"X","","大量输血后病人可出现",[["A","高钾血症"],["B","碱中毒"],["C","凝血异常"],["D","低体温"]],"ABCD","大量输血后可出现：①低体温（D对）（因输入大量冷藏血）；②碱中毒（B对）（枸橼酸钠在肝转化成碳酸氢钠）；③暂时性低钙血症（大量含枸橼酸钠的血制品）；④高钾血症（A对）（一次输入大量库存血所致）及凝血异常（C对）（凝血因子被稀释和低体温）等变化。","","N"],["2006-N149",1,"第五节 酸碱平衡失调","代谢性酸中毒治疗",2006,149,"X","","体液与酸碱失衡时，在积极治疗原发病的同时，首先采取的措施有",[["A","尽快恢复血容量"],["B","积极纠正缺氧"],["C","纠正严重酸中毒或碱中毒"],["D","治疗重度高钾血症"]],"ABCD","作为处理水、电解质及酸碱失调的基本原则，在治疗原发病的同时，如果存在多种失调，应分轻重缓急，依次予以纠正。首先应该处理的是：尽快恢复血容量（A对），保证循环状态良好；积极纠正缺氧（B对）；纠正严重酸中毒或碱中毒（C对）；治疗重度高钾血症（D对）。水电解质和酸碱平衡失调的临床处理需多管齐下，才能够较快改善病人状况、防止代谢失调的再发。","","N"],["2006-N150",53,"","",2006,150,"X","","神经根型颈椎病的临床表现有",[["A","颈肩痛向上肢放射"],["B","前臂及手指麻木"],["C","上肢牵拉实验阳性"],["D","上肢肌力下降"]],"ABCD","神经根型颈椎病发病机制为神经根被侧后方突出的颈椎间盘或增生肥大的钩椎关节或关节突压迫。临床上开始多为颈肩痛，短期内加重，并向上肢放射（A对）。放射痛范围根据受压神经根不同而表现在相应皮节。皮肤可有麻木（B对）、过敏等感觉异常。同时可有上肢无力（D对）、手指动作不灵活。当头部或上肢姿势不当，或突然牵撞患肢即可发生剧烈的闪电样锐痛。神经根型颈椎病患者多有上肢牵拉试验阳性（C对）：检查者一手扶患侧颈部，一手握腕，向相反方向牵拉。此时因臂丛神经被牵张，刺激已受压之神经根而出现放射痛。","","N"],["2007-N85",10,"第三节 全身麻醉","气管内插管",2007,85,"A","","全麻时导管插入气管内的深度，成人应为",[["A","﹤2cm"],["B","2～3cm"],["C","4～5cm"],["D","﹥5cm"]],"C","成人气管内插管是医生必须掌握的临床操作之一，主要用于：①麻醉期间保持病人的呼吸通畅，防止异物进入呼吸道，便于及时吸出气管内分泌物或血液；②进行有效的人工或机械通气，防止病人缺氧和CO₂蓄积；③便于吸入性全身麻醉药的应用。两个数据要记牢：导管插入气管内的深度在成人为4～5cm，导管尖端至中切牙的距离约为18～22cm。","","N"],["2007-N86",12,"第二节 心肺脑复苏","人工通气",2007,86,"A","","下列关于口对口人工呼吸操作的叙述，不恰当的是",[["A","头极度后仰，托起下颌"],["B","吹气时向后压环状软骨"],["C","吹气要看到胸廓抬起"],["D","吹气不少于20次/分"]],"D","保持呼吸道通畅是进行人工呼吸的先决条件，需防止昏迷引起的舌后坠或者分泌物、呕吐物等引起的呼吸道梗阻；吹气前需清除口腔分泌物、异物等防止进入呼吸道；头后仰法（头极度后仰，托起下颌）可防止舌后坠阻塞呼吸道（A对）。吹气时向后压环状软骨的目的是使头极度后仰造成的呼吸道弯曲变直，有利于吹气的进行（B对）。在吹气过程中，眼睛要斜视病人胸廓，观察是否随着吹气产生胸廓起伏，用以判断人工呼吸时吹气是否进入胸腔（C对）。有关心胸外心脏按压相关数据，九版、十版外科学有内容更新，按照九版、十版教材及最新临床指南所述，心脏按压30次后给予人工呼吸2次，即按压与吹气比例为30：2，按压频率以100～120 次/ 分计算，吹气频率为8～10次/分（D错，为本题正确答案）。","","N"],["2007-N87",3,"第三节 感染性休克","感染性休克概述",2007,87,"A","","下列选项中，对休克的微循环变化和内脏继发性损害较严重的是",[["A","心源性休克"],["B","低血容量性休克"],["C","感染性休克"],["D","过敏性休克"]],"C","感染性休克由各种微生物特别是革兰氏阴性细菌感染引起。因各种病原体、毒素及其有害的代谢产物作用，引起微循环血流灌注不足。导致组织器官缺血缺氧，细胞代谢障碍和坏死所引起的全身性微循环障碍综合征。由于细菌本身，分泌的内、外毒素等的损害，使得单纯的休克变得复杂，机体细胞受损发生早，甚至造成多器官功能障碍（C对）。心源性休克（A错）、低血容量性休克（B错）、过敏性休克（D错）三者以有效循环血容量锐减及组织灌注不足为基础，但是无内、外毒素等损害，相对于感染性休克危害较轻。","","N"],["2007-N88",3,"第一节 外科休克概述","微循环的变化",2007,88,"A","","休克代偿期，大量儿茶酚胺释放，但血液供应不减少的脏器是",[["A","肺"],["B","心"],["C","肾"],["D","肝"]],"B","休克早期又称休克代偿期。休克早期的血压下降，通过主动脉弓和颈动脉窦压力感受器引起血管舒缩中枢加压反射，交感-肾上腺轴兴奋导致大量儿茶酚胺释放。儿茶酚胺可使外周（皮肤、骨骼肌）和内脏（如肝、脾、胃肠、肺、肾）的小血管收缩，血流量减少（ACD错）。而冠状动脉主要受心肌代谢水平的影响，心肌代谢增强，代谢产物堆积，引起冠脉舒张。虽儿茶酚胺可使冠状动脉收缩，但同时也可使心肌代谢增强，引起冠脉舒张。在完整机体，神经因素的影响被心肌代谢改变引起的变化掩盖，综合作用下儿茶酚胺增加最终使冠状动脉舒张，血液供应不会减少（B对）。","","N"],["2007-N90",4,"第三节 肠外营养","肠外营养液的配制",2007,90,"A","","需用肠外营养的外科特殊病人，改变营养液的组成和用量时，错误的做法是",[["A","糖尿病人可增加脂肪乳剂用量"],["B","肝病失代偿期病人，营养液的用量应减为全量的1/2左右"],["C","肾衰竭的病人，应严格限制葡萄糖和脂肪乳剂的用量"],["D","严重创伤或危重病人的氨基酸溶液应选用谷氨酰胺二肽为好"]],"C","外科肠外营养支持情况下，针对不同的病人情况，营养液中各成分所占的比例有所不同：糖尿病人对血糖调节欠佳，在减少葡萄糖用量时，可相应增加脂肪乳剂的用量（A对）。肝病失代偿期病人，肝脏代谢功能锐减，无法及时有效的处理肠外营养输入的大量物质，营养液的用量应减为全量的1/2左右（B对）。严重创伤或危重病人，由于强烈的应激反应以及疾病本身的因素，使得机体呈负氮平衡，容易发生谷氨酰胺缺乏，但在体外谷氨酰胺水溶性差，容易变形，而谷氨酰胺二肽水溶性好，稳定，进入体内后可很快分解为谷氨酰胺以补充谷氨酰胺的缺乏（D对）。肾衰竭的病人，由于含氮代谢废物最终需通过尿液排出，故需限制氨基酸的用量，但无需限制葡萄糖和脂肪乳剂的用量（C错，为本题正确答案）。","","N"],["2007-N91",5,"第六节 有芽胞厌氧菌感染","破伤风病因",2007,91,"A","","下列关于破伤风梭菌特点的叙述，错误的是",[["A","厌氧"],["B","以增殖体状态分布于自然界"],["C","革兰染色阳性"],["D","产生大量外毒素"]],"B","破伤风杆菌是革兰氏阳性厌氧性梭状芽孢杆菌（AC对），芽孢位于菌体一侧，呈杵状，广泛存在于灰尘、土壤及粪便当中。菌体易杀灭，芽孢具有特殊的抵抗力，故自然界主要以芽孢形式分布（B错，为本题正确答案）。破伤风杆菌无法侵入正常皮肤与黏膜，因此破伤风都发生在创伤后。破伤风杆菌仅停留在伤口局部繁殖，生成的外毒素（D对）有痉挛毒素及溶血毒素两种。典型临床表现主要由痉挛毒素引起，在肌紧张收缩的基础上，阵发性强烈痉挛，最先受影响的肌群是咬肌，随后顺序为面部表情肌、颈、背、腹、四肢肌，最后为膈肌；典型征象为苦笑面容。溶血毒素可引起心肌损害与局部组织坏死。","","N"],["2007-N92",24,"第二节 常见内脏损伤的特征和处理","肝损伤诊断",2007,92,"A","","男性，30岁，由5米高处跌下2小时，腹痛来院，BP100/70mmHg，P120次/分，腹膜刺激征（+），血红蛋白100g/L，X线片示右膈升高。初步诊断是",[["A","肝破裂"],["B","脾破裂"],["C","胃破裂"],["D","腹膜后血肿"]],"A","青年男性患者，高空跌落史。出现腹痛及腹膜刺激征阳性，血红蛋白稍下降，X线片示右膈升高，初步诊断考虑肝破裂（A对）。高空坠落的撞击导致肝发生破裂，混合有胆汁的血液进入腹腔，刺激腹膜，引起腹痛及腹膜刺激征，大量内出血导致血红蛋白含量降低，右膈下血肿导致右膈升高。脾破裂（B错）可能性较低，因脾位于左侧，且脾破裂的X线片征象为胃右移、横结肠下移，胃大弯有锯齿形压迹（脾胃韧带内血肿），且脾破裂时血液进入腹腔，对腹膜的刺激比较温和，多无明显腹膜刺激征。胃破裂（C错）可能性较低，因胃位于上腹偏左，X线片见腹腔游离气体为胃肠道（主要是胃、十二指肠和结肠，少见于小肠）破裂的证据，立位腹部平片可表现为膈下新月形阴影。腹膜后血肿（D错）不会引起腹膜刺激征，X线片可见腰大肌影消失。","","N"],["2007-N93",29,"第七节 直肠癌","直肠癌概述",2007,93,"A","","下列关于直肠癌的叙述，错误的是",[["A","直肠癌的发病率在大肠癌中仅次于乙状结肠癌"],["B","低位直肠癌约占直肠癌的2/3～3/4"],["C","绝大多数癌肿行直肠指检可触及"],["D","溃疡型癌约占直肠癌全部类型的1/2以上"]],"A","直肠癌是乙状结肠直肠交界处至齿状线之间的癌，直肠癌发生率比结肠癌高（A错，为本题正确答案）。低位直肠癌所占比例高，约占直肠癌的60%～75%（B对）。绝大多数癌肿可在直肠指诊时触及（C对）。直肠癌大体类型可分为溃疡型、隆起型、浸润型，其中溃疡型癌约占直肠癌全部类型的1/2以上（D对）。","","N"],["2007-N94",28,"第三节 特殊类型阑尾炎","小儿急性阑尾炎",2007,94,"A","","男性，10岁，腹痛1天，伴恶心、呕吐、稀便2次，T38℃，右下腹肌紧张，有明显压痛，白细胞15×10⁹/L。最恰当的治疗是",[["A","给予镇静剂"],["B","给予解痉剂，服用肠道抗生素"],["C","输入广谱抗生素观察"],["D","急症手术"]],"D","患儿右下腹肌紧张，有明显压痛，此为典型的急性阑尾炎的体征，此外患儿白细胞、体温升高，有呕吐、稀便的消化道症状，不难诊断为儿童急性阑尾炎。由于缺乏大网膜的保护，加上小儿自身的免疫系统尚不健全，阑尾处炎症反应产物和细菌感染易于扩散，故小儿病情发展快且较重，早期即出现高热、呕吐等症状。有资料显示，小儿急性阑尾炎早期手术死亡率＜1%，而延误后手术死亡率升高逾10倍，故对于小儿急性阑尾炎，急症手术（D对）是最恰当的治疗，应采取积极的手术治疗，以免延误时机而至阑尾穿孔，引发腹膜炎和休克而危及生命。给予镇静剂（A错）、给予解痉剂，服用肠道抗生素（B错）、输入广谱抗生素观察（C错）等治疗都会耽误病情，错失治疗良机","","N"],["2007-N95",32,"第五节 胆道感染","手术方法",2007,95,"A","","腹腔镜胆囊切除时，对保证手术安全、成功和预防并发症发生最具重要意义的操作是",[["A","保持腹内气压的恒定"],["B","腹壁四个戳孔位置的正确"],["C","确认胆囊和胆管的位置"],["D","确认和分离胆囊管和胆囊动脉"]],"D","腹腔镜胆囊切除时，遵照以下几点原则，可以避免不必要的损伤。胆囊切除术的第一个关键性步骤是解剖胆囊三角。胆囊三角含有重要的组织结构，而异常的解剖结构和病理改变在此处是常见的。解剖胆囊三角的关键是明确胆囊和胆管位置，在胆囊管和胆囊床之间进行分离，暴露出清晰的手术视野，明确胆管结构后再使用钛夹。另一个重要步骤是处理胆囊动脉。胆囊血管的变异是很常见的，且部分变异胆囊动脉来源于肝动脉，比较常见且有一定危险性的是来源于肝右动脉。肝右动脉可能通过胆囊三角或与胆囊管伴行，在紧靠胆囊颈处才分出胆囊动脉，因而手术时易误认而被结扎切断。肝右动脉的血流量大，管径较粗，因此，当遇有粗大的胆囊动脉时，应沿该动脉向胆囊解剖分离，直至认清其进入胆囊壁，确认为胆囊动脉无误后才使用钛夹。如果肝动脉损伤，必须马上转到开腹手术。因而，确认和分离胆囊管和胆囊动脉（D 对）对保证手术成功和预防并发症具有重要意义。保持腹内气压的恒定（A 错）、腹壁四个戳孔位置的正确（B 错）、确认胆囊和胆管的位置（C 错）均有利于手术，亦需要注意，但不是最具重要意义的操作。","","N"],["2007-N96",32,"第三节 胆道畸形","先天性胆管扩张症治疗",2007,96,"A","","先天性胆总管囊肿最恰当的治疗方法是",[["A","消炎利胆保守治疗"],["B","囊肿完全切除、空肠胆管R-Y吻合术"],["C","囊肿空肠吻合术"],["D","囊肿十二指肠吻合术"]],"B","先天性胆总管囊肿现在称为先天性胆管扩张症，是指肝内胆管或（和）肝外胆管的先天性囊状扩张，好发于胆总管。其病因与先天性胰胆管合流异常、共同通道过长、慢性胰液胆管反流、胆管黏膜损伤、慢性炎症和胆管壁变薄有关。扩张的囊壁常因炎症、胆汁潴留以致发生溃疡，甚至癌变，其癌变率为10%，随着年龄的增长，囊肿壁的癌变率明显增高，故需尽早手术，囊肿完全切除、空肠胆管R-Y吻合术（B对）为最常用的术式。","","N"],["2007-N97",32,"第四节 胆石症","肝内胆管结石临床表现",2007,97,"A","","下列疾病中，可不出现梗阻性黄疸的是",[["A","肝内胆管结石"],["B","肝门部胆管癌"],["C","胰头癌"],["D","壶腹部肿瘤"]],"A","上段胆管癌又称肝门部胆管癌，90%～98%病人出现黄疸，逐渐加深（B错）。黄疸是胰头癌最主要的临床表现，呈进行性加重（C错）。壶腹癌黄疸出现早，可呈波动性（D错）。上述三种疾病均可导致胆汁流出道受阻，胆红素不能正常排出体外，蓄积在体内引起黄疸。肝内胆管结石（A对）时，若仅为单侧胆管阻塞，由于病变范围较小，其余正常肝组织可代偿此部分肝组织的功能，可不出现黄疸。合并肝外胆管结石或双侧肝胆管结石时，则可出现黄疸。","","N"],["2007-N98",30,"第四节 原发性肝恶性肿瘤","肝细胞癌病因和病理",2007,98,"A","","下列关于癌灶直径大小的选项中，属于小肝癌的是",[["A","1cm"],["B","3cm"],["C","6cm"],["D","9cm"]],"B","肝癌根据肿瘤大小可分为以下四类：①微小肝癌（直径≤1cm）；②小肝癌（＞1cm，≤5cm）；③大肝癌（＞5cm，≤10cm）；④巨大肝癌（＞10cm）。故由此分类可知，癌灶直径为3cm（B对）属于小肝癌，而癌灶直径为1cm（A错）属于微小肝癌；癌灶直径为6cm（C错）和9cm（D错）属于大肝癌。","","N"],["2007-N99",22,"第四节 静脉疾病","原发性下肢静脉曲张诊断",2007,99,"A","","女性，42岁，售货员，右下肢静脉迂曲、扩张8年，长时间站立有小腿酸胀，可凹性浮肿，近年来常有小腿皮肤瘙痒，色素沉着，检查Trendelenburg试验（+），Perthes试验（-）。初步诊断是",[["A","原发性下肢静脉曲张"],["B","原发性下肢深静脉瓣膜功能不全"],["C","下肢栓塞性浅静脉炎"],["D","周围型下肢深静脉血栓形成"]],"A","42岁女性患者，售货员（需长期站立，为原发性下肢静脉曲张的常见人群），右下肢静脉迂曲、扩张8年。长时间站立有小腿酸胀，可凹性浮肿，近年来常有小腿皮肤瘙痒，色素沉着（提示下肢静脉回流不畅，下肢淤血）。检查：Trendelenburg试验（+），提示大隐静脉瓣膜功能不全；Perthes试验（-），提示下肢深静脉通畅。综合该患者的病史、体查及专科检查，诊断考虑原发性下肢静脉曲张（A对）。原发性下肢深静脉瓣膜功能不全（B错）诊断尚不能完全排除，需进一步进行超声或下肢静脉造影，若观察到深静脉瓣膜关闭不全的特殊征象可明确。下肢栓塞性浅静脉炎（C错）主要表现为病变静脉区呈红肿索条状，明显疼痛和压痛，局部皮温升高，与患者症状不相符。周围型下肢深静脉血栓形成（D错）时，Perthes试验（+）。","","N"],["2007-N100",0,"第二节 手术人员和病人手术区域的准备","病人手术区的准备",2007,100,"A","","手术区域剃毛最佳的时机是",[["A","手术前三天进行"],["B","手术前二天进行"],["C","手术前一天进行"],["D","手术开始前进行"]],"D","手术区域皮肤若毛发细小，可不必剃毛；若毛发影响手术操作，手术前应予剃除，又称“备皮”。手术区域的毛发不仅妨碍手术操作，而且易污染，藏纳污垢、灰尘和滋生微生物。理论上，皮肤清洁处理距手术时间越短，清洁程度保持也就越高，故推荐在邻近手术前进行备皮（D对）。","","N"],["2007-N101",42,"第一节 肾肿瘤","CT",2007,101,"A","","目前诊断肾癌最可靠的影像学方法是",[["A","B超"],["B","KUB和IVU"],["C","肾动脉造影"],["D","CT"]],"D","B超（A错）无创、简单易行，发现肾癌的敏感性高，可以分辨肾内囊性或实质性肿物，但是对于肿物的血供情况和对周围组织浸润情况显示不如CT。KUB为立位尿路平片，IVU为静脉尿路造影，此两者多用于上尿路结石的诊断，对肾癌诊断意义不大（B错）。肾动脉造影（C错）用于观察肾的血管性疾病，对肿瘤诊断有一定帮助，可观察到肿瘤内血管紊乱，注射肾上腺素肿瘤血管不收缩，但其诊断效率较CT低。CT（D对）作为肾癌诊断最可靠的影像学诊断，可准确测定肾癌大小、CT值，了解注射增强剂后有无增强，并可了解肿瘤范围，静脉内有无癌栓，淋巴结有无受累，较其他影像学检查具有比较大的优势。","","N"],["2007-N102",10,"第四节 局部麻醉","臂丛阻滞",2007,102,"A","","臂丛的组成是",[["A","C₅～₈T₁的前支"],["B","C₅～₈T₁的后支"],["C","C₅～₈T₁的前支和后支"],["D","C₅～₇T₁的后支"]],"A","臂神经丛主要由 C₅-₈ 和T₁（A对）（C、T 分别代表颈和胸）脊神经的前支组成并支配上肢的感觉和运动”。这些神经根自各自的椎间孔发出，经前、中斜角肌之间的肋间沟，在此他们合成臂丛神经干，继而在锁骨中段的后方行向外下进入腋窝，并于腋窝内形成主要终末分支，及正中神经、桡神经、尺神经和肌皮神经。","","N"],["2007-N103",57,"第一节 骨肿瘤概论","骨肿瘤影像学检查",2007,103,"A","","下列选项中，提示骨肿瘤为恶性的X线表现是",[["A","界限清楚"],["B","三角形骨膜反应"],["C","骨皮质膨胀变薄"],["D","病灶周围硬化反应骨"]],"B","X线检查对明确骨肿瘤的性质、种类、范围及决定治疗方案均有重要价值，是骨肿瘤重要的检查方法。恶性骨肿瘤X线可见虫蛀样或筛孔样、密度不均、界限不清的骨质破坏。恶性骨肿瘤生长快，可将骨膜掀起，骨膜下可产生新骨，出现骨膜反应。三角形的骨膜反应（B对）阴影称Codman三角，提示肿瘤为恶性，多见于骨肉瘤。良性肿瘤一般生长缓慢不累及骨膜，与正常组织界限清楚（A错）骨皮质多保持完好或膨胀变薄（C错），不侵犯周围正常组织，病灶周围可有硬化反应骨（D错）。","","N"],["2007-N104",49,"第一节 骨盆骨折","骨盆骨折合并症",2007,104,"A","","男性，22岁，车祸致骨盆骨折，不会发生的并发损伤是",[["A","直肠损伤"],["B","膀胱损伤"],["C","脊髓损伤"],["D","坐骨神经损伤"]],"C","由于成人脊髓和椎管的长度不一致，脊髓各个节段与相应椎骨的高度并不完全对应。脊髓由延髓下行自C₁-L₁节为脊髓，其末端为圆锥，大约终止于L₁，其下为马尾，故骨盆骨折不会损伤脊髓（C错，为本题正确答案）。坐骨神经由L₄-₅和S₁-₃组成。骨盆为腹腔下方的骨性支持结构，围绕的空间构成盆腔，内有直肠、膀胱，闭孔处穿行过向下肢的神经，故当骨盆损伤时，骨折断端可损伤周围软组织，可导致直肠损伤（A对）、膀胱损伤（B对）、坐骨神经损伤（D对）。强大的剪切力还可导致后尿道断裂。","","N"],["2007-N105",54,"第一节 化脓性骨髓炎","急性化脓性骨髓炎临床表现",2007,105,"A","","下列关于急性骨髓炎临床表现的叙述，错误的是",[["A","高热"],["B","无明显压痛区"],["C","干骺端疼痛剧烈"],["D","白细胞计数和中性粒细胞增高"]],"B","急性血源性骨髓炎好发于儿童，多为血源性感染，由于干骺端血液循环丰富，故好发于干骺端。早期便有严重的全身症状，起病急骤，寒战后高热，可达39℃以上（A对），有明显毒血症症状，因此白细胞计数和中性粒细胞增高（D对）。病人早期即有患区（干骺端）疼痛（C对），局部皮温增高，有局限性压痛（B错，为本题正确答案）。","","N"],["2007-N106",44,"第一节 骨折的定义、成因、分类及移位","横形骨折",2007,106,"A","","下列骨折中，属稳定骨折的是",[["A","粉碎骨折"],["B","螺旋骨折"],["C","横形骨折"],["D","斜形骨折"]],"C","横行骨折（C对）骨折线与骨干纵轴接近垂直，在生理外力作用下骨折端不易发生侧方移位，为稳定性骨折。粉碎骨折（A错）则无法承受应力，属于不稳定骨折。螺旋骨折（B错）和斜行骨折（D错）受到的应力会分解向不同的方向，易引起骨折处的移位，属于不稳定骨折。","","N"],["2007-N125",19,"第三节 气胸","张力性气胸",2007,125,"B","","张力性气胸常见的呼吸状态表现是",[["A","胸壁反常呼吸"],["B","呼吸时纵隔扑动"],["C","气促胸闷、咯血"],["D","极度呼吸困难、发绀"]],"D","张力性气胸为气管、支气管或肺损伤处形成活瓣，气体随每次吸入进入胸膜腔并积累增多，导致胸膜腔压力高于大气压，又称为高压性气胸。病人表现为严重或极度呼吸困难、烦躁、意识障碍、大汗淋漓、发绀（D对）。胸壁反常呼吸（A错）为多根多处肋骨骨折的表现。呼吸时纵隔扑动（B错）为开放性气胸的表现。气促胸闷、咯血（C错）为肺栓塞的表现。","","N"],["2007-N126",19,"第二节 肋骨骨折","肋骨骨折临床表现",2007,126,"B","","多发肋骨骨折的表现是",[["A","胸壁反常呼吸"],["B","呼吸时纵隔扑动"],["C","气促胸闷、咯血"],["D","极度呼吸困难、发绀"]],"A","多发肋骨骨折可使局部胸壁失去完整肋骨支撑而软化，出现反常呼吸运动（A对），即吸气时软化区胸壁内陷，呼气时外突，称为连枷胸。连枷胸的反常呼吸运动可使伤侧肺受到塌陷胸壁的压迫，呼吸时两侧胸腔压力的不均衡造成纵隔扑动（B对），影响肺通气。气促胸闷、咯血（C错）为肺栓塞的表现。极度呼吸困难、发绀（D错）为张力性气胸的表现。故本题的答案应为AB，原参考答案为A。","","N"],["2007-N127",47,"第二节 股骨近端骨折","股骨头下骨折",2007,127,"B","","骨折最不容易愈合的是",[["A","股骨头下骨折"],["B","经股骨颈骨折"],["C","股骨颈基底骨折"],["D","股骨转子间骨折"]],"A","成人股骨头的血液供应有多种来源：①股骨头圆韧带内的小凹动脉，提供股骨头凹部的血液循环；②股骨干滋养动脉升支，沿股骨颈进入股骨头；③旋股内、外侧动脉的分支，是股骨头、颈的重要营养动脉。股骨颈头下型骨折（A对）的骨折线位于股骨头下，可损伤旋股内侧动脉，此时股骨头仅有小凹动脉很少量的供血，致使股骨头严重缺血，故发生股骨头缺血坏死的机会很大。常考的易发生缺血性骨坏死或不易愈合的骨折包括：胫骨中下1/3段骨折、股骨颈头下型骨折、手部腕舟骨骨折等。","","N"],["2007-N128",47,"第二节 股骨近端骨折","股骨转子间骨折临床表现和诊断",2007,128,"B","","外旋畸形﹥90°的可能是",[["A","股骨头下骨折"],["B","经股骨颈骨折"],["C","股骨颈基底骨折"],["D","股骨转子间骨折"]],"D","股骨头下骨折（A错）、经股骨颈骨折（B错）、股骨颈基底骨折（C错）均为关节囊内骨折，可出现下肢外旋畸形，一般在45°～60°之间。股骨转子间骨折（D对）为关节囊外骨折，骨折远端失去了关节囊约束，下肢外旋可达到甚至超过90°。","","N"],["2007-N147",23,"第二节 腹股沟疝","嵌顿性和绞窄性疝的处理原则",2007,147,"X","","下列选项中，不需行修补术的腹股沟疝有",[["A","婴幼儿疝"],["B","嵌顿性疝"],["C","绞窄性疝"],["D","直疝"]],"AC","婴幼儿的腹肌在发育中可逐渐强壮而使腹壁加强，单纯疝囊高位结扎常能获得满意疗效，因此，婴幼儿疝（A对）不需施行修补术。绞窄性疝（C对）因肠坏死而局部有严重感染，常使修补失败，因此，早期通常采取高位结扎，腹壁的缺损应在以后择期解决。成年腹股沟疝的病人都存在程度不同的腹股沟管前壁或后壁的薄弱或缺损，单纯疝囊高位结扎术不足以预防腹股沟疝的复发，只有在疝囊高位结扎后，加强或修补薄弱的腹股沟管前壁或后壁，才有可能得到彻底治疗。因此，嵌顿性疝（B错）和直疝（D错）均需要进行修补术。","","N"],["2007-N148",25,"第一节 急性弥漫性腹膜炎","腹痛",2007,148,"X","","急性化脓性腹膜炎腹痛的特点有",[["A","剧烈、持续性"],["B","阵发性全腹痛"],["C","改变体位时疼痛加剧"],["D","原发病变部位显著"]],"ACD","腹痛是腹膜炎最主要的临床表现。疼痛的程度与发病的原因、炎症的轻重、年龄、身体素质等有关。急性化脓性腹膜炎的疼痛一般都很剧烈，难以忍受，呈持续性（A对B错）。深呼吸、咳嗽、转动身体时疼痛加剧（C对）。病人多不愿改变体位。疼痛先从原发病变部位开始，随炎症扩散而延及全腹，而以原发病变部位为著（D对）。","","N"],["2007-N149",36,"第三节 泌尿、男生殖系统外科疾病的症状学","血尿",2007,149,"X","","下列关于血尿的叙述，正确的有",[["A","尿液呈红色即是血尿"],["B","一般在1000ml尿中含1ml血液即呈肉眼血尿"],["C","离心尿每个高倍镜视野中红细胞﹥3个即有病理意义"],["D","血尿程度与疾病严重性成正比"]],"BC","尿液呈红色并不一定是血尿（A错），可能由食用带色素的食物（辣椒、甜菜、人工色素）、药物（利福平、四环素）等引起。一般在1000mL尿中含1ml血液即呈肉眼血尿（B对）。一些血尿的发生会因为出血量过少而用肉眼无法发现，故将尿液离心观察沉渣，当每个高倍镜视野中红细胞＞3个即有病理意义（C对）。血尿对于泌尿系统是一个十分重要的临床表现，但是血尿程度与疾病严重性不成正比（D错），例如：尿路结石可能出现血尿，但是若结石排出往往预后很好；但无痛性肉眼血尿甚至仅为镜下血尿，若病人为泌尿道肿瘤患者，则疾病严重得多。","","N"],["2007-N150",56,"第三节 类风湿关节炎","类风湿关节炎概述",2007,150,"X","","下列关于类风湿性关节炎的叙述，正确的有",[["A","是一种非特异性炎症"],["B","多发于20～45岁女性"],["C","受累关节多为双侧对称性"],["D","多数患者类风湿因子阳性"]],"ABCD","类风湿性关节炎是一种非特异性炎症（A对），表现为多发性慢性关节炎，受累关节多为双侧对称性（C对），多发于20～45岁女性（B对）。其基本病理变化为关节滑膜的慢性炎症。早期滑膜充血、水肿，单核细胞、淋巴细胞浸润；滑膜边缘部分增生形成肉芽组织血管翳，并逐渐覆盖于关节软骨表面，软骨下骨，使骨小梁减少，骨质疏松。后期关节面间肉芽组织逐渐纤维化，形成纤维性关节僵直，进一步影响关节功能。多数患者（大约70%～80%）类风湿因子阳性（D对）。","","N"],["2007-N153-L",10,"第三节 全身麻醉","肌肉松弛药",2007,153,"A","C","下列关于肌松药的叙述，正确的是",[["A","只能使骨骼肌麻痹"],["B","有部分麻醉作用"],["C","有轻度使病人感觉消失作用"],["D","体温降低不能延长该药物的肌松作用"]],"A","手术时麻醉过深可能有导致死亡的危险，正常剂量的麻醉药物有时会出现病人已麻醉但是肌肉未完全松弛，不利于手术的进行，此时应用肌松药可以迅速松弛肌肉。需注意，肌松药仅有松弛骨骼肌的作用（A对），没有麻醉效能（B错），亦不能使病人神志和感觉丧失（C错）。肌松药能使得呼吸肌麻痹，故严禁将肌松药用于未麻醉、无呼吸机辅助呼吸的病人。体温降低有减慢新陈代谢，延长肌松药的作用（D错），因此在术中要密切观察，注意调整用量。","","N"],["2007-N154-L",20,"第三节 肺肿瘤","肺癌病因",2007,154,"A","C","下列关于肺癌发病的叙述，错误的是",[["A","肺癌发病率是男性肿瘤的首位"],["B","女性肺癌发病率明显增加"],["C","长期大量吸烟者周围型肺癌发病率高"],["D","城市比农村发病率高"]],"C","近50年来，全世界肺癌的发病率明显增高，在我国大城市中，肺癌的发病率已居男性各种肿瘤的首位（A对）。肺癌多发于男性，男女之比约3～5︰1，但近年来，女性肺癌的发病率也明显增加（B对）。由于城市大气污染较重，因此发病率高于农村（D对）。肺癌的病因至今未明。大量资料表明，长期大量吸烟是肺癌的一个重要致病因素。多年每日吸烟40支以上者、肺鳞癌和小细胞肺癌的发病率比不吸烟者高4～10倍。肺鳞癌和小细胞肺癌均以中央型多见，故长期大量吸烟者中央型肺癌发病率高（C错，为本题正确答案）。","","N"],["2007-N155-L",21,"第一节 食管癌","食管癌病理",2007,155,"A","C","食管癌最多见的发病部位是",[["A","颈段"],["B","胸部上段"],["C","胸部中段"],["D","胸部下段"]],"C","临床上采用国际抗癌联盟食管分段标准：①颈段：自食管入口（环状软骨水平）至胸廓入口处（胸骨上切迹下缘）；②胸段：又分为上、中、下三段。胸上段从胸骨切迹至奇静脉弓下缘；胸中段从奇静脉弓下缘至下肺静脉下缘，胸下段从下肺静脉下缘至食管裂孔上缘；③腹段：为食管裂孔至贲门。胸中段食管癌较多见（C对），下段次之，上段较少。","","N"],["2007-N156-L",3,"第一节 外科休克概述","一般监测",2007,156,"A","C","下列关于休克一般监测的叙述，错误的是",[["A","血压是反映休克程度最敏感的指标"],["B","休克指数﹥2.0提示有严重休克存在"],["C","轻压指甲，局部缺血苍白，松压后转为正常，表明末梢循环已恢复"],["D","血压正常、尿量少、比重低时提示有急性肾衰竭可能"]],"A","血压下降是休克的典型表现之一，但是，在休克早期，由于机体的代偿作用（交感-肾上腺轴兴奋导致大量儿茶酚胺释放，以及肾素-血管紧张素分泌增加等环节，可引起心跳加快，心排出量增加以维持循环容量相对稳定；选择性收缩外周和内脏的小血管使循环血量重新分布，保证心、脑等重要器官的有效灌注），造成了血压虽无明显下降，但实际上休克已经存在的现象，故血压并非反映休克程度最敏感的指标（A错，为本题正确答案）。常用脉率/收缩压（mmHg）计算休克指数，指数为0.5多提示无休克；﹥1.0～1.5提示有休克；﹥2.0为严重休克（B对）。皮肤温度色泽是体表灌流情况的标志，如轻压指甲，局部暂时缺血呈苍白，松压后色泽迅速转为正常，则表明末梢循环已恢复、休克好转（C对）。休克恢复后，血压正常，尿量一般正常，若血压正常但尿量少且比重偏低者，提示有急性肾衰竭可能（D对）。","","N"],["2007-N157-L",17,"第一节 甲状腺疾病","喉上神经损伤",2007,157,"A","C","女性，30岁，行甲状腺大部切除术后，出现饮水时呛咳，声音无改变，可能的原因是",[["A","喉返神经损伤"],["B","气管损伤"],["C","喉上神经损伤"],["D","交感神经损伤"]],"C","喉上神经来自迷走神经，分为内支（感觉支）分布在喉黏膜上，外支（运动支）与甲状腺上动脉贴近、同行，支配环甲肌，使声带紧张，喉返神经支配除环甲肌以外的全部喉肌。年轻女性患者甲状腺大部切除术后出现饮水呛咳，考虑喉上神经内支（C对）损伤，导致喉部黏膜感觉丧失，饮水时容易出现误咽呛咳。喉返神经损伤（A错），导致除环甲肌以外全部喉肌的瘫痪，一侧喉返神经损伤，可引起声嘶，双侧喉返神经损伤，可导致失音或严重的呼吸困难，甚至窒息。气管损伤（B错）可表现为呼吸困难，但不会引起饮水呛咳。交感神经损伤（D错）在甲状腺大部切除术罕见，系因颈交感神经节位置较深，不易受到损伤。","","N"],["2007-N158-L",25,"第一节 急性弥漫性腹膜炎","急性弥漫性腹膜炎腹部体征",2007,158,"A","C","急性化脓性腹膜炎时的腹部标志性体征是",[["A","腹式呼吸减弱或消失"],["B","腹部压痛、腹肌紧张和反跳痛"],["C","腹胀"],["D","肠鸣音减弱或消失"]],"B","腹部压痛、腹肌紧张和反跳痛是腹膜炎的标志性体征，尤以原发病灶所在部位最为明显（B对）。急性化脓性腹膜炎的腹部体征包括腹胀、腹式呼吸减弱或消失，但不属于标志性体征（A错）。腹胀加重是病情恶化的一项重要指标（C错）。急性化脓性腹膜炎听诊时肠鸣音减弱或消失，但不属于标志性体征（D错）。","","N"],["2007-N159-L",23,"第二节 腹股沟疝","腹股沟疝发病机制",2007,159,"A","C","下列关于腹股沟疝的叙述，错误的是",[["A","斜疝发病率占腹股沟疝的85%～95%"],["B","左侧斜疝较少是因左侧睾丸下降早"],["C","后天性斜疝的发生常与潜在的先天性解剖异常有关"],["D","滑疝常有消化不良和便秘的症状"]],"C","腹股沟斜疝是最多见的腹外疝，发病率约占全部腹外疝的75%～90%或占腹股沟疝的85%～95%（A 对）。由于左侧睾丸较右侧睾丸下降早，鞘突闭锁也相对较早，因此左侧斜疝较右侧少（B对）。滑疝因疝内容物不能完全还纳，影响肠道蠕动以及肠内容物下行，可引起消化不良以及便秘的症状（D对）。腹股沟斜疝有先天性疝和后天性疝的区别。后天性斜疝常与后天性腹壁薄弱与缺损有关（C错，为本题正确答案）。此题不严谨，单纯把后天性斜疝归结为后天因素，也并非完全正确，某些潜在的先天的发育不全也是发病因素之一，如腹内斜肌弓状下缘发育不全或位置偏高对发病也起着重要作用。","","N"],["2007-N160-L",37,"第四节 男性生殖器官先天性畸形","隐睾症",2007,160,"A","C","患儿一岁半，右侧阴囊空虚，于右腹股沟处可触到蚕豆大包块，诊为右侧隐睾。目前最恰当的处理是",[["A","观察，等待自行下降"],["B","短期应用绒毛膜促性腺激素"],["C","行睾丸固定术"],["D","行睾丸切除术"]],"B","观察，等待自行下降（A错）适用于一岁以内的睾丸未降患者。若一岁以后睾丸仍未下降，可短期应用绒毛膜促性腺激素（B对）每周肌注2次，每次500U，总剂量为5000～10000U。2岁以前睾丸仍未降，则考虑行睾丸固定术（C错）将其拉下。若未降睾丸已发生萎缩，且不能被拉下并置入阴囊，而对侧睾丸正常，则行睾丸切除术（D错），防止在腹腔内的睾丸日后发生癌变。","","N"],["2007-N161-L",39,"","",2007,161,"A","C","肾结核的血尿特点是",[["A","多为终末血尿"],["B","多为全程无痛肉眼血尿"],["C","伴肾绞痛"],["D","与膀胱刺激症状同时发生"]],"A","肾结核的典型症状包括尿路刺激征和血尿。其中，血尿常于尿频、尿痛后发生（D错），多数表现为终末性血尿，其原因是膀胱内结核性溃疡于膀胱收缩时出血所致（A对）。全程无痛肉眼血尿（B错）需要警惕泌尿系统肿瘤的可能。肾绞痛多发生于输尿管结石病人，肾结核一般不伴有肾绞痛（C错），仅少数病变破坏严重的肾结核，可发生结核性脓肾或输尿管堵塞，引起腰部钝痛或绞痛。","","N"],["2007-N162-L",44,"第三节 骨折的并发症","骨筋膜隔室综合征",2007,162,"A","C","骨筋膜室综合征多见于",[["A","腰部"],["B","上臂"],["C","大腿"],["D","小腿"]],"D","骨筋膜室综合征，即由骨、骨间膜、肌间隔和深筋膜形成的骨筋膜室内的肌肉和神经因急性缺血而产生的一系列早期症状和体征。最多见于前臂掌侧和小腿（D对），常由创伤骨折的血肿和组织水肿使筋膜室内容物体积增大或外包扎过紧，局部压迫使筋膜室容积减小而筋膜室内压力增高所致，引起远端缺血坏死。","","N"],["2007-N163-L",50,"第二节 上肢神经损伤","正中神经损伤",2007,163,"A","C","下列选项中，损伤与畸形不对应的是",[["A","尺神经损伤—爪形手畸形"],["B","正中神经损伤—垂腕畸形"],["C","Colles骨折—“银叉”畸形"],["D","肩关节脱位—方肩畸形"]],"B","尺神经损伤后，环、小指屈肌瘫痪，而伸肌功能正常，产生掌指关节的过伸畸形，称为爪形手畸形（A对）。垂腕畸形由桡神经肘上损伤导致，因为伸腕、伸指肌麻痹，腕关节不能主动伸直（B错，为本题正确答案）。正中神经损伤Colles骨折即桡骨远端伸直型骨折，发生于桡骨远端骨松质，并向背侧移位的骨折，伤后局部疼痛、肿胀，可出现典型畸形姿势，即侧面观呈“银叉”样（C对），正面观呈“枪刺”样。肩关节脱位时，正面观病人，发现患肩失去正常饱满圆钝的外形，呈“方肩”畸形（D对）；腋神经损伤亦可见“方肩”畸形。","","N"],["2007-N164-L",50,"第三节 下肢神经损伤","股神经损伤",2007,164,"A","C","男性，38岁，左腹股沟区发现4cm×6cm大小肿物，行肿物切除术后感大腿前部麻木，2周后站立或行走时感膝关节伸直障碍，考虑为",[["A","缝匠肌断裂"],["B","闭孔神经损伤"],["C","股神经损伤"],["D","坐骨神经损伤"]],"C","病人为腹股沟区肿物手术摘除病人，术后出现大腿前部麻木，2周后出现膝关节伸直障碍，诊断考虑股神经损伤（C对）。股神经自盆腔向下经过股管，腹股沟区手术可能损伤股神经，股神经损伤导致其支配的大腿前部皮肤感觉功能障碍，出现麻木感，此外其支配的股四头肌功能亦受影响，故出现站立行走时的膝关节伸直障碍。缝匠肌断裂（A错）不会引起麻木，伸膝关节的主要肌群为股四头肌，缝匠肌仅起一定的辅助作用，断裂对伸膝功能影响不严重。闭孔神经和坐骨神经位于大腿后方、臀部深面，而腹股沟区手术切口位于大腿前方腹股沟区，一般不会导致闭孔神经损伤（B错）及坐骨神经损伤（D错）。","","N"],["2007-N165-L",53,"第二节 腰椎退行性疾病","腰椎间盘突出症诊断",2007,165,"A","C","男性，26岁，2天前弯腰持重时感腰痛，后遂感疼痛向右下肢放射，行走时右下肢麻木。最可能的诊断是",[["A","腰扭伤"],["B","横突骨折"],["C","腰间盘突出"],["D","梨状肌出口综合征"]],"C","26岁男性患者，弯腰持重时感腰痛（腰椎间盘突出症的常见诱发因素），右下肢放射，行走时右下肢麻木（腰椎间盘突出症的常见临床表现）。综合该患者的病史及体征，诊断考虑腰椎间盘突出（C对）。腰扭伤（A错）一般不损伤神经，仅表现为腰部疼痛而不会有放射痛。横突骨折（B错）也是以疼痛为主要表现，由于成人腰部神经根主要在椎间孔穿出而不在横突，故也不会出现放射痛。梨状肌出口综合征（十版外科学P726）（D错）为坐骨神经在臀部受到卡压的一种综合征，主要表现为坐骨神经痛，疼痛从臀部经大腿后方向小腿和足部放射，可有轻度跛行，但一般不出现明显腰痛。","","N"],["2007-N179-L",18,"第四节 乳腺癌","乳腺癌诊断",2007,179,"A","C","女性，35岁，产后哺乳期，右乳红肿，1周来已扩展至全乳，体温36.8℃。右乳皮肤红肿、边界不清、乳房发硬、无压痛，未触到肿物，无波动感，右腋下触及直径约1cm大小的肿大淋巴结，尚活动、无压痛。初步诊断是",[["A","乳汁淤积"],["B","急性乳腺炎"],["C","浆细胞性乳腺炎"],["D","炎性乳癌"]],"D","炎性乳癌（D对）的特点是发展迅速、预后差，局部皮肤呈炎症样表现，迅速扩散到乳房大部分皮肤，皮肤发红、水肿、增厚、粗糙、表面温度升高，由于其发展迅速，易出现淋巴结转移，与题目相符。乳汁淤积（A错）主要的表现是乳房胀痛，但是无红肿表现，是哺乳期较常见的现象，婴儿的吮吸即可缓解；急性乳腺炎（B错）多由于乳汁淤积后的细菌感染所致，为化脓性感染性疾病，感染局部红肿热痛，位置较深者则只有深压痛，形成脓肿时可及波动感，均有发热、血象升高等全身症状，与该患者不符；浆细胞性乳腺炎（C错）是乳腺组织的无菌性炎症，主要症状除了乳头浆液性溢液，主要是在乳头或乳晕旁肿块，边界不清，可有局部红肿痛、皮肤粘连、乳头回缩以及腋淋巴结肿大等现象，易与乳腺癌混淆，但其并非全乳病变，病情发展也较慢。","c7","N"],["2007-N180-L",18,"第四节 乳腺癌","乳腺癌放射治疗",2007,180,"A","C","女性，35岁，产后哺乳期，右乳红肿，1周来已扩展至全乳，体温36．8℃。右乳皮肤红肿、边界不清、乳房发硬、无压痛，未触到肿物，无波动感，右腋下触及直径约1cm大小的肿大淋巴结，尚活动、无压痛。该病人明确诊断后，应采取的最恰当治疗是",[["A","应用抗生素"],["B","终止哺乳，理疗"],["C","手术"],["D","放疗，化疗"]],"D","炎性乳癌是乳腺癌的一种特殊类型，该肿瘤生长迅速，发展快，恶性程度高，预后差，治疗主要采用放疗及化疗，一般不做手术治疗（D对）。","c7","N"],["2008-N57",28,"第二节 急性阑尾炎","右下腹压痛",2008,57,"A","","患者，男，45岁。4小时前感上腹部胀痛伴恶心，呕吐一次为胃内容物，1小时以来右侧腹痛，有便意但未能排便，疑似急性阑尾炎。下列体征中，对确诊最有价值的是",[["A","体温37.8℃"],["B","McBurney点压痛"],["C","腰大肌征阳性"],["D","Rovsing征阳性"]],"B","患者疑似急性阑尾炎，McBurney点压痛对确诊最有价值（B对），因为右下腹压痛是急性阑尾炎最常见的重要体征，而且压痛点通常位于麦氏点，即McBurney点。体温37.8℃（A错）可发生于诸多疾病，不具有特异性。腰大肌征阳性（C错）提示炎症阑尾可能位于腰大肌前方，盲肠后位或腹膜后位，是急性阑尾炎的辅助诊断的体征但对确诊不是最有价值的体征。Rovsing征阳性（D错）即结肠充气试验阳性，是急性阑尾炎的辅助诊断的体征，但对确诊不是最有价值的体征。","","N"],["2008-N77",10,"第三节 全身麻醉","全身麻醉深度的判断",2008,77,"A","","施行腹部手术时，全身麻醉深度应为",[["A","Ⅱ期"],["B","Ⅲ期一级"],["C","Ⅲ期二级"],["D","Ⅲ期三级"]],"C","全身（乙醚）麻醉深度的分期标准可分为四期。（1）第Ⅰ期（镇痛期）指从麻醉诱导开始到病人意识消失。此时大脑皮层逐渐受到抑制，意识逐渐丧失，痛觉减退，呼吸和心率稍增快，其他反射仍存在。此期不宜手术；（2）第Ⅱ期（兴奋期）（A错）指大脑皮层受到抑制，皮层下中枢失去控制，临床表现为兴奋状态，如呼吸紊乱、血压和心率波动。最后出现深而有节律的呼吸。此期禁止任何手术；（3）第Ⅲ期（手术麻醉期）指皮层下中枢被抑制，兴奋状态消失，痛觉消失。此期适宜手术，分为4级。第一级（B错）：呼吸规律，频率稍快；眼睑反射消失，眼球活动减少；但肌肉不松弛。可施行一般手术；第二级（C对）：眼球固定中央，瞳孔不大；呼吸频率稍慢，但幅度无明显改变；肌张力逐渐减弱。可施行腹部手术；第三级（D错）：瞳孔开始散大；胸式呼吸减弱，腹式呼吸增强；血压下降，肌松弛。可施行刺激强度大的手术及操作；第四级：肌完全松弛，呼吸逐渐停止，循环显著抑制。应立即施行人工呼吸，减浅麻醉；（4）第Ⅳ期（延髓麻醉期）指呼吸停止，血压测不到，瞳孔散大。如不及时抢救可导致心脏停搏。","","N"],["2008-N78",5,"第二节 浅部组织细菌性感染","丹毒预防和治疗",2008,78,"A","","下列感染性疾病中，创面不需做清创引流的是",[["A","气性坏疽"],["B","急性丹毒"],["C","破伤风"],["D","急性皮下蜂窝织炎"]],"B","丹毒为皮肤和黏膜网状淋巴管的急性炎症，特点是蔓延很快，很少有组织坏死或化脓，伴有全身反应。淋巴管炎无法进行清创，治疗上除了休息、抬高患肢、局部皮肤硫酸镁热敷或3%碘酊涂擦外，需全身应用磺胺药或青霉素，并在全身和局部症状消失后继续应用3～5天，以免再发（B对）。气性坏疽又称梭状芽胞杆菌性肌坏死，是由梭状芽胞杆菌引起的特异性感染，致病菌产生的外毒素可以引起严重毒血症及肌肉组织的广泛坏死，临床特点是病情急剧恶化，甚至出现溶血性贫血、黄疸、血红蛋白尿等全身症状并迅速恶化，故需尽早治疗，早期急诊清创（A错）。由于破伤风是厌氧菌，其生长繁殖必须有缺氧的环境，治疗上应彻底清创、积极注射抗毒血清、充分敞开伤口引流（C错）。蜂窝织炎为非特异性感染，主要由溶血性链球菌、金葡菌等引起，治疗主要是注意休息，采用热敷、理疗，应用磺胺药或广谱抗生素，多处切开引流更利于缓解皮下炎症的扩散和减少皮肤坏死（D错）；需注意口底及颌下的急性蜂窝织炎，可发生喉头水肿和压迫气管，引起呼吸困难，甚至窒息，应及早切开减压，以防止上述急症。","","N"],["2008-N79",2,"第一节 输血的适应证和注意事项","大量失血",2008,79,"A","","近些年来提倡成分输血，不输全血。下列选项中，适合输入适量全血的情况是",[["A","失血量超过总血容量的30%"],["B","恶性肿瘤并发贫血"],["C","重症感染时"],["D","慢性失血所致贫血"]],"A","输血作为一种替代性治疗，可以补充血容量、改善循环、增加携氧能力，提高血浆蛋白，增进机体免疫力和凝血功能。近些年来提倡成分输血，不输全血。输血的主要适应证是大量失血，失血量少于总血容量的30%时，不输全血，可输晶体和胶体来补充血容量。失血量超过总血容量的30%时，可输入适量全血（A对）。重症感染时（C错），可考虑输注浓缩粒细胞，以提高机体抵抗能力，从而控制感染。恶性肿瘤并发贫血（B错）和慢性失血所致贫血（D错）都不是全血成分的减少，应以补充浓缩红细胞为主。","","N"],["2008-N80",7,"第一节 热力烧伤","Ⅲ度烧伤",2008,80,"A","","深度达皮下组织的烧伤是",[["A","Ⅰ度烧伤"],["B","浅Ⅱ度烧伤"],["C","深Ⅱ度烧伤"],["D","Ⅲ度烧伤"]],"D","皮肤分为表皮层，真皮层和皮下组织。表皮层（二版八年制组织学与胚胎学P161）位于皮肤浅层，由外到内依次是角质层、透明层、颗粒层、棘层、基底层（生发层）。真皮层（二版八年制组织学与胚胎学P164）位于表皮下，由外到内分为乳头层和网织层。皮下组织（二版八年制组织学与胚胎学P165）位于真皮下方，由疏松结缔组织和脂肪组织组成。Ⅰ°烧伤：仅伤及表皮浅层（A错）。浅Ⅱ°烧伤：伤及表皮的生发层和真皮乳头层（B错）。深Ⅱ°烧伤：伤及真皮乳头层以下，但仍残留部分网状层，还未累及皮下组织（C错）。Ⅲ°烧伤为皮肤全层烧伤，并累及皮下组织（D对）乃至深部的组织，属于皮肤烧伤中最严重的一种。","","N"],["2008-N81",23,"第二节 腹股沟疝","无张力疝修补术",2008,81,"A","","下列选项中，不属于无张力疝成形术优点的是",[["A","适用于某些有腹压增高的患者"],["B","术后下地早，恢复快"],["C","复发率低"],["D","较常规手术不易感染"]],"D","无张力疝修补术是在无张力的情况下，利用人工高分子材料网片进行修补，具有很强的支撑作用，且不牵扯周围组织，不会减少腹腔容积，增大腹压，因此适用于某些有腹内压高的患者（A对）。无张力疝修补术具有术后疼痛轻、恢复快（B对）、复发率低（C对）等优点。但置入的人工高分子材料毕竟属于外来异物，有潜在感染可能，因此，无张力疝修补术较传统的疝修补术更易发生感染（D错，为本题正确答案）。","","N"],["2008-N82",26,"第三节 胃十二指肠溃疡的外科治疗","胃大部切除术与适应证",2008,82,"A","","对顽固的胃溃疡病首选的手术方式是",[["A","胃大部切除术"],["B","迷走神经干切断术"],["C","选择性迷走神经切断术"],["D","高选择性迷走神经切断术"]],"A","胃大部切除术（A对）是治疗胃溃疡的常用术式，此手术切除了含有大量壁细胞和主细胞的远端胃体，降低了胃酸和胃蛋白酶的分泌；切除了胃窦就减少了G细胞分泌的促胃液素，从而降低了胃酸分泌；溃疡好发部位（十二指肠及胃窦小弯处）也被一并切除。迷走神经干切断术（B错）、选择性迷走神经切断术（C错）、高选择性迷走神经切断术（D错）因治疗效果不如胃大部切除术稳定，在临床中已经很少使用，相关知识也从第十版教材中删除。","","N"],["2008-N83",27,"第四节 肠梗阻","肠扭转病因",2008,83,"A","","下列关于肠扭转的叙述，错误的是",[["A","以逆时针扭转者多见"],["B","突然改变体位可诱发"],["C","肠内容物骤增时易发生"],["D","常存在肠管及其系膜解剖异常因素"]],"A","肠扭转是一段肠袢沿其系膜长轴旋转而造成的闭袢性肠梗阻。常常是因为肠袢及其系膜过长，系膜根部附着处过窄或粘连收缩靠拢等解剖异常因素（D对），并因肠内容重量骤增（C对），肠管动力异常，以及突然改变体位（B对）等诱发因素而引起。肠扭转部分在其系膜根部，以顺时针方向旋转多见（A错，为本题正确答案）。","","N"],["2008-N84",26,"第三节 胃十二指肠溃疡的外科治疗","术后肠梗阻",2008,84,"A","","患者，男，35岁。6天前因溃疡病出血行毕Ⅱ式胃大部切除术，2天来上腹胀满，进食后半小时尤甚，常恶心、呕吐，吐出胆汁样液体，量较多，不含食物，呕吐后症状缓解。查体：轻度脱水，上腹略饱满，轻度压痛。最可能的诊断是",[["A","吻合口梗阻"],["B","输入袢梗阻"],["C","输出袢梗阻"],["D","倾倒综合征"]],"B","年轻男性病人，毕Ⅱ式胃大部切除术后，出现腹胀、恶心、呕吐胆汁样液体，不含食物，查体：上腹部饱满，轻度压痛，诊断考虑输入袢梗阻（B对）。胃术后输入袢梗阻，胆汁及胰腺分泌的消化液淤积在十二指肠残端，当腹内压升高时，可有胆汁呕出，因输出袢通畅，食物通过无障碍，因此呕吐物没有食物。吻合口梗阻（A错）时，食物无法通过吻合口，而胆汁可通过输出袢下行，多表现为呕吐食物，不含有胆汁的液体。输出袢梗阻（C错）时，胆汁和食物均无法通过输出袢下行，呕吐物既有胆汁，又有食物。倾倒综合征（D错）包括早期倾倒综合征和晚期倾倒综合征。早期倾倒综合征多发生在进食后半小时，表现为心悸、出冷汗面色苍白等血容量不足的表现，可能与高渗性胃内容物过快进入肠腔导致肠道内分泌细胞大量分泌血管活性物质有关；晚期倾倒综合征发生在进食后2～4小时，主要表现为低血糖综合征，可能与食物进入肠道后刺激胰岛素大量分泌，导致反应性低血糖。","","N"],["2008-N85",29,"第十节 肛周脓肿","肛周脓肿诊断",2008,85,"A","","患者，男，32岁。1周来发热伴会阴部疼痛，逐渐加重，大便有里急后重感，且排尿困难，直肠指诊因疼痛不合作未能进行，白细胞17．5×10⁹/L。最可能的诊断是",[["A","急性膀胱炎"],["B","肛旁脓肿"],["C","血栓性外痔"],["D","坐骨直肠窝脓肿"]],"D","青年男性患者，会阴部疼痛，大便里急后重且有排尿困难，直肠指诊因疼痛不能合作未进行（肛周脓肿的常见局部症状），发热一周，白细胞17.5×10⁹/L（全身感染中毒症状，考虑为深部感染），诊断考虑坐骨直肠窝脓肿（D对）。肛旁脓肿（十版外科学P430）（B错）即肛周皮下脓肿，主要症状是肛周持续性胀痛，排便、咳嗽、下坐或受压时疼痛加重，行走不便，而发热、白细胞升高等全身症状轻。急性膀胱炎（十版外科学P542）（A错）为泌尿系统感染性疾病，以尿频、尿急、尿痛、尿道烧灼感为主，与病人症状不符。血栓性外痔（十版外科学P436））（C错）表现为肛周暗紫色长条圆形肿物，表面皮肤水肿、质硬、压痛明显，一般无排尿困难，为血栓性静脉炎的一种表现。","","N"],["2008-N86",27,"第四节 肠梗阻","绞窄性肠梗阻",2008,86,"A","","患者，女，34岁。阵发性腹痛伴呕吐3天，腹胀并停止排气排便2天，1天来腹痛加剧，疼痛变为持续性，2年前因阑尾穿孔行阑尾切除术。查体：右侧腹部稍膨隆，右下腹有明显压痛，轻度肌紧张，肠鸣音减弱，偶闻气过水声。可能的诊断是",[["A","内疝致绞窄性肠梗阻"],["B","粘连性不全性肠梗阻"],["C","麻痹性肠梗阻"],["D","阑尾残株炎"]],"A","病人虽有既往手术史，有造成粘连性肠梗阻的潜在可能，但患者腹胀、停止排气排便2天，且症状加重，疼痛变为持续性，也出现右下腹明显压痛和轻度肌紧张，说明已发展为绞窄性肠梗阻（A对），而非粘连性不全性肠梗阻（B错）。麻痹性肠梗阻（C错）患者由于肠壁肌呈瘫痪状态，没有收缩蠕动，肠鸣音减弱或消失，无气过水声，腹胀为均匀性。阑尾残株炎（D错）即阑尾残端炎，是由于阑尾切除时残段保留过长引起，表现与阑尾炎相同的症状，而非肠梗阻症状。","","N"],["2008-N87",30,"","",2008,87,"A","","肝穿刺的绝对禁忌证是",[["A","原发性肝癌"],["B","细菌性肝脓肿"],["C","阿米巴肝脓肿"],["D","肝包虫病"]],"D","B超引导下的肝穿刺组织活检有助于获得原发性肝癌（A错）的病理诊断，对诊断困难或者不适宜手术者，为指导下一步治疗，可做此项检查。对于细菌性肝脓肿（B错）和阿米巴肝脓肿（C错），穿刺抽液不仅用于疾病的诊断及鉴别两者，B超引导下的经皮肝穿刺吸脓或置管引流术还可作为治疗手段用于单个较大的病灶。肝包虫病又称肝棘球蚴病，为人畜共患寄生虫病。人为中间宿主，在肝内形成一巨大囊肿，囊内容物有囊液、育囊、原头节、生发囊和子囊，若囊壁破裂可使囊内容物外溢导致过敏反应，甚至过敏性休克，并且也能在腹腔内播散种植形成新的棘球蚴囊，故肝包虫病（D对）禁止肝穿刺。肝穿刺的禁忌证包括：①肝血管瘤、肝棘球蚴病患者；②有大量腹水患者；③肝外梗阻性黄疸患者；④昏迷、重度贫血或其他疾病不配合者。","","N"],["2008-N88",57,"第三节 骨巨细胞瘤","骨巨细胞瘤概述",2008,88,"A","","下列关于骨巨细胞瘤的叙述，错误的是",[["A","20～40岁年龄段好发"],["B","多见于长骨干骺端"],["C","偏心、溶骨、膨胀生长"],["D","单纯手术刮除易复发"]],"B","骨巨细胞瘤好发于20-40岁（A对），女性略多，好发部位为长骨干骺端（B对）和椎体，特别是股骨远端和胫骨近端，呈偏心、溶骨、膨胀生长（C对），无骨膜反应，病灶膨胀生长、骨皮质变薄，呈肥皂泡样改变。骨巨细胞瘤是一种交界性肿瘤，以手术治疗为主，采用切除术和灭活处理，再植入自体或异体骨或骨水泥，单纯手术刮除易复发（D对）。根据十版外科学观点，本题ABCD均对，无正确答案。","","N"],["2008-N89",47,"第二节 股骨近端骨折","人工关节置换术",2008,89,"A","","患者，女，72岁。股骨颈头下骨折，有移位1天。其最佳治疗方法是",[["A","胫骨结节骨牵引"],["B","闭合复位，穿丁字鞋，卧床休息"],["C","闭合复位，空心螺钉固定"],["D","全髋人工关节置换"]],"D","股骨头下骨折的骨折线位于股骨头下，股骨头仅有小凹动脉很少量的供血，致使股骨头严重缺血，故发生股骨头缺血坏死的机会很大；老年人本身循环较差，代谢率低，在发生股骨颈骨折后自愈的可能性极低。为了避免发生股骨头坏死、行二次手术风险，对于老年人股骨颈头下型骨折，采取全髋人工关节置换术视为优先选择（D对）。胫骨结节骨牵引（A错）及闭合复位，穿丁字鞋，卧床休息（B错）适用于年龄过大，全身情况差，合并有严重的心、肺、肾、肝等功能障碍不能耐受手术的患者。闭合复位，空心螺钉固定（C错）适用于经颈型和基底型股骨颈骨折。","","N"],["2008-N90",44,"第四节 骨折愈合过程","骨折临床愈合标准概述",2008,90,"A","","下列骨折临床愈合标准中，错误的是",[["A","局部无压痛及纵向叩击痛"],["B","局部无异常活动"],["C","X线摄片显示骨折断端塑型良好"],["D","X线摄片显示有连续骨痂通过骨折线"]],"C","骨折愈合包括畸形愈合，故愈合标准中并不包含塑型良好（C错，为本题正确答案）。局部有畸形、塑型差称为畸形愈合，亦属于骨折愈合。记忆技巧：对于骨折愈合标准，可概括为几个字：不痛、不动、看不清、负重不变形。需注意，过去的教材中还有一条标准：解除外固定后，上肢向前平举1kg重量达1分钟；下肢能不扶拐在平地连续步行3分钟，不少于30步，连续观察两周骨折处不变形。由于影像学技术的发展和负重实验本身所具有的一定危险性，负重试验已渐渐淡出临床，但是在老题目中出现相关选项时，仍旧可以作为备选答案。","","N"],["2008-N111",33,"第二节 胰腺炎","急性胰腺炎诊断",2008,111,"A","","患者，女，39岁。因持续上腹痛伴恶心、呕吐3天入院。5年来有胆囊结石病，常有短暂上腹不适症状。B超显示胆囊多发小结石，总胆管宽9mm，其内未见结石，胰腺肿大增厚，周围有积液。查体：体温37.7℃，脉率106次/分，呼吸28次/分，血压132/86mmHg，巩膜不黄，肺无音，上腹压痛，轻度肌紧张和反跳痛，肠鸣音较弱。化验：WBC13.5×10⁹/L，血尿淀粉酶高出正常一倍以上。对该患者最可能的诊断是",[["A","急性胃炎"],["B","胆源性胰腺炎"],["C","急性弥漫性腹膜炎"],["D","急性胆囊炎"]],"B","39岁女性患者，既往有胆囊结石病，常有短暂上腹不适症状（胰腺炎的常见致病危险因素）。持续上腹痛伴恶心、呕吐3天（急性胰腺炎的常见临床表现）。查体：上腹压痛，轻度肌紧张和反跳痛（腹膜炎的典型临床表现），肠鸣音较弱（提示麻痹性肠梗阻可能）。化验：WBC13.5×10⁹/L，血尿淀粉酶高出正常一倍以上（提示胰腺炎可能）。B超示胆囊多发小结石，总胆管宽9mm，其内未见结石，胰腺肿大增厚，周围有积液（急性胰腺炎的典型B超表现）。综合该患者的病史、体征、实验室检查及影像学检查，诊断考虑急性胆源性胰腺炎（B对）。急性胃炎（A错）以腹痛、呕吐为主要表现，但通常无腹膜刺激征，也不会出现胰腺的B超改变。急性弥漫性腹膜炎（十版外科学P364）（C错）则表现为全腹痛，严重的腹膜刺激征，且血、尿淀粉酶不升高。急性胆囊炎（十版外科学P473）（D错）以右上腹疼痛为主要表现，一般不引起腹膜刺激征，血、尿淀粉酶仅为轻度升高。","c15","N"],["2008-N112",33,"第二节 胰腺炎","抗生素的应用",2008,112,"A","","患者，女，39岁。因持续上腹痛伴恶心、呕吐3天入院。5年来有胆囊结石病，常有短暂上腹不适症状。B超显示胆囊多发小结石，总胆管宽9mm，其内未见结石，胰腺肿大增厚，周围有积液。查体：体温37.7℃，脉率106次/分，呼吸28次/分，血压132/86mmHg，巩膜不黄，肺无音，上腹压痛，轻度肌紧张和反跳痛，肠鸣音较弱。化验：WBC13.5×10⁹/L，血尿淀粉酶高出正常一倍以上。对该患者的最佳治疗方案是",[["A","禁食、胃肠减压、补液止痛"],["B","即刻急诊手术引流"],["C","抗感染，体温超过38.5℃则手术引流"],["D","腹腔灌洗"]],"C","目前该患者最佳治疗方案为抗感染，体温超过38.5℃表明腹腔内感染严重，须手术清除坏死组织并作引流术（C对）。禁食、胃肠减压、补液止痛（A错）为急性胰腺炎的一般对症治疗之一。对于急性胰腺炎不主张早期手术治疗（B错）。炎症早期，胰腺组织坏死严重，与周围组织分界不清，手术不仅无法阻止病情进展，反而能造成感染的扩散。腹腔灌洗（D错）可用于治疗弥漫性化脓性腹膜炎，以清除腹腔内脓液，减少粘连。","c15","N"],["2008-N113",42,"第二节 尿路上皮肿瘤","膀胱肿瘤诊断",2008,113,"A","","患者，男，53岁。1周来无诱因终末血尿3次，无发热，无尿频、尿痛等不适。吸烟史20年。胸片示陈旧肺结核，尿镜检有大量红细胞。对该患者最可能的诊断是",[["A","急性肾炎"],["B","膀胱癌"],["C","肾癌"],["D","肾结核"]],"B","53岁男性患者（肿瘤高发人群），吸烟史20年（吸烟为膀胱癌的重要致癌因素之一）。1周来无诱因终末血尿3次，无发热，无尿频、尿痛等不适（提示泌尿系感染可能性较低）。胸片示陈旧肺结核，尿镜检有大量红细胞。综合该患者病史及实验室检查，诊断优先考虑膀胱癌（B对）。位于膀胱颈部、三角区的肿瘤，可因膀胱排空末期膀胱收缩而出血，形成终末血尿。急性肾炎（A错）多急性起病，主要症状包括血尿、蛋白尿、水肿和高血压，可伴一过性氮质血症，近期有链球菌感染史，与该病人表现不相符。肾癌（C错）常见于50～70岁中老年人，为上尿路肿瘤，以间歇全程无痛性血尿为主要表现，与该患者临床表现不符。肾结核（D错）的典型症状包括尿路刺激征和血尿。多数表现为终末性血尿，由膀胱内结核性溃疡于膀胱收缩时出血引起。","c16","N"],["2008-N114",42,"第二节 尿路上皮肿瘤","膀胱镜检查、活检",2008,114,"A","","患者，男，53岁。1周来无诱因终末血尿3次，无发热，无尿频、尿痛等不适。吸烟史20年。胸片示陈旧肺结核，尿镜检有大量红细胞。下列进一步检查项目中，对该患者明确诊断帮助最大的是",[["A","尿细胞学检查"],["B","静脉尿路造影"],["C","尿路B超"],["D","膀胱镜检查"]],"D","膀胱镜检查（D对）是患膀胱癌年龄范围出现血尿病人的重要检查手段。可以直接观察到肿瘤所在部位、大小、数目、形态、有蒂或广基，初步估计基底部浸润等，在发现异常部位时，可取少量组织进行病理活检，具有确诊价值。尿细胞学检查（A错）可发现脱落的肿瘤细胞，可用于病人的初筛，但低级别肿瘤细胞不易与正常移行上皮细胞及炎症或结石引起的变异细胞鉴别。静脉尿路造影（B错）是必须的检查之一，但是其作用并不是诊断膀胱肿瘤的存在，而是了解上尿路有无同时伴发肿瘤。尿路B超（C错）检查是一切血尿病人的首选影像学检查，简便易行，能发现直径0.5cm以上的肿瘤，可作为病人的最初筛选。","c16","N"],["2008-N115",22,"第三节 动脉疾病","血栓闭塞性脉管炎一般疗法",2008,115,"A","","患者，男，38岁。出现下肢麻木、发凉，间歇性跛行8年，有20年吸烟史。近来病情发展，持续疼痛，夜间尤甚，右下肢肌肉萎缩，右足背动脉搏动消失，诊断为血栓闭塞性脉管炎。初诊时最重要的医嘱是",[["A","卧床休息"],["B","使用止痛药"],["C","注意保暖"],["D","立即戒烟"]],"D","血栓性闭塞性脉管炎的治疗原则是防止病变进展，改善和增进下肢血液循环。保守治疗时，最重要的一点是立即戒烟（D对）。（七版黄家驷外科学P1182）尼古丁可使皮肤血管收缩、血流减慢甚至中断。吸烟也可使儿茶酚胺、肾上腺素和去甲肾上腺素血浓度明显升高、血黏度增加、血小板聚集增强。寒冷亦可诱发该病，因而医嘱同样需要注明注意保暖，但不应使用热疗。部分病情较重的患者可卧床休息并酌情使用止痛药。","c17","N"],["2008-N116",22,"第三节 动脉疾病","血栓闭塞性脉管炎诊断",2008,116,"A","","患者，男，38岁。出现下肢麻木、发凉，间歇性跛行8年，有20年吸烟史。近来病情发展，持续疼痛，夜间尤甚，右下肢肌肉萎缩，右足背动脉搏动消失，诊断为血栓闭塞性脉管炎。不考虑该患者为下肢动脉硬化性闭塞的主要依据是",[["A","患者年轻，病史长"],["B","间歇性跛行"],["C","足背动脉搏动消失"],["D","夜间疼痛"]],"A","血栓闭塞性脉管炎和动脉硬化性闭塞症都有下肢供血不足，因而都可有间歇性跛行（B错）、足背动脉搏动消失（C错）以及静息痛/夜间疼痛（D错）。但两者的好发年龄不同，血栓闭塞性脉管炎患者多年轻（A对），动脉硬化性闭塞症多见于45岁以上的中老年人。","c17","N"],["2008-N117",22,"第三节 动脉疾病","血栓闭塞性脉管炎手术治疗",2008,117,"A","","患者，男，38岁。出现下肢麻木、发凉，间歇性跛行8年，有20年吸烟史。近来病情发展，持续疼痛，夜间尤甚，右下肢肌肉萎缩，右足背动脉搏动消失，诊断为血栓闭塞性脉管炎。对该患者最适宜的治疗是",[["A","使用血管扩张剂"],["B","腰交感神经切除术"],["C","截肢术"],["D","溶栓疗法"]],"B","在血栓闭塞性脉管炎的治疗中，使用血管扩张剂（A错）治疗的效果有限，而该患者症状较重。本患者行腰交感神经切除术可以解除血管痉挛从而缓解疼痛，以及促进侧支循环形成，有比较好的近期效果。截肢术（C错）适用于出现下肢的坏疽，溃疡无法愈合，严重危及生命的晚期患者。溶栓疗法（D错）适用于急性血管栓塞早期内的患者，最好在发生栓塞的3天内用药。","c17","N"],["2008-N118",48,"第一节 脊柱骨折","颈椎骨折分类",2008,118,"A","","患者，男，17岁。半小时前因跳马比赛不慎颈部受伤，初步检查：患者可主动做肩前屈、肘屈运动，但不能主动做肘伸运动，双下肢软瘫。该患者损伤部位最可能是位于",[["A","颈3、4"],["B","颈4、5"],["C","颈5、6"],["D","颈6、7"]],"C","脊髓对肌的节段性支配，脊髓对肌的节段性支配，概括来说，C₁-C₄支配颈肌及膈肌，C₅-T₁支配上肢肌，T₂-L₁支配躯干肌，L₂-S₂支配下肢肌，S₃-S₅及尾节主要支配会阴肌，故C₄以上的神经节段损伤不考虑。参与屈肘的肌肉有肱二头肌、肱肌和肱桡肌，均由C₅-C₆神经支配；伸肘的肌肉主要为肱三头肌，由C₆-C₇神经支配。该病人屈肘良好，说明C₅-C₆神经完好；伸肘障碍，说明损伤位于C₇。又由于脊髓和椎管的长度不一致，脊髓各个节段与相应椎骨的高度并不完全对应，脊髓下部颈节（C₅-C₈）和上部胸节对应同序数椎骨序列减1的椎骨。C₆神经对应的脊椎节段是颈5，C₇神经对应的椎体节段水平为颈6，故损伤应发生在颈5、6（C对）之间。","c18","N"],["2008-N119",48,"第二节 脊髓损伤","脊髓损伤治疗原则",2008,119,"A","","患者，男，17岁。半小时前因跳马比赛不慎颈部受伤，初步检查：患者可主动做肩前屈、肘屈运动，但不能主动做肘伸运动，双下肢软瘫。急诊入院后，颈椎X线片未见骨折脱位，最适宜的处理是",[["A","半卧位，减轻腹部对胸腔的压力"],["B","平卧四头带颈部牵引"],["C","气管切开，呼吸机辅助呼吸"],["D","急诊手术探查颈髓损伤程度"]],"B","病人入院急诊X线片未见骨折脱位，说明发生的为无骨折脱位脊髓损伤。该型多发生于儿童及青少年，多因车祸、高处坠落、牵拉等严重损伤，由于脊柱弹性较大，可发生脊髓损伤而无骨折脱位。对于该型脊髓损伤，治疗的主要目的是避免脊髓受到可能发生的二次伤害，故应给予平卧四头带颈部牵引（B对）。病人损伤节段在C₄以下，不会影响膈肌功能，故无需半卧位减轻腹部对胸腔的压力（A错），也无需气管切开辅助呼吸治疗（C错）。病人脊柱无骨折脱位，无需急诊手术探查颈髓损伤程度（D错），此时手术探查可能导致脊髓的二次损伤，不采用。","c18","N"],["2008-N120",48,"第二节 脊髓损伤","呼吸衰竭与呼吸道感染",2008,120,"A","","患者，男，17岁。半小时前因跳马比赛不慎颈部受伤，初步检查：患者可主动做肩前屈、肘屈运动，但不能主动做肘伸运动，双下肢软瘫。患者入院后，出现呼吸道感染，最主要的原因是",[["A","双下肢软瘫"],["B","肋间肌瘫痪"],["C","膈肌瘫痪"],["D","未联合使用抗生素"]],"B","人体存在腹式呼吸和胸式呼吸两种，胸式呼吸主要由肋间肌完成，腹式呼吸主要由膈肌完成。病人出现呼吸道感染，最主要原因是由下颈神经和胸神经支配的肋间肌瘫痪（B对），由于呼吸肌力量不足，呼吸非常费力，使得呼吸道阻力相应增加，分泌物不易排出，久卧者又容易产生坠积性肺炎。双下肢软瘫（A错）导致患者长期卧床，是深静脉血栓和压疮等并发症的主要原因，但与呼吸道感染无关。病人脊髓损伤节段为C₇，不会累及支配膈肌神经，不会导致膈肌瘫痪。无感染征象的患者不需要联合使用抗生素（D错）。","c18","N"],["2008-N145",21,"第一节 食管癌","食管癌病理",2008,145,"B","","较早出现梗阻症状的食管癌是",[["A","硬化型"],["B","髓质型"],["C","蕈伞型"],["D","溃疡型"]],"A","按病理形态，临床上食管癌可分为四型：缩窄型、溃疡型、髓质型、蕈伞型。缩窄型（又称硬化型）瘤体形成明显的环形狭窄，累及食管全部周径，较早出现阻塞症状（A对）。髓质型（B错）：管壁明显增厚并向腔内外扩展，此型恶性程度最高，最常见，出现阻塞较缩窄型晚。蕈伞型（C错）：瘤体向腔内呈蕈伞状突起，出现阻塞晚。溃疡型（D错）：溃疡大小和外形不一，深入肌层，阻塞程度较轻。","","N"],["2008-N146",21,"第一节 食管癌","食管癌病理",2008,146,"B","","阻塞程度较轻的食管癌是",[["A","硬化型"],["B","髓质型"],["C","蕈伞型"],["D","溃疡型"]],"D","按病理形态，临床上食管癌可分为四型：缩窄型（又称硬化型）、溃疡型、髓质型、蕈伞型。溃疡型：溃疡大小和外形不一，深入肌层，阻塞程度较轻（D对）。缩窄型（A错）：瘤体形成明显的环形狭窄，累及食管全部周径，较早出现阻塞症状。髓质型（B错）：管壁明显增厚，多数累及食管周径的全部或绝大部分，此型恶性程度最高，最常见，易出现阻塞。蕈伞型（C错）：瘤体呈卵圆形扁平肿块状，向腔内呈蘑菇样突起，阻塞程度比溃疡型重。","","N"],["2008-N147",33,"第五节 胰腺神经内分泌肿瘤","胰岛素瘤临床表现",2008,147,"B","","胰岛素瘤表现为",[["A","Zollinger-Ellison综合征"],["B","Charcot三联征"],["C","Whipple三联征"],["D","类癌综合征"]],"C","胰岛素瘤是胰岛B细胞组成的肿瘤，因为B细胞分泌胰岛素，大量的胰岛素释放进入血流，引起以低血糖为主的一系列症状，其典型表现为Whipple三联征（C对）： 空腹或运动后出现低血糖症状；症状发生时血糖低于2.8mmol/L；进食或静脉推注葡萄糖可迅速缓解症状，有关Whipple三联征的低血糖数据，十版外科学有更新。Zollinger-Ellison综合征（A错）为胃泌素瘤的典型表现，包括难治性消化性溃疡和腹泻（大量分泌的胃酸导致肠道内各种消化酶的失活，影响肠道内的消化吸收，导致肠腔内渗透压增高引起腹泻）。Charcot三联征（B错）为急性胆管炎的典型表现，包括腹痛、寒战高热、黄疸。有些肿瘤，如小细胞肺癌、髓样癌等，因其能产生降钙素（CT）、前列腺素（PG）、5-羟色胺（5-HT）、肠血管活性肽（VIP）等，病人可有腹泻、面部潮红和多汗等症状，称为类癌综合征（D错）。","","N"],["2008-N148",33,"第五节 胰腺神经内分泌肿瘤","胃泌素瘤临床表现",2008,148,"B","","胃泌素瘤表现为",[["A","Zollinger-Ellison综合征"],["B","Charcot三联征"],["C","Whipple三联征"],["D","类癌综合征"]],"A","胰腺内分泌肿瘤中，胃泌素瘤发病率仅次于胰岛素瘤，典型表现为Zollinger-Ellison综合征（A对），即难治性消化性溃疡及腹泻。Charcot三联征（十版外科学P469）（B错）为急性胆管炎的典型表现，包括腹痛、寒战高热、黄疸。Whipple三联征（十版外科学P496）（C错）为胰岛素瘤的典型表现，包括空腹或运动后出现低血糖症状；症状发生时血糖低于2.2mmol/L；进食或静脉推注葡萄糖可迅速缓解症状。有些肿瘤，如小细胞肺癌、髓样癌等，因其能产生降钙素（CT）、前列腺素（PG）、5-羟色胺（5-HT）、肠血管活性肽（VIP）等，病人可有腹泻、面部潮红和多汗等症状，称为类癌综合征（D错）。","","N"],["2008-N149",50,"第四节 周围神经卡压综合征","肘管综合征应用解剖",2008,149,"B","","肘管综合征卡压的神经是",[["A","正中神经"],["B","尺神经"],["C","坐骨神经"],["D","股神经"]],"B","腕管综合征（十版外科学P696）是正中神经在腕管内受压而表现出的一组症状和体征，表现为拇、示、中指感觉过敏或迟钝，鱼际肌萎缩，拇对掌无力，腕部正中神经Tinel征阳性。肘管综合征（B对）是指尺神经在肘部尺神经沟内因慢性损伤而产生的一组症状和体征，表现为手背尺侧、小鱼际、小指及环指尺侧半感觉异常，小指收展无力及手指收、展不灵活，环小指可呈爪形手畸形。梨状肌综合征（十版外科学P698）是指坐骨神经在臀部受到卡压出现的一组症状和体征，表现为坐骨神经痛，体查可发现小腿轻度萎缩，小腿以下皮肤感觉异常。","","N"],["2008-N150",50,"第四节 周围神经卡压综合征","梨状肌综合征应用解剖",2008,150,"B","","梨状肌出口综合征卡压的神经是",[["A","正中神经"],["B","尺神经"],["C","坐骨神经"],["D","股神经"]],"C","腕管综合征是正中神经（十版外科学P696）在腕管内受压而表现出的一组症状和体征，表现为拇、示、中指感觉过敏或迟钝，鱼际肌萎缩，拇对掌无力，腕部正中神经Tinel征阳性。肘管综合征（十版外科学P697）是指尺神经在肘部尺神经沟内因慢性损伤而产生的一组症状和体征，表现为手背尺侧、小鱼际、小指及环指尺侧半感觉异常，小指收展无力及手指收、展不灵活，环小指可呈爪形手畸形。梨状肌综合征（C对）是指坐骨神经在臀部受到卡压出现的一组症状和体征，表现为坐骨神经痛，体查可发现小腿轻度萎缩，小腿以下皮肤感觉异常。","","N"],["2008-N175",17,"第一节 甲状腺疾病","TSH抑制治疗",2008,175,"X","","可用甲状腺素治疗的甲状腺疾病有",[["A","单纯性甲状腺肿"],["B","甲状腺癌"],["C","亚急性甲状腺炎"],["D","桥本甲状腺肿"]],"ABCD","对于弥漫性单纯性甲状腺肿（A对）病人可给予小量甲状腺素，以抑制垂体前叶TSH分泌，缓解甲状腺的增生和肿大。亚急性甲状腺炎（C对）者，甲状腺滤泡破坏，功能减退，服用泼尼松同时加用甲状腺素制剂可减轻甲状腺负担。桥本甲状腺肿（D对），病变的甲状腺组织被淋巴细胞、浆细胞所取代，分泌的甲状腺减少，可长期服用甲状腺素片作替代治疗。甲状腺癌（B对）作次全或全切除后，患者应终身服用甲状腺素片，以预防甲状腺功能减退及抑制TSH分泌，减少肿瘤复发，系因分化型甲状腺癌细胞均有TSH受体，TSH通过其受体能影响甲状腺癌的生长。","","N"],["2008-N176",18,"第四节 乳腺癌","临床表现",2008,176,"X","","下列乳腺疾病中，可出现乳头内陷的有",[["A","乳腺癌"],["B","浆细胞性乳腺炎"],["C","乳腺派杰病"],["D","急性乳腺炎"]],"ABC","乳头内陷是乳腺疾病的常见症状。乳腺癌（A对）病人，癌细胞浸润周围组织产生粘连、牵拉，若病灶位于乳头或乳晕周围，则可侵犯乳管使其收缩可引起乳头内陷。浆细胞性乳腺炎（B对）区别于一般的炎症性疾病，属于乳腺良性病变，是由于乳晕下导管有阻塞，引起导管扩张，管壁上皮萎缩，管内各种类脂质及细胞碎屑积聚腐蚀管壁，在管壁周围的脂肪组织内见有片状的浆细胞浸润；病变发展时有局部红、肿、痛等症状，并可触及肿块，也可见皮肤粘连、乳头回缩、局部水肿及腋窝淋巴结增大等征象，易误诊为乳腺癌；乳腺派杰病（C对）即乳头湿疹样乳腺癌，其恶性度低，发展缓慢，乳头有瘙痒、烧灼感，后发展为乳头和乳晕的皮肤变粗糙、糜烂如湿疹样，进而形成溃疡，有时有鳞屑样痂皮，累及乳头深层时可出现乳头内陷或溃烂，较晚发生淋巴结转移。急性乳腺炎（D错）是乳腺常见的炎症性疾病，主要表现为红肿、疼痛，感染位置较深则仅有深压痛，伴全身感染症状，但无乳头内陷表现。","","N"],["2008-N177",10,"第二节 麻醉前评估和准备","胃肠道准备",2008,177,"X","","幽门梗阻患者术前应做的准备有",[["A","禁食，胃肠减压"],["B","纠正水电解质失调和低蛋白血症"],["C","应用广谱抗生素"],["D","温盐水洗胃"]],"ABCD","幽门梗阻的手术术前准备应按照消化道手术的术前准备来进行。禁食，胃肠减压（A对）和温盐水洗胃（D对）可使得胃壁水肿减轻，降低术后吻合口瘘的发生率，亦有利于清空胃内容物，使手术能顺利进行。幽门梗阻病人长期无法进食，并且呕吐出大量胃液，常伴低钾低氯性水电解质失调和低蛋白血症，使得病人对手术的耐受力降低，并影响愈合，不仅死亡率会上升，术后感染率也会增加，故需在术前纠正水电解质失调和低蛋白血症（B对）；胃与消化道其他部分不同，为高胃酸环境，多数细菌难以存活，胃部手术可视为清洁手术，通常不需要预防使用抗菌药物，但幽门梗阻时，由于胃排空障碍，胃酸被稀释，利于细菌生长，常合并有胃的炎症，故幽门梗阻术前也可应用抗生素（C）预防感染，但真题似乎认为不应该使用广谱抗生素，该题C选项存在争议。本题参考答案为ABD。","","N"],["2008-N178",29,"第十二节 痔","内痔",2008,178,"X","","下列肛门部疾患中，可便鲜血的有",[["A","肛瘘"],["B","肛裂"],["C","内痔"],["D","外痔"]],"BC","肛裂（B对）的典型临床表现为疼痛、便秘及出血，其中出血多由肛裂溃疡出血粘于粪便表面，出现便鲜血。内痔（C对）的主要临床表现是出血和脱出。间歇性便后出鲜血是内痔的常见症状。肛瘘（A错）为肛管周围的肉芽肿性管道，可有脓性或脓血性分泌物自瘘道外口流出，一般无便鲜血。外痔（十版外科学P435）（D错）的主要表现为肛门不适、潮湿不洁，有时瘙痒，一般无便血。九版诊断学P31页将肛瘘归为引起鲜血便的原因之一，但当年给出的答案为BC。","","N"],["2008-N179",56,"第一节 骨关节炎","骨关节炎病理",2008,179,"X","","下列关于非化脓性关节炎的叙述，正确的有",[["A","原发性骨关节病变起自于关节软骨"],["B","类风湿关节炎病变起自于滑膜"],["C","强直性脊椎炎病变起自于骶髂关节"],["D","血友病性关节病变起自于关节血管畸形"]],"ABC","原发性骨关节病变起自于关节软骨（A对），软骨破坏后可出现软骨下骨质增生、硬化和囊肿形成，滑膜增厚和炎性炎症。类风湿关节炎病变起自于滑膜（B对），为关节滑膜的慢性炎症，早期滑膜充血、水肿，单核细胞、淋巴细胞和浆细胞浸润，纤维蛋白渗出。强直性脊椎炎病变起自于骶髂关节（C对），逐渐向上蔓延至脊柱，导致纤维性或骨性强直和畸形。血友病患者由于缺乏凝血因子，不能将凝血酶原转变为凝血酶，使纤维蛋白原无法形成纤维蛋白而易在轻微外因作用下出血，且不易止血；血友病性关节病变起自于关节内出血（D错）。血友病患者关节内出血时可形成关节内血肿，血肿机化和炎症反应可损伤关节软骨，反复发作可损伤关节结构，导致血友病性关节病。","","N"],["2008-N180",53,"第二节 腰椎退行性疾病","X线平片",2008,180,"X","","腰椎间盘突出的典型X线平片表现有",[["A","腰椎前凸消失"],["B","椎间盘突出间隙左右不等宽"],["C","椎间盘影向后突出"],["D","椎间盘突出间隙前窄后宽"]],"ABD","X线片对腰椎显示良好，在腰椎间盘突出病人中，在侧位片上可见到病人腰椎生理前凸变小或消失（A对）。在正位片上可见腰椎侧弯，椎间盘突出间隙左右不等宽（B对）。椎间盘病变后前部椎间隙缺少椎间盘支撑而塌陷，后部椎间隙因关节突出而塌陷不明显，因此Ｘ线可表现为椎间隙前窄后宽（D对）。椎间盘主要由外层的纤维环（纤维软骨）和内层的髓核构成，在X线片上不显影（C错）。","","N"],["2009-N77",10,"第五节 椎管内麻醉","麻醉平面的调节",2009,77,"A","","硬膜外阻滞的麻醉平面与下列那些因素无关",[["A","穿刺间隙"],["B","麻药容积"],["C","麻药种类"],["D","导管方向"]],"C","硬膜外阻滞的麻醉平面是节段性的，影响麻醉平面的主要因素有：1.穿刺间隙（A对）：麻醉上、下平面的高低取决于穿刺间隙的高低；2.麻药容积（B对）：容积越大，扩散越广，麻醉范围越宽；3.导管方向（D对）：导管向头端插入，药液易向胸颈段扩散，导管向尾端插入，则药液易向腰骶段扩散，4.注药方式：一次性集中注药则麻药范围较广，分次注药则麻醉范围缩窄。麻药的种类为理化性质，主要影响的是麻药的作用时间和强度，而非影响麻醉平面（C错，为本题正确答案）。","","N"],["2009-N78",1,"第二节 水、钠代谢紊乱","等渗性脱水治疗",2009,78,"A","","一位肠梗阻患者，恶心，呕吐，少尿，尿比重增高，眼窝凹陷，肢端湿冷。血压较低，血清钠正常，首选的补液种类",[["A","5%葡萄糖"],["B","生理盐水"],["C","平衡盐溶液"],["D","5%氯化钠"]],"C","肠梗阻患者，恶心、呕吐，少尿，尿比重增高，眼窝凹陷，肢端湿冷，血压较低，血清钠正常，诊断考虑等渗性缺水（肠梗阻多引起急性失水，血清钠正常）。治疗时，应积极纠正病因，有针对性地纠正其细胞外液的减少。生理盐水为等渗溶液，但其中的Cl⁻含量比血清Cl⁻含量高50mmol/L（生理盐水和血浆中Cl⁻含量分别为154mmol/L及103mmol/L），大量输注可导致血Cl⁻过高，存在引起高氯性酸中毒的危险。平衡盐溶液（C对）的电解质含量和血浆内含量相仿，优于高Cl⁻水平的等渗生理盐水（B错），用来治疗等渗性缺水比较理想。5%氯化钠溶液（D错）为高渗溶液，可用于低渗性脱水的治疗，可纠正细胞外液的低渗状态和补充血容量（十版外科学P12）。5%葡萄糖（A错）为不含钠的等渗溶液，可补充血容量，但用于治疗等渗性缺水容易引起稀释性低钠血症，多用于治疗高渗性脱水。","","N"],["2009-N79",2,"第三节 自体输血和大量输血","自体输血",2009,79,"A","","一位外伤性脾破裂患者，术中经血液回收机收集失血处理后，回输给患者的是",[["A","全血"],["B","血浆"],["C","浓缩红细胞"],["D","洗涤红细胞"]],"C","回收式自体输血目前多采用血液回收机收集失血，经自动处理后去除血浆和有害物质，可得到浓缩红细胞，然后再回输（C对）。输入全血（A错）适应证：失血量超过总血容量的30%。输入血浆（B错）适应证：严重肝脏病、凝血因子缺乏、弥漫性血管内凝血（DIC）、烧伤等。输入洗涤红细胞（D错）适应证：对白细胞凝集素有发热反应者及肾功能不全不能耐受库存血中之高钾者。","","N"],["2009-N80",8,"第二节 常见体表肿瘤与囊肿","黑痣",2009,80,"A","","下列常见体表良性肿瘤中，易发生恶性病变的是",[["A","皮肤乳头状疣"],["B","交界痣"],["C","皮内痣"],["D","神经鞘瘤"]],"B","交界痣（B对）痣细胞位于基底细胞层，易受局部外伤或感染等激惹后恶变，故应及早做预防性切除。皮肤乳头状疣（十版外科学P97）（A错）非真性肿瘤，多由病毒所致。皮内痣（十版外科学P98）（C错）是黑痣最为常见的种类，是由含有色素的痣细胞所构成的最常见的皮肤良性色素斑块，很少恶变。神经鞘瘤（十版外科学P99）（D错）属于神经纤维瘤，体表神经鞘瘤可见于四肢神经干的分布部位，属于良性肿瘤，手术切除是唯一可能根治的方法。","","N"],["2009-N81",7,"第一节 热力烧伤","成人烧伤抗休克补液",2009,81,"A","","一位消防队员，体重65kg，在救火中不幸烧伤了面部，双上肢、躯干前方和会阴部，对该患者第一个24小时应补的液体总量",[["A","3500ml"],["B","4600ml"],["C","5000ml"],["D","5500ml"]],"D","补液是防治烧伤休克最重要的措施。常根据病人的烧伤面积和体重按下述公式计算补液量：伤后第1个24小时补液量：成人每1%Ⅱ°、Ⅲ°烧伤面积每公斤体重补液1.5ml（胶体液0.5ml和电解质液1ml），另加基础水分2000ml。成年男性烧伤面积估算（九分法）：头颈部一九；双上肢二九；躯干部三九；双下肢五九再加一。关于具体部位面积估算可用口诀来记忆：3、3、3、5、6、7（分别对应发部、面部、颈部、双手、双前臂、双上臂）；13、13、再加1（分别对应躯干前、躯干后、会阴）；5、7、13、21（分别对应双臀、双足、双小腿、双大腿）。患者烧伤面部，双上肢、躯干前方和会阴部，可知患者烧伤面积共占体表面积的3%＋18%＋13%＋1%＝35%。患者体重65kg，根据补液公式，第1个24小时补液总量为35×65×1.5＋2000＝5412.5ml≈5500ml（D对）。","","N"],["2009-N82",18,"第四节 乳腺癌","乳腺癌化学治疗",2009,82,"A","","下列选项中不属于乳腺癌的术后化疗指征的是",[["A","雌、孕激素受体阴性"],["B","腋窝淋巴结转移阳性"],["C","导管内癌"],["D","脉管癌栓"]],"C","教材中并无明确的乳腺癌化疗指征，但是从病理分型考虑则解题十分简单。对于乳腺癌病人，无论是放疗还是化疗，针对的都是浸润性乳腺癌，非浸润性乳腺癌只要切除原发灶、病理证实确实无浸润，术中可不行淋巴结清扫、术后无需常规放化疗。导管内癌属于非浸润性乳腺癌，无需使用术后化疗（C错，为本题正确答案）。雌、孕激素受体阴性（A对）、腋窝淋巴结转移阳性（B对）是乳腺癌的术后应用辅助化疗的指征。脉管癌栓（D对）形成浸润癌，需辅助化疗。","","N"],["2009-N83",26,"第三节 胃十二指肠溃疡的外科治疗","胃切除的范围",2009,83,"A","","下列关于胃十二指肠病手术治疗叙述正确的是",[["A","胃Ⅱ、Ⅲ型胃溃疡行胃大部切除的范围应不少于胃的60%"],["B","胃肠吻合口一般5～6cm为宜"],["C","毕Ⅱ式胃大部切除术后溃疡复发率较高"],["D","选择性迷走神经切断术不需要做胃引流手术"]],"A","胃大部切除术的范围包括胃远侧的2/3～3/4并包括幽门、近胃侧部分十二指肠球部，不难得出胃Ⅱ、Ⅲ型胃溃疡行胃大部切除的范围应不少于胃的60％（A对）。胃肠吻合口直径一般为3～4cm（B错），过大易发生倾倒综合征，过小影响胃排空。毕Ⅱ式胃大部切除术切除了溃疡的好发部位及泌酸的大部分胃体，因而溃疡复发率低（C错）。高选择性胃迷走神经切断术不需附加引流手术，因其未切断支配胃窦部迷走神经的鸦爪支，术后无排空障碍、无胃潴留；选择性迷走神经切断术并未保留鸦爪支，术后需要作胃引流手术（D错）。","","N"],["2009-N84",26,"第二节 胃癌及其他胃肿瘤","胃癌血行转移",2009,84,"A","","胃癌晚期血行转移最多见的部位是",[["A","骨"],["B","胰"],["C","肺"],["D","肝"]],"D","门静脉收集胃的静脉血并汇入肝脏，胃癌癌细胞进入血液后，可随血液回流，经门脉系统进入肝脏。若癌细胞滞留于肝脏并在此处增殖，即产生肝转移性胃癌，故胃癌晚期血行转移最多见的部位是肝（D对）。肺（C错）、胰（B错）、骨（A错）也是常见的癌症转移部位。","","N"],["2009-N85",25,"第二节 腹腔脓肿","盆腔脓肿诊断",2009,85,"A","","患者，男，33岁，因急性穿孔性阑尾炎伴局限性腹膜炎，行阑尾切除术后5天，体温38度以上，白细胞计数18×10⁹/L，腹痛，腹胀，大便3～5次/天，伴下坠感，应考虑是",[["A","盆腔脓肿"],["B","并发肠炎或痢疾"],["C","并发膈下脓肿"],["D","切口感染"]],"A","急性穿孔性阑尾炎伴局限性腹膜炎，行阑尾切除术后5天，体温升高伴直肠刺激症状（腹痛，腹胀，大便3～5次/天，伴下坠感），应考虑盆腔脓肿（A对），因为阑尾穿孔后，肠内容物顺右髂窝流入盆腔，术后半卧位，也有部分肠腔渗液流入盆腔，盆腹膜的吸收能力比上腹膜差，故易积聚盆腔形成脓肿。肠炎或痢疾（B错）会有大便性状的改变且与手术无关。膈下脓肿（C错）可有发热、白细胞计数增高、腹胀腹痛，但不会产生下坠感，下坠感是直肠周围受到刺激而引起。切口感染（D错）可在术后2～3日体温升高，切口胀痛或跳痛，局部红肿，压痛，但一般无腹胀腹痛及直肠刺激症状。","","N"],["2009-N86",28,"第三节 特殊类型阑尾炎","妊娠期急性阑尾炎",2009,86,"A","","患者，女，28岁，宫内孕27周，右侧腹痛30小时，伴发热38℃，恶心，未吐。查体：宫底脐上二指，右侧腹部压痛（+），无包块，白细胞计数10.8×10⁹/L，诊断为急性阑尾炎。下列处理中，不恰当的是",[["A","使用广谱抗生素"],["B","剖宫产加阑尾切除术"],["C","使用黄体酮"],["D","阑尾切除术"]],"B","病例中患者妊娠27周，体温38度，恶心未吐，查体：右侧腹部压痛，可明确诊断为妊娠中期急性阑尾炎，若不及时治疗，炎症发展易导致流产或早产，威胁母子生命安全，因此治疗以阑尾切除术为主（D对），围术期应使用黄体酮（C对）保胎，术后使用广谱抗生素（A对）。但妊娠27周时胎儿尚未发育完善，且无早产征象，未到临产期，剖宫产则婴儿死亡的可能性极大（B错，为本题正确答案）。","","N"],["2009-N87",10,"第二节 麻醉前评估和准备","胃肠道准备",2009,87,"A","","下列关于结肠癌患者术前准备的叙述，错误的是",[["A","术前两日进流食"],["B","口服肠道抗生素和泻剂"],["C","抗肿瘤药物灌肠"],["D","术前12～24h行肠道灌洗"]],"C","结肠癌患者术前应常规进行肠道准备，目的是减少肠道内的粪便残留和细菌数量，从而降低术后感染和吻合口瘘的发生率。其具体措施包括：术前两日进流食（A对）（流食几乎不产生残渣，可减少肠道内粪便，有利于结肠手术的进行）；口服肠道抗生素和泻剂（B对）的目的是为了抑制肠道细菌生长，排空肠腔，目的是降低手术过程中肠道内细菌和杂质污染腹腔的危险；术前12～24h行肠道灌洗（D对）可进一步清洁排空结肠。在直肠癌手术切除的具体操作中，首先要将肿瘤所在肠管的两段用纱布条扎紧，随即结扎相应血管，以防止癌细胞在肠腔内或血液中扩散种植和转移，可在扎闭的肠腔内给予稀释的抗癌化学药物后行肠袢切除，但抗肿瘤药物灌肠无意义（C错，为本题正确答案），不是常规肠道准备的要求。","","N"],["2009-N88",44,"第五节 影响骨折愈合的因素","骨折部位的血液供应",2009,88,"A","","胫骨下三分之一骨折愈合较慢的原因是",[["A","附近的主要血管损伤"],["B","附近的周围神经损伤"],["C","骨折远端血供全部中断"],["D","骨折远端血液供应减弱"]],"D","对于胫骨骨折，作如下总结：①腘动脉分胫前、胫后动脉，胫后动脉穿过比目鱼肌腱弓向下行走，此血管固定，胫骨上1/3骨折易损伤该动脉，引起下肢严重缺血；②在小腿中1/3，小腿深筋膜与胫腓骨及骨间膜形成四个界限清楚的筋膜室，由于骨折后骨髓腔出血，或肌肉损伤出血或血管损伤出血，均可引起骨筋膜室综合征；③胫骨下1/3骨折易损伤滋养动脉，导致胫骨下段骨折远端血液供应减弱（D对），引起骨折的延迟愈合。骨折远端血供全部中断（C错）说法过于绝对，胫骨下段可经少量细小的动脉交通支获得少量血供（一般来讲，过于绝对化的选项均欠妥）。胫骨下三分之一骨折愈合较慢与附近主要血管损伤（A错）及周围神经损伤无关（B错）。","","N"],["2009-N89",54,"第二节 化脓性关节炎","化脓性关节炎临床表现",2009,89,"A","","下列选项中，不属于化脓性关节炎特点的是",[["A","发热"],["B","好发于上肢各关节"],["C","周围血白细胞升高"],["D","血沉快"]],"B","化脓性关节炎为细菌引起的关节内化脓性感染，可导致发热（A对）、周围血白细胞升高（C对）、血沉加快（D对）。化脓性关节炎好发于下肢髋、膝关节（B错，为本题正确答案）。","","N"],["2009-N90",53,"第一节 颈椎退行性疾病","颈椎病诊断",2009,90,"A","","患者女，45岁，经常头痛，头晕，有时突然晕倒，随后很快清醒，偶有视物不清，查体：压头实验阳性，颈椎侧弯或后伸可加重头晕，双下肢腱反射亢进，脊髓造影有部分梗阻。最可能的诊断是",[["A","椎动脉型颈椎病"],["B","体位性眩晕"],["C","神经根型颈椎病"],["D","美尼尔症"]],"A","45岁女性患者，头痛，头晕（椎动脉型颈椎病的主要症状），有时突然晕倒，随后很快清醒，偶有视物不清（椎动脉型颈椎病的典型症状）。查体：压头实验阳性，颈椎侧弯或后伸可加重头晕（可刺激椎动脉，加重缺血症状），双下肢腱反射亢进，脊髓造影有部分梗阻（提示）。综合该患者的病史、体查及影像学检查，诊断考虑椎动脉型颈椎病（A对）。体位性眩晕（B错）主要是由于病人血压较低，故从卧位或蹲位较快速站起时，脑供血短暂性不足引起的眩晕，与病人临床表现不符，且脊髓造影不会出现梗阻。神经根型颈椎病（C错）的典型临床表现为肩颈痛及对应肢体的感觉和运动障碍，不会引起头晕等症状。美尼尔症（D错）是由内耳病变引起的疾病，一侧耳鸣、耳聋伴有突然性眩晕发作是本病的特点，病人无耳鸣、耳聋表现。","","N"],["2009-N111",32,"第四节 胆石症","胆囊结石治疗",2009,111,"A","","患者，男，75岁，7天前因胆囊多发小结石行腹腔镜胆囊切除术，近2日来发现巩膜黄染。患者出现黄疸最可能的原因是",[["A","术中胆总管损伤"],["B","胆管水肿狭窄"],["C","胆囊内结石手术时落入总胆管"],["D","甲型肝炎"]],"C","胆道手术后黄疸是胆道手术的常见并发症，多由于胆道损伤引起，或者是因为手术没能解除梗阻，如胆囊内结石手术时落入总胆管。该患者因胆囊多发小结石行腹腔镜胆囊切除术，存在小结石落入胆总管的风险；术后五天发生黄疸，考虑胆道梗阻，最可能的原因为胆囊内结石手术时落入总胆管（C对）致胆道梗阻，引起黄疸。术中胆总管损伤（A错）常在术后早期出现黄疸，并可有胆汁瘘、腹部剧痛及腹膜刺激征，与该患者表现不符。胆管水肿狭窄（B错）常于胆总管探查后发生，该患者进行胆囊切除术，术中并未刺激损伤胆管，因而发生该病可能性小。甲型肝炎（D错）是经消化道传播的肝炎，病人应有明确传染接触史方可诊断，发病与胆囊手术无关。","","N"],["2009-N112",32,"第二节 胆道疾病影像学检查","内镜逆行胰胆管造影",2009,112,"A","","患者，男，75岁，7天前因胆囊多发小结石行腹腔镜胆囊切除术，近2日来发现巩膜黄染。此时最好的处理方法是",[["A","ERCP加EST取石"],["B","开腹胆总管探查"],["C","消炎利胆治疗"],["D","保肝治疗"]],"A","ERCP加EST取石（A对）为此时最好的处理方法，能够直接取出致病结石，通畅胆道，并且手术损伤小，术后恢复快。开腹胆总管探查（B错）创伤大，患者为老年人，对手术耐受能力较差，暂时不宜行开放手术。消炎利胆治疗（C错）、保肝治疗（D错）均为保守治疗方法，并不能使胆总管结石排出体外，而该病患只有解除胆道梗阻，才能防止疾病进一步恶化。","","N"],["2009-N113",31,"","",2009,113,"A","","患者，男，60岁，乙肝肝硬化10年，曾间断黑便，近来出现轻度黄疸和少量腹水，2天前大量呕血。经用止血药和生长抑素及三腔二囊管压迫，血压稳定，脉率90次/分，Hb80g/L，在第24小时及48小时2次放松三腔二囊管牵引仍有出血。此时应考虑患者是",[["A","食管静脉曲张破裂出血"],["B","胃底静脉曲张破裂出血"],["C","门脉高压性胃病出血"],["D","溃疡病出血"]],"B","60岁男性患者，乙肝肝硬化10年（肝硬化门脉高压的常见病因），出现黄疸及腹水（肝功能减退），2天前大呕血（出血量较大，静脉曲张破裂出血可能性大），经止血药和生长抑素及三腔二囊管压迫，血压稳定，考虑诊断为食管胃底曲张静脉破裂出血。三腔二囊管压迫止血的原理是利用充气的气囊分别压迫胃底和食管下段的曲张静脉，其中压迫胃底需要依靠鼻外牵挂重物进行牵引，而压迫食管利用气囊本身的扩张压力即可，题干里提及2次放松三腔二囊管牵引有出血（压迫效果欠佳），提示该患者应属于胃底静脉曲张破裂出血（B对）。门脉高压性胃病出血（C错）及溃疡病出血（D错）出血量一般不超过500ml，引起大出血的可能性低，故不考虑。","c26","N"],["2009-N114",31,"门静脉高压","经颈静脉肝内门体静脉分流术",2009,114,"A","","患者，男，60岁，乙肝肝硬化10年，曾间断黑便，近来出现轻度黄疸和少量腹水，2天前大量呕血。经用止血药和生长抑素及三腔二囊管压迫，血压稳定，脉率90次/分，Hb80g/L，在第24小时及48小时2次放松三腔二囊管牵引仍有出血。对此患者最适宜的治疗方法是",[["A","急诊分流"],["B","急诊断流"],["C","经食管曲张静脉套扎"],["D","TIPS"]],"D","患者已存在腹水及黄疸症状，说明肝功能差，不适宜行急诊分流（A错）或急诊断流（B错），因为术后肝性脑病发生率及死亡率较高。曲张静脉套扎（C错）用于食管静脉曲张破裂效果好，但是对胃底曲张静脉破裂出血效果差。TIPS（D对）即经颈静脉肝内门体分流术，主要用于顽固性腹水和肝硬化门静脉高压症、食管胃底静脉曲张破裂大出血的治疗，其创伤小，止血效果确切，特别适用于肝功能差的病人。","c26","N"],["2009-N115",33,"第二节 胰腺炎","急性胰腺炎诊断",2009,115,"A","","患者，男，55岁，昨天中午参加婚宴后下午开始腹痛，为持续性胀痛，牵涉到后背，伴恶心、呕吐。有胆囊结石病10年。查体：体温37.2℃，血压110/82mmHg，脉率108次/分，呼吸24次/分，巩膜可疑黄染，上腹膨隆，全腹压痛，以左上腹为重，轻度肌紧张，肠鸣音1～2次/分。WBC11×10⁹/L，N80%，血淀粉酶1500U/dL，尿淀粉酶2200U/dL，B超显示胆囊多发结石，总胆管宽0.8cm，胰腺增大，边界不清，胰周有积液。对该患者可能诊断是",[["A","上消化道穿孔"],["B","急性胆囊炎"],["C","急性胰腺炎"],["D","急性胆管炎"]],"C","55岁男性患者，胆囊结石病史10年（胰腺炎的常见致病危险因素）。昨日下午开始腹痛，为持续性胀痛，牵涉到后背，伴恶心、呕吐（急性胰腺炎的常见临床表现）。查体：巩膜可疑黄染（提示胆道梗阻可能），上腹膨隆，全腹压痛，以左上腹为重，轻度肌紧张（提示轻度腹膜刺激征），肠鸣音1～2次/分（提示麻痹性肠梗阻）。实验室检查：WBC11×10⁹/L，N80%，血淀粉酶1500U/dL，尿淀粉酶2200U/dL（淀粉酶测值远大于500U/dL，提示急性胰腺炎），胰腺增大，边界不清，胰周有积液（急性胰腺炎的典型B超表现）。综合该患者的病史、体查、实验室检查、影像学检查，诊断考虑急性胰腺炎（C对）。上消化道穿孔（十版外科学P380）（A错）可伴有淀粉酶轻度升高，但穿孔所致腹膜炎刺激重，压痛反跳痛、肌紧张均明显。急性胆囊炎（十版外科学P473）（B错）以右上腹痛为著，右上腹压痛明显，淀粉酶可轻度升高。急性胆管炎（D错）多有黄疸，肝区叩痛严重，且伴高热。","c27","N"],["2009-N116",33,"第二节 胰腺炎","CT扫描",2009,116,"A","","患者，男，55岁，昨天中午参加婚宴后下午开始腹痛，为持续性胀痛，牵涉到后背，伴恶心、呕吐。有胆囊结石病10年。查体：体温37.2℃，血压110/82mmHg，脉率108次/分，呼吸24次/分，巩膜可疑黄染，上腹膨隆，全腹压痛，以左上腹为重，轻度肌紧张，肠鸣音1～2次/分。WBC11×10⁹/L，N80%，血淀粉酶1500U/dL，尿淀粉酶2200U/dL，B超显示胆囊多发结石，总胆管宽0.8cm，胰腺增大，边界不清，胰周有积液。为进一步明确诊断，应做得检查是",[["A","增强CT"],["B","MRI"],["C","腹部平片"],["D","选择性血管造影"]],"A","患者诊断为急性胰腺炎。增强CT（A对）是胰腺炎最具诊断价值的影像学检查，不仅能诊断急性胰腺炎，而且能鉴别出是否合并胰腺坏死。此外，CT对急性胰腺炎并发症如胰腺脓肿和假性囊肿等也具有较高的诊断价值。MRI与CT的诊断效果相差不大，但是费用昂贵，一般不作为首选。腹部平片（C错）对诊断急性胰腺炎价值有限。血管造影（D错）一般不用于胰腺炎诊断。","c27","N"],["2009-N117",33,"第三节 胰腺囊性疾病","胰腺假性囊肿治疗",2009,117,"A","","患者，男，55岁，昨天中午参加婚宴后下午开始腹痛，为持续性胀痛，牵涉到后背，伴恶心、呕吐。有胆囊结石病10年。查体：体温37.2℃，血压110/82mmHg，脉率108次/分，呼吸24次/分，Hb108，巩膜可疑黄染，上腹膨隆，全腹压痛，以左上腹为重，轻度肌紧张，肠鸣音1～2次/分。WBC11×10⁹/L，N80%，血淀粉酶1500U/dL，尿淀粉酶2200U/dL，B超显示胆囊多发结石，总胆管宽0.8cm，胰腺增大，边界不清，胰周有积液。2周后，病情稳定，体温不高，CT见胰体尾部增强不均匀，小网膜囊10cm×8cm液性包块。此时需做的处理是",[["A","手术清创引流"],["B","腹腔穿刺引流"],["C","切除胆囊，总胆管探查引流"],["D","继续保守治疗，2个月后处理囊肿和胆道"]],"D","患者诊断为急性胰腺炎，2周后病情稳定，见到胰体尾部一个液性包块，病人无不适表现，最有可能是伴发了胰腺假性囊肿。对于胰腺假性囊肿，在囊壁尚未成熟前，若检查排除恶性可能后，可暂予非手术治疗。一般须待囊肿壁成熟后（6周以上）再作内引流或外引流术。因此，该患者此时需继续保守治疗，2个月后处理囊肿和胆道（D对）。","c27","N"],["2009-N118",53,"第二节 腰椎退行性疾病","感觉异常",2009,118,"A","","患者，男，42岁，患腰椎间盘突出症伴典型的坐骨神经受压体征，检查小腿外侧及第1、2趾间背侧皮肤刺痛觉消失，并有伸拇肌力减弱，膝及踝反射正常。腰椎间盘突出的部位推断为",[["A","腰2～3"],["B","腰3～4"],["C","腰4～5"],["D","腰5～骶1"]],"C","腰4～5椎间盘突出压迫腰5神经根，表现为小腿前外侧及足背内侧感觉障碍，足拇趾背伸乏力或不能。根据患者神经系统表现，患者腰椎间盘突出的部位推断为腰4～5（C对）。腰2～3椎间盘突出（A错）压迫腰3神经根，表现为股骨内髁感觉障碍，伸膝无力，膝反射减弱或消失。腰3～4椎间盘突出（B错）压迫腰4神经根，表现为小腿前内侧及膝前感觉障碍，伸膝无力，膝反射减弱或消失。腰5～骶1椎间盘突出（D错）压迫骶1神经根，表现为小腿后外侧及外踝、足外侧感觉障碍，趾及足跖屈无力，踝反射减弱。","c28","N"],["2009-N119",53,"第二节 腰椎退行性疾病","造影检查",2009,119,"A","","患者，男，42岁，患腰椎间盘突出症伴典型的坐骨神经受压体征，检查小腿外侧及第1、2趾间背侧皮肤刺痛觉消失，并有伸拇肌力减弱，膝及踝反射正常。定位最准确最经济的检查是",[["A","腰椎X线片"],["B","腰椎过伸过屈位X线片"],["C","腰椎椎管造影"],["D","腰椎磁共振扫描"]],"C","腰椎X线片（A错）及腰椎过伸过屈位X线片（B错）显示不清晰、定位不准确，对本病的诊断价值有限。腰椎磁共振扫描可显示椎管形态，椎间盘突出方向、大小等，是目前最普遍、最准确、最经济的检查方法。腰椎椎管造影为有创检查，且操作复杂，并发症多，现已弃用。因此本题最佳答案为D，但当年给出的答案为C。","c28","N"],["2009-N120",53,"第二节 腰椎退行性疾病","腰椎间盘突出症手术方法",2009,120,"A","","患者，男，42岁，患腰椎间盘突出症伴典型的坐骨神经受压体征，检查小腿外侧及第1、2趾间背侧皮肤刺痛觉消失，并有伸𧿹肌力减弱，膝及踝反射正常。定位诊断为一侧神经根腋部椎间盘突出，最适宜的手术方法是",[["A","全椎板切除椎间盘切除术"],["B","半椎板切除椎间盘切除术"],["C","小开窗椎间盘切除术"],["D","经腹椎间盘切除术"]],"C","单纯腰椎间盘突出症的治疗首选小开窗椎间盘切除术（C对），此术式创伤较小，术后即能早期活动，迅速返回工作岗位，避免了开放性腰椎间盘手术后的硬膜外瘢痕形成、腰椎不稳等并发症。全椎板切除椎间盘切除术（A错）适应证包括：椎间盘突出合并有椎管狭窄、椎间盘向两侧突出、中央型巨大突出以及游离椎间盘突出。半椎板切除椎间盘切除术（B错）适用于单纯椎间盘向一侧突出者。L₅S₁椎间盘因髂骨翼遮挡，采用常规的后外侧入路穿刺成功率较低，可采用经腹椎间盘切除术（D错）。","c28","N"],["2009-N145",42,"第二节 尿路上皮肿瘤","膀胱肿瘤临床表现",2009,145,"B","","膀胱癌多出现",[["A","初始血尿"],["B","终末血尿"],["C","全程血尿"],["D","无血尿"]],"C","膀胱癌出血与膀胱收缩无关，肿瘤组织坏死出血混杂在膀胱中，随尿液排出，形成全程血尿（C对）。血尿是泌尿系统疾病最常见的症状之一，不同的表现往往预示着不同的疾病可能。初始血尿常见于前尿道损伤；终末血尿常见于急性膀胱炎、肾结核等；全程血尿常见于上尿路损伤及泌尿系肿瘤等疾病。","","N"],["2009-N146",39,"第三节 下尿路感染","急性细菌性膀胱炎临床表现",2009,146,"B","","急性膀胱炎时常见",[["A","初始血尿"],["B","终末血尿"],["C","全程血尿"],["D","无血尿"]],"B","急性膀胱炎时常见终末血尿（B对），因为排尿终末时，膀胱发生强烈收缩，导致局部出血，随尿液排出，产生血尿。血尿是泌尿系统疾病最常见的症状之一，不同的表现往往预示着不同的疾病可能。初始血尿常见于前尿道损伤；终末血尿常见于急性膀胱炎、肾结核等；全程血尿常见于上尿路损伤及泌尿系肿瘤等疾病。","","N"],["2009-N147",23,"第二节 腹股沟疝","腹股沟疝概述",2009,147,"B","","发生率最高的疝是",[["A","腹股沟斜疝"],["B","腹股沟直疝"],["C","股疝"],["D","切口疝"]],"A","腹外疝中，由于精索或子宫圆韧带经腹股沟管深环穿出的原因，使得此处的腹壁存在先天薄弱。在腹压增高时，腹腔内容物可经此先天薄弱处疝出，发生腹股沟斜疝（A对）。斜疝最为常见，占腹股沟疝的85%～95%，远多于腹股沟直疝（B错）。切口疝（十版外科学P350）（D错）为发生于腹壁手术切口处的疝，临床上比较常见，占腹外疝的第三位。股疝（C错）为疝囊通过股环，经股管向卵圆窝突出的疝，约占腹外疝的3%～5%。","","N"],["2009-N148",23,"第三节 股疝","股疝病理解剖",2009,148,"B","","最容易发生嵌顿的疝是",[["A","腹股沟斜疝"],["B","腹股沟直疝"],["C","股疝"],["D","切口疝"]],"C","股管为上宽下窄的漏斗形结构，上端为股环，下端为卵圆窝，由于股疝都是垂直的，疝块在卵圆窝处向前转折时形成锐角，且股环本身较小，周围多有坚韧的韧带，在强力劳动或排便等活动使腹内压增高时，疝块经狭小的股管突出后难以回纳，因此股管容易发生嵌顿（C对）。一旦嵌顿，又可迅速发展为绞窄性疝，因此，一旦确诊，应及时手术治疗。","","N"],["2009-N149",57,"第三节 骨巨细胞瘤","骨巨细胞瘤治疗",2009,149,"B","","骨巨细胞瘤可采用的最佳治疗方法是",[["A","放射治疗"],["B","放射治疗+手术治疗"],["C","手术治疗"],["D","化疗治疗加手术治疗"]],"C","骨巨细胞瘤为交界性肿瘤，以手术治疗（C对）为主，采用切除术加灭活处理，但术后易复发。骨巨细胞瘤对化疗不敏感（D错）。放射治疗（A错）仅用于手术困难部位（例如原发于脊椎者），但放疗后易肉瘤变。放射治疗+手术治疗（B错）可能出现放疗后肉瘤变，因而不作优选。","","N"],["2009-N150",57,"第四节 原发性恶性骨肿瘤","骨肉瘤治疗",2009,150,"B","","骨肉瘤可采用的最佳治疗方法是",[["A","放射治疗"],["B","放射治疗+手术治疗"],["C","手术治疗"],["D","化疗治疗加手术治疗"]],"D","骨肉瘤是典型的恶性肿瘤，应采取手术治疗。但单纯手术（C错）治疗5年存活期不足20%（七版黄家驷外科学P3080）。由于对化疗敏感，因此术前、术后可给予大剂量化疗，可降低瘤负荷，延长患者生存期，因此最佳治疗方法为化疗治疗加手术治疗（D对）。骨肉瘤对于放射治疗（AB错）通常不敏感。","","N"],["2009-N175",1,"第一节 水、电解质代谢紊乱和酸碱平衡失调概述","体液酸碱度的调节",2009,175,"X","","机体酸碱平衡调节依赖于",[["A","体液的缓冲系统"],["B","肺的呼吸"],["C","肾的排泄"],["D","肝的代谢"]],"ABC","酸碱平衡是人体维持内环境稳定的重要条件，体液的缓冲系统、肺的呼吸、肾的排泄为人体调节自身酸碱平衡最重要的三种方式。肺通过深大的呼吸将血液中的H₂CO₃以CO₂形式排出，调节较缓慢，以调节挥发酸为主（B对）；肾通过对尿中H⁺和HCO₃⁻的分泌和重吸收来调节酸碱平衡，主要对长期酸碱平衡进行调节，以调节固定酸为主（C对）；血液中存在多种缓冲系统，以HCO₃⁻/H₂CO₃最为重要，可以缓冲体液的小幅度酸碱改变，调节迅速（A对）。","","N"],["2009-N176",12,"第四节 急性呼吸窘迫综合征","急性呼吸窘迫综合征症状与体征",2009,176,"X","","ARDS的特征性表现是",[["A","肺水肿"],["B","进行性呼吸困难"],["C","顽固性低氧血症"],["D","肺顺应性降低"]],"ABCD","ARDS（急性呼吸窘迫综合征）是因肺实质急性弥漫性损伤而导致的急性缺氧性呼吸困难，临床表现以进行性呼吸困难（B对）和顽固性低氧血症（C对）为特征。其特征性病变是非心源性肺水肿（A对），即漏出性肺水肿。ARDS患者由于肺间质和肺泡水肿、充血，肺表面活性物质减少引起肺表面张力增加，肺顺应性降低（D对）。","","N"],["2009-N177",23,"第二节 腹股沟疝","传统的疝修补术",2009,177,"X","","成人疝修补手术的成功的重要环节有",[["A","修补外环口"],["B","关闭疝门"],["C","加强或修补腹股沟管管壁"],["D","高位结扎疝囊"]],"BCD","疝的发病原因是疝囊及其内容物的突出，故需要把疝内容物回纳入腹腔，突出的疝囊高位切除、结扎（D对）；同时封闭疝突出的“门户”，即关闭疝门（B对）。腹股沟疝的发生原因是腹股沟管壁存在不同程度的薄弱区和缺损，加强腹股沟管管壁能从发病机制上解决问题（C对）。若内环口封闭，则疝内容物缺少了向外突出的途径，不可能突出体表，因此外环口无需修补（A错）。","","N"],["2009-N178",32,"第四节 胆石症","胆总管切开取石、T管引流术",2009,178,"X","","胆总管探查后放置T管，其原因有",[["A","减低胆管内的压力有利于胆管切口愈合"],["B","等待探查后乳头部的炎症消退"],["C","有助于消化功能恢复"],["D","便于经窦道取出残余结石"]],"ABD","胆总管探查后放置T管，其原因有胆道减压引流、预防术后胆漏；减少胆汁对切口和乳头部的刺激，有利于探查后乳头部的炎症消退（B对）和胆道切口的愈合（A对）；作为支撑预防胆管狭窄；便于经窦道取出残余结石（D对）。放置T管后，进入小肠后的胆汁量减少，可引起脂类物质的消化吸收障碍（胆盐可乳化脂肪，有利于脂类的吸收），不利于消化功能的恢复（C错），故需嘱病人低脂饮食。","","N"],["2009-N179",48,"第二节 脊髓损伤","脊髓损伤并发症",2009,179,"X","","高位截瘫的并发症",[["A","褥疮"],["B","排尿障碍及泌尿系感染"],["C","高热"],["D","呼吸衰竭和肺部感染"]],"ABCD","截瘫和四肢瘫病人，一般不直接危及生命，但它的并发症则是导致截瘫病人死亡的主要原因。截瘫平面以下，皮肤失去感觉，下肢不能活动，迫使病人卧于一个体位不动，受压的皮肤缺血缺氧而坏死，形成压疮或褥疮（A对），最常发生于骶部、股骨大转子、髂嵴和足跟等处。S₂～S₄段脊髓为排尿的脊髓反射中枢，圆锥以上脊髓损伤的截瘫病人，尿道外括约肌失去高级神经支配，不能自主放松，因而出现尿潴留；在圆锥损伤病人，阴部神经中枢受损，尿道外括约肌放松，出现尿失禁。这些排尿障碍均导致患者泌尿道的天然防御能力降低，极易引起泌尿系统感染（B对）。截瘫病人交感神经受损，与副交感神经系统失去平衡，皮肤排汗及体温调节功能丧失，夏日无法通过出汗散热从而造成高热（C对），冬季也会因体温调节功能丧失而低体温。高位截瘫病人肋间呼吸肌已麻痹，如果损伤达到C₄以上，膈肌亦麻痹。由于呼吸肌力量不足，呼吸非常费力，使呼吸道的阻力相应增加，分泌物难以排出，极易引起呼吸困难和呼吸道感染，甚至呼吸衰竭。但截瘫一般不累及心血管系统（D对）。","","N"],["2009-N180",44,"第七节 骨折的治疗原则","切开复位",2009,180,"X","","骨折切开复位的适应症",[["A","关节内骨折，手法未能完全复位"],["B","闭合骨折，并有大血管损伤"],["C","闭合骨折，未达到解剖复位"],["D","手法复位失败，疑断端有软组织嵌入"]],"ABD","关节内骨折，手法未能完全复位（A对），可导致创伤性骨关节炎（十版外科学P618），影响关节功能，须尽早手术治疗。闭合骨折，并有大血管损伤（B对），应立即手术切开复位，否则易导致肢体缺血坏死。手法复位失败，疑断端有软组织嵌入（D对），须切开复位，否则易导致骨折不愈合。骨折复位的目的是使移位的骨折段恢复其正常或接近正常的解剖结构，为骨折愈合及功能的恢复奠定基础，争取最大限度的功能恢复，而不是最大限度的复位。因此骨折复位的基本要求是所复位置不影响正常功能的发挥，即功能复位。骨折的复位并不要求一定要达到解剖复位（C错），一味追求不必要的解剖复位可加重局部组织损伤，影响预后。","","N"],["2010-N59",27,"第四节 肠梗阻","是机械性还是动力性梗阻",2010,59,"A","","患者出现剧烈阵发性腹痛，约数分钟一次，无排气。查体：腹部膨隆，压痛（+），可见肠型及蠕动波，肠鸣音亢进金属音调，最可能的诊断是",[["A","血运性肠梗阻"],["B","麻痹性肠梗阻"],["C","痉挛性肠梗阻"],["D","机械性肠梗阻"]],"D","机械性肠梗阻（D对）食物不能通过某段肠管而积存于梗阻段以上，导致上段肠管出现痉挛性收缩，产生腹痛；后由于肠管平滑肌过度疲劳而暂时舒张，疼痛减缓，即腹痛表现为阵发性。因肠管极度紧张，导致肠管强烈的收缩时产生高亢的肠鸣音，表现为气过水声或高调金属音，这是机械性肠梗阻特征性的临床表现。血运性肠梗阻（A错）是由于供应某段肠管的血管阻塞或关闭导致相应段肠管的缺血缺氧，表现为剧烈持续的腹痛合并不明显的腹部体征，肠鸣音及肠蠕动一般减弱。麻痹性肠梗阻（B错）的腹胀明显，腹痛不明显，阵发性绞痛尤为少见，肠鸣音消失。痉挛性肠梗阻（C错）很少见，多见于急性肠炎、肠道功能紊乱或慢性铅中毒病人，腹痛在痉挛时表现为持续性，同时可出现肠鸣音亢进，但不会出现金属音调。","","N"],["2010-N77",3,"第一节 外科休克概述","补充血容量",2010,77,"A","","下列治疗休克的措施中，最重要的是",[["A","应用血管活性药"],["B","补充血容量"],["C","纠正酸碱平衡失调"],["D","保持合适的体位并吸氧"]],"B","休克是指机体有效循环血容量减少、组织灌注不足，细胞代谢紊乱和功能受损的病理过程，它是一个由多种病因引起的综合征。休克的本质是氧供给不足和需求增加；休克的特征是产生炎症介质；休克的共同点是机体有效循环血量减少；休克的救治原则首先是补充血容量。上述知识点是对休克及其治疗最根本的概括。补充血容量，从源头上解决有效循环血量不足的问题，为最重要的措施（B对）。血管活性药（A错）是在血容量已补足、血压仍旧无法上升的情况下使用；酸碱平衡失调（C错）通常可以随着血容量的补足、机体的自我调节而被纠正；保持合适的体位并吸氧（D错）属于一般性治疗，并非最重要。","","N"],["2010-N78",2,"第二节 输血的不良反应及其防治","溶血反应治疗",2010,78,"A","","患者误输异型血后无尿2天，无休克，此时最有效的治疗是",[["A","输注甘露醇"],["B","血液透析"],["C","注射地塞米松"],["D","静注大量速尿"]],"B","根据输入异型血即可断定发生溶血反应。溶血反应后大量红细胞被破坏，血红蛋白被释放入血液，血红蛋白通过肾排出时，易于沉淀阻塞肾小管，造成肾功能的损伤，故溶血早期可给予碳酸氢钠静滴以碱化尿液，促血红蛋白溶解；当血容量已基本补足，尿量基本正常时，应用甘露醇等药物利尿（AD错）；当肾功能损害严重、出现少尿无尿，或者氮质血症、高钾血症时，则给予透析治疗（B对）。透析能够快速改善血液状态、清除血液中有毒有害物质，用于无尿等特殊情况。此外溶血反应的治疗还包括扩容抗休克、输入成分血、应用激素（地塞米松）（C错）等一般治疗，出现DIC给予肝素，危重病人行血浆交换。","","N"],["2010-N79",27,"第四节 肠梗阻","粘连性肠梗阻病因和病理",2010,79,"A","","下列关于腹膜粘连的叙述中，错误的是",[["A","多为腹腔手术或炎症的后果"],["B","粘连可引起肠梗阻"],["C","粘连越广，肠梗阻越重"],["D","目前尚无有效的预防粘连的方法"]],"C","腹膜粘连多为腹腔手术或炎症的后果（A对），腹腔手术后，或急性腹膜炎症时，腹膜可分泌大量的渗出液。渗出液中的纤维蛋白沉积在病变周围，发生粘连，以防止感染的扩散并修复受损的组织，因此造成腹腔内的广泛纤维性粘连，导致肠管成角、扭曲或成团，因而粘连可引起肠梗阻（B对）。腹膜粘连是一种正常的生理反应，目前尚无有效的预防粘连的方法（D对），但部分认为清除手套上的滑石粉、不遗留异物于腹腔，手术轻柔等可一定程度上减少粘连。粘连越广，发生肠梗阻的几率越大，并不是肠梗阻越严重（C错，为本题正确答案），因为有些粘连带即使很小，也可导致严重的绞窄性肠梗阻；有些很大的片状粘连带，可能并不引起肠梗阻。肠排列可用于治疗部分粘连性肠梗阻，即将肠袢有序粘连，此时患者肠粘连范围仍广，但并无明显肠梗阻。","","N"],["2010-N80",33,"第二节 胰腺炎","急性胰腺炎诊断",2010,80,"A","","男性、75岁，总胆管结石行ERCP和EST取石术后3小时，出现上腹痛并恶心、呕吐，剑突下压痛。最可能的诊断是",[["A","急性胰腺炎"],["B","急性胆囊炎"],["C","急性胆管炎"],["D","急性乳头炎"]],"A","经内镜逆行胰胆管造影（ERCP）是将纤维十二指肠镜插至十二指肠降部，找到十二指肠大乳头，由活检管道内插入塑料导管至乳头开口部，注入造影剂后X线摄片，以显示胰胆管。由于操作过程中要将导管经乳头插入胆管、胰管及其共同通道，可造成胆汁逆流入胰管，从而诱发急性胰腺炎（A对）。该患者已将胆总管结石取出，解除了胆道梗阻，因此术后发生急性胆管炎（C错）的几率较小。ERCP操作并不牵涉胆囊，一般不会诱发急性胆囊炎（B错）。急性乳头炎（D错）并不是ERCP的常见并发症。","","N"],["2010-N81",33,"第三节 胰腺囊性疾病","胰腺假性囊肿临床表现(1)",2010,81,"A","","下列关于胰腺假性囊肿的叙述中，正确的是",[["A","多继发于腹部外伤"],["B","囊壁上皮可分泌粘液"],["C","主要体征是上腹包块"],["D","诊断后尽早手术切除"]],"C","胰腺假性囊肿多是急性胰腺炎所引起的，少数由腹部损伤引起（A错）。肿块形成过程如下：胰腺实质或胰管破裂，胰液外溢，伴随血性和炎性渗液，刺激胰腺周围的腹膜，引起纤维组织增生逐渐形成囊壁将其包裹。囊壁上没有上皮细胞覆盖，因此无分泌的功能（B错）。主要体征是上腹包块（C对），表现为上腹部半球形、光滑，不移动，囊性感的肿物，合并感染时有发热和触痛。胰腺假性囊肿经检查除外恶性后，可暂予非手术治疗。其外科治疗的适应证包括：①出现出血、感染、破裂、压迫等并发症；②囊肿增大（≥6cm）；③非手术治疗无效；④多发性囊肿；⑤囊肿壁厚；⑥合并慢性胰腺炎及胰管狭窄。一般须待囊肿壁成熟后（6周以上）再作内引流或外引流术（D错）。","","N"],["2010-N82",34,"第一节 上消化道大出血的诊断和处理","病因处理",2010,82,"A","","肝炎后肝硬化病人，有黄疸和大量腹水，因大量呕血入院。下列治疗措施中，不宜采取的是",[["A","三腔管压迫"],["B","立即手术"],["C","输血，静脉滴注垂体加压素"],["D","曲张静脉套扎、硬化"]],"B","对于有黄疸、大量腹水、肝功能严重受损的病人发生大出血，尤其是对肝功能储备Child C级的病人，如果立即手术（B错，为本题正确答案），死亡率很高，可达60～70%。对于这类病人应尽量采用非手术治疗。三腔管压迫（A对）止血是急诊治疗的有效方法，通过充气气囊压迫胃底和食管下段出血部位行压迫止血，控制出血率可达40～90%。由于在放气后有再次出血可能，仅适用于无法控制的大出血，或等待做进一步治疗的病人。输血可补充病人的血容量，而垂体加压素促使内脏小动脉收缩，血流量减少，从而减少了门静脉血的回流量，降低了门静脉压，使出血速度降低，有利于血栓形成，从而达到止血作用（C对）。经内镜曲张静脉套扎术是在套扎局部产生缺血性坏死和形成浅溃疡，急性无菌性炎症累及曲张静脉内膜，局部产生血栓，导致静脉曲张闭塞；联合硬化剂注射术，通过硬化剂注入产生的无菌性炎症诱发血栓的生成，其效果可达到食管黏膜下层，使黏膜下层纤维化，并可栓塞食管旁静脉的穿支静脉，从而提高内镜治疗的效果（D对）。","","N"],["2010-N83",17,"第四节 颈部肿块","甲状舌管囊肿",2010,83,"A","","女性，16岁。1个月前发现颈前有1个圆形肿物，近日肿物部位红肿疼痛，6天前破溃，流出黄色黏液样液体，伤口无愈合迹象。最可能的诊断是",[["A","颈部淋巴结结核"],["B","甲状舌管囊肿"],["C","甲状腺腺瘤"],["D","囊状淋巴管瘤"]],"B","颈部淋巴结结核（A错）一般于单侧或双侧胸锁乳突肌的前、后缘有多个大小不等的肿大淋巴结，且无红热及疼痛表现，均与患者临床表现不符。甲状腺腺瘤（C错）患者多为女性，年龄常在40岁以下，一般为甲状腺腺体内的圆形或椭圆形单发结节，表面光滑，边界清楚，质地韧实，与周围组织无粘连，可随吞咽上下移动，但无压痛和红肿表现。囊状淋巴管瘤（D错）又称囊状水瘤，颈后三角为好发部位，肿物突出皮肤，直径一般为4～6cm，光滑而柔软，波动感明显，边缘多不清楚，无触痛和红肿表现。甲状舌管囊肿（B对）好发于儿童和青少年，约50%的病例发生于20岁之前，绝大多数患者可见颈前位于舌骨以下的囊肿，舌骨体与囊肿之间可触及坚韧的索条与舌骨体粘连可随伸舌运动上下移动，若形成通口腔的窦道，则食物、口腔细菌等易进入囊腔中，细菌滋生，造成局部组织的炎性反应，而后化脓性改变、脓液破溃溢出体表。","","N"],["2010-N84",20,"第三节 肺肿瘤","腺癌",2010,84,"A","","目前发病率最高的肺癌病理类型是",[["A","大细胞癌"],["B","小细胞癌"],["C","鳞癌"],["D","腺癌"]],"D","十版外科学认为腺癌为最常见的肺癌（D对）。九版病理学（P204）认为鳞癌是肺癌中的最常见类型，需注意不同科目间答案的不同。","","N"],["2010-N85",10,"第三节 全身麻醉","通气不足",2010,85,"A","","麻醉中发现CO₂蓄积，如排出速度过快，最可能出现的临床表现是",[["A","血压下降，呼吸暂停"],["B","血压下降，呼吸变快"],["C","血压上升，呼吸变快"],["D","血压上升，呼吸变慢"]],"A","（八版生理学P182）CO₂蓄积主要出现酸中毒的临床表现：血液PH下降刺激颈动脉体和主动脉体，使得心率增快、血压升高以加速血液流动，代偿机体组织缺氧状态；呼吸加大加深，以排出过量的CO₂。当CO₂迅速排出后，血液酸中毒解除，使得机体血压下降；但是对于呼吸来说，中枢化学感受器在CO₂引起的通气反应中起主要作用，CO₂的迅速排出使得血液中PCO₂下降过快，低PCO₂的血液到达脑部，呼吸中枢因缺少足够的CO₂刺激而受到抑制，于是呼吸变慢变浅甚至停止（A对）。对于因高PCO₂引起昏迷的病人，切不可通过快速通气排出CO₂，应缓慢低流量持续给氧，以维持血液低O₂对外周化学感受器的刺激维持呼吸。","","N"],["2010-N86",25,"第一节 急性弥漫性腹膜炎","急性弥漫性腹膜炎腹部体征",2010,86,"A","","下列选项中，最能提示化脓性腹膜炎病情加重的临床指标是",[["A","腹式呼吸消失"],["B","腹肌紧张加重"],["C","腹痛加重"],["D","腹胀加重"]],"D","化脓性腹膜炎如不及时治疗或继续加重，则可因严重的电解质紊乱和毒素影响，造成肠道的蠕动功能减弱甚至消失，加之腹水的不断生成，使得腹胀加重，此为病情恶化的重要标志（D对）。腹式呼吸消失为急性化脓性腹膜炎的一般体征（A错）。腹肌紧张的程度随病因和病人的全身状况不同而不同，因此腹肌紧张加重不能作为病情加重的指标（B错）。腹痛程度与炎症轻重、年龄、身体素质有关，有些病情危重者可能因反应较差而无腹痛主诉，因此腹痛加重也不能作为病情加重的指标（C错）。","","N"],["2010-N87",26,"第三节 胃十二指肠溃疡的外科治疗","毕Ⅰ术式",2010,87,"A","","男性，57岁，胃窦部溃疡直径1．5cm，内科治疗8周无效，应采取的手术方式是",[["A","毕I式胃大部切除术"],["B","毕Ⅱ式胃大部切除术"],["C","选择性迷走神经切断术"],["D","高选择性迷走神经切断术"]],"A","由胃窦部溃疡直径1.5cm可知胃溃疡直径较小，且位于较为常见的胃窦部。胃溃疡由于胃酸常不增高，因而首选切胃量较少，且不改变消化道正常生理结构的毕Ⅰ式胃大部切除术（A对）。高胃酸的十二指肠溃疡常选用切胃量较多的毕Ⅱ式胃大部切除术（B错）。此外，选择性迷走神经切断术（C错）及高选择性迷走神经切断术（D错）亦可选用，但一般不作首选术式。","","N"],["2010-N88",46,"第一节 手外伤","组织修复",2010,88,"A","","手部开放性损伤后，早期清创缝合不应超过的时间是",[["A","4小时"],["B","8小时"],["C","12小时"],["D","16小时"]],"B","手部外伤后，应尽早彻底清创。清创应力争在6～8小时内进行，可减少组织损伤，在细菌大量繁殖并入侵机体前清除其存在场所，将污染伤口变为清洁伤口。超过8小时，微生物的数量将迅速增加，造成严重的污染，不宜再行清创术。","","N"],["2010-N89",44,"第四节 骨折愈合过程","骨折临床愈合标准概述",2010,89,"A","","男性，20岁，右肱骨干骨折2个月，外固定已拆除。提示骨折已愈合的临床表现是",[["A","X线片显示骨折线模糊，有连续骨痂"],["B","局部有轻微异常活动"],["C","有纵向叩痛，但无局部压痛"],["D","患肢平举0.5kg重物可持续1分钟"]],"A","骨折临床愈合的标准为①局部无压痛及纵向叩击痛（C错）；②局部无异常活动；③X线平片显示骨折处有连续性骨痂，骨折线已模糊（A对）。局部存在异常活动（B错）为骨折的特有体征之一。记忆技巧：对于骨折愈合标准，可概括为几个字：不痛、不动、看不清、负重不变形。过去的教材中还有一条标准：外固定解除后，上肢向前平举1kg重量达1分钟（D错）；下肢能不扶拐在平地连续步行3分钟，不少于30步，连续观察两周骨折处不变形。由于影像学技术的发展和负重实验本身所具有的一定危险性，负重试验已渐渐淡出临床，但是在老题目中出现相关选项时，仍旧可以作为备选答案。","","N"],["2010-N90",44,"第七节 骨折的治疗原则","骨折治疗概述",2010,90,"A","","女性，72岁，因车祸来院。查体：右下肢外旋、短缩畸形，X线平片示：右股骨颈头下型骨折，部分移位。既往有高血压、服药控制在130～140/80～90mmHg。最适宜的治疗方法是",[["A","右下肢持续牵引、对症治疗"],["B","切开复位内固定"],["C","手法复位，石膏固定"],["D","人工关节置换"]],"D","右下肢持续牵引、对症治疗（A错）及手法复位，石膏固定（C错）等非手术治疗多用于年龄过大，全身情况差，合并有严重心、肺、肾、肝功能障碍不能耐受手术者，患者虽老年，但是血压控制尚可，采取手术治疗可以迅速降低患者的疾病风险。对于全身情况尚好的高龄病人的股骨头下型骨折，最适宜的治疗方法是人工关节置换（D对），术后短期内便可恢复日常一般活动与行动能力。虽然切开复位也是治疗股骨颈骨折的有效方法，适用于部分闭合复位失败者，但是患者为老年人，且发生的是股骨颈头下型骨折部分移位，该骨折骨折线位于股骨头下，股骨头仅有小凹动脉很少量的血液供应，单纯行切开复位固定（B错）容易发生缺血性骨坏死，影响患者愈后。","","N"],["2010-N111",29,"第三节 乙状结肠扭转","乙状结肠扭转诊断",2010,111,"A","","男性，80岁，6小时前晨练后突发左下腹痛，恶心未吐，2天来尚未排便，既往无大病。查体：腹胀，左下腹有压痛，未及明显肿块，肠鸣音亢进，直肠指检阴性。该患者最可能的诊断是",[["A","缺血性肠病"],["B","乙状结肠扭转"],["C","小肠扭转"],["D","肠系膜动脉栓塞"]],"B","老年男性患者，晨练后突发左下腹痛，停止排气排便2天，进展为持续性疼痛，且患者无明显呕吐，诊断考虑乙状结肠扭转（B对）。乙状结肠扭转常见于乙状结肠冗长，有便秘的老年人，运动后导致轴心固定位置且有一定重量的肠袢发生扭转，扭转肠段肠系膜亦随之扭转，导致其血供减少，属于绞窄性肠梗阻。局部代谢产物堆积，刺激肠壁内的神经，引起持续性腹痛。缺血性肠病（A错）和肠系膜动脉栓塞（D错）多见于老年人，早期腹部绞痛、恶心呕吐频繁，无腹部膨隆、腹胀等典型阳性体征，即“症征不符”。小肠扭转（C错）多见于青壮年，腹痛常位于脐周，呕吐较频繁，腹胀一般不明显，与该患者表现不符。","c36","N"],["2010-N112",29,"第三节 乙状结肠扭转","乙状结肠扭转诊断",2010,112,"A","","男性，80岁，6小时前晨练后突发左下腹痛，恶心未吐，2天来尚未排便，既往无大病。查体：腹胀，左下腹有压痛，未及明显肿块，肠鸣音亢进，直肠指检阴性。对该患者的诊断和治疗有价值的措施是",[["A","扩血管药物"],["B","选择性动脉造影"],["C","钡灌肠"],["D","胃肠减压"]],"C","诊断乙状结肠扭转首选X线钡灌肠（C对），可见扭转部位钡剂受阻，钡影尖端呈“鸟嘴”形。对于部分早期乙状结肠扭转，钡剂灌肠也是一种有效的治疗方法，可通过灌注物引起的膨胀力量使得扭转的肠道恢复。扩血管药物（A错）为一般性对症治疗，并不能从根本上治愈疾病。选择性腹腔动脉造影（B错）主要用于诊断肠系膜动脉栓塞以及部分病因难以明确的上消化道出血。胃肠减压（D错）对低位乙状结肠扭转的意义不大。","c36","N"],["2010-N113",6,"第四节 治疗原则","通气",2010,113,"A","","男性，30岁，40分钟前骑摩托车摔伤，急送来院。神志朦胧，烦躁不安，四肢乱动，呼吸困难，咯血，口鼻均有泥沙夹血外溢，左侧胸腹部、左大腿严重擦伤、肿胀、左大腿大面积瘀血斑。此时最紧迫的急救措施是",[["A","吸氧"],["B","输血"],["C","应用止血药物"],["D","通畅呼吸道"]],"D","病人有“呼吸困难，咯血，口鼻均有泥沙夹血外溢”表现，血液、泥沙等易阻塞呼吸道造成窒息并危及生命，故预防呼吸道梗阻和窒息应当作为首要任务来处理。因此通畅呼吸道是最紧迫的急救措施，清理口、鼻腔后给予经口气管插管或气管切开（D对）。吸氧（A错）、应用止血药物（C错）为一般对症支持治疗，不是最急迫的治疗。输血（B错）主要用于大失血、休克时，患者仅有咯血和淤血，无大失血，不需输血。","c37","N"],["2010-N114",44,"第二节 骨折的临床表现及影像学检查","骨折的一般表现",2010,114,"A","","男性，30岁，40分钟前骑摩托车摔伤，急送来院。神志朦胧，烦躁不安，四肢乱动，呼吸困难，咯血，口鼻均有泥沙夹血外溢，左侧胸腹部、左大腿严重擦伤、肿胀、左大腿大面积瘀血斑。来院时，可首先排除的损伤是",[["A","颅脑损伤"],["B","左股骨骨折"],["C","血气胸"],["D","脾破裂"]],"B","对于骑摩托车摔伤的病人，神志朦胧，烦躁不安提示可能存在颅脑损伤（A错）。呼吸困难提示可能存在血气胸（C错）。左侧胸腹部擦伤提示可能存在脾破裂（D错）。但患者存在四肢乱动表现，说明四肢运动功能仍然存在，故可首先排除左股骨骨折（B对）。","c37","N"],["2010-N115",32,"第五节 胆道感染","急性梗阻性化脓性胆管炎实验室检查",2010,115,"A","","女性，35岁，反复发作右上腹痛伴寒战、发热4年，3天前再次出现同样症状。查体：体温40．5℃，脉搏130次/分，血压62/46mmHg，嗜睡，巩膜黄染，右上腹压痛及肌紧张，肝区叩痛明显。该患者可能出现的血常规化验结果是",[["A","白细胞总数升高，中性粒细胞比例下降"],["B","白细胞总数下降，中性粒细胞比例下降"],["C","白细胞总数升高，血小板计数下降"],["D","白细胞总数下降，血小板计数升高"]],"C","急性重症胆管炎的致病菌主要为革兰阴性菌，以大肠杆菌、克雷伯菌最常见，因此外周血白细胞总数升高，中性粒细胞比例增高，血小板计数可下降（C对）。","c38","N"],["2010-N116",32,"第五节 胆道感染","急性梗阻性化脓性胆管炎诊断",2010,116,"A","","女性，35岁，反复发作右上腹痛伴寒战、发热4年，3天前再次出现同样症状。查体：体温40．5℃，脉搏130次/分，血压62/46mmHg，嗜睡，巩膜黄染，右上腹压痛及肌紧张，肝区叩痛明显。对该患者最可能的诊断是",[["A","重症胆管炎、肝内外胆管结石"],["B","化脓性胆囊炎"],["C","肝脓肿"],["D","重症胰腺炎"]],"A","32岁女性（胆囊结石多见于女性），反复发作右上腹痛伴寒战、发热（结石性胆囊炎的典型表现）。3天前症状再次发作，伴有高热、脉快、休克、嗜睡及黄疸，右上腹压痛及肌紧张，肝区叩痛明显（典型的Reynolds五联征），诊断考虑重症胆管炎，肝内外胆管结石为最常见病因（A对）。化脓性胆囊炎（B错）常见表现为右上腹绞痛，可有畏寒，一般不会引起黄疸及血压下降。肝脓肿（C错）病程较短，可有畏寒高热，肝区叩痛，右上腹压痛及肌紧张，但不会出现血压降低、黄疸、嗜睡等症状。重症胰腺炎（十版外科学P488）（D错）多为左上腹及腰背部痛，左上腹压痛，黄疸一般不重。","c38","N"],["2010-N117",32,"第五节 胆道感染","急性梗阻性化脓性胆管炎非手术治疗",2010,117,"A","","女性，35岁，反复发作右上腹痛伴寒战、发热4年，3天前再次出现同样症状。查体：体温40．5℃，脉搏130次/分，血压62/46mmHg，嗜睡，巩膜黄染，右上腹压痛及肌紧张，肝区叩痛明显。经输液扩容及应用血管活性药物后，病情无明显好转，在手术前还应采取的主要措施是",[["A","加大升压药剂量"],["B","更换有效抗生素"],["C","加快输液"],["D","纠正酸中毒"]],"D","感染性休克常伴代谢性酸中毒，酸性内环境对心肌、血管平滑肌和肾功能均有抑制作用，故在给予扩容和血管活性药物均无起色的情况下应注重内环境的调节，纠正酸中毒（D对）。升压药通过缩血管作用提高血压，严重酸中毒时血管对升压药反应欠佳，加大升压药剂量（A错）可导致血管过度收缩，组织灌流量降低。经输液扩容及应用血管活性药物后，病情无明显好转，单纯加快输液（C错）并不能纠正休克，反而可能导致CVP过高，加重心脏和循环负担。重症胆管炎须选用敏感抗生素，但是更换有效抗生素（B错）缓解休克早期效果欠佳，抢救休克是当前病人的主要矛盾。","c38","N"],["2010-N118",53,"第二节 腰椎退行性疾病","感觉异常",2010,118,"A","","男性，38岁，3年前诊断为腰椎间盘突出症，腰腿痛反复发作，行卧床、牵引等保守治疗可缓解。查体：外踝及足外侧痛觉、触觉减退，趾及足跖屈肌力减弱，跟腱反射减弱。该患者最可能受累的神经根是",[["A","腰3"],["B","腰4"],["C","腰5"],["D","骶1"]],"D","腰椎间盘突出累及骶1神经根，表现为小腿后外侧及外踝、足外侧区感觉障碍，趾及足跖屈无力，踝反射减弱或消失。结合患者神经系统表现，该患者最可能受累的神经根是骶1（D对）。腰3神经根（A错）受累时表现为股骨内髁感觉障碍，伸膝无力，膝反射减弱或消失。腰4神经根（B错）受累时表现为小腿前内侧及膝前感觉障碍，伸膝无力，膝反射减弱或消失。腰5神经根（C错）受累时表现为小腿前外侧及足背内侧感觉障碍，足趾背伸乏力或不能。","c39","N"],["2010-N119",53,"第二节 腰椎退行性疾病","MRI",2010,119,"A","","男性，38岁，3年前诊断为腰椎间盘突出症，腰腿痛反复发作，行卧床、牵引等保守治疗可缓解。查体：外踝及足外侧痛觉、触觉减退，趾及足跖屈肌力减弱，跟腱反射减弱。患者搬重物后突发疼痛加重，伴大小便障碍，应即刻进行的检查是",[["A","腰椎正侧位X线片"],["B","腰椎过伸过屈位X线片"],["C","腰椎双斜位X线片"],["D","腰椎磁共振扫描"]],"D","患者搬重物后突发疼痛加重，伴大小便障碍，提示椎间盘突出加重，出现马尾综合征，应立即行腰椎核磁共振扫描（D对），能清楚地显示出人体解剖结构的图像，对于腰椎间盘突出的诊断有极大帮助。MRI可以全面地观察各椎间盘的退变情况，也可以了解髓核突出的程度和位置，并鉴别是否存在椎管内其他占位性病变。腰椎正侧位X线片（A错）、腰椎过伸过屈位X线片（B错）、腰椎双斜位X线片（C错）不能直接反映腰椎间盘突出，仅可看到腰椎侧弯、生理性前凸减少或消失等间接征象，部分病人可见纤维环钙化、骨质增生、关节突肥大、硬化等退变表现。","c39","N"],["2010-N120",53,"第二节 腰椎退行性疾病","腰椎间盘突出症手术方法",2010,120,"A","","男性，38岁，3年前诊断为腰椎间盘突出症，腰腿痛反复发作，行卧床、牵引等保守治疗可缓解。查体：外踝及足外侧痛觉、触觉减退，趾及足跖屈肌力减弱，跟腱反射减弱。患者搬重物后突发疼痛加重，伴大小便障碍，若诊断为椎间盘突出症，最适宜的处理方法是",[["A","持续牵引，理疗"],["B","髓核化学溶解术"],["C","椎间盘切除术"],["D","皮质激素硬膜外注射"]],"C","对于已确诊腰椎间盘突出症的患者，一旦出现马尾综合征，即有手术指征。该患者出现大小便障碍，提示马尾综合征，因此最适宜的处理方法是椎间盘切除术（C对）。持续牵引，理疗（A错）、髓核化学溶解术（B错）、皮质激素硬膜外注射（D错）均为非手术治疗，适用于初次发病且病程较短的病人。","c39","N"],["2010-N145",18,"第三节 乳腺良性疾病","导管内乳头状瘤临床表现",2010,145,"B","","导管内乳头状瘤时，常出现的乳头溢液是",[["A","血性溢液"],["B","黄色或黄绿色溢液"],["C","浆液性无色溢液"],["D","棕褐色溢液"]],"A","乳头溢液的性质对于判断疾病性质有帮助，常见的溢液性质与疾病需掌握。导管内乳头状瘤大多数发生于大乳管近乳头的壶腹部，瘤体很小，带蒂而有绒毛，且有很多壁薄的血管，故易出血，常出现的乳头溢液是血性溢液（A对）。黄色或黄绿色溢液（B错）常见于乳腺囊性增生病和乳腺癌，浆液性无色溢液（C错）常见于正常生理现象（如月经期或早期妊娠）和乳腺囊性增生病。棕褐色溢液（D错）常见于乳腺囊性增生病，若恶性疾病乳管阻塞，出血堆积混合坏死组织，也会形成棕褐色溢液。","","N"],["2010-N146",18,"第三节 乳腺良性疾病","乳腺囊性增生病临床表现",2010,146,"B","","正常月经期时，常出现的乳头溢液是",[["A","血性溢液"],["B","黄色或黄绿色溢液"],["C","浆液性无色溢液"],["D","棕褐色溢液"]],"C","浆液性无色溢液（C对）常见于正常生理现象（如月经期或早期妊娠）和乳腺囊性增生病。血性溢液（A错）可见于导管内乳头状瘤、导管内癌、乳腺囊性增生病等。黄色或黄绿色溢液（B错）常见于乳腺囊性增生病，棕褐色溢液（D错）常见于乳腺囊性增生病，若恶性疾病乳管阻塞，出血堆积混合坏死组织，也会形成棕褐色溢液。","","N"],["2010-N147",29,"第十一节 肛瘘","挂线疗法",2010,147,"B","","高位单纯性肛瘘的治疗方法是",[["A","瘘管切开"],["B","挂线疗法"],["C","肛瘘切除"],["D","切开联合挂线"]],"B","肛瘘很难自愈，多需手术治疗。其手术方法较多，选择何种手术为宜，应根据肛瘘是否累及肛管括约肌，或累及括约肌的多少来定。无论选择何种手术，其原则是在有效治疗肛瘘的同时，应尽量不损伤肛管括约肌，以免肛门失禁。挂线疗法（B对）最常用，适用于距离肛门3-5cm的低位肛瘘，或单纯性高位肛瘘。利用橡皮筋或有腐蚀作用的药线的机械性压迫作用，缓慢切开肛瘘，使肌肉组织一边坏死，一边愈合，从而避免被切断的肛直肠环回缩引起肛门失禁。肛瘘切开术（十版外科学P433）（A错）适用于低位复杂性肛瘘。肛瘘切除术（十版外科学P434）（C错）适用于低位单纯性肛瘘。瘘管切开+挂线疗法，即切开联合挂线法（D错），适用于高位复杂性肛瘘。","","N"],["2010-N148",29,"第十一节 肛瘘","肛瘘切除术",2010,148,"B","","低位单纯性肛瘘的治疗方法是",[["A","瘘管切开"],["B","挂线疗法"],["C","肛瘘切除"],["D","切开联合挂线"]],"C","肛瘘很难自愈，多需手术治疗。其手术方法较多，选择何种手术为宜，应根据肛瘘是否累及肛管括约肌，或累及括约肌的多少来定。无论选择何种手术，其原则是在有效治疗肛瘘的同时，应尽量不损伤肛管括约肌，以免肛门失禁。肛瘘切除术（C对）适用于低位单纯性肛瘘。瘘管位置较低，直接切除不会损伤括约肌，预后较好。肛瘘切开术（十版外科学P433）（A错）适用于低位复杂性肛瘘。挂线疗法（十版外科学P434）（B错）最常用，适用于距离肛门3-5cm的低位肛瘘，或单纯性高位肛瘘。瘘管切开+挂线疗法，即切开联合挂线法（D错），多用于高位复杂性肛瘘的治疗。","","N"],["2010-N149",50,"第四节 周围神经卡压综合征","肘管综合征应用解剖",2010,149,"B","","肘管综合征损伤的神经是",[["A","桡神经深支"],["B","桡神经浅支"],["C","尺神经"],["D","正中神经"]],"C","腕管综合征是正中神经（十版外科学P696）在腕管内受压而表现出的一组症状和体征，表现为拇、示、中指感觉过敏或迟钝，鱼际肌萎缩，拇对掌无力，腕部正中神经Tinel征阳性。肘管综合征（C对）是指尺神经在肘部尺神经沟内因慢性损伤而产生的一组症状和体征，表现为手背尺侧、小鱼际、小指及环指尺侧半感觉异常，小指收展无力及手指收、展不灵活，环小指可呈爪形手畸形。梨状肌综合征（十版外科学P698）是指坐骨神经在臀部受到卡压出现的一组症状和体征，表现为坐骨神经痛，体查可发现小腿轻度萎缩，小腿以下皮肤感觉异常。","","N"],["2010-N150",50,"第四节 周围神经卡压综合征","腕管综合征应用解剖",2010,150,"B","","腕管综合征损伤的神经是",[["A","桡神经深支"],["B","桡神经浅支"],["C","尺神经"],["D","正中神经"]],"D","腕管综合征是正中神经（D对）在腕管内受压而表现出的一组症状和体征，表现为拇、示、中指感觉过敏或迟钝，鱼际肌萎缩，拇对掌无力，腕部正中神经Tinel征阳性。肘管综合征（十版外科学P697）是指尺神经在肘部尺神经沟内因慢性损伤而产生的一组症状和体征，表现为手背尺侧、小鱼际、小指及环指尺侧半感觉异常，小指收展无力及手指收、展不灵活，环小指可呈爪形手畸形。梨状肌综合征（十版外科学P698）是指坐骨神经在臀部受到卡压出现的一组症状和体征，表现为坐骨神经痛，体查可发现小腿轻度萎缩，小腿以下皮肤感觉异常。","","N"],["2010-N175",7,"第一节 热力烧伤","吸入性损伤",2010,175,"X","","下列病情中，有助于诊断吸入性烧伤的有",[["A","在密闭空间的烧伤"],["B","面部烧伤重，眉毛、鼻毛烧焦"],["C","受伤时曾大声呼叫"],["D","伤后声嘶，咽部充血"]],"ABCD","吸入性损伤的诊断依据：①于密闭室内发生的烧伤（A对）；②面、颈和前胸部烧伤，特别是口、鼻周围深度烧伤（B对）；③鼻毛烧焦，口唇肿胀，口腔、口咽部红肿有水泡或黏膜发白者；④刺激性咳嗽，痰中有炭屑；⑤声嘶、吞咽困难或疼痛（D对）；⑥呼吸困难和（或）哮鸣；⑦纤维支气管镜检查发现气道黏膜充血、水肿、黏膜苍白、坏死、剥脱等，是诊断吸入性损伤最直接和准确的方法。患者受伤时曾大声呼叫，易于吸入烟雾中的多种化学物质而发生吸入性烧伤，有助于诊断吸入性烧伤（C对）。","","N"],["2010-N176",41,"第一节 泌尿系统结石概述","泌尿系统结石病因",2010,176,"X","","尿石症与胆石症的共同点有",[["A","钙代谢异常"],["B","发病率与地域有关"],["C","结石含一定数量的钙"],["D","可用体外碎石法治疗"]],"BC","钙代谢异常，尿中钙离子浓度过高，易于形成钙盐结石；但是胆结石的主要成分是胆色素和胆固醇，故钙代谢异常（A错）对于尿石症有影响，但是对于胆石症无影响。虽然钙代谢异常对于胆石症没有特殊影响，但是胆结石中也结合了一定量的Ca²⁺（无论是否钙代谢异常均有）；尿路结石多见草酸钙及磷酸钙成分，均含有大量的钙（C对）。尿石症和胆石症的发病率与地域有关（B对），我国南方地区尿石症发病率明显高于北方，西北地区胆囊结石发病率明显高于全国水平。体外冲击波碎石是上尿路结石治疗常用的方法，其破碎后易于自输尿管向下排出，但是对于胆结石，一般不行冲击波碎石，以手术治疗（D错）为主。","","N"],["2010-N177",32,"第四节 胆石症","肝内胆管结石临床表现",2010,177,"X","","肝内胆管结石的特征有",[["A","多发于右肝"],["B","常同时有肝外胆管结石"],["C","单侧胆管阻塞可无黄疸"],["D","多表现为肝区和胸背部疼痛"]],"BCD","肝内胆管结石是胆管结石的一种类型，是指左右肝管汇合部以上各分枝胆管内的结石。由于胆管解剖位置的关系，左侧结石比右侧多见（A错），左侧最常见的部位是左外叶、右侧为右后叶，与此两肝叶的肝管与肝总管汇合的解剖关系导致的引流不畅相关。肝内胆管结石易进入胆总管并发肝外胆管结石（B对）。单侧胆管阻塞时，由于病变范围较小，其余肝组织可代偿此部分肝组织的功能，可不出现黄疸（C对）。肝内胆管结石引起的胆管阻塞、胆汁淤积可出现疼痛，多表现为肝区和胸背部疼痛（D对）。","","N"],["2010-N178",17,"第一节 甲状腺疾病","药物准备",2010,178,"X","","甲状腺功能亢进症手术治疗前，药物准备的方法有",[["A","先用硫脲类药物后改用碘剂"],["B","单独使用碘剂"],["C","普萘洛尔与碘剂合用"],["D","单独使用普萘洛尔"]],"ABCD","碘剂可阻断甲状腺激素的释放，是甲亢术前准备的主要药物，其服用方法有：1.单独使用碘剂，但是根据十版外科学（P235），甲亢术前准备的药物准备已删除“单用碘剂”，所以B选项存在争议。2.先服用碘剂2周，如症状减轻不明显，可加用硫氧嘧啶类药物，待症状基本控制后，停用硫氧嘧啶类药物，继续服用碘剂1～2周，再进行手术。3.先服用硫脲类药物（可抑制甲状腺素的合成），待症状基本控制后，改服碘剂1～2周再进行手术（A对），此法运用于基础代谢率很高、甲亢症状不易控制的患者。普萘洛尔是β受体阻滞剂（在外周可阻断T₄转化为T₃），能减慢心率，快速降低基础代谢率，控制甲亢症状、缩短术前准备时间。普萘洛尔需要单独使用（C错D对），术后逐渐停药。本题官方给出的参考答案为ABCD，但根据最新临床观点，应选择AD。","","N"],["2010-N179",57,"第二节 良性骨肿瘤","骨样骨瘤",2010,179,"X","","下列肿瘤中，属于骨组织的良性肿瘤有",[["A","脊索瘤"],["B","软骨瘤"],["C","骨肉瘤"],["D","骨样骨瘤"]],"BD","原发骨肿瘤中，良性比恶性多见。常见的良性骨肿瘤包括骨瘤、骨样骨瘤、内生软骨瘤、骨软骨瘤。软骨瘤（B对）是一种松质骨的、透明软骨组织构成的、软骨源性的良性肿瘤，好发于手和足的管状骨。骨样骨瘤（D对）是一种孤立性、圆形的、成骨性的良性肿瘤，以疼痛为主，较少见。恶性骨肿瘤包括骨肉瘤（C错）、软骨肉瘤、尤因肉瘤、浆细胞性骨髓瘤、恶性淋巴瘤和骨纤维肉瘤。脊索瘤（十版外科学P767）（A错）是一种先天性的，来源于残余的胚胎性脊索组织的恶性肿瘤。","","N"],["2010-N180",44,"第七节 骨折的治疗原则","解剖复位",2010,180,"X","","下列骨折中，治疗需要达到解剖复位的有",[["A","三踝骨折"],["B","肱骨干骨折"],["C","肱骨髁间骨折"],["D","胫骨平台骨折"]],"ACD","骨折的复位包括功能复位和解剖复位。解剖复位是指骨折段通过复位，恢复正常的解剖关系，对位对线良好。功能复位是指经复位后，两骨折段虽未恢复至正常的解剖关系，但在骨折愈合后对肢体功能无明显影响者。三踝骨折（A对）、肱骨髁间骨折（C对）、胫骨平台骨折（D对）都属于关节内骨折，分别累及踝关节、肘关节、膝关节，若不能实现解剖复位，骨折愈合后容易遗留关节面不平整，长期磨损容易引起创伤性关节炎，致使关节活动时出现疼痛，影响患者生活质量。肱骨干骨折（B错）要求功能复位即可。","","N"],["2011-N77",10,"第五节 椎管内麻醉","适应证和禁忌证",2011,77,"A","","腰麻的绝对禁忌证是",[["A","休克"],["B","肾脏疾病"],["C","慢性肝炎"],["D","有普鲁卡因过敏史"]],"A","腰麻是具有一定风险的医疗操作，患者存在上述症状时，进行腰麻，会使得风险几率大大增加甚至危害病人生命，故需掌握如上的禁忌证。局麻药本身不具有肝肾毒性，且酰胺类局麻药在肝内代谢，酯类局麻药由血浆假性胆碱酯酶代谢，故肾脏疾病、慢性肝炎、肝功能尚可者均不是腰麻禁忌证（BC错）。对于有普鲁卡因（为酯类局麻药）过敏者，可以选用酰胺类局麻药物，此类药物极少发生过敏反应（D错）。腰麻时会导致麻醉区域的血管扩张，回心血量减少，导致血压下降。因此，休克（A对）为绝对禁忌。","","N"],["2011-N78",32,"第四节 胆石症","胆总管切开取石、T管引流术",2011,78,"A","","T型管拔出后患者出现持续性右上腹痛伴肌紧张，最可能的原因是",[["A","胆道痉挛"],["B","胆汁性腹膜炎"],["C","急性胆管炎"],["D","急性胰腺炎"]],"B","患者拔管后出现持续性右上腹痛伴肌紧张（腹膜刺激征表现），最可能的原因是胆汁自瘘口漏出，引起胆汁性腹膜炎（B对）。胆道痉挛（A错）的疼痛多为阵发性，不会引起腹肌紧张，且胆道痉挛一般与拔除T管无关。急性胆管炎（C错）典型表现为Charcot三联征，即腹痛、寒战高热、黄疸，一般不会出现腹肌紧张。T管引流将多余胆汁引流出体外，同时将残留胆石引流排除，去除了胰腺炎的发病因素，拔管后一般不会引起急性胰腺炎（D错）。","","N"],["2011-N79",32,"第四节 胆石症","胆囊结石治疗",2011,79,"A","","对胆囊结石患者，目前最好的治疗方法是",[["A","胆囊切开取石"],["B","药物溶石"],["C","胆囊切除术"],["D","体外碎石"]],"C","胆囊结石的外科治疗最常用的手术方法仍然是胆囊切除术（C对）。胆囊结石患者75%～90%可合并慢性胆囊炎，胆囊可发生不同程度的萎缩，此时胆囊已失去浓缩及排泄胆汁的生理功能，只有手术切除胆囊，才能彻底消除结石的产生。胆囊切开取石（A错）术后复发率高，且引起胆汁性腹膜炎的可能性较大。药物溶石（B错）疗法通过口服鹅脱氧胆酸或熊脱氧胆酸，通过改变胆汁的成分促进结石的自我溶解，但总体而言其疗效差、肝毒性大、服药时间长、复发率高。体外碎石（D错）常用于肾结石及上段输尿管结石及肾结石的治疗，在胆囊结石病人中用之甚少，且可导致胆管结石形成；碎石后若残留较大结石，需再次碎石治疗。","","N"],["2011-N80",13,"第二节 术后处理","静脉输液",2011,80,"A","","患者，男，50岁。昨日在全麻下进行右半结肠切除术，全天胃肠减压量800ml，尿量2000ml，今晨电解质正常。今日输液的最佳方案应是",[["A","5%葡萄糖盐水1500ml+10%葡萄糖2500ml"],["B","5%葡萄糖盐水2000ml+10%葡萄糖2800ml"],["C","5%葡萄糖盐水1000ml+10%葡萄糖2500ml"],["D","5%葡萄糖盐水1500ml+10%葡萄糖1000ml"]],"D","外科病人补液量＝每日生理需要量+累积损失量+日损失量。正常成年人每日生理需要量为2000ml，包含氯化钠4.5g（相当于5%葡萄糖盐水500ml）+1500ml 10%葡萄糖溶液。累积损失量指发病至开始治疗这部分时间，因各种原因导致的水和电解质丢失。病人排尿2000ml为正常排尿，未提及病人有脱水症状，因此该病人累积损失量为0。该病人日损失量为全天胃肠减压量800ml，丢失大量含电解质的消化液，故可用5%葡萄糖盐水适当补充这部分损失的含电解质溶液。补液总量＝每日生理需要量+累积损失量+日损失量＝（10%葡萄糖溶液1500ml+5%葡萄糖盐水500ml）+0+5%葡萄糖盐水800ml=5%葡萄糖盐水1300ml+10%葡萄糖溶液1500ml。从临床考虑，由于患者无法进食且电解质丢失严重，故可适当增加电解质溶液所占的比例，由选项可知5%葡萄糖盐水1500ml+10%葡萄糖1000ml为最接近的选项（D对）。","","N"],["2011-N81",33,"第三节 胰腺囊性疾病","胰腺假性囊肿诊断",2011,81,"A","","患者，男，50岁，2个月前饮酒后剧烈腹痛，住院30天后好转，近日上腹稍左发现一包块，有轻度压痛，此患者应高度怀疑为",[["A","胰腺假性囊肿"],["B","脾脏肿瘤"],["C","胰腺炎性包块"],["D","胰腺恶性肿瘤"]],"A","中年男性患者，饮酒后剧烈腹痛入院，提示有饮酒引起的急性胰腺炎病史。近日出现左上腹包块，有轻压痛，最大可能为胰腺假性囊肿（A对）。胰腺假性囊肿多是急性胰腺炎引起，少数才是由腹部外伤引起。胰腺实质或胰管破裂，胰液外溢，伴随血性和炎性渗液，刺激胰腺周围的腹膜，引起纤维组织增生逐渐形成囊壁将其包裹，因囊壁上没有上皮细胞覆盖，故称假性囊肿。脾脏肿瘤（B错）临床少见，且与本例病史不符合。胰腺炎性包块（C错），一般有高热及剧烈的腹膜刺激征，与该患体征不符。急性胰腺炎不会引起恶变，不考虑胰腺恶性肿瘤（D错）。","","N"],["2011-N82",17,"第二节 甲状旁腺功能亢进的外科治疗","原发性甲状旁腺功能亢进",2011,82,"A","","下列关于甲状旁腺功能亢进的叙述，错误的是",[["A","原发性甲状旁腺功能亢进中，80%是由单发甲状旁腺腺瘤引起"],["B","慢性肾衰竭可引起甲状旁腺功能亢进"],["C","甲状旁腺素（PTH）的分泌受垂体控制"],["D","甲状旁腺癌也可引起甲状旁腺功能亢进"]],"C","甲状旁腺功能亢进有原发和继发的两种。原发性甲状旁腺功能亢进是由于甲状旁腺增生、腺瘤或腺癌（D对）自主性地分泌过多的PTH，不受血钙的反馈作用（C错，为本题正确答案），使血钙持续增高所致。慢性肾衰竭患者，肾小球滤过率降低，尿磷排泄障碍，导致血磷增高。高血磷会与钙形成磷酸钙沉淀于软组织，使血钙降低，刺激PTH的分泌，诱发继发性甲状旁腺功能亢进（B对）。甲状旁腺瘤约占原发性甲状旁腺功能亢进的80%，多为单发腺瘤（A对），多发腺瘤少于1%～5%。","","N"],["2011-N83",8,"第一节 肿瘤概述","化学治疗",2011,83,"A","","目前单独应用化疗治疗效果最佳的肿瘤是",[["A","霍奇金淋巴癌"],["B","乳腺癌"],["C","儿童急性淋巴细胞白血病"],["D","粒细胞白血病"]],"C","化疗是化学药物治疗的简称，通过使用化学治疗药物杀灭癌细胞达到治疗目的。化疗是目前治疗癌症最有效的手段之一，和手术、放疗一起并称癌症的三大治疗手段。化疗曾经被作为辅助治疗用于手术前后，随着临床研究的发展，已发现部分肿瘤可通过单独的化疗完全治愈。首选化疗的恶性肿瘤，可记忆为“大伯培养小林到高中”，其意思是大：大细胞淋巴瘤，伯：Burkitt淋巴瘤，培：胚胎性横纹肌肉瘤，养：恶性滋养细胞瘤，小：小细胞肺癌，林：急性淋巴细胞白血病（C对），高：睾丸精原细胞瘤，中：中枢神经系统淋巴瘤。霍奇金淋巴癌（A错）、乳腺癌（B错）、粒细胞白血病（D错）等肿瘤应用化疗可使肿瘤获缓解或使肿瘤缩小，或可使手术范围缩小以尽可能多地保留器官功能，而这些肿瘤不能单独应用化疗治愈。","","N"],["2011-N84",13,"第三节 术后并发症的防治","术后发热与低体温",2011,84,"A","","直肠癌根治术后第一天，病人突然寒战高热，达39℃，最可能的原因是",[["A","伤口感染"],["B","肺炎"],["C","腹腔感染"],["D","输液反应"]],"D","发热是术后最常见的症状，但术后发热一般不一定表示发生感染，由于细菌的繁殖需要时间达到一定数量方能引起症状，故非感染性发热通常比感染性发热来得早，分别平均在术后1.4天和2.7天。另外伤口感染应有伤口红肿痛及脓性分泌物表现（A错）；腹腔感染除了发热外，会出现腹膜刺激征（C错）；肺炎患者除发热外，肺部存在湿啰音、咳嗽咳痰（B错）。术后一天内突发寒战高热首先应想到输血或输液反应的可能（D对）。","","N"],["2011-N85",24,"第一节 腹部损伤概述","腹部损伤临床表现",2011,85,"A","","下列情况中，腹膜刺激征最轻的是",[["A","消化道穿孔"],["B","脾破裂"],["C","急性胆囊炎"],["D","急性重症胰腺炎"]],"B","不同的体液具有不同的理化性质，对于腹膜的刺激也是不同的，通常是胃液、胆汁、胰液刺激最强，肠液次之，血液最轻。脾破裂（B对）以血液漏入腹膜腔为主，刺激性最低，引起的腹膜刺激征也是最轻的。消化道穿孔（A错）导致胃液、小肠液以及混合了胆汁及胰液的各种液体漏入腹膜腔，可引起严重的腹膜刺激征。急性胆囊炎（C错）漏入腹腔的主要是局部炎症产物，对腹膜刺激亦较强，腹膜刺激征亦较重。急性重症胰腺炎（D错）漏出液为混合了炎症产物的胰液，可引起强烈的腹膜刺激征。","","N"],["2011-N86",27,"第四节 肠梗阻","是单纯性还是绞窄性梗阻",2011,86,"A","","下列肠梗阻表现中，揭示发生肠绞窄可能性较小的是",[["A","发病急，疼痛重而持续"],["B","腹膜刺激征明显，有休克表现"],["C","呕吐物为血性液体"],["D","有多次腹部手术史，反复发作腹痛"]],"D","在临床工作中，若患者出现下列表现，应考虑绞窄性肠梗阻的可能：（一）发病急，疼痛重而持续（A错）。有时出现腰背部痛。（二）腹膜刺激征明显，有休克表现（B错），抗休克治疗后改善不明显。（三）有腹膜炎的表现，体温上升、脉率增快、白细胞计数增高。（四）腹胀不对称，腹部有局部隆起或触及有压痛的肿块（孤立胀大的肠袢）。（五）呕吐出现早而频繁，呕吐物、胃肠减压抽出液、肛门排出物为血性（C错）。腹腔穿刺抽出血性液体。（六）腹部X线检查见孤立扩大的肠袢。（七）经积极的非手术治疗症状体征无明显改善。有多次腹部手术史，反复发作腹痛（D对），提示为粘连性肠梗阻可能性大，因多次手术导致腹膜损伤，形成肠管间粘连，肠管蠕动受限。","","N"],["2011-N87",29,"第六节 结肠癌","结肠癌并发急性肠梗阻的手术",2011,87,"A","","患者，75岁，肠梗阻5天急行手术探查，术中发现结肠脾曲癌致结肠梗阻，无转移征象，横结肠扩张、水肿，恰当的手术方式是",[["A","横结肠造口术、二期左半结肠切除"],["B","左半结肠切除、横结肠乙状结肠吻合术"],["C","肿瘤切除、横结肠造口术"],["D","横结肠、乙状结肠侧侧吻合术"]],"A","75岁男性患者（高龄患者），肠梗阻5天，术中发现横结肠扩张水肿。患者此时全身一般情况很差，宜行横结肠造口解除梗阻，待全身情况好转后二期行左半结肠切除（A对）。左半结肠切除、横结肠乙状结肠吻合术（B错）为一期手术，患者此时全身及肠道情况差，强行进行一期手术可导致吻合口愈合不良，可引起肠瘘。患者身体状况较差，难以耐受一期肿瘤切除、横结肠造口术（C错）。横结肠、乙状结肠侧侧吻合术（D错）虽旷置肿瘤，解除了梗阻，但因横结肠局部条件差，术后易发生吻合口瘘，故不宜采用。","","N"],["2011-N88",47,"第二节 股骨近端骨折","股骨颈骨折病因和分类",2011,88,"A","","下列关于股骨颈骨折的叙述，错误的是",[["A","老年股骨颈骨折不易发生缺血坏死"],["B","头下型骨折易出现缺血坏死"],["C","基底型骨折不易出现缺血坏死"],["D","缺血坏死可发生在骨折数年后"]],"A","股骨颈骨折若损伤了营养股骨头的血管支，则会导致股骨头的血供变差，老年人又是血液循环较差的群体，更易于发生股骨头缺血性坏死（A错，为本题正确答案）。股骨颈头下型骨折骨折线位于股骨头下，股骨头仅有小凹动脉很少量的供血，致使股骨头严重缺血，发生股骨头缺血坏死的机会很大（B对）。股骨颈基底骨折的骨折线位于股骨颈与大、小转子间连线处。由于有旋股内、外侧动脉分支吻合成的动脉环提供血液循环，对骨折部血液供应的干扰较小，骨折容易愈合（C对）。骨折后发生的缺血坏死属于骨折的晚期并发症，可发生在骨折后数月甚至数年后（D对）。","","N"],["2011-N89",54,"第一节 化脓性骨髓炎","急性化脓性骨髓炎概述",2011,89,"A","","急性血源性骨髓炎症多见的部位是",[["A","股骨下段"],["B","掌骨"],["C","髂骨"],["D","胫骨下端"]],"A","急性血源性骨髓炎多继发于身体其他部位的感染性病灶。机体抵抗力下降或原发灶处理不当，细菌可进入血液发生菌血症或诱发脓毒症。菌栓进入骨营养动脉后，往往受阻于长骨干骺端的毛细血管内并在局部繁殖，引起急性血源性骨髓炎。骺板附近的微小终末动脉与毛细血管往往弯曲形成血管襻，使得该处血流缓慢，细菌容易沉积，成为骨髓炎的好发部位。据统计，急性血源性骨髓炎以胫骨上段和股骨下段最多见（A对），其次为肱骨与髂骨，脊柱与其他四肢骨骼都可以发病，肋骨和颅骨少见。","","N"],["2011-N90",57,"第三节 骨巨细胞瘤","骨巨细胞瘤概述",2011,90,"A","","下列关于骨巨细胞瘤的叙述，错误的是",[["A","好发于20～40岁"],["B","局部肿胀包块"],["C","好发于膝关节上、下骨端"],["D","多属恶性"]],"D","骨巨细胞瘤属于交界性肿瘤（D错，为本题正确答案），恶性程度介于良性和恶性之间。骨巨细胞瘤好发于20～40岁（A对）人群，女性多见。好发部位为长骨干骺端和椎体，特别好发于膝关节上、下骨端（C对）及肱骨近端。主要症状为疼痛和肿胀包块（B对），与病情发展相关。局部肿块压之有乒乓球感觉和压痛，病变的关节活动受限。","","N"],["2011-N111",22,"第四节 静脉疾病","深静脉血栓形成诊断",2011,111,"A","","患者，男，60岁，10天前行胃癌根治术，近5天来体温38℃左右，胸片正常，尿常规未见异常，腹部伤口愈合好，已拆线，上腹部B超未见积液，查体发现左小腿微肿，腓肠肌有压痛。可能的诊断是",[["A","左下肢肌筋膜炎"],["B","左膝关节炎"],["C","左下肢深静脉血栓形成"],["D","左下肢浅静脉炎"]],"C","60岁男性患者，10天前行胃癌根治术（手术术后需卧床，为静脉血栓发病的高危因素），5天来体温38℃左右。查体：发现左小腿微肿，腓肠肌有压痛（提示左下肢淤血）。胸片正常，尿常规正常，腹部伤口愈合好，上腹部B超未见积液（基本排除了肺部、切口以及腹部的感染的可能）。综合该患者的病史、体查、实验室检查及影像学检查，诊断考虑左下肢深静脉血栓形成（C对）。左下肢肌筋膜炎（A错）是肌肉组织与其筋膜组织的非特异性炎症，临床表现为反复的慢性肌肉疼痛、下肢酸软无力。左膝关节炎（B错）表现为左膝部的疼痛等症状。左下肢浅静脉炎（D错）表现为沿浅静脉分布的充血肿胀、发硬。","c47","N"],["2011-N112",22,"第四节 静脉疾病","深静脉血栓形成预防和治疗",2011,112,"A","","患者，男，60岁，10天前行胃癌根治术，近5天来体温38℃左右，胸片正常，尿常规未见异常，腹部伤口愈合好，已拆线，上腹部B超未见积液，查体发现左小腿微肿，腓肠肌有压痛。对该患者不宜采取的措施",[["A","手术"],["B","抗凝"],["C","抬高患肢"],["D","多做下肢运动"]],"D","下肢深静脉血栓的患者，若发病较早（3～5天以内），可以进行手术（A对）取栓。其他对症治疗手段包括抗凝（B对），抬高患肢（C对）促进静脉回流。但是不宜多做下肢运动（D错，为本题正确答案），以免血栓脱落造成肺栓塞。但在尚未形成下肢静脉血栓的患者，则鼓励进行适量的下肢活动，以免因长时间制动而形成静脉血栓。","c47","N"],["2011-N113",28,"第二节 急性阑尾炎","急性阑尾炎临床诊断",2011,113,"A","","患者，女，35岁，2天前开始腹痛，先上腹后脐周，有阵发性加剧，伴恶心，呕吐2次胃内容物，腹泻3～5次/日，稀便。查体：体温37．5℃，下腹中部压痛，轻度肌紧张，肠鸣音活跃。化验血WBC12．5×10⁹/L，大便常规WBC2～4。腹部X线平片未见膈下游离气体，中下腹可见数个气液平面。最可能的诊断是",[["A","急性阑尾炎"],["B","急性胃肠炎"],["C","急性盆腔炎"],["D","急性肠梗阻"]],"A","患者先上腹后脐周的腹痛，为典型的转移性腹痛。患者下腹中部压痛，轻度肌紧张，说明有固定点压痛；非右下腹部压痛，是由于阑尾位置的个体差异所决定的，不能据此排除急性阑尾炎诊断。加上血象升高、胃肠道刺激症状、大便常规白细胞增多等症状，急性阑尾炎为本例最可能的诊断（A对）。急性胃肠炎（B错）为肠道功能紊乱引起，并非真正意义上的炎症，可有腹痛、呕吐、腹泻等症状，但一般不会有血象增高，大便脓细胞阳性。急性盆腔炎（C错）主要表现为下腹疼痛及直肠刺激征，与本例不符。急性肠梗阻（D错）患者常有停止排气、排便症状，与题目不符。","c48","N"],["2011-N114",28,"第二节 急性阑尾炎","急性阑尾炎影像学检查",2011,114,"A","","患者，女，35岁，2天前开始腹痛，先上腹后脐周，有阵发性加剧，伴恶心，呕吐2次胃内容物，腹泻3～5次/日，稀便。查体：体温37．5℃，下腹中部压痛，轻度肌紧张，肠鸣音活跃。化验血WBC12．5×10⁹/L，大便常规WBC2～4。腹部X线平片未见膈下游离气体，中下腹可见数个气液平面。该患者腹部X线平片出现气液平面的原因是",[["A","为肠梗阻的表现"],["B","为腹泻的表现"],["C","有肠麻痹"],["D","盆腔炎症刺激所致"]],"B","患者先上腹后脐周的腹痛，为典型的转移性腹痛。患者下腹中部压痛，轻度肌紧张，说明有固定点压痛；非右下腹部压痛，是由于阑尾位置的个体差异所决定的，不能据此排除急性阑尾炎诊断。加上血象升高、胃肠道刺激症状、大便常规白细胞增多等症状，急性阑尾炎为本例最可能的诊断。肠梗阻（A错）虽可出现气液平面，但该患者并无肠梗阻典型停止排气、排便症状，故不考虑此原因。肠麻痹（C错）引起麻痹性肠梗阻时，可出现气液平面，但该患者肠鸣音活跃，可排除肠麻痹可能。盆腔炎症刺激（D错）主要表现为大便次数增多，里急后重等，一般不会出现气液平面。关于腹泻是否能引起气液平面，十版教材未明确说明，可能由于病人肠道本身存在一定的气体，又发生腹泻，稀便成为X线片的液相部分，故可出现气液平面（B对）。","c48","N"],["2011-N115",17,"第一节 甲状腺疾病","术后呼吸困难和窒息",2011,115,"A","","患者，女，30岁。甲亢行甲状腺次全切除术。返回病房2小时后感气憋，心慌，急查见患者面色发绀，呼吸急促，30次/分，血压136/90mmHg，脉率120次/分，伤口部饱满，张力高。该患者最可能发生的并发症是",[["A","创面出血压迫气管"],["B","喉返神经损伤"],["C","喉上神经损伤"],["D","甲状旁腺损伤"]],"A","术后呼吸困难和窒息是术后最危急的并发症。多发生在术后48小时内。此患者返回病房2小时后感气憋、心慌、面色发绀，为呼吸困难表现；再由伤口部饱满，张力高，不难推测是由于创面出血压迫气管（A对）导致呼吸困难。喉返神经（B错）含支配声带的运动神经纤维，一侧喉返神经损伤引起声嘶，双侧喉返神经损伤可造成呼吸困难，甚至窒息，但伤口不会饱满，张力高；且喉返神经损伤引发的呼吸困难一般发生于术中。喉上神经损伤（C错）若损伤外支会使环甲肌瘫痪，引起声带松弛，音调降低；内支损伤，则喉部黏膜感觉丧失，进食特别是饮水时，容易误咽发生呛咳，一般不会引起呼吸困难。甲状旁腺损伤（D错）时，PTH分泌减少，血钙浓度下降，可引起，面部、唇部或手足部的针刺样麻木感或强直感，严重者可出现面肌和手足伴有疼痛的持续性痉挛，每天发作多次，每次持续10～20分钟或更长，严重者可发生喉和膈肌痉挛，引起窒息，但患者没有痉挛和抽搐等症状，因此不考虑甲状旁腺损伤。","c49","N"],["2011-N116",17,"第一节 甲状腺疾病","术后呼吸困难和窒息",2011,116,"A","","患者，女，30岁。甲亢行甲状腺次全切除术。返回病房2小时后感气憋，心慌，急查见患者面色发绀，呼吸急促，30次/分，血压136/90mmHg，脉率120次/分，伤口部饱满，张力高。应立即采取的措施是",[["A","急做B超"],["B","立即拆除缝合线"],["C","急查血钙"],["D","静脉注射氯化钙20ml"]],"B","患者颈部肿胀，多为切口内出血所引起。发现上述情况时，必须立即床旁抢救，及时切开缝线（B对），敞开切口，迅速除去血肿，解除对气管的压迫；如此时病人呼吸仍无改善，则应立即施行气管插管。因此，术后应常规的在病人床旁放置无菌的气管插管和手套，以备急用。急做B超（A错）、急查血钙（C错）对于迅速解除气道梗阻无作用。静脉注射氯化钙20ml（D错）可迅速提高血钙浓度，用于急救甲状旁腺损伤、出现手足抽搐者。","c49","N"],["2011-N117",17,"第一节 甲状腺疾病","术后呼吸困难和窒息",2011,117,"A","","患者，女，30岁。甲亢行甲状腺次全切除术。返回病房2小时后感气憋，心慌，急查见患者面色发绀，呼吸急促，30次/分，血压136/90mmHg，脉率120次/分，伤口部饱满，张力高。进一步的治疗是",[["A","急送手术室探查止血"],["B","急送手术室修复受损神经"],["C","加强补钙，并予DT₁₀治疗"],["D","密切观察"]],"A","通过急救患者情况好转，但内出血的病因尚未解决，需再送手术室进一步的探查止血（A对），术后予以其他一般支持治疗及密切观察（D错）。急送手术室修复受损神经（B错）可用于治疗甲状腺手术引起的喉上神经及喉返神经损伤。加强补钙，并予DT₁₀治疗（C错）可用于治疗手术损伤甲状旁腺引起的低钙血症。","c49","N"],["2011-N118",55,"第二节 脊柱结核","脊柱肿瘤",2011,118,"A","","患者，男，52岁。双下肢无力，行走受限2月。检查：T₉压痛，叩痛明显，脐以下痛觉减退，下肢不能自主活动，足趾可微动，病理征阳性。X线射片见T₉椎弓根及椎体后缘显影不清，未见软组织肿大阴影。对该患者的可能诊断是",[["A","T₉肿瘤"],["B","T₉转移瘤"],["C","T₉结核"],["D","T₉骨髓炎"]],"B","52岁男性患者，双下肢无力，行走受限2月。体查：T₉压痛，叩痛明显（提示T₉节段存在病变），脐以下痛觉减退，下肢不能自主活动，足趾可微动，病理征阳性（病变压迫脊髓，累及锥体系）。X线射片见T₉椎弓根及椎体后缘显影不清，未见软组织肿大阴影（脊柱肿瘤的典型影像学表现）。综合该患者的病史、体查及影像学检查，诊断考虑T₉转移瘤（B对）并脊髓受压。原发性T₉肿瘤（A错）临床上少见，一般不作优先考虑。T₉结核（十版外科学P742）（C错）一般先累及椎体，后累及椎弓根，椎间隙狭窄，常见椎旁软组织影，且有低热、盗汗等结核中毒症状，与患者表现不符。T₉骨髓炎（十版外科学P731）（D错）起病急骤，寒战后高热，可达39℃以上，多有明显感染中毒症状，患处存在明显的疼痛、红肿，与患者表现不符。","c50","N"],["2011-N119",55,"第二节 脊柱结核","MRI",2011,119,"A","","患者，男，52岁。双下肢无力，行走受限2月。检查：T₉压痛，叩痛明显，脐以下痛觉减退，下肢不能自主活动，足趾可微动，病理征阳性。X线射片见T₉椎弓根及椎体后缘显影不清，未见软组织肿大阴影。为明确诊断，首选的影像学检查是",[["A","胸椎CT"],["B","胸椎正、侧、斜位X线片"],["C","全身骨骼同位素扫描"],["D","胸椎MRI"]],"D","脊柱转移癌伴脊髓受压患者的影像学检查首选胸椎MRI（D对），可显示骨质受累及脊髓受压情况。胸椎CT（A错）虽能较好地显示骨质破坏情况，但无法显示脊髓受压情况。胸椎正、侧、斜位X线片（B错）不能很好地显示细微的骨质破坏、脊髓受压及椎间盘病变情况。全身骨骼同位素扫描（C错）诊断骨肿瘤敏感性高，但亦不能显示脊髓受压情况。","c50","N"],["2011-N120",55,"第二节 脊柱结核","CT",2011,120,"A","","患者，男，52岁。双下肢无力，行走受限2月。检查：T₉压痛，叩痛明显，脐以下痛觉减退，下肢不能自主活动，足趾可微动，病理征阳性。X线射片见T₉椎弓根及椎体后缘显影不清，未见软组织肿大阴影。如经上述影像学检查仍不能确诊，应进一步采取的检查方法是",[["A","开胸探查取活组织病理"],["B","胸椎后外侧入路探查活检"],["C","CT引导下穿刺活检"],["D","B超引导下穿刺活检"]],"C","若影像学无法确诊，则需行组织病理学检查以明确诊断。CT引导下穿刺活检（C对）可在较小的创伤下取得病理标本；B超引导下穿刺活检（D错），准确性不及CT引导下的穿刺。脊柱肿瘤未能确诊时，一般不会手术探查，因此不考虑开胸探查取活组织病理（A错）及胸椎后外侧入路探查活检（B错）。","c50","N"],["2011-N145",19,"第一节 胸部损伤概论","院内急诊处理",2011,145,"B","","下述疾病中，急需手术探查的是",[["A","开放性气胸"],["B","闭合性气胸"],["C","进行性血气胸"],["D","张力性气胸"]],"C","持续大量出血所致胸膜积血称为进行性血胸，伤者会出现不同程度的低血容量休克表现、胸腔积液表现和胸部X线表现，应及时作开胸探查手术（C对），否则，出血难以自止，保守治疗不能纠正休克。开放性气胸（A错）急救处理要点为：将开放性气胸立即变为闭合性气胸。闭合性气胸（B错）发生缓慢且积气量少的病人，不需要特殊处理，胸腔内的积气一般可在1～2周内自行吸收；大量闭合性气胸需进行胸膜腔穿刺，或行胸腔闭式引流术。张力性气胸（D错）入院前或院内急救需迅速使用粗针头穿刺胸膜腔减压，并外接单向活瓣装置，进一步处理应安置闭式胸腔引流。","","N"],["2011-N146",19,"第三节 气胸","开放性气胸临床表现",2011,146,"B","","下述病例中，可引起纵隔扑动的是",[["A","开放性气胸"],["B","闭合性气胸"],["C","进行性血气胸"],["D","张力性气胸"]],"A","开放性气胸时，外界空气经胸壁伤口或软组织缺损处，随呼吸自由进出胸膜腔；呼、吸气时，出现两侧胸膜腔压力不均衡的周期性变化，使纵膈在吸气时移向健侧，呼气时移向伤侧，称为纵膈扑动（A对）。闭合性气胸（B错）、进行性血气胸（C错）、张力性气胸（D错）纵膈均向健侧移位。","","N"],["2011-N147",32,"第十一节 胆道恶性肿瘤","胆囊癌临床表现",2011,147,"B","","下述疾病中，一般无发热症状的是",[["A","急性胆囊炎"],["B","肝内胆管结石"],["C","胆囊癌"],["D","肝脓肿"]],"C","急性胆囊炎（十版外科学P472）（A错）为胆囊的炎症性病变，炎症释放炎性介质，可导致机体轻度至中度发热。肝内胆管结石（十版外科学P471）（B错）通常以梗阻症状为主，常可继发急性胆管炎，可引起寒战高热和腹痛。肝脓肿（十版外科学P444）（D错）常见为细菌性肝脓肿，主要症状是寒战、高热、肝区疼痛和肝肿大。胆囊癌（C对）是胆道最常见的恶性病变，在未形成梗阻和周围浸润的情况下，无特异性症状：不伴感染则无发热症状。","","N"],["2011-N148",32,"第十一节 胆道恶性肿瘤","胆囊癌临床表现",2011,148,"B","","下述疾病中，一般转氨酶不升高的是",[["A","急性胆囊炎"],["B","肝内胆管结石"],["C","胆囊癌"],["D","肝脓肿"]],"C","急性胆囊炎（十版外科学P472）（A错）时，胆囊炎症对肝功能有一定影响，可使血清丙氨酸转移酶、碱性磷酸酶常升高。肝内胆管结石（十版外科学P471）（B错）通常以梗阻症状为主，常可继发急性胆管炎，引起寒战高热和腹痛，肝功能酶学检查异常。肝脓肿（D错）为肝脏的化脓性病变，坏死及炎症波及的肝细胞死亡释放出大量转氨酶，血清转氨酶浓度升高。胆囊癌（C对）是胆道最常见的恶性病变，在未形成梗阻和周围浸润的情况下，无特异性症状：不伴感染则无发热症状；不伴梗阻则无黄疸和肝酶升高；病人实验室检查可见CEA、CA19-9、CA125等升高，以CA19-9最敏感。","","N"],["2011-N149",53,"第一节 颈椎退行性疾病","脊髓空洞症",2011,149,"B","","有助于鉴别脊髓型颈椎病与脊髓空洞症的检查方法是",[["A","X线颈椎平片"],["B","肌电图"],["C","痛温觉与触觉分离"],["D","MRI"]],"C","脊髓型颈椎病和脊髓空洞症均有感觉障碍，但发生的情况并不相同，脊髓型颈椎病痛温觉、触觉同时发生障碍，产生麻木等感觉和运动异常；而脊髓空洞症由于从脊髓中心白质部分先发生病变，白质由上行传导神经纤维组成，主要负责传导痛温觉，故该类病人会有感觉分离现象，即痛温觉丧失，触压觉及精细触觉仍然存在（C对）。脊髓型颈椎病MRI可显示脊髓不同程度的受压情况，而脊髓空洞症MRI示脊髓内有与脑脊液相同之异常信号区，因此本题D亦对，但当年给出的答案为C。","","N"],["2011-N150",53,"第一节 颈椎退行性疾病","脊髓型颈椎病",2011,150,"B","","有助于鉴别脊髓型颈椎病与髓内肿瘤的检查方法是",[["A","X线颈椎平片"],["B","肌电图"],["C","痛温觉与触觉分离"],["D","MRI"]],"D","医学影像学的发展，使得脊髓型颈椎病与髓内肿瘤的鉴别变得简单，MRI可反映椎体病变、脊髓受压情况及有无变性，对鉴别诊断有决定意义（D对）。","","N"],["2011-N175",1,"第三节 钾代谢紊乱","高钾血症治疗",2011,175,"X","","血钾浓度过高时，可以降低血K⁺浓度的措施有",[["A","静脉注射5%碳酸氢钠100ml"],["B","静脉注射10%葡萄糖酸钙20ml"],["C","25%葡萄糖溶液200ml，每5g糖加入1U胰岛素，静脉输注"],["D","应用阳离子交换树脂15g，每日2~3次口服"]],"ACD","高钾血症有导致病人心搏突然停止的危险，故一经诊断需积极治疗。治疗方法主要概括为以下几点：1、停止一切含钾离子药物使用，防止血钾进一步升高；2、使用碳酸氢钠或乳酸钠溶液静滴（A对）；3、使用葡萄糖溶液及胰岛素（又称“极化液”）（C对），可促进K⁺与葡萄糖经共同转运体进入细胞内，降低血钾；4、口服阳离子交换树脂（D对），血液中浓度较高的钾透过肠壁与树脂中的阳离子交换，可促进钾经肠道排出，降低血钾；5、对于血钾高于6.5mmol/L或上述降钾治疗无效者，予透析治疗快速降钾；6、10％葡萄糖酸钙20ml缓慢静脉注射可促进钾离子进入细胞内，并拮抗高血钾对心脏的毒性作用，该方法起效快但持续时间短（B对）。有关高血钾的临床治疗措施，九、十版外科学相关内容有更新，根据九、十版外科学，本题答案为ABCD，原答案为ACD。","","N"],["2011-N176",13,"第二节 术后处理","引流管",2011,176,"X","","外科引流的主要目的有",[["A","引流渗血、渗液"],["B","引流脓液"],["C","预防吻合口漏"],["D","治疗吻合口漏"]],"ABD","外科引流是将组织裂隙、体腔等部位的液体引离原处和排出体外的方法。引流可将感染性液体/脓液和非感染性液体（如渗血、渗液、组织液等）引出体腔（AB对），减少术后感染的发生几率，从而加快伤口愈合。吻合口瘘的发生主要与手术中吻合不当或吻合不到位有关，与是否安放引流无关（C错）；一旦发生吻合口瘘，可进行引流将自瘘中流出的异物引流出体外，对瘘起到治疗作用（D对）。","","N"],["2011-N177",42,"第二节 尿路上皮肿瘤","膀胱肿瘤概述",2011,177,"X","","下列选项中，其发生率占膀胱肿瘤总数2%以上的有",[["A","移行细胞癌"],["B","肉瘤"],["C","腺癌"],["D","鳞癌"]],"ACD","膀胱肿瘤可分为上皮性肿瘤和非上皮性肿瘤，其中上皮性肿瘤是最常见的膀胱肿瘤，约占全部肿瘤的90%；其中移行上皮癌（A对）最为常见，占膀胱癌的90%，鳞癌较少见，占膀胱癌的3%～7%，腺癌比例更为少见，占膀胱癌的比例＜2%（三版八年制外科学P770）。根据四版本实用外科学P1889的观点，膀胱上皮来源的尿路上皮癌、鳞癌、腺癌，占全部肿瘤的95%以上，非上皮来源的肿瘤以及膀胱以外异位组织发生的横纹肌肉瘤、软骨瘤等均极少见。本题数据在各版本教材均有差别，原答案选择ACD。","","N"],["2011-N178",5,"第六节 有芽胞厌氧菌感染","气性坏疽病因",2011,178,"X","","下列关于气性坏疽的叙述，正确的有",[["A","是梭状芽孢杆菌所致的肌坏死或肌炎"],["B","常是几种细菌的混合感染"],["C","可出现黄疸"],["D","抗生素治疗最关键"]],"ABC","气性坏疽是厌氧菌感染的一种，即梭状芽胞杆菌所致的肌坏死或肌炎（A对），此类感染发展急剧，预后严重，感染发生时，往往不是单一细菌，而是几种细菌的混合（B对）。致病菌产生的外毒素可以引起严重毒血症及肌肉组织的广泛坏死。临床特点是病情急剧恶化，甚至出现溶血性贫血、黄疸（C对）、血红蛋白尿等全身症状并迅速恶化，故需尽早治疗，早期急诊清创（D错）是治疗的关键，必要时给予截肢以挽救生命。","","N"],["2011-N179",44,"第一节 骨折的定义、成因、分类及移位","嵌插骨折",2011,179,"X","","可不出现骨折特有体征的骨折有",[["A","裂缝骨折"],["B","嵌插骨折"],["C","青枝骨折"],["D","不完全骨折"]],"ABCD","不完全骨折（D对）包括青枝骨折（C对）和裂缝骨折（A对），是指骨的连续性和完整性部分中断，由于残存的骨质仍旧牢固连接，故骨的稳定性及正常形态尚存，可不出现畸形、异常活动以及骨擦音或骨擦感等骨折特有体征。嵌插骨折（B对）因骨质相互嵌插，不易发生相对移位，为稳定性骨折，一般不出现骨折的三个特有体征。","","N"],["2011-N180",55,"第三节 髋关节结核","托马斯征",2011,180,"X","","因软组织挛缩可出现Thomas征阳性的有",[["A","内收肌"],["B","髂腰肌"],["C","髂股韧带"],["D","髋关节前方关节囊"]],"BCD","Thomas征用来检查髋关节有无屈曲畸形。方法如下：病人平卧于检查床上，检查者将其健侧髋、膝关节完全屈曲，使膝部贴住或尽可能贴近前胸，此时腰椎前凸完全消失而腰背平贴于床面，若患髋存在屈曲畸形，即能一目了然，根据大腿与床面所成之角度，断定屈曲畸形为多少。除关节本身的因素如髋关节结核外，关节前部的软组织（髂腰肌）（B对）、髂股韧带（C对）、髋关节前部的关节囊（D对）挛缩均可出现Thomas征阳性。大腿内收肌群包括耻骨肌、长收肌、股薄肌、短收肌和大收肌5块肌肉，其主要作用是使髋关节内收，而Thomas征主要是检查髋关节有无屈曲畸形，因此内收肌挛缩不会出现Thomas征阳性（A错）。","","N"],["2012-N77",18,"第三节 乳腺良性疾病","乳腺囊性增生病诊断",2012,77,"A","","女性，38岁，因双乳胀痛伴肿块数年而就诊。查体：双乳可扪及多个大小不等的结节，质韧，同侧腋窝淋巴结无明显肿大，挤压乳头时有乳白色液体溢出，细胞学检查未发现异常细胞。最可能的诊断是",[["A","乳癌"],["B","乳房囊性增生"],["C","导管内乳头状瘤"],["D","乳腺结核"]],"B","乳房囊性增生病（B对）好发于中年妇女，突出表现为乳房胀痛和肿块，可累及一侧或双侧乳腺，肿块呈结节状、片状，质韧不硬，少数病人可有乳头溢液，本题女性，38岁，因双乳胀痛伴肿块数年而就诊，双乳可扪及多个大小不等的结节，质韧，挤压乳头时有乳白色液体溢出与之相符。乳癌（A错）多发于老年妇女，一般无乳房胀痛，肿块质硬、不平，常有腋窝淋巴结肿大，可有血性乳头溢液，细胞学检查常有癌细胞，本题细胞学检查未发现异常细胞，可排除乳癌。导管内乳头状瘤（C错）主要症状是乳头溢出血性液体，而无乳房胀痛，乳房肿块一般较小，本题双乳胀痛伴肿块数年，乳白色溢液与之不符。乳腺结核（D错）表现为单个或多个有痛或无痛性结节，常与皮肤有粘连，有结核中毒症状，与本题病史不符。","","N"],["2012-N78",29,"第六节 结肠癌","结肠癌临床表现",2012,78,"A","","大肠癌的好发部位是",[["A","横结肠"],["B","升结肠及结肠肝曲"],["C","降结肠及乙状结肠"],["D","直肠及乙状结肠"]],"D","大肠癌包括结肠和直肠癌，是我国常见的恶性肿瘤之一。大肠癌的好发部位依次为直肠（50%）、乙状结肠（20%）、盲肠、升结肠、横结肠和降结肠。因此，大肠癌的好发部位是直肠及乙状结肠（D对）。","","N"],["2012-N79",5,"第五节 脓毒症","脓毒症临床表现",2012,79,"A","","革兰阴性杆菌败血症的临床特点是",[["A","易并发心肌炎"],["B","感染性休克发生早、持续时间长"],["C","热型为稽留热或弛张热"],["D","常见可转移性脓肿"]],"B","革兰阴性杆菌的主要毒性是内毒素，虽然大多数抗生素都能杀菌，但对内毒素及其介导的多种炎症介质无效，因此，革兰性阴性杆菌所致的败血症一般病情严重，可出现三低现象（低温、低白细胞、低血压），感染性休克发生早且持续时间长（B对）。革兰阴性菌败血症可有发热，但多为间歇热（C错）。易并发心肌炎（A错）、稽留热或弛张热（C错）、转移性脓肿多见（D错），均为革兰阳性球菌败血症的特点。","","N"],["2012-N80",13,"第二节 术后处理","缝线拆除",2012,80,"A","","下列属于清洁伤口的是",[["A","甲状腺手术切口"],["B","胸部刀割伤后4小时清创伤口"],["C","头面部撞伤14小时的伤口"],["D","胃大部切除术的切口"]],"A","甲状腺手术为无菌手术，其切口属于清洁切口（A对）；而胸部刀割伤后4小时清创伤口（B错）、胃大部切除术的切口（D错），手术时可能带有污染，属于可能污染切口；头面部撞伤14小时的伤口（C错）属于污染切口。","","N"],["2012-N81",8,"第一节 肿瘤概述","二级预防",2012,81,"A","","下列措施中，属于癌症二级预防的是",[["A","减少职业性致癌物的暴露"],["B","改善生存质量，对症性治疗"],["C","改进烟草质量使之无害化"],["D","对高发区及高危人群定期检查"]],"D","恶性肿瘤是由环境、营养、饮食、遗传、病毒感染和生活方式等多种不同的因素相互作用而引起的，尚无有效的单一预防方法，此时恶性肿瘤的三级预防概念就相当重要。一级预防以避免诱发肿瘤的一切不良因素为主，即对因治疗；二级预防强调“三早”的重要性：早发现、早诊断、早治疗；三级预防目的是提高病人生存质量，延长生存期，即对症治疗。减少职业性致癌物的暴露（A错）是对因治疗，属于一级预防的范畴；改善生存质量，对症性治疗（B错）属于三级预防的范畴；改进烟草质量使之无害化（C错）属于无稽之谈。对高发区及高危人群定期检查（D对）满足“早发现”要求，属于癌症的二级预防。","","N"],["2012-N82",29,"第六节 结肠癌","结肠癌根治性手术",2012,82,"A","","男性，45岁，横结肠癌约4×4cm大小，已累及浆膜层，CT检查左肝外叶亦有3cm大小转移灶，胰腺正常。该病人的治疗应首选",[["A","仅行全身化学疗法"],["B","根治性结肠切除术"],["C","结肠造瘘术"],["D","根治性结肠切除+左肝外叶切除术"]],"D","结肠癌仅有肝转移者，根治性切除术后，有长期存活甚至治愈的可能。该患者结肠癌累及浆膜层，但未穿破肠壁，可以行根治性结肠切除术。CT示仅左肝外叶存在3cm转移灶，可以行左肝外叶切除术（D对B错）。术后可予以辅助化疗，可获得较好疗效。仅行全身化学疗法（A错）多用于晚期无法手术切除病灶的患者。结肠造瘘术（C错）主要用于治疗左侧结肠癌合并急性肠梗阻。","","N"],["2012-N83",24,"第二节 常见内脏损伤的特征和处理","脾损伤临床表现",2012,83,"A","","腹部外伤中最容易受损的器官是",[["A","肝"],["B","十二指肠"],["C","肾"],["D","脾"]],"D","“常见受损内脏在开放性损伤中依次是肝、小肠、胃、结肠、大血管等；在闭合性损伤中依次是脾、肾、小肠、肝、肠系膜等。胰、十二指肠、直肠等由于解剖位置较深，故损伤发生率较低”。因此，腹部开放性损伤最容易受损的器官是肝；腹部闭合性损伤中最容易受损的器官是脾；腹部外伤中最容易受损的器官是脾（D对）。请考生注意鉴别题目的不同问法。","","N"],["2012-N84",34,"第一节 上消化道大出血的诊断和处理","胃十二指肠溃疡",2012,84,"A","","并发大出血的胃十二指肠溃疡所在部位一般多见于",[["A","幽门或十二指肠球前壁"],["B","胃小弯或十二指肠球后壁"],["C","胃大弯或十二指肠外侧壁"],["D","胃底部或十二指肠球后部"]],"B","胃、十二指肠溃疡又称消化性溃疡，其出血占上消化道出血的40～50%，大出血的溃疡一般位于胃小弯或十二指肠球后壁（B对），都是由于溃疡基底血管被侵蚀破裂所致，多数为动脉性出血。","","N"],["2012-N85",26,"第二节 胃癌及其他胃肿瘤","胃癌淋巴转移",2012,85,"A","","恶性程度较高的胃癌可以跳跃式淋巴结转移，其中最常见的转移是",[["A","脾门淋巴结"],["B","肝总动脉淋巴结"],["C","腹腔淋巴结"],["D","锁骨上淋巴结"]],"D","胃癌除了转移至胃周淋巴结外，还有两处跳跃式淋巴结转移的常见部位：一是左锁骨上淋巴结，如触及肿大为癌细胞沿胸导管转移所致，又称Virchow淋巴结（D对）；二是脐周淋巴结，如触及肿大为癌细胞通过肝圆韧带淋巴管转移所致。脾门淋巴结（A错）转移、肝总动脉淋巴结（B错）转移、腹腔淋巴结（C错）转移均属于胃的区域淋巴结转移。","","N"],["2012-N86",26,"第三节 胃十二指肠溃疡的外科治疗","碱性反流性胃炎",2012,86,"A","","胃大部切除术后，碱性反流性胃炎通常发生的时间是",[["A","6个月内"],["B","1至2年"],["C","3至4年"],["D","5年以上"]],"B","本知识点与七版外科学不符合且第十版教材中已删除。但考生仍需了解：碱性反流性胃炎常发生于毕Ⅱ式手术后，原因是胃空肠吻合后，正常解剖结构改变，失去幽门-十二指肠的抗返流屏障，空肠中分泌的碱性肠液伴随胆汁共同反流入胃，造成胃黏膜屏障的损伤并呕吐含胆汁的胃内容物，同时有上腹或胸骨后烧灼痛；消化功能低下引起体重下降。历年西医综合考题认为，碱性反流性胃炎通常发生在胃大部切除术后1～2年（B对）。","","N"],["2012-N87",33,"第二节 胰腺炎","急性胰腺炎诊断",2012,87,"A","","女性，47岁。疑胆管结石行ERCP检查，4小时后剑突下偏左出现持续性疼痛并呕吐。查体：T37．8℃，剑突下偏左轻压痛，无反跳痛和肌紧张。最可能的诊断是",[["A","胃炎"],["B","胰腺炎"],["C","胆囊炎"],["D","胆管炎"]],"B","中年女性患者，行ERCP检查后4小时出现剑突下偏左侧持续性痛并呕吐，发热，无腹膜刺激征，诊断考虑急性胰腺炎（B对）。ERCP是将纤维十二指肠镜插至十二指肠降部，找到十二指肠大乳头，由活检管道内插入塑料导管至乳头开口部，注入造影剂后X线摄片，以显示胰胆管。由于操作过程中要将导管经乳头插入胆管、胰管及其共同通道，可造成胆汁逆流入胰管，从而诱发急性胰腺炎。该患者已将胆总管结石取出，解除了胆道梗阻，因此术后发生急性胆管炎（D错）的几率较小。ERCP操作并不牵涉胆囊，因此不会诱发急性胆囊炎（C错）。ERCP操作一般不会损伤胃黏膜，不引起胃炎（A错）。","","N"],["2012-N88",45,"第八节 桡骨头半脱位","桡骨头半脱位临床表现和诊断",2012,88,"A","","患儿2岁，某母在牵拉患儿双手做游戏时，患儿突然大哭，诉左上肢疼痛，其左上肢屈曲，不肯用该手取物。患儿最有可能的诊断是",[["A","肩关节脱位"],["B","肘关节脱位"],["C","桡骨小头半脱位"],["D","腕关节脱位"]],"C","2岁患儿（桡骨小头半脱位的好发年龄段），其母在牵拉患儿双手做游戏时（存在腕、手向上牵拉史）。诉左上肢疼痛，其左上肢屈曲，活动受限（桡骨小头半脱位的典型临床表现） ，诊断考虑桡骨小头半脱位（C对）。肩关节脱位（A错）、肘关节脱位（B错）、腕关节脱位（D错）多为强暴力导致，牵拉引起的可能性小，且与该患者临床表现不符。","","N"],["2012-N89",44,"第一节 骨折的定义、成因、分类及移位","间接暴力",2012,89,"A","","某篮球运动员，在起跳抢球时与对方球员相撞，即感右髂部疼痛，下肢活动受限。X线显示右髂前上棘撕脱骨折。其骨折成因为",[["A","直接暴力所致"],["B","间接暴力所致"],["C","疲劳性骨折"],["D","病理性骨折"]],"B","缝匠肌起于髂前上棘，止于胫骨上端内侧面，主要作用是屈髋屈膝。该病人在打篮球时，由于相撞时缝匠肌猛烈收缩，产生的暴发性牵引力作用于骨盆骨突的骨化中心而造成撕脱性损伤，此为肌肉收缩引起，故为间接暴力所致（B对）。","","N"],["2012-N90",53,"第一节 颈椎退行性疾病","颈椎病病因和病理",2012,90,"A","","钩椎关节（Luschka关节）所在部位是",[["A","颈椎"],["B","胸椎"],["C","腰椎"],["D","骶、尾椎"]],"A","脊柱颈段下一椎体的钩突与上一椎体的斜坡构成钩椎关节，又称Luschka关节或弓体关节（A对），这一结构在胸、腰、骶、尾脊椎并不存在。钩椎关节可防止椎间盘向侧后方突出，但当其退行变而增生时，反而可刺激侧后方的椎动脉，或压迫后方的颈神经根。","","N"],["2012-N111",24,"第二节 常见内脏损伤的特征和处理","脾损伤诊断",2012,111,"A","","男性，35岁，骑自行车与汽车相撞后1小时来诊，查体：P110次/分，BP60/45mmHg，面色苍白，左上腹压痛，肌紧张，移动性浊音阳性。该患者最可能的诊断是",[["A","肝破裂"],["B","脾破裂"],["C","小肠破裂"],["D","胰腺损伤"]],"B","青壮年男性患者，汽车撞伤1小时，查体：脉细速，面色苍白，左上腹压痛及肌紧张，移动性浊音阳性，诊断考虑外伤性脾破裂并休克（B对）。腹部外伤致脾破裂，大量血液进入腹腔，血液为温和的腹膜刺激物，导致轻度的腹膜刺激征，并出现移动性浊音阳性，因循环血量减少，导致脉速及低血压。肝破裂（A错）可因失血导致脉细速及移动性浊音阳性，但胆汁为强烈的腹膜刺激物，多引起强烈的腹膜刺激征。小肠破裂（C错）一般不引起休克，且肠液中含多种消化液成分，为强烈的腹膜刺激物，可引起强烈的腹膜刺激征。胰腺位于上腹部腹膜后深处，本身不易成为闭合性腹部损伤的受累器官，且胰腺损伤（D错）的症状虽然包含休克、腹膜刺激征、移动性浊音阳性等，但是其症状较病理描述要严重得多；胰腺损伤的疼痛多起于中上腹，后可波及全腹。","c58","N"],["2012-N112",24,"第一节 腹部损伤概述","超声检查",2012,112,"A","","男性，35岁，骑自行车与汽车相撞后1小时来诊，查体：P110次/分，BP60/45mmHg，面色苍白，左上腹压痛，肌紧张，移动性浊音阳性。为明确诊断，首选的辅助检查是",[["A","腹部X线片"],["B","腹部B超"],["C","腹部增强CT"],["D","腹部MRI"]],"B","青壮年男性患者，汽车撞伤1小时，查体：脉细速，面色苍白，左上腹压痛及肌紧张，移动性浊音阳性，诊断考虑外伤性脾破裂并休克。首选检查为B超（B对），因其具有安全、简便、无创、可重复等优点。腹部X线片（A错）主要用于辅助诊断腹部空腔脏器穿孔。对于已经休克的病人不宜作过多搬动，进行操作复杂繁琐的腹部增强CT（C错）及腹部MRI（D错）等检查。","c58","N"],["2012-N113",24,"第一节 腹部损伤概述","超声检查",2012,113,"A","","男性，24岁。背重物时突然昏倒2小时入院，查体：P120次/分，R30次/分，BP80/60mmHg，神清，面色苍白，腹胀，全腹轻度压痛及反跳痛，移动性浊音阳性，肠鸣音消失，左下胸有皮肤瘀斑痕迹。1周前因车祸撞击左下胸部，曾卧床休息2天。为进一步明确诊断，急诊首选的检查是",[["A","CT"],["B","B超"],["C","MRI"],["D","腹部X线"]],"B","年轻男性患者，一周前有左下胸撞击史。2小时前背重物突然晕倒，查体见脉速，血压降低，面色苍白，腹胀，腹膜刺激征及移动性浊音，左下胸皮肤瘀斑痕迹，诊断考虑外伤性脾破裂。首选检查为B超（B对），因其具有安全、简便、无创、可重复等优点。对于已经休克的病人不宜作过多搬动，进行操作复杂繁琐的CT（A错）及MRI（C错）等检查。腹部X线（D错）主要用于辅助诊断腹部空腔脏器穿孔。","c59","N"],["2012-N114",24,"第二节 常见内脏损伤的特征和处理","脾损伤诊断",2012,114,"A","","男性，24岁。背重物时突然昏倒2小时入院，查体：P120次/分，R30次/分，BP80/60mmHg，神清，面色苍白，腹胀，全腹轻度压痛及反跳痛，移动性浊音阳性，肠鸣音消失，左下胸有皮肤瘀斑痕迹。1周前因车祸撞击左下胸部，曾卧床休息2天。该患者最可能的诊断是",[["A","脾破裂"],["B","肝破裂"],["C","肠系膜血管破裂"],["D","腹膜后血肿"]],"A","年轻男性患者，一周前有左下胸撞击史。2小时前背重物突然晕倒，查体见脉速，血压降低，面色苍白，腹胀，腹膜刺激征及移动性浊音，左下胸皮肤瘀斑痕迹，诊断考虑外伤性脾破裂（A对）。一周前左下胸外伤史导致脾被膜下血肿形成，2小时前背重物导致血肿破裂，大量血液进入腹腔，血液为温和的腹膜刺激物，导致轻度的腹膜刺激征，并出现移动性浊音阳性，因循环血量减少，导致脉速及低血压。肝破裂（B错）常见于右季肋区外伤，有腹腔内出血及严重的腹膜刺激征，因胆汁对腹膜的强烈刺激作用。肠系膜血管破裂（C错）常有腹部外伤史，多在短时间内危及病人生命，一般不会再伤后一周出现症状。腹膜后血肿（D错）常伴发于骨盆骨折及下段脊柱骨折，与该患者病史不相符。","c59","N"],["2012-N115",24,"第一节 腹部损伤概述","腹部损伤处理",2012,115,"A","","男性，24岁。背重物时突然昏倒2小时入院，查体：P120次/分，R30次/分，BP80/60mmHg，神清，面色苍白，腹胀，全腹轻度压痛及反跳痛，移动性浊音阳性，肠鸣音消失，左下胸有皮肤瘀斑痕迹。1周前因车祸撞击左下胸部，曾卧床休息2天。该患者手术探查的顺序是",[["A","先探查胰腺，后探查肝脾"],["B","先探查肝脾，后探查胃肠道"],["C","先探查盆腔器官，后探查肝脾"],["D","最先探查肠系膜根部大血管"]],"B","腹部闭合性损伤的探查顺序：应先探查肝、脾等实质性器官，同时探查膈肌、胆囊等有无损伤。接着从胃开始，逐段探查十二指肠第一段、空肠、回肠、大肠及其系膜。然后盆腔脏器，再切开胃结肠韧带显露网膜囊，检查胃后壁和胰腺。如有必要，最后还应切开后腹膜探查十二指肠二、三、四段（B对）。","c59","N"],["2012-N116",29,"第十二节 痔","痔诊断",2012,116,"A","","男性，35岁，肛周持续性剧烈疼痛2天，局部有肿物突出，无便血。查体：肛周1．0cm直径的肿物，呈暗紫色，表面光滑，水肿，质硬有触痛。该患者最可能的诊断是",[["A","肛裂前哨痔"],["B","直肠肛管黑色素瘤"],["C","内痔脱出嵌顿"],["D","血栓性外痔"]],"D","35岁男性，肛周持续性痛2天，肛周直径1.0cm肿物，暗紫色（血栓可能），表面光滑，水肿（局部血液回流不畅），质硬有触痛，诊断考虑血栓性外痔（D对）。直肠肛管黑色素瘤（B错）属于上皮肿瘤，通常不引起疼痛，形成的肿物也因黑色素的缘故而成黑色，无触痛。肛裂前哨痔（十版外科学P429）（A错）为袋状皮垂，疼痛特点为便时疼痛-便后缓解-括约肌挛缩痛，不会出现持续性痛2天。内痔脱出嵌顿（C错）可出现持续性疼痛，但嵌顿性内痔体积较大，一般不会仅1.0cm。","c60","N"],["2012-N117",29,"第十二节 痔","血栓外痔剥离术",2012,117,"A","","男性，35岁，肛周持续性剧烈疼痛2天，局部有肿物突出，无便血。查体：肛周1．0cm直径的肿物，呈暗紫色，表面光滑，水肿，质硬有触痛。对该患者正确的处理方法是",[["A","肿物切除活检"],["B","肿物还纳"],["C","剥离痔内血栓"],["D","胶圈套扎"]],"C","该病人诊断为血栓性外痔，正确处理方法为剥离痔内血栓（C对）。在局麻下将痔表面的皮肤梭形切开，摘除血栓，伤口填入纱布而不缝合创面。肿物切除活检（A错）可用于鉴别直肠内肿块性质。肿物还纳（B错）可用于治疗嵌顿性痔。胶圈套扎（十版外科学P436）（D错）用于治疗Ⅰ、Ⅱ、Ⅲ度内痔。","c60","N"],["2012-N118",56,"第二节 强直性脊柱炎","强直性脊柱炎诊断标准",2012,118,"A","","男性，18岁。近一年反复腰部疼痛，活动受限。近两月来，又出现双髋疼痛，轻度屈曲畸形，需拄拐行走。X线检查显示：双侧骶髂关节面模糊，双侧股骨头表面毛糙，髋关节间隙变窄。该患者最有可能的诊断是",[["A","类风湿关节炎"],["B","骨关节结核"],["C","强直性脊柱炎"],["D","双侧股骨头缺血性坏死"]],"C","18岁男性患者（强直性脊柱炎的好发年龄）。反复腰部疼痛，活动受限一年。出现双髋疼痛，轻度屈曲畸形，需拄拐行走2月（强直性脊柱炎的典型临床表现）。X线示：双侧骶髂关节面模糊，双侧股骨头表面毛糙，髋关节间隙变窄（强直性脊柱炎晚期X线改变）。综合该患者的病史及影像学检查，最有可能的诊断是强直性脊柱炎（C对）。类风湿关节炎（十版外科学P755）（A错）好发于20～45岁的中青年女性，多累及近侧指间关节，以及腕、肘、肩、膝和足趾关节，X线早期表现为关节周围软组织肿大，关节间隙增宽，关节周围骨质疏松，随病变发展关节周围骨质疏松更明显，关节面边缘模糊不清，关节间隙逐渐狭窄，晚期间关节间隙消失，出现骨性强直。骨关节结核（十版外科学P739）（B错）累及髋关节者，多有低热、乏力、盗汗等结核中毒症状，患肢早期可出现屈曲、外展、外旋畸形，X线最早的表现为局限性的骨质疏松，常须两侧对比才能发现，偶尔可在数周内迅速出现关节的完全破坏，出现空洞及死骨。双侧股骨头缺血性坏死（十版外科学P715）（D错）多发于老年人，多有股骨头下型骨折病史，病变一般不会累及骶髂关节。","c61","N"],["2012-N119",56,"第二节 强直性脊柱炎","强直性脊柱炎实验室检查",2012,119,"A","","男性，18岁。近一年反复腰部疼痛，活动受限。近两月来，又出现双髋疼痛，轻度屈曲畸形，需拄拐行走。X线检查显示：双侧骶髂关节面模糊，双侧股骨头表面毛糙，髋关节间隙变窄。下列检查项目中，对该患者明确诊断帮助最大的是",[["A","ESR、RF、骶髂关节CT"],["B","ESR、HLA-B₂₇、骶髂关节CT"],["C","ESR、RF、双髋关节MRI"],["D","ESR、HLA-B₂₇，双髋关节MRI"]],"B","强直性脊柱炎患者类风湿因子（RF）阴性，活动期血沉加快（ESR），HLA-B27阳性率高达88%～96%，有一定的特异性。骶髂关节CT可以清楚地显示骶髂关节病变，早期表现为关节骨质疏松，关节边缘呈虫蛀状改变，关节间隙不规则增宽，软骨下骨有硬化致密改变；以后关节面渐趋模糊，间隙逐渐变窄，直至双侧骶髂关节完全融合。MRI首选用于了解神经等软组织受累情况，本题中双髋关节MRI对强直性脊柱炎的诊断价值不如骶髂关节CT，因为强直性脊柱炎起病于骶髂关节，后期才累及髋关节，因此，下列检查项目对明确诊断帮助最大的是ESR、HLA-B27、骶髂关节CT（B对）。","c61","N"],["2012-N120",56,"第二节 强直性脊柱炎","强直性脊柱炎病理",2012,120,"A","","男性，18岁。近一年反复腰部疼痛，活动受限。近两月来，又出现双髋疼痛，轻度屈曲畸形，需拄拐行走。X线检查显示：双侧骶髂关节面模糊，双侧股骨头表面毛糙，髋关节间隙变窄。此病较少累及的部位是",[["A","脊柱"],["B","髋关节"],["C","膝关节"],["D","手关节"]],"D","强直性脊柱炎的病变常从骶髂关节开始，逐渐向上蔓延至脊柱（A错），向下蔓延累及双髋关节（B错），少数也可累及膝关节（C错），但极少累及肘、手腕（D对）和足部的小关节。","c61","N"],["2012-N145",18,"第三节 乳腺良性疾病","导管内乳头状瘤临床表现",2012,145,"B","","乳头鲜红色血性溢液多见于",[["A","导管内乳头状瘤"],["B","乳管阻塞的导管内乳头状瘤"],["C","终止哺乳后"],["D","正常月经期，早期妊娠或囊性增生病"]],"A","导管内乳头状瘤（A对）大多数发生于大乳管近乳头的壶腹部，瘤体很小，带蒂而有绒毛，且有很多壁薄的血管，故易出血，常出现的乳头溢液是鲜红色血性溢液。乳管阻塞的导管内乳头状瘤（B错）可见棕褐色溢液，是因为恶性疾病乳管阻塞，出血混合坏死组织所致。终止哺乳后（C错）常见乳头溢液常为乳汁，为白色或略带黄色的液体。正常月经期，早期妊娠或囊性增生病（D错）常见乳头溢液为浆液性无色溢液。","","N"],["2012-N146",18,"第三节 乳腺良性疾病","乳腺囊性增生病临床表现",2012,146,"B","","乳头浆液性无色溢液可见于",[["A","导管内乳头状瘤"],["B","乳管阻塞的导管内乳头状瘤"],["C","终止哺乳后"],["D","正常月经期，早期妊娠或囊性增生病"]],"D","正常月经期，早期妊娠或囊性增生病（D对）常见乳头溢液为浆液性无色溢液。导管内乳头状瘤（A错）大多数发生于大乳管近乳头的壶腹部，瘤体很小，带蒂而有绒毛，且有很多壁薄的血管，故易出血，常出现的乳头溢液是鲜红色血性溢液。乳管阻塞的导管内乳头状瘤（B错）可见棕褐色溢液，是因为恶性疾病乳管阻塞，出血混合坏死组织所致。终止哺乳后（C错）常见乳头溢液常为乳汁，为白色或略带黄色的液体。","","N"],["2012-N147",41,"第一节 泌尿系统结石概述","泌尿系统结石成分及特性",2012,147,"B","","泌尿系草酸钙结石的特点是",[["A","质硬粗糙、不规则、常呈桑椹样，棕褐色"],["B","易碎粗糙、不规则，呈灰白色、黄色或棕色"],["C","X线不被显示"],["D","光滑、淡黄至黄棕色、蜡样外观"]],"A","常见的泌尿系结石作如下总结：①草酸钙类，质硬粗糙、不规则、常呈桑椹样，棕褐色。X线平片显影（A对）；②磷酸钙类，易碎，表面粗糙，不规则，常呈灰白色、黄色或棕色，尿路平片可见多层现象；③尿酸类，圆形光滑，结构质密，中等硬度，极易吸附尿色素而呈黄色或砖红色。X线平片不显影；④磷酸铵镁结石，易碎粗糙、不规则或鹿角形，呈灰白色、黄色或棕色。X线平片不显影；⑤胱氨酸结石，光滑圆形或鹿角形，淡黄至黄棕色，蜡样外观。X线平片不显影。","","N"],["2012-N148",41,"第一节 泌尿系统结石概述","泌尿系统结石成分及特性",2012,148,"B","","泌尿系胱氨酸结石的特点是",[["A","质硬粗糙、不规则、常呈桑椹样，棕褐色"],["B","易碎粗糙、不规则，呈灰白色、黄色或棕色"],["C","X线不被显示"],["D","光滑、淡黄至黄棕色、蜡样外观"]],"D","常见的泌尿系结石作如下总结：①草酸钙类，质硬粗糙、不规则、常呈桑椹样，棕褐色。X线平片显影；②磷酸钙类，质地坚硬，可有同心层，浅灰色。X线平片显影；③尿酸类，圆形光滑，结构质密，中等硬度，极易吸附尿色素而呈黄色或砖红色。X线平片不显影；④磷酸镁铵结石，易碎粗糙、不规则或鹿角形，呈灰白色、黄色或棕色。X线平片不显影；⑤胱氨酸结石，光滑圆形或鹿角形，淡黄至黄棕色，蜡样外观（D对）。X线平片不显影。本题C选项亦正确，但当年给出答案为D。","","N"],["2012-N149",57,"第四节 原发性恶性骨肿瘤","尤因肉瘤",2012,149,"B","","尤文肉瘤的常见X线表现是",[["A","“肥皂泡”样改变"],["B","“日光射线”形态"],["C","“葱皮状”的现象"],["D","“溶冰征”"]],"C","尤文（Ewing）肉瘤X线表现为虫蛀样溶骨改变，界限不清，外有骨膜反应，呈板层状或“葱皮状”的现象（C对）。骨巨细胞瘤（十版外科学P764）典型的X线特征为骨端偏心位、溶骨性、囊性破坏而无骨膜反应，病灶膨胀生长、骨皮质变薄，呈“肥皂泡”样改变（A错）。骨肉瘤（十版外科学P765）X线表现为不同形态，密质骨和髓腔有成骨性、溶骨性和混合性骨质破坏，骨膜反应明显，呈侵袭性发展，可见Codman三角或呈“日光射线”形态（B错）。恶性淋巴瘤（十版外科学P766）是一种恶性淋巴细胞组成并在骨骼内产生膨胀性病灶的肿瘤，X线有时呈“溶冰征”（D错），骨膜反应少见。","","N"],["2012-N150",57,"第三节 骨巨细胞瘤","骨巨细胞瘤临床表现",2012,150,"B","","骨巨细胞瘤的常见X线表现是",[["A","“肥皂泡”样改变"],["B","“日光射线”形态"],["C","“葱皮状”的现象"],["D","“溶冰征”"]],"A","骨巨细胞瘤典型的X线特征为骨端偏心位、溶骨性、囊性破坏而无骨膜反应，病灶膨胀生长、骨皮质变薄，呈肥皂泡样改变（A对）。骨肉瘤（十版外科学P765）X线表现为不同形态，密质骨和髓腔有成骨性、溶骨性和混合性骨质破坏，骨膜反应明显，呈侵袭性发展，可见Codman三角或呈“日光射线”形态（B错）。尤文（Ewing）肉瘤（十版外科学P766）X线表现为虫蛀样溶骨改变，界限不清，外有骨膜反应，呈板层状或“葱皮状”的现象（C错）。恶性淋巴瘤（十版外科学P766）是一种恶性淋巴细胞组成并在骨骼内产生膨胀性病灶的肿瘤，X线有时呈“溶冰征”（D错），骨膜反应少见。","","N"],["2012-N175",19,"第三节 气胸","胸腔闭式引流术",2012,175,"X","","关于闭式胸膜腔引流术的叙述中正确的有",[["A","如胸膜腔内为气体，引流选在锁骨中线第2肋间"],["B","如胸膜腔内为液体，引流选在腋前线的第6～8肋间"],["C","为保持管腔通畅，要经常挤压引流管"],["D","拔管时待病人深吸气后屏气，再迅速拔除引流管"]],"ACD","穿刺部位需考生掌握，可以这样简单区分记忆：气体密度小，故应在胸腔上部，即锁骨中线第2肋间（A对）；液体密度高，处于胸腔底部，引流应选在腋中线与腋后线第6或第7肋间隙（B错）。挤压引流管是利用引流管内液体或空气冲击将堵塞引流管的血凝块或组织块冲出，以保持管腔通畅（C对）。深吸气时膈肌和肋间外肌收缩，胸廓扩大，深吸气后屏气胸膜腔空间最大，利于拔管（D对）。","","N"],["2012-N176",18,"第四节 乳腺癌","临床表现",2012,176,"X","","关于乳癌的描述，下列各项中正确的有",[["A","多见于更年期和绝经前后妇女"],["B","最常见、最早的症状是无痛性肿块"],["C","癌细胞阻塞静脉回流产生“橘皮样”改变"],["D","侵犯Cooper韧带产生“酒窝征”"]],"ABD","乳腺癌大都发生在45～50岁，更年期和绝经期前后的妇女（A对）。乳腺癌早期表现为无痛单发小肿块（B对），不易引起注意。随着病情的发展，会出现一些由癌细胞浸润引起的肉眼可见的乳房表现，最典型的表现即“酒窝征”和“橘皮样”改变。“酒窝征”是由于癌细胞浸润Cooper韧带，与周围组织粘连硬化，牵拉Cooper韧带从而在乳房皮肤表面形成的凹陷（D对）。“橘皮样”改变是由于癌细胞浸润浅表组织淋巴管，而非静脉（C错），使得淋巴管阻塞，淋巴液回流障碍，进而造成真皮水肿，由于皮肤毛囊与皮下组织粘连较紧密，在真皮水肿时毛囊处即会形成许多点状小孔，形成了凹凸不平的橘皮样改变。","","N"],["2012-N177",28,"第二节 急性阑尾炎","急性阑尾炎手术治疗",2012,177,"X","","急性化脓性阑尾炎、行麦氏切口阑尾切除术。下列描述正确的是",[["A","注意保护切口"],["B","阑尾残端妥善处理，防止术后发生肠瘘"],["C","腹腔局部使用抗生素冲洗"],["D","腹腔可不放引流"]],"ABD","急性化脓性阑尾炎其阑尾腔内含有大量的细菌、坏死细胞残留和炎性细胞等，阑尾周围的腹腔内有稀薄脓液，形成局限性腹膜炎，临床症状和体征较重，宜早期手术治疗。行麦氏切口阑尾切除术时，需在皮肤切口两边垫上生理盐水浸润过的纱布以注意保护切口（A对），不被污染。病变阑尾切除后，残留端需要做荷包缝合，用碘酒、酒精涂擦后收拢荷包、打结，以将阑尾残端完全包埋，可防止肠瘘的发生（B对）。阑尾切除术后，引流较少应用，仅在局部有脓腔，或阑尾残端包埋不满意及处理困难时采用，如果有肠瘘形成，肠内容物可从引流管流出（D对）；也无需使用抗生素冲洗，一方面是冲洗可能造成感染的扩散，另一方面是因为抗生素作为一种异物，灌洗腹腔无法避免的会造成腹腔内的粘连，故非污染的腹腔不采用（C错）。","","N"],["2012-N178",0,"第一节 手术器械、物品的灭菌、消毒法","药液浸泡法",2012,178,"X","","能达到灭菌效果的制剂包括",[["A","甲醛"],["B","酒精"],["C","过氧乙酸"],["D","氯己定"]],"AC","灭菌是指杀灭一切活的微生物，包括芽孢；消毒是指杀灭病原微生物和其他有害微生物。70%乙醇（B错）、1：1000苯扎溴铵、1：1000氯己定（D错）为常用的消毒药液。环氧乙烷气体法、过氧化氢等离子体低温法、低温甲醛（A对）蒸气法均为灭菌常用方法。过氧乙酸（C对）为过氧化物，与过氧化氢有相近化学性质，其中的过氧键有强氧化性，可用于灭菌。（甲醛较为特殊，既可以用于灭菌又可用于消毒）。","","N"],["2012-N179",47,"第七节 膝关节半月板损伤","膝关节半月板损伤影像学检查与关节镜检查",2012,179,"X","","用于确诊是否半月板损伤的检查方法有",[["A","关节造影"],["B","CT检查"],["C","MRI检查"],["D","关节镜检查"]],"ACD","半月板损伤时，关节造影不仅对鉴别诊断有参考价值，如骨软骨损伤、关节游离体、骨肿瘤等需排除，而且对决定是否手术也有意义（A对）。磁共振成像MRI可以较清楚地显示关节内软骨、半月板、韧带损伤的部位（C对）。关节镜检查（D对）不仅可以发现影像学难以觉察的半月板损伤，还可以同时发现有无交叉韧带、关节软骨和滑膜病变。CT不能完全显示半月板、软骨等情况，不能确诊半月板的损伤（B错）。","","N"],["2012-N180",43,"第一节 先天性畸形","发育性髋关节脱位病因",2012,180,"X","","典型性先天性髋脱位的主要发病因素有",[["A","髋臼发育不良"],["B","股骨颈前倾角增大"],["C","关节囊、韧带松弛"],["D","股骨头发育不良"]],"AC","先天性髋关节发育不良（先天性髋关节脱位）的病因包括：①遗传因素：此病有明显的家族史；②体位与机械因素：臀位产高发；③关节松弛（C）：母体在生产过程中产生的大量激素（雌激素），结果使盆腔韧带松弛，胎儿也会受此影响，导致关节韧带松弛；④原发性髋臼发育不良（A）。根据诸福棠实用儿科学说法（P2510）：本症的病因尚不十分明了，遗传因子起重要作用，显性遗传，主要原因系髋关节的骨性结构形态的异常（D）和关节四周软组织的发育缺陷，一些观点支持髋关节发育不良的说法，也有观点认为是关节囊松弛、股骨颈前倾角过大（B）所致。本题官方参考答案为AC，但其他选项根据现有观点存在争议。","","N"],["2013-N77",4,"第一节 外科病人的代谢变化","机体能量消耗的组成、测定及计算",2013,77,"A","","男性，50岁。体重60kg，行胃癌根治术，其术后每日需要最合适的热量是",[["A","1500kcal"],["B","1650kcal"],["C","1800kcal"],["D","1950kcal"]],"B","通常的择期、限期手术，术后热量增加10%左右；创伤、感染时视其严重程度热量可增加20%～30%；大面积烧伤热量可增加50%～100%。患者行胃癌根治术属限期手术，术后患者每日热量需要量会高出正常量的10%。七版外科学有关正常人基础能量需要的数据为25kcal/（kg·d），本题原答案为根据七版外科学数据计算即25kcal/（kg·d）×60kg×110%=1650kcal（B），有关正常人基础能量需要的相关内容，九版、十版外科学有数据更新（25～30）kcal/（kg·d）（十版外科学P38）。","","N"],["2013-N78",10,"第五节 椎管内麻醉","麻醉平面与阻滞作用",2013,78,"A","","椎管内阻滞麻醉时，最先受到阻滞的神经是",[["A","交感神经"],["B","副交感神经"],["C","感觉神经"],["D","运动神经"]],"A","神经纤维被阻滞的顺序依次为：自主神经（C类纤维传导的痛觉及交感神经）→感觉神经（Aδ纤维传导的温痛觉、Aβ纤维传导的触～压觉）→运动神经（Aα纤维传导的躯体运动）→Aγ纤维传导的固有感觉（深部感觉和位置觉）。不难得出，最先受到阻滞的神经是交感神经（A对）。","","N"],["2013-N79",19,"第三节 气胸","张力性气胸",2013,79,"A","","下列急性胸部损伤中，对生命威胁最大的是",[["A","闭合性气胸"],["B","开放性气胸"],["C","张力性气胸"],["D","血气胸"]],"C","张力性气胸：伤侧肺严重萎缩，纵隔显著向健侧移位，健侧肺受压，腔静脉回流障碍。病人表现为严重或极度呼吸困难、烦躁、意识障碍、大汗淋漓、发绀，为可迅速致死的危急重症（C对）。闭合性气胸（A错）：胸膜裂口较小，可有不同程度肺萎陷、胸腔积气，对呼吸循环的影响较小。开放性气胸（B错）：外界空气可经胸壁伤口随呼吸自由进入胸膜腔，导致纵隔扑动，引起循环障碍。但与张力性气胸进行性加重相比，没有张力性气胸危急。血气胸（D错）指气胸与血胸同时存在，一般不会导致患者迅速死亡，但值得注意的是，进行性血气胸也相当危险，应及时作开胸探查手术。","","N"],["2013-N80",26,"第三节 胃十二指肠溃疡的外科治疗","术后肠梗阻",2013,80,"A","","女性，55岁。10天前行胃癌根治术，术后3天拔出胃管开始进流食。3天来进食后半小时出现右上腹胀痛，伴呕吐，吐出物为大量胆汁，吐后症状缓解。此患者最可能的诊断是",[["A","急性输入袢梗阻"],["B","慢性输入袢梗阻"],["C","输出袢梗阻"],["D","吻合口梗阻"]],"B","老年女性病人，胃癌根治术后。进食半小时后出现右上腹胀痛，呕吐大量胆汁样液体，吐后症状缓解，诊断考虑慢性输入袢梗阻（B对）。胃癌根治术中，残胃与肠管断端的吻合方法与毕Ⅱ式类似。胃术后慢性不全性输入袢梗阻，胆汁及胰腺分泌的消化液淤积在十二指肠残端，当腹内压升高时，可有胆汁呕出，因输出袢通畅，食物通过无障碍，因此呕吐物没有食物。急性输入袢梗阻（A错）时，因少量瘀滞即可导致十二指肠残端内压力升高，早期即出现疼痛及呕吐，呕吐物量少，不含胆汁。输出袢梗阻（C错）时，胆汁和食物均无法通过输出袢下行，呕吐物既有胆汁，又有食物。吻合口梗阻（D错）时，食物无法通过吻合口，而胆汁可通过输出袢下行，多表现为呕吐食物，不含有胆汁的液体。","","N"],["2013-N81",17,"第一节 甲状腺疾病","TSH抑制治疗",2013,81,"A","","女性，55岁。因结节性甲状腺肿行双侧甲状腺次全切除术，术后病理报告，右叶甲状腺有5mm乳头状癌结节。对此患者进一步的处理是",[["A","手术切除剩余的右叶甲状腺"],["B","切除右叶甲状腺加颈淋巴结清扫"],["C","终生口服甲状腺素钠"],["D","加用外照射治疗"]],"C","①腺叶（加峡部）切除术适用于肿瘤直径 <1cm，无颈部放射史、远处转移、甲状腺腺外侵犯、其他不良病理亚型、明显临床淋巴结转移者。②甲状腺全切除术或近全切除术适用于肿瘤直径 >4cm者。③若肿瘤直径在1～4cm，应充分评估是否具有相对的高危因素并结合病人意愿决定手术方式。该患者为局限于右叶 <1cm的微小乳头状癌，需要行腺叶（加峡部）切除术+病灶同侧中央区淋巴结清扫术（A错B对），术后给予甲状腺素钠作为终身代替治疗（C 对），以预防甲状腺功能减退及抑制 TSH。加用外照射治疗（D 错）主要用于未分化型甲状腺癌。本题官方给出的参考答案为C，但根据最新临床观点，可选择BC。","","N"],["2013-N82",25,"第三节 腹腔间隔室综合征","腹腔间隔室综合征诊断",2013,82,"A","","诊断腹腔间隔室综合征（abdominal compartment syndrome，ACS）时，膀胱内测得压力应大于",[["A","10mmHg"],["B","15mmHg"],["C","20mmHg"],["D","25mmHg"]],"C","腹腔是一个封闭的腔，与外界相对隔绝。在正常情况下，腹腔内压力（IAP）为5～7mmHg。虽然腹腔有一定的扩张限度，但当腹内压过高时，腹腔内器官与邻近组织都将受压，引起腹腔内及全身器官生理功能受损，导致器官功能不全和循环衰竭。腹腔间隔室综合征的诊断主要依靠IAP测量，最广泛应用的测定IAP的方法：用Foley尿管经尿道测膀胱压或者直接穿刺膀胱置管测压。诊断腹腔间隔室综合征（ACS）时，膀胱内测得压力应大于20mmHg（C对）。","","N"],["2013-N83",29,"第七节 直肠癌","直肠指诊触及肿物",2013,83,"A","","对中国人直肠癌，直肠指诊的发现率是",[["A","40%"],["B","50%"],["C","60%"],["D","70%"]],"D","直肠指诊是诊断直肠癌最重要的方法。对于中国人直肠癌，直肠指诊的发现率是60％ ~70%（D 对）。","","N"],["2013-N84",10,"第三节 全身麻醉","氧化亚氮",2013,84,"A","","肠梗阻病人不宜使用的麻醉药是",[["A","氧化亚氮"],["B","恩氟烷"],["C","异氟烷"],["D","七氟烷"]],"A","一氧化二氮（N₂O），又称“笑气”，早期被用于牙科手术的麻醉，是人类最早应用于医疗的麻醉剂之一。因其可使体内封闭腔内压升高，因此不宜应用于肠梗阻患者。使用氧化亚氮还有如下注意事项：大手术需配合硫喷妥钠及肌肉松弛剂等；吸入气体中必须维持吸入氧浓度（FiO₂）高于0.3，以免发生低氧血症；麻醉终止后，应继续吸纯氧5～10分钟，以防止缺氧。","","N"],["2013-N85",40,"第二节 良性前列腺增生的诊断","良性前列腺增生临床表现",2013,85,"A","","男性，82岁。前天饮酒后出现腹部胀痛，小便频，量少，逐渐加重。平时大便干燥，2～3天1次。查体：腹部膨隆，下腹为著，全腹压痛，下腹更重，肌紧张不明显，肠鸣音活跃。经肥皂水灌肠后，排出较多粪块，腹痛无明显缓解。此患者最可能的诊断是",[["A","急性膀胱炎"],["B","急性尿潴留"],["C","乙状结肠扭转"],["D","习惯性便秘"]],"B","82岁男性患者（多有前列腺不同程度增生）。饮酒（可引起前列腺充血，加重尿道梗阻）后出现腹部胀痛，逐渐加重，小便频，量少（提示尿潴留）。平时大便干燥，2～3天1次。查体：腹部膨隆，下腹为著，全腹压痛，下腹更重（急性尿潴留常见疼痛部位），肌紧张不明显，肠鸣音活跃。经肥皂水灌肠后，排出较多粪块，腹痛无明显缓解（可排除便秘引起的腹痛）。综合该患者病史、体查及治疗结果，诊断考虑为急性尿潴留（B对）。急性膀胱炎（十版外科学P542）（A错）的主要症状为尿频、尿急、尿痛，以及耻骨区疼痛，并可伴有终末血尿。该病人虽有尿频，但起病较缓慢，且该患者以下腹膨隆为主，与急性膀胱炎表现不符。乙状结肠扭转（十版外科学P396）（C错）属于急症，若不及时治疗可因肠管缺血坏死迅速恶化，该病人肥皂水灌肠后排出较多粪块，说明肠道尚通畅。习惯性便秘（D错），通过灌肠后病情常好转，与该患者病情变化不符。","","N"],["2013-N86",32,"第十一节 胆道恶性肿瘤","胆囊癌病因",2013,86,"A","","下列胆囊疾病中，与胆囊癌发病无关的是",[["A","胆囊结石﹥2cm"],["B","“瓷化”胆囊"],["C","胆囊腺瘤"],["D","胆囊胆固醇息肉"]],"D","胆固醇息肉（D对）可能是胆囊胆固醇沉着症的一种，本身并不是肿瘤，体积较小，并有蒂。胆囊胆固醇息肉是最常见的胆囊良性病变，与胆囊癌的发生无关。约70%的胆囊癌与胆囊结石有关，胆囊癌合并胆囊结石是不合并胆囊结石的13.7倍，直径3cm的结石发病是直径1cm的10倍，因此可认为胆囊结石＞2cm（A错）与胆囊癌发病相关。完全钙化的“瓷化”胆囊（B错）进展为胆囊癌的概率高达15～60%。胆囊腺瘤（C错）可恶变，其癌变率约1.5%，被视为癌前病变。","","N"],["2013-N87",31,"门静脉高压","食管胃底曲张静脉破裂出血手术治疗",2013,87,"A","","目前外科治疗肝硬化门静脉高压症主要目的是",[["A","解除脾功能亢进"],["B","改善肝功能"],["C","预防和治疗曲张静脉出血"],["D","减少腹水形成"]],"C","目前外科治疗肝硬化门静脉高压症主要目的是预防和治疗曲张静脉出血（C对）， 临床上常用术式包括分流术或断流术两大类。门体分流术可降低门静脉压力，减少甚至消除交通支静脉的曲张；断流术可阻断门奇静脉间的反常血流，以达到止血目的。虽然断流术对肝门静脉血供影响较小，但分流术会影响肝的门静脉血供，继而影响肝的营养导致肝功能继续变坏，肝性脑病发病率高（B错），即手术治疗不一定能改善肝功，甚至可能加剧肝损害。通过保肝、利尿和休养等措施可以缓解腹水，难治性腹水提示预后不佳，需要肝移植（D错）。","","N"],["2013-N88",45,"第七节 肘关节脱位","肘关节脱位临床表现和诊断",2013,88,"A","","儿童肘部外伤后，鉴别肱骨髁上骨折和肘关节脱位最可靠的体征是",[["A","肿胀明显"],["B","活动明显受限"],["C","畸形"],["D","肘后三角关系改变"]],"D","肱骨髁上骨折好发于儿童，占儿童肘部骨折的首位；肘关节脱位在全身四大关节脱位中占第二位。两者均存在伤后肘关节肿胀明显（A错）、疼痛、活动明显受限（B错）并出现畸形（C错）。鉴别肱骨髁上骨折和肘关节脱位最可靠的体征是肘后三角关系改变（D对）与否。肘后三角由肱骨内、外髁及尺骨鹰嘴组成。肱骨髁上骨折时损伤在鹰嘴以上，关节无损伤，故肘后三角关系正常；而肘关节脱位时，肘后三角关系发生改变。","","N"],["2013-N89",57,"第四节 原发性恶性骨肿瘤","骨肉瘤",2013,89,"A","","最常见的原发性恶性骨肿瘤是",[["A","骨纤维肉瘤"],["B","尤文肉瘤"],["C","软骨肉瘤"],["D","骨肉瘤"]],"D","最常见的原发性恶性骨肿瘤是骨肉瘤（D对），约占恶性骨肿瘤总量的44.58%。骨纤维肉瘤（A错）约占恶性骨肿瘤总量的6.58%。尤文肉瘤（B错）约占恶性骨肿瘤总量的4.58%。软骨肉瘤（C错）约占恶性骨肿瘤总量的14.24%。具体参阅七版黄家驷外科学骨肿瘤章节。","","N"],["2013-N90",53,"","",2013,90,"A","","颈椎病中发病率最高的类型是",[["A","脊髓型"],["B","神经根型"],["C","椎动脉型"],["D","交感型"]],"B","颈椎病根据不同的神经、血管受累及不同的临床表现，分为四类：神经根型颈椎病（B对），发病率最高，约占58.5%（七版黄家驷外科学P3114），表现为颈肩臂痛并有神经根支配区感觉和运动障碍（如放射痛等）。交感型及椎动脉型合计约占33.7%。交感型颈椎病表现为头昏头疼，颈肩背痛，面部麻或半身麻，泌汗异常；视物不清、耳鸣、心动过速等。椎动脉型颈椎病表现为转头时突发眩晕、恶心呕吐，四肢无力、共济失调，甚至倾倒，但意识清醒。脊髓型颈椎病发病率约7.8%，表现为手足或肢体麻木，僵硬不灵活，握物不稳，写字、持筷不便或行走不稳，足踩棉花感。","","N"],["2013-N111",35,"急腹症","急腹症的处理原则",2013,111,"A","","男性，80岁。因突发全腹剧痛8小时来院，途中频繁呕吐，随后出现气急、喘憋。既往有房颤史。入院查体：P95次/分，BP84/60mmHg，急性病容，呼吸急促，两肺均可闻及哮鸣音及湿啰音，右侧为著，心率120次/分，节律不整，腹部膨隆，全腹均有压痛，右侧更明显，轻度反跳痛，肌紧张，肠鸣音弱。化验Hb124g/L，WBC30×10⁹/L，中性粒细胞90%。即刻应采取的处理措施是",[["A","快速补液加升压药"],["B","增强CT"],["C","血管造影"],["D","减慢心率"]],"A","老年男性患者急性起病，心率120次/分（心率增快），血压仅84/60mmHg，考虑合并休克，因此治疗首选快速补液加升压药（A对），以恢复血容量，提高全身组织灌流，缓解组织缺氧。在休克状态下，不宜作过多检查，以免耽误时间导致休克复苏延迟，因此此时不宜做增强CT（B错）、血管造影（C错）。心率加快为血容量下降时机体正常的代偿机制，可以在一定程度上提高血压，补足血容量后，心率自然会减慢（D错）。","c69","N"],["2013-N112",4,"第四节 肠内营养","肠内营养并发症及防治",2013,112,"A","","男性，80岁。因突发全腹剧痛8小时来院，途中频繁呕吐，随后出现气急、喘憋。既往有房颤史。入院查体：P95次/分，BP84/60mmHg，急性病容，呼吸急促，两肺均可闻及哮鸣音及湿啰音，右侧为著，心率120次/分，节律不整，腹部膨隆，全腹均有压痛，右侧更明显，轻度反跳痛，肌紧张，肠鸣音弱。化验Hb124g/L，WBC30×10⁹/L，中性粒细胞90%。患者突发严重的喘憋可能的原因是",[["A","哮喘发作"],["B","吸入性肺炎"],["C","肺栓塞"],["D","急性心衰"]],"B","老年男性患者频繁呕吐后（吸入性肺炎的常见诱因），突然出现气急、憋喘、呼吸急促（呼吸道梗阻的典型临床表现）、两肺哮鸣音及湿啰音（肺部存在炎症渗出病灶），诊断考虑吸入性肺炎（B对）。哮喘发作（A错）与频繁呕吐无密切关系。肺栓塞（C错）典型表现为胸痛，呼吸困难，咯血等症状。急性心衰（D错）常有呼吸困难，咳嗽，咳粉红色泡沫痰等症状，听诊可有双侧对称性湿啰音。","c69","N"],["2013-N113",35,"急腹症","胃十二指肠溃疡急性穿孔",2013,113,"A","","男性，80岁。因突发全腹剧痛8小时来院，途中频繁呕吐，随后出现气急、喘憋。既往有房颤史。入院查体：P95次/分，BP84/60mmHg，急性病容，呼吸急促，两肺均可闻及哮鸣音及湿啰音，右侧为著，心率120次/分，节律不整，腹部膨隆，全腹均有压痛，右侧更明显，轻度反跳痛，肌紧张，肠鸣音弱。化验Hb124g/L，WBC30×10⁹/L，中性粒细胞90%。患者的下列拟诊中可排除的是",[["A","上消化道穿孔"],["B","肠系膜上动脉栓塞"],["C","急性重症胰腺炎"],["D","乙状结肠扭转"]],"D","该病人腹部病变的拟诊中可排除的是乙状结肠扭转（D对），因为乙状结肠扭转病变部位于左下腹，典型临床表现为突发左下腹痛，呈阵发性绞痛，发病早期即有明显腹胀，但一般无明显呕吐，与该患者临床表现不符。患者突发全腹部剧痛，呕吐，腹膜刺激征明显，故不能排除上消化道穿孔（A错）及急性重症胰腺炎（C错）。老年人，有房颤病史，突发全腹部剧痛，呕吐，腹膜刺激征明显，不能排除心腔内血栓脱落后随血液循环进入腹腔血管，导致肠系膜上动脉栓塞（B错）。","c69","N"],["2013-N114",30,"第二节 肝脓肿","细菌性肝脓肿诊断",2013,114,"A","","男性，70岁。1年前因壶腹癌行Whipple手术，手术恢复好。近2月来反复发热，伴寒战，最高体温达39．5度，WBC15×10⁹/L，血清ALT121U/L，Tbil58μmol/L，CT示肝内多发直径1～2cm低密度灶，边缘强化明显。下列拟诊中可能性最大的是",[["A","肝转移癌"],["B","急性胆管炎"],["C","急性肝炎"],["D","多发性肝脓肿"]],"D","Whipple手术即胰头十二指肠切除术，主要用于治疗胰头癌。切除范围包括胰头（含钩突）、远端胃、十二指肠、上端空肠、胆囊和胆总管，需同时切除相应区域淋巴结，切除后再将胰腺、肝总管和胃与空肠重建。70岁男性，1年前行Whipple手术（术后吻合口可能出现狭窄，存在易感因素），2月来反复发热，伴寒战，最高体温达39.5度，WBC 15×10⁹/L（感染中毒症状明显），血清 ALT121U/L（正常值小于40 U/L），Tbil58μmol/L（正常值不超过17.1μmol/L）（存在肝功能损伤），CT示肝内多发直径 1～2cm低密度灶，边缘强化明显（细菌性肝脓肿的典型CT表现），诊断考虑多发性肝脓肿（D对）。肝转移癌（十版外科学P449）（A错）多有肝外原发肿瘤的临床表现，转移灶较大时可出现上腹或肝区不适及疼痛，一般不会出现高热寒战等急性感染中毒症状，CT亦表现为实质性病变，强化时转移瘤整体CT值增高明显。急性胆管炎（十版外科学P469）（B错）典型表现为Charcot三联征，即腹痛、黄疸、寒战高热，一般不会出现肝内CT边缘强化明显的低密度灶。急性肝炎（C错）多由肝炎病毒引起，典型表现为乏力、恶心呕吐、食欲减退及黄疸等肝功能减退的表现，一般不会导致外周血白细胞明显增高。","c70","N"],["2013-N115",30,"第二节 肝脓肿","细菌性肝脓肿病因和病理",2013,115,"A","","男性，70岁。1年前因壶腹癌行Whipple手术，手术恢复好。近2月来反复发热，伴寒战，最高体温达39．5度，WBC15×10⁹/L，血清ALT121U/L，Tbil58μmol/L，CT示肝内多发直径1～2cm低密度灶，边缘强化明显。发生上述情况的原因是",[["A","肿瘤复发转移"],["B","胆肠吻合口狭窄"],["C","手术时输血感染"],["D","免疫功能低下"]],"B","肝脓肿的感染途径有很多：胆道、肝动脉、门静脉、周围感染直接蔓延以及外伤带入致病菌，其中最常见的是经胆道途径的感染。患者存在胆道-消化道改建手术，若胆肠吻合口狭窄（B对），则胆汁排泄不畅，细菌易于在胆道内滋生，并向肝蔓延。肿瘤复发转移（A错）不会出现寒战高热、白细胞增多等急性炎症的表现。患者手术远在一年之前，因此手术时输血感染（C错）可能性很小。患者术后恢复好，并未提及易感染等提示免疫功能低下（D错）的表现。","c70","N"],["2013-N116",32,"第五节 胆道感染","急性梗阻性化脓性胆管炎临床表现",2013,116,"A","","女性，82岁，上腹痛、尿黄1周，1天来寒战、高热。有高血压、糖尿病病史，药物控制，半年前心肌梗死。查体：T39．5℃，P120次/分，BP96/82mmHg，神志淡漠，皮肤、巩膜黄染，右上腹部压痛，Hb115g/L，WBC22×10⁹/L。B超提示肝内外胆管扩张，胆囊增大，总胆管远端显示不清。此病状最符合",[["A","Charcot三联征"],["B","Reynolds五联征"],["C","Whipple三联征"],["D","Grey-Turner征"]],"B","老年女性患者，上腹痛伴尿黄，有寒战高热等感染中毒症状，血压降低、脉快，右上腹压痛。B超提示肝内外胆管扩张，胆囊增大，总胆管远端显示不清，为胆管梗阻征象，诊断考虑急性梗阻性化脓性胆管炎，其典型表现为Reynolds五联征（B对），包括寒战高热、腹痛、黄疸、休克及神经系统抑制表现。Charcot三联征（十版外科学P469）（A错）为胆管炎的典型表现，包括寒战高热、腹痛、黄疸。Whipple三联征（十版外科学P496）（C错）为胰岛素瘤的典型表现，包括空腹或运动后低血糖症状；症状发作时血糖低于2.22mmol/L；进食或静脉推注葡萄糖可迅速缓解症状。Grey-Turner征（十版外科学P488）（D错）为重症胰腺炎的典型表现，表现为腰部、季肋部和下腹部皮肤出现大片青紫色瘀斑。","c71","N"],["2013-N117",32,"第五节 胆道感染","急性梗阻性化脓性胆管炎治疗",2013,117,"A","","女性，82岁，上腹痛、尿黄1周，1天来寒战、高热。有高血压、糖尿病病史，药物控制，半年前心肌梗死。查体：T39．5℃，P120次/分，BP96/82mmHg，神志淡漠，皮肤、巩膜黄染，右上腹部压痛，Hb115g/L，WBC22×10⁹/L。B超提示肝内外胆管扩张，胆囊增大，总胆管远端显示不清。下列治疗方法中不宜采取的是",[["A","ENBD"],["B","急诊探查总胆管并引流"],["C","PTCD"],["D","先保守治疗，待休克纠正后手术"]],"D","重症胆管炎所致严重的临床过程多半与胆管系统内高压和细菌通过毛细胆管的肝细胞屏障直接进入肝血流中有关。重症急性胆管炎的发展有时异常迅猛，因此应早期采取积极的措施。若不及时解除胆道梗阻，则不可能阻止胆汁或细菌向血液的反流，无法阻止病情的恶化，因此，不能先保守治疗，待休克纠正后手术（D错，为本题正确答案）。恰当的处理原则是紧急手术，切开胆总管减压，去除结石、解除梗阻、通畅引流胆道，即急诊探查总胆管并引流（B对）。在病人生命体征允许的情况下，AOSC也可采用ENBD（A对）（经鼻胆管引流术）或PTCD（C对）（经皮肝穿刺胆道外引流术）治疗，都能够减轻阻塞胆管内压力，引流含化脓菌的胆汁。","c71","N"],["2013-N118",43,"第二节 姿态性畸形","脊柱侧凸",2013,118,"A","","女性，13岁。1年前无意中发现双肩背部不等高，后逐渐明显。X线显示胸椎侧凸畸形，Cobb角25度，临床诊断为特发性脊柱侧凸。对该患者的最佳治疗方案是",[["A","改变坐姿"],["B","牵引按摩治疗，每月随诊一次"],["C","佩戴支具，每半年随诊一次"],["D","立即手术治疗"]],"C","青少年特发性脊柱侧凸的治疗原则是根据Cobb角决定的，其治疗原则为：①Cobb角＜20°，应观察随访，主要目的是观察脊柱畸形是否发展；②Cobb角在20°～40°之间，应行支具治疗，治疗期间定期复查随访；③支具治疗无效，Cobb角度超过40°～50°则应行手术治疗。该患者Cobb角25°，应佩戴支具，定期随诊（C对），以监测疾病进展及进行治疗效果评估。","c72","N"],["2013-N119",43,"第二节 姿态性畸形","脊柱侧凸",2013,119,"A","","女性，13岁。1年前无意中发现双肩背部不等高，后逐渐明显。X线显示胸椎侧凸畸形，Cobb角25度，临床诊断为特发性脊柱侧凸。其治疗目的是",[["A","找到病因，去除病因"],["B","尽早手术，矫正畸形"],["C","维持目前状态，待骨骼成熟后再行手术治疗"],["D","矫正畸形，获得稳定，维持平衡"]],"D","脊柱侧凸的治疗目的为矫正畸形，获得稳定，维持平衡（D对）。特发性脊柱侧凸病因尚不明确，不可能找到病因，去除病因（A错）。尽早手术，矫正畸形（B错）、维持目前状态，待骨骼成熟后再行手术治疗（C错）属于治疗方法，而不属于治疗目的范畴。","c72","N"],["2013-N120",43,"第二节 姿态性畸形","脊柱侧凸",2013,120,"A","","女性，13岁。1年前无意中发现双肩背部不等高，后逐渐明显。X线显示胸椎侧凸畸形，Cobb角25度，临床诊断为特发性脊柱侧凸。关于该病，以下说法不正确的是",[["A","属于非结构性脊柱侧凸"],["B","最常见，约占脊柱侧凸75%-80%"],["C","严重胸廓畸形，可使肺受压变形，引起通气功能障碍"],["D","可分为婴儿型，少儿型，青少年型及成人型"]],"A","脊柱侧凸分为非结构性脊柱侧凸和结构性脊柱侧凸，特发性脊柱侧凸属于结构性脊柱侧凸（A错，为本题正确答案），最常见，约占脊柱侧凸75%～80%（B对）。根据其发病年龄，又分为：①婴儿型（0～3岁）；②少儿型（4～10岁）；③青少年型（11～18岁）；④成人型（＞18岁）（D对）。严重的脊柱侧凸可导致严重胸廓畸形，可使肺受压变形，引起通气功能障碍（C对），导致肺源性心脏病。","c72","N"],["2013-N145",28,"第三节 特殊类型阑尾炎","小儿急性阑尾炎",2013,145,"B","","6岁儿童诊断为急性阑尾炎，治疗应选择",[["A","抗生素治疗"],["B","保守治疗无效再手术"],["C","中药治疗"],["D","尽早手术"]],"D","由于缺乏大网膜的保护，加上小儿自身的免疫系统尚不健全，阑尾处炎症反应产物和细菌感染易于扩散，故小儿病情发展快且较重，穿孔率较高，并发症和死亡率也较高，故对于小儿急性阑尾炎，治疗时应尽早手术（D对）。抗生素治疗（A错）适用于单纯性阑尾炎、急性阑尾炎早期阶段。保守治疗无效再手术（B错）是阑尾脓肿的治疗原则。中药治疗（C错）较少用于急性阑尾炎的治疗。","","N"],["2013-N146",28,"第三节 特殊类型阑尾炎","妊娠期急性阑尾炎",2013,146,"B","","妊娠36周孕妇诊断为急性化脓性阑尾炎，治疗应选择",[["A","抗生素治疗"],["B","保守治疗无效再手术"],["C","中药治疗"],["D","尽早手术"]],"D","妊娠期急性化脓性阑尾炎若不及时治疗，炎症发展易导致流产或早产，威胁母子生命安全，妊娠36周为妊娠后期，此时急性化脓性阑尾炎的治疗应选择尽早手术（D对），抗生素治疗（A错）适用于单纯性阑尾炎、急性阑尾炎早期阶段。保守治疗无效再手术（B错）是阑尾脓肿的治疗原则。中药治疗（C错）较少用于急性化脓性阑尾炎的治疗。","","N"],["2013-N147",33,"第五节 胰腺神经内分泌肿瘤","胃泌素瘤临床表现",2013,147,"B","","最容易发生消化性溃疡的是",[["A","Zollinger-Ellison综合征"],["B","Gardner综合征"],["C","Peutz-Jeghers综合征"],["D","Budd-Chiari综合征"]],"A","Zollinger-Ellison 综合征（A对）即胃泌素瘤，胃泌素瘤分泌大量的促胃液素，不断刺激胃壁细胞分泌大量胃酸，最终造成胃十二指肠黏膜损伤，发生糜烂和溃疡。Gardner综合征（B错），是染色体显性遗传疾病，主要表现为肠息肉病合并多发性骨瘤和多发性软组织瘤，与消化性溃疡发生无关。Peutz-Jeghers综合征（C错）亦称黑斑息肉病，特点为胃肠道多发性息肉伴口腔黏膜、口唇、口周、肛周及双手指掌、足底黑色素沉着，以小肠息肉为主，约30％的病人有结直肠息肉，与消化性溃疡发生无关。Budd-Chiari综合征（D错），指布加综合征，由各种原因所致肝静脉和其开口以上，下腔静脉阻塞性病变引起的常伴有下腔静脉高压为特点的一种肝后门脉高压症。急性期病人有发热、右上腹痛、迅速出现大量腹腔积液、黄疸、肝大，肝区有触痛，少尿。与消化性溃疡发生无关。","","N"],["2013-N148",31,"","",2013,148,"B","","完全与恶性肿瘤无关的是",[["A","Zollinger-Ellison综合征"],["B","Gardner综合征"],["C","Peutz-Jeghers综合征"],["D","Budd-Chiari综合征"]],"D","Zollinger-Ellison综合征（A错）即胃泌素瘤，分泌大量的促胃液素，不断刺激胃壁细胞分泌大量胃酸，最终造成胃十二指肠黏膜损伤，发生糜烂和溃疡。60%～70%胃泌素瘤为恶性。结直肠息肉若为多发性绒毛状腺瘤，则称为Gardner综合征（B错），系染色体显性遗传疾病，癌变率达50%。Peutz-Jeghers综合征（C错）亦称黑斑息肉病，特点为胃肠道多发性息肉伴口腔黏膜、口唇、口周、肛周及双手指掌、足底黑色素沉着，以小肠息肉为主，约30%的病人有结直肠息肉，可发生癌变。Budd-Chiari综合征（D对），指布加综合征，由各种原因所致肝静脉和其开口以上，下腔静脉阻塞性病变引起的常伴有下腔静脉高压为特点的一种肝后门脉高压症。急性期病人有发热、右上腹痛、迅速出现大量腹腔积液、黄疸、肝大，肝区有触痛，少尿。为非肿瘤性疾病，与恶性肿瘤无关。","","N"],["2013-N149",44,"第三节 骨折的并发症","创伤性骨化性肌炎",2013,149,"B","","肘关节骨折后易发生的并发症是",[["A","缺血性骨坏死"],["B","骨化性肌炎"],["C","创伤性关节炎"],["D","关节僵硬"]],"B","肘关节骨折，例如肱骨髁上骨折，反复暴力复位或骨折后肘关节伸屈活动受限而进行反复牵拉，可导致骨膜剥离形成骨膜下血肿，血肿机化并在关节附近软组织内广泛骨化，造成严重的关节活动功能障碍，称为骨化性肌炎（B对），亦称损伤性骨化。特别多见于肘关节。缺血性骨坏死（A错）常见于腕舟状骨骨折后近侧骨折端缺血性坏死，股骨颈骨折后股骨头缺血性坏死。创伤性关节炎（C错）常见于关节内骨折，肘关节骨折后也可发生创伤性关节炎，但肘关节关节内骨折不如关节外骨折常见。关节僵硬（D错）是骨折和关节损伤最为常见的并发症，也可发生于肘关节骨折。此二者虽也可发生于肘关节骨折，但肘关节骨折最易发生的并发症是骨化性肌炎。","","N"],["2013-N150",44,"第三节 骨折的并发症","缺血性骨坏死",2013,150,"B","","腕舟状骨骨折后发生的并发症是",[["A","缺血性骨坏死"],["B","骨化性肌炎"],["C","创伤性关节炎"],["D","关节僵硬"]],"A","骨折使某一骨折段的血液供应被破坏，易发生该骨折段缺血性坏死，常见于腕舟状骨近端骨折段缺血性骨坏死（A对），股骨颈骨折后股骨头缺血性坏死。骨化性肌炎（B错），又称损伤性骨化，由于关节扭伤、脱位或关节附近骨折，骨膜剥离形成骨膜下血肿，处理不当使血肿扩大，血肿机化并在关节附近软组织内广泛骨化，造成严重关节活动功能障碍，特别多见于肘关节，如肱骨髁上骨折。创伤性关节炎（C错）多见于关节内骨折，关节面遭到破坏，又未能准确复位，骨愈合后使关节面不平整，长期磨损易引起创伤性关节炎，致使关节活动时出现疼痛。关节僵硬（D错）是指患肢长时间固定，静脉和淋巴回流不畅，关节周围组织中浆液纤维性渗出和纤维蛋白沉积，发生纤维粘连，并伴有关节囊和周围肌肉挛缩，致使关节活动障碍。这是骨折和关节损伤最为常见的并发症，常发生于关节附近的骨折。","","N"],["2013-N175",18,"第三节 乳腺良性疾病","乳腺囊性增生病临床表现",2013,175,"X","","乳腺囊性增生病的特点有",[["A","乳腺疼痛和结节为突出表现"],["B","触诊可触及颗粒样肿块"],["C","易发生乳腺癌"],["D","一般不必药物治疗"]],"ABD","乳腺囊性增生病的突出表现是乳房胀痛和肿块（A对），特点是部分病人有周期性，即乳房胀痛一般于月经前明显，月经后减轻，严重者整个月经周期都有疼痛。触诊发现一侧或双侧乳腺有弥漫性增厚，肿块呈颗粒状（B对）、结节状或片状，大小不一，质韧而不硬，边界不清。治疗主要是对症治疗，且疼痛通常与月经周期有关，可自行缓解，故一般不必药物治疗（D对）。本病有无恶变尚无定论（C错）。","","N"],["2013-N176",40,"第二节 良性前列腺增生的诊断","良性前列腺增生临床表现",2013,176,"X","","前列腺增生可出现的并发症有",[["A","肾功能衰竭"],["B","癌变"],["C","腹股沟疝"],["D","无痛性血尿"]],"ACD","长期排尿困难使得膀胱高度膨胀，内压升高，输尿管末端丧失其活瓣作用，导致膀胱输尿管反流，引起肾积水、肾功能不全，乃至肾功能衰竭（A对）。前列腺增生可致下尿路梗阻，病人排尿困难，需通过增加腹压促进排尿，长此以往可出现腹股沟疝（C对）、脱肛和痔疮等。无痛性血尿（D对）可见于前列腺增生，因为增生腺体表面黏膜较大的血管破裂。前列腺增生为良性病变，主要为前列腺移行带肥大，而前列腺癌好发部位为前列腺外周带。因此，一般认为前列腺增生与前列腺癌无关（B错）。","","N"],["2013-N177",32,"第四节 胆石症","胆囊结石治疗",2013,177,"X","","下列胆囊结石病人应行胆囊切除术的情况有",[["A","年轻人无症状"],["B","常发作右上腹痛"],["C","结石＞2cm"],["D","伴有糖尿病"]],"BCD","部分单发或多发的胆囊结石，在胆囊内自由移动，不易发生嵌顿，很少产生症状，被称为无症状胆囊结石（静止性胆囊结石），年轻人无症状（A错）的胆囊结石一般不需预防性手术治疗，可观察和随诊。胆囊结石常发作右上腹痛（B对），说明患者存在明显临床症状，应在控制症状后行择期胆囊切除术。结石＞2cm（C对），说明结石大无法自行溶解或排出体外，需通过手术方能治疗。伴有糖尿病（D对）的胆囊结石病人，无论其有无症状，在出现糖尿病的心血管、肾的并发症之前将胆囊切除比出现并发症之后手术更为安全。","","N"],["2013-N178",26,"第一节 解剖生理概要","胃的神经",2013,178,"X","","应用高选择性迷走神经切断术治疗十二指肠溃疡病，手术时注意保留",[["A","迷走神经的前后干"],["B","肝支"],["C","腹腔支"],["D","分布到胃窦的“鸦爪”支"]],"ABCD","高选择性迷走神经切断术只切断胃大部近端的迷走神经（A对），切断胃前、后latarjet神经分支（胃前、后支），保留迷走神经肝支（B对）、腹腔支（C对）和“鸦爪”支神经（D对），不必附加引流手术，相比迷走神经干切断术和选择性迷走神经切断术，高选择性迷走神经切断术可降低胃肠功能的紊乱，尤其是倾倒综合征、腹泻和胆汁反流等。","","N"],["2013-N179",53,"第二节 腰椎退行性疾病","反射异常",2013,179,"X","","腰椎间盘突出症骶₁神经根受压时的临床表现有",[["A","外踝附近及足外侧痛、触觉减退"],["B","踝及伸拇肌力下降"],["C","踝反射减弱或消失"],["D","直腿抬高试验及加强试验阳性"]],"ACD","腰椎间盘突出症骶₁神经根受压时的临床表现包括：外踝附近及足外侧痛、触觉减退（A对）；踝反射减弱或消失（C对）。腰椎间盘突出症一般均可出现直腿抬高试验及加强试验阳性（D对）。踝及伸拇肌力下降（B错）为腰₅神经根受压时的临床表现。","","N"],["2013-N180",43,"第一节 先天性畸形","先天性肌性斜颈临床表现",2013,180,"X","","先天性肌性斜颈的临床表现错误的有",[["A","头向健侧偏斜"],["B","下颌向健侧偏斜"],["C","患侧脸部发育较大"],["D","健侧脸部发育较大"]],"AC","单侧胸锁乳突肌挛缩可导致先天性斜颈，挛缩的肌肉牵引位于耳后的乳突，引起头向肌肉挛缩的患侧偏（A错，为本题正确答案），而下颌转向健侧（B对）。患病幼儿颈部活动受限制，平卧时病儿总是睡在患侧，从而使患侧头面部经常受压，长期以往，双侧面部发育不对称，未受压的健侧脸部发育较大（D对），而患侧脸部发育较小（C错，为本题正确答案），患侧眼的外眦与同侧口角的距离小于健侧。","","N"],["2014-N41",7,"第一节 热力烧伤","浅Ⅱ度烧伤",2014,41,"A","","男性，16岁，左手烫伤，红肿，少数水泡，无感染。经治疗痊愈，局部皮肤组织的病理变化表现为",[["A","纤维瘢痕形成"],["B","皮肤附属器破坏"],["C","毛细血管增生"],["D","正常皮肤"]],"D","Ⅰ°烧伤有明显红斑、疼痛和灼烧感，不见水疱；浅Ⅱ°烧伤局部红肿明显，有大小不一的水疱形成，水疱皮如剥脱，创面红润、潮湿、疼痛明显；深Ⅱ°烧伤也可有水泡，但去水疱皮后，创面微湿，红白相间，痛觉较迟钝；Ⅲ°烧伤创面焦黄、无水泡、痛觉消失。患者16岁，处于青少年阶段，皮肤再生能力强，左手烫伤，红肿，少数水泡，无感染，属于浅Ⅱ°烧伤，皮肤细胞可完全再生，不留瘢痕（A错），形成正常皮肤（D对）。浅Ⅱ°烧伤不伤及位于真皮乳头层以下的皮肤附属器和毛细血管（十版外科学P73 图10-1），经治疗痊愈后，既无皮肤附属器破坏（B错），也无毛细血管增生（需要在原有血管基底膜降解的基础上发生）（C错）。","","N"],["2014-N77",5,"第三节 手、足部急性化脓性细菌感染","甲沟炎和脓性指（趾）头炎预防和治疗",2014,77,"A","","中指脓性指头炎如治疗不及时，最易发生的并发症是",[["A","败血症"],["B","掌中间隙感染"],["C","末节指骨缺血坏死"],["D","化脓性腱鞘炎"]],"C","在发生脓性指头炎时，虽然可有发热、白细胞计数增高等全身中毒症状，但因此导致败血症者少见（A错）。掌中间隙感染（B错）多由中指和环指腱鞘感染蔓延所致，化脓性腱鞘炎（D错）多为局部刺伤后继发细菌感染所致，此两者均不是来源于脓性指头炎。中指脓性指头炎是中指末节掌面的皮下化脓性细菌感染，形成压力很高的脓腔，除引起剧烈疼痛外，还能压迫末节指骨的滋养血管，引起指骨缺血、坏死；如果治疗不及时，脓液直接侵及指骨，易引起骨髓炎（C对）。","","N"],["2014-N78",18,"第四节 乳腺癌","前哨淋巴结活检术及腋淋巴结清扫术",2014,78,"A","","乳腺癌的前哨淋巴结活检适合于",[["A","癌块﹤2cm"],["B","癌块﹥2cm"],["C","临床腋窝淋巴结阳性者"],["D","临床腋窝淋巴结阴性者"]],"D","前哨淋巴结活检指患侧腋窝中接受乳腺癌淋巴引流的第一站淋巴结，可采用示踪剂显示后切除活检。根据前哨淋巴结的病理结果预测腋淋巴结是否有肿瘤转移，对前哨淋巴结阴性的乳腺癌病人可不做腋淋巴结清扫。前哨淋巴结活检适用于临床腋淋巴结阴性的乳腺癌病人（D对）。前哨淋巴结活检的目的是判断乳腺癌有无淋巴结转移，与癌块大小无关（AB错）；若临床腋窝淋巴结阳性，则无需前哨淋巴结活检也能确定发生了淋巴结转移，必须做淋巴结清扫（C错）。","","N"],["2014-N79",29,"第七节 直肠癌","Hartmann手术",2014,79,"A","","男性，73岁。因肠梗阻4天手术探查，术中发现直肠、乙状结肠交接部直径约3cm肿瘤，尚可活动，近段结肠扩张、水肿。合理手术方式是",[["A","横结肠造口术"],["B","Miles手术"],["C","Dixon手术"],["D","Hartmann手术"]],"D","老年患者，肠梗阻4天，术中发现近段结肠扩张、水肿，此时病人全身情况一般很差，不能耐受Miles手术，急性肠梗阻又不宜行Dixon手术。此时合理的手术方式为Hartmann手术（D对），即经腹直肠癌切除、近端造口、远端封闭手术，留待二期还纳。直肠癌并发肠梗阻急诊手术时，可行乙状结肠双腔造口，而非横结肠造口（A错）。Miles手术（腹会阴联合直肠癌根治术）（B错）适用于肿块下缘距肛缘小于5cm患者，在部分肿瘤大、浸润明显患者，肿块下缘距离肛缘7cm者亦可行Miles手术。Dixon手术（C错）（经腹直肠癌切除术）适用于距离肛缘5～7cm以上患者。","","N"],["2014-N80",24,"第二节 常见内脏损伤的特征和处理","十二指肠损伤诊断",2014,80,"A","","腹部闭合性损伤手术探查时发现横结肠系膜根部有很多气泡，应高度怀疑的创伤是",[["A","空肠破裂"],["B","十二指肠破裂"],["C","直肠破裂"],["D","横结肠破裂"]],"B","本题中结肠系膜根部是很关键的解题点。出现气泡，通常是空腔脏器（主要是胃、十二指肠和结肠，少见于小肠）破裂的证据；手术探查时发现横结肠系膜根部有很多气泡，因横结肠系膜根部覆盖于腹膜后，可得出损伤位于腹膜后。空肠、横结肠为腹膜内位器官，其破损若有气体，应位于腹腔内，因而不考虑空肠破裂（A错）及横结肠破裂（D错）；直肠分为上中下三部分，上部分位于腹膜间位，中、下部分为腹膜外位器官；上部破裂多与结肠破裂表现相同，直肠中下部的损伤更多表现为直肠周围间隙感染，无腹膜炎症状（十版外科学P361），因此不考虑直肠破裂（C错）。十二指肠分为四段：球部、降部、水平部和升部。其中球部和升部为腹膜内位器官，而处在中间的降部和水平部为腹膜外位器官，若此两段破裂，肠道内气体可积存于腹膜后的腔隙中（B对）。","","N"],["2014-N81",32,"第五节 胆道感染","急性结石性胆囊炎辅助检查",2014,81,"A","","男性，56岁。一年前因胆管癌行肿瘤切除、胆肠吻合术，半年来反复发热，服抗生素有效，考虑可能有胆道感染。为确诊应采取的方法是",[["A","肝胆B超"],["B","发热时查肝功能"],["C","MRCP"],["D","上腹CT"]],"B","患者曾行肿瘤切除、胆肠吻合术，患者胆道原先的解剖结构改变，胆管直接与空肠吻合。因术后解剖结构的改变，肠道内容物易反流进入胆道从而引起反复发作的胆道感染。对于该病人的检查，不应首选肝胆B超（A错）检查，因为肠腔内气体将影响B超的效果，无法得到准确影像。上腹CT（D错）本身可以显示胆道，但其诊断胆道感染需要结合血中炎性指标和肝功能。由梗阻造成的胆道感染患者，尿胆红素阳性，血胆红素升高，尤其是直接血胆红素升高，ALP升高，肝功能改变，因此发热时查肝功能（B对）对诊断胆道感染有一定的提示意义。胆肠吻合术后胆道感染可以由胆道反流、吻合口狭窄等原因引起，但主要原因为反流。MRCP（C）可直接清晰地显示胆道树、胆道及吻合口狭窄部位以及有无肿瘤复发等，但对反流的作用有限。本题官方参考答案为B，C选项略有争议，但B选项似乎更佳。","","N"],["2014-N82",17,"第一节 甲状腺疾病","手术治疗",2014,82,"A","","女性，29岁。因右侧甲状腺结节行手术治疗，术中见甲状腺右叶直径1.5cm囊实性结节，未触及肿大淋巴结，冰冻切片提示甲状腺乳头状癌。应采取的手术方式是",[["A","甲状腺近全切除术"],["B","甲状腺全切及颈淋巴结清扫术"],["C","右侧腺叶切除术"],["D","右侧腺叶加峡部切除术"]],"B","目前有关甲状腺的切除范围仍有分歧，且缺乏前瞻性随机对照实验结果的依据，但完全切除肿瘤十分重要，文献提示肿瘤是否完全切除是一项独立预后因素。本例为年轻女性患者，病理检查为低危乳头状癌，肿瘤直径1.5cm，根据老版本教材（7版外科学），手术首选方式为右侧腺叶+峡部切除术（D）。但最新NCCN指南以及新版教材指出，对于局限于一侧腺叶内的单发PTC（甲状腺乳头状癌），肿瘤≤1cm的，复发危险度低，对侧腺叶内无结节，无颈部淋巴结转移和远处转移者适用于作甲状腺腺叶+峡部切除术；对肿瘤＞4cm，多癌灶，尤其是双侧癌灶，不良病理亚型，已有远处转移，需要术后¹³¹I治疗，伴有双侧颈部淋巴结转移，伴有腺外侵犯者宜行全甲状腺切除或近甲状腺切除术；而对肿瘤直径1～4cm者，有主张做甲状腺腺叶＋峡部切除术，也有主张行全甲状腺切除或近全甲状腺切除术。根据最新观点以及临床实际情况，本例患者宜采取全甲状腺切除或近全甲状腺切除术（AB），单侧腺叶切除是不能满足临床预后的（C错）。同时，对于所有分化型甲状腺癌病人，术中在有效保护甲状旁腺和喉返神经的情况下，至少行病灶同侧中央区淋巴结清扫术在国内已达成共识（B）。本题官方给出的参考答案为D，但根据最新观点，应选择B。","","N"],["2014-N83",18,"第四节 乳腺癌","浸润性特殊癌",2014,83,"A","","下列乳腺癌的病理类型中，预后较好的是",[["A","黏液腺癌"],["B","浸润性小叶癌"],["C","浸润性导管癌"],["D","硬癌"]],"A","黏液腺癌（A对）属浸润性特殊癌，是乳腺癌的病理类型中预后较好的，分化一般较高。浸润性小叶癌（B错）、浸润性导管癌（C错）、硬癌（D错）属于浸润性非特殊癌，一般分化低，预后较差。","","N"],["2014-N84",19,"第一节 胸部损伤概论","院内急诊处理",2014,84,"A","","下列胸部损伤中须考虑手术探查的是",[["A","胸腹联合伤"],["B","胸部爆震伤"],["C","胸骨损伤"],["D","创伤性窒息"]],"A","胸腹联合伤：胸腹外伤史，可能伤及膈肌及其邻近的腹腔脏器，需要考虑开胸和（或）开腹探查（A对）。胸部爆震伤（B错）的救治在于维护呼吸和循环功能，包括保持呼吸道通畅、给氧、必要时行气管切开和人工呼吸器辅助呼吸以及输血补液抗休克。胸骨骨折（十版外科学P257-P258）（C错）单纯无移位者以卧床休息、止痛为主，有移位者以手法或手术复位。创伤性窒息（十版外科学P260-P261）（D错）是钝性暴力作用于胸部所致的上半身广泛皮肤、黏膜、末梢毛细血管淤血及出血性损害。创伤性窒息所致出血点及瘀斑，一般于2～3周后自行吸收消退。一般病人在严密观察下对症处理，有合并伤者应针对具体伤情给予积极处理。","","N"],["2014-N85",38,"第五节 尿道损伤","局部血肿",2014,85,"A","","尿道膜部损伤后血肿最常见的部位是",[["A","会阴部"],["B","阴囊部"],["C","尿生殖膈以上"],["D","下腹壁"]],"C","膜部和球部以尿生殖膈为界，膜部位于尿生殖膈以上，球部位于尿生殖膈以下。膜部的损伤，出血及血肿最常位于尿生殖膈以上（C对），如耻骨后间隙、膀胱周围。前尿道（尿道球部）损伤后，血肿和尿液常积聚在尿生殖膈以下的部位，如会阴部（A错）、阴茎、阴囊部（B错）、下腹壁（D错）等。","","N"],["2014-N86",29,"第七节 直肠癌","低位前切除术",2014,86,"A","","目前认为Dixon手术的远端切缘至肿瘤最短距离应是",[["A","2cm"],["B","3cm"],["C","4cm"],["D","5cm"]],"A","大宗病例报道发现肿瘤下缘平面以下淋巴结阳性者仅6.5%，平面以下2cm仍有淋巴结阳性者仅2%。因此Dixon手术要求远端切缘距肿瘤的最短距离是2cm（A对）。","","N"],["2014-N87",23,"第二节 腹股沟疝","嵌顿性和绞窄性疝的处理原则",2014,87,"A","","男性，75岁。因腹股沟斜疝嵌顿2天急诊手术。术中见疝囊有大团小肠，仍有活动，并有少量淡黄色渗出液，松解疝环，将小肠还纳腹腔并作疝修补术。术后第二天，病人觉腹痛较前加重，T38.8℃，腹部压痛、反跳痛、肌紧张，WBC18×10⁹/L．最可能的原因是",[["A","术中腹腔感染"],["B","术中损伤肠管"],["C","缺血性肠病发作"],["D","遗漏术中坏死肠袢"]],"D","术中腹腔感染（A错）症状通常发生于3～5天后，但该患者于术后第二天便出现症状，故不考虑术中腹腔感染。术中损伤肠管（B错），则因肠内容物流入腹腔，术后应立即出现腹膜刺激征，故不考虑术中损伤肠管。缺血性肠病的特征为严重的症状与轻微的体征不相符，但该患者第二天症状与体征同时出现（C错），故不考虑缺血性肠病发作。嵌顿疝发生后，由于疝囊颈的相对狭窄，使疝内容物（多数为肠管）的血供存在障碍，若长时间如此，势必发生疝内容物的缺血坏死，导致肠穿孔；患者绞窄疝两天后急诊手术，疝囊内有大团小肠，可能是逆行性嵌顿疝，术中未检查腹腔内的中间肠袢是否坏死，而直接将小肠还纳腹腔并作疝修补术。患者出现的腹膜刺激征（腹部压痛、反跳痛、肌紧张），最有可能是遗漏的坏死肠袢（D对）在术后穿孔引起的腹膜炎。","","N"],["2014-N88",46,"第一节 手外伤","神经损伤的检查",2014,88,"A","","女性，48岁。左腕部玻璃切割伤。表现为左腕部掌侧斜行切口，深达肌层，左手呈爪手畸形，拇指对掌功能丧失，手指浅感觉丧失。其损伤的神经是",[["A","正中神经"],["B","尺神经及桡神经"],["C","桡神经及正中神经"],["D","尺神经及正中神经"]],"D","患者伤后左手呈爪手畸形（提示尺神经损伤），拇指对掌功能丧失（猿手）（提示正中神经损伤），手指浅感觉丧失，考虑其损伤的神经是尺神经及正中神经（D对）。桡神经（BC错）损伤表现为垂腕，伸拇、伸指障碍。另外，胸长神经和副神经损伤表现为翼状肩；腋神经损伤表现为方肩；胫神经损伤表现为钩状足；腓总神经损伤表现为马蹄内翻足。","","N"],["2014-N89",53,"","",2014,89,"A","","脊髓型颈椎病早期出现的症状是",[["A","四肢乏力，持物不稳"],["B","颈肩痛向上肢放射"],["C","头痛、心悸"],["D","眩晕"]],"A","脊髓型颈椎病发病机制为颈椎退变结构压迫脊髓。病人表现为上肢或下肢麻木无力、僵硬、双足踩棉花感，足尖不能离地，触觉障碍、束胸感，双手精细动作笨拙，不能用筷进餐，写字颤抖，夹持东西无力，手持物经常掉落（A对）。颈肩痛向上肢放射（B错）为神经根型颈椎病（十版外科学P718）的典型表现，因为神经根为侧后方突出的颈椎间盘或增生肥大的钩椎关节或关节突压迫。头痛、心悸（C错）为交感神经型颈椎病的典型表现，此型发病原因不明。眩晕（D错）为椎动脉型颈椎病（十版外科学P719）的典型表现，因为椎动脉遭受压迫或刺激，导致椎-基底动脉供血不足。","","N"],["2014-N90",47,"第七节 膝关节半月板损伤","膝关节半月板损伤影像学检查与关节镜检查",2014,90,"A","","男性，34岁。1年前打篮球受伤后膝关节经常隐痛，检查发现：右膝前内侧关节间隙处有压痛，McMurray试验阳性，最有可能的诊断是",[["A","内侧副韧带损伤"],["B","内侧半月板损伤"],["C","前十字韧带损伤"],["D","创伤性关节炎"]],"B","McMurray试验即旋转挤压实验，将被检查者的下肢置于内收（或外展）同时内旋（或外旋）位，自极度屈曲位逐渐被动伸直，以检查在此过程中出现的疼痛、弹响及弹动感，为半月板损伤检查特征性试验。该患者McMurray试验阳性，提示存在半月板损伤。右膝前内侧关节间隙处有压痛，提示为右膝关节内侧半月板损伤（B对）。内侧副韧带损伤（A错）可有固定的压痛点，其特征性体征为侧方应力试验阳性。十字韧带损伤（C错）的特征性体征为膝关节处的抽屉实验阳性。创伤性关节炎（D错）为骨折的晚期并发症，患者并无骨折病史。","","N"],["2014-N91",35,"急腹症","月经史",2014,91,"A","","女性，22岁。无诱因突发右下腹部剧烈疼痛，向腰骶及会阴部放射，伴头晕、恶心、出大汗、欲排大便感，未作任何处理来院急诊。在询问病史中，对明确腹痛病因价值最大的是",[["A","转移性腹痛史"],["B","泌尿系结石史"],["C","婚姻月经史"],["D","不洁饮食史"]],"C","22岁女性患者（育龄期），无诱因突发右下腹剧痛，向腰骶部及会阴部放射（异位妊娠破裂常见临床表现），伴头晕、恶心、出大汗（内出血征象）、欲排大便感（提示盆腔内有积血），诊断考虑输卵管异位妊娠破裂出血。妊娠时，妊娠黄体分泌大量的雌激素及孕激素可导致停经，因此对明确腹痛病因价值最大的是婚姻月经史（C对）。转移性腹痛史（A错）多提示急性阑尾炎，但阑尾炎一般不出现内出血征象。泌尿系结石史（B错）多表现为阵发性绞痛，不出现内出血征象。不洁饮食史（D错）多提示急性胃肠炎，亦不出现内出血征象。","","N"],["2014-N92",35,"急腹症","消化道症状",2014,92,"A","","女性，22岁。无诱因突发右下腹部剧烈疼痛，向腰骶及会阴部放射，伴头痛、恶心、出大汗、欲排大便感，未作任何处理来院急诊。该患者体检中不可能出现的体征是",[["A","肠鸣音亢进"],["B","腹部移动性浊音阳性"],["C","血压下降、心率增快"],["D","右下腹压痛、反跳痛"]],"A","异位妊娠破裂导致大量血液进入腹腔，腹部移动性浊音阳性（B对）。血液对腹膜有一定的刺激性，可引起腹膜刺激征，导致右下腹压痛、反跳痛（D对）。出血量大的病人可因循环血量不足，出现血压下降、心率增快（C对）。异位妊娠破裂导致大量血液进入腹腔，可引起腹膜刺激征，腹肌强直，肠鸣音一般不亢进（A错，为本题正确答案），甚至可消失。出血若进入肠腔内，可刺激肠道蠕动，导致肠鸣音活跃。","","N"],["2014-N111",32,"第五节 胆道感染","急性结石性胆囊炎辅助检查",2014,111,"A","","女性，80岁。3天来发现巩膜黄染、皮肤瘙痒，来院就诊。为了解黄疸性质，下列检查项目中最有意义的是",[["A","转氨酶水平"],["B","乙肝病毒标志物"],["C","DBiL/TBiL"],["D","AFP"]],"C","常见的黄疸分类包括梗阻性黄疸、肝细胞性黄疸和溶血性黄疸。为了解黄疸性质，最有意义的检查方法为测定DBil（直接胆红素）/TBil（总胆红素）（C对），溶血性黄疸其比值小于15%～20%；肝细胞性黄疸其比值大于30%～40%；胆汁淤积性黄疸其比值大于59%～60%。转氨酶水平（A错）仅能反应肝细胞受损情况，无法判断肝细胞损伤的原因。乙肝病毒标志物（B错）主要用于诊断乙型肝炎。AFP（D错）主要用于肝癌的诊断及预后判断。","","N"],["2014-N112",32,"第二节 胆道疾病影像学检查","胆道疾病超声检查",2014,112,"A","","女性，80岁。3天来发现巩膜黄染、皮肤瘙痒，来院就诊。为了解胆道是否有梗阻及梗阻部位，最简便的检查方法是",[["A","B型超声"],["B","CT"],["C","MRI"],["D","ERCP"]],"A","B型超声（A对）是诊断胆道梗阻经济简便易行，是最简单有效的影像学诊断方式。根据胆管有无扩张、扩张部位和程度，可了解胆道是否有梗阻及梗阻程度。如胆总管及以上胆管扩张，提示胆总管下端或壶腹部梗阻。如肝内外胆管均未扩张，多提示为非梗阻性黄疸。CT（B错）以及MRI（C错）虽然分辨率较B超高，但是其价格昂贵且操作不便，一般不作为首选检查。ERCP（D错）为有创检查，亦不作首选。","","N"],["2014-N113",32,"第五节 胆道感染","手术方法",2014,113,"A","","女性，80岁。3天来发现巩膜黄染、皮肤瘙痒，来院就诊。3天后患者突然高热，体温达39℃，WBC15．0×10⁹/L，此期最佳处理措施是",[["A","加大抗生素用量"],["B","PTCD"],["C","MRCP"],["D","急诊手术引流"]],"B","老年女性患者，黄疸3天，现突然出现高热、白细胞升高，考虑合并胆道感染，可行（经皮肝穿刺胆管引流）PTCD（B对）以解除胆道梗阻，防止胆道内压力过高，胆汁逆流入血，引起败血症等不良后果。若不解决梗阻，单纯加大抗生素用量（A错）治疗效果有限。MRCP（C错）即核磁共振胆胰管造影只能用于诊断疾病，不能用于治疗。高龄女性患者多难以耐受急诊手术引流（D错），须在进行充分的术前准备后方择期手术治疗。","","N"],["2014-N114",33,"第二节 胰腺炎","急性胰腺炎诊断",2014,114,"A","","女性，56岁。2天前突发持续上腹痛，阵发加剧，并腰背部胀痛，恶心、呕吐，急诊入院。既往有胆囊结石病史3年。查体：T36.9℃，P104次/分，R20次/分，BP130/80mmHg，巩膜无黄染，上腹较膨隆，压痛，轻度肌紧张及反跳痛，肠鸣音弱。化验：Hb128g/L，WBC16.7×10⁹/L，血淀粉酶786U/dl，尿淀粉酶1600U/dl。此病人最可能的诊断是",[["A","急性胰腺炎"],["B","急性胆管炎"],["C","急性胆囊炎"],["D","上消化道穿孔"]],"A","56岁女性患者，既往有胆囊结石病史3年（胰腺炎的常见致病危险因素）。2天前突发持续上腹痛，阵发加剧，并腰背部胀痛，恶心、呕吐（急性胰腺炎的常见临床表现）。查体：上腹较膨隆，压痛，轻度肌紧张及反跳痛（提示轻度腹膜刺激征），肠鸣音弱（提示麻痹性肠梗阻）。化验：WBC16.7×10⁹/L，血淀粉酶786U/dl，尿淀粉酶1600U/dl（淀粉酶测值远大于500U/dl，提示急性胰腺炎）。综合该患者的病史、体查、实验室检查，诊断考虑急性胰腺炎（A对）。急性胆管炎（B错）多有黄疸，肝区叩痛严重，且伴高热。急性胆囊炎（C错）以右上腹痛为著，右上腹压痛明显，淀粉酶可轻度升高。上消化道穿孔（D错）可伴有淀粉酶轻度升高，但穿孔所致腹膜炎刺激重，压痛反跳痛、肌紧张均明显。","c79","N"],["2014-N115",33,"第二节 胰腺炎","超声",2014,115,"A","","女性，56岁。2天前突发持续上腹痛，阵发加剧，并腰背部胀痛，恶心、呕吐，急诊入院。既往有胆囊结石病史3年。查体：T36.9℃，P104次/分，R20次/分，BP130/80mmHg，巩膜无黄染，上腹较膨隆，压痛，轻度肌紧张及反跳痛，肠鸣音弱。化验：Hb128g/L，WBC16.7×10⁹/L，血淀粉酶786U/dl，尿淀粉酶1600U/dl。为确定诊断，最简单有效的腹部检查方法是",[["A","CT"],["B","B超"],["C","MRI"],["D","X线片"]],"B","腹部超声（B对）诊断急性胰腺炎经济简便易行，是最简单有效的影像学诊断方式。可发现胰腺肿大和胰周液体积聚。胰腺水肿时显示为均匀低回声，出现粗大的强回声提示有出血、坏死的可能。CT（A错）和MRI（C错）分辨率高，但价格昂贵且操作繁琐，一般不作为首选。X线片（D错）对诊断胰腺炎价值有限。","c79","N"],["2014-N116",33,"第二节 胰腺炎","急性胰腺炎非手术治疗",2014,116,"A","","女性，56岁。2天前突发持续上腹痛，阵发加剧，并腰背部胀痛，恶心、呕吐，急诊入院。既往有胆囊结石病史3年。查体：T36.9℃，P104次/分，R20次/分，BP130/80mmHg，巩膜无黄染，上腹较膨隆，压痛，轻度肌紧张及反跳痛，肠鸣音弱。化验：Hb128g/L，WBC16.7×10⁹/L，血淀粉酶786U/dl，尿淀粉酶1600U/dl。诊断确定后，首先采取的治疗措施是",[["A","急诊手术切除胆囊"],["B","急诊总胆管探查"],["C","腹痛加重时手术探查"],["D","禁食、补液、胃肠减压等保守治疗"]],"D","急性胰腺炎的非手术治疗适用于急性胰腺炎全身反应期，水肿性及尚无感染的出血坏死性胰腺炎，其中禁食、补液、胃肠减压（D对）是最首要的治疗方式，可减少包括胃泌素、缩胆囊素、促胰液素在内的胃肠激素的分泌，从而减少胰液的分泌，有利于胰腺炎症的恢复及组织修复。此外，胃肠减压还可防止呕吐、减轻腹胀，降低腹内压。急性胰腺炎手术治疗适应证为：①急性腹膜炎不能排除其他急腹症时；②胰腺和胰周坏死组织继发感染；③伴胆总管下端梗阻或胆道感染者；④合并肠穿孔、大出血或胰腺假性囊肿。对于胆源性胰腺炎，手术方式包括胆囊切除+胆总管探查+胰周坏死组织清除+引流术。具体可参考七版黄家驷外科学P1837。","c79","N"],["2014-N117",33,"第三节 胰腺囊性疾病","胰腺假性囊肿治疗",2014,117,"A","","女性，56岁。2天前突发持续上腹痛，阵发加剧，并腰背部胀痛，恶心、呕吐，急诊入院。既往有胆囊结石病史3年。查体：T36.9℃，P104次/分，R20次/分，BP130/80mmHg，巩膜无黄染，上腹较膨隆，压痛，轻度肌紧张及反跳痛，肠鸣音弱。化验：Hb128g/L，WBC16.7×10⁹/L，血淀粉酶786U/dl，尿淀粉酶1600U/dl。2周后，病情尚平稳，但上腹部可触及一包块，B超显示为一7×6cm囊性肿物。此时应采取的治疗方法是",[["A","继续保守治疗"],["B","囊肿切开引流术"],["C","囊肿空肠吻合术"],["D","手术切除囊肿"]],"A","患者诊断为急性胰腺炎，2周后病情稳定，见到胰体尾部一个囊性肿物，病人无不适表现，诊断考虑胰腺假性囊肿。对于胰腺假性囊肿，在囊壁尚未成熟前，若检查排除恶性可能，可暂予非手术治疗。一般须待囊肿壁成熟后（6周以上）再作内引流或外引流术。因此，该患者此时需继续保守治疗（A对），2个月后处理囊肿和胆道。","c79","N"],["2014-N118",48,"第一节 脊柱骨折","脊柱骨折诊断",2014,118,"A","","男性，29岁。从3楼跌落，臀部着地，双下肢完全不能活动，双侧腹股沟平面感觉丧失，尿潴留。患者最可能的诊断是",[["A","第4胸椎骨折"],["B","第5腰椎骨折"],["C","第10胸椎骨折"],["D","骨盆骨折"]],"C","年轻男性患者，高空坠落臀部着地史，现双下肢不能活动，提示脊柱骨折合并脊髓损伤。双侧腹股沟平面感觉丧失，尿潴留，提示脊髓损伤在T₁₂。七版黄家驷外科学P2896页认为：胸段脊髓的神经离开脊髓后经椎间孔向外走行，自上而下，由横行变斜行至下胸椎。一般来讲，同序数的脊髓节段约比同序数的脊柱节段高2～3个节段。该患者脊髓损伤在T₁₂，因此最可能的诊断为第9或第10胸椎骨折（C对）。第4胸椎骨折（A错）多损伤T₆～T₇节段脊髓，感觉丧失平面应在剑突至肋弓下缘之间。第5腰椎骨折（B错）通常不会有脊髓损伤，因为成年人脊髓多终止于第一腰椎平面。骨盆骨折（D错）不会造成脊髓损伤，主要临床表现为失血性休克以及伴随的多发损伤。","","N"],["2014-N119",48,"第一节 脊柱骨折","脊柱骨折影像学检查",2014,119,"A","","男性，29岁。从3楼跌落，臀部着地，双下肢完全不能活动，双侧腹股沟平面感觉丧失，尿潴留。不必立即采取的检查项目是",[["A","MRI检查"],["B","心电图及血气分析检查"],["C","下肢肌电图检查"],["D","X线检查"]],"C","对于脊髓损伤，X线检查（D错）和CT检查为常规检查，可以发现脊髓损伤部位的脊柱骨折或脱位。MRI检查（A错）可观察到脊髓本身的信号强度、信号改变的范围和脊髓萎缩的情况等。心电图及血气分析（B错）为一般检查项目，可用于检查病人是否存在心脏病和呼吸系统疾病，用于评价手术前的病人状态，便于实行手术治疗。而发生瘫痪的病人，由于脊髓休克的存在，下肢肌电图不会有任何反应，无需行下肢肌电图检查（C对）。下肢肌电图常用于恢复期检查神经及下肢肌力恢复情况。","","N"],["2014-N120",48,"第一节 脊柱骨折","胸腰椎损伤",2014,120,"A","","男性，29岁。从3楼跌落，臀部着地，双下肢完全不能活动，双侧腹股沟平面感觉丧失，尿潴留。应采取的最佳治疗措施是",[["A","高压氧治疗"],["B","给与维生素B及激素等药物治疗"],["C","减压、内固定手术治疗"],["D","牵引外固定，平卧硬板床"]],"C","胸椎骨折合并脊髓损伤，说明骨折块压迫了脊髓，应尽早手术探查，进行减压、内固定手术治疗（C对），解除对脊髓的压迫，重建脊柱的稳定性。高压氧治疗、给与维生素B及激素等药物治疗、牵引外固定，平卧硬板床为一般性对症治疗，有利于患者康复，但保守治疗效果较手术差。","","N"],["2014-N145",10,"第四节 局部麻醉","普鲁卡因",2014,145,"B","","毒性反应最小的局麻药是",[["A","利多卡因"],["B","丁卡因"],["C","普鲁卡因"],["D","布比卡因"]],"C","普鲁卡因（C对）是目前毒性最小的局麻药，表现为中枢神经兴奋型，症状较轻。若有过敏反应则相当严重，如抢救不及时可立即死亡。丁卡因（B错）毒性大，因其扩散和表面穿透力强，常用于黏膜表面麻醉。若用量大，浓度高或局部有伤口，很易发生严重的心血管中毒反应，出现抽搐，甚至心跳突然停止。利多卡因（A错）轻度中毒表现为寒战和肢体抽动，神情淡漠或嗜睡等中枢抑制症状，严重者有抽搐。布比卡因（D错）是麻醉作用时间最长的局麻药，中毒表现为中枢神经兴奋型。本品易在心肌组织内蓄积，因此对心脏的毒性较强，且易引起室性心律失常。","","N"],["2014-N146",10,"第四节 局部麻醉","布比卡因",2014,146,"B","","适合于分娩镇痛的局麻药是",[["A","利多卡因"],["B","丁卡因"],["C","普鲁卡因"],["D","布比卡因"]],"D","局麻药注入体内后，一部分呈游离状态的起麻醉作用，另一部分与局麻组织的蛋白结合，或吸收入血与血浆蛋白结合，结合状态的药物将暂时失去药理活性。与利多卡因（A错），丁卡因（B错），普鲁卡因（C错）相比，布比卡因的血浆蛋白结合率最高，游离药的浓度最低，因此透过血胎屏障进入胎儿体内的药物浓度低，较适合于分娩镇痛（D对）。值得一提的是，罗哌卡因虽然蛋白结合率低于布比卡因，但是前者具有感觉和运动分离的作用，因此更适用于分娩镇痛。","","N"],["2014-N147",26,"第二节 胃癌及其他胃肿瘤","早期胃癌",2014,147,"B","","属于早期胃癌的是",[["A","癌组织侵入粘膜下层并有淋巴结转移"],["B","癌组织直径2cm侵入胃壁肌层"],["C","癌灶侵出浆膜并有淋巴结转移"],["D","皮革胃"]],"A","早期胃癌指病变仅限于黏膜或黏膜下层，不论病灶大小或有无淋巴结转移。癌组织侵入黏膜下层并有淋巴结转移（A对），对于胃癌来说仍旧可归类为早期胃癌。癌组织直径2cm，侵入胃壁肌层（B错），已突破黏膜下层，为进展期胃癌。癌灶侵出浆膜并有淋巴结转移（C错），也为进展期胃癌。皮革胃（D错）即全胃广泛弥漫性浸润癌组织，胃活动度差，胃壁僵硬如皮革，为晚期胃癌。","","N"],["2014-N148",26,"第二节 胃癌及其他胃肿瘤","进展期胃癌",2014,148,"B","","预后最差的是",[["A","癌组织侵入粘膜下层并有淋巴结转移"],["B","癌组织直径2cm侵入胃壁肌层"],["C","癌灶侵出浆膜并有淋巴结转移"],["D","皮革胃"]],"D","癌组织仅仅侵入黏膜下层，虽然有淋巴结转移，对于胃癌来说仍旧可归类为早期胃癌（A错）。癌组织直径2cm，侵入胃壁肌层，已突破黏膜下层，为进展期胃癌（B错）。癌灶侵出浆膜并有淋巴结转移（C错），也为进展期胃癌。皮革胃（D对）即癌组织弥漫性广泛性浸润胃组织，胃活动度差，胃壁僵硬如皮革，是恶性度极高的胃癌，病人预后极差，生存期一般不长。","","N"],["2014-N149",45,"第十节 桡骨远端骨折","桡骨远端骨折屈曲型骨折",2014,149,"B","","桡骨远端屈曲型骨折，骨折近端向背侧移位，远端向掌侧、桡侧移位，称为",[["A","Colles骨折"],["B","Smith骨折"],["C","Galeazzi骨折"],["D","Barton骨折"]],"B","Smith骨折常由跌倒时腕关节屈曲、手背着地受伤引起，X 线片可发现典型移位，近折端向背侧移位，远折端向掌侧、尺侧移位（B对）。伸直型骨折（Colles 骨折）多为腕关节处于背伸位、手掌着地、前臂旋前时受伤，X 线片可见骨折远端向桡、背侧移位，近端向掌侧移位，因此表现出典型的畸形体征，即侧面观呈“银叉”畸形，正面观呈“刺刀样”畸形（A错）。尺骨上 1/3 骨干骨折可合并桡骨小头脱位，称为孟氏（Monteggia）骨折。桡骨干下 1/3 骨折合并尺骨小头脱位，称为盖氏（Galeazzi）骨折（C错）。桡骨远端关节面骨折伴腕关节脱位（Barton 骨折）是桡骨远端骨折的一种特殊类型，X 线片可发现典型的移位。当跌倒时，腕关节屈曲、手背着地受伤，可发生与上述相反的桡骨远端掌侧关节面骨折及腕骨向掌侧移位（掌侧 Barton 骨折）（D错）。本题为考研真题，题干可能出现笔误。","","N"],["2014-N150",45,"第九节 前臂双骨折","前臂双骨折临床表现和诊断",2014,150,"B","","桡骨干下1/3骨折合并尺骨小头脱位，称为",[["A","Colles骨折"],["B","Smith骨折"],["C","Galeazzi骨折"],["D","Barton骨折"]],"C","Colles骨折（A错）为桡骨远端伸直型骨折，发生于桡骨远端骨松质，并向背侧移位的骨折。Smith骨折（B错）为桡骨远端屈曲型骨折，发生于桡骨远端骨松质，并向掌侧移位的骨折。Barton骨折（D错）为伴有腕关节半脱位的桡骨远端关节面骨折。Monteggia骨折为尺骨上1/3骨折合并桡骨头脱位。Galeazzi骨折（C对）为桡骨下1/3骨折合并尺骨小头（下尺桡关节）脱位。","","N"],["2014-N175",28,"第四节 慢性阑尾炎","慢性阑尾炎临床表现",2014,175,"X","","慢性阑尾炎钡灌肠X线表现有",[["A","阑尾充盈不全"],["B","阑尾排空延迟至3天以上"],["C","阑尾腔不规则"],["D","阑尾不充盈"]],"ABCD","大多数慢性阑尾炎由急性阑尾炎转变而来，主要体征是右下腹的局限性疼痛和压痛，这种压痛经常存在，位置也较固定；疼痛可不典型，也可急性发作。主要治疗即手术。钡灌肠X线表现可见阑尾不充盈（D对）或充盈不全（A对），阑尾排空延迟至3天以上（B对），阑尾腔不规则（C对）。","","N"],["2014-N176",4,"第四节 肠内营养","肠内营养方式和途径选择",2014,176,"X","","重症胰腺炎时肠内营养的最佳途径有",[["A","空肠造瘘输入"],["B","鼻空肠管输入"],["C","胃管滴入"],["D","口服"]],"AB","急性胰腺炎的非手术治疗原则是尽量减少胰液分泌，即胰腺休息疗法，防止感染，防止向重症发展，这是急性胰腺炎的基础治疗。故对于急性胰腺炎的肠内营养，要注意营养液不应该经过胃和十二指肠，刺激胰腺分泌；经口进食定会刺激胰腺分泌（D错），经胃管滴入的食物经过幽门和十二指肠都会刺激胰腺分泌（C错）。空肠造瘘输入（A对）、鼻空肠管输入（B对）都是将营养管直接引入空肠，可避免食物通过上消化道对胰腺的刺激。","","N"],["2014-N177",4,"第三节 肠外营养","脏器功能损害",2014,177,"X","","长期肠外营养发生胆汁淤积、肝功能损害的原因有",[["A","肠道缺乏食物刺激"],["B","体内谷氨酰胺大量消耗"],["C","葡萄糖超负荷"],["D","肠道细菌及内毒素移位"]],"ABCD","肠外营养时肝所处的环境及功能状态与正常进食时有明显的不同，营养物质进入肝的形式、比例，在门静脉与肝动脉血流中的比例，淋巴系统的分流，以及随营养物质进入肝的激素（胰岛素、CCK）浓度等，在肠外营养支持时均不可能达到正常进食时的状态：肠外营养改变了正常获取蛋白质、糖和脂肪等物质的途径，不再有食物进入消化道，缺乏食物刺激使胆汁不向肠腔排出，造成胆汁淤积，损害肝功能（A对）。食物中的谷氨酰胺是小肠上皮细胞的重要能量来源，现小肠不再有食物通过，无法吸收到谷氨酰胺，只能利用机体产生的谷氨酰胺，使其大量消耗；谷氨酰胺又是肝脏执行解毒功能重要的物质，缺乏导致肝功能损害（B对）。肠外营养中高浓度葡萄糖是补充能量消耗所必须的物质，但是高渗葡萄糖本身对机体具有毒害作用，可使肝细胞脂肪变性，并损害肝对葡萄糖的敏感性（C对）。长期无食物刺激的消化道黏膜坏死剥落，肠道内细菌易位入血后经门静脉入肝脏，造成肝脏的损害（D对）。故对于病人来说，如果可以采取肠内营养，就应避免使用肠外营养。","","N"],["2014-N178",5,"第六节 有芽胞厌氧菌感染","急诊清创",2014,178,"X","","下列疾病中，需要早期切开、清创引流的有",[["A","气性坏疽"],["B","寒性脓肿"],["C","蜂窝织炎"],["D","破伤风"]],"AD","气性坏疽是厌氧菌感染的一种，即梭状芽胞杆菌所致的肌坏死或肌炎，致病菌产生的外毒素可以引起严重毒血症及肌肉组织的广泛坏死，预防的关键是早期切开、清创引流（A对）。破伤风是由专性厌氧的破伤风梭菌引起的特异性感染性疾病，致病菌产生的外毒素可以使机体在肌紧张性收缩的基础上发生阵发性强烈痉挛，重者可发生呼吸暂停。由于破伤风梭菌是厌氧菌，其生长繁殖必须有缺氧的环境，因此，预防破伤风发生的最重要措施是创伤后早期彻底清创，改善局部循环（D对）。蜂窝织炎为非特异性感染，主要由溶血性链球菌、金葡菌等引起，治疗主要是注意休息，采用热敷、理疗，应用磺胺药或广谱抗生素；如上述处理仍不能控制其扩散者，应做广泛多处切开引流（C错）；需注意口底及颌下的急性蜂窝织炎可发生喉头水肿和压迫气管，引起呼吸困难，甚至窒息，应及早切开减压，以防止上述急症。寒性脓肿由结核杆菌感染引起，若采取切开引流方法治疗，会使切口经久不愈，故不能选择早期切开、清创引流治疗（B错）。","","N"],["2014-N179",55,"第一节 骨与关节结核概论","骨与关节结核临床表现",2014,179,"X","","骨关节结核的临床表现中，下列描述正确的有",[["A","浅表关节早期常有轻度肿胀、疼痛与压痛"],["B","深部关节或脊柱肿胀不明显"],["C","脓肿常局限病灶附近，一般无红、热"],["D","发病多隐潜、缓慢，常为多发病灶"]],"ABC","骨关节结核多为单发病灶（D错），少数为多发性，但对称性十分罕见。起病缓慢，有低热、乏力、盗汗等结核全身症状。肘、腕、膝、踝以及手足等处的病变，位置表浅肿胀容易发现，有轻度肿胀疼痛与压痛（A对）。脊柱以及髋关节等深部关节病灶，早期局部肿胀或脓肿不易发现（B对）。结核杆菌感染不会引起急性炎症反应，故不会出现红、热表现，脓肿较局限，但有穿破可能（C对）。","","N"],["2014-N180",56,"第一节 骨关节炎","骨关节炎病因",2014,180,"X","","引起继发性骨关节炎的常见原因有",[["A","后天性关节平面不平整"],["B","先天性关节结构异常"],["C","关节不稳定"],["D","体重超重者下肢关节过于承重劳损"]],"ABC","骨关节炎是一种以关节软骨退行性变和继发性骨质增生为特征的慢性关节病。分为原发性和继发性两类。继发性骨关节炎是由于创伤（如关节内骨折）、关节面后天性不平整（A对）（如缺血性骨坏死导致的关节面变性塌陷）、先天性关节结构异常（B对）（如发育性髋关节脱位）、关节不稳定（C对）（如关节囊韧带松弛）、关节畸形引起的关节面对合不良，在关节局部原有病变的基础上发生的骨关节炎。体重超重者下肢关节过于承重劳损（D错）为原发性骨关节炎的病因之一。","","N"],["2015-N77",23,"第四节 其他腹外疝","其他腹外疝切口疝",2015,77,"A","","下列腹部切口中，切口疝发生率最高的是",[["A","经腹直肌切口"],["B","旁正中切口"],["C","沿肋缘斜切口"],["D","麦氏切口"]],"A","切口疝最好发于经腹直肌切口，有一定的解剖因素：腹部肌肉分层比较特殊，主要包括腹内斜肌、腹外斜肌、腹横肌和腹直肌。腹内斜肌和腹外斜肌走行上相互交叉，还有腹横肌垫衬，故对于旁正中切口（B错）、沿肋缘斜切口（C错）以及麦氏切口（D错）来说，肌肉层丰富，张力的抵抗性强，故切口疝发生率不高。但是无论是腹内斜肌、腹外斜肌还是腹横肌，在腹部前区均融合成为筋膜，衬垫于腹直肌后，即腹直肌切口处只有腹直肌一块肌性结构；腹直肌的走行是自上而下的，其收缩形成的张力也是上下方向的，经腹直肌切口是顺着腹直肌走行切开的切口，腹直肌收缩无法给予该切口足够大的水平方向的收缩力来使得切口闭合，多依靠缝合产生的张力牵拉切口两端闭合，故切口疝最好发于经腹直肌切口（A对）。","","N"],["2015-N78",22,"第四节 静脉疾病","原发性下肢深静脉瓣膜功能不全诊断",2015,78,"A","","女性，60岁。右下肢内侧静脉迂曲10年，伴酸胀。查体：Pratt实验阳性，其临床意义",[["A","下肢深静脉血栓形成"],["B","隐-股静脉瓣膜功能不全"],["C","交通支瓣膜功能不全"],["D","原发性下肢深静脉瓣膜功能不全"]],"C","Pratt试验也称交通静脉瓣膜功能试验：病人仰卧，抬高患肢，在大腿根部扎止血带，然后从足趾向上至腘窝缠绕第一根弹力绷带，再自止血带向下，扎上第二根弹力绷带。嘱病人站立，一边向下解开第一根弹力绷带，一边向下缠绕第二根弹力绷带，如果在两根弹力绷带之间的间隙内出现曲张静脉，即提示该处存在交通支瓣膜功能不全（C对）。下肢深静脉血栓形成（A错）常在B超检查中发现，可有Perthes试验阳性。隐-股静脉瓣膜功能不全（B错）可有Trendelenburg试验阳性。原发性下肢深静脉瓣膜功能不全（D错）可在静脉造影及B超检查中发现有特征意义的瓣膜关闭不全。","","N"],["2015-N79",30,"第四节 原发性肝恶性肿瘤","肝细胞癌诊断与鉴别诊断",2015,79,"A","","为筛选原发性肝癌，首选的影像学检查是",[["A","选择性腹腔动脉造影"],["B","增强CT"],["C","MRI"],["D","B型超声"]],"D","筛选方法需要做到经济、方便且诊断敏感性较高。虽然增强CT（B错）和MRI（C错）均对于肝癌的诊断有较高的诊断效能，但是其花费较高，不适用于筛选人群的检查（BC错）。选择性腹腔动脉造影（A错）可以选择肝动脉的造影，由于肝癌血供异常丰富，故能够显示病变；但是其作为有创性检查，一般不作首选。B型超声（D对）是经济方便且诊断符合率较高的手段，可适用于人群的筛查，可显示肿瘤的部位、数目、大小、形态及肝静脉或门静脉内有无癌栓等，诊断符合率可达90%左右。","","N"],["2015-N80",26,"第二节 胃癌及其他胃肿瘤","早期胃癌",2015,80,"A","","确定早期胃癌最主要的指标是",[["A","侵犯深度"],["B","肿瘤直径"],["C","生长方式"],["D","是否淋巴转移"]],"A","胃癌的分期方法较为特殊，主要体现在对于早期胃癌的划分不参考淋巴结转移情况以及肿瘤的大小，而只看浸润深度。局限于黏膜或黏膜下层的胃癌即为早期胃癌，进犯肌层的癌为进展期胃癌，即侵犯深度（A对）作为评判是否为早期胃癌的主要指标。对于大多数肿瘤而言，判断早期的最主要指标是是否有转移。","","N"],["2015-N81",28,"第二节 急性阑尾炎","右下腹压痛",2015,81,"A","","诊断急性阑尾炎最有意义的体征是",[["A","右下腹固定压痛"],["B","腰大肌试验阳性"],["C","结肠充气试验阳性"],["D","闭孔肌试验阳性"]],"A","右下腹固定压痛是诊断急性阑尾炎最有意义的体征（A对）。腰大肌试验阳性（B错）是提示炎症阑尾可能位于腰大肌前方，盲肠后位或腹膜后位。结肠充气试验阳性（C错）为急性阑尾炎辅助诊断体征，且阴性不能排除诊断。闭孔内肌试验阳性（D错）提示阑尾炎位置靠近腹腔内较低位置的闭孔内肌。这三个体征，属于辅助诊断的其他体征，更多情况下是用于对不典型位置阑尾炎的判断，并非诊断急性阑尾炎最有意义的体征。","","N"],["2015-N82",8,"第二节 常见体表肿瘤与囊肿","皮脂腺囊肿",2015,82,"A","","男性，46岁。左耳后有圆形肿物3年，直径1cm，肿物表面可见一小黑点，基底活动，无压痛，曾有红肿史。应诊断的疾病是",[["A","血管瘤"],["B","皮脂腺囊肿"],["C","皮样囊肿"],["D","淋巴结炎"]],"B","皮脂腺囊肿（B对）因皮脂腺导管阻塞导管从而引起皮脂腺排泄障碍、淤积而成，阻塞物多为灰尘堵塞及细菌感染所致，一般无自觉症状，表现为高出皮面的肿物，表面光滑，无压痛，挤压可见豆腐渣样内容物，若并发感染可出现红肿热痛表现，与病人的主诉“曾有红肿史”相符。血管瘤（A错）主要发生于压力较大的动脉，体表动脉瘤最典型的表现为搏动性肿块和杂音，对于体表的血管瘤，其外观为红色斑点，与病人表现不符。皮样囊肿（C错）为囊性畸胎瘤，浅表者好发于眉梢或颅骨骨缝处，可与颅内交通呈哑铃状。手术摘除前应有充分估计和准备，其表面皮肤可活动，但基底常粘连固定，质较软，有波动或面团样感，一般不发生感染，不会有红肿史。淋巴结炎（D错）多为急性发作，以红、肿、热、痛为主要临床表现，无间歇性表现，起病即以红肿热痛为主，严重者可出现波动感和破溃。","","N"],["2015-N83",18,"第四节 乳腺癌","临床表现",2015,83,"A","","乳腺癌最常发生的部位是",[["A","外下象限"],["B","内下象限"],["C","内上象限"],["D","外上象限"]],"D","外上象限（D对）是乳腺癌最常发生的部位，这与外上象限腺体密集有关。","","N"],["2015-N84",33,"第四节 胰腺癌和壶腹周围癌","腹痛",2015,84,"A","","胰头癌常见首发表现",[["A","脂肪泻"],["B","黄疸"],["C","贫血"],["D","上腹部隐痛"]],"D","上腹不适常为首发症状，早期因肿块压迫胰管，使胰管不同程度梗阻、扩张、扭曲及压力增高，出现上腹部不适，或上腹部隐痛（D对）、钝痛、胀痛。脂肪泻（A错）多见于慢性胰腺炎或者胰腺癌晚期，不是首发症状。因为胰腺功能衰竭，胰酶分泌较少，导致包括脂肪在内的营养物质消化障碍，肠道渗透压增高，出现脂肪泻。黄疸为胰头癌最主要的症状，多数由胰头癌压迫或直接浸润胆总管引起，呈进行性加重。黄疸（B错）需待胆道严重梗阻时才会出现，多数病人出现黄疸时已属中晚期。消瘦、贫血等为恶病质表现，早期胰头癌对全身影响较小，不能引起恶病质，因而早期大多不出现贫血（C错）。","","N"],["2015-N85",23,"第二节 腹股沟疝","腹股沟疝诊断",2015,85,"A","","男性，23岁。右腹股沟可复性包块2年。查体：肿块还纳后，压迫内环口不复出，无压痛。手术中最有可能的发现是",[["A","直疝三角部位腹壁薄"],["B","疝囊颈位于腹壁下动脉外侧"],["C","盲肠组成疝囊壁的一部分"],["D","疝内容物常为大网膜"]],"B","年轻男性患者，右侧腹股沟可复性包块2年。肿块还纳后，压迫内环口后肿块不复出，诊断考虑右侧腹股沟斜疝。因腹股沟斜疝自腹股沟管内环处突出，压迫内环即封闭了斜疝的突出路径，使疝块不能突出。而腹股沟直疝经直疝三角直接突出至体表形成包块，压迫内环口后肿块仍可突出。该病人为腹股沟斜疝，直疝三角部位不会出现腹壁薄弱的表现（A错）。在腹股沟斜疝，疝囊颈位于腹壁下动脉的外侧（B对）。该病人肿块可还纳，说明为易复性疝；盲肠组成疝囊壁的一部分（C错）是滑疝，属于难复性疝。易复性腹股沟斜疝疝内容物以小肠居多，难复性疝以大网膜（D错）居多。","","N"],["2015-N86",29,"第七节 直肠癌","直肠指诊触及肿物",2015,86,"A","","男性，64岁。排便习惯改变、便血2个月，首选的检查是",[["A","直肠指诊"],["B","直肠镜"],["C","纤维肠镜"],["D","钡灌肠"]],"A","老年男性患者，排便习惯改变、便血2个月，须考虑直肠癌可能。直肠指诊（A对）是首选的检查，国人直肠癌约70%为低位直肠癌，能在直肠指诊时触及。直肠镜（B错）、纤维结肠镜（C错）为直肠癌的确诊方法，可同时取样活检。钡灌肠（D错）对直肠癌诊断意义不大。","","N"],["2015-N87",33,"第四节 胰腺癌和壶腹周围癌","黄疸",2015,87,"A","","男性，60岁，黄疸、尿色变深、皮肤瘙痒2周。查体：T36．5℃，皮肤巩膜黄染。右上腹无痛性圆形肿块，随呼吸上下运动，肿块最可能为",[["A","肝脏下缘"],["B","胆囊"],["C","胰头部肿瘤"],["D","胆总管囊肿"]],"B","黄疸、尿色变深以及皮肤瘙痒均提示病人存在胆色素排泄障碍。肝脏下缘触感正常情况下为较锐软组织，即使肝硬化病人，肝脏下缘（A错）触感也仅为变硬和不再锐利，不会以圆形肿块的形式出现。胰头部肿瘤（C错）极难从体表被触及，且较固定，不会随着呼吸上下运动。胆总管囊肿（D错）一般指先天性胆管扩张症，儿童期发病多见，虽然80%以上病人右上腹可扪及表面光滑的囊性肿块，但其典型临床表现为腹痛、腹部肿块、黄疸三联征和反复发作的胆管炎，合并感染时肿块有触痛。胆道梗阻使得胆汁难以排出，除了使得血胆色素浓度上升外，多余无法排除的胆汁会积聚在胆囊中，造成胆囊膨大；胆囊位于肝脏下方，离体表较近，平时被肝叶覆盖，不易触及；当胆囊因梗阻积液肿大时，即可扪及。老年男性患者，出现黄疸及右上腹无痛性肿块，且随呼吸上下运动，考虑胰头部肿瘤引起的Courvoisier征，即无痛性胆囊（B对）增大。因为胆总管下段被胰头部包绕，胰头部肿瘤可直接浸润或压迫胆管导致胆总管梗阻，导致上段胆管扩张以及胆囊无痛性肿大。","","N"],["2015-N88",50,"第三节 下肢神经损伤","腓总神经损伤",2015,88,"A","","不属于腓总神经损伤的临床表现",[["A","足不能背屈、外翻、伸趾"],["B","马蹄内翻足"],["C","小腿前内侧区感觉障碍"],["D","行走困难，呈“跨阈步态”"]],"C","腓总神经主要支配小腿前外侧伸肌群及小腿前外侧和足背皮肤，其损伤常导致足不能背屈、外翻、伸趾（A对）及马蹄内翻足（B对）（外侧伸肌群瘫痪，无法形成对抗内侧伸肌群的收缩力），并出现小腿前外侧区感觉障碍。小腿前内侧区感觉障碍（C错，为本题正确答案）见于股神经损伤。行走困难，呈“跨阈步态”（D对）亦见于腓总神经损伤，表现为足和足趾不能够背屈，走路高举足，足尖先落地。本题考查的是胫神经和腓总神经损伤的表现区别，此题可以通过解剖位置情况轻松解题：胫骨位于内侧，腓骨位于外侧，内胫外腓，胫神经与腓总神经的行经以及感觉支配也与此相对应，故腓总神经不会支配小腿前内侧区的感觉。","","N"],["2015-N89",54,"第一节 化脓性骨髓炎","慢性血源性骨髓炎治疗",2015,89,"A","","慢性骨髓炎的治疗，不适当的处理是",[["A","清除病灶、消灭死腔、伤口闭合"],["B","可将不重要部位的病骨整段切除"],["C","病程久不愈，可考虑施行截肢术"],["D","急性发作时，抗生素治疗、清除病灶"]],"D","慢性骨髓炎的治疗，主要为手术治疗，行病灶清除术，原则是清除病灶、消灭死腔、伤口闭合（A对）。腓骨、肋骨、髂骨翼等不重要部位的慢性骨髓炎，可将病骨整段切除，一期缝合伤口（B对）。部分病例病程久、已有窦道口皮肤癌变或足部广泛骨髓炎骨质损毁严重不可能彻底清除病灶者，可施行截肢术（C对）。慢性骨髓炎急性发作期不宜作病灶清除术，应以抗生素治疗为主（D错，为本题正确答案），积脓时可切开引流。","","N"],["2015-N90",49,"第一节 骨盆骨折","腹膜后血肿",2015,90,"A","","骨盆骨折早期最危险的并发症是",[["A","膀胱、尿道破裂"],["B","坐骨神经损伤"],["C","直肠损伤"],["D","出血性休克"]],"D","骨盆由扁骨组成，内有造血能力旺盛的红骨髓，血运丰富，且骨盆骨折常容易合并髂内、髂外动静脉及其分支的断裂，容易引起大出血，导致出血性休克，若未能在短期内纠正，早期即可造成病人死亡。因此，一般认为骨盆骨折最危险的并发症出血性休克（D对）。膀胱、尿道破裂（A错），坐骨神经损伤（B错），直肠损伤（C错）也属于早期并发症，会造成不良后果，但是不会在短时间内造成病人的死亡。","","N"],["2015-N111",32,"第五节 胆道感染","急性梗阻性化脓性胆管炎诊断",2015,111,"A","","女性，43岁。肝外胆管结石症史3年，10小时前突然右上腹绞痛，恶心、呕吐，继而出现，寒战、高热、神志淡漠、嗜睡，查体：T40℃，P120次/分，BP85/60mmHg，上腹轻压痛。最可能诊断是",[["A","肝脓肿"],["B","急性梗阻化脓性胆管炎"],["C","急性胰腺炎"],["D","急性胆囊炎"]],"B","43岁女性（胆道系统结石的好发人群），肝外胆管结石病史3年（常见基础疾病，结石可堵塞胆道，引起胆血反流）。突然右上腹绞痛，恶心、呕吐，继而出现，寒战、高热、神志淡漠、嗜睡，脉快，休克（Reynolds五联征表现），诊断考虑急性梗阻化脓性胆管炎（B对）。肝脓肿（十版外科学P444）（A错）虽然有寒战高热等感染中毒症状表现，但是疼痛主要表现为肝区钝痛和压痛，而非绞痛。急性胰腺炎（十版外科学P487）（C错）亦可能由胆道结石所诱发，但表现主要为左上腹剧烈疼痛，伴恶心呕吐，且呕吐后腹痛无缓解。急性胆囊炎（十版外科学P472）（D错）主要表现为右上腹绞痛，轻中度发热，查体可有Murphy征阳性，通常无寒战，一般亦不出现休克。","c87","N"],["2015-N112",32,"第五节 胆道感染","急性梗阻性化脓性胆管炎影像学检查",2015,112,"A","","女性，43岁。肝外胆管结石症史3年，10小时前突然右上腹绞痛，恶心、呕吐，继而出现，寒战、高热、神志淡漠、嗜睡，查体：T40℃，P120次/分，BP85/60mmHg，上腹轻压痛。首选的腹部检查方法是",[["A","B超"],["B","增强CT"],["C","MRI"],["D","X线平片"]],"A","B超（A对）操作简单且可迅速得到结果，加之超声可在床边进行，能及时了解胆道梗阻部位、肝内外胆管扩张情况及病变性质，对诊断很有帮助。增强CT（B错）以及MRI（C错）虽然分辨率较B超高，但是其价格昂贵且操作不便，且患者此时已出现休克，不宜进行反复搬运，不作为首选检查。X线平片（D错）对无法显示胆道梗阻，仅能显示部分X线阳性的混合性结石，亦不首选。","c87","N"],["2015-N113",32,"第五节 胆道感染","急性梗阻性化脓性胆管炎治疗",2015,113,"A","","女性，43岁。肝外胆管结石症史3年，10小时前突然右上腹绞痛，恶心、呕吐，继而出现，寒战、高热、神志淡漠、嗜睡，查体：T40℃，P120次/分，BP85/60mmHg，上腹轻压痛。最佳的处理措施是",[["A","静脉大量补液"],["B","静脉应用升压药"],["C","联合抗生素保守治疗"],["D","紧急手术"]],"D","重症胆管炎所致严重的临床表现多与胆管系统内高压和细菌通过毛细胆管的肝细胞屏障直接进入肝血流中有关。重症急性胆管炎的发展有时异常迅猛，因此应早期采取积极的措施。若不及时解除胆道梗阻，则不可能阻止胆汁或细菌向血液的反流，无法阻止病情的恶化。原则是紧急手术（D对），切开胆总管减压，去除结石梗阻，通畅引流胆道，才有可能中止胆汁或细菌向血液的反流，阻断病情的恶化。常用的术式包括：胆总管切开减压、T管引流；ENBD；PTCD。静脉大量补液（A错）、静脉应用升压药（B错）、联合抗生素保守治疗（C错）均为一般性对症支持治疗，不能解除梗阻，阻止胆血反流，因而无法阻断疾病的进展。","c87","N"],["2015-N114",33,"第二节 胰腺炎","急性胰腺炎诊断",2015,114,"A","","男性，32岁。饮酒后中上腹持续性疼痛6小时，并逐渐加剧，向肩、背部放射，伴恶心、呕吐。查体：P118次/分，BP90/75mmHg，急性面容，表情痛苦，全腹压痛，尤以中上腹为著，轻度肌紧张和反跳痛，肝区未触及肿块。外周血WBC15×10⁹/L，中性粒细胞81%。最可能的诊断是",[["A","急性胰腺炎"],["B","急性绞窄性肠梗阻"],["C","溃疡病穿孔"],["D","急性肠扭转"]],"A","32岁男性，饮酒后（急性胰腺炎常见诱因）中上腹持续性疼痛6小时，逐渐加剧，向肩、背部放射，伴恶心、呕吐（急性胰腺炎的典型临床表现）。查体：P118 次/分，BP90/75mmHg（提示可能存在低血容量性休克），全腹压痛，尤以中上腹为著，轻度肌紧张和反跳痛（提示存在轻度腹膜刺激征）。外周血 WBC15×10⁹/L，中性粒细胞81%（正常约50%～70%），考虑合并感染。综合该患者的病史、体查、实验室检查，诊断考虑急性胰腺炎（A对）。溃疡病穿孔（十版外科学P380）（C错）可表现为中上腹剧烈疼痛伴放射痛，但是由于消化液的漏出，多会出现严重的腹膜刺激征，且患者多有长期消化性溃疡病病史，题干中未提及。急性绞窄性肠梗阻（十版外科学P392）（B错）和急性肠扭转（十版外科学P396）（D错）表现相似，都存在持续性绞痛及恶心、呕吐、腹胀等症状，但其疼痛位置多位于脐周或肠道相应部位，且发病与饮酒无明确相关性。","c88","N"],["2015-N115",33,"第二节 胰腺炎","CT扫描",2015,115,"A","","男性，32岁。饮酒后中上腹持续性疼痛6小时，并逐渐加剧，向肩、背部放射，伴恶心、呕吐。查体：P118次/分，BP90/75mmHg，急性面容，表情痛苦，全腹压痛，尤以中上腹为著，轻度肌紧张和反跳痛，肝区未触及肿块。外周血WBC15×10⁹/L，中性粒细胞81%。明确诊断后，对决定治疗最有价值的诊断检查是",[["A","腹部B超"],["B","腹部增强CT"],["C","血钙测定"],["D","血、尿淀粉酶测定"]],"B","腹部增强CT（B对）是最具诊断价值的影像学检查。不仅能确诊胰腺炎，而且能鉴别是否合并胰腺组织坏死以及坏死程度及范围，可用于辅助诊断轻型及重症胰腺炎。在胰腺弥漫性肿大的背景上若出现质地不均、液化和蜂窝状低密度区，即可诊断为胰腺坏死。对其并发病胰腺脓肿和假性囊肿等也有诊断价值。腹部B超（A错）简便易行，但由于上腹部胃肠气的干扰，可影响准确性。血钙测定（C错）可提示是否为重症胰腺炎，一般认为血钙降低（＜1.87mmol/L）支持重症胰腺炎诊断，但特异性相对增强CT差。血、尿淀粉酶测定（D错）为诊断胰腺炎最常用的方法，淀粉酶值越高，诊断的正确率越高，但升高的幅度与病变严重程度并非正比，因而不能很好判断是否为重症胰腺炎。","c88","N"],["2015-N116",17,"第二节 甲状旁腺功能亢进的外科治疗","原发性甲状旁腺功能亢进实验室检查",2015,116,"A","","女性，37岁。因左叶甲状腺乳头状癌行甲状腺左叶全切、峡部及右叶大部切除术。术后第一天发生呼吸急促，口周麻木，手足持续性痉挛。为明确诊断，首选检查是",[["A","血T₃、T₄"],["B","颈部B超"],["C","颈部穿刺"],["D","血清钙、磷浓度"]],"D","中年女性患者甲状腺大部切除术后发生呼吸困难，口周麻木，手足持续性痉挛，考虑手术损伤甲状旁腺，导致PTH分泌减少，血钙降低。为明确诊断，首选血清钙、磷浓度（D对）测定。血T₃、T₄（A错）测定主要用于诊断甲状腺功能亢进症。颈部B超（B错）、颈部穿刺（C错）主要用于术前甲状腺肿块的诊断及病理性诊断的鉴别。","c89","N"],["2015-N117",17,"第一节 甲状腺疾病","甲状旁腺功能减退",2015,117,"A","","女性，37岁。因左叶甲状腺乳头状癌行甲状腺左叶全切、峡部及右叶大部切除术。术后第一天发生呼吸急促，口周麻木，手足持续性痉挛。首选处理措施",[["A","拆除颈部伤口缝线"],["B","气管切开"],["C","静脉注射钙剂"],["D","检查引流管"]],"C","甲状旁腺位于甲状腺两叶的后侧，甲状腺切除术可能损伤甲状旁腺。损伤后，PTH分泌不足，PTH是调节钙代谢最重要的因素，有升血钙降血磷的作用，故甲状旁腺损伤者血钙下降，表现为面部、口周或肢端发麻，严重者有手足抽搐。病人呼吸急促是由于血钙过低，呼吸肌痉挛引起，而非喉头处出血压迫，需结合全身症状判断病人病情。血钙过低严重影响病人的呼吸情况，需迅速升高血钙缓解痉挛表现，故给予静脉注射钙剂（C对）。拆除颈部伤口缝线（A错）、气管切开（B错）、检查引流管（D错）为甲状腺手术术后出血引起术后呼吸困难和窒息的处理措施。","c89","N"],["2015-N118",53,"","",2015,118,"A","","男性，60岁。左手麻木半年，双下肢乏力，行走不稳3个月。查体：左上肢桡骨膜反射减弱，左手拇指针刺觉减退，双下肢腱反射亢进，双侧Babinski征（+）。初步诊断为颈椎病。颈椎病变的平面最可能位于",[["A","颈₄-₅"],["B","颈₅-₆"],["C","颈₆-₇"],["D","颈₇-胸₁"]],"B","患者双下肢腱反射亢进，双侧Babinski征（+），诊断考虑脊髓型颈椎病。颈₄～₅（C₅）受累表现为一侧颈部及肩部放射痛，三角肌处麻木，无反射改变。颈₅～₆（C₆）受累表现为拇指放射痛，桡骨膜反射和肱二头肌反射减弱。颈₆～₇（C₇）受累表现为中指放射痛，肱三头肌反射减弱。颈₇～胸₁（C₈）受累表现为环指和小指放射痛，无反射改变。病人左上肢桡骨膜反射减弱，左手拇指针刺觉减退，因此颈椎病病变应该定位于颈₅～₆（B对）。","c90","N"],["2015-N119",53,"第一节 颈椎退行性疾病","MRI检查",2015,119,"A","","男性，60岁。左手麻木半年，双下肢乏力，行走不稳3个月。查体：左上肢桡骨膜反射减弱，左手拇指针刺觉减退，双下肢腱反射亢进，双侧Babinski征（+）。初步诊断为颈椎病。对诊断最有意义的影像学检查是",[["A","X线"],["B","CT"],["C","增强CT"],["D","MRI"]],"D","MRI（D对）不仅可以显示颈椎的解剖学形态，T₁和T₂加权像还可以显示椎间盘形态和脊髓受压的情况，以及脊髓变性、水肿、萎缩等病理形态，是颈椎间盘突出症最有意义的影像学检查。椎间盘突出症病人X线片（A错）为常规检查，可观察脊椎序列、椎间隙变化，但无法观察脊髓受压情况。CT（B错）及增强CT（C错）可以显示椎间盘突出的类型、骨赘形成与否、韧带的病变及椎管形态的改变，亦可观察脊髓受压情况，效果较MRI差。","c90","N"],["2015-N120",53,"第一节 颈椎退行性疾病","颈椎病治疗",2015,120,"A","","男性，60岁。左手麻木半年，双下肢乏力，行走不稳3个月。查体：左上肢桡骨膜反射减弱，左手拇指针刺觉减退，双下肢腱反射亢进，双侧Babinski征（+）。初步诊断为颈椎病。患者最终确诊颈椎单一节段椎间盘突出，相应平面颈椎管狭窄，颈脊髓变性，不宜采取的治疗是",[["A","颈椎前路手术"],["B","颈椎后路手术"],["C","颈椎前后路联合手术"],["D","按摩治疗"]],"D","由于患者左手麻木半年，双下肢乏力，行走不稳3个月，双侧Babinski征（＋），诊断为脊髓型颈椎病。脊髓型颈椎病应立即手术治疗（ABC对），按摩治疗不但不能解决问题，甚至可能加重脊髓损伤，导致瘫痪（D错，为本题正确答案）。","c90","N"],["2015-N145",7,"第一节 热力烧伤","Ⅰ度烧伤",2015,145,"B","","未损伤生发层的皮肤烧伤是",[["A","Ⅰ度烧伤"],["B","浅Ⅱ度烧伤"],["C","深Ⅱ度烧伤"],["D","Ⅲ度烧伤"]],"A","皮肤分为表皮层，真皮层和皮下组织。表皮层（3版八年制组织学与胚胎学P166）位于皮肤浅层，由外到内依次是角质层、透明层、颗粒层、棘层、基底层（生发层）。真皮层（3版八年制组织学与胚胎学P170）位于表皮下，由外到内分为乳头层和网织层。皮下组织（3版八年制组织学与胚胎学P171）位于真皮下方，由疏松结缔组织和脂肪组织组成。Ⅰ°烧伤：仅伤及表皮浅层，生发层健在（A对）；浅Ⅱ°烧伤：伤及表皮的生发层和真皮乳头层（B错）；深Ⅱ°烧伤：伤及真皮乳头层以下，但仍残留部分网状层（C错）；Ⅲ°烧伤：又称焦痂型烧伤，全层皮肤烧伤，可深达肌肉甚至骨骼、内脏器官等（D错）。","","N"],["2015-N146",7,"第一节 热力烧伤","深Ⅱ度烧伤",2015,146,"B","","去除水疱后创面湿润，但感觉迟钝的皮肤烧伤是",[["A","Ⅰ度烧伤"],["B","浅Ⅱ度烧伤"],["C","深Ⅱ度烧伤"],["D","Ⅲ度烧伤"]],"C","Ⅰ°烧伤表面红斑状、干燥和灼烧感（A错）。浅Ⅱ°烧伤局部红肿明显，有大小不一的水疱形成，水疱皮如剥脱，创面红润、潮湿、疼痛明显（B错）。深Ⅱ°烧伤也可有水疱，但去水疱皮后，创面微湿，红白相间，痛觉较迟钝（C对）。Ⅲ°烧伤无水疱，创面蜡白或焦黄、甚至炭化。硬如皮革、干燥、无渗液、发凉、针刺和拔毛无痛觉（D错）。","","N"],["2015-N147",38,"第五节 尿道损伤","前尿道损伤的病史和查体",2015,147,"B","","会阴部骑跨伤后出现排尿困难，尿道滴血的泌尿系损伤的常见部位是",[["A","后尿道"],["B","尿道球部"],["C","腹膜内膀胱"],["D","腹膜外膀胱"]],"B","后尿道位于骨盆内部，骑跨伤通常不会损伤到此处（A错），后尿道损伤常由骨盆骨折时的强大剪切力造成。会阴部骑跨伤时，外来暴力将尿道挤向耻骨联合下方，引起尿道球部（B对）损伤，导致排尿困难及尿道滴血。膀胱通常情况下位于骨盆深处，受到周围筋膜、肌肉、骨盆及其他软组织的保护，一般不易发生膀胱损伤。腹膜内膀胱损伤，以尿液引起急性腹膜炎及疼痛为主要表现（C错）。腹膜外膀胱损伤以尿外渗及血肿积聚下腹部引起的疼痛、压痛及肌紧张为主要表现（D错）。","","N"],["2015-N148",38,"第五节 尿道损伤","后尿道外伤概述",2015,148,"B","","骨盆多处骨折后出现排尿困难的泌尿系损伤的常见部位是",[["A","后尿道"],["B","尿道球部"],["C","腹膜内膀胱"],["D","腹膜外膀胱"]],"A","膜部尿道穿过尿生殖膈，当骨盆骨折时，附着于耻骨下支的尿生殖膈突然移位，产生剪切样暴力，使薄弱的膜部尿道撕裂，甚至在前列腺尖处撕断，属于后尿道（A对）损伤。尿道球部损伤（B错）常发生于会阴部骑跨伤，外来暴力将尿道挤向耻骨联合下方，引起尿道球部损伤。膀胱通常情况下位于骨盆深处，受到周围筋膜、肌肉、骨盆及其他软组织的保护，一般不易发生膀胱损伤。腹膜内膀胱损伤，以尿液引起急性腹膜炎及疼痛为主要表现（C错）。腹膜外膀胱损伤以尿外渗及血肿积聚下腹部引起的疼痛、压痛及肌紧张为主要表现（D错）。","","N"],["2015-N149",55,"第二节 脊柱结核","X线平片",2015,149,"B","","X线表现为骨破坏和椎间隙狭窄，常见于",[["A","脊柱结核"],["B","脊柱恶性肿瘤"],["C","强直性脊柱炎"],["D","退行性脊柱骨关节病"]],"A","脊柱结核（A对）的典型X线表现为骨破坏和椎间隙狭窄。其中，中心型椎体结核的骨质破坏集中在椎体中央，很快出现椎体压缩成楔状，前窄后宽。边缘型的骨质破坏集中在椎体的上下缘或下缘，表现为进行性椎间隙狭窄，并累及邻近两个椎体。脊柱恶性肿瘤（十版外科学P745）（B错）的X线可见骨破坏累及椎弓根，椎间隙高度正常，一般无椎旁软组织影。强直性脊柱炎（十版外科学P753）（C错）的X线早期表现为骶髂关节骨质疏松，关节边缘呈虫蛀状改变，间隙不规则增宽，软骨下骨有硬化致密改变；以后关节面渐趋模糊，间隙逐渐变窄，直至双侧骶髂关节完全融合。椎间小关节出现类似变化，随病变发展椎间盘的纤维环和脊柱前、后纵韧带发生骨化，形成典型的“竹节样”脊柱。退行性脊柱关节病（D错）X线平片可见椎间隙变窄，脊柱边缘增生和骨赘形成。","","N"],["2015-N150",56,"第二节 强直性脊柱炎","强直性脊柱炎影像学检查",2015,150,"B","","X线表现为“竹节样”改变，常见于",[["A","脊柱结核"],["B","脊柱恶性肿瘤"],["C","强直性脊柱炎"],["D","退行性脊柱骨关节病"]],"C","脊柱疾病的鉴别属于常考内容，考生须牢牢掌握。强直性脊柱炎（C对）是与HLA-B27基因密切相关的慢性炎症性疾病，属于结缔组织病。早期骶髂关节骨质疏松，关节边缘呈虫蛀状改变，间隙不规则增宽，软骨下骨有硬化致密改变；以后关节面渐趋模糊，间隙逐渐变窄，直至双侧骶髂关节完全融合。椎间小关节出现类似变化，随病变发展椎间盘的纤维环和脊柱前、后纵韧带发生骨化，形成典型的“竹节样”脊柱（C对）。X线表现上，脊柱结核（十版外科学P743）（A错）的X线表现以骨质破坏和椎间隙狭窄为主，并可有椎旁软组织影增宽。脊柱恶性肿瘤（十版外科学P745）（B错）的X线表现为骨破坏首先累及椎弓根，椎间隙高度正常，一般无椎旁软组织影。退行性脊柱骨关节病（十版外科学P718）（D错）的X线表现为椎间隙变窄，邻近的上下关节突增生，但无骨质破坏及周围软组织影。","","N"],["2015-N175",19,"第二节 肋骨骨折","肋骨骨折治疗",2015,175,"X","","女性，28岁。车祸伤及右胸1小时。查体：P96次/分，R24次/分，BP140/95mmHg。右前胸未见反常呼吸运动，局部肿胀、压痛明显，右肺呼吸音降低，X线胸片示右侧8、9肋骨后端骨折，正确的处理有",[["A","腹部B超"],["B","镇静止痛"],["C","牵引固定"],["D","胸带固定"]],"ABD","病人基本生命体征尚平稳，主要症状集中在右胸的车祸伤。未见反常呼吸运动，即病人肋骨骨折未形成连枷胸，骨折量较少，病人尚无需使用呼吸机以及手术固定肋骨治疗；胸片示右侧第8、9肋骨后端骨折，该位置靠近腹腔上方，有腹内脏器和膈肌损伤的可能，故给予腹部B超属必要（A对）。骨折以及软组织损伤导致呼吸时疼痛，病人无法正常自主呼吸，故需要给予镇静止痛治疗（B对）。牵引固定（C错）多适用于四肢及脊柱的骨折治疗，如有多根肋骨骨折引起反常呼吸时，先用加垫包扎或肋骨牵引限制部分胸廓浮动，再行肋骨固定。胸带固定（D对）是常用的固定胸廓的方法，能减少肋骨断端活动、缓解疼痛，有助于病人保持自主呼吸的同时维持骨折处的稳定。","","N"],["2015-N176",4,"第三节 肠外营养","肠外营养适应证",2015,176,"X","","全胃肠外营养的适应证有",[["A","短肠综合征"],["B","结肠外瘘"],["C","重症胰腺炎"],["D","甲亢术后饮水呛咳"]],"AC","短肠综合征是大段的小肠切除后，残存的有功能的肠管不能维持机体营养需要的吸收不良综合征，由于是吸收功能本身的缺乏，任何肠内营养都无法获得有效的吸收和利用，故只有用肠外营养维持病人营养（A对）。结肠外瘘病人的小肠功能不受影响，而营养吸收的主要部位位于小肠，故病人仍旧采取肠内营养，更加符合生理情况，对于外瘘症状，可以给予体外引流解决（B错）。重症胰腺炎的病人小肠虽然吸收功能正常，但是主要的消化酶均由胰腺分泌，重症胰腺炎病人由于消化酶缺乏，无法有效吸收营养；此外，若是向肠道内输送营养液，也会刺激胰腺分泌，这样会加重胰腺的负担，不利于疾病恢复，故应采用全胃肠外营养（C对）。甲亢术后饮水呛咳是由于喉上神经的损伤引起（十版外科学P236），此时可以改变进食的方式，采用胃管或者空肠置管的方式将营养物质输送入消化道，避免了对咽喉部的刺激（D错）。","","N"],["2015-N177",18,"第四节 乳腺癌","乳腺癌病因和流行病学特点",2015,177,"X","","女性乳腺癌的危险因素中，有循证医学证据的包括",[["A","初产年龄大于35岁"],["B","月经初潮早"],["C","肥胖"],["D","单纯乳腺增生"]],"ABC","乳腺是多种内分泌激素的靶器官，如雌激素、孕激素及泌乳素等，无论是月经初潮年龄早（B对）、绝经晚、不孕或者高龄初产（A对），都是体内雌孕激素未发生适时的变化所致。脂肪细胞具有保护雌激素的功能，肥胖（C对）病人体内雌激素清除较慢，可加强或延长雌激素对乳房上皮细胞的刺激，长期可引起过度刺激。过去认为单纯乳腺增生（D错），又称乳腺囊性增生病，无癌变潜能；现课本中认为该观点尚有争论，但无循证医学证据，若碰到题目，尚可认为乳腺囊性增生病不会发生恶变。","","N"],["2015-N178",32,"第一节 胆道系统解剖生理概要","胆囊管",2015,178,"X","","下列属于Calot三角边线的是",[["A","肝脏下缘"],["B","胆总管"],["C","肝总管"],["D","胆囊管"]],"ACD","Calot三角由胆囊管（D对）、肝总管（C对）、肝下缘（A对）共同构成。其中有胆囊动脉、肝右动脉、副右肝管常在此区穿过，胆道手术时需注意保护或者必要时结扎。","","N"],["2015-N179",48,"第一节 脊柱骨折","脊柱骨折体征",2015,179,"X","","胸腰椎骨折的临床表现",[["A","畸形、后凸、生理弧度消失"],["B","功能障碍"],["C","异常活动与骨擦音"],["D","疼痛及肿胀"]],"ABD","骨折病人存在许多表现，一般表现有局部疼痛、肿胀和功能障碍，特征性表现有畸形、异常活动、骨擦音和骨擦感。但需要意识到，不同部位的骨折存在不同的表现，可以说存在任何一项特异性表现就可以判断发生了骨折，但是不能说缺乏某个特异性表现就不是骨折。从选项上来看，畸形、后凸、生理弧度消失（A对）是由于胸腰椎骨折后，受力不平衡引起的畸形，以及疼痛和防御性体位共同导致的后凸及生理弯曲消失；功能障碍（B对）即胸腰椎骨折后引起的脊柱支持功能的障碍，病人无法正常活动；疼痛及肿胀（D对）是其一般表现。异常活动及骨擦音为骨折的专有体征，但部分骨折如裂缝骨折、嵌插骨折、脊柱骨折、骨盆骨折等没有异常活动及骨擦音（C错）。","","N"],["2015-N180",53,"第二节 腰椎退行性疾病","腰椎间盘突出症病理及发病机制",2015,180,"X","","腰椎间盘突出症致坐骨神经痛的原因",[["A","纤维环内层受到突出的髓核刺激"],["B","破裂椎间盘组织产生化学物质的刺激"],["C","自身免疫使神经根发生炎症"],["D","受压的神经根缺血"]],"BCD","破裂椎间盘组织产生化学物质是一种本身不存在于神经根生存环境的物质，自然会刺激神经根产生疼痛（B对）。椎间盘破裂产生的化学物质同时作为自身抗原使得机体产生免疫反应，使得神经根周围组织产生炎症，波及神经根产生疼痛（C对）。神经根受到突入椎管的髓核的急性机械性压迫会产生腰腿痛症状，此外受压神经由于压迫缺血也可产生疼痛（D对）。椎间盘由外层纤维环及中央的髓核构成，软骨板形成椎间盘的上下壁。只有纤维环破裂，髓核经破口脱出时，方可刺激神经根产生坐骨神经痛，单纯纤维环内层受到突出的髓核刺激不会产生坐骨神经痛（A错）。","","N"],["2016-N77",32,"第四节 胆石症","胆囊结石治疗",2016,77,"A","","患者女性，45岁，B超查体发现多个胆囊结石。最大直径1．2cm。胆囊壁光滑，不厚，患者无明显症状，患者要求保留胆囊，应该怎么处理",[["A","观察"],["B","保留胆囊取石"],["C","体外碎石术"],["D","药物碎石"]],"A","中年女性患者，B超查体发现胆囊结石多枚，最大的结石直径1.2cm（结石数量多及结石直径≥2～3cm才考虑行手术治疗），胆囊壁光滑、不厚（胆囊壁增厚（＞3mm）才考虑行手术治疗），患者无明显相关临床症状（无症状的胆囊结石一般不需预防性手术治疗），且不愿切除胆囊，因此暂不予处理，临床观察（A对）。保胆取石术（B错）术后复发率高，且引起胆汁性腹膜炎的可能性较大，故一般不采用。体外碎石术（C错）常用于肾结石及上段输尿管结石的治疗，在胆囊结石病人中用之甚少，且可导致胆管结石形成；碎石后若残留较大结石，需再次碎石治疗。药物碎石（D错）疗法通过口服鹅脱氧胆酸或熊脱氧胆酸，通过改变胆汁的成分促进结石的自我溶解，但总体而言其疗效差、肝毒性大、服药时间长、复发率高。","","N"],["2016-N78",25,"第三节 腹腔间隔室综合征","腹腔间隔室综合征诊断",2016,78,"A","","腹腔间隔室综合征时，膀胱内测得的压力应不低于",[["A","20mmHg"],["B","25mmHg"],["C","30mmHg"],["D","35mmHg"]],"A","腹腔是一个封闭的腔，与外界相对隔绝。在正常情况下，腹腔内压力为零或接近于零。虽然腹腔有一定的扩张限度，但当腹内压（IAP）过高时，腹腔内器官与邻近组织都将受压，引起腹腔内及全身器官生理功能受损，导致器官功能不全和循环衰竭。腹腔间隔室综合征的诊断主要依靠IAP测量，最广泛应用的测定IAP的方法：用Foley尿管经尿道测膀胱压或者直接穿刺膀胱置管测压。诊断腹腔间隔室综合征（ACS）时，膀胱内测得压力应大于20mmHg（A对）。","","N"],["2016-N79",33,"第五节 胰腺神经内分泌肿瘤","胰岛素瘤概述",2016,79,"A","","有关胰岛素瘤的描述，不正确的是",[["A","单发肿瘤占90%以上"],["B","细胞形态是决定其良恶性的主要依据"],["C","手术是唯一根治性治疗手段"],["D","90%以上为良性肿瘤"]],"B","胰岛素瘤90%以上为单发圆形肿瘤（七版黄家驷外科学P1853页）（A对）。胰岛素瘤90%以上为良性肿瘤（D对）。手术是唯一根治性治疗手段（C对），一经诊断，手术应尽早施行。胰腺内分泌肿瘤的良恶性仅从组织、细胞形态学上很难区别，主要取决于有无侵袭周围组织、器官或（和）发生转移等（B错，为本题正确答案）。","","N"],["2016-N80",31,"门静脉高压","食管胃底曲张静脉破裂出血非手术治疗(1)",2016,80,"A","","男性，45岁，10年前患乙型肝炎，保肝治疗后病情缓解，近来查体发现脾大至肋缘，胃镜见食管下段静脉中度曲张。肝功能化验大致正常，血Hb124g/L，WBC2.9×10⁹/L，PLT40×10⁹L，此病人恰当的处理方法是",[["A","脾切除术"],["B","脾切除，贲门周围血管离断术"],["C","脾切除，脾肾分流"],["D","保肝治疗，观察"]],"D","中年男性患者，有乙肝病史10余年，近来查体发现脾大至肋缘，胃镜见食管下段静脉中度曲张（门脉高压常见表现）。肝功能化验大致正常，血Hb124g/L（正常值130～175g/L），WBC2.9×10⁹/L（正常值3.5～9.5×10⁹/L），PLT40×10⁹L（正常值125～350×10⁹L），诊断为乙型肝炎肝硬化门静脉高压症合并脾功能亢进。患者门静脉高压症尚未出现出血症状，目前倾向于不作预防性手术（BC错），重点应为内科保肝治疗（D对），因为肝炎后肝硬化病人的肝功能损害多较严重，任何一种手术对病人都是负担，甚至引起肝功能衰竭。患者脾大至肋缘，说明脾脏为轻度肿大，无需行脾切除术（A错）（九版内科学P603）。","","N"],["2016-N81",17,"第一节 甲状腺疾病","TSH抑制治疗",2016,81,"A","","女性，29岁。因右侧甲状腺结节手术，术中见甲状腺右叶多个囊实性结节，颈部无肿大淋巴结，行右叶全切除术。术后病理报告提示，甲状腺内有5mm乳头状癌灶。进一步的处理应是",[["A","峡部及左叶部分切除术"],["B","口服甲状腺素"],["C","甲状腺近全切除术"],["D","甲状腺全切及颈淋巴结清扫术"]],"B","①甲状腺全切或近全切适用于有颈部放射史、有远处转移、双侧癌结节、腺外侵犯、肿瘤直径＞4cm、预后不良、多发淋巴结转移等情况。②腺叶加峡部切除术适用于肿瘤直径＜1cm，其余阴性者。③对于所有分化型甲状腺癌病人，术中在有效保护甲状旁腺和喉返神经的情况下，至少行病灶同侧中央区淋巴结清扫术在国内已达成共识。该患者为局限于右叶的微小乳头状癌，已行右叶甲状腺全切除，需要再进行峡部切除+同侧中央区淋巴结清扫，术后口服甲状腺素（B对）终身代替治疗，以预防甲状腺功能减退及抑制TSH。峡部及左叶部分切除术（A错）、甲状腺近全切除术（C错）和甲状腺全切及颈淋巴结清扫术（D错）的手术范围过大。根据新版教材，该患者进一步处理为峡部切除+同侧中央区淋巴结清扫+术后口服甲状腺素终身代替治疗，本题无最优答案。","","N"],["2016-N82",26,"第三节 胃十二指肠溃疡的外科治疗","胃十二指肠溃疡瘢痕性幽门梗阻治疗",2016,82,"A","","下列幽门梗阻患者术前准备措施中，不合理的是",[["A","应用广谱抗生素"],["B","纠正水电解质平衡"],["C","禁食、胃肠减压"],["D","温盐水洗胃"]],"A","幽门梗阻是因幽门管、幽门溃疡或十二指肠球部溃疡反复发作形成瘢痕狭窄，合并幽门痉挛水肿，其为外科治疗的绝对适应证，手术方式可采用胃大部切除术（首选）或迷走神经切断加胃窦切除术等，手术目的是恢复胃肠连续性，解除梗阻，术前准备包括禁食、胃管减压（C对）和温盐水洗胃（D对），以清除胃内潴留的食物，减轻胃粘膜水肿，同时给与H₂受体拮抗剂以减少胃酸分泌，纠正水电解质和酸碱平衡紊乱（B对），加强营养支持，改善贫血和低蛋白血症，同时麻醉前和围术期静脉注射广谱抗生素（A对）。根据九版外科学和7版黄家驷外科学相关叙述，幽门梗阻患者术前的抗生素使用是必要的，但真题似乎认为不应该使用广谱抗生素，该题A选项存在争议。本题参考答案为A。","","N"],["2016-N83",1,"第五节 酸碱平衡失调","呼吸性碱中毒诊断",2016,83,"A","","女性，30岁。癔病发作后出现手足搐搦，口周麻木，其原因是",[["A","代谢性酸中毒"],["B","代谢性碱中毒"],["C","呼吸性碱中毒"],["D","呼吸性酸中毒"]],"C","癔病是由精神因素，如生活事件、内心冲突、暗示或自我暗示，作用于易病个体引起的精神障碍。癔病发作时常为腕关节，掌指关节屈曲，指骨间关节伸直，拇指内收，下肢伸直或全身僵硬，呼吸阵发性加快，引起通气过度，二氧化碳呼出过多，引起呼吸性碱中毒（C对）。呼吸性碱中毒后，病人可发生眩晕，手足抽搐和口周麻木。代谢性酸中毒（A错）常见病因有碱性物质丢失过多、酸性物质产生过多和肾功能不全等。代谢性碱中毒（B错）常见病因有胃液丧失过多、碱性物质摄入过多、缺钾和利尿剂的作用等。呼吸性酸中毒（D错）常见原因有全身麻醉过深、镇静剂过量、中枢神经系统损伤、气胸、急性肺水肿和呼吸机使用不当等。","","N"],["2016-N84",13,"第一节 术前准备","心血管病",2016,84,"A","","下列高血压患者术前处理中，正确的是",[["A","术前两周停用降压药"],["B","入手术室血压骤升，应果断停手术"],["C","血压降至正常后再手术"],["D","血压160/100mmHg以下不予处理"]],"D","高血压患者应继续服用降压药物，避免戒断综合征（A错）；病人血压在160/100mmHg以下时不予处理，也不必把血压降至正常范围再手术（D对C错）；进入手术室，血压急骤升高者，应与麻醉医生共同处理，根据病情和手术性质，抉择实施或延期手术（B错）。","","N"],["2016-N85",7,"第一节 热力烧伤","Ⅲ度烧伤",2016,85,"A","","烧伤创面可见脂肪组织，应属于",[["A","Ⅰ度烧伤"],["B","浅Ⅱ度烧伤"],["C","深Ⅱ度烧伤"],["D","Ⅲ度烧伤"]],"D","皮肤分为表皮层，真皮层和皮下组织。表皮层（3版八年制组织学与胚胎学P166）位于皮肤浅层，由外到内依次是角质层、透明层、颗粒层、棘层、基底层（生发层）。真皮层（3版八年制组织学与胚胎学 P170）位于表皮下，由外到内分为乳头层和网织层。皮下组织（3版八年制组织学与胚胎学 P170）位于真皮下方，由疏松结缔组织和脂肪组织组成。Ⅰ°烧伤：仅伤及表皮浅层，生发层健在（A错）；浅Ⅱ°烧伤：伤及表皮的生发层和真皮乳头层（B错）；深Ⅱ°烧伤：伤及真皮乳头层以下，但仍残留部分网状层，由于真皮层内有残存的皮肤附件，故位于真皮层下方的疏松结缔组织和脂肪组织不可见（C错）；Ⅲ°烧伤：又称焦痂型烧伤，深达皮下组织，故创面可见皮下脂肪组织（D对）。","","N"],["2016-N86",18,"第三节 乳腺良性疾病","导管内乳头状瘤临床表现",2016,86,"A","","不可能出现乳头内陷的乳房疾病是",[["A","乳腺癌"],["B","浆细胞性乳腺炎"],["C","乳腺Paget病"],["D","乳管内乳头状瘤"]],"D","乳头内陷是乳腺疾病的常见症状。乳腺癌（A对）病人，癌细胞浸润周围组织产生粘连、牵拉，若病灶位于乳头或乳晕周围，则可侵犯乳管使其收缩可引起乳头内陷。浆细胞性乳腺炎（B对）区别于一般的炎症性疾病，属于乳腺良性病变，是由于乳晕下导管有阻塞，引起导管扩张，管壁上皮萎缩，管内各种类脂质及细胞碎屑积聚腐蚀管壁，在管壁周围的脂肪组织内见有片状的浆细胞浸润；病变发展时有局部红、肿、痛等症状，并可触及肿块，也可见皮肤粘连、乳头回缩、局部水肿及腋窝淋巴结增大等征象，易误诊为乳腺癌；乳腺Paget病（C对）即乳头湿疹样乳腺癌，其恶性度低，发展缓慢，乳头有瘙痒、烧灼感，后发展为乳头和乳晕的皮肤变粗糙、糜烂如湿疹样，进而形成溃疡，有时有鳞屑样痂皮，累及乳头深层时可出现乳头内陷或溃烂，较晚发生淋巴结转移。乳管内乳头状瘤大部分病例发生在大乳管近乳头的壶腹部，瘤体小。而发生于中小乳管的乳头状瘤位于乳房周围区域，均不会引起乳头凹陷（D错，为本题正确答案）。","","N"],["2016-N87",32,"第十节 胆囊息肉和良性肿瘤","胆囊息肉治疗",2016,87,"A","","下列无症状的胆囊疾病中，应早做手术的是",[["A","胆囊多发息肉样病变"],["B","胆囊单发结石1.5cm"],["C","胆囊单发息肉病变1.2cm"],["D","胆囊多发结石"]],"C","胆囊多发息肉（A错）常为良性病变，若无症状，无需手术。无症状胆囊结石的手术指征其中一条为：结石数量多及结石直径≥2～3cm。只有胆囊单发结石1.5cm（B错）或胆囊多发结石（D错）不满足手术指征。胆囊息肉直径＞1cm（C对）是恶变的危险因素，应尽早手术切除。","","N"],["2016-N88",44,"第一节 骨折的定义、成因、分类及移位","骨折成因概述",2016,88,"A","","运动员骤然跨步，由于肌肉突然猛烈收缩，最不可能发生的损伤是",[["A","髂前上棘撕脱骨折"],["B","髌骨骨折"],["C","跟腱撕裂"],["D","胫骨干骨折"]],"D","髂前上棘撕脱骨折（A对）为缝匠肌猛烈收缩的结果。骤然跨步由于肌肉突然猛烈收缩，肌肉牵拉暴力常致髌骨横形骨折（B对）。跟腱撕裂（C对）多由间接暴力引起，主要由腓肠肌猛烈收缩引起。单纯胫骨干骨折较少见，多由比较轻的直接暴力引起（D错，为本题正确答案）。","","N"],["2016-N89",48,"第一节 脊柱骨折","压缩骨折",2016,89,"A","","颈椎压缩性骨折合并脱位，首选的治疗方法是",[["A","颌枕带牵引"],["B","手法复位，石膏固定"],["C","颅骨牵引"],["D","切开复位"]],"C","颈椎压缩性骨折合并脱位，应首选颅骨牵引复位（C对）及前路椎间融合，次选后路切开复位固定术（D错）。若合并急性椎间盘突出，则在复位前需先行前路椎间盘切除，再行后路切开复位内固定和前路植骨融合。颌枕带牵引（A错）可用于治疗稳定型颈椎骨折轻度压缩者。颈椎骨折手法复位，石膏固定（B错）困难，很少采用。注意：颈椎骨折合并脱位与胸腰椎骨折合并脱位首选处理方法不一样，胸腰椎骨折合并脱位常合并脊髓损伤，无论有无脊髓神经损伤，都应首选后路切开复位内固定以恢复脊柱正常解剖序列，对合并神经损伤的病人还需行椎管减压手术。","","N"],["2016-N90",53,"第一节 颈椎退行性疾病","颈椎病诊断",2016,90,"A","","女性，52岁，颈部痛伴右肩部痛一年余，近5个月出现四肢麻木无力，行走时有踩棉花感，查体：颈部无明显畸形，活动轻度受限，右手及前臂尺侧感觉减退，双下肢紧张增高，肌力Ⅳ级，X线见颈椎骨质增生，生理曲度变直，最有可能的诊断是",[["A","肩周炎"],["B","交感神经型颈椎病"],["C","脊髓型颈椎病"],["D","颈椎肿瘤"]],"C","根据患者出现四肢麻木，无力，行走时有踩棉花样感觉，右手及前臂尺侧感觉减退，双下肢肌张力增高，肌力Ⅳ级等症状及体查，结合X线结果：颈椎骨质增生，生理曲度变直，诊断考虑为脊髓型颈椎病（C对）。肩周炎（十版外科学P713）（A错）典型临床表现为肩关节各个方向活动受限，肩部疼痛。交感神经型颈椎病（B错）典型临床表现为头痛、头晕，视物模糊，瞳孔扩大或缩小等。颈椎肿瘤（D错）较少见，一般不作优先考虑。","","N"],["2016-N111",33,"第二节 胰腺炎","CT扫描",2016,111,"A","","女性，56岁，2天前突发持续上腹痛，阵发加剧，并腰背部胀痛，恶心，呕吐，急诊入院。既往有胆囊结石病史3年，查体：T36.9℃，P104次/分，R20次/分，BP132/82mmHg，巩膜无黄染，上腹较膨隆，压痛，轻度肌紧张及反跳痛，肠鸣音弱。化验：Hb128g/L，WBC16.7×10⁹/L，血淀粉酶786U/dL，尿淀粉酶1600U/dL。为明确诊断，最有效的检查方法是",[["A","腹部X线片"],["B","腹部CT"],["C","腹部B超"],["D","ERCP"]],"B","56岁女性患者，既往有胆囊结石病史3年（胰腺炎的常见致病危险因素）。2天前突发持续上腹痛，阵发加剧，并腰背部胀痛，恶心，呕吐（急性胰腺炎常见临床表现）。查体：上腹较膨隆，压痛，轻度肌紧张及反跳痛（提示轻度腹膜刺激征），肠鸣音弱（提示麻痹性肠梗阻）。化验：WBC16.7×10⁹/L，血淀粉酶786U/dL，尿淀粉酶1600U/dL（淀粉酶测值远大于500U/dL，提示急性胰腺炎）。综合该患者的病史、体查、实验室检查，诊断考虑急性胰腺炎。为明确诊断，最有效的检查方法是腹部CT（B对）。不仅能诊断急性胰腺炎，而且能鉴别是否合并胰腺组织坏死。在胰腺弥漫性肿大的背景上若出现质地不均、液化和蜂窝状低密度区，则可诊断为胰腺坏死。重症胰腺炎时，可有皂化斑形成，腹部X线片（A错）可见钙化点，但不能作为诊断依据。B超（C错）经济简便易行，是胰腺炎首选的方法，可用于排除性诊断，但由于上腹部胃肠气体的干扰，可影响诊断的准确性。ERCP（D错）易诱发胰腺炎，临床已被MRCP取代。","c98","N"],["2016-N112",33,"第二节 胰腺炎","急性胰腺炎非手术治疗",2016,112,"A","","女性，56岁，2天前突发持续上腹痛，阵发加剧，并腰背部胀痛，恶心，呕吐，急诊入院。既往有胆囊结石病史3年，查体：T36.9℃，P104次/分，R20次/分，BP132/82mmHg，巩膜无黄染，上腹较膨隆，压痛，轻度肌紧张及反跳痛，肠鸣音弱。化验：Hb128g/L，WBC16.7×10⁹/L，血淀粉酶786U/dL，尿淀粉酶1600U/dL。诊断确定后，首选治疗措施是",[["A","急诊手术切除胆囊"],["B","急诊胆总管探查术"],["C","ERCP置管引流"],["D","保守治疗"]],"D","非手术治疗适用于急性胰腺炎全身反应期、水肿性及尚无感染的出血坏死性胰腺炎。该患者腹膜刺激征轻微，且无明显感染中毒征象，首选治疗为保守治疗（D对），包括：①禁食、胃肠减压；②补液、防治休克；③镇痛解痉；④抑制胰腺分泌；⑤营养支持治疗；⑥酌情应用抗生素。手术适应证：①急性腹膜炎不能排除其他急腹症时；②胰腺和胰周坏死组织继发感染；③伴胆总管下端梗阻或胆道感染者；④合并肠穿孔、大出血或胰腺假性囊肿。","c98","N"],["2016-N113",32,"第五节 胆道感染","急性梗阻性化脓性胆管炎诊断",2016,113,"A","","女，32岁。9个月前因先天性胆总管囊肿行囊肿切除、胆肠Roux-Y吻合术，术中曾输血400ml。2个月来易“感冒”，自服抗生素好转，近一周出现发热、寒战，最高体温达39℃。查体：P123次/分，R22次/分，BP102/80mmHg，巩膜黄染，双肺呼吸音粗，上腹轻压痛。化验：WBC18×10⁹/L，中性粒细胞89%，TBil121μmol/L，DBil86μmol/L，ALT203U/L。最可能的诊断是",[["A","急性胰腺炎"],["B","上消化道穿孔"],["C","急性重症胆管炎"],["D","急性肝炎"]],"C","青年女性，有先天性胆总管囊肿行囊肿切除、胆肠Roux-Y吻合术手术史（胆道手术史，为胆道感染的易感人群）。近一周出现发热、寒战，巩膜黄染，上腹轻压痛（典型的Charcot三联征）。化验：WBC18×10⁹/L（正常值4～10×10⁹/L），中性粒细胞占比89%（正常约50%～70%）（提示存在感染），血清总胆红素（TBil）121μmol/L（成人正常值3.4～17.1μmol/L），血清结合胆红素（DBil） 86μmol/L（正常值0～6.8μmol/L），ALT203U/L（正常值＜40U/L）（提示肝功能损害，急性胆管炎肝功能有不同程度的损害），查体：P123次/分，BP102/80mmHg，休克指数=脉率/收缩压=123/102＞1 ，即有休克存在，可诊断为急性胆管炎（C对）。急性胰腺炎（P484）（A错）典型表现为左上腹剧痛，可向左肩即左腰部放射，伴腹胀、恶心、呕吐等症状，严重者可出现明显的腹膜刺激征；上消化道穿孔（P356）（B错）典型表现为突发上腹部刀割样剧痛，并有典型的板样腹体征；急性肝炎（D错）早期症状为低热、疲乏无力、食欲减退，伴有恶心、呕吐、厌油腻、肝区不适及尿黄等。","c99","N"],["2016-N114",32,"第五节 胆道感染","紧急胆管减压引流",2016,114,"A","","女，32岁。9个月前因先天性胆总管囊肿行囊肿切除、胆肠Roux-Y吻合术，术中曾输血400ml。2个月来易“感冒”，自服抗生素好转，近一周出现发热、寒战，最高体温达39℃。查体：P123次/分，R22次/分，BP102/80mmHg，巩膜黄染，双肺呼吸音粗，上腹轻压痛。化验：WBC18×10⁹/L，中性粒细胞89%，TBil121μmol/L，DBil86μmol/L，ALT203U/L。下列治疗措施中，最有效的是",[["A","加大抗生素用量"],["B","ERCP置管引流"],["C","腹腔镜探查"],["D","PTCD"]],"D","患者诊断为急性重症胆管炎，原则是立即解除胆道梗阻并引流。根据患者既往行胆总管囊肿切除术+胆肠Roux-Y吻合术（该术式吻合口一般位于肝门）既往史，可推测此次发病为高位胆管梗阻引起的急性重症胆管炎。PTCD（D对）操作简单，能及时减压，对较高位胆管或非结石性阻塞效果较好，可作为首选治疗措施。患者行胆肠Roun－Y手术，壶腹部，胆管，十二指肠等部位的生理结构改变，无法经十二指肠做ERCP置管引流（B错）；加大抗生素用量（A错）和腹腔镜探查（C错）均不能立即解除胆道梗阻并引流。","c99","N"],["2016-N115",32,"第五节 胆道感染","急性梗阻性化脓性胆管炎病因",2016,115,"A","","女，32岁。9个月前因先天性胆总管囊肿行囊肿切除、胆肠Roux-Y吻合术，术中曾输血400ml。2个月来易“感冒”，自服抗生素好转，近一周出现发热、寒战，最高体温达39℃。查体：P123次/分，R22次/分，BP102/80mmHg，，巩膜黄染，双肺呼吸音粗，上腹轻压痛。化验：WBC18×10⁹/L，中性粒细胞89%，TBil121μmol/L，DBil86μmol/L，ALT203U/L。引起此病症的根本原因最可能是",[["A","体质虚弱易感染"],["B","胆肠吻合口狭窄"],["C","肝门部胆管癌"],["D","术中输血感染肝炎"]],"B","患者既往行胆总管囊肿切除术+胆肠Roux-Y吻合术，可因胆肠吻合口狭窄（B对）引起胆道逆行感染。体质虚弱（A错）为急性重症胆管炎的易感因素之一，但题干所述并未提示患者体质虚弱。肝门部胆管癌（十版外科学P484）（C错）可引起黄疸，但一般不引起腹痛及腹膜刺激征，未合并感染时无白细胞增多、中性粒细胞比值升高等感染中毒表现。术中输血感染肝炎（D错），造成肝实质炎症而非胆道系统炎症，一般由肝炎病毒引起，不出现白细胞增多、中性粒细胞比值升高等细菌感染的实验室检查结果。","c99","N"],["2016-N116",26,"第三节 胃十二指肠溃疡的外科治疗","胃十二指肠溃疡穿孔诊断",2016,116,"A","","女性，63岁。半年来因下肢骨关节病疼痛服用布洛芬治疗。10天来上腹不适，1周前突发腹痛，经禁食、输液4天后好转，但仍觉上腹胀满，不能进食，发热，查体：T37．8摄氏度，P96次/分，BP130/80mmHg，上腹饱满有压痛，轻度肌紧张，肠鸣音正常。B超：胆囊6．8×3．5，壁厚3mm，胰腺显示不清，上腹肝下有一直径10cm含液性病变。化验：WBC14×10⁹/L，中性粒细胞84%，Hb112g/L，血尿淀粉酶正常。患者最可能的诊断是",[["A","胰腺假性囊肿"],["B","胃穿孔后包裹积液"],["C","胆囊穿孔包裹积液"],["D","巨大肝囊肿"]],"B","女性，63岁。半年来因下肢骨关节病疼痛服用布洛芬治疗。10天来上腹不适，1周前突发腹痛。B超：上腹肝下有一直径 10cm含液性病变。为患者长期服用非甾体抗炎药，导致胃溃疡并穿孔，包裹局限于肝下（B对）。其他选项并不符合该患者的临床症状和各项检查。胆囊穿孔包裹积液（十版外科学P477）（C错）的患者曾有急性胆囊炎病史，未穿孔前即表现为右上腹绞痛或持续性疼痛伴阵发加剧，畏寒发热，右上腹局部压痛反跳痛，可触及肿大的胆囊，Murphy 征阳性。胰腺假性囊肿（十版外科学P490）（A错）多继发于胰腺炎或上腹部外伤后，上腹逐渐膨隆，腹胀，压迫胃、十二指肠引起恶心、呕吐，影响进食。若患者于一周前患胰腺炎，此时尿淀粉酶应该还未降为正常，且胰腺假性囊肿多位于胰体尾部而非位于肝下，故不考虑为胰腺假性囊肿。肝囊肿（十版外科学P451）因生长缓慢可长期或终身无症状，常在B超检查时偶然发现，且巨大肝囊肿（D错）一般大于10cm。","c100","N"],["2016-N117",25,"第二节 腹腔脓肿","经皮穿刺置管引流术",2016,117,"A","","女性，63岁。半年来因下肢骨关节病疼痛服用布洛芬治疗。10天来上腹不适，1周前突发腹痛，经禁食、输液4天后好转，但仍觉上腹胀满，不能进食，发热，查体：T37．8摄氏度，P96次/分，BP130/80mmHg，上腹饱满有压痛，轻度肌紧张，肠鸣音正常。B超：胆囊6．8×3．5，壁厚3mm，胰腺显示不清，上腹肝下有一直径10cm含液性病变。化验：WBC14×10⁹/L，中性粒细胞84%，Hb112g/L，血尿淀粉酶正常。此时最适宜的处理措施是",[["A","穿刺置管引流"],["B","胆囊切除术"],["C","继续保守治疗"],["D","开腹探查"]],"A","患者上腹包裹性积液，且已有压迫症状，最好的治疗方法是B超引导下穿刺置管引流（A对），该法创伤小，局麻下即可完成，且一般不会污染腹腔，引流效果好。患者已出现临床症状，不能继续保守治疗（C错）。开腹探查（D错）创伤大，且易造成腹腔污染，为次选的手术方法。","c100","N"],["2016-N118",57,"第四节 原发性恶性骨肿瘤","骨肉瘤诊断",2016,118,"A","","女性，16岁。6个月来左小腿上段肿胀疼痛，近1个月来肿胀明显，以夜间痛为著。查体：左小腿上段肿胀，浅静脉怒张，压痛明显，触及一直径约6cm左右肿块，质硬，固定，边界不清。X线检查示，左胫骨上端呈虫蚀状溶骨性破坏，骨膜反应明显，可见Codman三角。最可能的诊断是",[["A","左胫骨慢性骨髓炎"],["B","左胫骨软骨肉瘤"],["C","左胫骨骨肉瘤"],["D","左胫骨骨巨细胞瘤恶变"]],"C","16岁女性患者（骨肉瘤好发年龄），左小腿上段胀痛半年，加重1月，夜间痛显著（骨肉瘤的典型临床表现）。查体：左小腿上段肿胀（骨肉瘤好发部位），浅静脉怒张，压痛明显，触及一直径约6cm左右肿块，质硬，固定，边界不清。X线示：左胫骨上端呈虫蚀状溶骨性破坏，骨膜反应明显，可见Codman三角（骨肉瘤典型X线表现）。综合该患者病史、体查及影像学检查，诊断考虑左胫骨骨肉瘤（C对）。左胫骨慢性骨髓炎（十版外科学P733）（A错）病变不活动阶段表现为皮肤表面有窦道，伤口长期不愈合，偶有小块死骨排出；活动阶段可出现局部红肿热痛。X线片表现为虫蛀状骨破坏与骨质稀疏，并逐渐出现硬化区。左胫骨软骨肉瘤（十版外科学P766）（B错）发病缓慢，以疼痛和肿胀为主。X线表现为一密度减低的溶骨性破坏，边界不清，病灶内有散在的钙化斑点或絮状骨化影，典型者可有云雾状改变。左胫骨骨巨细胞瘤恶变（D错）X线表现类似于非恶性骨巨细胞瘤，表现为骨端偏心位、溶骨性、囊性破坏，病灶膨胀性生长、骨皮质变薄，呈肥皂泡样改变。","c101","N"],["2016-N119",57,"第四节 原发性恶性骨肿瘤","骨肉瘤治疗",2016,119,"A","","女性，16岁。6个月来左小腿上段肿胀疼痛，近1个月来肿胀明显，以夜间痛为著。查体：左小腿上段肿胀，浅静脉怒张，压痛明显，触及一直径约6cm左右肿块，质硬，固定，边界不清。X线检查示，左胫骨上端呈虫蚀状溶骨性破坏，骨膜反应明显，可见Codman三角。在手术治疗前，必须要进行的检查是",[["A","腹股沟淋巴结活检"],["B","头颅CT"],["C","肿块穿刺物细菌培养"],["D","胸部X线摄片"]],"D","骨肉瘤极易发生肺转移，因此术前必须进行的检查为胸部X线摄片（D对）。若发现肺部转移灶，而患者临床分期为G₂T₁₋₂M₁者，除原发灶根治性切除及术前术后化疗外，可同时行手术切除转移灶。","c101","N"],["2016-N120",57,"第四节 原发性恶性骨肿瘤","骨肉瘤治疗",2016,120,"A","","女性，16岁。6个月来左小腿上段肿胀疼痛，近1个月来肿胀明显，以夜间痛为著。查体：左小腿上段肿胀，浅静脉怒张，压痛明显，触及一直径约6cm左右肿块，质硬，固定，边界不清。X线检查示，左胫骨上端呈虫蚀状溶骨性破坏，骨膜反应明显，可见Codman三角。最适合的治疗方法",[["A","单纯化疗"],["B","抗生素治疗"],["C","病灶切除，术前术后化疗"],["D","肿瘤刮除，骨水泥填充术"]],"C","骨肉瘤是典型的恶性肿瘤，应采取手术治疗为主的综合治疗。骨肉瘤对化疗敏感，术前、术后可给予大剂量化疗，可降低瘤负荷，延长患者生存期，因此最佳治疗方法为病灶切除，术前术后化疗（C对）。抗生素治疗（B错）用于治疗急性血源性骨髓炎。肿瘤刮除，骨水泥充填术（D错）用于治疗骨巨细胞瘤。除少数血液系统肿瘤及滋养层细胞肿瘤、睾丸精原细胞瘤、胚胎性横纹肌肉瘤可单独应用化疗（A错）以外，多数恶性肿瘤应采取手术治疗为主的综合治疗。","c101","N"],["2016-N145",20,"第三节 肺肿瘤","鳞状细胞癌",2016,145,"B","","中老年男性吸烟患者易发生的肺癌是",[["A","鳞状细胞癌"],["B","腺癌"],["C","小细胞癌"],["D","大细胞癌"]],"A","常见的肺癌包括鳞状细胞癌、腺癌、小细胞癌和大细胞癌这四种。其中鳞状细胞癌（A对）多见于中老年男性，与吸烟有密切关系。八版病理学观点认为鳞状细胞为肺癌中最常见的类型，但八版外科学观点认为鳞状细胞癌曾是最常见的肺癌，现在已经被腺癌超越，可见鳞状细胞癌虽不是最常见的，但发病率仅次于腺癌。值得一提的是，小细胞癌（C错）与吸烟关系密切，老年男性多见；大细胞癌（D错）与吸烟有关，老年男性多见。但两者发病率均不及鳞状细胞癌，故鳞状细胞癌为中老年男性吸烟患者易发生的肺癌。腺癌（B错）为女性患者易发生的肺癌。","","N"],["2016-N146",20,"第三节 肺肿瘤","腺癌",2016,146,"B","","女性患者易发生的肺癌是",[["A","鳞状细胞癌"],["B","腺癌"],["C","小细胞癌"],["D","大细胞癌"]],"B","肺腺癌近年来发病率上升明显，已超鳞癌成为最常见的肺癌。较易发生于女性（B对）及不抽烟者。鳞癌（A错）、小细胞癌（C错）和大细胞癌（D错）均好发于老年男性，与吸烟关系密切。","","N"],["2016-N147",26,"第二节 胃癌及其他胃肿瘤","早期胃癌",2016,147,"B","","属于早期胃癌的是",[["A","癌组织侵入黏膜下层并有淋巴结转移"],["B","癌组织侵入胃壁肌层有淋巴结转移"],["C","癌组织侵出浆膜无淋巴结转移"],["D","皮革胃"]],"A","胃黏膜分层为黏膜层、黏膜下层、肌层、外膜（浆膜）层。早期胃癌的概念是癌组织浸润仅限于黏膜层或黏膜下层，而不论有无淋巴结转移。因此癌组织侵入黏膜下层并有淋巴结转移（A对）为早期胃癌。癌组织侵入胃壁肌层有淋巴结转移（B错）、癌组织侵出浆膜无淋巴结转移（C错）、皮革胃（全胃受累）（D错）属于进展期胃癌。","","N"],["2016-N148",26,"第二节 胃癌及其他胃肿瘤","进展期胃癌",2016,148,"B","","预后最差的是",[["A","癌组织侵入黏膜下层并有淋巴结转移"],["B","癌组织侵入胃壁肌层有淋巴结转移"],["C","癌组织侵出浆膜无淋巴结转移"],["D","皮革胃"]],"D","癌组织侵入黏膜下层并有淋巴结转移为早期胃癌，预后较好（A错）。癌组织侵入胃壁肌层有淋巴结转移（B错）、癌组织侵出浆膜无淋巴结转移（C错）、皮革胃（D对）均属于进展期胃癌，其中皮革胃为全胃受到侵袭，恶性程度高，发生转移早，预后最差。","","N"],["2016-N149",47,"第二节 股骨近端骨折","股骨颈解剖概要",2016,149,"B","","髋内翻的颈干角范围是",[["A","≥140°"],["B","＜140°"],["C","＞110°"],["D","≤110°"]],"D","股骨颈的长轴与股骨干纵轴之间形成的角度称为颈干角，又称内倾角。正常值在110～140°之间，颈干角大于正常值为髋外翻，小于正常值为髋内翻。因此，髋内翻为≤110°（D对）。","","N"],["2016-N150",47,"第二节 股骨近端骨折","股骨颈解剖概要",2016,150,"B","","髋外翻的颈干角范围是",[["A","≥140°"],["B","＜140°"],["C","＞110°"],["D","≤110°"]],"A","股骨颈的长轴与股骨干纵轴之间形成的角度称为颈干角，又称内倾角。正常值在110～140°之间，颈干角大于正常值为髋外翻，小于正常值为髋内翻。因此，髋外翻为≥140°（A对）。","","N"],["2016-N175",32,"第五节 胆道感染","急性非结石性胆囊炎临床表现",2016,175,"X","","急性非结石性胆囊炎的特点有",[["A","好发于老年女性"],["B","病情发展迅速"],["C","长期肠外营养者易发生"],["D","坏疽发生率高"]],"BCD","急性非结石性胆囊炎多见于老年男性（A错），应区别于急性结石性胆囊炎，后者女性多见。临床表现类似急性结石性胆囊炎，但病情发展更为迅速（B对），穿孔及坏疽发生率高（D对），一经诊断，应及早手术治疗。长期肠外营养时，胃肠道缺乏食物刺激，导致包括缩胆囊素在内的胃肠激素分泌减少，导致胆囊排空障碍，长期胆汁淤积及缺血可导致非结石性胆囊炎的产生（C对）。","","N"],["2016-N176",33,"第二节 胰腺炎","急性胰腺炎局部并发症",2016,176,"X","","重症急性胰腺炎可能出现的并发症",[["A","胰腺脓肿"],["B","胰腺假性囊肿"],["C","腹腔出血"],["D","腹腔间隔室综合征"]],"ABCD","重症急性胰腺炎可能出现的并发症包括：①胰腺及胰周组织坏死；②胰腺脓肿（A对）；③胰腺假性囊肿（B对）；④胃肠道瘘；⑤腹腔出血（C对）；⑥腹腔间隔室综合征（D对）。","","N"],["2016-N177",31,"门静脉高压","原发肝病",2016,177,"X","","肝硬化门脉高压症合并肝癌者，接受肝移植的术后，获得的益处有",[["A","消除肝硬化"],["B","解除脾功能亢进"],["C","降低食管静脉破裂出血风险"],["D","不再发生肝癌"]],"ABC","肝移植替换了病肝，消除了肝硬化（A对）。肝移植解除了门脉高压，门静脉系统血流动力学恢复到正常，脾脏淤血减轻，可部分解除脾功能亢进（B对）；同时解除了交通静脉的曲张，降低食管静脉破裂出血风险（C对）。肝癌患者即使肝移植后，也可能再次发生肝癌（D错）。","","N"],["2016-N178",28,"第三节 特殊类型阑尾炎","小儿急性阑尾炎",2016,178,"X","","需要尽早手术的阑尾炎是",[["A","儿童急性阑尾炎"],["B","老人急性阑尾炎"],["C","妊娠35周急性阑尾炎"],["D","右下腹可触及包块的阑尾炎"]],"ABC","儿童急性阑尾炎病情发展快，体征不明显，穿孔率高，需要尽早手术（A对）。老人急性阑尾炎体征不典型，体温和白细胞升高均不明显，容易延误诊断和治疗，需要尽早手术（B对）。妊娠35周急性阑尾炎为妊娠后期，腹腔感染后更加难以控制，需要尽早手术（C对）。右下腹可触及包块的阑尾炎无法确定是穿孔局限，阑尾脓肿或是慢性阑尾炎，无法确定是否需要尽早手术（D错）。","","N"],["2016-N179",47,"第五节 髌骨骨折","髌骨骨折治疗",2016,179,"X","","髌骨骨折的治疗原则是",[["A","解剖复位，保持关节面平滑"],["B","尽可能保留髌骨"],["C","稳定固定的情况下早期活动"],["D","屈曲位膝关节固定"]],"ABC","七版黄家驷外科学P2859页认为，髌骨骨折的治疗原则是：①尽可能保留髌骨；②充分恢复其后关节面的平整；③修复股四头肌扩张部分的裂伤；④早期锻炼股四头肌；⑤在尽可能条件下，早期练习膝关节的伸屈活动，以期通过模造，使髌股关节恢复吻合（C对）。解剖复位，保持关节面平滑（A对），否则容易引起髌股关节的骨关节病。尽可能保留髌骨（B对），切除髌骨易导致股四头肌的伸膝功能及控制膝关节的能力受损。髌骨骨折应保持膝关节伸直位固定（D错）。","","N"],["2016-N180",51,"第二节 慢性软组织损伤","腰腿痛治疗",2016,180,"X","","严重腰肌劳损时可以采取的治疗措施有",[["A","卧床休息，活动时带腰托保护"],["B","物理治疗"],["C","联合服用两种非甾体抗炎药"],["D","压痛点注射激素封闭治疗"]],"ABD","三版八年制外科学P946页认为，腰肌劳损的治疗原则为：（1）病情较重时，应适当休息，定时改变姿势，必要时可在工作中使用腰围（A对），但休息时应解除；（2）腰部进行物理治疗（B对），为治疗腰肌劳损的主要方法；（3）腰痛点可行糖皮质激素注射封闭治疗（D对）；（4）腰痛明显时，可服用非甾体类抗炎药，但不能多种合用，否则可增加不良反应，而治疗效果增强不明显（C错）。","","N"],["2017-N57",1,"第四节 镁、钙、磷代谢紊乱","低镁血症",2017,57,"A","","低血钾的患者给予补钾治疗后仍然低血钾，此时应该考虑合并",[["A","低钠血症"],["B","低磷血症"],["C","低钙血症"],["D","低镁血症"]],"D","补钾治疗后仍然低血钾，此时应该考虑合并低镁血症（D对）。低钾与低镁相伴而行，低镁时可能会影响髓袢升支粗段钠泵的激活，使钾的重吸收受到影响。","","N"],["2017-N58",29,"第六节 结肠癌","结肠癌诊断",2017,58,"A","","结肠癌患者血清CEA检测的临床意义，下列描述错误的是",[["A","CEA的阳性率与结肠癌的分期有关"],["B","术后CEA未明显下降说明可能有肿瘤的残留"],["C","术后CEA持续升高提示肿瘤复发"],["D","术前CEA指标正常是缩小切除范围的依据"]],"D","CEA即血清癌胚抗原，是胎儿胃肠道产生的一组糖蛋白，在结肠癌、胃癌、肺癌、乳癌中升高，对直肠癌疗效判断、病情发展、监测和预后估计是一个较好的肿瘤标志物，但其特异性不强，灵敏度不高，对肿瘤早期诊断作用不明显。术前CEA指标正常不能作为缩小切除范围的依据（D错，为本题正确答案），直肠癌的外科治疗是主要的治疗方法，直肠癌的切除范围包括癌肿在内的两端足够肠段（低位直肠癌的下切缘应距肿瘤边缘2cm）、全部直肠系膜或至少包括癌肿下缘5cm的直肠系膜、周围淋巴结及浸润的组织。CEA主要用于检测复发。通过CEA早期检查复发患者，结合放射学检查，可提高手术切除率和帮助结肠癌的预后判断，术后CEA未明显下降说明可能有肿瘤的残留（B对），当它水平升高时通常意味着残存肿瘤术后复发（C对）。CEA的分期与TNM分期呈正相关，TNMⅠ期、TNMⅡ期、TNMⅢ期、TNMⅣ期病人的血清CEA阳性率依次分别是25%、45%、75%和85%左右，即CEA的阳性率与结肠癌的分期有关（A对）（二版八年制外科学P587）。","","N"],["2017-N59",17,"第一节 甲状腺疾病","喉上神经损伤",2017,59,"A","","男性，45岁。因甲状腺癌行左叶甲状腺全切术。术后出现饮水呛咳，但发音正常。首先考虑的原因是",[["A","喉返神经损伤"],["B","交感神经损伤"],["C","喉上神经外支损伤"],["D","喉上神经内支损伤"]],"D","一侧喉返神经损伤（A错），大都可以引起声嘶；双侧喉返神经损伤，可导致失声或严重的呼吸困难，甚至窒息；交感神经受损（B错）表现为瞳孔缩小、眼睑下垂及眼球内陷即霍纳综合征；喉上神经外支损伤（C错）会使环甲肌瘫痪，引起声带松弛，音调降低；喉上神经内支损伤（D对）则喉部黏膜感觉丧失，进食特别是饮水时，容易误咽发生呛咳。","","N"],["2017-N60",18,"第四节 乳腺癌","乳腺癌分期",2017,60,"A","","女，55岁。左侧乳房内肿块4cm×3cm，基底不固定，左腋下可触及多个质硬淋巴结相互融合，淋巴活检病理报告乳腺癌转移，未发现远处转移。按照国际标准，应属于的分期是",[["A","T₁N₁M₀"],["B","T₂N₁M₀"],["C","T₃N₁M₀"],["D","T₂N₂M₀"]],"D","该患者病理诊断为乳腺癌，根据国际抗癌协会建议的T（原发癌瘤）、N（区域淋巴结）、M（远处转移）分期法，患者左侧乳房内肿块大小4cm×3cm属于T₂期（癌瘤长径＞2cm，≤5cm）；左腋下可触及多个质硬淋巴结相互融合属于N₂期（同侧腋窝有肿大淋巴结彼此融合）；未发现远处转移属于M₀期（无远处转移）。该患者应属于的分期是T₂N₂M₀（D对）。","","N"],["2017-N61",23,"第三节 股疝","股疝病理解剖",2017,61,"A","","最容易发生嵌顿的腹外疝是",[["A","脐疝"],["B","腹股沟直疝"],["C","腹股沟斜疝"],["D","股疝"]],"D","最容易发生嵌顿的腹外疝是股疝（D对），由于股管几乎是垂直的疝块在卵圆窝处向前转折时形成一锐角，且股环本身较小，周围又多坚韧的韧带，因此股疝容易嵌顿。脐疝（A错）有小儿脐疝和成人脐疝之分，小儿脐疝多属易复性，极少发生嵌顿和绞窄，成人发生嵌顿或绞窄者较多，故应采取手术疗法。腹股沟直疝（B错）常见于年老体弱者，平卧后疝块多能自行消失，不需用手推送复位。腹股沟斜疝（C错）常发生于儿童及青壮年，发生嵌顿性疝机会较多，且临床症状较严重，但并非最常见嵌顿疝。","","N"],["2017-N62",29,"第六节 结肠癌","结肠癌临床表现",2017,62,"A","","下列关于结肠癌正确的是",[["A","胃肠道肿瘤中预后最好"],["B","右侧结肠癌多表现为肠梗阻"],["C","左侧结肠癌多表现为贫血"],["D","早期以血道转移为主"]],"A","结肠癌是胃肠道中常见的恶性肿瘤，治疗原则是以手术切除（结肠癌根治性手术最常见）为主的综合治疗，在胃肠道肿瘤中预后最好（A对）。右侧结肠癌一般以全身症状、贫血、腹部肿块为主要表现（B错），左侧结肠癌一般以肠梗阻、便秘、腹泻、便血等症状为显著（C错）。结肠癌主要经淋巴转移（D错）。","","N"],["2017-N63",32,"第五节 胆道感染","急性结石性胆囊炎手术治疗",2017,63,"A","","男性，65岁。反复上腹部不适、轻度黄疸3个月，腹痛、黄疸加重伴高热2天。入院查体：T39.5℃，P125次/分，BP75/50mmHg，右上腹压痛。腹部超声检查发现胆囊多发结石，胆总管直径1.5cm，胰头显示不清。血WBC15×10⁹/L，中性粒细胞90％。该患者首选的治疗方法是",[["A","大剂量抗生素抗感染后择期手术"],["B","全胃肠外营养后择期手术"],["C","大量输液抗休克同时尽早手术"],["D","应用血管收缩剂至血压正常后及早手术"]],"C","老年男性患者，反复上腹部不适、轻度黄疸3个月（胆囊炎症状），腹痛、黄疸加重伴高热2天（急性发作）。入院查体：T39.5℃，P125次/分（心率加快），BP75/50mmHg（提示休克），右上腹压痛。腹部超声检查发现胆囊多发结石，胆总管直径1.5cm（胆总管增宽，可能结石嵌顿），胰头显示不清（结石嵌顿，胆汁反流入胰管，引起胰腺炎或因肠气遮挡显示不清）。血WBC15×10⁹/L（增高，提示感染），中性粒细胞90%（增高，提示感染）。根据患者病史、体征、检查结果，诊断为急性结石性胆囊炎、急性坏死性胰腺炎可能、急性化脓性梗阻性胆管炎（患者有Reynolds五联征：腹痛、黄疸、高热、休克，但缺乏神经系统临床表现）、感染性休克。该患者病情不稳定，需急诊手术（AB错），同时纠正休克状态，首选的治疗方法是大量输液抗休克同时尽早手术（C对）。休克治疗的关键是补充血容量，血管收缩剂（D错）等血管活性物质在患者充分容量复苏后才应用。","","N"],["2017-N64",29,"第七节 直肠癌","低位前切除术",2017,64,"A","","男性，62岁，脓血便3个月，结肠镜检距肛门处7cm可见直肠肿瘤，直径约2cm，活检示直肠癌，合理的手术方式是",[["A","Hartman术"],["B","Miles术"],["C","Dixon术"],["D","York-Mason术"]],"C","老年男性直肠癌患者，直肠肿瘤距肛门处7cm，患者一般情况尚好，合理的手术方式是Dixon手术（C对）。Dixon手术（经腹腔直肠癌切除术）适用于距齿状线5cm以上的直肠癌患者，该患者直肠癌块下缘距肛门处7cm，距离齿状线应约为5cm以上（齿线距肛缘约1.5～2cm），符合Dixon术。Hartmann手术（A错）适用于因全身一般情况很差，不能耐受Miles手术或急性肠梗阻不宜行Dixon手术的直肠癌病人。Miles手术（B错）适用于肿块下缘距肛缘小于5cm患者，在部分肿瘤大、浸润明显患者，肿块下缘距离肛缘7cm者亦可行Miles手术。York-Mason术（D错）手术操作有一定难度，理论上可能并发肛门扩约肌失禁，目前较少采用。","","N"],["2017-N65",47,"第二节 股骨近端骨折","人工关节置换术",2017,65,"A","","男，80岁，摔倒后致右髋部疼痛2天，平素体健。X线检查见右股骨颈头下型骨折，有移位。最合适的治疗方法是",[["A","皮牵引"],["B","人工股骨头置换术"],["C","切开复位内固定"],["D","卧床休息，穿防旋转鞋"]],"B","老年患者，右股骨颈头下型骨折，有移位，该患者一般情况较好，最合适的治疗方法是人工股骨头置换术（B对）。股骨颈头下型骨折易造成股骨头缺血坏死，高龄病人若发生该型骨折，难以自我恢复，应使用股骨头置换术或全髋关节置换术。皮牵引（A错）和卧床休息，穿防旋转鞋（D错）用于年龄过大，全身情况差等不可耐受手术者。切开复位内固定（C错）用于手法复位失败，或固定不可靠，或青壮年的陈旧骨折不愈合等情况。","","N"],["2017-N66",54,"第一节 化脓性骨髓炎","急性化脓性骨髓炎概述",2017,66,"A","","急性血源性骨髓炎的好发部位是",[["A","桡骨，尺骨"],["B","肱骨，肩胛骨"],["C","骨盆，脊椎"],["D","胫骨，股骨"]],"D","急性血源性骨髓炎以胫骨上段和股骨下段最多见（D对）。急性血源性骨髓炎多继发于身体其他部位的感染性病灶。当机体抵抗力下降或原发灶处理不当，细菌可进入血液发生菌血症或诱发脓毒症。菌栓进入骨营养动脉后，往往受阻于长骨干骺端的毛细血管内并在局部繁殖，引起急性血源性骨髓炎。骺板附近的微小终末动脉与毛细血管往往弯曲形成血管襻，使得该处血流缓慢，细菌容易沉积，成为骨髓炎的好发部位，如胫骨上段和股骨下段。除多见于胫骨和股骨外，肱骨、髂骨、脊柱与其他四肢骨骼（ABC错）都可以发病，肋骨和颅骨少见。","","N"],["2017-N67",53,"第一节 颈椎退行性疾病","颈椎病分型及临床表现",2017,67,"A","","下列关于颈椎病的叙述，不正确的是",[["A","可有心动过速等交感神经表现"],["B","神经根型表现为手部麻木无力"],["C","交感型颈椎病最多见"],["D","骨赘压迫食管可引起吞咽困难"]],"C","颈椎病依据其对脊髓、神经、血管等重要组织的压迫，分为神经根型颈椎病、脊髓型颈椎病、交感神经型颈椎病和椎动脉型颈椎病。神经根型颈椎病发病率最高（C错，为本题正确答案），临床上开始多为颈肩痛，短期内加重，并向上肢放射，皮肤可有麻木、过敏等感觉异常，同时可有上肢无力、手指动作不灵活（B对）。交感神经型颈椎病主要表现为交感神经受刺激的症状，可表现为心动过速等交感神经兴奋症状（A对），也可表现为交感神经抑制症状。另有极少数病人椎体前方有较大而尖锐的骨赘增生，从而压迫食管引起吞咽困难（D对），可归纳为“食管型颈椎病”。","","N"],["2017-N93",24,"第一节 腹部损伤概述","诊断性腹腔穿刺术",2017,93,"A","","女性，55岁。上腹部被汽车撞伤2小时，剧烈腹痛，伴恶心呕吐，神志淡漠。查体：P135次/分，BP75/45mmHg，全腹有压痛、反跳痛及肌紧张，移动性浊音可疑阳性，肠鸣音减弱。首选的诊断方法是",[["A","腹部CT检查"],["B","腹腔穿刺"],["C","腹腔动脉造影"],["D","立位腹平片"]],"B","中年女性，上腹部外伤史，剧烈腹痛，伴恶心呕吐，神志淡漠。查体：P135次/分，BP75/45mmHg（休克表现，提示血容量不足），全腹有压痛、反跳痛及肌紧张（提示腹膜炎），移动性浊音可疑阳性（提示腹腔内积液可能），肠鸣音减弱（提示麻痹性肠梗阻）。综合该患者的病史及体查，诊断考虑肝脾破裂。诊断性腹腔穿刺（B对）阳性率可达90%以上，若抽出不凝血，可提示实质性脏器破裂出血。腹部CT检查（A错）仅适用于病情稳定而又需明确诊断的患者，患者已出现休克征象，不宜行CT检查。腹腔动脉造影（C错）多用于寻找常规手段难以发现的出血点。立位腹平片（D错）若发现膈下新月状低密度影可辅助诊断消化道穿孔，但对于实质性脏器破裂出血缺乏诊断意义。","c111","N"],["2017-N94",24,"第一节 腹部损伤概述","是否存在多发性损伤",2017,94,"A","","女性，55岁。上腹部被汽车撞伤2小时，剧烈腹痛，伴恶心呕吐，神志淡漠。查体：P135次/分，BP75/45mmHg，全腹有压痛、反跳痛及肌紧张，移动性浊音可疑阳性，肠鸣音减弱。最可能的诊断是",[["A","胃穿孔"],["B","小肠破裂"],["C","腹膜后血肿"],["D","肝脾破裂"]],"D","中年女性，上腹部外伤史，剧烈腹痛，伴恶心呕吐，神志淡漠。查体：P135次/分，BP75/45mmHg（休克表现，提示血容量不足），全腹有压痛、反跳痛及肌紧张（提示腹膜炎），移动性浊音可疑阳性（提示腹腔内积液可能），肠鸣音减弱（提示麻痹性肠梗阻）。综合该患者的病史及体查，诊断考虑肝脾破裂（D对）。胃穿孔（A错）及小肠破裂（B错）在腹部闭合性损伤少见，可引起继发性腹膜炎，出现板状腹及腹腔内积液及麻痹性肠梗阻，但早期一般无低血容量休克的表现。腹膜后出血（C错）主要表现为内出血征象、腰背痛和肠麻痹，仅在部分腹膜破损患者可出现腹膜炎表现。","c111","N"],["2017-N95",26,"第三节 胃十二指肠溃疡的外科治疗","胃十二指肠溃疡穿孔检查",2017,95,"A","","男性，25岁，突发上腹剧痛6小时，既往“胃病史”。查体:P110次/分，BP:130/80mmHg，全腹压痛，上腹部为著，板样腹，肠鸣音减弱。实验室检查:Hb120g/L，WBC10.5×10⁹/L。最有价值的检查是",[["A","腹部立位腹平片"],["B","腹部B超"],["C","腹腔穿刺"],["D","腹部CT"]],"A","青年男性患者，既往“胃病史”，突发上腹剧痛6小时（胃病史，突发剧烈腹痛，提示急性胃十二指肠溃疡穿孔）。查体：P110次/分，BP：130/80mmHg，全腹压痛，上腹部为著，板样腹（急性胃十二指溃疡穿孔引起腹膜炎典型体征），肠鸣音减弱。实验室检查：Hb120g/L，WBC10.5×10⁹/L（白细胞稍增高）。综合患者病史、体查及实验室检查，诊断为急性胃十二指溃疡穿孔，最有价值的检查是腹部立位平片（A对）出现膈下游离气体、结合溃疡病史、典型“板状腹”可确立诊断。诊断性腹腔穿刺（C错）发现胃肠内容物可辅助诊断消化性溃疡穿孔。腹部B超（B错）可发现有腹膜炎引起的腹腔内不等量的液体，但不能鉴别其性质。腹部CT（D错）可用于鉴别是否合并急性胰腺炎，不直接用于急性胃十二指溃疡穿孔的诊断。","c112","N"],["2017-N96",26,"第三节 胃十二指肠溃疡的外科治疗","胃十二指肠溃疡穿孔治疗",2017,96,"A","","男性，25岁，突发上腹剧痛6小时，既往“胃病史”。查体:P110次/分，BP:130/80mmHg，全腹压痛，上腹部为著，板样腹，肠鸣音减弱。实验室检查:Hb120g/L，WBC10.5×10⁹/L。最有效的治疗方法",[["A","大量抗生素"],["B","镇静镇痛治疗"],["C","胃肠减压，补液"],["D","手术探查"]],"D","青年男性患者，既往“胃病史”，突发上腹剧痛6小时（提示急性胃十二指肠溃疡穿孔）。查体：P110次/分，BP：130/80mmHg，全腹压痛，上腹部为著，板样腹（腹膜炎典型体征），肠鸣音减弱（提示腹膜炎）。实验室检查：Hb120g/L，WBC10.5×10⁹/L（正常值3.5～9.5×10⁹/L）。综合患者病史、体征及实验室检查，诊断为急性胃十二指溃疡穿孔，消化性溃疡穿孔的最有效治疗措施是手术探查（D对），主要术式为穿孔缝合术。大量抗生素（A错）、镇静镇痛治疗（B错）、胃肠减压，补液（C错）为一般非手术治疗措施，适用于病情较轻或病情超过24小时，且腹部体征已减轻或伴有严重心肺等脏器疾患不能耐受手术者。","c112","N"],["2017-N97",5,"第六节 有芽胞厌氧菌感染","破伤风病因",2017,97,"A","","男性，28岁，足底铁钉刺伤后两天，乏力，张口困难，继之苦笑面容，角弓反张，声响会诱发上述症状，神志清，无发热。引起该患者症状的致病菌为",[["A","大肠埃希菌"],["B","厌氧芽孢杆菌"],["C","产气荚膜杆菌"],["D","变形杆菌"]],"B","患者足底被铁钉刺伤（外伤史）两天后乏力，张口困难，继之苦笑面容，角弓反张（破伤风典型表现），结合病史和临床表现，诊断为破伤风，引起该病的致病菌为破伤风梭菌，属于厌氧芽胞杆菌（B对）。大肠埃希菌（A错）常引起胃肠炎和肠道外感染。产气荚膜杆菌（C错）为气性坏疽和食物中毒的致病菌。变形杆菌（D错）可引起多种感染以及食物中毒。","","N"],["2017-N98",5,"第六节 有芽胞厌氧菌感染","伤口处理",2017,98,"A","","男性，28岁，足底铁钉刺伤后两天，乏力，张口困难，继之苦笑面容，角张反弓，声响了诱发上述症状，神志清，无发热。该伤口处置应用",[["A","高浓度抗生素"],["B","高锰酸钾溶液"],["C","过氧化氢溶液"],["D","生理盐水"]],"C","青年男性，足底铁钉刺伤后两天（深而口小的伤口，易形成局部无氧环境），乏力，张口困难，继之苦笑面容，角弓反张（肌张力异常），声响诱发上述症状，神志清，无发热（破伤风的常见临床表现）。综合该患者的病史及体征，诊断考虑破伤风。破伤风梭菌为专性厌氧菌，过氧化氢（C对）可被血液催化分解为水及氧气，提高局部氧浓度，不利于细菌生长，适宜用于该伤口处置。","","N"],["2017-N99",5,"第六节 有芽胞厌氧菌感染","破伤风治疗",2017,99,"A","","男性，28岁。足底被锈钉刺伤2天，出现乏力，张口困难，继之出现苦笑面容，角弓反张，声响可诱发上述症状，神志清楚，无发热。治疗中不必使用的药物是",[["A","青霉素"],["B","丙种球蛋白"],["C","甲硝唑"],["D","TAT"]],"B","青霉素（A对）和甲硝唑（C对）可抑制破伤风梭菌生长。TAT（破伤风抗毒素）（D对）可中和游离毒素，早期应用可减少毒素与神经组织结合，减轻症状，TAT可能引起超敏反应，目前推荐应用破伤风人体免疫球蛋白。丙种球蛋白（B错，为本题正确答案）用于自身免疫性疾病和感染性疾病的治疗。","","N"],["2017-N100",26,"第三节 胃十二指肠溃疡的外科治疗","胃十二指肠溃疡穿孔诊断",2017,100,"A","","男性，35岁，4小时前吃枣时误服一枚枣核，现感腹痛，无呕吐、无排便。该病人可能发生的最严重的情况是",[["A","幽门梗阻"],["B","消化道穿孔"],["C","消化道黏膜损伤"],["D","回盲瓣梗阻"]],"B","青年男性，误服枣核，现感腹痛，无呕吐、无排便，可能发生的最严重的情况是消化道穿孔（B对）。枣核体积较小，两端尖锐，可损伤消化道黏膜（C错），引起腹痛，一般无严重影响；若戳破消化道管壁，可引起消化道穿孔（B对），引起继发性腹膜炎。枣核体积较小，仅一枚一般不会引起消化道梗阻，因而极少出现幽门梗阻（A错）及回盲瓣梗阻（D错）。","","N"],["2017-N101",26,"第三节 胃十二指肠溃疡的外科治疗","胃十二指肠溃疡穿孔检查",2017,101,"A","","男性，35岁，4小时前吃枣时误服一枚枣核，现感腹痛，无呕吐、无排便。判断有无上述严重后果最简单有效的方法是",[["A","B超"],["B","CT"],["C","腹部物诊检查"],["D","消化道造影"]],"C","青年男性，误服枣核，现感腹痛，无呕吐、无排便，可能发生的最严重的情况是消化道穿孔，消化道穿孔后消化道内容物可漏入腹腔，刺激腹膜，出现严重的腹膜刺激征，出现腹部疼痛、压痛及反跳痛，也可出现肝浊音界消失，判断有无上述严重后果最简单有效的方法是腹部物诊检查（C对），严重者可呈“板状腹”。B 超（A错）及CT（B错）对诊断消化道穿孔意义不大。消化道穿孔时造影剂可漏入腹腔，因而消化道造影（D错）一般不用于诊断消化道穿孔。","","N"],["2017-N102",26,"第三节 胃十二指肠溃疡的外科治疗","胃十二指肠溃疡穿孔治疗",2017,102,"A","","男性，35岁，4小时前吃枣将一枚枣核咽下，现腹痛，无呕吐、排便。经1天观察，腹痛减轻，仍未排便。处理措施是",[["A","开腹探查，取异物"],["B","结肠镜检查"],["C","口服液体石蜡油"],["D","胃镜检查"]],"C","青年男性，误服枣核，现感腹痛，无呕吐、无排便，可能发生的最严重的情况是消化道穿孔，口服液体石蜡油（C对）可润滑肠道，减轻枣核对肠腔黏膜的损伤，并促进肠道蠕动，加快异物排出。开腹探查（A错）、结肠镜检（B错）、胃镜检查（D错）仅用于上述治疗无效，且症状持续不缓解甚至加重的患者。","","N"],["2017-N103",55,"第三节 髋关节结核","髋关节结核诊断",2017,103,"A","","女，28岁，右髋关节疼痛伴肿物3个月，低热、咳嗽1个月。查体：右髋关节呈屈曲畸形，可触及一直径约5cm左右的肿物，屈伸活动受限，Thomas征（+），血沉58mm/h。X线：右髋关节间隙变窄，关节面有虫蚀样骨质破坏，右髋臼有约2cm大小的空洞。最可能的诊断是",[["A","肺癌骨转移"],["B","髋关节骨关节炎"],["C","髋关节化脓性关节炎"],["D","全髋关节结核"]],"D","青年女性，起病缓慢，低热、咳嗽1个月（结核全身中毒症状），右髋关节疼痛伴肿物3个月，右髋关节呈屈曲畸形、活动受限（髋关节结核临床表现），Thomas征（+），血沉58mm/h（女性正常值0～20mm/h，提示有炎症），右髋关节间隙变窄，有虫蚀样骨质破坏和空洞（髋关节结核X线表现），结合上述症状、体征和影像学检查结果，最可能的诊断是全髋关节结核（D对）。","c113","N"],["2017-N104",55,"第三节 髋关节结核","髋关节结核影像学检查",2017,104,"A","","女，28岁，右髋关节疼痛伴肿物3个月，低热、咳嗽1个月。查体：右髋关节呈屈曲畸形，可触及一直径约5cm左右的肿物，屈伸活动受限，Thomas征（+），血沉58mm/h。X线：右髋关节间隙变窄，关节面有虫蚀样骨质破坏，右髋臼有约2cm大小的空洞。下列检查中对确诊最有价值的是",[["A","胸部X线片"],["B","骨扫描"],["C","髋部B超"],["D","髋部MRI"]],"D","青年女性，起病缓慢，低热、咳嗽1个月（结核全身中毒症状），右髋关节疼痛伴肿物3个月，右髋关节呈屈曲畸形、活动受限（髋关节结核临床表现），Thomas征（+），血沉58mm/h（女性正常值0～20mm/h，提示有炎症），右髋关节间隙变窄，有虫蚀样骨质破坏和空洞（髋关节结核X线表现），结合上述症状、体征和影像学检查结果，最可能的诊断是全髋关节结核。对确诊最有价值的检查是髋部MRI（D对）。MRI能更好地显示髋关节积液、微小骨破坏及浸润灶。胸部X线片（A错）主要用于呼吸系统相关疾病的诊断。骨扫描（B错）多用于诊断早期骨转移肿瘤。髋部B超（C错）对诊断关节内积液有一定价值，不用于髋关节结核诊断。","c113","N"],["2017-N105",55,"第三节 髋关节结核","髋关节结核手术治疗",2017,105,"A","","女，28岁，右髋关节疼痛伴肿物3个月，低热、咳嗽1个月。查体：右髋关节呈屈曲畸形，可触及一直径约5cm左右的肿物，屈伸活动受限，Thomas征（+），血沉58mm/h。X线：右髋关节间隙变窄，关节面有虫蚀样骨质破坏，右髋臼有约2cm大小的空洞。住院治疗4周后，患者精神状况和食欲改善，复查血沉20mm/h，但是肿物没有消失，进一步治疗方案为",[["A","肿物切除术"],["B","髋人形石膏固定"],["C","人工关节置换术"],["D","病灶清除术"]],"D","青年女性，起病缓慢，低热、咳嗽1个月（结核全身中毒症状），右髋关节疼痛伴肿物3个月，右髋关节呈屈曲畸形、活动受限（髋关节结核临床表现），Thomas征（+），血沉58mm/h（女性正常值0～20mm/h，提示有炎症），右髋关节间隙变窄，有虫蚀样骨质破坏和空洞（髋关节结核X线表现），结合上述症状、体征和影像学检查结果，最可能的诊断是全髋关节结核。在行4周内科治疗后，患者一般情况较好，进一步治疗方案为病灶清除术（D对）。肿物切除术（A错）多用于体温高，中毒症状明显和全身状况不好不能耐受病灶清除术的患者。髋人形石膏固定（B错）用于稳定关节，减轻疼痛和矫正畸形。人工关节置换术（C错）在患者结核病灶已完全控制后，为了恢复关节功能可选择，但有诱发结核病灶活动的风险。","c113","N"],["2017-N106",54,"第一节 化脓性骨髓炎","急性化脓性骨髓炎诊断依据",2017,106,"A","","10岁男孩，左大腿下段疼痛伴高热40℃1天，怀疑为急性化脓性骨髓炎。体格检查有力证据是",[["A","左股骨下端皮温升高"],["B","左股骨下端肿胀"],["C","左股骨下端（干骨骺）深压痛"],["D","左膝关节伸屈受限"]],"C","急性化脓性骨髓炎主要表现为全身中毒症状，寒战、高热、呕吐，呈脓毒症样发作，长骨干骺端疼痛剧烈而不愿活动肢体，局部深压痛（C对）。左股骨下端皮温升高（A错），左股骨下端肿胀（B错），左膝关节伸屈受限（D错）均为急性化脓性骨髓炎的一般表现，缺乏特异性，不作为体格检查有力证据。","","N"],["2017-N107",54,"第一节 化脓性骨髓炎","急性化脓性骨髓炎局部分层穿刺",2017,107,"A","","10岁男孩，左大腿下段疼痛伴高热40℃1天，怀疑为急性化脓性骨髓炎。下列有诊断意义的辅助检查是",[["A","血培养"],["B","血常规"],["C","X线检查"],["D","局部穿刺"]],"D","疑诊为急性骨髓炎患者，可选用有内芯的穿刺针，在压痛最明显的干骺端刺入，边吸边深入，不要一次穿入骨内，以免将单纯软组织脓肿的细菌带入骨内，抽出浑浊液体或血性液可作涂片检查与细菌培养，涂片中发现多是脓细胞或细菌即可明确诊断，故局部穿刺（D对）是急性骨髓炎有诊断意义的辅助检查。急性骨髓炎的致病菌系经过血源性播散，虽血培养（A错）可获致病菌、血常规（B错）可示白细胞计数增高，但两者特异性差，可见于其他感染。急性骨髓炎起病后的14天内的X线检查往往无异常发现，该患者起病1天，X线检查（C错）对早期诊断意义不大。","","N"],["2017-N132",17,"第一节 甲状腺疾病","抗甲状腺药物加碘剂",2017,132,"B","","能使甲亢患者甲状腺体积缩小，质地变硬的药物是",[["A","丙硫氧嘧啶"],["B","复方碘溶液"],["C","普萘洛尔"],["D","醋酸泼尼松"]],"B","能使甲亢患者甲状腺体积缩小，质地变硬的药物是复方碘溶液（B对），它可减少甲状腺的血流量，为甲状腺切除术的术前药物准备。丙硫氧嘧啶（A错）属于硫脲类抗甲状腺药物，此类药物能使甲亢患者甲状腺体积增大，充血。普萘洛尔（C错）和醋酸泼尼松（D错）对甲状腺体积无明显影响。","","N"],["2017-N133",17,"第一节 甲状腺疾病","单用抗甲状腺药物",2017,133,"B","","能使甲亢患者甲状腺体积增大，充血的药物是",[["A","丙硫氧嘧啶"],["B","复方碘溶液"],["C","普萘洛尔"],["D","醋酸泼尼松"]],"A","能使甲亢患者甲状腺体积增大，充血的药物是丙硫氧嘧啶（A对）。复方碘溶液（B错）能通过减少甲状腺血流量而使甲亢患者甲状腺体积缩小，质地变硬。普萘洛尔（C错）和醋酸泼尼松（D错）对甲状腺体积无明显影响。","","N"],["2017-N134",39,"","",2017,134,"B","","膀胱结核的血尿特点",[["A","无痛性全程肉眼血尿"],["B","终末血尿伴膀胱刺激征"],["C","初始血尿"],["D","疼痛伴血尿"]],"B","膀胱结核的血尿特点为终末血尿伴膀胱刺激征（B对），多由结核性膀胱炎及溃疡引起。无痛性全程肉眼血尿（A错）为膀胱癌血尿的典型特点。初始血尿（C错）常见于前尿道损伤。疼痛伴血尿（D错）大多与膀胱炎或尿石症有关。","","N"],["2017-N135",42,"第二节 尿路上皮肿瘤","膀胱肿瘤临床表现",2017,135,"B","","膀胱癌血尿的典型特点",[["A","无痛性全程肉眼血尿"],["B","终末血尿伴膀胱刺激征"],["C","初始血尿"],["D","疼痛伴血尿"]],"A","膀胱癌血尿的典型特点为无痛性全程肉眼血尿（A对）。血尿是膀胱癌最常见和最早出现的症状，约85%的病人表现为间歇性肉眼血尿，且早期无痛，易忽略。尿频、尿急、尿痛为膀胱肿瘤的晚期常见表现。终末血尿伴膀胱刺激征（B错）为膀胱结核的血尿特点。初始血尿（C错）常见于前尿道损伤。疼痛伴血尿（D错）大多与膀胱炎或尿石症有关。","","N"],["2017-N160",33,"第四节 胰腺癌和壶腹周围癌","胰腺癌概述",2017,160,"X","","下列有关胰腺导管腺癌的叙述，正确的有",[["A","5年总体生存率低于10%"],["B","长春新碱是其首选化疗药物"],["C","放射治疗敏感"],["D","CA19-9是其主要血清标记物"]],"AD","胰腺癌恶性程度很高，不易早期发现，切除率低和预后差为本病的特点，即使在可切除患者中，5年生存率亦不到5%（A对）。多数胰腺癌可出现多种血清学标记物升高，包括CA19-9、CA24-2、CA50、CEA等，其中以CA19-9的阳性率较高，最常作为胰腺癌的辅助诊断和术后随访的指标，可视为胰腺导管腺癌的主要血清标记物（D对）。胰腺导管腺癌术中放射治疗可用于杀死残留的肿瘤细胞，防止复发，提高手术疗效，体外放射治疗可以用于术前或术后，尤其是对不能切除的胰体尾部癌，经照射后可缓解顽固性疼痛（实用外科学P766），胰腺导管腺癌对放疗不太敏感，但放疗可使30%～50%患者腹痛和背痛得到缓解，并在一定程度上抑制肿瘤的发展（实用内科学P2065），也有主张以放射治疗为基本疗法的综合性治疗，本题C选项有争议。以前应用最多的化疗药物是氟尿嘧啶，近年来吉西他滨是胰腺导管腺癌首选化疗药物（B错）。","","N"],["2017-N161",24,"第二节 常见内脏损伤的特征和处理","脾损伤处理",2017,161,"X","","下列关于脾破裂处理措施中，正确的有",[["A","先纠正失血性休克再手术"],["B","轻度脾破裂可行脾修补"],["C","外伤性脾破裂可行自体血回输"],["D","儿童切脾后可行自体脾片移植"]],"BCD","轻度脾破裂时，出血量不大，可行单纯脾修补（B对）。腹腔为无菌环境，当外伤性脾破裂为闭合性损伤时，脾破裂所出的血无污染，可行自体血回输（C对）。儿童对感染的抵抗力弱，切脾后可发生以肺炎球菌为主要病原菌的脾切除后凶险性感染（OPSI），故可行自体脾片移植防止日后发生OPSI（D对）。脾破裂出现失血性休克时提示出血量很大，且往往为进行性出血，单纯纠正失血性休克不能控制病情，应采取边纠正失血性休克边准备手术（A错）。","","N"],["2017-N162",26,"第二节 胃癌及其他胃肿瘤","胃肠道间质瘤诊断",2017,162,"X","","下面关于胃肠间质瘤的描述正确的是",[["A","肿瘤组织免疫组化检测CD117（+）"],["B","核分裂数与肿瘤预后相关"],["C","肿瘤长径与肿瘤预后相关"],["D","来源于胃肠道平滑肌组织"]],"ABC","胃肠间质瘤是消化道最常见的间叶源性肿瘤，来源于间质细胞（D错）。肿瘤组织免疫组化检测CD117（+）（A对）和CD34过表达。肿瘤预后与肿瘤部位、大小（C对）、细胞有丝分裂指数（核分裂象）（B对）、肿瘤浸润深度和有无转移相关。","","N"],["2017-N163",33,"第二节 胰腺炎","手术适应证",2017,163,"X","","急性胰腺炎手术适应证为",[["A","膀胱测压22mmHg"],["B","合并胆道梗阻"],["C","保守治疗后，病情急剧恶化"],["D","脓肿形成"]],"BCD","膀胱测压可反映腹腔内压力。急性胰腺炎可导致腹内压升高，严重者可出现腹腔间隔室综合征（十版外科学P488），若非手术治疗无效，腹内压持续＞25mmHg且威胁生命时，应施行腹腔切开术。因此，膀胱测压22mmHg不是手术指征（A错）。合并胆道梗阻（B对）是急性胰腺炎手术指征，手术目的是解除胆道梗阻，通畅引流，减少或消除胆汁反流，消除急性胰腺炎诱因。保守治疗后，病情急剧恶化（C对）是急性胰腺炎手术适应证，最常用的是坏死组织清除术加引流术，可减少炎症因子的吸收，一定程度减轻全身炎症反应综合征（SIRS）及继发性感染的发生率。脓肿多由胰腺和胰周组织坏死继发感染引起，基本措施是坏死组织清除加局部灌洗引流（D对）。","","N"],["2017-N164",44,"第二节 骨折的临床表现及影像学检查","骨折的特有体征",2017,164,"X","","骨折的特有体征有",[["A","局部压痛"],["B","成角畸形"],["C","骨擦音"],["D","局部肿胀"]],"BC","骨折的特有体征为畸形（B对）、异常活动和骨擦音（C对）或骨擦感。局部压痛（A错）、局部肿胀（D错）为骨折的一般表现。","","N"],["2017-N165",51,"第五节 与慢性损伤相关的其他疾病","粘连性肩关节囊炎治疗",2017,165,"X","","关于肩周炎的治疗，可以采用的措施有",[["A","临床观察"],["B","物理治疗"],["C","三角巾悬吊固定"],["D","关节镜松解术"]],"ABD","肩周炎为自限性疾病，对于症状轻微的患者，可临床观察（A对），不需特殊治疗。肩周炎的治疗目的是缓解疼痛，恢复功能，避免肌肉萎缩。物理治疗（B对）、局部封闭治疗、短期服用非甾体抗炎药物、主动地肩关节活动（C错）等均可缓解症状。症状重者可采用手法或关节镜下松解粘连治疗（D对）。对于肩外因素所致的肩周炎还需对原发病进行治疗。","","N"],["2018-N57",4,"第一节 外科病人的代谢变化","创伤应激状态下机体代谢变化",2018,57,"A","","关于机体在应激状态下代谢变化的叙述，错误的是",[["A","代谢率增高"],["B","脂肪动员加速"],["C","蛋白质分解加速"],["D","葡萄糖的储存增加"]],"D","机体在应激状态下，体内促进分解代谢，其特征为静息能量消耗增高，代谢率增加（A对），高代谢状态是机体严重创伤应激后的代谢特点。儿茶酚胺、糖皮质激素、促生长激素、胰高血糖素等促进分解代谢的激素释放增多，胰岛素的分泌量减少或正常，导致糖原分解和糖异生均增加，同时体内出现胰岛素抵抗（儿茶酚胺抑制胰岛β细胞以及肾清除率增加等因素），可出现葡萄糖的储存受抑制，出现高血糖（D错，为本题正确答案）。应激状态下蛋白质代谢变化是蛋白质分解加速（C对）、负氮平衡。应激状态下，由于肾上腺素、去甲肾上腺素、胰高血糖素等激素的分泌增多，体内脂肪动员加速（B对），脂肪分解增强。以上代谢改变的目的均是为了保持机体内环境稳定。","","N"],["2018-N58",9,"第二节 移植免疫","超急性排斥反应",2018,58,"A","","因受者体内存在针对供者特异性抗原的预存抗体所引起的排斥反应是",[["A","超急性排斥反应"],["B","加速性排斥反应"],["C","急性排斥反应"],["D","慢性排斥反应"]],"A","因受体体内存在针对供者特异性抗原的预存抗体所引起的排斥反应是超急性排斥反应（A对），表现为移植物再灌注后数分钟或数小时内，预存抗体迅速与移植物内皮细胞结合，激活补体和凝血反应，导致溶解反应，移植物微血管系统广泛微血栓形成。加速性排斥反应（B错）又称血管排斥反应，通常是由于受体体内预存抗供体低浓度抗体所致。急性排斥反应（C错），细胞免疫及体液免疫均发挥重要作用。慢性排斥反应（D错）其发生机制尚不完全清楚，主要为免疫因素如急性排斥反应反复发作，多种非免疫因素促进慢性排斥反应进展共同导致慢性移植物失功。","","N"],["2018-N59",1,"第三节 钾代谢紊乱","高钾血症治疗",2018,59,"A","","男性，35岁。5小时前重物砸伤双大腿，急诊查血钾6.1mmol/L，心率50次/分，律不齐。应首先静脉注射的药物是",[["A","25%葡萄糖100ml + 6U胰岛素"],["B","10%葡萄糖酸钙20ml"],["C","11.2%乳酸钠50ml"],["D","5%碳酸氢钠100ml"]],"B","35岁男性患者，有外伤史（高血钾诱因），血钾6.1mmol/L（正常值为3.5～5.3mmol/L），心率50次/分（正常人心率60～100/分），心率50次/分，出现心率不齐（高血钾干扰心肌正常的电生理活动），应首选的静脉注射药物是10%葡萄糖酸钙20ml（B对）可拮抗钾离子对心肌细胞的毒性作用，对抗心律失常。25%葡萄糖100ml+6U胰岛素（A错）可通过细胞膜上葡萄糖-钾共体将钾泵入细胞内，降低血钾浓度；11.2%乳酸钠50ml（C错）、5%碳酸氢钠100ml（D错）可增加血容量，稀释血钾浓度，同时又能使钾离子转移入细胞内或经尿液排出，从而降低血钾浓度，此三种方法均可用于高血钾治疗，但起效较缓慢，无法立即对抗钾离子的心肌毒性作用，纠正心律失常。","","N"],["2018-N60",42,"第一节 肾肿瘤","肾细胞癌诊断",2018,60,"A","","男性，65岁。3个月前有3次无痛性血尿，近来出现腰痛及尿频、尿痛、血尿和排尿困难，有时尿有血块。最可能的诊断是",[["A","前列腺癌"],["B","膀胱肿瘤"],["C","膀胱结石"],["D","肾癌"]],"D","65岁老年男性（肾癌高发人群），3个月前有3次无痛性肉眼血尿（间歇性、无痛性肉眼血尿），近来出现腰痛、尿频、尿痛、血尿和排尿困难（血尿、肾区疼痛），有时尿血块，最可能的诊断是肾癌（D），肾癌症状多变，早期诊断困难，血尿、疼痛和肿块是肾癌的主要症状，其中任何一个症状出现都应该引起重视，想到肾癌的可能性，其临床诊断主要依靠影像学检查。膀胱肿瘤（B）最常见的症状是间断全程无痛性肉眼血尿，对长期不能治愈的“膀胱炎”应警惕有膀胱癌的可能性，膀胱刺激征多为晚期表现，常因肿瘤坏死、溃疡或并发感染所致，需要注意的是，对出现不明原因无痛血尿的中老年人，肾癌和膀胱肿瘤都是应高度怀疑的疾病，该题答案存在争议，若考虑为膀胱癌，腰痛为肾积水所致，尿频、尿痛为肿瘤坏死、感染所致也不无道理，该题参考答案为D选项。前列腺癌（十版外科学P574）（A错）多数无明显症状，可表现为下尿路梗阻症状，如尿频、尿急、尿流缓慢，但血尿少见，常在体检时直肠指检或检查血清PSA值升高被发现，也可在前列腺增生手术标本中发现。膀胱结石（十版外科学P563）（C错）典型表现为排尿突然中断，随体位改变而恢复，伴排尿困难和膀胱刺激症状。","","N"],["2018-N61",19,"第二节 肋骨骨折","肋骨骨折临床表现",2018,61,"A","","出现反常呼吸运动的胸部损伤是",[["A","闭合性气胸"],["B","张力性气胸"],["C","多根多处肋骨骨折"],["D","开放性气胸"]],"C","出现胸部反常运动的胸部损伤是多根多处肋骨骨折（C对），多根多处肋骨骨折胸壁可见畸形，局部压痛明显，反常呼吸为胸壁失去完整肋骨支撑而软化所致，吸气时软化区胸壁内陷，呼气时外突。开放性气胸（D错）呼吸自由进出胸膜腔，典型表现为纵隔扑动，气管在吸气时移向健侧，呼气时移向伤侧。闭合性气胸（A错）伤侧胸内压增加可引起纵隔向健侧移位。张力性气胸（B错）伤侧肺严重萎陷，纵隔显著向健侧移位，易形成纵隔气肿或皮下气肿。","","N"],["2018-N62",32,"第四节 胆石症","胆总管切开取石、T管引流术",2018,62,"A","","男性，65岁。患胆总管结石，手术切开胆总管探查、取石，并放置T管引流。术后T管造影发现仍有0.5cm残余结石。可经T管瘘管取出残余结石的最短时间是",[["A","术后2周"],["B","术后4周"],["C","术后6周"],["D","术后8周"]],"B","患者老年男性，胆囊切除术、胆总管探查术后。T 管引流造影显示残余结石，经T管瘘管取出残余结石的最短时间是为术后4 周（B对），待纤维窦道形成后行纤维胆道镜检查和取石。有关T 管引流术相关内容，十版外科学有数据更新，术后造影发现结石遗留，新版数据为应在手术4～8 周（八版外科学为6周）待纤维窦道形成再施行胆道镜检查和取石，根据最新版数据，本题应选B，原答案为C。","","N"],["2018-N63",24,"第二节 常见内脏损伤的特征和处理","十二指肠损伤诊断",2018,63,"A","","男性，30岁。上腹部钝器伤3小时来院，曾呕吐少量鲜血，诉上腹及腰部疼痛。查体上腹压痛，轻度肌紧张，肠鸣音弱。腹部平片见右肾及腰大肌轮廓模糊。最可能的诊断是",[["A","胃破裂"],["B","十二指肠破裂"],["C","脾脏破裂"],["D","空肠破裂"]],"B","患者青年男性，上腹部钝器伤3小时来院（腹部闭合伤），曾呕吐少量鲜血（提示消化道出血），诉上腹及腰部不适。查体上腹压痛，轻度肌紧张，肠鸣音弱（提示腹腔炎症）。腹部平片见右肾及腰大肌轮廓模糊（提示腹膜后气体形成）。综合患者临床表现及体征，考虑诊断为腹膜后位十二指肠破裂（B对）。胃破裂（A错）表现为肝浊音界消失，膈下游离气体形成。脾破裂（C错）根据出血量不同表现不同。出血量大而速度快时早期出现低血容量性休克；出血量少而慢者除左上腹痛外无其他明显体征。患者血红蛋白、红细胞进行性降低提示内出血。空肠破裂（D错）可在早期即产生明显腹膜炎，随着时间推移可出现腹痛、腹胀，仅少数人存在气腹。","","N"],["2018-N64",17,"第一节 甲状腺疾病","喉上神经损伤",2018,64,"A","","女性，35岁。甲状腺乳头状癌根治手术后第一天，发现饮水时有呛咳，说话音调降低。最可能的原因是",[["A","喉返神经损伤"],["B","喉上神经损伤"],["C","声带损伤"],["D","插管致声门水肿"]],"B","患者甲状腺乳头状癌手术术后出现饮水呛咳，音调降低最可能的原因是喉上神经损伤（B对），喉上神经内支支配喉部黏膜感觉，若损伤可致饮水呛咳，喉上神经外支支配环甲肌，损伤可致环甲肌瘫痪，引起声带松弛、音调降低。单侧喉返神经损伤（A错）可引起声嘶，双侧喉返神经损伤可导致失声或严重的呼吸困难，甚至窒息。声带损伤（C错）可导致声嘶及说话时咽喉部疼痛，插管致声门水肿（D错）可堵塞气道，引起呼吸困难甚至窒息，均不会出现饮水呛咳及音调降低。","","N"],["2018-N65",54,"第二节 化脓性关节炎","化脓性关节炎实验室检查",2018,65,"A","","关于化脓性关节炎的叙述，正确的是",[["A","关节液外观可为透明或浑浊黄白色"],["B","关节液培养最常见白色葡萄球菌"],["C","关节液镜检见多量革兰阴性细菌"],["D","多见于老年女性，可早期关节腔注射抗生素"]],"A","化脓性关节炎为关节内化脓性感染，关节液外观可呈透明或浑浊黄白色（A对），清亮关节液为浆液性渗出，浑浊关节液为纤维蛋白性渗出，黄白色关节液为脓性渗出。化脓性关节炎关节液培养多为金黄色葡萄球菌（B错），可占85%左右，其次为白色葡萄球菌、淋病奈瑟菌、肺炎球菌等（C错）。化脓性关节炎多见于儿童（D错），早期可每天作关节腔穿刺抽液，并注入抗生素。","","N"],["2018-N66",47,"第六节 膝关节韧带损伤","抽屉试验",2018,66,"A","","下列膝关节检查结果与疾病的关系，错误的是",[["A","浮髌试验（+）：膝关节积液"],["B","前抽屉试验（+）：后交叉韧带断裂"],["C","研磨试验（+）：半月板损伤"],["D","麦氏试验（+）：半月板损伤"]],"B","前抽屉试验（+）提示前交叉韧带断裂（B错，为本题正确答案），后抽屉试验（+）提示后交叉韧带断裂。浮髌实验（+）提示膝关节积液（A对）。研磨试验（+）提示半月板损伤（C对）。麦氏试验（+）提示半月板损伤（D对）。","","N"],["2018-N67",53,"第二节 腰椎退行性疾病","腰椎侧凸",2018,67,"A","","腰椎间盘突出如髓核突出在神经根的外侧时，减轻疼痛的姿势性代偿变位是",[["A","腰椎凸向健侧"],["B","腰椎凸向患侧"],["C","腰椎无侧凸变化"],["D","腰椎前凸消失"]],"B","腰椎间盘突出病人髓核突出于神经根外侧时，腰椎凸向患侧（B对C错）可减少髓核对神经根的压迫，减轻疼痛。腰椎凸向健侧（A错）可见于髓核突出于神经根内侧。腰椎前凸消失（D错）见于脊柱结核。","","N"],["2018-N93",17,"第一节 甲状腺疾病","甲状腺功能亢进概述",2018,93,"A","","女性，40岁。发现甲状腺结节10年，近年来易出汗、心悸，渐感呼吸困难。查体：脉搏104次/分，血压130/70mmHg；无突眼，甲状腺Ⅲ度肿大，结节状。心电图示：窦性心律不齐。最可能的诊断是",[["A","原发性甲亢"],["B","单纯性甲状腺肿"],["C","继发性甲亢"],["D","桥本甲状腺炎"]],"C","中年女性患者，甲状腺结节10年（结节性甲状腺肿表现），近年来易出汗、心悸，渐感呼吸困难（基础代谢率增高，机体产热及耗氧量增加），脉搏104次/分（脉率快），窦性心律不齐（心肌兴奋性提高，异常起搏，导致心律不齐），血压130/70mmHg（脉压增大）等甲状腺功能亢进症状，综合患者病史、体征等表现，诊断考虑结节性甲状腺肿继发性甲亢（C对）。原发性甲亢（A错），即Graves病，多表现为甲状腺弥漫性肿大，一般无甲状腺结节。单纯性甲状腺肿（B错）亦表现为甲状腺弥漫性肿大，一般无甲亢表现。桥本甲状腺炎（D错）多为无痛性弥漫性甲状腺肿，对称，质硬，表面光滑，多伴甲状腺功能减退。","c122","N"],["2018-N94",17,"第一节 甲状腺疾病","血清TSH、T₃及T₄测定",2018,94,"A","","女性，40岁。发现甲状腺结节10年，近年来易出汗、心悸，渐感呼吸困难。查体：脉搏104次/分，血压130/70mmHg；无突眼，甲状腺Ⅲ度肿大，结节状。心电图示：窦性心律不齐。确诊的主要根据是",[["A","颈部CT"],["B","血清T3、T4、TSH值"],["C","甲状腺B超"],["D","颈部MRI"]],"B","中年女性患者，甲状腺结节10年（结节性甲状腺肿表现），近年来易出汗、心悸，渐感呼吸困难（基础代谢率增高，机体产热及耗氧量增加），脉搏104次/分（脉率快），窦性心律不齐（心肌兴奋性提高，异常起搏，导致心律不齐），血压130/70mmHg（脉压增大）等甲状腺功能亢进症状，综合患者病史、体征等表现，诊断考虑结节性甲状腺肿继发性甲亢，对诊断有肯定价值的是血清中T₃、T₄、TSH的含量，是确诊的主要依据。甲亢的诊断的依据是甲状腺功能状态，测定方法为测定基础代谢率、甲状腺吸收¹³¹I吸收率以及血清中T₃、T₄、TSH的含量。颈部CT（A错）、甲状腺B超（C错）、颈部MRI（D错）均为甲状腺影像学形态检查，不能反映甲状腺功能。","c122","N"],["2018-N95",17,"第一节 甲状腺疾病","甲状腺功能亢进手术治疗",2018,95,"A","","女性，40岁。发现甲状腺结节10年，近年来易出汗、心悸，渐感呼吸困难。查体：脉搏104次/分，血压130/70mmHg；无突眼，甲状腺Ⅲ度肿大，结节状。心电图示：窦性心律不齐。首选的根治性治疗方法是",[["A","抗甲状腺药物治疗"],["B","甲状腺大部切除术"],["C","甲状腺全切术"],["D","同位素治疗"]],"B","中年女性患者，甲状腺结节10年（结节性甲状腺肿表现），出现易出汗心悸呼吸困难（基础代谢率增高，机体产热及耗氧量增加），心率104次/分（心率快），心律不齐，血压130/70mmHg（脉压增大）等甲状腺功能亢进症状，综合患者病史、体征等表现，诊断考虑结节性甲状腺肿继发甲亢，首选治疗为甲状腺大部分切除术（B对），通常需切除腺体的80%～90%，并同时切除峡部。抗甲状腺药物治疗（A错）是甲状腺功能亢进的首选治疗方案，但不适用于结节性甲状腺肿合并甲亢。甲状腺全切术（C错）一般用于治疗部分甲状腺癌，如颈部存在放射史、已有远处转移等情况者。同位素治疗（D错）为欧美国家甲状腺功能亢进者首选，亦可用于甲状腺癌根治术后全身辅助治疗。","c122","N"],["2018-N96",30,"第四节 原发性肝恶性肿瘤","介入治疗",2018,96,"A","","男性，55岁。有乙肝病史15年，近日CT发现右肝直径8cm 肿物，靠近第一肝门，肝功能Child分级为C级，AFP 890 ng/ml，考虑为肝癌。最佳治疗方案是",[["A","局部无水酒精注射"],["B","局部放射治疗"],["C","选择性肝动脉栓塞"],["D","全身化疗"]],"C","55岁中年男性患者，乙肝病史15年（肝癌诱因），CT示肝直径8cm肿物（大肝癌），靠近第一肝门，Child分级C级（肝功能差），AFP890ng/ml（≥400ng/ml），考虑诊断为肝癌，根据患者癌肿的大小（肿瘤大）及肝功能情况（肝功能差），不宜做一期切除，最佳的治疗方案是选择性肝动脉栓塞（C对），可减少肿瘤组织的血供，导致肿瘤细胞营养供给不足，增长变慢甚至坏死，具有靶向性好、创伤小、可重复的特点，部分患者经此方法治疗后肿瘤缩小，可获得手术切除机会（二期切除）。局部无水酒精注射（A错）多在US或CT引导下，将无水酒精直接注入肝癌组织内，使癌细胞脱水、变性、坏死，适用于肿瘤＜3cm者，可达到治疗性切除的目的。肝癌对化疗和放疗不敏感，故不考虑局部放射治疗（B错）及全身化疗（D错）。","c123","N"],["2018-N97",30,"第四节 原发性肝恶性肿瘤","肝切除",2018,97,"A","","男性，55岁。有乙肝病史15年，近日CT发现右肝直径8cm 肿物，靠近第一肝门，肝功能Child分级为C级，AFP 890 ng/ml，考虑为肝癌。经治疗3个月后，肿瘤缩小至5×6cm，肝功能改善，无远处转移。此时的治疗方案是",[["A","手术切除"],["B","射频消融治疗"],["C","介入治疗"],["D","化疗"]],"A","55岁中年男性患者，原发性肝癌，局限于一叶内，经治疗后肝功能好转，且无远处转移灶，首选治疗为二期切除——手术治疗（A对），手术治疗是治疗肝癌最有效的方法，一旦肿瘤经过综合治疗缩小，应尽可能争取二期切除，可显著延长患者生存期。介入治疗（C错）分为放射介入治疗和超声介入治疗两大类，前者主要是指经导管动脉化疗栓塞（TACE），适用于肿瘤巨大或多发不能行一期手术切除者；超声介入治疗包括经皮无水酒精注射等消融治疗（B错），适用于不宜手术或不需要手术患者，亦可用于术中及术后，用于治疗转移、复发瘤。化疗（D错）在治疗肝癌已有多年历史，主要用于全身情况和肝功能良好的患者，一般宜选择弥漫性肝癌，以及配合手术治疗进行综合治疗，对合并明显肝功能损害或全身情况极度衰竭的患者，化疗有害无益，对巨大的肝癌化疗效果差。","c123","N"],["2018-N98",33,"第二节 胰腺炎","急性胰腺炎非手术治疗",2018,98,"A","","男性，39岁。饱餐饮酒后出现上腹部持续性疼痛伴恶心呕吐6小时入院。查体：T 37℃，P110次/分，BP136/86mmHg，腹部平坦，中上腹有压痛，轻度肌紧张，肠鸣音正常。化验血WBC 12×10⁹/L，N 78%，血清淀粉酶2130U/dL。拟诊急性胰腺炎。入院后的腹部增强CT检查提示：胰腺增大，密度不均，边界模糊，胰周有中等量渗出液，胰腺体尾部片状低密度、强化不均匀。首选的治疗方式是",[["A","手术清除坏死组织并引流"],["B","穿刺置管引流积液"],["C","胰腺体尾部切除术"],["D","全身支持保守治疗"]],"D","中年男性，饱餐饮酒后（胰腺炎常见诱因）出现上腹部持续性疼痛伴恶心呕吐6小时入院（胰腺炎常见临床症状），查体：中上腹有压痛，轻度肌紧张（腹膜刺激征），肠鸣音正常。化验血WBC12×10⁹/L（成人正常值3.5～9.5×10⁹/L），N78%（正常值50%～70%）（白细胞计数增加，中性粒细胞比例增加，提示感染可能），血清淀粉酶2130U/dL（正常值40～180U/dL），腹部增强CT提示胰腺增大，密度不均，边界模糊，胰腺周围轻度渗出，胰体尾部低密度斑块影（胰腺炎典型影像学表现），考虑该患者诊断为急性胰腺炎，根据患者的实际情况，首选治疗方法为保守对症支持治疗（D对），包括禁食、胃肠减压、补液、防治休克、镇痛解痉、抑制胰腺分泌等。手术清除坏死组织加引流（A错）多用于治疗胰腺和胰周坏死组织继发感染，术后常规须置管引流渗出液（B错）。胰腺体尾切除术（C错）用于治疗胰体尾部占位性病变或胰体尾部外伤。","c124","N"],["2018-N99",33,"第二节 胰腺炎","其他项目",2018,99,"A","","男性，39岁。饱餐饮酒后出现上腹部持续性疼痛伴恶心呕吐6小时入院。查体：T 37℃，P110次/分，BP136/86mmHg，腹部平坦，中上腹有压痛，轻度肌紧张，肠鸣音正常。化验血WBC 12×10⁹/L，N 78%，血清淀粉酶2130U/dL。拟诊急性胰腺炎。对判断患者的预后最有价值的化验结果是",[["A","血清淀粉酶升高3倍以上"],["B","血清钙降至2.0mmol/L以下"],["C","早期血糖升高"],["D","血清脂肪酶升高"]],"B","中年男性，饱餐饮酒后（胰腺炎常见诱因）出现上腹部持续性疼痛伴恶心呕吐6小时入院（胰腺炎常见临床症状），查体：中上腹有压痛，轻度肌紧张（腹膜刺激征），肠鸣音正常。化验血WBC12×10⁹/L（成人正常值3.5～9.5×10⁹/L），N78%（正常值50%～70%）（白细胞计数增加，中性粒细胞比例增加，提示感染可能），血清淀粉酶2130U/dL（正常值40～180U/dL），腹部增强CT提示胰腺增大，密度不均，边界模糊，胰腺周围轻度渗出，胰体尾部低密度斑块影（胰腺炎典型影像学表现），考虑该患者诊断为急性胰腺炎，由于急性坏死性胰腺炎周围组织脂肪坏死和脂肪内钙皂形成消耗了钙，所以血钙水平的降低也侧面代表了胰腺坏死的程度，血钙降低往往发生在发病后2～3天后，如果血钙水平明显降低，持续低于2.0mmol/L以下（B对），常预示病情严重（八版黄家驷外科学P1634）。血尿淀粉酶、血清脂肪酶升高的幅度和病变的严重程度不呈正相关（AD错）。早期血糖升高，为肾上腺皮质的应激反应，一般为轻度升高，后期若在长期禁食状态下仍然超过11mmol/L，则反映胰腺广泛坏死，预后不良（C错）。","c124","N"],["2018-N100",32,"第四节 胆石症","胆总管切开取石、T管引流术",2018,100,"A","","女性，55岁。1月前因急性胆管炎、胆囊炎、胆总管结石急诊行胆囊切除、胆总管切开取石、T管引流术。一般拔除T管的时间是",[["A","术后2周"],["B","术后4周"],["C","术后6周"],["D","术后8周"]],"B","开放性胆总管切开取石，T管引流术后2周可行T管造影术，造影后继续引流约24h以上，如病人无明显不适，即可关闭 T 管。如胆道通畅无结石和其他病变，开腹手术可予手术后4周（B对）左右拔管，腹腔镜手术可适当延长拔管时间。推荐在拔管前行胆道镜检查，确认无结石残留 ，如造影发现有结石遗留，应在手术4～8周后待纤维窦道形成再施行胆道镜检查和取石。以上为最新十版教材的观点，八版教材的观点为：术后10～14天可行T管造影，造影后继续引流24h以上，如胆道畅通无结石和其他病变，应夹闭T管24～48小时，无腹痛、黄疸、发热等症状可予拔管，故本题的原参考答案为A，按最新十版教材的观点，本题答案应为B。","c125","N"],["2018-N101",32,"第四节 胆石症","肝外胆管结石影像学检查",2018,101,"A","","女性，55岁。1月前因急性胆管炎、胆囊炎、胆总管结石急诊行胆囊切除、胆总管切开取石、T管引流术。拔除T管前经T管胆道造影，结果如下图。此图显示的征象是",[["A","正常胆道影像"],["B","胆总管残余结石"],["C","壶腹部狭窄"],["D","左肝管显影不良"]],"D","该患者因急性胆管炎，胆囊炎，胆总管结石急诊行胆囊切除，胆总管切开取石，T管引流术，拔除T管前经T管胆道造影示左肝管显影不良（D对），疑合并肝内胆管结石。","c125","N"],["2018-N102",32,"第四节 胆石症","肝外胆管结石影像学检查",2018,102,"A","","女性，55岁。1月前因急性胆管炎、胆囊炎、胆总管结石急诊行胆囊切除、胆总管切开取石、T管引流术。根据上述造影结果，下一步的处理应是",[["A","常规拔除T管"],["B","经T管窦道胆道镜取石"],["C","行Whipple手术"],["D","肝脏CT检查"]],"D","该患者因急性胆管炎，胆囊炎，胆总管结石急诊行胆囊切除，胆总管切开取石，T管引流术，拔除T管前经T管胆道造影，示左肝管显影不良，疑肝内胆管结石。肝内胆管结石多合并有肝外胆管结石，可多年无症状或仅有上腹和胸背部胀痛不适，B超和CT（D对）对结石的诊断和定位均有帮助，PTC、MRCP能提供较满意的有助于诊断的影像学结果。","c125","N"],["2018-N103",48,"第一节 脊柱骨折","脊柱骨折诊断",2018,103,"A","","男性，29岁。高处坠落2小时，主诉胸背部疼痛，双下肢不能活动。根据患者情况，首先考虑的是",[["A","脊柱损伤合并骨盆骨折"],["B","脊柱损伤合并脊髓损伤"],["C","脊柱损伤合并双下肢骨折"],["D","胸部损伤合并骨盆骨折"]],"B","29岁男性患者，高处坠落2小时（外伤史），主诉胸背部疼痛，双下肢不能活动（脊髓损伤临床表现），根据患者外伤史、临床表现，最可能的诊断是胸段脊柱损伤并脊髓损伤（B对），外伤暴力致胸椎骨折，导致胸背部疼痛，同时脊柱骨折致脊髓严重损伤，导致下肢瘫痪。脊柱损伤并骨盆骨折（A错）、胸部损伤合并骨盆骨折（D错）可表现为胸背部疼痛，多存在严重的多发伤，休克常见，同时伴下肢长度不对称、会阴部瘀斑等表现，骨盆分离试验与挤压试验阳性。脊柱损伤并双下肢骨折（C错）表现为胸背部疼痛，同时伴下肢畸形及下肢异常活动。","","N"],["2018-N104",48,"第一节 脊柱骨折","脊柱骨折MRI",2018,104,"A","","男性，29岁。高处坠落2小时，主诉胸背部疼痛，双下肢不能活动。对诊断最有价值的检查是",[["A","脊髓造影"],["B","MRI检查"],["C","X线检查"],["D","脑脊液穿刺检查"]],"B","29岁男性患者，高处坠落2小时（外伤史），主诉胸背部疼痛，双下肢不能活动（脊髓损伤临床表现），根据患者外伤史、临床表现，最可能的诊断是胸段脊柱损伤并脊髓损伤，MRI检查（B对）可了解脊髓受压程度，还可以观察脊髓信号强度、脊髓信号改变的范围和脊髓萎缩情况等，对于患者疾病的诊断、治疗方案的拟定及愈后判断有重要价值。脊髓造影（A错）主要适用于腰段椎管占位性病变、椎间盘突出、椎管狭窄症、椎管畸形、脊柱退行性病变等。X线检查（C错）可通过观察椎体形态、椎间隙变化推测脊髓状况，但无法直接观察脊髓变化，诊疗价值有限。脑脊液穿刺（D错）多用于诊断神经系统感染性疾病及自身免疫性神经疾病。","","N"],["2018-N105",48,"第一节 脊柱骨折","脊柱骨折急救搬运",2018,105,"A","","男性，29岁。高处坠落2小时，主诉胸背部疼痛，双下肢不能活动。现场对该患者的正确搬运方法是",[["A","一人用一手抱颈，另一手抱脚放于担架上"],["B","一人抬头，另一人抬足放于木板上"],["C","两人架其上肢拉到担架上"],["D","两人将躯干保持平直状态成一体平移至木板上"]],"D","29岁男性患者，高处坠落2小时（外伤史），主诉胸背部疼痛，双下肢不能活动（脊髓损伤临床表现），根据患者外伤史、临床表现，最可能的诊断是胸段脊柱损伤并脊髓损伤，脊柱骨折患者搬运的要点是保持脊柱相对稳定，以避免脊髓再次遭受损伤。对该患者正确搬运方法是两人将躯干保持平直状态成一体平移至木板上（D对）可避免脊柱再次发生位移，不会增加脊髓的二次损伤。一人用一手抱颈，另一只手抱脚放于担架上（A错），一人抬头，另一人抬足放于木板上（B错）、两人架其上肢拉到担架上（C错）均无法保证脊柱稳定，可引起脊柱再次受伤，增加患者截瘫风险。","","N"],["2018-N106",55,"第二节 脊柱结核","脊柱结核诊断",2018,106,"A","","女性，30岁。腰背痛伴低热、盗汗1个月。既往有肺结核病史。体格检查发现胸11～12棘突明显压痛。最可能的诊断是",[["A","脊柱肿瘤"],["B","强直性脊柱炎"],["C","脊柱结核"],["D","化脓性脊柱炎"]],"C","患者青年女性，既往肺结核病史，低热盗汗（典型结核中毒症状），体格检查示：胸11～12棘突出现压痛（脊柱受累，局部炎性刺激），综合患者病史、症状、体查，该患者诊断考虑为脊柱结核（C对）。脊柱肿瘤（A错）分为良性、恶性，良性肿瘤多缓慢起病，恶性肿瘤则多为急性起病，当肿物增大压迫脊髓或者神经根时才会出现神经压迫症状，表现为腰背部疼痛及下肢活动障碍等，但患者无结核中毒症状。强直性脊柱炎（B错）是脊椎的慢性进行性炎症，以骶髂关节和脊柱附着点炎症为主要病变的疾病，好发于青壮年男性，有明显的家族遗传史，多数有骶髂关节炎，症状以后背疼痛为主，多数病人HLA-B27检测为阳性（十版外科学P753）。化脓性脊柱炎（D错）多数病人起病急骤，伴有畏寒、高热，局部疼痛、脓毒血症等（十版外科学P735）。","c126","N"],["2018-N107",55,"第二节 脊柱结核","MRI",2018,107,"A","","女性，30岁。腰背痛伴低热、盗汗1个月。既往有肺结核病史。体格检查发现胸11～12棘突明显压痛。最具有诊断价值的检查是",[["A","MRI"],["B","X线片"],["C","CT"],["D","结核菌素试验"]],"A","患者青年女性，既往肺结核病史，低热盗汗（典型结核中毒症状），体格检查示：胸11～12棘突出现压痛（脊柱受累，局部炎性刺激），综合患者病史、症状、体查，该患者诊断考虑为脊柱结核，最有价值的检查是MRI（A对），MRI能在疾病早期即在结核炎性浸润阶段即可显示异常信号，特别是对早期脊柱结核的诊断，较其他任何影像学检查包括ECT更为敏感，能清楚显示脊柱结核椎体骨炎，椎间盘破坏，椎旁脓肿及脊髓神经有无压迫和变性。X线片（B错）在骨质破坏或椎间隙狭窄时才会有所表现。CT（C错）可清晰显示骨质破坏的部位及程度，但对脊髓、椎间盘破坏等软组织显影效果差。结核菌素试验（D错）对未接种卡介苗的儿童、青少年有诊断价值，对感染过结核者及成人诊断价值不大。","c126","N"],["2018-N132",17,"第一节 甲状腺疾病","乳头状癌",2018,132,"B","","患者术后一般能存活15年以上的肿瘤是",[["A","胰腺导管腺癌"],["B","结肠癌"],["C","甲状腺乳头状癌"],["D","胃癌"]],"C","甲状腺乳头状癌（C对）为分化型甲状腺癌，分化良好，早期行根治术后规律内分泌治疗，术后一般能长期存活。胰腺导管腺癌（A错）的切除率及5年生存率目前仍较低。结、直肠癌（B错）的预后与肿瘤的分期有关，根据统计，Dukes A期五年生存率为90%以上，B期为70%，C期为35%。早期胃癌经合理治疗后，黏膜癌的5年生存率为98.0%，黏膜下癌为88.7%；进展期胃癌根治术后5年生存率一般在40%左右，纵观国内各医院胃癌切除术后5年生存率，差距较大，一般综合性医院为30%，有些专科医院可达50%以上（D错）。","","N"],["2018-N133",33,"第四节 胰腺癌和壶腹周围癌","胰腺癌病理类型",2018,133,"B","","患者术后很少存活5年的肿瘤是",[["A","胰腺导管腺癌"],["B","结肠癌"],["C","甲状腺乳头状癌"],["D","胃癌"]],"A","胰腺导管腺癌（A对）的切除率及5年生存率目前仍较低，其主要原因在于胰腺癌起病隐匿，发现时多已处于晚期，治疗效果差。甲状腺乳头状癌（C错）为分化型甲状腺癌，分化良好，早期行根治术后规律内分泌治疗，术后一般能长期存活。结肠癌（B错）平均5年生存率在50%～60%之间。胃癌（D错）与胃癌的病理分期、部位、组织类型、生物学行为以及治疗措施有关，早期胃癌平均五年生存率为82%～95%，根据大宗报告 ，规范治疗的Ⅰ期胃癌的5年生存率为82%～95%，Ⅱ期为55%，Ⅲ期为15%～30%，Ⅳ期仅2%。","","N"],["2018-N134",29,"第七节 直肠癌","Hartmann手术",2018,134,"B","","男性，82岁。粪便带血及黏液1个月。1周前结肠镜发现距肛缘15cm处环周肿物，镜身不能进入，取活检，病理报告：中分化腺癌。3天来腹胀、腹痛，停止排便排气，诊断肠梗阻。应选择的术式是",[["A","Miles 术"],["B","Dixon 术"],["C","Hartmann术"],["D","Parks 术"]],"C","82岁男性患者（高龄），直肠癌合并急性肠梗阻，一般状况差，难以耐受大手术，手术需尽量减少创伤，以解除肠道梗阻为主要目的，故首选Hartmann术（C对），适用于全身一般情况很差的直肠癌患者。Miles术（A错）适用于距离肛缘7cm以下的直肠癌段患者，该术式缺点是手术损伤大，不适用于老年、体弱及同时伴有较严重心肺等疾病的直肠癌患者。Dixon术（B错）适用于直肠癌距离肛缘6～7cm以上的直肠中上段癌患者，肠梗阻患者不适用。Parks术（D错）适用于低位直肠肿瘤，肿瘤下缘距离肛门4～7cm的直肠癌患者。","","N"],["2018-N135",29,"第七节 直肠癌","腹会阴切除术",2018,135,"B","","男性，58岁。脓血便2周。肛门指诊距肛缘4cm触及肿物，质硬，不活动，占据左侧大半周，上界未触及，指套有血渍。拟诊直肠癌。应选择的术式是",[["A","Miles 术"],["B","Dixon 术"],["C","Hartmann术"],["D","Park 术"]],"A","58岁中年男性患者，诊断为直肠癌，癌肿距肛缘4cm，质硬，不活动，占据左侧结肠大半周，无内科合并症，耐受手术能力可，应选择的手术方式是Miles术，Miles术（A对）适用于距离肛缘7cm以下的直肠癌段患者。Dixon术（B错）适用于距齿状线5cm以上的直肠癌，根治原则要求肿瘤远端距切缘至少2cm，低位直肠癌至少1cm，只要肛门外括约肌和肛提肌未受累，保证环周切缘阴性的前提下，均可行该术式。Hartmann术（C错）适用于患者一般状况较差，难以耐受Miles手术者或急性肠梗阻不宜行Dixon术患者。Park术（D错）适用于低位直肠肿瘤，肿瘤下缘距离肛门4～7cm的直肠癌患者。注意：十版外科学不再强调Dixon术适用于距离肛门5～7cm以上的直肠癌患者，临床上的最新观点为距离肛门5cm以上，且能保肛尽量保肛。","","N"],["2018-N160",32,"第四节 胆石症","肝内胆管结石临床表现",2018,160,"X","","肝内胆管结石可发生的并发症有",[["A","胆管炎"],["B","肝衰竭"],["C","胆管癌"],["D","门脉高压症"]],"ABCD","肝内胆管结石的病因为胆道感染、胆道寄生虫、胆汁淤滞、胆管解剖变异等因素有关，病理改变主要是结石造成肝内胆管的胆汁滞留、急慢性炎症、炎症狭窄和近端扩张，扩张的胆管积聚结石，会进一步加重胆管梗阻，并发反复的胆管炎（A对）、肝脓肿、胆道出血等，长期的慢性炎症可诱发胆管癌（C对），长期的梗阻也可导致肝硬化、门脉高压症（D对）、上消化道出血、肝衰竭（B对）。","","N"],["2018-N161",26,"第二节 胃癌及其他胃肿瘤","胃癌淋巴转移",2018,161,"X","","胃窦癌第二站淋巴结有",[["A","贲门右侧淋巴结"],["B","脾门淋巴结"],["C","胃左动脉旁淋巴结"],["D","腹腔动脉周围淋巴结"]],"ACD","淋巴转移是胃癌转移的主要途径，引流胃的区域淋巴结分为16组，第1组，贲门右；第2组，贲门左；第3组，胃小弯；第4组，胃大弯；第5组，幽门上；第6组，幽门下；第7组，胃左动脉旁；第8组，肝总动脉旁（动脉前方表示为8a，动脉后方表示为8p）；第9组，腹腔动脉旁；第10组，脾门；第11组，脾动脉旁（脾动脉近侧为11p，脾动脉远侧为11d）；第12组，肝十二指肠韧带（沿肝动脉为12a，沿门静脉为12p）；第13组，胰头后；第14组，肠系膜上血管旁（肠系膜上静脉旁为14v，肠系膜上动脉旁为14a）；第15组，结肠中血管旁；第16组，腹主动脉旁。八版外科学P362“表34-1 不同部位胃癌各站淋巴结的划分”显示：胃窦癌第二站淋巴结为1、7、8、9，即贲门右侧淋巴结（A对）、胃左动脉旁淋巴结（C对）、肝总动脉旁淋巴结和腹腔动脉周围淋巴结（D对），故本题当年的参考答案为ACD。然而，最近十版外科学P376“表38-3 胃癌根治术淋巴结清扫范围”显示：胃窦癌第二站淋巴结为8a、9、11p、12a，即肝总动脉前方淋巴结、腹腔动脉周围淋巴结（D对）、脾动脉近侧淋巴结和肝十二指肠韧带沿肝动脉淋巴结，按最新九版教材的观点，本题答案仅为","","N"],["2018-N162",19,"第三节 气胸","胸腔闭式引流术",2018,162,"X","","拔除胸腔闭式引流管的指征有",[["A","胸腔内气液无残留，肺扩张好，引流管通畅"],["B","胸腔内气体少量残留，肺扩张好，引流管不通畅"],["C","胸腔内气液无残留，肺不张，引流管通畅"],["D","胸腔内气体少量残留，引流管内间断有气体逸出"]],"AB","放置胸腔闭式引流管后，需要经常挤压引流管以保持通畅，定时记录引流液量，引流后肺复张良好，已无气体和液体排出，可在病人深吸气后屏气时拔出引流管并封闭伤口。胸腔内气液无残留，肺扩张好，引流管通畅符合拔管指征（A对）。胸腔内气体少量残留，肺扩张好，拔出引流管后剩余少量气体可自行吸收，引流管不通畅时，也需要拔出引流管（B对）。胸腔内气液无残留，但是肺不张，需要留置闭式引流管，等待进一步的观察治疗，再决定是否拔出引流管（C错）。胸腔内气体少量残留，引流管间断有气体逸出，说明胸腔内压高，仍需继续引流（D错），本题正确答案应为AB，但当年给出的参考答案为ABC。","","N"],["2018-N163",5,"第五节 脓毒症","脓毒症临床表现",2018,163,"X","","真菌败血症的临床表现有",[["A","突发寒战、高热"],["B","神志淡漠、昏迷、休克"],["C","多伴有消化道出血"],["D","外周血有类白血病反应"]],"ABD","真菌败血症多继发于细菌感染之后，或与细菌感染混合存在，常见的致病菌是白色念珠菌，病程进展缓慢，临床毒血症症状可被原发病及伴发的细菌感染掩盖，临床表现为骤起寒战高热（39～40℃）（A对）、出现神志淡漠、昏睡、休克（B对）等，少数病人尚有消化道出血（C错），外周血有类白血病反应（D对），出现晚幼粒细胞和中幼粒细胞，白细胞计数升高，可达25×10⁹/L（五版外科学P187）。基础疾病重、免疫功能低下者，应特别重视抗生素的合理应用以预防深部真菌感染。","","N"],["2018-N164",45,"第四节 肱骨近端骨折","肱骨近端骨折病因与分类",2018,164,"X","","关于肱骨外科颈骨折，下列说法正确的有",[["A","多见于中老年人"],["B","可合并血管神经损伤"],["C","可合并肱骨头碎裂骨折"],["D","有侧方和成角移位者须手术治疗"]],"ABC","肱骨外科颈骨折主要是因间接外力所致，可发生于任何年龄，多见于中老年人（A对）。在解剖颈下2～3cm，有臂丛神经、腋血管通过，可合并血管神经损伤（B对）。如撞击外力强大，骨质亦较疏松脆弱，可合并肱骨头碎裂骨折（C对），肱骨外科颈骨折切开复位适应证包括：三型骨折、开放性二型骨折或二型骨折闭合复位失败，伴血管神经损伤，肩关节脱位者或治疗较晚不能手法复位者，有侧方和成角移位者需根据位移的情况和患者本身的实际状况来决定是否手术（D错）。","","N"],["2018-N165",57,"第三节 骨巨细胞瘤","骨巨细胞瘤概述",2018,165,"X","","关于骨巨细胞瘤，下列说法正确的有",[["A","是一种生物学行为不确定的肿瘤"],["B","好发年龄为20～40岁"],["C","X线显示骨端偏心性溶骨性破坏"],["D","治疗以化疗和放疗为主"]],"ABC","骨巨细胞瘤是一种较常见的骨原发肿瘤，骨巨细胞瘤为交界性或行为不确定（A对）的肿瘤，可分为巨细胞瘤和恶性巨细胞瘤，好发于20～40岁，女性略多（B对）。其典型的X线特征为骨端偏心位、溶骨性、囊性破坏而无骨膜反应，病灶膨胀生长、骨皮质变薄，呈肥皂泡样改变。侵袭性强的肿瘤可穿破骨皮质致病理骨折（C对）。骨巨细胞瘤的组织学与生物行为常不一致，即使组织学是典型的巨细胞瘤（良性肿瘤），也可具有很强的侵袭性，并可发生转移，骨巨细胞瘤总体来说以手术治疗为主，不常用化疗和放疗治疗（D错），效果不佳。","","N"],["2019-N57",7,"第一节 热力烧伤","现场急救",2019,57,"A","","女性，25岁，火灾中烧伤，烧伤面积达70%，准备转入120km以外的大医院救治。转运前最重要的处理是",[["A","清创并包扎创面"],["B","注射止痛药物"],["C","建立静脉通道并输液"],["D","准备烧伤饮料"]],"C","青年女性，全身烧伤面积大，需要立刻转送至大医院救治，伤后早期体液渗出量较大，转运途中须建立静脉输液通道（C对），途中继续输液，保证呼吸道通畅，避免液体丢失过多导致低血容量性休克，必要时可经通道输入血管活性药物。清创并包扎创面（A错）为医院内处理，若在现场附近，创面只求不再污染损伤，可用干净敷料或布类保护，简单包扎后转运。注射止痛药物（B错）为一般对症治疗，疼痛剧烈可酌情使用地西泮、哌替啶等，但非最重要的处理。准备烧伤饮料（D错）适用于不具备输液条件患者，防止单纯大量饮水发生水中毒，不作首选。","","N"],["2019-N58",17,"第一节 甲状腺疾病","慢性淋巴细胞性甲状腺炎诊断",2019,58,"A","","女性，42岁。无痛性甲状腺肿大3个月。查体：甲状腺弥漫性肿大，触诊质地较硬、韧，表面光滑。化验：T₃，T₄略低于正常。最可能的诊断是",[["A","单纯性甲状腺肿"],["B","慢性淋巴细胞性甲状腺炎"],["C","亚急性甲状腺炎"],["D","甲状腺癌"]],"B","中年女性患者（慢性淋巴细胞性甲状腺炎好发于30～50岁女性，高发人群），无痛性甲状腺肿大3个月（病程缓慢，慢性淋巴细胞性甲状腺炎常见临床表现），查体：甲状腺弥漫性肿大，触诊质地较硬，韧，表面光滑（慢性淋巴细胞性甲状腺炎常见体征），化验T₃，T₄略低于正常（提示甲状腺功能减退），根据该患者的病史、体查及实验室检查，最可能的诊断是慢性淋巴细胞性甲状腺炎（B对），又称桥本甲状腺炎，是一种自身免疫性疾病，也是甲状腺功能减退的常见原因。单纯性甲状腺肿（A错）病因多不同，早期甲状腺多呈对称性、弥漫性肿大，腺体质地柔软，表面光滑，随吞咽上下移动，可能继发甲亢，也可能发生恶变（十版外科学P234）。亚急性甲状腺炎（C错）常继发于上呼吸道感染，为甲状腺的亚急性肉芽肿性炎症，临床表现为甲状腺突然肿胀、发硬、吞咽困难及疼痛，疼痛常只波及患侧耳、颞枕部，早期血清T₃，T₄浓度升高，病程约为3个月，愈后甲状腺功能多不减退（十版外科学P236-P237）。甲状腺癌（D错）最常见的表现为甲状腺单发或多发肿块，质地较硬，较固定，或有压迫症状，又或存在多年的甲状腺肿块在短期内迅速增大，且不同病理类型的甲状腺癌，其生物学特性、临床表现、诊断、治疗及预后均有所不同，细胞穿刺学检查可以帮助诊断（十版外科学P237-P238）。","","N"],["2019-N59",42,"第一节 肾肿瘤","肾细胞癌诊断",2019,59,"A","","男性，50岁。1个月来有过2次无痛性血尿，近日觉阴囊坠胀感，卧位坠胀无减轻，体检发现右侧阴囊内精索静脉曲张。最可能的诊断是",[["A","原发性精索静脉曲张"],["B","肾癌"],["C","肾结石"],["D","膀胱肿瘤"]],"B","50岁男性患者（中老年男性患者，肾癌高发人群），1个月来有过两次无痛性肉眼血尿（中老年出现无痛肉眼血尿），近日觉阴囊坠胀感，卧位坠胀无减轻（腹部疼痛），体检发现右侧阴囊内精索静脉曲张（考虑癌肿形成癌栓），考虑患者主诉和体征，最可能的诊断是肾癌（B对），凡在40岁以上中老年人，出现血尿、腰痛、腹部肿物应该想到肾癌的可能性。膀胱肿瘤（D错）也会出现无痛性血尿，同时可伴有排尿不畅、疼痛等尿路梗阻症状，当肿瘤浸润膀胱肌层，会出现膀胱刺激征，故不明原因出现血尿或膀胱刺激征的患者，应考虑到膀胱肿瘤的可能性。需要注意的是，对出现不明原因无痛血尿的中老年人，肾癌和膀胱肿瘤都是应高度怀疑的疾病，本例患者的临床表现和体征更倾向支持肾癌的诊断。肾结石（C错）最常见的症状是腰痛和血尿，在肾盂内较小的结石由于移动性大和直接刺激，能引起急性梗阻，出现肾绞痛，病史中凡有腰部疼痛（或运动后）后伴血尿，多考虑肾结石。原发性精索静脉曲张（A错）一般多无症状，易被忽视，仅在体检时发现，症状严重时可表现为病侧阴囊胀大，有坠胀、隐痛，步行或站立过久则症状加重，平卧后症状可缓解或消失。","","N"],["2019-N60",31,"门静脉高压","断流手术",2019,60,"A","","脾切除、贲门周围血管离断术治疗肝硬化门静脉高压症食管静脉破裂出血的优点中，不被普遍认可的是",[["A","手术打击相对较小"],["B","止血效果较满意"],["C","术后脑病发生率较低"],["D","术后肝功能改善"]],"D","离断术是通过阻断门、奇静脉之间的反常血流，达到止血目的，其中以脾切除加贲门周围血管离断术最为有效，是目前国内治疗食管胃底静脉曲张出血的主要方式，该术式主要阻断脾胃区，特别是胃左静脉（冠状静脉食管支）的血流，针对性强，止血效果迅速而确切（B对）；对患者打击较小，肝功能损伤轻，术后并发症少（A对），肝性脑病发生率低（C对），术后生存质量高，操作相对简单，易于在基层医院推广（4版实用外科学P639）。手术完成后仍能维持较高的肝门静脉压力，保持甚至增加肝门静脉的向肝血流，有利于术后肝细胞的再生和肝功能的改善，但亦有研究表明断流术后肝门静脉压虽仍高于正常值的上缘，但肝门静脉的血流是有所降低的（肝胆外科查房释疑P84-P85），故有关该术式不被“普遍认可”的观点为术后肝功能是否改善（D错，为本题正确答案）。","","N"],["2019-N61",19,"第三节 气胸","开放性气胸临床表现",2019,61,"A","","可能发生纵隔扑动的胸部损伤的是",[["A","开放性气胸"],["B","闭合性气胸"],["C","张力性气胸"],["D","进行性血胸"]],"A","可能发生纵隔扑动的胸部损伤的是开放性气胸（A对），是因开放性气胸时，外界空气随呼吸经胸壁缺损处自由进出胸膜腔，伤侧胸膜腔内的大气压力显著高于健侧，纵隔偏向健侧移位，致使健侧肺扩张也明显受限，此时吸气时，纵隔移向健侧，呼气时又回移向患侧，这种纵隔扑动和移位会影响腔静脉回心血量，引起循环障碍。闭合性气胸（B错）时胸膜腔内压力仍然低于大气压，其症状和胸膜腔内积气的量与速度有关，患侧胸腔内压升高，纵隔向健侧偏移（十版外科学P258）。张力性气胸（C错）为胸壁损伤处形成活瓣，患侧胸腔内压进行性升高，高于大气压，又称高气压气胸，伤侧肺萎陷严重，纵隔向健侧偏移（十版外科学P259）。进行性血胸（D错）表现为胸腔内持续出血，伤侧胸部呼吸运动减弱，肋间隙变宽，胸腔饱满，气管向健侧移位，呼吸音减弱甚至消失，叩诊浊音，需要及时剖胸探查，手术止血，可与闭合性气胸、开放性气胸及张力性气胸同时存在（十版外科学P260）。","","N"],["2019-N62",32,"第四节 胆石症","胆囊结石治疗",2019,62,"A","","女性，28岁。体检发现胆囊多发结石，最大直径0.6cm，无症状。应采取的处理措施是",[["A","胆囊切除术"],["B","胆囊切开取石术"],["C","服用药物排石"],["D","随访观察"]],"D","青年女性患者，无症状多发小结石，最大直径0.6cm（＜2cm），不在手术适应症范围内，一般不做预防性胆囊切除（A错），可随访观察（D对）。对胆囊结石，下列情况考虑手术治疗：①结石数量多及结石直径≥2～3cm；②胆囊壁钙化或瓷性胆囊；③伴有胆囊息肉≥1cm；④胆囊壁增厚（＞3mm）即伴有慢性胆囊炎（十版外科学P469）。胆囊切开取石术（B错）后胆囊缝线、炎症瘢痕等因素常导致新发结石，临床现已弃用该术式。服用药物排石（C错）效果不确切，不作常规应用。","","N"],["2019-N63",23,"第二节 腹股沟疝","嵌顿性和绞窄性疝的处理原则",2019,63,"A","","男性，65岁。右腹股沟包块3年，卧位可消失，12小时前突然不能还纳，并出现右下腹痛。查体：T 38℃，P 100次/分，右侧腹股沟4×3cm肿块，触痛明显，右下腹有压痛及肌紧张。正确的治疗措施是",[["A","急行疝修补术"],["B","切除坏死肠管、高位结扎疝囊"],["C","切除坏死肠管后疝修补术"],["D","注射止痛剂后手法复位"]],"B","65岁男性（老年男性患者），右下腹肿块3年，卧位可自主还纳（提示长期可复性疝），12小时前突然不能还纳（提示嵌顿/绞窄性疝），出现右腹痛。入院查体，T 38℃（发热，提示感染），P100次/分（正常人心率为60～100次/分，心率加快），右腹股沟4×3cm肿块，触痛明显，右下腹压痛肌紧张（提示腹膜炎，肠管缺血坏死可能），根据患者病史、临床表现和查体结果，诊断考虑绞窄性疝，肠管坏死并腹膜炎，此时需要行紧急手术治疗（D错），防止病情恶化，解除伴发肠梗阻，正确的处理是切除坏死肠管并行高位疝囊结扎术（B对C错），疝囊高位结扎是腹股沟疝手术治疗中的重点内容，同时，已经实施肠切除吻合术的病人，因在手术区存在污染，故在高位结扎疝囊后，一般不宜做疝修补术（A错），以免因感染而导致修补失败。疝修补术是利用临近组织加强腹壁强度的方法，术式较多，均包括内环的修补和腹股沟管管壁的加强两个主要环节。止痛并手法复位（D错）适用于年老体弱，嵌顿时间较短，局部无腹膜炎表现患者，且长期使用疝带可使疝囊颈经常受到摩擦变得肥厚坚韧而增加疝嵌顿的发病率，并有促使疝囊与疝内容物发生粘连的可能，该患者不宜选用。","","N"],["2019-N64",22,"第四节 静脉疾病","手术疗法",2019,64,"A","","判断大隐静脉曲张能否手术的关键检查是",[["A","Pratt试验"],["B","Trendelenburg试验"],["C","Perthes试验"],["D","Buerger试验"]],"C","判断大隐静脉曲张能否手术的关键检查是Perthes试验（C对），对于大隐静脉曲张，传统的方法大隐静脉高位结扎及主干与曲张静脉剥脱术，术后下肢血液经深静脉回流，故术前须行下肢静脉彩超或Perthes试验（C对）判断深静脉是否通畅，如深静脉回流不畅，为手术禁忌证。Pratt试验（A错）用于判断下肢深浅静脉间交通静脉瓣膜功能。Trendelenburg试验（B错）用于判断下肢浅静脉瓣膜功能。Buerger试验（D错）用于初步判断动脉供血障碍及静脉逆流或回流障碍性疾病。","","N"],["2019-N65",47,"第二节 股骨近端骨折","股骨颈骨折临床表现与诊断",2019,65,"A","","判断大转子上移的测量参数是",[["A","Cobb角"],["B","Bryant三角"],["C","Codman三角"],["D","Pauwels三角"]],"B","判断大转子上移的测量参数是Bryant三角（B对），其测量需要病人仰卧位，从髂前上棘垂直向下和向大转子尖各画一线，再从大转子向近侧画一水平线，该三线构成的三角形为Bryant三角，水平的底边一般长度为5cm，当大转子上移时，患侧较健侧短。Cobb角（A错）用于度量脊柱侧弯程度。Codman三角（C错）见于骨肉瘤。Pauwels三角（D错）为股骨颈远端骨折线与两侧髂嵴连线的夹角，可用于判断股骨颈骨折的稳定性。","","N"],["2019-N66",45,"第六节 肱骨髁上骨折","肱骨髁解剖概要",2019,66,"A","","肱骨干轴线和肱骨髁轴线之间的前倾角，正常的角度是",[["A","小于10°"],["B","10～20°"],["C","30～50°"],["D","大于50°"]],"C","肱骨干轴线和肱骨髁轴线之间的正常前倾角度为30～50°（C对），为皮质骨与松质骨交界处，较薄弱，容易发生肱骨髁上骨折。","","N"],["2019-N67",56,"第一节 骨关节炎","骨关节炎诊断",2019,67,"A","","女性，49岁。右肩痛，右上肢上举、外展受限8个月，无肩周红、肿、热等表现，疼痛可向右侧颈、耳、前臂及手放射。X线示：右肩关节间隙变窄，软骨下骨囊性变，关节边缘骨质增生。最可能的诊断是",[["A","肩关节骨关节炎"],["B","类风湿关节炎"],["C","肩袖损伤"],["D","粘连性肩关节囊炎"]],"A","中年女性患者（高发人群），肩部疼痛伴活动受限，局部无红肿热痛等急性炎症表现，疼痛可向右侧颈、耳、前臂及手放射（牵涉痛），X线示关节间隙变窄，软骨下囊性变，关节周围骨质增生提示肩关节退行性变（骨关节炎影像学表现），最可能的诊断是肩关节骨关节炎（A对），骨关节炎又名退行性骨关节炎，为关节软骨发生退行性变，关节边缘有骨刺形成，并产生疼痛等症状。类风湿性关节炎（B错）较少累及肩关节，早期X线表现为周围软组织增大，关节间隙变宽，关节周围骨质疏松，晚期关节边缘模糊不清，关节间隙逐渐变窄。肩袖损伤（C错）X线无明显阳性表现，可伴肩关节外展无力，与患者症状不符。粘连性肩关节囊炎（D错）可有肩关节活动受限，但肩关节X线除骨质疏松外，一般无明显结构异常。","","N"],["2019-N71",33,"第四节 胰腺癌和壶腹周围癌","黄疸",2019,71,"A","","男性，65岁。2个月来食欲下降，体重减轻3公斤，无腹胀、腹痛。既往体健。查体：T 36.8℃，P 72次/分，BP 120/75mmHg，一般情况良好，浅表淋巴结不大，皮肤巩膜明显黄染，心肺（-），腹平软，右上腹可及一肿物，光滑，质韧，无触痛，深吸气时易触及，移动性浊音（-），肠鸣音正常。该患者触及的肿物最可能来自的脏器是",[["A","肝脏"],["B","胆囊"],["C","肾脏"],["D","胰腺"]],"B","老年男性患者，近来食欲下降，有明显体重减轻（胰腺癌可有的消化道症状和全身症状），无腹胀、腹痛。既往体健。查体：T 36.8℃，P 72次/分，BP 120/75mmHg，一般情况良好（胰腺癌早期可无典型症状），皮肤巩膜明显黄染（黄疸），心肺（-），移动性浊音（-），肠鸣音正常。腹平软，右上腹可及一肿物，光滑，质韧，无触痛，深吸气时易触及（库瓦济埃征，即在胰腺癌时，肿瘤压迫导致胆道系统梗阻，肝脏和胆囊显著肿大，但无压迫，胆囊常可与体表触及），根据患者的临床表现和体征，最可能的诊断是胰腺癌，查体时该患者触及的肿物最可能来自的脏器是胆囊（B对）。","c128","N"],["2019-N72",33,"第四节 胰腺癌和壶腹周围癌","胰腺癌诊断",2019,72,"A","","男性，65岁。2个月来食欲下降，体重减轻3公斤，无腹胀、腹痛。既往体健。查体：T 36.8℃，P 72次/分，BP 120/76mmHg，一般情况良好，浅表淋巴结不大，皮肤巩膜明显黄染，心肺（-），腹平软，右上腹可及一肿物，光滑，质韧，无触痛，深吸气时易触及，移动性浊音（-），肠鸣音正常。该患者应考虑的原发疾病最可能的是",[["A","肝癌"],["B","胆囊癌"],["C","肾癌"],["D","胰头癌"]],"D","老年男性患者，近来食欲下降，有明显体重减轻（胰腺癌可有的消化道症状和全身症状），无腹胀、腹痛。既往体健。查体：T 36.8℃，P 72次/分，BP 120/75mmHg，一般情况良好（胰腺癌早期可无典型症状），皮肤巩膜明显黄染（黄疸），心肺（-），移动性浊音（-），肠鸣音正常。腹平软，右上腹可及一肿物，光滑，质韧，无触痛，深吸气时易触及（库瓦济埃征，即在胰腺癌时，肿瘤压迫导致胆道系统梗阻，肝脏和胆囊显著增大，但无压迫，胆囊常可与体表触及），根据患者的临床表现和体征，最可能的诊断是胰头癌（D对），胰头癌早期可无明显症状，仅见巩膜及皮肤黄染及因肿瘤压迫胆总管致胆汁潴留而使胆囊胀大，因胆囊本身无病变，故光滑、无触痛。肝癌（A错）患者一般有肝炎、肝硬化病史，甲胎蛋白≥400ng/ml，影像学检查可发现肝实质肿块，临床表现可有肝区疼痛、肝大或右上腹肿块，乏力、消瘦、食欲减退、黄疸、腹胀等全身及消化道症状（十版外科学P448）。胆囊癌（B错）能触及右上腹肿物时往往已到晚期，常伴有腹胀、食欲差、体重减轻或消瘦、贫血、肝大，甚至出现黄疸、腹水、全身衰竭（十版外科学P481）。肾癌（C错）典型表现为血尿、肾区疼痛和腹部肿块（十版外科学P564）。","c128","N"],["2019-N93",27,"第五节 肠系膜血管缺血性疾病","肠系膜上动脉栓塞",2019,93,"A","","男性，67岁。3小时前突发脐周绞痛，面色苍白，大汗，2小时后疼痛减轻，出现腹胀。有心房颤动病史。查体：全腹压痛、反跳痛、轻度肌紧张，移动性浊音可疑，肠鸣音弱。最可能的诊断是",[["A","重症急性胰腺炎"],["B","急性肠扭转"],["C","肠系膜上动脉栓塞"],["D","上消化道穿孔"]],"C","老年男性，3小时前突发脐周绞痛、面色苍白、大汗（起病急骤，症状明显且严重），2小时后疼痛缓解，出现腹胀（剧烈疼痛转为持续性疼痛，提示肠梗阻）。既往有心房颤动史（肠系膜上动脉栓塞病因）。查体：全腹压痛、反跳痛，轻度肌紧张，腹部移动性浊音可疑，肠鸣音减弱（腹膜刺激征阳性，肠鸣音弱，提示肠坏死），根据该患者的既往病史、临床表现及查体结果，最可能的诊断是肠系膜上动脉栓塞（C对）。急性重症胰腺炎（A错）时也可伴腹膜刺激征阳性及肠鸣音减弱，但疼痛多呈进行加重，可有脉搏细速、血压下降、乃至休克。急性肠扭转（B错）常有剧烈运动史，疼痛多呈进行性加重，查体可见腹壁局部隆起伴肠型，突出症状是频繁呕吐伴持续腹痛，呈阵发性加剧。上消化道穿孔（D错）患者多有溃疡病史或服用非甾体抗炎药或皮质激素病史，穿孔前常有过度疲劳、精神紧张等诱发因素，疼痛为突发性、刀割样疼痛，多由局部迅速扩散至全腹，腹膜刺激征明显，腹肌紧张呈“板状腹”，反跳痛明显，肠鸣音减弱或消失，可闻及移动性浊音。","","N"],["2019-N94",27,"第五节 肠系膜血管缺血性疾病","肠系膜血管缺血性疾病检查",2019,94,"A","","男性，67岁。3小时前突发脐周绞痛，面色苍白，大汗，3小时后疼痛减轻，出现腹胀。有心房颤动病史。查体：全腹压痛、反跳痛、轻度肌紧张，移动性浊音可疑，肠鸣音弱。最有诊断意义的检查是",[["A","血淀粉酶测定"],["B","立卧位腹部平片"],["C","腹部B超检查"],["D","选择性腹腔动脉造影"]],"D","老年男性，3小时前突发脐周绞痛、面色苍白、大汗（起病急骤，症状明显且严重），2小时后疼痛缓解，出现腹胀（剧烈疼痛转为持续性疼痛，提示肠梗阻）。既往有心房颤动史（肠系膜上动脉栓塞病因）。查体：全腹压痛、反跳痛，轻度肌紧张，腹部移动性浊音可疑，肠鸣音减弱（腹膜刺激征阳性，肠鸣音弱，提示肠坏死），根据该患者的既往病史、临床表现及查体结果，最可能的诊断是肠系膜上动脉栓塞，最有诊断意义的检查是选择性腹腔动脉造影（D对），不仅能帮助诊断，还可鉴别是动脉栓塞、血栓形成或血管痉挛，在明确诊断的同时给予血管扩张剂等治疗。血淀粉酶测定（A错）主要用于诊断胰腺炎。立卧位腹部平片（B错）可用于诊断消化道穿孔。腹部B超检查（C错）用于腹部疾病筛查，对于肠系膜血管栓塞诊断价值有限。","","N"],["2019-N95",13,"第二节 术后处理","静脉输液",2019,95,"A","","男性，45岁，体重65kg。因胆囊结石及胆总管结石行胆囊切除、胆总管切开取石术，手术顺利。手术当日出入量如下：总输入液量4500ml，出量：胃肠减压500ml，T管引流450ml，腹腔引流液50ml，尿量2500ml。患者心、肾功能及血电解质正常，未用利尿剂。术后第一天输液总量应是",[["A","1500ml"],["B","2000ml"],["C","3500ml"],["D","4500ml"]],"C","65kg患者，术后第一天总输液量=生理需要量（2000ml～2500ml）+累计丢失量（1000ml）=3000ml～3500ml（C对）。","c134","N"],["2019-N96",13,"第二节 术后处理","静脉输液",2019,96,"A","","男性，45岁，体重65kg。因胆囊结石及胆总管结石行胆囊切除、胆总管切开取石术，手术顺利。手术当日出入量如下：总输入液量4500ml，出量：胃肠减压500ml，T管引流450ml，腹腔引流液50ml，尿量2500ml。患者心、肾功能及血电解质正常，未用利尿剂。患者手术当天的显性额外损失量是",[["A","1000ml"],["B","2000ml"],["C","2500ml"],["D","3500ml"]],"A","未应用利尿剂的情况下，该患者手术当天显性额外损失量=T管引流+腹腔引流+胃肠减压=450ml+50ml+500ml=1000ml（A对）。","c134","N"],["2019-N97",13,"第二节 术后处理","静脉输液",2019,97,"A","","男性，45岁，体重65kg。因胆囊结石及胆总管结石行胆囊切除、胆总管切开取石术，手术顺利。手术当日出入量如下：总输入液量4500ml，出量：胃肠减压500ml，T管引流450ml，腹腔引流液50ml，尿量2500ml。患者心、肾功能及血电解质正常，未用利尿剂。术后第一天补液中应包括生理盐水",[["A","500ml"],["B","1000ml"],["C","1500ml"],["D","2000ml"]],"C","术后患者补液多由糖、脂乳、氨基酸、各种微量元素及维生素制剂构成，补充钠盐的药物除生理盐水外还包括各种高渗制剂如10%氯化钠溶液。该患者额外显性损失（胃肠减压、T管引流、胃肠减压）为1000ml等渗液，可予相应的生理盐水1000ml或平衡盐溶液补充，加上生理需要量4.5g钠，约500ml生理盐水，共计1500ml（C对）。","c134","N"],["2019-N98",32,"第四节 胆石症","肝内胆管结石诊断",2019,98,"A","","女性，55岁。反复发作上腹痛并发热8年，近日再次发作。查体：T 39℃，P 112次/分，BP 132/86mmHg，巩膜不黄，上腹压痛，轻度肌紧张，肝区叩痛。化验：Hb132g/L，WBC 13.8×10⁹/L，N 86%，ALT 86U/L，T-Bil 28.5μmol/L。MRCP提示：左侧肝内胆管局限性扩张，其内可见多发低信号影，右侧肝内胆管及肝外胆管未见扩张，胆囊不大，肝左叶体积缩小。该患者的诊断是",[["A","左肝脓肿"],["B","左肝癌"],["C","左肝内胆管结石、胆管炎"],["D","胆囊炎"]],"C","55岁女性，反复发作性上腹痛8年（病史较长），近日再次发作，查体：体温39℃（正常人体温36～37℃，高热），心率112次/分（正常人心率为60～100次/分，心动过速），血压132/86mmHg（90mmHg≤正常收缩压＜139mmHg，60mmHg≤正常舒张压＜89mmHg，血压正常），巩膜不黄，辅助检查Hb132g/L，白细胞13.8×10⁹/L（正常值3.5～9.5×10⁹/L，提示感染），中性粒86%（正常值：40%～75%，提示感染），ALT86U/L（正常值：5～40U/L，提示肝损伤），T-Bil28.6μmol/L（正常值：1.7～17.1μmol/L，提示梗阻），MRCP示左侧肝内胆管局限性扩张，其内可见多发低信号影（提示局限性胆管梗阻），右侧肝内胆管及肝外胆管未见扩张，肝左叶萎缩（长期反复炎症致肝实质萎缩，病变定位于左肝），根据该患者的病史、查体及影像学检查，诊断考虑左肝胆结石合并胆管炎（C对）。左肝脓肿（A错）可出现感染中毒症状及肝损伤，但一般无胆管扩张。左肝癌（B错）一般无感染中毒症状，且影像学表现为左肝占位性病变，可有恶病质等肿瘤相关全身表现。胆囊炎（D错）可出现感染中毒症状，但无肝内胆管系统扩张及黄疸及左肝萎缩的表现，与患者表现不符。","c135","N"],["2019-N99",32,"第四节 胆石症","肝切除术",2019,99,"A","","女性，55岁。反复发作上腹痛并发热8年，近日再次发作。查体：T 39℃，P 112次/分，BP 132/86mmHg，巩膜不黄，上腹压痛，轻度肌紧张，肝区叩痛。化验：Hb132g/L，WBC 13.8×10⁹/L，N 86%，ALT 86U/L，T-Bil 28.6μmol/L。MRCP提示：左侧肝内胆管局限性扩张，其内可见多发低信号影，右侧肝内胆管及肝外胆管未见扩张，胆囊不大，肝左叶体积缩小。最佳的治疗方案是",[["A","内镜下Oddi括约肌切开术"],["B","急行胆囊切除术"],["C","PTCD治疗"],["D","保守治疗后左半肝切除术"]],"D","55岁女性，反复发作性上腹痛8年（病史较长），近日再次发作，查体：体温39℃（正常人体温36～37℃，高热），心率112次/分（正常人心率为60～100次/分，心动过速），血压132/86mmHg（90mmHg≤正常收缩压＜139mmHg，60mmHg≤正常舒张压＜89mmHg，血压正常），巩膜不黄，辅助检查Hb113g/L，白细胞13.8×10⁹/L（正常值3.5～9.5×10⁹/L，提示感染），中性粒86%（正常值：40%～75%，提示感染），ALT86U/L（正常值：5～40U/L，提示肝损伤），T-Bil28.μmol/L（正常值：1.7～17.1μmol/L，提示梗阻），MRCP示左侧肝内胆管局限性扩张，右侧肝内胆管及肝外胆管未见扩张（提示局限性胆管梗阻），肝左叶萎缩（长期反复炎症致肝实质萎缩，病变定位于左肝），根据该患者的病史、查体及影像学检查，诊断考虑左肝胆结石合并胆管炎，目前该患者合并感染，最佳的治疗方案是保守治疗后行左肝叶切除术（D对），可同时切除病变的肝，包括结石和感染的病灶，去除结石的再发源地，并可防止病变肝叶的癌变。内镜下Oddi括约肌切开术（A错）适用于胆总管下段的梗阻性病变。急诊胆囊切除术（B错）适用于急性胆囊炎伴胆囊结石患者。PTCD治疗（C错）适用于急性重症胆管炎的急救治疗。","c135","N"],["2019-N100",29,"第七节 直肠癌","腹会阴切除术",2019,100,"A","","男性，60岁。自述1年半前因直肠肿瘤在外院手术治疗，具体术式不清。检查见左下腹部旁正中12厘米直切口瘢痕，其外侧有一肠造口，肛门已不存在。推测患者所做的手术方式应是",[["A","Miles"],["B","Dixon"],["C","Hartmann"],["D","乙状结肠造瘘"]],"A","老年患者，直肠癌术后1年余，考虑为非姑息性手术，同时患者腹部为旁正中切口，左下腹单腔造口，不存在肛门（Miles手术需于左下腹行永久性乙状结肠单腔造口，术后无肛门），符合Miles手术（A对）特点。Dixon（B错）为直肠癌保肛手术，可为旁正中切口，部分患者可留有保护性双腔造口。Hartmann（C错）适用于一般情况差，不能耐受Miles手术或急性肠梗阻不宜行Dixon手术的患者，手术避免了肛门部操作，术后患者肛门仍保留。乙状结肠造瘘（D错）为姑息手术，用于晚期直肠癌患者，以解除痛苦和处理并发症为主要目的，多为双腔造口，且保留肛门，患者生存期较短，与本例不符。","c136","N"],["2019-N101",30,"第五节 转移性肝肿瘤","转移性肝肿瘤诊断",2019,101,"A","","男性，60岁。自述1年半前因直肠肿瘤在外院手术治疗，具体术式不清。检查见左下腹部旁正中12厘米直切口瘢痕，其外侧有一肠造口，肛门已不存在。患者一般状况尚好，肠造口排便正常。肝脏CT见右后叶下段肝内有一直径2.5cm结节，环周强化明显，血CEA升高，AFP、CA19-9正常。应首先考虑的诊断是",[["A","原发性肝癌"],["B","肝血管瘤"],["C","肝囊肿"],["D","转移性肝癌"]],"D","老年患者，直肠癌术后1年余，考虑为非姑息性手术，同时患者腹部为旁正中切口，左下腹单腔造口，不存在肛门（Miles手术需于左下腹行永久性乙状结肠单腔造口，术后无肛门），说明该患者直肠癌术式为Miles术，现患者一般状况尚好（转移性肝癌较小时，一般无症状），肝脏CT见右后叶下段肝内有一直径2.5cm结节，环周强化明显（肝转移癌增强CT可出现环状强化或结节性强化），血CEA升高（胃肠道肝转移病人，CEA阳性率约50%），AFP正常（转移性肝癌AFP升高者较少）、CA19-9正常（不考虑肺转移癌），应首先考虑的诊断是转移性肝癌（D对）。原发性肝癌（A错）影像学检查可发现肝实质性肿块，增强CT多呈结节状强化，典型肝癌结节呈“快进快出”表现，肿瘤标志物检测AFP升高。肝血管瘤（B错）属于肝脏良性病变，CT诊断有高度的敏感性和特异性，增强后早期在病变周围出现羟化晕环，延迟期造影剂呈向心性弥散。肝囊肿（C错）为较常见的肝良性病变，超声为其诊断首选方法，CT多呈低密度肝占位灶，无强化，可明确囊肿的大小、部位、形态和数目。","c136","N"],["2019-N102",30,"第五节 转移性肝肿瘤","转移性肝肿瘤治疗",2019,102,"A","","男性，60岁。自述1年半前因直肠肿瘤在外院手术治疗，具体术式不清。检查见左下腹部旁正中12厘米直切口瘢痕，其外侧有一肠造口，肛门已不存在。患者一般状况尚好，肠造口排便正常。肝脏 CT 见右后叶下段肝内有一直径 2.5cm结节，环周强化明显，血 CEA 升高，AFP、CA19-9 正常。最佳治疗方法是",[["A","右半肝切除术"],["B","肝部分切除术"],["C","肿瘤射频消融"],["D","全身化疗"]],"B","老年患者，直肠癌术后1年余，考虑为非姑息性手术，同时患者腹部为旁正中切口，左下腹单腔造口，不存在肛门（Miles手术需于左下腹行永久性乙状结肠单腔造口，术后无肛门），说明该患者直肠癌术式为Miles术，现患者一般状况尚好（转移性肝癌较小时，一般无症状），肝脏CT见右后叶下段肝内有一直径2.5cm结节，环周强化明显（肝转移癌增强CT可出现环状强化或结节性强化），血CEA升高（胃肠道肝转移病人，CEA阳性率约50%），AFP正常（转移性肝癌AFP升高者较少）、CA19-9正常（不考虑肺转移癌），应首先考虑的诊断是转移性肝癌，单发肝转移癌最有效的方法是肝部分切除术，本例一般情况可，且肿瘤单发，位于右下叶后段内，为可切除性转移瘤，故首选肝部分切除术（B对），手术原则要求最大限度保留健康肝组织。右半肝切除术（A错）可达到切除目的，但对正常肝组织损伤过大。肿瘤射频消融（C错）多适用于无法耐受手术患者，不作首选。全身化疗（D错）对于肝肿瘤效果较差，必要时可采用选择性肝动脉栓塞（化疗）。","c136","N"],["2019-N103",53,"第二节 腰椎退行性疾病","MRI",2019,103,"A","","男性，55岁。腰痛3个月。查体：L4、5水平棘突间压痛。双下肢无畸形，肌力正常，双侧膝反射正常，跟腱反射未引出；双下肢肢体深浅感觉对称、正常，鞍区痛、触觉减退。为明确诊断，应首选的检查是",[["A","X线片"],["B","MRI"],["C","肌电图"],["D","脊髓造影"]],"B","中年男性，L4、5水平棘突间压痛（腰间盘突出症多发症状），双下肢无畸形，肌力正常，双侧膝反射正常（L5神经根受累膝反射可无改变），跟腱反射未引出（S1神经根受累腱反射障碍）；双下肢肢体深浅感觉对称、正常，鞍区痛、触觉减退（提示马尾受累），疑腰椎间盘突出症，为明确诊断，应首选的检查是MRI（B对），MRI对软组织的分辨率高，整体观强，对诊断椎间盘突出有重要意义，通过不同层面的矢状像及椎间盘轴位像可以观察病变的形态及其所占椎管内的位置，此外还可了解椎间盘蜕变、椎管狭窄、马尾肿瘤等。X线（A错）可作常规检查，腰椎侧片对诊断有参考价值，但由于椎间盘不显影，故腰椎平片有时可示完全正常，无法从平片诊断有无椎间盘破裂和突出，需要其他辅助检查。肌电图（C错）有助于腰椎间盘突出的诊断，推断神经受损的节段，由于肌电图检查也会受到一些因素的干扰，应与其他检查及临床表现结合来进行分析判断，不作为本病的首选检查。脊髓造影（D错）亦为诊断腰椎间盘突出症的一项检查方法，为有创检查，现在临床应用较少，不作常规首选，在一般诊断方法不能明确时作为辅助检查，需慎重。","c137","N"],["2019-N104",53,"第二节 腰椎退行性疾病","腰椎管狭窄症",2019,104,"A","","男性，55岁。腰痛3个月。查体：L4、5水平棘突间压痛。双下肢无畸形，肌力正常，双侧膝反射正常，跟腱反射未引出；双下肢肢体深浅感觉对称、正常，鞍区痛、触觉减退。本病与腰椎管狭窄进行鉴别诊断的要点是",[["A","下腰痛"],["B","持续跛行"],["C","症状多阳性体征少"],["D","鞍区感觉异常"]],"C","中年男性，L4、5水平棘突间压痛（腰间盘突出症多发症状），双下肢无畸形，肌力正常，双侧膝反射正常（L5神经根受累膝反射可无改变），跟腱反射未引出（S1神经根受累腱反射障碍）；双下肢肢体深浅感觉对称、正常，鞍区痛、触觉减退（提示马尾受累），疑腰椎间盘突出症。腰椎管狭窄症是一种临床综合征，其定义并没有统一标准，普遍认为是指除外腰椎管狭窄的独立的临床疾病以外的任何原因引起的椎管、神经根管和椎间孔等任何形式的狭窄，并引起马尾神经或神经根受压的综合征，故有时腰椎间盘突出就是椎管狭窄的原因，但真正意义的腰椎管狭窄症不应包括椎间盘突出症。二者症状相似，主要鉴别点在于腰椎管狭窄相对腰椎间盘突出症的症状多，阳性体征少（C对），前者直腿抬高试验常为阴性。下腰痛（A错）、鞍区感觉异常（D错）为二者均可出现的症状，无法作为鉴别点。间歇性跛行是腰椎管狭窄的特异性表现，故在腰椎间盘突出和腰椎管狭窄症时均可出现（3版八年制外科学P973）。持续跛行（B错）可出现于多种疾病，不能作为特异性临床表现用于二者的鉴别诊断。","c137","N"],["2019-N105",53,"第二节 腰椎退行性疾病","腰椎间盘突出症非手术治疗",2019,105,"A","","男性，55岁。腰痛3个月。查体：L4、5水平棘突间压痛。双下肢无畸形，肌力正常，双侧膝反射正常，跟腱反射未引出；双下肢肢体深浅感觉对称、正常，鞍区痛、触觉减退。首选的治疗方案是",[["A","微创髓核摘除术"],["B","椎板切除减压术"],["C","非手术治疗"],["D","椎板减压加椎弓根钉内固定术"]],"C","中年男性，L4、5水平棘突间压痛（腰间盘突出症多发症状），双下肢无畸形，肌力正常，双侧膝反射正常（L5神经根受累膝反射可无改变），跟腱反射未引出（S1神经根受累腱反射障碍）；双下肢肢体深浅感觉对称、正常，鞍区痛、触觉减退（提示马尾受累），疑腰椎间盘突出症，首选的治疗方案是非手术治疗（C对ABD错）。大部分腰椎间盘突出症患者可经非手术治疗而愈，治疗原理是改变椎间盘组织与受累神经根的相对位置或部分回纳，减轻对神经根的压迫，松解神经根的粘连，消除神经根的炎症，解除症状。手术治疗（ABD错）应用于病史超过半年经非手术治疗无效后的患者，或有效但仍反复发作且症状较重者，马尾综合征急症患者等情况（十版外科学P727）。首次发作或反复发作未经保守治疗属于手术的禁忌证（3版八年制外科学P977）。腰椎间盘突出症手术治疗指征为（八版黄家驷外科学P2787）：①腰椎间盘突出症病史超过半年，经过严格保守治疗无效者；或保守治疗有效，经常复发且疼痛较重者。②首次发作的腰椎间盘突出症疼痛剧烈，尤以下肢症状为著者，病人因疼痛难以行动及入眠，被迫处于屈髋屈膝侧卧位，甚至跪位。③出现单根神经麻痹或马尾神经受压麻痹的症状和体征。④病人中年，病史较长，影响工作或和生活。⑤病史虽不典型，经影像学检查，CT或MRI或椎管造影证实椎间盘对神经或硬膜囊有明显严重压迫。⑥腰椎间盘突出症合并有腰椎椎管狭窄。按照此观点，本题答案存在争议，但原答案为C。4版实用外科学认为出现鞍区感觉障碍，排尿困难等马尾症状者也属于手术的适应证，按照此观点，本题答案存在争议，但原答案为C。","c137","N"],["2019-N106",50,"第二节 上肢神经损伤","桡神经损伤",2019,106,"A","","男性，28岁。右前臂刀割伤半小时来诊。检查发现垂腕畸形，掌指关节不能主动伸直。下列处理方法中，不正确的是",[["A","神经探查修补术"],["B","肌腱、血管探查"],["C","前臂骨筋膜室切开减压术"],["D","伤口清创术"]],"C","青年男性，右前臂刀割伤半小时来诊，垂腕，掌指关节不能主动伸直（提示桡神经损伤），前臂外伤致桡神经损伤，早期应行神经探查修补术（A对），有助于早期恢复神经的连续性，保留神经功能；肌腱、血管探查（B对）可探查肌腱血管合并伤，可同时一期修复；伤口清创术（D对）可将污染伤口变为清洁伤口，可以一期闭合。患者目前无前臂骨筋膜室综合征表现，暂不需行前臂骨筋膜室减压术（C错，为本题正确答案），盲目切开减压可加剧局部软组织伤。","","N"],["2019-N107",50,"第二节 上肢神经损伤","桡神经损伤",2019,107,"A","","男性，29岁。右前臂刀割伤半小时来诊。检查发现垂腕畸形，掌指关节不能主动伸直。可能损伤的神经是",[["A","桡神经"],["B","尺神经"],["C","正中神经"],["D","尺动脉"]],"A","青年男性，右前臂刀割伤半小时来诊，垂腕（桡神经损伤典型表现），掌指关节不能主动伸直，最可能的诊断为桡神经（A对）损伤。尺神经（B错）损伤主要表现为骨间肌、蚓状肌、拇收肌麻痹所致环、小指爪形手畸形及手指内收、外展障碍。正中神经（C错）损伤表现为拇指对掌、指功能受限，拇指、示指屈曲受阻，前臂旋前不能或受限。尺动脉（D错）损伤表现为局部活动性出血，但因前臂尺动脉及桡动脉之间存在广泛的交通支，一般不出现明显的肢体坏死。","","N"],["2019-N134",18,"第三节 乳腺良性疾病","乳腺囊性增生病临床表现",2019,134,"B","","与月经周期相关的乳腺疾病是",[["A","乳腺纤维腺瘤"],["B","乳腺囊性增生病"],["C","乳管内乳头状瘤"],["D","乳腺癌"]],"B","与月经周期相关的乳腺疾病是乳腺囊性增生病（B对），因本病系内分泌功能失调所致，患者雌、孕激素比例失调，乳腺实质增生过度和复旧不全，故部分病人的疼痛具有周期性，往往在月经前疼痛加重，月经期间疼痛减轻或消失。乳房纤维腺瘤（A错）是因乳腺小叶内纤维细胞对雌激素的敏感性异常增高，可能与纤维细胞所含雌激素受体的量或质的异常有关，月经周期对肿块的大小无明显影响（十版外科学P247-P248）。乳管内乳头状瘤（C错）由扩张的导管壁的导管上皮和血管结缔组织呈树枝状、乳头状增生所形成的病变，与月经周期不相关（十版外科学P248）。乳腺癌（D错）由乳腺腺泡及导管细胞恶变导致，临床表现早期患侧乳房出现无痛、单发小肿块，当肿瘤累及Cooper韧带可出现“酒窝征”，若肿瘤继续增大可出现“橘皮样”改变，其临床表现与月经周期不相关（十版外科学P249）。","","N"],["2019-N135",18,"第三节 乳腺良性疾病","导管内乳头状瘤临床表现",2019,135,"B","","易出现乳头血性溢液的乳房疾病是",[["A","乳腺纤维腺瘤"],["B","乳腺囊性增生病"],["C","乳管内乳头状瘤"],["D","乳腺癌"]],"C","易出现乳头血性溢液的乳房疾病是乳管内乳头状瘤（C对），为其主要症状，乳管内乳头状瘤是由扩张的导管壁的导管上皮和血管结缔组织呈树枝状、乳头状增生所形成的病变，因瘤体常带有很多薄壁血管，故容易出血。乳腺纤维腺瘤（A错）临床表现多为乳房质韧肿物，一般无乳头溢液。乳腺囊性增生病（B错）少数病人可有乳头溢液，常为棕色、浆液性或血性液体。乳腺癌（D错）少数患者（5%～10%）第一症状是乳头溢液、乳头糜烂或乳头回缩。","","N"],["2019-N160",4,"第三节 肠外营养","肠外营养并发症及防治",2019,160,"X","","长期肠外营养可能出现的并发症有",[["A","肝功能异常"],["B","高磷血症"],["C","肠黏膜萎缩"],["D","细菌移位"]],"ACD","肠外营养的并发症主要有静脉导管相关并发症、代谢性并发症、脏器功能损害及代谢性骨病等。长期肠外营养支持时，肝脏所处的环境及功能状态与正常进食时明显不同，可能造成肝脏损害，功能异常（A对）和胆汁淤积等，以及长期禁食可导致肠黏膜萎缩（C对），肠黏膜上皮通透性增加，肠道免疫功能障碍，导致肠道细菌易位而引发肠源性感染（D对）；长期肠外营养会导致重要营养物质的缺乏，其发生与肠外营养的某种基质，如维生素、微量元素、氨基酸等供给不足有关，在20世纪70年代，由于认识不足，肠外营养未及时补充磷制剂，低磷血症时有发生，而高磷血症（B错）在临床上少见，可发生在急性肾衰竭、甲状旁腺功能低下等，常继发低钙血症。","","N"],["2019-N161",5,"第二节 浅部组织细菌性感染","丹毒临床表现",2019,161,"X","","丹毒的临床的特点有",[["A","主要致病菌为乙型溶血性链球菌"],["B","口腔溃疡可以是诱因"],["C","很少发生组织坏死"],["D","必要时可切开引流"]],"ABC","丹毒是以皮肤及其浅层淋巴结管网的感染，主要致病菌为乙型溶血性链球菌（A组-β溶血性链球菌）（A对），常由皮肤或黏膜的轻微损伤诱发，如足癣、口腔溃疡（B对）、鼻窦炎等，丹毒起病急，进展快，蔓延迅速，全身反应剧烈，易反复发作，可引起慢性淋巴水肿，丹毒很少有组织坏死或化脓（C对），故治疗以保守方法为主（D错），措施包括抬高患肢，局部可使用硫酸镁液湿敷（50%），全身应用抗菌药物，静脉滴注如青霉素、头孢类敏感抗生素。","","N"],["2019-N162",17,"第一节 甲状腺疾病","TSH抑制治疗",2019,162,"X","","下列甲状腺疾病中可用甲状腺素治疗的有",[["A","20岁以下弥漫性单纯性甲状腺肿"],["B","亚急性甲状腺炎"],["C","慢性淋巴细胞性甲状腺炎"],["D","甲状腺癌根治术后"]],"ABCD","20岁以下弥漫性单纯性甲状腺肿（A对）病人可给予小量甲状腺素或优甲乐，以抑制腺垂体TSH分泌，缓解甲状腺的增生和肿大。亚急性甲状腺炎（B对）典型病例呈甲亢期、甲减期和恢复期三期，其中病程较长伴甲减者，应加用甲状腺素替代治疗直到甲状腺功能恢复，一般疗程约3～6月。慢性淋巴细胞性甲状腺炎（C对）因正常甲状腺组织被破坏，远期多表现为甲减，须甲状腺素替代治疗。甲状腺癌根治术后（D对）应终身服用甲状腺素片或甲状腺素，以预防甲状腺功能减退及抑制TSH。","","N"],["2019-N163",32,"第四节 胆石症","胆囊结石临床表现",2019,163,"X","","胆囊结石可能发生的并发症有",[["A","梗阻性黄疸"],["B","胰腺炎"],["C","肠梗阻"],["D","胆囊癌"]],"ABCD","胆囊结石的并发症多由结石的梗阻引起，或起源于梗阻而发展起来的一些病理改变。由于胆囊的收缩，较小的结石由胆囊管进入胆总管而发生梗阻性黄疸（A对），若嵌顿于壶腹部，则可同时导致胰液分泌障碍，胰液反流至胰腺，引起胆源性胰腺炎（B对）。由于结石压迫引起胆囊炎症慢性穿孔，可造成胆囊十二指肠瘘或胆囊结肠瘘，大的结石可通过瘘管进入肠道，偶尔可以引起肠梗阻（胆石性肠梗阻）（C对）。并发症的发生及其严重性，一般与病程特别是病人的年龄有密切关系，结石及炎症的长期刺激可诱发胆囊癌（D对）。","","N"],["2019-N164",43,"第二节 姿态性畸形","脊柱侧凸",2019,164,"X","","下列属于非结构性脊柱侧凸的有",[["A","腰椎间盘突出合并脊柱侧凸"],["B","Marfan综合征合并脊柱侧凸"],["C","下肢不等长合并脊柱侧凸"],["D","姿势不正性脊柱侧凸"]],"ACD","脊柱侧凸分非结构性和结构性脊柱侧凸两大类。非结构性脊柱侧凸指脊柱及其支持组织无内在结构的固有改变，在侧方弯曲像或牵引像上畸形可矫正，针对病因治疗后，脊柱侧凸即能消除。腰椎间盘突出者脊柱侧凸（A对）为缓解疼痛的强迫体位；下肢不等长脊柱侧凸（C对）及姿势不良性脊柱侧凸（D对）均为平衡躯体重心而产生的代偿，脊柱及其支持组织结构并无变化。以上均属于非结构性脊柱侧凸。Marfan综合征，为一种遗传性结缔组织疾病（常染色体显性遗传），典型患者运动系统临床表现主要有长骨细长，蜘蛛指（趾），肌肉发育不良，肌张力降低，关节活动度过度，可有脊柱侧凸和脊柱后凸畸形，其脊柱侧凸伴脊柱及其支持组织的改变，属于结构性脊柱侧凸（B错）。","","N"],["2019-N165",55,"第二节 脊柱结核","X线平片",2019,165,"X","","成人脊柱结核区别于脊柱肿瘤的X线特点有",[["A","椎体骨质破坏"],["B","椎间隙狭窄或消失"],["C","脊柱侧弯或后凸畸形"],["D","椎旁软组织阴影增宽"]],"BD","成人脊柱结核区别脊柱肿瘤X线特点包括：脊柱结核X线平片表现为骨质破坏和椎间隙狭窄、消失，脊柱肿瘤一般只累及一个椎体，X线平片可见骨质破坏，常累及椎弓根，椎间隙不受累（B对），而脊柱结核往往首先破坏椎间隙；同时脊柱结核椎旁软组织影（腰大肌）增宽，但脊柱肿瘤通常无椎旁软组织影（D对）。二者均会出现椎体骨质破坏（A错）和脊柱侧弯或后凸畸形（C错）。","","N"],["2020-N58",18,"第四节 乳腺癌","乳腺癌病因和流行病学特点",2020,58,"A","","下列选项中，不属于乳腺癌促发因素的是",[["A","初潮年龄小"],["B","绝经期晚"],["C","哺乳"],["D","初产年龄大"]],"C","乳腺癌的病因尚未完全明了，但与以下因素有关：①内分泌因素：雌醇、雌二醇与乳腺癌的发病相关，催乳素有促进乳腺癌发病的作用，孕酮既有致癌又有抑癌的作用，临床上月经初潮早于12岁（A对），停经迟于55岁的发病率较高（B对），初产年龄迟于35岁者发病率高于初产在20岁以前者（D对），未婚未育者发病率高于已婚已育者。②饮食与肥胖：脂肪的摄取与乳腺癌的发病率正相关。③放射线照射以及乳汁因子与乳腺癌发病率亦有关。④家族史与遗传史。哺乳（C错，为本题正确答案）不属于乳腺癌的促发因素。","","N"],["2020-N59",25,"第一节 急性弥漫性腹膜炎","急性弥漫性腹膜炎诊断",2020,59,"A","","下列选项中，诊断急性弥漫性腹膜炎最重要的依据是",[["A","腹痛病史"],["B","症状和体征"],["C","B超提示腹腔积液"],["D","CT见肠管扩张"]],"B","对诊断急性弥漫性腹膜炎最有意义的是患者的症状和体征，腹痛是最主要的临床表现，一般很剧烈，呈持续性，难以忍受，腹部压痛、腹肌紧张、反跳痛是腹膜炎的标志性体征，腹胀加重是病情恶化的一项重要标志，根据患者病史及典型临床症状和体征，白细胞计数及分类，辅助影像学检查，腹膜炎的诊断一般比较容易。询问腹痛病史（A错）、超声和CT扫描有助于了解原发病因：各种原发疾病均有其本身的典型病史，超声提示腹腔积液（C错）但不能辨别液体性质，需穿刺抽液或腹腔灌洗可帮助诊断，如CT显示广泛肠管扩张提示麻痹性肠梗阻，孤立肠管扩张，提示肠扭转或闭襻型肠梗阻（D错）。","","N"],["2020-N60",28,"第二节 急性阑尾炎","阑尾管腔阻塞",2020,60,"A","","青少年容易发生急性阑尾炎的原因中，最重要的是",[["A","阑尾发育尚不健全"],["B","寄生虫造成阑尾梗阻"],["C","粪石阻塞阑尾管腔"],["D","阑尾淋巴滤泡组织增生致阑尾梗阻"]],"D","急性阑尾炎最主要的病因是阑尾管腔阻塞，青少年急性阑尾炎最重要的原因是阑尾管壁中淋巴滤泡明显增生导致阑尾管腔梗阻（D对），成年人急性阑尾炎的常见病因为管腔中的粪石或结石引起阑尾管腔梗阻（C错）。异物、炎性狭窄、食物残渣、寄生虫（蛔虫）、肿瘤等为较少见的原因（B错）。而阑尾本身结构管腔细长，开口狭小，有不同程度的卷曲，都是造成其容易阻塞的因素。阑尾发育尚不健全（A错），如阑尾过长、过度扭曲、管腔细小、血运不佳等均属于易于发生急性炎症的条件。","","N"],["2020-N61",32,"第一节 胆道系统解剖生理概要","胆汁的分泌和功能",2020,61,"A","","正常成人每日胆汁分泌量是",[["A","200-600ml"],["B","800-1200ml"],["C","1300-1700ml"],["D","1800-2200ml"]],"B","胆汁主要由肝细胞分泌，正常成人每日的胆汁分泌量约800～1200ml（B对）。","","N"],["2020-N62",32,"第十节 胆囊息肉和良性肿瘤","胆囊息肉治疗",2020,62,"A","","女性，45岁。B超发现胆囊多发息肉样病变，最大直径0.6cm，无症状。对此患者的正确处理是",[["A","胆囊切除术"],["B","保留胆囊、息肉摘除术"],["C","观察，定期复查"],["D","熊去氧胆酸溶解息肉"]],"C","胆囊息肉的外科治疗指征为：胆囊单发息肉直径超过10mm，患者年龄＞50岁，有明显症状，合并胆囊结石；胆囊颈部有息肉引起胆囊管梗阻者。当怀疑恶变或直径≥20mm行开腹手术，≤10mm，可行腹腔镜手术。本例患者45岁（＜50岁），胆囊息肉最大直径0.6cm（＜1cm），无明显临床症状，无其他合并症，不属于外科治疗指征（AB错）。对于直径＜10mm的单发或多发息肉，应先联系观察追踪半年，如稳定不增大，则需要定期检查（C对）。熊去氧胆酸为利胆药物，反馈性抑制胆汁酸合成，引起胆汁流动，调节胆固醇合成与消除，促进脂溶性维生素和脂质的吸收等，主要用于治疗胆结石、胆汁淤积性肝病、胆囊炎等（D错）。","","N"],["2020-N63",19,"第五节 创伤性窒息","创伤性窒息治疗",2020,63,"A","","下列胸部创伤性疾病中，一般采用非手术治疗的是",[["A","创伤性窒息"],["B","血胸"],["C","张力性气胸"],["D","开放性气胸"]],"A","胸部损伤疾病中，张力性气胸（C错）、开放性气胸（D错）一般紧急处理后，都需要进一步行闭式胸腔引流术。血胸（B错）若为少量则可自行吸收，但进行性血胸及中等量以上都需要及时开胸探查。创伤性窒息（A对）的病人需严密观察，形成的出血点及瘀斑多可自行吸收。","","N"],["2020-N64",1,"","",2020,64,"A","","下列液体中，其渗透压高于血浆的是",[["A","Ringer液"],["B","5%葡萄糖溶液"],["C","5%碳酸氢钠溶液"],["D","1.87%乳酸钠溶液"]],"C","5%碳酸氢钠（C对）属于高渗溶液，渗透压大于血浆渗透压。Ringer液（林格氏液）为生理盐水中加入氯化钾、氯化钙，属于等渗溶液（A错）。5%葡萄糖溶液（B错）的渗透压为278mOsm/L，属于等渗溶液。1.87%乳酸钠溶液（D错）属于等渗溶液。","","N"],["2020-N65",44,"第二节 骨折的临床表现及影像学检查","骨折局部表现",2020,65,"A","","骨折的临床诊断中，错误的是",[["A","骨折的特有体征包括畸形、反常活动、骨擦音或骨擦感"],["B","具有骨折特有体征之一者，即可诊断为骨折"],["C","检查可疑骨折病人时，应诱发骨擦音或骨擦感，以明确诊断"],["D","临床未见骨折特有体征，不能排除骨折"]],"C","骨折的特有体征包括畸形、反常活动、骨擦音或骨擦感（A对）。在骨折的临床诊断中，以上三种体征只要发现其中一种，即可确诊（B对），但需要注意的是，未见此三种体征时，也有可能有骨折（D对），例如嵌插、裂缝骨折等，在初次检查患者时应小心谨慎，不可故意反复多次检查使特有体征发生，以免加重周围组织损伤，特别是重要血管、神经损伤（C错，为本题正确答案）。","","N"],["2020-N66",57,"第五节 转移性骨肿瘤","转移性骨肿瘤概述",2020,66,"A","","骨转移癌中，最常见的原发癌是",[["A","甲状腺癌"],["B","乳腺癌"],["C","前列腺癌"],["D","肾癌"]],"B","转移性骨肿瘤是指原发于骨外器官或组织的恶性肿瘤，经血行或淋巴转移至骨骼并继续生长，形成子瘤。好发于躯干骨，常发生骨转移的肿瘤依次为乳腺癌（B对）、前列腺癌（C错）、肺癌、甲状腺癌（A错）和肾癌（D错）等。","","N"],["2020-N67",54,"第一节 化脓性骨髓炎","慢性血源性骨髓炎治疗",2020,67,"A","","男性，20岁。胫骨中上段慢性骨髓炎，一般情况好，体温正常，局部有流脓窦道，X线片有3cm×1cm死骨，周围包壳完整。下列选项中不考虑的治疗方式是",[["A","手术摘除死骨，肌瓣填塞消灭死腔"],["B","手术摘除死骨，庆大霉素-骨水泥珠链填塞和二期植骨"],["C","病灶清除术，伤口一期缝合，负压吸引"],["D","患肢管型石膏固定，开窗换药，全身大量应用抗生素"]],"D","青年男性患者，胫骨中上段慢性骨髓炎，局部有流脓窦道，X片显示有3cm×1cm死骨（有死骨形成），周围包壳完整，一般情况良好，无发热，该患者的基本情况符合慢性骨髓炎手术治疗指征，手术需要解决以下三个问题：清除病灶、消灭死腔、伤口的闭合。清除病灶要摘除死骨，吸尽脓液，切除坏死组织和肉芽组织，边缘带血管组织通常也要切除。消灭死腔的方式有：碟形手术（Orr开放手术法）适用于死腔较小患者；肌瓣填塞适用于死腔较大者（A对）；抗生素骨水泥珠链如庆大霉素-骨水泥珠链填塞和二期植骨（B对）；闭式灌洗适用于小儿患者。伤口的闭合应为一期缝合，并留置负压吸引管（C对），当周围软组织缺少不能缝合时，应敞开伤口，骨腔内填充凡士林纱布或碘纺纱条，包管形石膏，开窗换药；本例患者采取手术治疗，术前需进行细菌培养和药敏试验，在术前两日开始使用抗生素为最佳，保证手术部位组织有足够的抗生素浓度，同时术后应选择针对多数致病菌有效的广谱抗生素进行全身治疗，本例患者一般情况良好，体温正常，不需大剂量使用抗生素（D错，为本题正确答案）。","","N"],["2020-N93",32,"第三节 胆道畸形","先天性胆管扩张症诊断",2020,93,"A","","女性，43岁。1年来经常右上腹胀痛，有时出现黄疸、发热。外院发现胆总管扩张并有结石，行胆囊切除、胆总管探查术，取出结石一枚。术后3周经T管造影，结果显示：胆总管扩张，直径约5cm，腔内未见明显结石，肝内胆管未见扩张，十二指肠显影正常，胰管显影。此结果提示",[["A","胆总管残余结石"],["B","胆总管下段肿瘤"],["C","正常胆道影像"],["D","先天性胆管扩张症"]],"D","中年女性，经常右上腹痛，间歇性黄疸，发热一年（胆管扩张症典型症状），外院发现胆总管扩张并有结石，行手术取石（胆管扩张症合并胆结石），术后影像学提示胆总管扩张，直径5cm（正常成年人胆总管全长4～8cm，口径0.6～0.8cm）（C错），腔内未见明显结石（A错），肝内胆管未见扩张，十二指肠影像正常，胰管显影（胆管扩张症影像学表现，囊性扩张），根据患者病史、影像学检查结果，最可能的原因为胆管扩张症，即成人先天性胆管扩张症（D对），该病大多数病人在10岁以前得到诊治，部分病人到成年之后才表现出临床症状。胆总管下端肿瘤（B错）临床表现多为进行性无痛性黄疸，包括深色尿、巩膜、皮肤黄染，陶土便及瘙痒，影像学提示肿瘤上方胆管扩张。","c147","N"],["2020-N94",32,"第八节 胆道疾病常见并发症","胆道出血治疗",2020,94,"A","","女性，43岁。1年来经常右上腹胀痛，有时出现黄疸、发热。外院发现胆总管扩张并有结石，行胆囊切除、胆总管探查术，取出结石一枚。术后3周经T管造影，结果显示：胆总管扩张，直径约5cm，腔内未见明显结石，肝内胆管未见扩张，十二指肠显影正常，胰管显影。下列进一步的治疗措施中，首选的是",[["A","胆道镜取石"],["B","Whipple手术"],["C","肝外胆管切除、胆肠吻合术"],["D","拔除T管，继续观察"]],"C","中年女性，经常右上腹痛，间歇性黄疸，发热一年（胆管扩张症典型症状），外院发现胆总管扩张并有结石，行手术取石（胆管扩张症合并胆结石），术后影像学提示胆总管扩张，直径5cm（正常成年人胆总管全长4～8cm，口径0.6～0.8cm），腔内未见明显结石（A错），肝内胆管未见扩张，十二指肠影像正常，胰管显影（胆管扩张症影像学表现，囊性扩张），根据患者病史、影像学检查结果，最可能的原因为胆管扩张症，即成人先天性胆管扩张症，该病大多数病人在10岁以前得到诊治，部分病人到成年之后才表现出临床症状，因本病频繁发作和各种并发症（反复发作易导致肝硬化、癌变或囊状扩张破裂等）需要尽早治疗，原则是早期手术以减轻症状和防止远期并发症，首选的手术方式为切除扩张胆管和胆管空肠Roux-en-Y吻合（C对），长期随访80%病理得到满意效果。Whipple（胰头十二指肠切除术）是治疗胰腺癌、壶腹周围癌等疾病的外科手段（B错）。若胆道通常无结石和其他病变，T管拔除时间为术后4周左右（D错）。","c147","N"],["2020-N95",13,"第一节 术前准备","心血管病",2020,95,"A","","女性，65岁。胆囊结石10年，近来反复发作胆绞痛，要求手术治疗。有高血压、糖尿病病史，服药血压维持在150～160/85～95mmHg，空腹血糖7.3mmol/L。患者术前处理措施中，正确的是",[["A","血压降至130/90mmHg再手术"],["B","血糖降至6.1mmol/L再手术"],["C","血糖、血压均正常后再手术"],["D","不需特殊处理，可手术"]],"D","老年女性患者，现因胆囊结石欲行择期手术，有高血压、糖尿病病史，服药血压维持在150～160/85～95mmHg（＜160/100mmHg，不做特殊处理），空腹血糖7.3mmol/L（成人空腹血糖正常值3.9～6.1mmol/L，术前需维持空腹血糖轻度升高状态），可不做特殊术前处理（D对ABC错）。","c148","N"],["2020-N96",32,"第四节 胆石症","胆囊结石治疗",2020,96,"A","","女性，65岁。胆囊结石10年，近来反复发作胆绞痛，要求手术治疗。有高血压、糖尿病病史，服药血压维持在150～160/85～95mmHg，空腹血糖7.3mmol/L。患者行腹腔镜胆囊切除术，手术顺利。术后前3天引流管微黄清亮液体15～20ml/日，拔除引流管。术后10天觉右上腹不适来院复查，T37.2℃，血WBC9.0×10⁹/L，N75%，B超发现胆囊窝处4～5cm液性暗区，穿刺抽出黄色液体似胆汁。最合理的处理是",[["A","穿刺置管引流"],["B","局部理疗"],["C","加用抗生素"],["D","手术引流"]],"A","本例患者行腹腔镜胆囊切除术后，觉右上腹不适，查体，T：37.2℃（正常体温36～37℃，体温稍高），WBC：9×10⁹/L（正常值3.5～9.5×10⁹/L），N75%（正常值0.5～0.75），B超示胆囊腋窝处4～5cm的液性暗区，穿刺抽出黄色液体似胆汁（胆瘘可有影像学表现），根据患者病史、临床表现体征、实验室检查结果及影像学结果，最可能的诊断是胆囊切除术后并发胆瘘，本例患者基本情况良好，暂无严重感染、腹膜炎表现，最合适的处理是穿刺置管引流（A对BD错）。加用抗生素（C错）也属于本例治疗方案内容，但最重要的治疗措施为穿刺置管引流。","c148","N"],["2020-N97",17,"第一节 甲状腺疾病","单纯性甲状腺肿诊断",2020,97,"A","","女性，53岁。诊断结节性甲状腺肿2年，近日突觉颈部胀痛，复查B超见左叶结节较1年前增大，直径由1.8cm变为2.6cm，呈囊实性，部分囊壁可见片状钙化。可能的诊断是",[["A","恶性变"],["B","囊内出血"],["C","亚急性甲状腺炎"],["D","桥本甲状腺炎"]],"B","中年女性，诊断结节性甲状腺肿2年，近日突觉颈部胀痛，B超检查左叶结节增大，呈囊实性，部分囊壁可见片状钙化，此时该患者的诊断应为结节性甲状腺肿。因长时间血液循环不良，结节内发生退行性变，导致囊肿形成，并发囊内出血（B对），并有局部的纤维化和钙化。亚急性甲状腺炎（C错）是最常见的痛性甲状腺疾病，是一种与病毒感染有关的自限性甲状腺炎，绝大多数可以治愈，一般不遗留甲状腺功能减退症，起病前1～3周常有病毒性咽炎、腮腺炎、麻疹或其他病毒感染的症状。桥本甲状腺炎（D错）为甲状腺炎最常见的临床类型，病程较长，甲状腺呈弥漫性、无痛性的轻度或中度肿大，质地坚韧，较硬，发展缓慢，可有轻压痛、颈部局部压迫，常有咽喉部不适感，血TgAb或TPOAb阳性。本例可癌变，目前提供的临床证据暂不支持恶性变（A错）。","c149","N"],["2020-N98",17,"第一节 甲状腺疾病","单纯性甲状腺肿治疗",2020,98,"A","","女性，53岁。诊断结节性甲状腺肿2年，近日突觉颈部胀痛，复查B超见左叶结节较1年前增大，直径由1.8cm变为2.7cm，呈囊实性，部分囊壁可见片状钙化。此时最适宜的处理是",[["A","对症治疗"],["B","甲状腺大部切除术"],["C","穿刺抽液"],["D","甲状腺结节切除术"]],"A","该患者诊断为结节性甲状腺肿2年，近期发现有囊内出血钙化，左叶结节增大。该患者目前未出现压迫症状，无需进行穿刺引流（C错）或手术治疗（BD错），给予对症治疗（A对）即可。","c149","N"],["2020-N99",17,"第一节 甲状腺疾病","手术治疗",2020,99,"A","","女性，53岁。诊断结节性甲状腺肿2年，近日突觉颈部胀痛，复查B超见左叶结节较1年前增大，直径由1.8cm变为2.8cm，呈囊实性，部分囊壁可见片状钙化。两年后复查B超发现右叶腺体有沙粒样钙化。拟行的治疗方案是",[["A","继续保守治疗"],["B","右叶全切、左叶次全切除术"],["C","右叶全切除术"],["D","双叶次全切除术"]],"B","中年女性，诊断结节性甲状腺肿2年，近日突觉颈部胀痛，B超检查左叶结节增大，呈囊实性，部分囊壁可见片状钙化，该患者的诊断为甲状腺结节囊内出血，两年后复查B超发现右叶腺体有沙粒样钙化，此时高度怀疑甲状腺结节恶性变，即甲状腺癌，该患者目前的诊断为甲状腺左叶结节性甲状腺肿，甲状腺右叶甲状腺癌。甲状腺癌手术切除范围需至少切除病变腺叶，考虑到该患者左侧甲状腺结节有囊内出血病史，疑发展为甲状腺癌，应及时行次全切，故该患者拟行的治疗方案是右叶全切、左叶次全切除术（B对），有证据显示甲状腺近全或全切除术后复发率较低。","c149","N"],["2020-N100",29,"第七节 直肠癌","低位前切除术",2020,100,"A","","男性，62岁，因大便有脓血1个月入院。肛门指诊在距肛缘7cm处触及直径4cm大小肿物，中间有溃疡，活检病理：中分化腺癌。全身检查无阳性发现，肝肺未见转移。应采取的手术方式是",[["A","乙状结肠造口术"],["B","Miles术"],["C","Dixon术"],["D","Hartmann术"]],"C","老年男性直肠癌患者，病理示中分化腺癌（Ⅱ级），癌肿直径4cm，距肛缘7cm，暂无转移表现，故最适合的手术方式是Dixon手术（C对），适用于肿瘤下缘距肛门5～7cm的直肠癌，该手术方式保留肛门括约肌，是直肠癌切除术控制排便功能最为满意的一项手术，目前为低位直肠癌施行保肛手术的首选术式。乙状结肠造口术（A错）属于晚期直肠癌的姑息手术，适用于患者发生排便困难或肠梗阻时，目的为解除痛苦和处理并发症。Miles手术（经会阴切除术）（B错），适用于距肛门5cm以内的直肠癌（若肿瘤较大、浸润明显、骨盆狭窄的肥胖患者、肿瘤范围浸润较大患者7cm以内也可行该手术），该手术损伤较大，需永久性乙状结肠造口。Hartmann手术（经腹直肠癌切除、近端造口、远端封闭手术）（D错）适用于全身一般情况很差，不能耐受Miles手术或急性梗阻不宜行Dixon手术的病人。","c150","N"],["2020-N101",29,"第七节 直肠癌","直肠癌诊断",2020,101,"A","","男性，62岁，因大便有脓血1个月入院。肛门指诊在距肛缘7cm处触及直径4cm大小肿物，中间有溃疡，活检病理：中分化腺癌。全身检查无阳性发现，肝肺未见转移。术后化疗5个疗程。2年后复查CT，发现左肝2个直径2～3cm结节，边缘清晰，强化明显，呈“牛眼征”。最可能的诊断是",[["A","直肠癌肝转移"],["B","原发性肝癌"],["C","肝多发血管瘤"],["D","多发肝囊肿"]],"A","老年男性直肠癌患者（转移性肝癌原发肿瘤），行Dixion术后化疗5个疗程，2年后复查，影像学显示左肝2个直径为2～3cm结节，边缘清晰，强化明显，呈“牛眼征”（转移性肝癌影像学特征性表现），影像学检查在发现继发性肝癌诊断中有重要价值，继发性肝癌在各种影像学检查中多显示多发、散在、大小相仿或相差不大的占位性病变，多无肝硬化征象，根据患者病史和影像学表现，该患者最可能的诊断是直肠癌肝转移（A对）。原发性肝癌（B错）发病与肝硬化、病毒性肝炎以及黄曲霉素等因素有关，临床表现多为肝区疼痛、肝大、右上腹肿块等，全身表现为乏力、消瘦、食欲减退、黄疸等，甲胎蛋白、超声、CT有助于诊断。肝多发血管瘤（C错）属于肝脏良性肿瘤，有赖于影像学、肝功能等多种检查联合诊断，影像学首选B超（典型表现为边界清晰的低回声占位伴有后方不甚明显的回声增强效应），次选MRI、CT或核素标记红细胞扫描，临床表现与肿瘤的大小有关，较大时牵拉肝被膜或压迫胃肠道邻近组织可有相关症状。多发肝囊肿（D错）为肝脏良性疾病，超声是诊断的首选方法，典型表现为圆形或卵圆形的液性暗区，边界光滑清晰，后壁肝组织回声增强，本病还应注意肾、肺、胰以及其他脏器有无囊肿或先天畸形。","c150","N"],["2020-N102",30,"第五节 转移性肝肿瘤","转移性肝肿瘤治疗",2020,102,"A","","男性，62岁，因大便有脓血1个月入院。肛门指诊在距肛缘7cm处触及直径4cm大小肿物，中间有溃疡，活检病理：中分化腺癌。全身检查无阳性发现，肝肺未见转移。术后化疗5个疗程。2年后复查CT，发现左肝2个直径2~3cm结节，边缘清晰，强化明显，呈“牛眼征”。此时最合理的治疗方法是",[["A","继续化疗"],["B","左半肝切除术"],["C","观察"],["D","介入治疗"]],"B","老年男性直肠癌患者（转移性肝癌原发肿瘤），行Dixion术后化疗5个疗程，2年后复查，影像学显示左肝2个直径为2～3cm结节，边缘清晰，强化明显，呈“牛眼征”（转移性肝癌影像学特征性表现），影像学检查在发现继发性肝癌诊断中有重要价值，继发性肝癌在各种影像学检查中多显示多发、散在、大小相仿或相差不大的占位性病变，多无肝硬化征象，根据患者病史和影像学表现，该患者最可能的诊断是直肠癌肝转移，影像学提示转移癌肿局限在半肝内，且原发肿瘤已被切除，故最合理的治疗是左肝叶切除（B对C错）。化疗（A错）用于手术后的综合治疗，或原发和继发病灶均属于晚期，仅能进行化疗、放疗、生物治疗和中医中药治疗的患者。介入治疗（D错）用于不宜手术的原发性肝癌，或术后复发的转移性肝癌。","c150","N"],["2020-N103",45,"第九节 前臂双骨折","前臂双骨折临床表现和诊断",2020,103,"A","","男性，50岁。因车轮碾压致左前臂外伤5小时。查体：神志清楚，左前臂明显肿胀疼痛，皮肤瘀斑，出血，成角畸形。应首先考虑的诊断是",[["A","桡骨头脱位"],["B","尺骨骨折"],["C","桡骨骨折"],["D","尺、桡骨骨折"]],"D","50岁男性患者，前臂碾压外伤史（尺桡骨骨折常见原因），查体患者基本情况良好，左前臂明显肿胀疼痛，皮肤瘀斑、出血，成角畸形（尺桡骨骨折临床表现），根据该患者受伤史、临床表现和体征，应诊断为尺、桡骨骨折（前臂双骨折）（D对）。尺骨骨折（B错）在西方被称之为“警棍骨折”，其多由于防护性动作致伤，多为直接碰撞、打击所引起，如摔倒时前臂内侧（尺侧）先着地，因尺骨位于皮下，配合前臂正侧位X光检查，易于诊断。桡骨骨折（C错）发生率少于尺骨骨折，多发生于青壮年或儿童，多有旋转移位，患者前臂旋后运动完全丧失，患侧手向桡侧屈曲或旋转前臂，旋转范围可不受限，但因其局部疼痛加剧，配合前臂正侧位X光检查，易于诊断。桡骨头脱位（A错）俗称牵拉肘，是小儿多见的日常损伤，多见于5岁以内儿童，为肘关节处于伸直位时，前臂旋前时突然受到牵拉致伤，查体前臂多呈旋前位半屈，患者多有哭闹，不肯使用患肢特别是举起前臂，桡骨头处可有压痛，但无肿胀及畸形，肘关节活动明显受限。","","N"],["2020-N104",45,"第九节 前臂双骨折","前臂双骨折手法复位外固定",2020,104,"A","","男性，50岁。因车轮碾压致左前臂外伤6小时。查体：神志清楚，左前臂明显肿胀疼痛，皮肤瘀斑，出血，成角畸形。该患者治疗方案选择手法复位外固定的依据是",[["A","受伤时间较短的开放性骨折"],["B","稳定性骨折"],["C","神经血管损伤"],["D","合并肌腱损伤"]],"B","50岁男性患者，前臂碾压外伤史（尺桡骨骨折常见原因），查体患者基本情况良好，左前臂明显肿胀疼痛，皮肤瘀斑、出血，成角畸形（尺桡骨骨折临床表现），根据该患者受伤史、临床表现和体征，应诊断为尺、桡骨骨折（前臂双骨折），对于一些位移不显著，较为稳定的骨折，在臂神经丛阻滞下进行手法复位外固定，可以得到满意的闭合复位（B对），前臂双骨折可接受的整复标准是：桡骨旋转畸形不能大于30°，尺骨旋转畸形不能大于10°，尺桡骨的成角畸形不得大于10°（不符合以上标准的，应直接进行手术切开复位内固定，以便获得良好的功能结果）（七版黄家驷外科学P2799）。损伤时间较短的开放性骨折（A错）、合并血管神经损伤（C错）、伴有肌腱损伤（D错）属于切开复位内固定的手术指征。","c151","N"],["2020-N105",44,"第三节 骨折的并发症","骨筋膜隔室综合征",2020,105,"A","","男性，50岁。因车轮碾压致左前臂外伤6小时。查体：神志清楚，左前臂明显肿胀疼痛，皮肤瘀斑，出血，成角畸形。患者经手法复位，小夹板固定4小时后，感觉患肢剧痛，手指麻木，肿胀，活动时疼痛加重，可能的原因是",[["A","神经损伤"],["B","骨筋膜室综合征"],["C","急性骨髓炎"],["D","缺血性骨坏死"]],"B","50岁男性患者，前臂碾压外伤史（尺桡骨骨折常见原因），查体患者基本情况良好，左前臂明显肿胀疼痛，皮肤瘀斑、出血，成角畸形（尺桡骨骨折临床表现），根据该患者受伤史、临床表现和体征，应诊断为尺、桡骨骨折（前臂双骨折），患者经手法复位，小夹板固定4小时（骨筋膜室综合征常见原因），感觉患肢剧痛，手指肿胀、麻木，活动时疼痛加剧（骨筋膜室综合征典型临床表现），则出现该情况可能的原因是骨筋膜室综合征（B对）。所有外固定均应注意松紧度，避免压迫引起皮肤、肌肉坏死、骨筋膜室综合征。神经损伤（A错）应发生相对应的神经功能障碍，包括肌肉的控制和感觉障碍，如桡神经损伤（多为肱骨干骨折导致）时可有垂腕等表现；正中神经损伤（偶为肱骨髁上骨折导致）时可有拇、示、中指不能屈曲，拇指不能外展和对掌等；尺神经损伤（多在腕部和肘部损伤）时可有小指感觉消失，环、小指末节屈曲功能障碍等，与患者临床表现不符。缺血性骨坏死（D错）属于骨折的晚期并发症，为骨折段的血液供应被切断导致发生缺血性坏死，常见的有腕舟状骨骨折后近侧骨折端缺血性坏死，股骨颈骨折后股骨头缺血性坏死。急性骨髓炎（C错）除患处局部表现外，会有全身中毒症状，如起病急，伴有高热，寒战，精神不振，消化道症状，严重者可发生中毒性休克，还应注意与发病相关的病史，包括可能的潜在的血源感染源、药物治疗史等。","c151","N"],["2020-N106",57,"第二节 良性骨肿瘤","骨软骨瘤",2020,106,"A","","男性，14岁。无意中发现右膝内下一圆形肿物，质硬，固定，局部无红肿热痛，X线片显示右胫骨上端有一骨性突起，皮质和松质骨以宽广的蒂与正常骨相连。最可能的诊断是",[["A","骨样骨瘤"],["B","骨肉瘤"],["C","骨软骨瘤"],["D","骨巨细胞瘤"]],"C","青少年男性患者，无意中发现右膝内下一圆形肿物（骨软骨瘤常见发现方式），质硬，固定（骨软骨瘤可有临床表现），局部无红肿热痛（无感染表现），X线显示右胫骨上端有一骨性突起，皮质和松质骨以宽大的蒂与正常骨相连（骨软骨瘤典型影像学表现），根据患者的临床表现和影像学检查结果，最可能的诊断是骨软骨瘤，又称外生性骨疣，单发常见于儿童或青少年，好发于长骨干骺端，特别是股骨下端、胫骨上端、肱骨上端。骨样骨瘤（A错）典型的临床表现为持续数月的钝痛，夜间加重，服用水杨酸或非甾体消炎药可缓解，影像学表现为骨干皮质内，呈现小的圆形或椭圆形的放射性透明巢，直径常小于1cm，多有致密的硬骨包绕。骨巨细胞瘤（D错）是一种具有局部侵袭性的原发良性骨肿瘤，典型临床表现为疼痛、肿胀，关节活动受限常见，可有病理性骨折，突发剧痛可为首发症状，影像学表现通常显示偏心、膨胀的溶骨性破坏，骨巨细胞瘤在松质骨中表现为“肥皂泡样”改变。骨肉瘤（B错）为骨恶性肿瘤，也叫成骨肉瘤，最常见的临床症状为疼痛和肿块，初期为间歇性隐痛，多发展为持续性疼痛，体格检查可发现局部肿块，有疼痛和压痛，局部发热和毛细血管扩张，影像学上一些骨肉瘤成骨明显；另一些则以溶骨性破坏为主，可见呈蜂窝状，退行性变或呈毛细血管扩张样改变的肿瘤。","c152","N"],["2020-N107",57,"第二节 良性骨肿瘤","骨软骨瘤",2020,107,"A","","男性，14岁。无意中发现右膝内下一圆形肿物，质硬，固定，局部无红肿热痛，X线片显示右胫骨上端有一骨性突起，皮质和松质骨以宽广的蒂与正常骨相连。目前应该采取的处理是",[["A","根治性瘤段切除、假体植入"],["B","放化疗加免疫治疗"],["C","肿瘤切除术"],["D","不需治疗，观察"]],"D","青少年男性患者，无意中发现右膝内下一圆形肿物（骨软骨瘤常见发现方式），质硬，固定（骨软骨瘤可有临床表现），局部无红肿热痛（无感染表现），X线显示右胫骨上端有一骨性突起，皮质和松质骨以宽大的蒂与正常骨相连（骨软骨瘤典型影像学表现），根据患者的临床表现和影像学检查结果，最可能的诊断是骨软骨瘤，又称外生性骨疣，单发常见于儿童或青少年，好发于长骨干骺端，特别是股骨下端、胫骨上端、肱骨上端，该患者目前无明显症状，也无感染、恶变倾向，可暂不做手术，密切观察（D对ABC错），本病外科手术指征为：成年后持续生长；出现疼痛；影响关节活动；肿瘤较大影响外观；有邻近骨骼血管神经压迫；位于中轴部位，如骨盆、肩胛骨、脊柱等；怀疑有恶变倾向。","c152","N"],["2020-N132",31,"门静脉高压","食管胃底曲张静脉破裂出血非手术治疗(1)",2020,132,"B","","男性，53岁。乙肝肝硬化病史13年，中度至重度食管胃底静脉曲张，化验血Hb110g/L，WBC2.3×10⁹/L，Plt32×10⁹/L，肝功能Child-PughA级，无出血史。治疗方式应是",[["A","分流术"],["B","断流术"],["C","保守治疗"],["D","TIPS"]],"C","中年男性患者，乙肝肝硬化病史，中度至重度食管胃底静脉曲张，实验室检查Hb110g/L（正常成年男性130～175g/L，贫血），WBC2.3×10⁹/L（正常成年人3.5～9.5×10⁹/L，白细胞降低），PLT32×10⁹/L（正常成年人125～350×10⁹/L，血小板降低），肝功能Child-PughA级，无出血史，根据该患者的临床情况，该患者为肝硬化、食管胃底静脉曲张（暂无出血）、脾功能亢进，此时优先选择内科保守治疗（C对），治疗重点为保肝护肝，若内科治疗无效，病情持续进展，考虑手术治疗。有关是否进行预防性手术（主要术式为断流术），目前临床上较为统一的意见是，有食管胃底静脉曲张的病人不一定发生大出血，而部分从未出血的患者在进行预防性手术后反而发生出血，肝炎后肝硬化患者的肝功能损害都较为严重，手术负担大，因此不主张做预防性手术，若患者食管胃底静脉曲张严重，特别是镜下见曲张静脉表面有“红色征”，为了预防首次急性大出血，可酌情考虑行预防性手术。","","N"],["2020-N133",31,"门静脉高压","经颈静脉肝内门体静脉分流术",2020,133,"B","","男性，48岁。乙肝肝硬化病史8年，中度食管胃底静脉曲张，化验血Hb80g/L,WBC3.1×10⁹/L，Plt36×10⁹/L，肝功能Child-PughC级。近1年内曾呕血3次，等待肝移植。1天前再次呕血1500ml，行三腔二囊管压迫止血，24小时放空气囊，仍有出血。应进一步采取的治疗方式是",[["A","分流术"],["B","断流术"],["C","保守治疗"],["D","TIPS"]],"D","中年男性患者，乙肝肝硬化病史，中度食管胃底静脉曲张，化验血Hb80g/L（正常成年男性130～175g/L，贫血），WBC3.1×10⁹/L（正常成年人3.5～9.5×10⁹/L，白细胞降低），PLT36×10⁹/L（正常成年人125～350×10⁹/L，血小板降低），肝功能Child-PughC级，有出血史，患者为终末肝病伴有食管胃底静脉曲张反复出血，并发脾功能亢进，需肝移植，1天前再次呕血1500ml，三腔二囊管止血效果差，此时应进一步采取的治疗方式是TIPS（经颈静脉肝内门体分流术）（D对C错），可明显降低门静脉压力，从而进行性减轻曲张静脉的压力，减少出血风险，控制出血。TIPS目前主要用于肝功能较差的病人，其适应证为：①肝移植患者在等待肝供体期间发生大出血；②非手术治疗无效而外科手术风险极大的出血患者；③外科手术后或内镜治疗后再出血患者。分流术（A错）、断流术（B错）适用于肝功能Child-PughA级、B级的患者，后者应用广泛，目前为治疗门静脉高压症的主要手术（90%）。","","N"],["2020-N134",20,"第三节 肺肿瘤","肺癌临床表现",2020,134,"B","","一侧上睑下垂、瞳孔缩小、眼球内陷等表现属于",[["A","Horner综合征"],["B","Mirizzi综合征"],["C","Budd-Chiari综合征"],["D","Peutz-Jeghers综合征"]],"A","一侧上睑下垂、瞳孔缩小、眼球内陷的表现是Horner综合征（A对），Horner综合征为颈交感神经被压迫时表现出的一系列临床症状，还包括同侧额部与胸壁少汗或无汗水。Mirizzi综合征（B错）是特殊类型的胆囊结石，临床特点是胆囊炎及胆管炎反复发作及黄疸，胆道影像检查可见胆囊增大、肝总管扩张、胆总管正常。Budd-Chiari综合征（C错）为由肝静脉或其开口以上的下腔静脉阻塞引起的以门静脉高压或门静脉和下腔静脉高压为特征的一组疾病。Peutz-Jeghers综合征（色素沉着息肉综合征）（D错）为肠息肉病，青少年多见，可癌变，属于错构瘤，此病病变广泛，无法手术根治，当并发肠道大出血、肠梗阻或肠套叠时，可作部分肠切除术。","","N"],["2020-N135",32,"第四节 胆石症","Mirizzi综合征",2020,135,"B","","胆囊管结石压迫肝总管并致其狭窄时，称为",[["A","Horner综合征"],["B","Mirizzi综合征"],["C","Budd-Chiari综合征"],["D","Peutz-Jeghers综合征"]],"B","胆囊结石压迫肝总管并致其狭窄表现是Mirizzi综合征（B对），临床特点是胆囊炎及胆管炎反复发作及黄疸，胆道影像检查可见胆囊增大、肝总管扩张、胆总管正常。Horner综合征（A错）为颈交感神经被压迫时表现出的一系列临床症状，表现为同侧上眼睑下垂、瞳孔缩小、眼球内陷、面部无汗等。Budd-Chiari综合征（C错）为由肝静脉或其开口以上的下腔静脉阻塞引起的以门静脉高压或门静脉和下腔静脉高压为特征的一组疾病。Peutz-Jeghers综合征（色素沉着息肉综合征）（D错）为肠息肉病，青少年多见，可癌变，属于错构瘤，此病病变广泛，无法手术根治，当并发肠道大出血、肠梗阻或肠套叠时，可作部分肠切除术。","","N"],["2020-N160",20,"第三节 肺肿瘤","小细胞癌",2020,160,"X","","目前常见的肺癌病理类型有",[["A","大细胞癌"],["B","小细胞癌"],["C","鳞状细胞癌"],["D","腺癌"]],"BCD","常见的肺癌病理类型有鳞状细胞癌（C对）（约占肺癌30%）、腺癌（D对）（曾最常见肺癌）、小细胞肺癌（B对）（约占肺癌12%～14%）。大细胞肺癌（A错）较少见，约占所有肺癌3%（数据来源为四版实用外科学）。本题有关各型肺癌相关教材数据并不完全统一，官方答案为BCD。","","N"],["2020-N161",2,"第一节 输血的适应证和注意事项","大量失血",2020,161,"X","","失血时输血的原则中，正确的有",[["A","失血量低于总血容量10%时，不需输血，可待其自行代偿"],["B","失血量达总血容量10%～20%时，输入晶体及胶体液"],["C","失血量达总血容量20%～30%时，可适当输入浓缩红细胞"],["D","失血量超过总血容量30%时，应全部输入全血"]],"ABC","输血的目的是在机体大量失血时补充血容量，治疗各种原因导致的低血容量休克。当失血量低于总血量10%时，机体可自身代偿，无需输血（A对）；失血量占总血量10%～20%时，可根据临床情况输入适量晶体液、胶体液（B对）或少量血浆代用品；失血量超过总血20%时，除输入晶体液或胶体外，还应适当输入浓缩红细胞（C对）；失血量小于总血30%时，不输全血，失血量超过总血30%时，可输全血与CRBC各半（D错）。","","N"],["2020-N162",4,"第三节 肠外营养","肠外营养并发症及防治",2020,162,"X","","长期肠外营养可能产生的并发症有",[["A","肝功能损害"],["B","肾功能损害"],["C","水、电解质平衡紊乱"],["D","骨质疏松"]],"ACD","长期肠外营养支持的并发症包括静脉导管相关并发症，代谢性并发症、脏器功能损害及代谢性骨病等。肝功能损害（A对）属于脏器功能损害，主要病理改变为肝脏脂肪浸润和胆汁淤积。水、电解质平衡紊乱（C对）属于代谢性并发症，原因为营养物质直接进入循环，营养底物过量或不足容易引起或加重机体代谢紊乱和器官功能异常。骨质疏松（D对）属于代谢性骨病。肾功能损害（B错）不属于肠外营养的并发症（十版外科学未明确说明）。","","N"],["2020-N163",5,"第二节 浅部组织细菌性感染","丹毒临床表现",2020,163,"X","","丹毒的临床特点有",[["A","β-溶血性链球菌为主要致病菌"],["B","口腔溃疡可以是诱发因素"],["C","反复发作可发生组织坏死"],["D","治愈后易复发"]],"ABD","急性淋巴管炎分为网状淋巴管炎和管状淋巴管炎，前者又称为丹毒，是β溶血性链球菌（乙型溶血性链球菌）（A对）侵入皮肤和黏膜网状淋巴管导致的急性炎症，好发于下肢与面部。大多常先有病变远端皮肤或黏膜的某种病损，如口腔溃疡（B对）可为其诱发因素、足癣或血丝虫感染可引起下肢丹毒反复发作。丹毒发病后淋巴管网分布区域的皮肤出现炎症反应，病变蔓延较快，常累及引流区淋巴结，局部很少有组织坏死（C错）或化脓，轻者仅有局部淋巴结肿大和略有压痛，常能自愈，但容易复发（D对）。","","N"],["2020-N164",47,"第七节 膝关节半月板损伤","膝关节半月板损伤损伤机制和病理",2020,164,"X","","造成半月板损伤的因素有",[["A","膝的半屈"],["B","膝的挤压"],["C","膝的内收外展"],["D","膝的旋转"]],"ABCD","半月板是充填在股骨和胫骨关节间隙内的纤维软骨，每个膝关节有两个半月板，分别是内侧半月板和外侧半月板，周围厚，中间薄。主要作用是保持关节稳定性，承受重力、吸收震荡、润滑关节、协同膝关节的伸屈以及旋转。研磨力量是产生半月板破裂的主要原因。当膝关节处于半屈（A对）状态，股骨髁与半月板的接触面缩小，由于重力的影响，半月板的下面与胫骨平台接触固定，此时若膝关节猛烈的旋转（D对），可产生巨大的研磨力量造成半月板破裂。膝的长期负荷过重会产生对半月板的挤压（B对），进而对半月板产生研磨作用，导致半月板损伤。当膝关节做内收或外展（C对）时，两侧半月板位于一前一后，动作突然时，半月板来不及滑移，就会使半月板在股骨髁和胫骨平台之间发生研磨导致半月板破裂。","","N"],["2020-N165",51,"第五节 与慢性损伤相关的其他疾病","粘连性肩关节囊炎临床特点",2020,165,"X","","关于粘连性肩关节囊炎，正确的描述有",[["A","最主要的激发因素是肩部急性挫伤"],["B","肩盂肱关节囊粘连、僵硬，致肩关节痛和活动受限"],["C","颈椎病可诱发本病"],["D","本病有自限性"]],"BCD","粘连性肩关节囊炎又称肩周炎，俗称冻结肩，是肩周、肌腱、肌肉、滑囊及关节囊的慢性损伤性炎症，以活动时疼痛、功能受限为其临床特点，其最主要的致病激发因素是慢性致伤力，如长期过度活动，姿势不良等（A错），肩外因素如颈椎病也可诱发本病（C对）。本病病变主要发生在盂肱关节周围，肩盂肱关节囊炎性粘连，僵硬，从而产生疼痛和活动受限（B对）。肩周炎有其自然病程，有自限性（D对），早期给予理疗、针灸、适度的推拿按摩，可改善症状，但若不配合治疗和功能锻炼，将遗留不同程度的功能障碍，肩外因素所致肩周炎除局部治疗外，还需对原发病进行治疗。","","N"],["2021-N57",13,"第一节 术前准备","特殊准备",2021,57,"A","","下列关于术前准备的叙述中，错误的是",[["A","高血压患者应继续服用降压药物，避免戒断综合征"],["B","确有凝血障碍者，择期手术前应做相应治疗"],["C","肾功能损害者，在有效的透析疗法治疗后，可耐受手术"],["D","糖尿病病人须在术前把血糖控制在正常水平"]],"D","病人手术前都需进行一系列的术前准备，确保手术顺利完成，防治可能发生的并发症。例如，糖尿病人须在术前将血糖控制在适当水平（D错，为本题正确答案），但并不一定要求将血糖控制在正常水平（血糖正常值：3.9～6.0mmol/L），如，禁食病人需维持血糖处于轻度升高状态（5.6～11.2mmo/L），重症病人围术期的血糖理想范围在7.77～9.99mmol/L之间；高血压者应继续服用降压药物，避免引发戒断综合征（A对）；临床确有凝血障碍者，择期手术前应做相应治疗（B对），避免患者术中大出血，如当血小板＜50×10⁹/L，建议输血小板，大手术或涉及血管部位的手术，应保持血小板达75×10⁹/L等；肾功能损害者，为最大限度地改善肾功，需在手术前24小时内进行透析治疗，达到耐受手术及预防并发症的作用（C对）。","","N"],["2021-N58",4,"第三节 肠外营养","肠外营养适应证",2021,58,"A","","下列不需要使用全胃肠外营养的情况是",[["A","短肠综合征"],["B","溃疡性结肠炎长期腹泻"],["C","重症急性胰腺炎"],["D","胆囊造瘘术后"]],"D","肠外营养是指通过胃肠道以外途径（即静脉途径）提供营养的方式，其适应证为：①高代谢状态；②胃肠道皮肤瘘及短肠综合征，两者均为肠道实际吸收面积不足，营养物质不能被肠道所吸收，短肠综合征病人还可在家庭内长期使用肠外营养（A对）；③急性肠道炎性疾病：如克罗恩病、广泛溃疡性结肠炎等炎性肠道疾病（B对），在急性发作期或术前准备时，均采用肠外营养，同时其他消化系统急性炎症如重症急性胰腺炎（C对），在禁食期则主要靠完全肠外营养。④胃肠道梗阻；⑤肿瘤病人接受大面积放疗和大剂量化疗时；⑥轻度肝、肾功能障碍病人，此类病人可试用肠外营养支持，但重度衰竭禁用。胆囊造瘘术是采用简单的方法引流胆囊炎症，在患者度过危险期情况稳定后，在作胆囊切除根治疾病，手术本身不涉及肠道吸收营养障碍，故术后不需要使用全胃肠外营养（D错，为本题正确答案）。","","N"],["2021-N59",10,"第五节 椎管内麻醉","麻醉平面与阻滞作用",2021,59,"A","","麻醉平面达脐部时，相对应的脊神经节段是",[["A","T₆"],["B","T₈"],["C","T₁₀"],["D","T₁₂"]],"C","当麻醉平面达脐部时，相对应的脊神经节段是T₁₀（C对）。T₆（A错）对应剑突下，T₈（B错）对应季肋部肋缘，T₁₂（D错）对应耻骨联合上2～3cm。","","N"],["2021-N60",21,"第一节 食管癌","食管癌手术治疗",2021,60,"A","","女性，32岁，间断吞咽困难伴呕吐10年。上消化道造影提示食管明显扩张，蠕动减弱。食管末端呈“鸟嘴样”狭窄，狭窄部黏膜尚光滑。宜采取的手术方式是",[["A","食管大部切除，胃代食管术"],["B","食管下段、贲门部肌层切开"],["C","食管下段，近段胃切除术"],["D","腹腔镜胃底折叠术"]],"B","32岁女性患者（贲门失弛缓症高发人群），间断吞咽困难伴呕吐10年（贲门失弛缓症的典型临床表现），上消化道造影提示食管明显扩张，食管末端呈“鸟嘴样”狭窄，狭窄部黏膜尚光滑（贲门失弛缓症的典型钡餐造影表现），综合患者的病史、临床表现和影像学检查，该病人考虑诊断为贲门失弛缓症，宜采取的手术方式是食管下段、贲门部肌层切开（B对），即食管下段贲门肌层切开术(Heller手术)，方法简单，效果良好，目前多采用经腹腔镜或胸腔镜微创方法。食管大部切除，胃代食管术（A错）主要用于食管上、中段癌的治疗。食管下段，近段胃切除术（C错）主要用于食管下端癌及贲门胃底癌的治疗。腹腔镜胃底折叠术（D错）主要用于胃食管反流病的治疗。","","N"],["2021-N61",18,"第四节 乳腺癌","转移途径",2021,61,"A","","有关乳腺癌血行转移的叙述，错误的是",[["A","癌细胞可经淋巴途径进入静脉"],["B","癌细胞直接侵入血循环"],["C","血行转移只发生在肿瘤晚期"],["D","常见远处转移部位依次为骨、肺、肝"]],"C","乳腺癌可经局部扩散、淋巴转移、血运转移等途径转移。但作为一种全身性疾病，乳腺癌早期就可以进行血行转移（C错，为本题正确答案），甚至癌细胞可直接侵入血液循环（B对）向远处转移，最常见的远处转移依次为骨、肺、肝（D对）。此外癌细胞可经淋巴途径进入静脉（A对），具体转移过程为：癌细胞→胸大肌外侧缘淋巴管→同侧腋窝淋巴结→锁骨下淋巴结→锁骨上淋巴结→胸导管（左）或右淋巴管→静脉→远处转移。","","N"],["2021-N62",29,"第六节 结肠癌","结肠癌根治性手术",2021,62,"A","","男性55岁，因腹痛一个月来诊，结肠镜发现乙状结肠肿物，病理提示中分化腺癌，腹部CT提示乙状结肠肿物，大小为5cm×4cm，侵及浆膜，肝左外叶可见直径2cm转移灶，腹腔内未见肿大淋巴结，首选的治疗措施是",[["A","结肠癌根治术"],["B","结肠癌根治术联合肝左外叶切除术"],["C","全身化疗"],["D","局部放疗"]],"B","55岁男性（符合结肠癌的发病年龄和性别），腹痛（符合结肠癌常见症状）一个月来诊，结肠镜发现乙状结肠肿物，病理提示中分化腺癌（确诊结肠癌），腹部CT提示乙状结肠肿物，大小为5cm×4cm，侵及浆膜（T₃），肝左外叶可见直径2cm转移灶（提示转移性肝肿瘤，M₁），腹腔内未见肿大淋巴结（N₀），综合该患者的病史、临床表现和影像学检查，该病人考虑诊断为结肠癌合并肝脏转移，分期为T₃M₁N₀，结肠癌的治疗原则至今为止手术切除仍然是最主要而有效的治疗方法，原则是以手术切除为主的综合治疗，对原发癌肿尚能切除，但已有远处转移的病例，应首选争取尽量切除原发肿瘤，如转移灶为单发，则可根据病人的情况一期或分期切除转移灶（B对A错），对不适用手术切除的多发性肝转移病例，可行肝动脉化疗，同时进行全身化疗（C错）。结肠癌不适宜进行手术前后的辅助放疗（D错），除非有术中放疗设备可考虑术中放射（黄家驷外科学P1565）。","","N"],["2021-N63",33,"第四节 胰腺癌和壶腹周围癌","胰腺癌诊断",2021,63,"A","","男性，65岁，上腹部不适、食欲不振2个月，体重下降。近20天皮肤巩膜黄染，并进行性加重。粪便色灰白，尿色黄。查体：肝脾未扪及，深呼吸时，于右肋缘下触及半球形肿物，Murphy征（—）。化验：TBil230μmol/L，DBil186μmol/L。最可能的诊断为",[["A","慢性肝炎"],["B","胆总管结石"],["C","胰头癌"],["D","肝癌"]],"C","65岁男性（胰头癌高发人群），上腹部不适、食欲不振2个月，体重下降（胰头癌常见临床表现）。近20天皮肤巩膜黄染，并进行性加重。粪便色灰白，尿色黄（黄疸进行性加重，胰头癌典型表现）。查体：肝脾未扪及，深呼吸时，于右肋缘下触及半球形肿物（提示胆囊肿大）。化验：TBil230μmol/L（血清总胆红素，正常值为1.7～17.1μmol/L），DBil186μmol/L（直接胆红素，正常值为0～3.42μmol/L）。综合患者的病史、临床表现和实验室检查，该病人考虑诊断为胰腺癌，胰腺癌多发于头部，最可能的诊断为胰头癌（C对），慢性肝炎（A错）多表现为乏力、腹胀、右上腹隐痛、学习或工作精力减退等非特异性症状，持续发展至肝硬化时，出现肝功下降及门脉高压的相关症状。胆总管结石（B错）一般无症状或仅有上腹部不适，当结石造成胆管梗阻继发胆管炎时，典型表现为反复发作的腹痛、寒战高热和黄疸，称为Charcot三联征。肝癌（D错）早期一般无特异性表现，至中晚期可表现为肝区疼痛、肝大或右上腹肿块，乏力、消瘦、食欲减退、黄疸、腹胀等全身及消化道症状。","","N"],["2021-N64",27,"第四节 肠梗阻","是单纯性还是绞窄性梗阻",2021,64,"A","","下列不属于绞窄性肠梗阻的典型临床表现的是",[["A","早期出现休克"],["B","腹胀"],["C","腹膜炎体征"],["D","血便"]],"B","绞窄性肠梗阻有血运障碍，会发生肠坏死、穿孔与腹膜炎，发病急骤且迅速加重，早期腹痛剧烈，无静止期，呕吐频繁，可有血液呕吐物，某些绞窄性肠梗阻（包括肠套叠或肠系膜血管栓塞），在腹部绞痛后可排出少量血性液状便或果酱样粪便（D对）；腹部有腹膜炎体征（C对），可有局部隆起或触及有压痛的肿块，腹腔穿刺可以有血性液体；全身变化也较快出现，脉率快、体温上升，较早出现休克症状（A对）。腹胀（B错，为本题正确答案）在判断绞窄性肠梗阻时没有特异性，腹胀程度是随梗阻部位的高低而有所不同，低位梗阻的腹胀较高位明显。需要注意的是本题考查范畴为肠梗阻，考点为单纯性和绞窄性梗阻的临床表现的鉴别。","","N"],["2021-N65",43,"第一节 先天性畸形","Ortolani试验（弹入试验）",2021,65,"A","","站立前期先天性髋关节脱位的典型体征是",[["A","屈髋畸形"],["B","骨盆挤压试验(+)"],["C","摇摆式跛行"],["D","弹入试验(Ortolani)(+)"]],"D","站立前期先天性髋关节脱位的典型体征包括髋关节屈曲外展试验、Allis征、弹入试验（Ortolani试验）（D对）、Barlow试验。其中弹入试验具体检查方法为：病人平卧，屈膝、屈髋关节各90°，当髋关节外展至一定角度后突然弹跳者为阳性，与股骨头复位－脱位有关。屈髋畸形（A错）见于髋关节后脱位。骨盆挤压试验(+)（B错）见于骨盆骨折，检查者用双手挤压病人的两髂嵴，伤处出现疼痛即为骨盆挤压试验(+)。摇摆式跛行（C错）见于股骨头骨软骨病，严重程度及疼痛度与活动度有明显关系，也可见于先天性髋关节脱位站立行走期（脱位期）。","","N"],["2021-N66",53,"第二节 腰椎退行性疾病","腰椎间盘突出症手术适应证",2021,66,"A","","单纯椎间盘突出症患者行经皮腰椎间盘切除术的适应症是",[["A","膨出型"],["B","脱出型"],["C","经骨突出型"],["D","Schmorl结节型"]],"B","单纯椎间盘突出症患者根据其突出程度、影像学特征及结合治疗方法可分为膨出型、突出型、脱出型、游离型、Schmorl结节及经骨突出型。其中膨出型（A错）纤维环仅部分破裂，但表层完整；髓核向椎管内局限性隆起，但表面光滑，故保守治疗大多可缓解或治愈。脱出型（B对）髓核穿破后纵韧带，形同菜花状，但其根部仍在椎间隙内，需行经皮腰椎间盘切除术治疗。Schmorl结节及经骨突出型（CD错）存在不同程度的髓核突出，但均无神经症状，故无需手术治疗。","","N"],["2021-N67",49,"第一节 骨盆骨折","盆腔内脏器损伤",2021,67,"A","","骨盆骨折最常见的并发症是",[["A","尿道损伤"],["B","膀胱损伤"],["C","肾脏损伤"],["D","直肠损伤"]],"A","骨盆骨折常合并严重合并症，最常见的并发症是尿道损伤（A对），膀胱损伤（B错）和直肠损伤（D错）次之。肾脏损伤（C错）多见于腹部闭合性损伤。","","N"],["2021-N93",24,"第二节 常见内脏损伤的特征和处理","脾损伤诊断",2021,93,"A","","男性，30岁，晨起跑步时突然昏倒2小时入院，1周前因骑车摔倒撞击左下胸壁，曾卧床休息3天，查体：P120次/分，R30次/分，BP80/60mmHg，神清、面色苍白，左下胸可见皮下瘀斑，全腹轻度压痛及肌紧张，移动性浊音阳性，肠鸣音消失。最可能的诊断是",[["A","脾破裂"],["B","肝破裂"],["C","胰腺破裂"],["D","肠系膜撕裂"]],"A","30岁男性，晨起跑步时突然昏倒2小时入院（运动导致出血被膜破裂），1周前因骑车摔倒撞击左下胸壁（提示闭合性损伤病史，符合脾脏损伤部位），曾卧床休息3天（考虑脾被膜下破裂），查体：P120次/分（正常值：60～100次/分，心率加快），R30次/分（正常值：12～20次/分，呼吸加快），BP80/60mmHg（正常值：收缩压：90～139mmHg，舒张压：60～89mmHg，考虑休克），神清、面色苍白（提示休克），左下胸可见皮下瘀斑（提示胸壁损伤），全腹轻度压痛及肌紧张（腹膜刺激征表现，提示内脏破裂出血，但无胆汁、胰液外漏），移动性浊音阳性，肠鸣音消失（提示出血量较大），综合患者的病史和临床表现，该病人最可能的诊断为脾破裂（A对），脾破裂的表现以内出血及血液对腹膜引起的刺激为主要特征，并常与出血量和出血速度密切相关。肝破裂（B错）常见损伤部位为右上腹或右下胸壁，未伤及胆管时临床表现与脾破裂相似，但若伴有较大肝内胆管断裂时，因胆汁刺激性强，可出现明显的腹痛和腹膜刺激征，肝组织坏死分解，可继发细菌感染形成腹腔脓肿。胰腺破裂（C错）常见于上腹受挤压时，可被压在脊柱上而导致断裂，伴有胰管断裂、胰液外漏时，临床表现与肝破裂胆汁外漏相同，但没有一项能足够准确特异性的诊断胰腺损伤，要通过仔细询问病史、全面的体格检查、实验室检查、影像学检查来综合判断病情，必要时需要手术探查。肠系膜撕裂（D错）导致血管损时可发生失血性休克，临床表现主要取决于损伤的程度以及是否有其他脏器损伤，主要表现为腹膜炎。","c162","N"],["2021-N94",24,"第一节 腹部损伤概述","CT检查",2021,94,"A","","男性，30岁，晨起跑步时突然昏倒2小时入院，1周前因骑车摔倒撞击左下胸壁，曾卧床休息3天，查体：P120次/分，R30次/分，BP80/60mmHg，神清，面色苍白，左下胸可见皮下瘀斑，全腹轻度压痛及肌紧张，移动性浊音阳性，肠鸣音消失。为明确诊断，急诊首选的检查是",[["A","腹腔动脉造影"],["B","腹部CT"],["C","腹部MRI"],["D","腹部X线平片"]],"B","30岁男性，晨起跑步时突然昏倒2小时入院（运动导致出血被膜破裂），1周前因骑车摔倒撞击左下胸壁（提示闭合性损伤病史，符合脾脏损伤部位），曾卧床休息3天（考虑脾被膜下破裂），查体：P120次/分（正常值：60～100次/分，心率加快），R30次/分（正常值：12～20次/分，呼吸加快），BP80/60mmHg（正常收缩压：90～139mmHg，舒张压：60～89mmHg，考虑休克），神清、面色苍白（提示休克），左下胸可见皮下瘀斑（提示胸壁损伤），全腹轻度压痛及肌紧张（腹膜刺激征表现，提示内脏破裂出血，但无胆汁、胰液外漏），移动性浊音阳性，肠鸣音消失（提示出血量较大），综合患者的病史和临床表现，该病人最可能的诊断为脾破裂，诊断依据为外伤史和忽然发展迅速的内出血的临床表现，为明确诊断，急诊首选的检查是腹部CT（B对）及B超（需要注意的是，超声是闭合性腹部实质脏器损伤的首选检查方法），能够确定破脏破裂的范围及程度，对腹腔积血提供诊断信息。腹腔动脉造影（A错）用于经过上述方法未能证实的腹部损伤，当实质器官破裂时，可见动脉像造影剂外漏，但该检查属于侵入性检查手段，对设备条件和技术条件要求较高且费用昂贵，不作为主要检查。腹部MRI（C错）对血管损伤和某些特殊部位的血肿如十二指肠壁间血肿有较高的诊断价值。腹部X线平片（D错）可发现膈下游离气和某些脏器的位置、大小的改变，但腹腔内脏脏器已经确定特别是伴有休克者，应立刻处理，不必再行X线检查，延误治疗，立位腹平片更有诊断意义，但不适用于重伤员。","c162","N"],["2021-N95",24,"第一节 腹部损伤概述","腹部损伤处理",2021,95,"A","","男性，30岁，晨起跑步时突然昏倒2小时入院，1周前因骑车摔倒撞击左下胸壁，曾卧床休息3天，查体：P120次/分，R30次/分，BP80/60mmHg，神清，面色苍白，左下胸可见皮下瘀斑，全腹轻度压痛及肌紧张，移动性浊音阳性，肠鸣音消失。如若手术，术中探查顺序是",[["A","先探查胰腺，再探查肝脾"],["B","先探查胃肠，再探查肝脾"],["C","先探查肝脾，再探查胃肠及其他"],["D","先探查肠系膜血管，再探查其他"]],"C","30岁男性，晨起跑步时突然昏倒2小时入院（运动导致出血被膜破裂），1周前因骑车摔倒撞击左下胸壁（提示闭合性损伤病史，符合脾脏损伤部位），曾卧床休息3天（考虑脾被膜下破裂），查体：P120次/分（正常值：60～100次/分，心率加快），R30次/分（正常值：12～20次/分，呼吸加快），BP80/60mmHg（正常收缩压：90～139mmHg，舒张压：60～89mmHg，考虑休克），神清、面色苍白（提示休克），左下胸可见皮下瘀斑（提示胸壁损伤），全腹轻度压痛及肌紧张（腹膜刺激征表现，提示内脏破裂出血，但无胆汁、胰液外漏），移动性浊音阳性，肠鸣音消失（提示出血量较大），综合患者的病史和临床表现，该病人最可能的诊断为脾破裂，如若手术，术中探查顺序是首先探查破裂的脾脏，考虑到患者外伤的位置为胸壁，故不能排除肝脏损伤的可能性，故应先探查肝脾，待控制出血后，应按照次序继续探查膈肌、胆囊等有无损伤，接着探查胃肠等空腔脏器（C对）。","c162","N"],["2021-N96",33,"第二节 胰腺炎","急性胰腺炎诊断",2021,96,"A","","女性，42岁，因持续上腹痛伴恶心、呕吐3天入院。近2年来查体有胆囊结石。平时进食油腻食物后会有上腹部不适。查体：体温37.8℃，脉率100次/分，呼吸24次/分，血压126/84mmHg，皮肤巩膜无黄染，上腹部压痛，轻度肌紧张，肠鸣音减弱。B超提示胆囊内泥沙样结石。胆总管宽9mm，上段无结石，下段观察不清，胰腺肿大增厚，周围有积液。化验：WBC13.0×10⁹/L，血淀粉酶400U/dL（正常值40～180 U/dl）。患者最可能的诊断是",[["A","急性胆囊炎"],["B","急性胰腺炎"],["C","急性胃炎"],["D","急性胆管炎"]],"B","中年女性症状，持续上腹痛伴恶心、呕吐3天入院（急性胰腺炎早期可有临床表现），既往胆囊结石病史（提示胆源性急性胰腺炎），平时进食油腻食物后会有上腹部不适（提示急性胰腺炎的发病诱因）。查体：体温37.8℃（正常值：36℃～37℃，发热），脉率100次/分（正常值：60～100次/分），呼吸24次/分（正常值：12～20次/分），血压126/84mmHg（正常值：收缩压：90～139mmHg，舒张压：60～89mmHg），上腹部压痛，轻度肌紧张，肠鸣音减弱（腹膜刺激征表现），B超提示胆囊内泥沙样结石（病因为胆石症）。胆总管宽9mm（正常值：6～8mm，提示胆总管扩张），上段无结石，下段观察不清，胰腺肿大增厚，周围有积液（提示急性水肿性胰腺炎）。化验：WBC13.0×10⁹/L（正常值：3.5～9.5×10⁹/L，提示感染），血淀粉酶400U/dL（正常值：40～180 U/dl，急性胰腺炎时升高）。综合该患者的病史、临床表现和影像学检查，该病人考虑诊断为胆源性急性胰腺炎（B对）。急性胆囊炎（A错）主要表现为进食油腻食物后发作右上腹绞痛，多在午夜发病，向右肩和右腰背部放射；体检时右上腹有腹膜刺激征，Murphy征阳性；超声可见胆囊壁炎症、增厚、胆囊内结石有助于诊断。急性胃炎（C错）主要表现为上腹痛、胀满、恶心、呕吐和食欲不振等，重症可有呕血、黑粪、脱水、酸中毒或休克，胃镜可见糜烂及出血病灶。急性胆管炎（D错）主要表现为上腹疼痛伴高热、寒战、黄疸，伴发感染可导致休克和精神症状。","c163","N"],["2021-N97",33,"第二节 胰腺炎","急性胰腺炎非手术治疗",2021,97,"A","","女性，42岁，因持续上腹痛伴恶心、呕吐3天入院。近2年来查体有胆囊结石。平时进食油腻食物后会有上腹部不适。查体：体温37.8℃，脉率100次/分，呼吸24次/分，血压126/84mmHg，皮肤巩膜无黄染，上腹部压痛，轻度肌紧张，肠鸣音减弱。B超提示胆囊内泥沙样结石。胆总管宽9mm，上段无结石，下段观察不清，胰腺肿大增厚，周围有积液。化验：WBC13.0×10⁹/L，血淀粉酶400U/dL（正常值40～180 U/dl）。最佳治疗措施",[["A","禁食、补液、应用抗生素"],["B","腹腔灌洗"],["C","急诊手术引流"],["D","经内镜Oddi括约肌切开"]],"A","中年女性症状，持续上腹痛伴恶心、呕吐3天入院（急性胰腺炎早期可有临床表现），既往胆囊结石病史（提示胆源性急性胰腺炎），平时进食油腻食物后会有上腹部不适（提示急性胰腺炎的发病诱因）。查体：体温37.8℃（正常值：36℃～37℃，发热），脉率100次/分（正常值：60～100次/分），呼吸24次/分（正常值：12～20次/分），血压126/84mmHg（正常值：收缩压：90～139mmHg，舒张压：60～89mmHg），上腹部压痛，轻度肌紧张，肠鸣音减弱（腹膜刺激征表现），B超提示胆囊内泥沙样结石（病因为胆石症）。胆总管宽9mm（正常值：6～8mm，提示胆总管扩张），上段无结石，下段观察不清，胰腺肿大增厚，周围有积液（提示急性水肿性胰腺炎）。化验：WBC13.0×10⁹/L（正常值：3.5～9.5×10⁹/L，提示感染），血淀粉酶400U/dL（正常值：40～180 U/dl，急性胰腺炎时升高）。综合该患者的病史、临床表现和影像学检查，该病人考虑诊断为胆源性急性胰腺炎，病理分型为急性水肿性胰腺炎，目前的最佳治疗措施为禁食、补液、应用抗生素等（A对）非手术治疗，原则是早期液体复苏、动态评估病情发展、维持水、电解质平衡、脏器功能支持、积极防治局部及全身并发症。急诊手术引流（C错）、腹腔灌洗（B错）为急性胰腺炎的手术治疗及术中处理措施，应用范围为急性胰腺炎并发急性腹膜炎、胆总管下端梗阻或感染、胰腺和胰周坏死继发感染等重症患者。经内镜Oddi括约肌切开（D错）适用于胆管结石合并胆道梗阻且以胆道疾病为主的急性胰腺炎。","c163","N"],["2021-N98",22,"第四节 静脉疾病","深静脉血栓形成诊断",2021,98,"A","","男性，65岁，8日前行结肠癌根治术。2天来发热伴左下肢疼痛。查体：T38℃，腹部切口愈合良好，已拆线。左小腿肿胀，腓肠肌压痛（+），Homans征（+）。检查：胸片正常，B超未见腹腔积液。化验：血白细胞9.8×10⁹/L，尿常规正常。最可能的诊断是",[["A","左下肢肌筋膜炎"],["B","左下肢丹毒"],["C","左下肢深静脉血栓"],["D","左下肢浅静脉炎"]],"C","老年男性患者，行结肠癌根治术后（深静脉血栓形成高危因素）发生左下肢疼痛伴发热（考虑血栓形成），查体：T38℃，腹部切口愈合良好，已拆线（暂不考虑伤口感染致发热，深静脉血栓形成急性期可因局部炎症反应和血栓吸收出现低热），左小腿肿胀（深静脉血栓典型临床表现），腓肠肌压痛（+），Homans征（+）（提示周围型下肢深静脉血栓）。检查：胸片正常，B超未见腹腔积液（排除腹腔感染）。化验：血白细胞9.8×10⁹/L（白细胞正常值：3.5～9.5×10⁹/L），尿常规正常。综合患者的病史、临床表现和实验室检查，该病人最可能的诊断为左下肢深静脉血栓（C对），分型为周围型。肌筋膜炎（A错）主要是外伤、劳损、受凉等原因引起的肌肉和筋膜非特异性炎症变化。丹毒（B错）早期起病急，开始即可有畏寒、发热、头痛、全身不适等，病变多见于下肢，表现为片状微隆起的皮肤红疹、色鲜红、中间稍淡、边界清楚；丹毒经治疗好转后，可因病变复发而导致淋巴管阻塞、淋巴液淤滞，最终形成淋巴水肿、肢体肿胀、局部皮肤粗厚，甚至发展成“象皮肿”（十版外科学P52）。血栓性浅静脉炎（D错）为曲张静脉易引起血栓形成及静脉周围炎，常遗有局部硬结与皮肤粘连（十版外科学P332）。","c164","N"],["2021-N99",22,"第四节 静脉疾病","深静脉血栓形成预防和治疗",2021,99,"A","","男性，65岁，8日前行结肠癌根治术。2天来发热伴左下肢疼痛。查体：T38℃，腹部切口愈合良好，已拆线。左小腿肿胀，腓肠肌压痛（+），Homans征（+）。检查：胸片正常，B超未见腹腔积液。化验：血白细胞9.8×10⁹/L，尿常规正常。该患者目前不宜做的是",[["A","抗凝"],["B","多做下肢运动"],["C","抬高患肢"],["D","手术"]],"B","老年男性患者，行结肠癌根治术后（深静脉血栓形成高危因素）发生左下肢疼痛伴发热（考虑血栓形成），查体：T38℃，腹部切口愈合良好，已拆线（暂不考虑伤口感染致发热，深静脉血栓形成急性期可因局部炎症反应和血栓吸收出现低热），左小腿肿胀（深静脉血栓典型临床表现），腓肠肌压痛（+），Homans征（+）（提示周围型下肢深静脉血栓）。检查：胸片正常，B超未见腹腔积液（排除腹腔感染）。化验：血白细胞9.8×10⁹/L（白细胞正常值：3.5～9.5×10⁹/L），尿常规正常。综合患者的病史、临床表现和实验室检查，该病人考虑诊断为左下肢深静脉血栓，分型为周围型，此时该患者的治疗应以非手术治疗为主，主要内容为卧床休息、抬高患肢，适当应用利尿剂（C对），同时根据病情合理应用抗血小板聚集药物、行抗凝治疗、溶栓治疗（A对），下肢深静脉血栓形成不常规行手术治疗取栓，适应证为：①股青肿；②病史不超过7天（发病后接受正规抗凝溶栓治疗或深静脉造影显示为“双轨征”者可延长至14天）；③中心型或混合型；④65岁以下有工作能力者（D对）。目前患者不宜做的是多做下肢运动（B错，为本题正确答案），挤压小腿有使血栓脱落的风险，严重时导致肺动脉栓塞，晕厥甚至死亡，应在进行合理治疗之后，当全身症状和局部压痛缓解后，进行轻便活动，起床时应穿弹力袜或用弹力绷带。","c164","N"],["2021-N100",31,"门静脉高压","门静脉高压诊断与鉴别诊断",2021,100,"A","","男性，40岁，因呕血、黑便2天入院，既往有乙型肝炎病史10年，查体：神志清，贫血貌，肝肋下未触及，脾肋下3cm，腹部无压痛，移动性浊音（＋），肠鸣音活跃，化验：血Hb80g/L，血白蛋白20g/L，血总胆红素76μmol/L。应首先考虑的诊断是",[["A","十二指肠溃疡"],["B","门静脉高压"],["C","胃癌"],["D","胆管结石"]],"B","中年男性，因呕血、黑便（门静脉高压引起的消化道症状）2天入院，既往乙型肝炎10年（提示病因），查体：神志清，贫血貌，肝肋下未触及（肝硬化、肝缩小），脾肋下3cm（脾大，提示门脉高压），腹部无压痛，移动性浊音（＋）（有腹水），肠鸣音活跃，化验：血Hb80g/L（血红蛋白正常值：130～175g，提示贫血），血白蛋白20g/L（正常值：35～50g/L，提示肝功障碍），血总胆红素76μmol/L（正常值：3.4～17.1μmol/L，提示肝细胞性黄疸），综合患者的病史、临床表现和实验室检查，该病人考虑诊断为门静脉高压（B对），分型为肝内型门静脉高压，该型最常见的病因为肝硬化，称为肝硬化门脉高压症。十二指肠溃疡（A错）典型症状为上腹痛，具有慢性过程、反复或周期性发作、饥饿痛或夜间痛、进餐后缓解、腹痛可被抑酸或抗酸剂缓解等特点（九版内科学P359）。胃癌（C错）早期多无明显症状，可有上腹部不适，进食后饱胀恶心等非特异性的上消化道症状，晚期病人出现上腹疼痛加重，食欲下降、乏力、消瘦，体重减轻等症状，可触及上腹部质硬、固定的肿块（十版外科学P374）。胆管结石（D错）一般无症状或仅有上腹部不适，当胆管梗阻时出现反复腹痛或黄疸，继发感染可有寒战高热，进一步加重时出现休克和精神症状（十版外科学P469）。","c165","N"],["2021-N101",31,"门静脉高压","门静脉高压X线钡餐和内镜检查",2021,101,"A","","男性，40岁，因呕血、黑便2天入院，既往有乙型肝炎病史10年，查体：神志清，贫血貌，肝肋下未触及，脾肋下3cm，腹部无压痛，移动性浊音（＋），肠鸣音活跃，化验：血Hb80g/L，血白蛋白20g/L，血总胆红素76μmol/L。为明确诊断，首选的检查是",[["A","腹部B超"],["B","肠系膜上动脉造影"],["C","上消化道造影"],["D","胃镜"]],"D","中年男性，因呕血、黑便（门静脉高压引起的消化道症状）2天入院，既往乙型肝炎10年（提示病因），查体：神志清，贫血貌，肝肋下未触及（肝硬化、肝缩小），脾肋下3cm（脾大，提示门脉高压），腹部无压痛，移动性浊音（＋）（有腹水），肠鸣音活跃，化验：血Hb80g/L（血红蛋白正常值：130～175g，提示贫血），血白蛋白20g/L（正常值：35～50g/L，提示肝功障碍），血总胆红素76μmol/L（正常值：3.4～17.1μmol/L，提示肝细胞性黄疸），综合患者的病史、临床表现和实验室检查，该病人考虑诊断为门静脉高压，同时并发食管胃底静脉曲张破裂出血，为明确诊断应选用胃镜（D对），是识别食管胃底静脉曲张的金标准，可明确食管胃底静脉曲张出血位置及其程度，以及是否有胃黏膜病变或溃疡等，必要时还能进行内镜下急诊止血治疗。上消化道造影（C错）可在钡剂充盈和排空时显示出特异性的影像学表现，但在内镜检查时更为明显。腹部B超（A错）用于显示腹水、肝密度及质地异常、门静脉扩张、血管开放情况、门静脉与肝动脉血流量，门静脉系统有无血栓等。肠系膜上动脉造影（B错）主要用于可疑小肠和部分大肠出血的诊断。","c165","N"],["2021-N102",31,"门静脉高压","食管胃底曲张静脉破裂出血非手术治疗(1)",2021,102,"A","","男性，40岁，因呕血、黑便2天入院，既往有乙型肝炎病史10年，查体：神志清，贫血貌，肝肋下未触及，脾肋下3cm，腹部无压痛，移动性浊音（＋），肠鸣音活跃，化验：血Hb80g/L，血白蛋白20g/L，血总胆红素76μmol/L。下列治疗方法不宜应用的是",[["A","扩容补液"],["B","应用止血药"],["C","内镜治疗"],["D","手术治疗"]],"D","40岁男性，因呕血、黑便（门静脉高压引起的消化道症状）2天入院，既往乙型肝炎10年（提示肝炎引发的门静脉高压），查体：神志清，贫血貌，肝肋下未触及（提示肝病晚期），脾肋下3cm（提示门静脉高压），腹部无压痛，移动性浊音（＋）（提示门静脉高压症严重），肠鸣音活跃，化验：血Hb80g/L（血红蛋白正常值：130～175g/L，提示贫血），血白蛋白20g/L（正常值：35～50g/L，提示肝功障碍），血总胆红素76μmol/L（正常值：3.2～20μmol/L，提示肝功障碍）。综合患者的病史、临床表现和实验室检查，该病人考虑诊断为门静脉高压，并发食管胃底静脉曲张破裂出血，且根据 Child-Pugh分级表考虑该患者肝功能为ChildC级，首选治疗应为非手术治疗，药物和内镜治疗为一线治疗，对有黄疸、大量腹水、肝功能严重受损的病人行外科手术，死亡率很高，故分流术和断流术（手术治疗）为二线治疗，终末期肝病需行肝移植治疗。因此患者不宜应用的是是手术治疗（D错，为本题正确答案）。非手术治疗的内容包括扩容补液（A对）、输血、应用止血药（B对）、抗生素、内镜治疗（C对）、三腔管压迫止血术等。手术治疗适用于曾经或现在发生消化道出血，尤其是对非手术治疗失败的病人，或静脉曲张明显和红色征出血风险较大，及一般情况尚可、肝功能ChildA级、B级，估计能耐受手术者。","c165","N"],["2021-N103",47,"第二节 股骨近端骨折","股骨颈骨折临床表现与诊断",2021,103,"A","","男性，75岁。下楼时摔伤右髋部致局部疼痛。2天后加重，无法下地行走。查体右下肢短缩畸形，外旋50º，右髋部肿胀不明显，有叩击痛。最可能的诊断是",[["A","右股骨转子间骨折"],["B","右股骨颈骨折"],["C","髋关节后脱位"],["D","髋关节前脱位"]],"B","老年男性患者，下楼时摔伤右髋部致局部疼痛（老年人跌倒受伤史），2天后加重，无法下地行走（提示稳定骨折发展为不稳定骨折），查体右下肢短缩畸形，外旋50º（符合股骨颈骨折的典型畸形表现），右髋部肿胀不明显，有叩击痛（符合股骨颈骨折伤后的体征），综合患者的病史、临床表现，该病人考虑诊断为右侧股骨颈骨折（B对），老年人多有骨质疏松，由于骨量减少，骨小梁稀疏，骨的脆性增加，故轻微外力即可造成骨折。股骨转子间骨折（A错）往往表现为转子区疼痛、肿胀明显，下肢不能活动，有转子间压痛及轴向叩击痛，患肢短缩、外旋畸形，但外旋角度可达90º（十版外科学P656）。髋关节后脱位（C错）常有强大暴力所致外伤史，通常暴力很大，例如车祸或高处坠落，髋关节疼痛，不能主动活动，患肢短缩，髋关节呈屈曲、内收、内旋畸形（十版外科学P650）。髋关节前脱位（D错）有强大暴力所致外伤史，患肢呈外展、外旋和屈曲畸形，腹股沟处肿胀（十版外科学P651）。","c166","N"],["2021-N104",47,"第二节 股骨近端骨折","股骨颈骨折临床表现与诊断",2021,104,"A","","男性，75岁。下楼时摔伤右髋部致局部疼痛。2天后加重，无法下地行走。查体右下肢短缩畸形，外旋50º，右髋部肿胀不明显，有叩击痛。首选检查是",[["A","X线"],["B","CT"],["C","MRI"],["D","骨扫描"]],"A","老年男性患者，下楼时摔伤右髋部致局部疼痛（老年人跌倒受伤史），2天后加重，无法下地行走（提示稳定骨折发展为不稳定骨折），查体右下肢短缩畸形，外旋50º（符合股骨颈骨折的典型畸形表现），右髋部肿胀不明显，有叩击痛（符合股骨颈骨折伤后的体征），综合患者的病史、临床表现，该病人考虑诊断为右侧股骨颈骨折，首选检查是X线（A对），即使临床上已表现为明显骨折者，X线平片检查也很有必要，可以帮助了解骨折的部位、类型和骨折端移位情况，对于骨折的治疗具有重要指导意义。CT（B错）是对X线检查的补充说明，用于复杂骨折或深在部位的损伤。MRI（C错）适用于了解软组织的病理变化，对明确脊柱骨折合并脊髓损伤情况、膝关节半月板及韧带损伤，关节软骨损伤等具有独特的优势。骨扫描（D错）主要用于转移性骨肿瘤的诊断。","c166","N"],["2021-N105",47,"第二节 股骨近端骨折","按骨折线部位分类",2021,105,"A","","男性，75岁。下楼时摔伤右髋部致局部疼痛。2天后加重，无法下地行走。查体右下肢短缩畸形，外旋50º，右髋部肿胀不明显，有叩击痛。最有可能的并发症是",[["A","脂肪栓塞"],["B","创伤性骨化"],["C","坐骨神经损伤"],["D","股骨头坏死"]],"D","老年男性患者，下楼时摔伤右髋部致局部疼痛（老年人跌倒受伤史），2天后加重，无法下地行走（提示稳定骨折发展为不稳定骨折），查体右下肢短缩畸形，外旋50º（符合股骨颈骨折的典型畸形表现），右髋部肿胀不明显，有叩击痛（符合股骨颈骨折伤后的体征），综合患者的病史、临床表现，该病人考虑诊断为右侧股骨颈骨折，股骨颈骨折后影响股骨头血供，故最有可能的并发症是股骨头坏死（D对），缺血坏死的发生率在临床上为20%～40%，坏死发生的风险和股骨颈骨折的位置和原始移位程度相关。脂肪栓塞（A错）常在损伤后24～48小时内表现出来，多见于多发性骨折病例（十版外科学P617）。创伤性骨化（B错）又称骨化性肌炎，常见于肘关节，是骨折后血肿处理不当，发生机化，在关节附近软组织内广泛骨化，造成严重关节活动功能障碍（十版外科学P618）。坐骨神经损伤（C错）主要见于髋关节后脱位、骨盆骨折（十版外科学P650）。","c166","N"],["2021-N106",51,"第五节 与慢性损伤相关的其他疾病","狭窄性腱鞘炎诊断",2021,106,"A","","女性，50岁，右手中指晨起僵硬伴疼痛半年，近两周出现中指关节轻度肿胀及活动受限，活动患指可出现弹响伴明显疼痛，最可能诊断",[["A","类风湿关节炎"],["B","关节内游离体"],["C","骨关节炎"],["D","狭窄性腱鞘炎"]],"D","中年女性患者（狭窄性腱鞘炎好发人群），右手中指晨起僵硬伴疼痛半年，近两周出现中指关节轻度肿胀及活动受限（符合狭窄性腱鞘炎病程发展表现），活动患指可出现弹响伴明显疼痛（狭窄性腱鞘炎典型体征），综合患者的病史、临床表现，该病人考虑诊断为狭窄性腱鞘炎（D对），为手指屈肌腱腱鞘炎（弹响指）。类风湿关节炎（A错）多发生于20～45岁女性，常有乏力、肌肉痛，低热和手足麻木、刺痛等全身症状，以及反复发作的、对称性、多发性小关节炎（十版外科学P755）。关节内游离体（B错）为股骨头坏死没有及时修复引起的，也可见于骨关节炎，是关节软骨失去弹性后，不断磨损，软骨破裂、剥脱形成的（九版外科学P723）。骨关节炎（C错）主要表现为静息痛，特点为静止或晨起时疼痛，稍微活动后减轻，但过量活动时疼痛加剧，休息后可好转，其疼痛可与天气变化、潮湿受凉等因素有关（十版外科学P750）。","c167","N"],["2021-N107",51,"第五节 与慢性损伤相关的其他疾病","初始治疗中使用保守疗法",2021,107,"A","","女性，50岁，右手中指晨起僵硬伴疼痛半年，近两周出现中指关节轻度肿胀及活动受限，活动患指可出现弹响伴明显疼痛，目前最正确的治疗是",[["A","腱鞘切开减压"],["B","限制中指运动"],["C","口服糖皮质激素"],["D","反复按摩患处"]],"B","中年女性患者（狭窄性腱鞘炎好发人群），右手中指晨起僵硬伴疼痛半年，近两周出现中指关节轻度肿胀及活动受限（符合狭窄性腱鞘炎病程发展表现），活动患指可出现弹响伴明显疼痛（狭窄性腱鞘炎典型体征），综合患者的病史、临床表现，该病人考虑诊断为狭窄性腱鞘炎，目前该患者最正确的治疗应采取保守疗法，减少手部活动、尤其是中指屈伸活动（B对），也可根据情况进行蜡疗或鞘管内注射皮质激素类药物（C错）。理疗、按摩等（D错）可根据患者实际情况作为辅助治疗措施。手术治疗即腱鞘切开减压（A错）用于注射治疗无效或症状反复者。","c167","N"],["2021-N132",17,"第一节 甲状腺疾病","髓样癌",2021,132,"B","","分泌降钙素的甲状腺癌是",[["A","乳头状癌"],["B","滤泡状癌"],["C","髓样癌"],["D","未分化癌"]],"C","甲状腺癌是髓样癌（C对）发生于滤泡旁降钙素分泌细胞（C细胞），故可分泌大量降钙素和多种胺类、多肽类激素，血清降钙素测定可协助诊断髓样癌，血清降钙素升高伴甲状腺结节者首先考虑甲状腺髓样癌。","","N"],["2021-N133",17,"第一节 甲状腺疾病","乳头状癌",2021,133,"B","","临床上最常见的甲状腺癌是",[["A","乳头状癌"],["B","滤泡状癌"],["C","髓样癌"],["D","未分化癌"]],"A","临床上最常见的甲状腺癌是乳头状癌（A对），大约占所有甲状腺癌的60%，滤泡状腺癌（B错）占甲状腺癌的20%～25%；髓样癌（C错）占甲状腺癌的5%～10%；未分化癌（D错）占甲状腺癌的5%～10%（数据来源为十版病理学P297，有关甲状腺癌各型所占比例在各教材中数据有所不同，本题需直接记忆考点，最常见的类型为乳头状癌）。","","N"],["2021-N134",33,"第五节 胰腺神经内分泌肿瘤","胃泌素瘤临床表现",2021,134,"B","","胃泌素瘤的典型临床表现是",[["A","Whipple三联征"],["B","Zollinger-Ellison综合征"],["C","Charcot三联征"],["D","Carcinoid综合征"]],"B","胃泌素瘤的典型临床表现是Zollinger-Ellison综合征（ZES）（B对），因1955年Zollinger和Ellison首先报告两例以高胃酸分泌、顽固性溃疡和胰岛非B细胞瘤为特征的临床病例，以后文献将有此三联征特点的疾病称为卓－艾综合征(Zollinger-Ellison syndrome)，1961年证明该病的症状是由于肿瘤组织大量分泌胃泌素引起，故定名为胃泌素瘤。Whipple三联征（A错）是胰岛素瘤的典型临床表现。Charcot三联征（C错）是肝外胆管结石的典型表现，主要表现为腹痛、寒战高热和黄疸。Carcinoid综合征（D错）即类癌综合征，可见于消化道、呼吸道的一些肿瘤，类癌细胞可产生多种有生物活性的物质，其中最主要的是5-羟色胺、缓激肽、组胺及前列腺素等，可引起喘息、皮肤潮红等一系列表现。","","N"],["2021-N135",33,"第五节 胰腺神经内分泌肿瘤","胰岛素瘤临床表现",2021,135,"B","","胰岛素瘤的典型临床表现是",[["A","Whipple三联征"],["B","Zollinger-Ellison综合征"],["C","Charcot三联征"],["D","Carcinoid综合征"]],"A","Whipple三联征（A对）是胰岛素瘤的典型临床表现，此三联征包括：空腹或运动后出现低血糖症状；症状发作时血糖低于2.2mmol/L；进食或静脉推注葡萄糖可迅速缓解症状。Zollinger-Ellison综合征（ZES）（B错）即胃泌素瘤，来源于G细胞，主要表现为顽固性消化性溃疡和腹泻。Charcot三联征（C错）是肝外胆管结石的典型表现，主要表现为腹痛、寒战高热和黄疸。Carcinoid综合征（D错）即类癌综合征，可见于消化道、呼吸道的一些肿瘤，类癌细胞可产生多种有生物活性的物质，其中最主要的是5-羟色胺、缓激肽、组胺及前列腺素等，可引起喘息、皮肤潮红等一系列表现。","","N"],["2021-N160",32,"第八节 胆道疾病常见并发症","胆道出血",2021,160,"X","","胆道疾病的常见并发症有",[["A","癌变"],["B","狭窄"],["C","出血"],["D","肝脓肿"]],"ABCD","胆道疾病的常见并发症有：胆囊穿孔、胆道出血（C对）、胆管炎性狭窄（B对）、胆源性肝脓肿（D对）、胆源性胰腺炎等，胆道疾病发生癌变（A对）与胆结石密切相关，如胆囊癌与胆囊结石的存在有密切关系，胆结石愈大胆囊癌的危险性愈高；胆管癌的病因与胆囊癌很相似，与胆管慢性炎症、胆结石及胆汁淤滞可能有关，约50%的病人合并胆结石。","","N"],["2021-N161",30,"第四节 原发性肝恶性肿瘤","肝癌并发症的处理",2021,161,"X","","肝癌破裂出血的治疗方法有",[["A","手术切除"],["B","肝动脉栓塞"],["C","非手术治疗"],["D","放射治疗"]],"ABC","肝癌破裂出血是肝癌常见的并发症，当裂口较小时，往往可被大网膜粘连而自行止血；肿瘤破裂较大而不能自行止血者，需紧急行手术切除治疗（A对），术中如发现癌肿较小而局限，最好将肿瘤完全切除，若条件不许可，可做肝动脉结扎或肝动脉栓塞术（B对），也可作微波、射频或冷冻治疗，以延长病人生命。对晚期病例不能进行手术或TACE止血者，宜采取保守治疗（C对），包括卧床、镇静、吸氧、补液、输血、镇痛、止血药、腹带捆绑以及支持疗法等，保守治疗的关键是维持有效循环血量和水、电解质平衡。虽然经保守治疗大部分病人可能止血，但预后仍差（8版黄家驷外科学P1512）。放射治疗（D错）包括外照射和内照射，大剂量可引起放射性肝炎，目前认为对肝癌有一定疗效，可以使部分肿块缩小，用于症状缓解并延长寿命，用于全身情况尚好，肝功能良好，肿块较为局限又不能手术切除，或肝切除后肝创面有残癌或手术切除后复发者。","","N"],["2021-N162",26,"第二节 胃癌及其他胃肿瘤","早期胃癌",2021,162,"X","","下列关于早期胃癌概念正确的是",[["A","胃癌侵犯到黏膜层和黏膜下层，无淋巴结转移"],["B","病变局限于黏膜层内和黏膜下层，有淋巴转移"],["C","病变浸润浆膜层，无淋巴转移"],["D","微小胃癌和小胃癌是早期胃癌的特殊类型"]],"ABD","早期胃癌是指病变局限于黏膜层内和黏膜下层，不论病灶大小或有无淋巴结转移（AB对）。微小胃癌和小胃癌均是早期胃癌的特殊类型（D对），其中癌灶直径在10mm以下称为小胃癌，5mm以下为微小胃癌，该类型胃癌手术预后极佳，10年生存率可达100%。病变浸润深度超过黏膜下层，为进展期胃癌，又称为中晚期胃癌（C错）。","","N"],["2021-N163",40,"第二节 良性前列腺增生的诊断","良性前列腺增生临床表现",2021,163,"X","","男性急性尿潴留的常见原因有",[["A","良性前列腺增生"],["B","尿路狭窄"],["C","尿路结石"],["D","前列腺炎"]],"ABC","男性急性尿潴留的常见原因有下尿路梗阻[如良性前列腺增生症（A对）、尿道狭窄（B对）、尿道异物和尿道结石（C对）]膀胱神经受损和（或）膀胱逼尿肌功能受损，故在诊断时病史询问尤为重要，需明确既往有无尿道狭窄、尿路结石、下尿路感染、糖尿病、神经系统疾病等病史，男性病人注意询问有无前列腺增生病史。急性细菌性前列腺炎（Ⅰ型）因前列腺充血、肿大，严重时可发生急性尿潴留（D错），但前列腺炎不属于男性急性尿潴留的常见原因。","","N"],["2021-N164",51,"第二节 慢性软组织损伤","腰腿解剖生理",2021,164,"X","","属于椎间盘的结构",[["A","前纵韧带"],["B","软骨终板"],["C","髓核"],["D","纤维环"]],"BCD","脊柱由32个椎骨组成，每个椎骨包括椎体、椎弓根、椎板、上、下关节突、横突和棘突。椎骨由前纵韧带（A错）、后纵韧带、黄韧带、棘间韧带和棘上韧带以及椎间盘和关节囊连结成24个运动节段。椎间盘由上、下软骨终板（B对），中心的髓核（C对）及四周的纤维环（D对）三部分组成，髓核位于椎间盘的中央偏后。","","N"],["2021-N165",56,"第三节 类风湿关节炎","类风湿关节炎诊断标准",2021,165,"X","","类风湿性关节炎的诊断标准",[["A","3个关节肿大（大于6周）"],["B","对称关节肿大（大于6周）"],["C","晨僵大于一个小时（＞6周）"],["D","关节畸形（＞6周）"]],"ABC","类风湿关节炎（RA）是全身慢性结缔组织疾病的局部非特异性炎症表现，为多发性对称性关节病变，诊断标准为1987年美国风湿病协会修订的诊断标准：①晨起关节僵硬至少1小时（≥6周）（C对）；②3个或3个以上关节肿胀(≥6周）（A对）；③腕、掌指关节或近侧指间关节肿胀（≥6周）；④对称性关节肿胀（≥6周）（B对）；⑤皮下结节；⑥手、腕关节X线平片有明确的骨质疏松或骨侵蚀；⑦类风湿因子阳性（滴度＞1:32)。确认本病需具备4条或4条以上标准。但对某些不典型或早期类风湿性关节炎，除进行常规检查外，MRI、高频超声及几种特殊的免疫球蛋白也常非常必要。关节畸形不属于诊断标准（D错），属于类风湿性病变持续发展，晚期出现的体征。","","N"],["2022-N57",1,"第二节 水、钠代谢紊乱","高渗性脱水",2022,57,"A","","关于高渗性脱水，下列叙述错误的是",[["A","细胞外液减少"],["B","细胞内液增加"],["C","抗利尿激素分泌增加"],["D","醛固酮分泌增加"]],"B","高渗性脱水（低容量性高钠血症），特点是失水多于失钠，血清Na⁺＞150mmol/L，血浆渗透压＞310mOsm/L，细胞外液量和细胞内液量均减少（A对），以细胞内液减少为主（B错，为本题正确答案）。对机体的影响会引起口渴，因细胞外液含量减少，细胞外液渗透压升高，通过刺激渗透压感受器引起抗利尿激素分泌增多，加强肾小管对H₂O的重吸收（C对）；而由于血容量下降，也可反射性的引起醛固酮分泌增多（D对），增强肾小管对Na⁺的重吸收，与抗利尿激素一起有助于维持细胞外液容量和循环血量。","","N"],["2022-N58",3,"第一节 外科休克概述","休克代偿期",2022,58,"A","","休克代偿期的临床表现是",[["A","血压正常或稍高，心率、脉压正常"],["B","血压正常或稍低，心率、脉压正常"],["C","血压正常或稍高，心率快，脉压缩小"],["D","血压正常或稍低，心率快，脉压增加"]],"C","血压在休克代偿期的特点是：血压正常或稍高，心率加快，脉压缩小（C对）。","","N"],["2022-N59",4,"第四节 肠内营养","肠内营养制剂",2022,59,"A","","全胃肠外营养时，补充氮（克）和热量（千卡）的比例一般是",[["A","1：10～1：50"],["B","1：60～1：90"],["C","1：150～1：200"],["D","1：250～1：300"]],"C","健康人正常状态下所需的氮（克）和热量（千卡）的比例是1：125～150，通常情况下，肠外营养的日供应量（一般成人）为：氮入量0.15g/kg，热卡量：105（25kcal）/kg，换算为氮热比约为1:166，但需要全肠外营养的病人补充营养时，应根据具体临床情况进行重新配比，故全胃肠外营养时，补充氮（克）和热量（千卡）的比例一般是1：150～1：200（C对）。","","N"],["2022-N60",17,"第一节 甲状腺疾病","甲状腺危象",2022,60,"A","","预防甲亢术后甲状腺危象最关键的措施是",[["A","术后应用镇静药物"],["B","吸氧"],["C","术后给予氢化可的松"],["D","术前使基础代谢率降至正常范围"]],"D","甲状腺危象是甲状腺功能亢进症术后最严重的并发症，多发生在术后12～36小时内，必须避免诱因，注意先兆，早期发现，及时治疗，以最大限度地降低死亡率。发病机制迄今尚未确定。预防关键在于术前做好充分准备，待甲状腺功能、基础代谢率接近正常（D对）、循环系统情况改善后始行手术；同时手术操作要轻柔；术中、术后可补充适量的糖皮质激素（C错）；术后继续给予碘剂，都是预防甲状腺危象的重要措施。吸氧（B错）、术后给予镇静药物（A错）均属于甲状腺危象的对症治疗措施。","","N"],["2022-N61",18,"第三节 乳腺良性疾病","乳腺囊性增生病诊断",2022,61,"A","","女性，38岁。双侧乳房周期性胀痛3年，自检可触及直径1.5cm不规则包块，伴触痛，月经过后疼痛有所减轻，包块略缩小。最可能的诊断是",[["A","乳腺癌"],["B","乳腺纤维腺瘤"],["C","乳腺囊性增生病"],["D","乳管内乳头状瘤"]],"C","中年女性患者（乳腺囊性增生常见人群），双侧乳房周期性胀痛三年（病程较长，发展缓慢），自检可触及直径1.5cm不规则包块，伴触痛，月经后疼痛有所减轻，包块略缩小（乳房胀痛和肿块有周期性，乳腺囊性增生病典型表现），根据患者临床表现和体征，最可能的诊断是乳腺囊性增生病（Ｃ对），本病系内分泌功能失调所致。乳腺纤维腺病（B错）好发于乳房外上象限，约75%为单发，少数属多发，常无明显自觉症状。肿块增大缓慢，有弹性感，表面光滑，易于推动，偶伴有疼痛。乳管内乳头状瘤（D错）常因乳头溢液污染内衣而引起注意，溢液可为血性、暗棕色或黄色液体，肿瘤小，常不能触及，偶有较大的肿块，轻压此肿块，常可从乳头溢出液体。乳腺癌（A错）最常见的临床表现为乳房肿块，早期表现是患侧乳房出现无痛、单发的小肿块，好发于乳房外上象限，若累及Cooper韧带，可出现“酒窝征”，若癌肿引起淋巴回流障碍，皮肤可呈“橘皮样”改变，乳头有血性溢液，乳房疼痛。","","N"],["2022-N62",19,"第五节 创伤性窒息","创伤性窒息概述",2022,62,"A","","下列关于创伤性窒息的病理生理改变，错误的是",[["A","瞬间声门紧闭"],["B","小支气管和肺泡破裂"],["C","胸内压骤升"],["D","上腔静脉系统血逆流"]],"B","创伤性窒息是由于胸部或胸腹部同时受到外力严重挤压、冲击后引起胸腔内瞬间高压而诱发的广泛性皮肤、黏膜下出血等的一组临床综合征。病理生理改变为当胸部、上腹部受重物挤压或高压气体冲击后，病人声门紧闭（A对），胸腔内压力突然大幅度升高（C对），压力经血液传导，右心房血液经无静脉瓣的上腔静脉系统逆流（D对），使人体上半身广泛的毛细血管破裂而出血。小支气管和肺泡破裂（B错，为本题正确答案）是可能导致气胸的原因。","","N"],["2022-N63",20,"第三节 肺肿瘤","小细胞癌",2022,63,"A","","下列关于肺癌的描述，正确的是",[["A","鳞癌常为周围型"],["B","鳞癌通常首先血行转移"],["C","腺癌在早期发生淋巴转移"],["D","小细胞癌对放、化疗都敏感"]],"D","起源于支气管、肺叶支气管的肺癌，位置靠近肺门者称中心型肺癌；起源于肺段支气管以下的肺癌，位于肺周围部分者称周围型肺癌。2004年世界卫生组织（WHO）对肺癌的病理分类进行了修订，按细胞类型将肺癌分为9种：①鳞状细胞癌；②小细胞癌；③腺癌；④大细胞癌；⑤腺鳞癌；⑥多型性，肉瘤样或含肉瘤成分癌；⑦类癌；⑧唾液腺型癌；另外将不典型腺瘤样增生，原位癌等统称为侵袭前病变。其中鳞状细胞癌（鳞癌）常为中心型肺癌（A错），但生长速度较缓慢，病程较长，对放射和化学疗法较敏感。通常先经淋巴转移（B错），血行转移发生较晚；腺癌多为周围型肺癌一般生长较慢，但有时在早期即发现血行转移（C错），淋巴转移则较晚发生；大细胞癌甚为少见，常在发生脑转移后才被发现，预后很差；小细胞癌（未分化小细胞癌）大多为中心型肺癌，恶性程度高，生长快，较早出现淋巴和血行广泛转移，对放射和化学疗法虽较敏感（D对），但在各型肺癌中预后最差。","","N"],["2022-N64",42,"第三节 前列腺癌","前列腺癌诊断",2022,64,"A","","下列检查中，不属于诊断前列腺癌的基本方法的是",[["A","直肠指检"],["B","血清PSA水平"],["C","穿刺活检"],["D","血清癌胚抗原"]],"D","目前诊断前列腺癌的主要方法为：直肠指诊（A对）、相关实验室检查和经直肠超声。直肠指诊对前列腺癌的诊断和分期有重要价值；实验室检查最有特异性的检查为血清前列腺特异性抗原（PSA），前列腺癌常伴有血清PSA升高，极度升高者多数有转移病灶；经直肠超声引导下穿刺活检是确诊前列腺癌的主要方法（C对）。血清癌胚抗原（CEA）（D错，为本题正确答案）是一种肿瘤相关抗原，在胃肠道肿瘤、肺癌、乳腺癌时升高，目前最有价值的用途是疗效的评价和监测复发，特别与结肠癌预后相关。","","N"],["2022-N65",53,"第二节 腰椎退行性疾病","腰椎管狭窄症",2022,65,"A","","腰椎管狭窄症区别于腰椎间盘突出症的主要临床特点是",[["A","腰痛"],["B","坐骨神经痛"],["C","腰椎侧凸"],["D","神经源性间歇跛行"]],"D","腰椎管狭窄症和腰椎间盘突出症均会出现腰痛（A错）、坐骨神经痛（B错），因此不能作为二者的鉴别点。有时腰椎间盘突出症就是椎管狭窄的原因，但真正意义上的腰椎椎管狭窄症不应包括腰椎间盘突出症。主要的鉴别点在于腰椎椎管狭窄症在体征上较腰椎间盘突出症少，直腿抬高试验常为阴性，临床上以下腰痛、马尾神经或腰神经受压症状为主要表现，以神经源性间歇性跛行为主要特点（D对），间歇性跛行为腰椎管狭窄的特异性表现（三版八年制外科学P973）。腰椎侧凸（C错）是一种为减轻疼痛的姿势性代偿畸形，具有辅助诊断价值。","","N"],["2022-N66",48,"第二节 脊髓损伤","脊髓损伤并发症",2022,66,"A","","下列不属于颈椎骨折合并高位截瘫并发症的是",[["A","呼吸道感染"],["B","泌尿道结石"],["C","心力衰竭"],["D","体温失调"]],"C","脊髓损伤后截瘫病人的主要并发症为压疮、泌尿系感染和呼吸系统感染，这些是截瘫病人死亡的主要原因，其中肺部感染是早期死亡的重要原因（Ａ对）；截瘫病人交感神经受损，与副交感神经系统失去平衡，会导致皮肤排汗及体温调节功能丧失（D对）；颈椎骨折合并高位截瘫病人泌尿道外括约肌因失去高级神经支配，不能自主放松，病人出现尿潴留需要长期留置导尿管，容易发生尿道的感染与结石，甚至导致肾衰竭（B对）。心力衰竭（C错）不属于脊髓损伤的并发症。","","N"],["2022-N67",47,"第一节 髋关节脱位","髋关节后脱位临床表现和诊断",2022,67,"A","","女性，56岁。车祸伤，右髋痛，右下肢变短，活动明显受限2小时来诊。检查见右髋关节屈曲、内收内旋，最可能的诊断是",[["A","股骨颈骨折"],["B","股骨转子骨折"],["C","髋关节后脱位"],["D","髋关节前脱位"]],"C","老年女性患者，车祸伤（髋关节后脱位常见原因），右髋痛，右下肢变短，活动明显受限（髋关节后脱位典型临床表现），检查见右髋关节屈曲、内收内旋（髋关节后脱位典型临床体征），根据患者外伤史、临床表现和体征，最可能的诊断是髋关节后脱位（C对），主要原因为当髋关节屈曲，暴力使大腿急剧内收、内旋时，迫使股骨颈前缘抵于髋臼前缘作支点，因杠杆作用股骨头冲破后关节囊，滑向髋臼后方形成后脱位。髋关节前脱位（D错）较少见，患肢呈现为外展、外旋和轻度屈曲畸形，比健肢稍长。股骨颈骨折（A错）和股骨转子骨折（B错）都表现为外旋，前者一般在45°～60°，后者常≥90°且多伴有髋部肿胀和瘀斑。","","N"],["2022-N93",35,"急腹症","急性胆管炎",2022,93,"A","","男性，45岁。突发右上腹痛伴寒战、高热1天入院。既往“胃痛”病史。查体：T39.2℃，BP100/60mmHg，皮肤巩膜轻度黄染，心率110次/分，Murphy‘s sign（-）。B超：胆囊8cm×4cm，壁厚0.2cm，腔内未见结石，总胆管上段直径1.2cm，下段显示不清，血WBC15.0×10⁹/L，血淀粉酶234U/L，T-BiL68μmol/L，D-BiL45μmol/L。最可能的诊断为",[["A","急性胆囊炎"],["B","急性胰腺炎"],["C","急性胆管炎"],["D","急性胃炎"]],"C","中年男性患者，因右上腹痛伴寒战、高热1天入院，既往“胃痛”病史（病因），查体：体温39.2℃（高热），血压100/60mmHg（血压降低），皮肤巩膜轻度黄染（黄疸），心率110次/分（＞100次/分，心率增快），墨菲征（-）（暂不考虑急性胆囊炎），B超：胆囊8cm×4cm，厚0.2cm，腔内未见结石（排除急性胆囊炎）（A错），总胆管上段直径1.2cm，下段显示不清（提示总胆管扩张）。血WBC15.0×10⁹/L（＞9.5×10⁹/L，升高），血淀粉酶234U/L（正常值35～135U/L，升高），T-BiL68μmol/L（正常值3.4～17.1μmol/L，升高），D-BiL45μmol/L（正常值0～6.8μmol/L，升高），根据患者病史、典型Charcot三联征（上腹部剧烈疼痛、寒战高热和黄疸）临床表现和体征及实验室检查结果，最可能的诊断是急性胆管炎（C对），系指胆管不同程度的梗阻合并不同程度的感染而表现出的临床综合征。急性胰腺炎（B错）常因暴饮暴食、酗酒、胆道梗阻诱发，表现为突发剧烈腹痛，呈持续性，常向左腰背部放射，可伴腹胀、恶心、呕吐、发热，查体可发现上腹部或全腹明显压痛、腹肌紧张，血、尿淀粉酶测定对确诊有重要意义；急性胃炎（D错）多表现为上腹痛、胀满、恶心、呕吐和食欲不振等；重症可有呕血、黑粪、脱水、酸中毒或休克。","c177","N"],["2022-N94",35,"急腹症","CT和_或MRI",2022,94,"A","","男性，45岁。突发右上腹痛伴寒战、高热1天入院。既往“胃痛”病史。查体：T39.2℃，BP100/60mmHg，皮肤巩膜轻度黄染，心率110次/分，Murphy‘s sign（-）。B超：胆囊8cm×4cm，壁厚0.2cm，腔内未见结石，总胆管上段直径1.2cm，下段显示不清，血WBC15.0×10⁹/L，血淀粉酶234U/L，T-BiL68μmol/L，D-BiL45μmol/L。为进一步明确诊断，最简单准确的检查方法是",[["A","腹部X线平片"],["B","MRCP"],["C","ERCP"],["D","PTC"]],"B","中年男性患者，因右上腹痛伴寒战、高热1天入院，既往“胃痛”病史（病因），查体：体温39.2℃（高热），血压100/60mmHg（血压降低），皮肤巩膜轻度黄染（黄疸），心率110次/分（＞100次/分，心率增快），墨菲征（-）（暂不考虑急性胆囊炎），B超：胆囊8cm×4cm，厚0.2cm，腔内未见结石（排除急性胆囊炎）（A错），总胆管上段直径1.2cm，下段显示不清（提示总胆管扩张）。血WBC15.0×10⁹/L（＞9.5×10⁹/L，升高），血淀粉酶234U/L（正常值35～135U/L，升高），T-BiL68μmol/L（正常值3.4～17.1μmol/L，升高），D-BiL45μmol/L（正常值0～6.8μmol/L，升高），根据患者病史、典型Charcot三联征（上腹部剧烈疼痛、寒战高热和黄疸）临床表现和体征及实验室检查结果，最可能的诊断是急性胆管炎，为进一步明确诊断，最简单最准确的检查是MRCP（磁共振胆胰管成像）（B对），该检查为一种无创性的胆道造影方法，并且能够显示梗阻上、下端肝内、外胆管的状况，具有无创性和可重复性的优点，在有条件的医院里，已经基本上取代了PTC（经皮肤肝穿刺胆道造影）和ERCP（经十二指肠内镜逆行胆管造影）检查，该检查完全无创，成功率高，不需要注射造影剂对比，可以显示肝内正常胆管系统的第三级分支，一般很少失败，在梗阻性黄疸的定位诊断、胆管狭窄、胆管损伤、腹腔内（如膈下）的积液或积脓、胆肠吻合术后、肝内、外胆管结石、胆道系统的变异等，均有其独特的作用。PTC（D错）及ERCP（C错）为有创性检查，能清楚地显示结石及部位，但可诱发胆管炎及急性胰腺炎和导致出血、胆漏等并发症。腹部X线摄片（A错）对胆道系统疾病的诊断价值极为有限，但可鉴别消化道穿孔或肠梗阻等其他急腹症。","c177","N"],["2022-N95",24,"第二节 常见内脏损伤的特征和处理","十二指肠损伤诊断",2022,95,"A","","男性，25岁。骑摩托车摔倒后1小时来诊。查体：BP100/60mmHg，心率100次/分，全腹压痛，脐周明显肌紧张、反跳痛，肝浊音界缩小，移动性浊音可疑。最可能的诊断是",[["A","脾破裂"],["B","肝破裂"],["C","胰腺损伤"],["D","肠破裂"]],"D","青年男性患者，1小时前骑摩托车跌倒，查体BP100/60mmHg（血压降低），心率100次/分（心率增快），全腹压痛，脐周明显反跳痛、肌紧张（腹膜刺激征），肝浊音界缩小（十二指肠等空腔脏器穿孔表现），移动性浊音可疑（考虑脏器破裂引发腹膜炎），根据患者外伤史、临床表现和体征，最可能的诊断是肠破裂（D对）。脾破裂（A错）的临床表现以内出血及血液对腹膜引起的刺激为主要特征，临床表现与出血量和出血速度密切相关，腹痛初在左上部，慢慢涉及全腹，但仍以左上腹最明显，因血液刺激膈肌可能出现左肩牵涉痛，腹腔诊断性穿刺抽出不凝血。肝破裂（B错）表现为腹腔内出血及低血容量性休克，血腹可引起腹膜刺激征，临床表现与脾破裂相似，但因肝破裂后可能有胆汁溢入腹腔，故腹痛和腹膜刺激征常较脾破裂病者更为明显。胰腺损伤（C错）的主要临床表现是内出血和胰液性腹膜炎，凡在中上腹部受挤压并出现中上腹压痛，特别是空腹时中上腹受到挤压，要考虑胰腺损伤的可能性，胰腺破损或断裂后，胰液可积聚于网膜囊内而表现为上腹明显压痛和肌紧张，还可因膈肌受刺激而出现肩部疼痛，外渗的胰液经网膜孔或破裂的小网膜进入腹腔后，可出现弥漫性腹膜炎，超声和CT有助于确诊。","c178","N"],["2022-N96",24,"第一节 腹部损伤概述","超声检查",2022,96,"A","","男性，25岁。骑摩托车摔倒后1小时来诊。查体：BP100/60mmHg，心率100次/分，全腹压痛，脐周明显肌紧张、反跳痛，肝浊音界缩小，移动性浊音可疑。首先进行的检查是",[["A","血淀粉酶测定"],["B","腹部MRI"],["C","腹部B超"],["D","腹腔穿刺"]],"C","青年男性患者，1小时前骑摩托车跌倒，查体BP100/60mmHg（血压降低），心率100次/分（心率增快），全腹压痛，脐周明显反跳痛、肌紧张（腹膜刺激征），肝浊音界缩小（十二指肠等空腔脏器穿孔表现），移动性浊音可疑（考虑脏器破裂引发腹膜炎），根据患者外伤史、临床表现和体征，最可能的诊断是肠破裂，不论是腹部损伤的脏器还是损伤导致的继发性腹膜炎，诊断性腹腔穿刺都是重要的确诊方法，特别是本例患者症状体征都明显指向肠破裂时，此时为明确诊断最重要的检查是腹腔穿刺（D），穿刺可见消化液或血性液体，临床多为超声引导下腹腔穿刺抽液，准确度高。超声（C）作为简便、经济、快捷直观的非损伤性检查方法，是闭合性腹部实质性损伤的首选检查方法，主要用于肝、脾、肾和上腹部创伤，但对空腔脏器的诊断不够敏感，如果空腔脏器周围有积液，可以在超声引导下腹腔穿刺，有助于诊断。本例题干表述为“首先进行的检查是”，综上所述，官方标准答案为C。肠破裂时可有血清淀粉酶升高的表现，但对肠破裂的诊断无特异性（A错），胰腺损伤时，血尿淀粉酶均升高。腹部MRI（B错）对血管损伤和某些特殊部位的血肿如十二指肠壁间血肿有较高的诊断价值，MRCP尤适用于胆道损伤的诊断。","c178","N"],["2022-N97",17,"第一节 甲状腺疾病","术后呼吸困难和窒息",2022,97,"A","","男性，50岁。行甲状腺癌根治术，术后10小时开始感呼吸困难，心悸。查体：R32次/分，BP140/92mmHg，心率124次/分，切口处饱满。 目前最可能出现的情况是",[["A","喉头痉挛"],["B","声带麻痹"],["C","甲状腺危象"],["D","创面血肿"]],"D","患者行甲状腺癌根治术后10小时出现呼吸困难、心率加快，切口处饱满（血肿压迫表现），考虑为手术止血不彻底，甲状腺动脉或粗静脉的结扎线脱落，或是残留腺体切面严重渗血所致的创面血肿（多发生于术后24～48h内）（D对）。喉头痉挛（A错）多为手术创伤所示，也可因气管插管引起，表现为呼吸道梗阻。声带麻痹（B错）是因喉返神经在术中损伤，单侧损伤会引起声音嘶哑，两侧损伤会导致两侧声带内收，发生严重的呼吸困难。甲状腺危象（C错）主要表现为发热和心率增快，症状往往发展很快，体温可迅速升至39℃,脉率增至120～140次/分以上。可出现烦躁不安、谵妄，甚至昏迷，也可表现为神志淡漠、嗜睡，还可有呕吐及水泻，以及全身红斑及低血压。","c179","N"],["2022-N98",17,"第一节 甲状腺疾病","术后呼吸困难和窒息",2022,98,"A","","男性，50岁。行甲状腺癌根治术，术后10小时开始感呼吸困难，心悸。查体：R32次/分，BP140/92mmHg，心率124次/分，切口处饱满。应立即采取的措施是",[["A","急查B超"],["B","立即拆线敞开伤口"],["C","急查血钙"],["D","急查喉镜"]],"B","患者行甲状腺癌根治术后10小时出现呼吸困难、心率加快，切口处饱满（血肿压迫表现），考虑为手术止血不彻底，甲状腺动脉或粗静脉的结扎线脱落，或是残留腺体切面严重渗血所致的创面血肿（多发生于术后24～48h内），应立即在床边拆开切口及颈前肌，清除血肿，严密止血（B对）。","c179","N"],["2022-N99",17,"第一节 甲状腺疾病","术后呼吸困难和窒息",2022,99,"A","","男性，50岁。行甲状腺癌根治术，术后10小时开始感呼吸困难，心悸。查体：R32次/分，BP140/92mmHg，心率124次/分，切口处饱满。进一步的处理措施是",[["A","补钙"],["B","手术探查止血"],["C","吸氧、密切观察"],["D","应用糖皮质激素"]],"B","患者行甲状腺癌根治术后10小时出现呼吸困难、心率加快，切口处饱满（血肿压迫表现），考虑为手术止血不彻底，甲状腺动脉或粗静脉的结扎线脱落，或是残留腺体切面严重渗血所致的创面血肿（多发生于术后24～48h内），应立即在床边拆开切口及颈前肌，清除血肿，严密止血，进一步的治疗措施为，情况好转后，立即返回手术室，在无菌条件下拆开创口，手术探查止血（B对），术后应放置引流管，并给予大量抗生素抗感染，分别双重结扎甲状腺的主要血管分支，残留腺体切面彻底止血并作缝合，在缝合切口前要求患者用力咳嗽几声，观察有无因结扎线松脱而产生的活跃出血，是预防术后再出血的主要措施。","c179","N"],["2022-N100",23,"第二节 腹股沟疝","腹股沟疝诊断",2022,100,"A","","男性，60岁。因右腹股沟疝行手术治疗，术中见疝囊一部分由盲肠构成。其诊断是",[["A","Littre疝"],["B","滑动疝"],["C","Richter疝"],["D","逆行性嵌顿疝"]],"B","疝囊的一部分由盲肠构成，这种腹外疝称为滑动疝（B对），滑动疝为难复性疝的一种特殊类型，其有部分疝囊壁是由腹腔内脏（如盲肠包括阑尾、乙状结肠或膀胱）所构成。Littre疝（A错）嵌顿的疝内容物是小肠憩室（通常为Meckel憩室），此类疝易发生绞窄。Richter疝（C错）嵌顿的疝内容物仅为部分肠壁，即使出现嵌顿或发生了绞窄，但临床上可无肠梗阻的表现。逆行性嵌顿疝（D错）两个或更多的肠袢进入疝囊，其间的肠袢仍位于腹腔，形如“W”状，位于疝囊内的肠袢血运可以正常，但腹腔内的肠袢可能有坏死，需要全面的检查。","","N"],["2022-N101",23,"第二节 腹股沟疝","无张力疝修补术",2022,101,"A","","男性，60岁。因右腹股沟疝行手术治疗，术中见疝囊一部分由盲肠构成。处理疝囊过程中，最易误损伤的器官是",[["A","精索"],["B","膀胱"],["C","盲肠"],["D","股动脉"]],"C","男性患者行右侧腹股沟疝手术，术中见疝囊一部分由盲肠构成，说明该疝为滑动疝，滑动疝缺损往往较大，腹股沟区后壁整体薄弱，因此不适合网塞法，可行Lichtenstein修补术或腹膜前补片修补术，处理疝囊时应注意滑出的脏器的浆膜层构成疝囊，本例处理疝囊过程中，最易损伤的器官是盲肠（C对），术中需特别注意，安全的做法是先在较薄的疝囊处打开疝囊，探明滑出的脏器的性质和范围后，再进行游离、回纳，并按前述选择修补方法。","","N"],["2022-N102",23,"第二节 腹股沟疝","无张力疝修补术",2022,102,"A","","男性，60岁。因右腹股沟疝行手术治疗，术中见疝囊一部分由盲肠构成。对此病人，目前认为较合理的疝修补术式是",[["A","Bassini法"],["B","Halsted法"],["C","McVay法"],["D","Lichtenstein法"]],"D","男性患者行右侧腹股沟疝手术，术中见疝囊一部分由盲肠构成，说明该疝为滑动疝，滑动疝缺损往往较大，腹股沟区后壁整体薄弱，因此不适合网塞法，可行Lichtenstein修补术或腹膜前补片修补术，术中需特别注意，安全的做法是先在较薄的疝囊处打开疝囊，探明滑出的脏器的性质和范围后，再进行游离、回纳，并按前述选择修补方法。传统的疝修补术的基本原则是疝囊高位结扎、加强或修补腹股沟管管壁，Bassini法（A错）、Halsted法（B错）、McVay法（C错）的共同点是利用自身组织进行修补，但缺点是将不同结构的解剖层强行缝合在一起，张力较大，不利于愈合，在现代疝修补术中的使用已经逐渐减少，且考虑到本例术中发现为滑动疝，更不适用以上术式。","","N"],["2022-N103",54,"第一节 化脓性骨髓炎","急性化脓性骨髓炎诊断依据",2022,103,"A","","男童，8岁。1天前突发“感冒”，伴寒战，体温39.5℃。同时出现右大腿下端疼痛、红肿、皮温增高、压痛，行走困难。怀疑为急性化脓性骨髓炎。对诊断最有价值的体征是",[["A","右大腿下端局限性深压痛"],["B","右大腿下端皮温升高"],["C","右大腿下端软组织肿胀"],["D","右大腿下端皮肤发红"]],"A","8岁患儿，1天前突发“感冒”（感染灶），伴寒战，体温39.5℃（高热），同时右大腿下端疼痛、红肿、皮温增高、压痛，行走困难（急性化脓性脊髓炎典型表现），怀疑急性化脓性骨髓炎，对诊断最有价值的体征右大腿下端局限性深压痛（A对）。患肢剧痛、不敢活动、长骨干骺端有深压痛是急性化脓性骨髓炎的诊断要点。患处红（D错）、肿（C错）、热（B错）不具有诊断特异性，属于局部炎症反应的一般表现。","c180","N"],["2022-N104",54,"第一节 化脓性骨髓炎","急性化脓性骨髓炎影像学检查",2022,104,"A","","男童，8岁。1天前突发“感冒”，伴寒战，体温39.5℃。同时出现右大腿下端疼痛、红肿、皮温增高、压痛，行走困难。怀疑为急性化脓性骨髓炎。目前对该患者最有早期诊断价值的辅助检查是",[["A","X线片检查"],["B","MRI检查"],["C","CT检查"],["D","局部脓肿分层穿刺"]],"B","对急性化脓性骨髓炎具有早期诊断价值的检查是MRI和局部分层穿刺。MRI检查对病灶敏感性高、特异性强，可以更早期发现长在长骨干骺端的病灶，于骨干内有炎性异常信号，还可以显示出骨膜下脓肿。局部分层穿刺对早期诊断也有重要价值，若骨膜下脓肿形成可以抽到血性脓液，但任何性质穿刺液都应作细菌培养与药物敏感试验，故对该患者最具有早期诊断价值的辅助检查是MRI（B对D错）。早期（起病后14天内）骨髓炎患儿X线平片一般正常，但于鉴别诊断有益（A错）。CT有助于评价骨膜下脓肿、软组织脓肿以及骨破坏的定位，较X线平片可以提前发现骨膜下脓肿，但对小的骨脓肿仍难以显示（C错）。","c180","N"],["2022-N105",54,"第一节 化脓性骨髓炎","急性化脓性骨髓炎治疗",2022,105,"A","","男童，8岁。1天前突发“感冒”，伴寒战，体温39.5℃。同时出现右大腿下端疼痛、红肿、皮温增高、压痛，行走困难。怀疑为急性化脓性骨髓炎。该患者经足量抗生素治疗2天后，全身症状好转，但右大腿下端疼痛肿胀加重，下一步应考虑的治疗是",[["A","更换抗生素"],["B","原抗生素＋止痛药"],["C","原抗生素＋石膏托固定"],["D","原抗生素＋钻孔引流"]],"D","急性骨髓炎患儿经过抗生素治疗后全身症状好转，但局部加重，说明抗生素有效（A错），但单纯应用抗生素不能消灭骨脓肿，需要手术引流，引流越早、越彻底越好，最好在抗生素治疗48～72小时仍不能控制局部症状时进行手术（也有主张36小时的）。根据骨髓炎治疗五项原则（Nade,1983）：①在脓肿形成前，应用适当的抗生素是有效的；②抗生素不能消灭无血运组织和脓液中的细菌，只有通过手术才能将其去除；③如果手术清创有效，应使用抗生素以防止脓肿再次形成，只有在这种情况下，一期缝合切口才是安全的；④手术时不能进一步损害已经缺血的骨质和软组织；⑤手术后必须继续使用抗生素。因此此时针对该患儿下一步考虑的治疗应是继续使用原抗生素＋钻孔引流（D对BC错）。","c180","N"],["2022-N106",43,"第一节 先天性畸形","先天性肌性斜颈诊断",2022,106,"A","","男婴，20天。1天前洗澡时无意中被发现右颈部有一椭圆形肿物，局部无红肿热痛，头部轻度向右偏斜，下颌向右侧被动旋转活动受限，无发热及腹泻，偶有吐奶。最可能的诊断是",[["A","颈部软组织炎症"],["B","先天性肌性斜颈"],["C","视力性斜颈"],["D","骨性斜颈"]],"B","新生儿出生后不久发现右颈部有一椭圆形肿物，局部无红肿热痛，头部轻度向右偏斜，下颌部右侧被动旋转活动受限（先天性肌性斜颈典型临床表现），无发热及腹泻（排除感染），该患儿最可能的诊断是先天性肌性斜颈（B对），是一种较为常见的畸形，小儿多见，如果在儿童期没有治愈，畸形往往会随着年龄的增加而渐渐加重。颈部软组织炎症（A错）如咽喉部炎症、扁桃体炎、颈淋巴结的化脓性或结核性感染时，由于炎症刺激，局部软组织充血、水肿，颈椎韧带更加松弛，导致寰枢椎旋转移位而发生斜颈，本例患儿无发热等感染性症状。视力性斜颈（C错）是因视力障碍视物时出现斜颈姿势，但无胸锁乳突肌挛缩，也无颈部活动受限，做视力检查及视神经检查可以确定诊断。骨性斜颈（D错）为先天性颈椎发育异常引起的斜颈，本无胸锁乳突肌挛缩，但也有一些病人会继发颈部软组织挛缩。","c181","N"],["2022-N107",43,"第一节 先天性畸形","非手术治疗",2022,107,"A","","男婴，20天。1天前洗澡时无意中被发现右颈部有一椭圆形肿物，局部无红肿热痛，头部轻度向右偏斜，下颌向右侧被动旋转活动受限，无发热及腹泻，偶有吐奶。明确诊断后，对该婴儿应采取的治疗是",[["A","胸锁乳突肌切除术"],["B","给予肌松药物"],["C","胸锁乳突肌松解术"],["D","局部热敷、按摩"]],"D","新生儿出生后不久发现右颈部有一椭圆形肿物，局部无红肿热痛，头部轻度向右偏斜，下颌部右侧被动旋转活动受限（先天性肌性斜颈典型临床表现），无发热及腹泻（排除感染），该患儿最可能的诊断是先天性肌性斜颈，明确诊断后，考虑到该患儿为新生儿，宜采取非手术治疗，适用于1岁以内的婴儿，目的在于促进局部肿块尽早消散，防止胸锁乳突肌挛缩，因此该婴儿采取的治疗措施是局部按摩、热敷（D对）、手法矫治和矫形帽外固定，晚上患儿睡着后用沙袋保持头部于矫正位，教会家长作胸锁乳突肌的手法牵拉，坚持每日治疗，约90%的患儿在出生2年后可自愈，仅10%的患儿需要手术松解。胸锁乳突肌切除术（A错）、胸锁乳突肌松解术（C错）属于手术治疗，适用于1岁以上的患儿，最佳手术年龄是1～4岁。该病的治疗不包括给予肌松药（B错）。","c181","N"],["2022-N132",31,"门静脉高压","门静脉高压分型",2022,132,"B","","巴德-吉亚利（Budd-Chiari）综合征导致的门脉高压症类型是",[["A","肝前型"],["B","肝后型"],["C","窦前型"],["D","窦后型"]],"B","巴德-吉亚利（Budd-chiari）综合征导致的门脉高压属于肝后型（B对）门静脉高压症。肝前型（A错）的主要病因包括肝外门静脉血栓形成、先天性畸形等；窦前型（C错）的主要病因为血吸虫病等；窦后型（D错）的主要病因为肝炎肝硬化。","","N"],["2022-N133",31,"门静脉高压","门静脉高压分型",2022,133,"B","","血吸虫性肝硬化导致的门脉高压类型是",[["A","肝前型"],["B","肝后型"],["C","窦前型"],["D","窦后型"]],"C","血吸虫性肝硬化导致的门脉高压属于窦前型（C对）门静脉高压症。肝前型（A错）的主要病因包括肝外门静脉血栓形成、先天性畸形等；肝后型（B错）的主要病因为巴德-吉亚利（Budd-chiari）综合征和缩窄性心包炎等；窦后型的主要病因为肝炎肝硬化（D错）。","","N"],["2022-N134",33,"第四节 胰腺癌和壶腹周围癌","胰腺癌诊断",2022,134,"B","","黄疸进行性加重，一般无腹痛，最可能的诊断是",[["A","胰头癌"],["B","慢性胰腺炎"],["C","硬化性胆管炎"],["D","胆总管结石"]],"A","黄疸进行性加重是胰头癌最突出的症状，可伴有腹痛，也可表现为无痛性黄疸（A对）。慢性胰腺炎（B错）临床以反复发作的上腹部疼痛和（或）胰腺外、内分泌功能不全为主要表现，通常将腹痛、体重下降、糖尿病和脂肪泻称之为慢性胰腺炎的四联症，只有少数病人出现黄疸，为胰头纤维增生压迫胆总管下端所致。硬化性胆管炎（C错）常为间歇性反复发作，表现为无痛性黄疸、皮肤瘙痒及肝功能异常，黄疸可以在一定范围内波动、起伏。胆总管结石（D错）的主要临床症状是发作性胆管梗阻和胆管炎，典型表现为反复发作的腹痛、寒战高热和黄疸，称为Charcot三联征。","","N"],["2022-N135",32,"第四节 胆石症","肝外胆管结石诊断与鉴别诊断",2022,135,"B","","黄疸程度波动，常伴腹痛，最可能的诊断是",[["A","胰头癌"],["B","慢性胰腺炎"],["C","硬化性胆管炎"],["D","胆总管结石"]],"D","黄疸波动，常伴腹痛最可能的诊断为胆总管结石（D对），胆总管结石的主要临床症状是发作性胆管梗阻和胆管炎，典型表现为反复发作的腹痛、寒战高热和黄疸，称为Charcot三联征。慢性胰腺炎（B错）临床以反复发作的上腹部疼痛和（或）胰腺外、内分泌功能不全为主要表现，通常将腹痛、体重下降、糖尿病和脂肪泻称之为慢性胰腺炎的四联症，只有少数病人出现黄疸，为胰头纤维增生压迫胆总管下端所致。硬化性胆管炎（C错）常为间歇性反复发作，表现为无痛性黄疸、皮肤瘙痒及肝功能异常，黄疸可以在一定范围内波动、起伏。胰头癌（A错）黄疸的特点是进行性加重，出现早晚与肿瘤位置相关。","","N"],["2022-N160",33,"第二节 胰腺炎","胰酶测定",2022,160,"X","","血清淀粉酶检验值诊断急性胰腺炎的意义，正确的有",[["A","淀粉酶值持续升高，不代表胰腺炎持续加重"],["B","淀粉酶值下降后又升高，说明病情有反复"],["C","淀粉酶值不高，可排除胰腺炎"],["D","淀粉酶值愈高，诊断正确率愈高"]],"ABD","血尿淀粉酶的测定是胰腺炎诊断的最常用和最重要的手段，血清淀粉酶在发病数小时开始升高，24小时达高峰，4～5天后逐渐降至正常，血尿淀粉酶在发病后保持高位不能回落，表明胰腺病变持续存在（四版实用外科学P708），因此淀粉酶值持续升高，不代表胰腺炎持续加重（A对），同时淀粉酶值下降后又升高，说明病情反复（B对），因很多急腹症都有血清淀粉酶升高，因此有非常明显的升高（＞正常值3倍）才有诊断急性胰腺炎的价值，虽然淀粉酶值愈高诊断正确率也越大（D对），但淀粉酶升高的幅度和病变严重程度不成正相关（C错）。","","N"],["2022-N161",28,"第三节 特殊类型阑尾炎","老年人急性阑尾炎",2022,161,"X","","关于老年人急性阑尾炎的叙述，正确的有",[["A","体征不典型"],["B","腹痛程度较轻"],["C","临床症状轻但病理改变重"],["D","尽量采取保守治疗"]],"ABC","老年人急性阑尾炎发病率不高，因老年人反应弱，临床表现可不典型（A对），老年人腹痛症状多逐渐出现，也缺乏典型的转移性右下腹痛，且不是很重（B对），有时即使急性阑尾炎病理发展已很严重，临床表现可能并不严重，导致“临床与病理不符合”（C对），病情常被忽视，故不可因为其临床表现轻微而忽视对疾病进行及时有效的处理，特别是老年人阑尾如有感染，发展很快，坏疽穿孔均较早，穿孔率也较高，常发生弥漫性腹膜炎，另一方面，老年人常合并有其他疾病，免疫防御能力也明显下降，故死亡率较高，一旦诊断应及时手术（D错）。","","N"],["2022-N162",30,"第四节 原发性肝恶性肿瘤","肝癌并发症的处理",2022,162,"X","","肝癌破裂出血的治疗方法有",[["A","手术切除"],["B","肝动脉化疗"],["C","肝动脉栓塞"],["D","纱布填压"]],"ACD","肝癌结节破裂出血是肝癌最常见的并发症，当肝癌破裂的裂口较小时，往往可被大网膜粘着而自行止血，肿瘤破裂较大而不能自行止血者，需紧急手术（A对），手术中如发现癌肿较小而局限，最好切除肿瘤，已有小肝癌结节破裂经手术切除后而长期生存的报道，如条件不许可，也可作肝动脉结扎或肝动脉栓塞术（C对）、纱布填塞（D对）等，也可作微波、射频或冷冻治疗，以延长病人生命。肝动脉化疗（B错）用于治疗不可切除的肝癌或作为肝癌切除术后的辅助治疗，有些不适应一期手术切除的大或巨大肝癌，经此方法治疗后肿瘤缩小，部分病人可获得手术切除机会。","","N"],["2022-N163",38,"第二节 肾损伤","肾损伤临床表现",2022,163,"X","","肾挫伤后临床上可表现为",[["A","肉眼血尿或镜下血尿"],["B","无血尿"],["C","腰部肿块"],["D","会阴部放射痛"]],"ABC","肾损伤的主要症状有休克、出血、血尿、疼痛、伤侧腹壁强直和腰部肿胀等。其中90%以上的肾损伤患者可见血尿，轻者仅为镜下血尿，但肉眼血尿多见（A对），血尿程度与损伤程度并不一致，损伤未累及集合系统时，或肾血管断裂及输尿管断裂等严重损伤时，均不出现血尿（B对）；肾破裂时的血和尿外渗在腰部可形成一不规则的弥漫性肿块（C）。肾损伤可出现疼痛与腹壁强直，常为钝痛，为肾包膜因张力增高或软组织损伤所致，疼痛可局限于腰部或上腹部，或散布到全腹，放射到背后、肩部、髋部或腰骶部（未明确提及会阴部）。通常会阴区放射痛（D错）提示输尿管结石，或肾损伤时血块通过输尿管时引起的剧烈肾绞痛，下放至膀胱甚至睾丸。本题官方给出的参考答案为ABC，但C选项略有争议，有观点认为肾挫伤较轻微，外伤仅限于部分肾实质，肾包膜完整，形成包膜下血肿，通常不会引起腰部肿块，而腰部肿块是肾裂伤的表现。","","N"],["2022-N164",44,"第三节 骨折的并发症","骨折的早期并发症",2022,164,"X","","骨折的早期并发症包括",[["A","脂肪栓塞"],["B","坠积性肺炎"],["C","神经损伤"],["D","急性骨萎缩"]],"AC","骨折的早期并发症包括：1.休克；2.脂肪栓塞综合征（A对）；3.重要内脏器官损伤（①肝、脾破裂、②肺损伤、③膀胱和尿道损伤、④直肠损伤）4..重要周围组织损伤（①重要血管损伤、②周围神经损伤（C对）、③脊髓损伤）；5.骨筋膜室综合征。坠积性肺炎（B错）和急性骨萎缩（D错）属于骨折的晚期并发症。","","N"],["2022-N165",43,"第二节 姿态性畸形","脊柱侧凸",2022,165,"X","","属于非结构性脊柱侧凸的原因有",[["A","姿势性脊柱侧凸"],["B","癔症性脊柱侧凸"],["C","神经根受刺激脊柱侧凸"],["D","先天性脊柱侧凸"]],"ABC","非结构性脊柱侧凸又称功能性侧凸，一旦病因去除，脊柱即可恢复正常。若引起脊柱畸形的原因长期存在，脊柱在发育过程中也可由功能性侧凸改变成为结构性侧凸。引起非结构性脊柱侧凸的原因包括：①姿势性脊柱侧凸（A对）；②癔症性脊柱侧凸（B对）；③神经根受刺激（C对）：椎间盘突出、肿瘤；④炎症；⑤下肢不等长；⑥髋关节挛缩。先天性脊柱侧凸（D错）属于结构性脊柱侧凸，又称器质性侧凸，即脊椎骨有结构的改变。","","N"],["2023-N57",13,"第三节 术后并发症的防治","原因",2023,57,"A","","关于腹部切口裂开的原因，错误的是",[["A","营养不良"],["B","手术后剧烈咳嗽"],["C","应用糖皮质激素"],["D","行切口减张缝合"]],"D","腹部切口裂开的影响因素有：①营养不良（A对），组织愈合能力差等全身因素，在糖尿病、尿毒症、使用免疫抑制剂、黄疸、脓毒症、低蛋白血症、癌症、肥胖、接受皮质类固醇激素治疗（C对）的病人以及老年病人中常见；②切口缝合技术有缺陷，如缝线打结不紧，组织对合不全等；③腹腔内压力突然增高的动作，如剧烈咳嗽（B对），或严重腹胀。行切口减张缝合（D错，为本题正确答案）不是术后伤口裂开的原因，而是术后伤口裂开的预防措施。","","N"],["2023-N58",10,"第二节 麻醉前评估和准备","胃肠道准备",2023,58,"A","","关于术前胃肠道准备的叙述，正确的是",[["A","禁食4小时，禁饮水2小时"],["B","禁食6小时，禁饮水2小时"],["C","禁食12小时，禁饮水4小时"],["D","禁食24小时，禁饮水12小时"]],"C","术前胃肠道准备要求成人禁食8～12小时（三版八年制外科学P8：从术前12小时开始禁食，术前4小时禁止饮水），禁饮水4小时（C对）。","","N"],["2023-N59",3,"第二节 低血容量性休克","补充血容量",2023,59,"A","","男性，24岁。撞伤右季肋部1小时急诊就诊。初步诊断为失血性休克，肝破裂。在等待血型鉴定和交叉配血期间，首选的输注液体是",[["A","5%葡萄糖液"],["B","5%葡萄糖氯化钠溶液"],["C","平衡盐溶液"],["D","10%葡萄糖液"]],"C","失血性休克患者积极补充血容量是扭转组织低灌注和缺氧的关键，是纠正休克的基础，首选的输注液体是平衡盐溶液（C对），平衡盐溶液的电解质含量和血浆内含量相仿，目前常用的平衡盐溶液有乳酸钠和复方氯化钠注射液（1.86%乳酸钠溶液和复方氯化钠溶液之比为1：2）与碳酸氢钠和等渗盐水注射液（1.25%碳酸氢钠溶液和等渗盐水之比为1：2）两种，现有的证据表明平衡盐溶液可以引起相对较少的炎症反应、免疫失调和电解质紊乱。单用等渗盐水，易导致血Cl⁻过高，会导致高氯性酸中毒。","","N"],["2023-N60",40,"第三节 良性前列腺增生的治疗","良性前列腺增生手术治疗概述",2023,60,"A","","关于良性前列腺增生手术指征的叙述，错误的是",[["A","反复尿潴留"],["B","反复泌尿系感染"],["C","血清PSA轻度升高"],["D","继发膀胱结石"]],"C","良性前列腺增生手术指征：①反复尿潴留（A对）；②反复血尿，5-α还原酶抑制剂治疗无效；③反复发作的继发性泌尿系统感染（B对）；④继发膀胱结石（D对）；⑤继发性上尿路积水（伴或不伴肾功能损害）；⑥合并膀胱大憩室，腹股沟疝，严重的痔疮或脱肛，临床判断不解除下尿路梗阻难以达到治疗效果者；⑦残余尿量明显增多，经正规药物治疗无效、排除神经肌源性膀胱功能障碍或神经肌源性膀胱功能障碍因素不明显的，有充溢性尿失禁的患者。手术治疗方式分为开放性手术、经尿道手术、激光治疗。血清PSA前列腺肿瘤标记物，对前列腺结节排除前列腺癌有重要意义，血清PSA升高可以作为前列腺穿刺活检的指征，并不是良性前列腺增生的手术指征（C错，为本题正确答案）。","","N"],["2023-N61",19,"第四节 血胸","血胸临床表现",2023,61,"A","","男性，23岁。因胸部钝挫伤2小时来诊。自诉呼吸困难。听诊右侧肺呼吸音消失，胸片提示右侧大量胸腔积液。为明确诊断，最有价值的检查是",[["A","胸部CT"],["B","胸部超声"],["C","胸腔穿刺"],["D","胸部MRI"]],"C","青年男性患者，胸部外伤后出现呼吸困难，听诊右侧肺呼吸音消失，胸片提示右侧大量胸腔积液（提示血胸），最有价值的检查是胸腔穿刺（C对），胸膜腔穿刺抽出不凝血可明确诊断。胸部CT（A错）、胸部超声（B错）有助于判断胸腔积液的存在，但不能确定积液性质，不能用于确诊。MRI（D错）主要用于软组织损伤的检查。","","N"],["2023-N62",17,"第一节 甲状腺疾病","甲状腺腺瘤诊断",2023,62,"A","","女性，40岁。发现颈部肿物伴疼痛3天就诊。查体：左颈前可触及直径3cm肿物，边界清，质韧，光滑，可随吞咽移动，触痛（+）。最可能的诊断是",[["A","亚急性甲状腺炎"],["B","甲状舌管囊肿"],["C","甲状腺腺瘤囊内出血"],["D","甲状腺癌"]],"C","中年女性患者（甲状腺腺瘤常见人群），发现颈部肿块伴疼痛3天（提示囊内出血），查体：左颈前可触及直径3cm肿物，边界清，质韧，光滑，可随吞咽移动（甲状腺腺瘤较典型体征），触痛（+）（提示囊内出血），根据患者临床表现和体征，最可能的诊断是甲状腺腺瘤囊内出血（C对），一般情况下，20～45岁青壮年尤其是女性患者出现颈部肿块应首先考虑甲状腺腺瘤的可能性。甲状腺癌（D错）多表现为甲状腺肿块质硬、固定，颈淋巴结肿大，可能有压迫症状，也可能或存在多年的甲状腺肿块在短期内迅速增大，超声有助于诊断，确诊依赖活检。亚急性甲状腺炎（A错）在发病前1～2周常有呼吸道感染史，表现为甲状腺肿胀、质地较硬、有压痛，疼痛常波及至患侧耳、颞枕部，病人体温多升高，基础代谢率升高而甲状腺摄碘率显著降低这种分离现象有助于诊断。甲状舌管囊肿（B错）是甲状腺发育有关的先天性畸形，多见于15岁以下儿童，男性为女性的2倍，表现为在颈前区中线、舌骨下方有直径1～2cm的圆形肿块，境界清楚，表面光滑，有粪性感，并能随吞咽或伸、缩舌而上下移动。","","N"],["2023-N63",23,"第二节 腹股沟疝","腹股沟疝临床表现",2023,63,"A","","关于腹股沟直疝的叙述，正确的是",[["A","疝内容物经腹壁下动脉外侧突出"],["B","多见于青年男性"],["C","压住深环站立时疝块出现"],["D","易发生嵌顿和绞窄"]],"C","腹股沟直疝常见于老年体弱者（B错），极少嵌顿和绞窄（D错），疝内容物在腹壁下动脉内侧（A错），同时回纳疝块后压住深环，疝块仍可突出（C对），与此相对应的，腹股沟斜疝多见于儿童及青壮年，疝内容物在腹壁下动脉外侧，易嵌顿绞窄，回纳疝块后压住深环，疝块不再突出。","","N"],["2023-N64",32,"第五节 胆道感染","手术方法",2023,64,"A","","男性，90岁。右上腹痛5天就诊。既往有心肌梗死、脑出血病史。查体：T38℃，右上腹压痛明显。腹部B超提示胆囊10cm×5cm，壁厚0.5cm，腔内可见多发结石，直径最大1.5cm，胆总管直径0.6cm，化验血WBC15×10⁹/L。最适宜的治疗方案是",[["A","急诊胆囊切除术"],["B","急诊胆囊切除加胆总管引流术"],["C","急诊经皮经肝胆囊穿刺引流术"],["D","急诊开腹胆囊造瘘术"]],"C","老年男性患者（高龄老年患者），右上腹痛5天就诊，既往有心肌梗死、脑出血病史（有基础疾病），查体T38℃（正常体温：36.0～37.0℃，体温上升），右上腹压痛明显（急性胆囊炎常见体征），腹部B超提示胆囊10cm×5cm（正常值3～5cm×5～8cm，提示胆囊略大），壁厚0.5cm（正常值：0.19cm左右，提示囊壁增厚），腔内可见多发结石，直径最大1.5cm（胆囊多发结石），胆总管直径0.6cm（正常值0.6～0.8cm，未扩张），实验室检查：WBC15×10⁹/L（正常值4～10×10⁹/L，白细胞升高，提示感染），根据患者病史、临床表现和体征及实验室检查结果，最可能的诊断是急性结石性胆囊炎，其急诊手术指征为：①寒战、高热，WBC＞20×10⁹/L；②黄疸加重；③胆囊肿大，张力高；④局部腹膜刺激征；⑤并发重症急性胰腺炎；⑥60岁以上老年病人，容易发生严重并发症，应多采取早期手术处理。本例患者符合急诊手术指征，但患者年龄较高，且有心梗和脑出血病史，属于高危患者，考虑到老年患者在急性期手术的死亡率较高，此时不但要考虑手术的彻底性，更要考虑手术的安全性及减少术后并发症，故对高危病人，手术方法应简单有效，故不考虑需要全麻的手术/开腹手术（ABD错），即最适宜的治疗方案为急诊经皮经肝胆囊穿刺引流术（C对），该术式方便、不需全麻、且可床旁操作，是首选的急诊救急处理措施，急性胆囊炎最终都需要手术治疗，可在炎症消退后，患者身体恢复较好，根据实际情况再选择争取择期手术。","","N"],["2023-N65",49,"第一节 骨盆骨折","骨盆骨折急救处理",2023,65,"A","","对于骨盆骨折合并尿道损伤及失血性休克患者，正确的处理顺序是",[["A","骨盆骨折-尿道损伤-休克"],["B","尿道损伤-休克-骨盆骨折"],["C","休克-骨盆骨折-尿道损伤"],["D","休克-尿道损伤-骨盆骨折"]],"C","骨盆骨折常并发大出血，也是导致死亡的最主要原因，且骨盆骨折常合并严重的合并症，当合并尿道损伤时，正确的处理顺序是休克-骨盆骨折-尿道损伤（C对），原则为首先挽救患者的生命，对威胁生命的重大损伤予以优先处理，尽量恢复骨盆的形态和稳定性，待伤情稳定后再处理尿道损伤。","","N"],["2023-N66",45,"第三节 肩关节脱位","肩关节脱位病因和分类",2023,66,"A","","肩关节脱位发生率最高的类型是",[["A","后脱位"],["B","上脱位"],["C","前脱位"],["D","下脱位"]],"C","肩关节脱位中发生率最高的是前脱位（C对），占95%以上，因肩盂关节面朝向前下外，前侧关节囊更为薄弱，故最易导致盂肱关节前脱位。","","N"],["2023-N67",44,"第三节 骨折的并发症","骨筋膜隔室综合征",2023,67,"A","","骨筋膜室综合征最早期的临床表现是",[["A","患肢皮肤发黑"],["B","患肢肌力减退"],["C","患肢手指或足趾呈屈曲状态"],["D","患肢持续性剧烈疼痛"]],"D","骨筋膜室综合征是骨折早期并发症，为创伤后骨筋膜室内压力增高，导致室内的肌肉、神经受压继而发生缺血、坏死，最终导致不同程度的神经肌肉功能障碍。骨筋膜室综合征最早期的临床表现是患肢持续性剧烈疼痛（D对），系骨筋膜室内神经受压和缺血的早期表现，该疼痛呈逐渐增加趋势，其他早期表现还包括患侧指（趾）呈屈曲状态（C错），肌力减弱（B错）、患处肿胀、感觉异常。后期表现为肌肉麻痹或瘫痪、无脉、皮肤苍白（A错）乃至严重的挤压综合征，如处理不当会发生严重后果，成为缺血性肌痉挛，成为典型的爪形手或爪形足畸形。","","N"],["2023-N93",32,"第五节 胆道感染","急性梗阻性化脓性胆管炎诊断",2023,93,"A","","男性，76岁。腹痛、发热伴寒战10小时来诊。既往有心肌梗死、高血压病史，曾疑有胆总管结石。查体：T38.6℃，P100次/分，BP90/60mmHg。巩膜黄染，右上腹压痛，肠鸣音正常。化验：血WBC17.5×10⁹/L。最可能的诊断是",[["A","急性胆囊炎"],["B","急性胃肠炎"],["C","急性胰腺炎"],["D","急性胆管炎"]],"D","老年男性患者，既往有心肌梗死，高血压病史，曾疑有胆总管结石（可能病因），腹痛，发热伴寒战，查体巩膜黄染（典型Charcot三联征，提示急性胆管炎），查体：T38.6℃（正常体温36.0℃～37.0℃，发热），P100次/分（正常心率：60～100次/分），BP90/60mmhg（血压降低，提示休克），巩膜黄染，右上腹压痛（胆管炎体征），肠鸣音正常（暂排除穿孔），化验：血WBC17.5×10⁹/L（正常值3.5～9.5×10⁹/L，提示感染），根据患者病史、临床表现和体征及实验室检查结果，最可能的诊断是急性胆管炎（D对），急性胆管炎系指胆管不同程度的梗阻合并不同程度的感染而表现出的临床综合征，本病的典型临床表现为上腹部剧烈疼痛、寒战高热和黄疸，即Charcot三联征，当疾病发展出现低血压和神志改变时，与之前的三项合称为Reynolds五联征，是急性梗阻性化脓性胆管炎（AOSC）不可缺少的诊断依据。急性胆囊炎（A错）表现为在进食油腻食物后发作右上腹绞痛，疼痛向右肩和右腰背部放射，体格检查右上腹有压痛、反跳痛、肌紧张，Murphy征（+）。急性胰腺炎（C错）表现为饮酒或暴食后腹痛，多位于左上腹可向肩背部放射，疼痛剧烈呈持续性，伴有恶心、呕吐，呕吐后腹痛不缓，实验室检查血清和尿淀粉酶明显升高。急性胃肠炎（B错）表现为典型的胃肠道症状，如腹痛、恶心、呕吐、腹泻等，无典型特异性表现，常有不洁饮食等诱因。","c190","N"],["2023-N94",32,"第五节 胆道感染","急性梗阻性化脓性胆管炎影像学检查",2023,94,"A","","男性，76岁。腹痛、发热伴寒战10小时来诊。既往有心肌梗死、高血压病史，曾疑有胆总管结石。查体：T38.6℃，P100次/分，BP90/60mmHg。巩膜黄染，右上腹压痛，肠鸣音正常。化验：血WBC17.5×10⁹/L。为明确诊断，首选的检查是",[["A","ERCP"],["B","腹平片"],["C","MRCP"],["D","PTC"]],"C","老年男性患者，既往有心肌梗死，高血压病史，曾疑有胆总管结石（可能病因），腹痛，发热伴寒战，查体巩膜黄染（典型Charcot三联征，提示急性胆管炎），查体：T38.6℃（正常体温36.0℃～37.0℃，发热），P100次/分（正常心率：60～100次/分），BP90/60mmhg（血压降低，提示休克），巩膜黄染，右上腹压痛（胆管炎体征），肠鸣音正常（暂排除穿孔），化验：血WBC17.5×10⁹/L（正常值3.5～9.5×10⁹/L，提示感染），根据患者病史、临床表现和体征及实验室检查结果，最可能的诊断是急性胆管炎，此时的检查应首选便捷、安全、非损伤性的检查方式，B超为诊断首选，如病情允许，可行CT和MRCP明确诊断（C对），MRCP具有无创性和可重复性的优点，无需造影剂，成功率高，可明确胆总管扩张的程度、位置以及有无肝内胆管扩张、是否合并胆管内结石。PTC（D错）属于有创检查，可清楚显示肝内外胆管的病变部位、范围和程度，本身有一定的并发症，如胆漏、出血、胆道感染等。ERCP（A错）兼有诊断和治疗的双重作用，但易造成出血、胰腺炎等，诊断作用现已部分为MRCP所代替，对急性梗阻性化脓性胆管炎，当炎症得到控制后，胆道造影是必不可少的检查，可行PTC或ERCP或内镜超声等，可显示肝内或肝外胆管扩张情况、狭窄或梗阻的部位和性质，确定胆管内梗阻的原因。部分胆管结石在腹部平片中不显影，故腹部平片（B错）并非首选检查，当有消化道穿孔时可作为辅助检查手段。","c190","N"],["2023-N95",32,"第五节 胆道感染","紧急胆管减压引流",2023,95,"A","","男性，76岁。腹痛、发热伴寒战10小时来诊。既往有心肌梗死、高血压病史，曾疑有胆总管结石。查体：T38.6℃，P100次/分，BP90/60mmHg。巩膜黄染，右上腹压痛，肠鸣音正常。化验：血WBC17.5×10⁹/L。最合适的治疗措施是",[["A","采用非手术治疗"],["B","胆囊切除术"],["C","经内镜鼻胆管引流术"],["D","胆总管切开取石术"]],"C","老年男性患者，既往有心肌梗死，高血压病史，曾疑有胆总管结石（可能病因），腹痛，发热伴寒战，查体巩膜黄染（典型Charcot三联征，提示急性胆管炎），查体：T38.6℃（正常体温36.0℃～37.0℃，发热），P100次/分（正常心率：60～100次/分），BP90/60mmhg（血压降低，提示休克），巩膜黄染，右上腹压痛（胆管炎体征），肠鸣音正常（暂排除穿孔），化验：血WBC17.5×10⁹/L（正常值3.5～9.5×10⁹/L，提示感染），根据患者病史、临床表现和体征及实验室检查结果，最可能的诊断是急性胆管炎。治疗原则是解除胆管梗阻，减压胆管和引流胆汁，使感染得到控制，此时的非手术治疗（A错）既是稳定病情的治疗手段也是术前准备——边抗休克边准备手术，除建立静脉通道，快速补充水、电解质等，还包括解痉镇痛、利胆药物和抗生素的应用等；对紧急胆道减压引流，原则为抢救生命，方法力求简单有效，减少伤害，目前内镜下胆道引流和减压已经成为治疗急性梗阻性化脓性胆管炎的主要方法之一，尤其适用于年老体弱不能耐受手术或已经行多次胆道手术的患者，故本例患者最合适的治疗方法是经内镜鼻胆管引流术/ENBD（C对），对于病情一开始较为严重，特别是黄疸较深且不具备内镜下引流和减压条件的患者可直接行开腹手术引流，行胆总管切开减压T管引流术（D错）。胆囊切除（B错）不是急性胆管炎的手术治疗术式。","c190","N"],["2023-N96",33,"第二节 胰腺炎","急性胰腺炎诊断",2023,96,"A","","男性，50岁。饮酒后上腹部疼痛伴恶心呕吐6小时就诊。既往体健。查体：T37℃，P80次/分，BP130/80mmHg。皮肤巩膜无黄染，上腹部压痛，无反跳痛及肌紧张。化验：血WBC11×10⁹/L，血淀粉酶1000U/L。最可能的诊断是",[["A","急性胆管炎"],["B","急性胃炎"],["C","急性胰腺炎"],["D","上消化道穿孔"]],"C","中年男性患者，饮酒后上腹疼痛伴恶心呕吐6小时（饱餐饮酒后发病），查体T37℃，P80次/分，BP130/80mmHg，皮肤巩膜无黄染，上腹部压痛（胰腺炎体征），无反跳痛及肌紧张（暂时不考虑消化道穿孔），实验室检查：血白细胞11×10⁹/L（正常值3.5～9.5×10⁹/L，血白细胞升高），血淀粉酶1000U/L（35～135U/L，升高＞3倍更有诊断意义，提示胰腺炎），根据患者的发病诱因、临床表现和实验室检查结果，最可能的诊断是急性胰腺炎（C对）。确诊急性胰腺炎至少需要符合以下3项标准中的2项：①与急性胰腺炎相一致的腹痛症状；②血清淀粉酶和（或）脂肪酶＞正常值上限的3倍；③符合急性胰腺炎的影像学特征，本例患者符合前两项，诊断依据明确。急性胆管炎（A错）的典型表现为上腹疼痛伴高热、寒战、黄疸（Charcot三联征）；急性胃炎（B错）多有病因，如严重创伤等应激、非甾体抗炎药的使用史、过度酒精摄入史等，常有上腹痛、胀满、恶心、呕吐和食欲不振等；重症可有呕血、黑粪、脱水、酸中毒或休克表现，诊断时要注意临床表现与相关病因与诱因，胃镜可确诊；上消化道穿孔（D错） 多与服用 NSAIDs 有关，多数是老年病人，穿孔前可以没有症状，穿孔后呈突发剧烈腹痛，持续而加剧，先出现于上腹，继之延及全腹，体征有腹壁板样僵直，压痛、反跳痛，肝浊音界消失，部分病人出现休克。","c191","N"],["2023-N97",33,"第二节 胰腺炎","解痉镇痛",2023,97,"A","","男性，50岁。饮酒后上腹部疼痛伴恶心呕吐6小时就诊。既往体健。查体：T37℃，P80次/分，BP130/80mmHg。皮肤巩膜无黄染，上腹部压痛，无反跳痛及肌紧张。化验：血WBC11×10⁹/L，血淀粉酶1000U/L。下列治疗措施中，不恰当的是",[["A","禁食、补液"],["B","使用抗生素"],["C","使用生长抑素"],["D","常用吗啡止痛"]],"D","中年男性患者，饮酒后上腹疼痛伴恶心呕吐6小时（饱餐饮酒后发病），查体T37℃，P80次/分，BP130/80mmHg，皮肤巩膜无黄染，上腹部压痛（胰腺炎体征），无反跳痛及肌紧张（暂时不考虑消化道穿孔），实验室检查：血白细胞11×10⁹/L（正常值3.5～9.5×10⁹/L，血白细胞升高），血淀粉酶1000U/L（35～135U/L，升高＞3倍更有诊断意义，提示胰腺炎），根据患者的发病诱因、临床表现和实验室检查结果，最可能的诊断是急性胰腺炎，治疗原则为早期液体复苏、动态评估病情发展、维持水、电解质平衡、脏器功能支持、积极防治局部及全身并发症，因此禁食、补液（A对），使胰腺得到充分的休息、维持循环和水、电解质平衡；应用抑制胰腺分泌的药物如生长抑素等（C对）；控制感染，应用抗生素（B对）等措施，均为合理恰当的治疗措施。吗啡类止痛剂及哌替啶类止痛剂，会导致Oddi括约肌痉挛，不宜单独使用，根据临床实际情况在必要时宜与阿托品或山莨菪碱（654-2）等药物联合应用，减少以上副作用（D错，为本题正确答案）。","c191","N"],["2023-N98",26,"第三节 胃十二指肠溃疡的外科治疗","术后肠梗阻",2023,98,"A","","男性，64岁。因胃癌行“远端胃癌根治，毕Ⅱ式吻合术”。术后1周出现上腹剧痛伴呕吐，呕吐物不含胆汁。查体：上腹部压痛，无反跳痛及肌紧张。化验：血WBC12×10⁹/L。最可能的诊断是",[["A","倾倒综合征"],["B","输入袢梗阻"],["C","输出袢梗阻"],["D","术后胃瘫"]],"B","老年患者，因胃癌行“远端胃癌根治，毕Ⅱ式吻合术”，术后一周上腹剧痛伴呕吐（提示术后肠梗阻），呕吐物不含胆汁（提示梗阻部位为输入袢），查体：上腹部压痛，无反跳痛及肌紧张，化验：血WBC12×10⁹/L（正常值3.5～9.5×10⁹/L，升高提示有感染），根据患者病史、临床表现和体征，最可能的诊断是输入袢梗阻，且为急性完全性输入袢梗阻（B对）。输出袢梗阻（C错）临床表现为上腹部胀满，呕吐含胆汁胃内容物，多见于术后肠粘连或结肠后方系膜压迫肠管所致，应根据临床情况手术治疗解除病因。倾倒综合征（A错）是胃大部切除术后胃失去了幽门的节制功能，致胃内容物排空过快产生的一系列临床症状，分为早期倾倒综合征和晚期倾倒综合征（低血糖综合征），前者多在进食后30分钟以内发生，表现为上腹饱胀不适、腹泻，心悸乏力、出汗、头昏晕厥、大汗淋漓、面色苍白、呼吸深大等；后者多在进食2～4小时出现，表现为心慌、出汗、眩晕无力、苍白、手颤等。术后胃瘫（D错）是胃手术后以胃排空障碍为主的综合征，通常发生在术后2～3天，多发生在饮食由禁食改为流质或流质改为半流质时，临床表现为恶心、呕吐，呕吐物多呈绿色，此时需进行胃肠减压，当引流管内流量减少，引流液体由绿转黄、转清是胃瘫缓解的标志。","c192","N"],["2023-N99",26,"第三节 胃十二指肠溃疡的外科治疗","术后肠梗阻",2023,99,"A","","男性，64岁。因胃癌行“远端胃癌根治，毕Ⅱ式吻合术”。术后1周出现上腹剧痛伴呕吐，呕吐物不含胆汁。查体：上腹部压痛，无反跳痛及肌紧张。化验：血WBC12×10⁹/L。目前不宜采取的治疗方法是",[["A","胃肠减压"],["B","灌肠通便"],["C","手术治疗"],["D","温盐水洗胃"]],"C","老年患者，因胃癌行“远端胃癌根治，毕Ⅱ式吻合术”，术后一周上腹剧痛伴呕吐（提示术后肠梗阻），呕吐物不含胆汁（提示梗阻部位为输入袢），查体：上腹部压痛，无反跳痛及肌紧张，化验：血WBC12×10⁹/L（正常值3.5～9.5×10⁹/L，升高提示有感染），根据患者病史、临床表现和体征，最可能的诊断是输入袢梗阻，且患者呕吐不含胆汁，提示为完全性输入袢梗阻，故明确诊断后经适当的处理和术前准备后，应及时行剖腹探查，胃肠减压（A对）、灌肠通便（B对）、温盐水洗胃（D对）均为术前准备，目前手术治疗（C错，为本题正确答案）应在完成术前准备及处理后根据患者的临床实际情况再进行。","c192","N"],["2023-N100",32,"第二节 胆道疾病影像学检查","MRI和磁共振胆胰管成像",2023,100,"A","","女性，24岁。因间断上腹痛3个月就诊。查体：右上腹略饱满。化验：肝功能正常。B超提示胆总管扩张，直径5cm左右，肝内胆管未见扩张。拟诊先天性胆管扩张症。为明确诊断，进一步的检查是",[["A","超声内镜"],["B","ERCP"],["C","MRCP"],["D","PTC"]],"C","本例患者拟诊先天性胆管扩张症，为明确诊断，进一步检查应选择MRCP/磁共振胆胰管成像（C对），MRCP具有无创性和可重复性的优点，无需造影剂，成功率高，可明确胆总管扩张的程度、位置以及有无肝内胆管扩张、是否合并胆管内结石。超声内镜（A错）可弥补普通B超的不足，在中下段胆管癌、壶腹癌、胆囊颈部癌诊断中的应用具有较高的价值。PTC（D错）属于有创检查，可清楚显示肝内外胆管的病变部位、范围和程度，本身有一定的并发症，如胆漏、出血、胆道感染等。ERCP（B错）兼有诊断和治疗的双重作用，但易造成出血、胰腺炎等，诊断作用现已部分为MRCP所代替。","c193","N"],["2023-N101",32,"第三节 胆道畸形","先天性胆管扩张症分型",2023,101,"A","","女性，24岁。因间断上腹痛3个月就诊。查体：右上腹略饱满。化验：肝功能正常。B超提示胆总管扩张，直径5cm左右，肝内胆管未见扩张。拟诊先天性胆管扩张症。检查显示胆总管全程呈囊状扩张，其分型是",[["A","Ⅰ型"],["B","Ⅱ型"],["C","Ⅲ型"],["D","Ⅳ型"]],"A","本例患者拟诊先天性胆管扩张症，影像学提示胆总管扩张5cm，肝内胆管未见扩张，胆总管全长呈囊样扩张，故其分型应为Ⅰ型（A对）。先天性胆总管分为五种类型，分别为：I型：囊性扩张，约占总数的90%，最为常见是囊肿，其次呈梭形或球形。Ⅱ型：憩室样扩张。Ⅲ型：胆总管开口脱垂。Ⅳ型：混合型肝内外扩张。Ⅴ型：单纯肝内胆管扩张（Caroli病）。","c193","N"],["2023-N102",32,"第三节 胆道畸形","先天性胆管扩张症治疗",2023,102,"A","","女性，24岁。因间断上腹痛3个月就诊。查体：右上腹略饱满。化验：肝功能正常。B超提示胆总管扩张，直径5cm左右，肝内胆管未见扩张。拟诊先天性胆管扩张症。最适宜的治疗方法是",[["A","囊肿-十二指肠吻合术"],["B","囊肿切除，胆肠Roux-en-Y吻合术"],["C","囊肿-空肠吻合术"],["D","囊肿切除，肝管-十二指肠吻合术"]],"B","本例患者诊断为先天性胆管扩张症，分型为Ⅰ型，扩张胆总管切除胆道重建术（手术治疗）是根治本病的首选方法，最佳术式为囊肿切除，胆肠Roux-en-Y吻合术（B对），该手术已广泛应用于临床，手术要求吻合口足够大，保证胆汁的充分引流，目前可在腹腔镜下操作，疗效也已达到开放手术的效果。","c193","N"],["2023-N103",53,"","",2023,103,"A","","男性，54岁。右颈肩痛2年伴右手麻木3个月，颈部活动受限1周。查体：C₅₋₆棘突间压痛，右手掌桡侧皮肤感觉减退，Eaton试验（+），Spurling征（+）。X线片显示颈椎生理弧度消失，C₅₋₆椎体后缘骨质增生。初步诊断为颈椎病。下列选项中，最有诊断价值的是",[["A","颈肩部疼痛"],["B","颈部活动受限"],["C","右手麻木"],["D","Eaton试验（+）"]],"D","本例患者诊断为颈椎病，支持诊断的阳性表现及体征包括：颈肩部疼痛，颈部活动受限，部分感觉减退、麻木，Eaton 试验（臂丛神经牵拉试验）、Spurling 征（压头试验）阳性，其中Eaton 试验（臂丛神经牵拉试验）（D对）、Spurling 征（压头试验）提示颈椎神经根受压，最有诊断价值；其他表现对颈椎病的诊断及其分型无特异性。","c194","N"],["2023-N104",53,"第一节 颈椎退行性疾病","神经根型颈椎病",2023,104,"A","","男性，54岁。右颈肩痛2年伴右手麻木3个月，颈部活动受限1周。查体：C₅₋₆棘突间压痛，右手掌桡侧皮肤感觉减退，Eaton试验（+），Spurling征（+）。X线片显示颈椎生理弧度消失，C₅₋₆椎体后缘骨质增生。初步诊断为颈椎病。最需要鉴别的疾病是",[["A","脊髓空洞症"],["B","胸廓出口综合征"],["C","肌萎缩侧索硬化症"],["D","肩周炎"]],"B","本例患者初步诊断为颈椎病，临床体征表现为Eaton 试验（臂丛神经牵拉试验）、Spurling 征（压头试验）阳性，提示颈椎神经根受累，故应诊断为神经根型颈椎病，该型颈椎病的诊断要点为：①具有较典型的根性症状（麻木、疼痛等），范围与神经支配区域一致；②压颈试验与臂丛神经牵拉试验多为阳性；③影像学检查；④除外以下致疼痛为主的疾病，如胸廓出口综合征、肘管综合征和尺管综合征、颈椎骨骼实质性病变（结核、肿瘤）等。神经根型颈椎病也需要与肩周炎（D错）相鉴别，但肩周炎的疼痛主要在肩部，症状向远端不超过肘关节，无麻木和肌力减退的表现（本例患者有典型的手部麻木、皮肤感觉异常的表现）。综合考虑，本例患者最需要鉴别的疾病为胸廓出口综合征（B对）。脊髓空洞症（A错）、肌萎缩侧索硬化症（C错）需要与脊髓型颈椎病相鉴别。","c194","N"],["2023-N105",53,"第一节 颈椎退行性疾病","颈椎病治疗",2023,105,"A","","男性，54岁。右颈肩痛2年伴右手麻木3个月，颈部活动受限1周。查体：C₅₋₆棘突间压痛，右手掌桡侧皮肤感觉减退，Eaton试验（+），Spurling征（+）。X线片显示颈椎生理弧度消失，C₅₋₆椎体后缘骨质增生。初步诊断为颈椎病。该患者MRI检查显示颈椎间盘突出，脊髓与神经根受压。目前不推荐的治疗是",[["A","颈椎牵引"],["B","颈部按摩和推拿"],["C","手术治疗"],["D","应用非甾体抗炎药"]],"B","本例患者诊断为颈椎病，影像学提示脊髓与神经根受压。此时的非手术治疗方法有颈椎牵引（A对）、颈部制动、颈部理疗、改善不良工作体位和睡眠姿势、调整枕头高度等方法，常配合阿司匹林、芬必得等非甾体抗炎药（D对）和肌松药、神经营养药等，会得到更好的治疗效果。需要注意的是，颈部推拿和按摩（B错，为本题正确答案）虽可以松解局部神经或软组织粘连，缓解肌痉挛，帮助肌肉关节运动，减少肌肉萎缩和关节僵硬，但严禁用于脊髓型颈椎病，会加重病情，引发更严重的并发症。若脊髓或神经根明显受压至脊髓变性；保守治疗半年无效或影响正常生活、工作；或神经根性剧烈疼痛、保守治疗无效；或在保守治疗后仍有发展趋势者，则应采取手术治疗（C对）。","c194","N"],["2023-N106",50,"第二节 上肢神经损伤","桡神经损伤",2023,106,"A","","男性，28岁。与他人掰手腕过程中，突发右上臂疼痛、肿胀和畸形，上肢不能活动，X线片显示肱骨中下1/3骨折。如伴有神经损伤，临床上除骨折体征外，还可出现的体征是",[["A","伸腕功能存在、伸指功能丧失"],["B","伸指、伸腕功能丧失"],["C","屈指、屈腕功能丧失"],["D","屈指、伸指功能丧失"]],"B","本例患者诊断为肱骨中、下1/3骨折，该处解剖位置有桡神经紧贴肱骨，故除骨折外，还可合并桡神经损伤，表现为伸腕、伸拇、伸指、前臂旋后障碍及手背桡侧（虎口区）感觉异常，故可出现的体征为伸腕、伸指功能均丧失（B对）。","c195","N"],["2023-N107",50,"第二节 上肢神经损伤","桡神经损伤",2023,107,"A","","男性，28岁。与他人掰手腕过程中，突发右上臂疼痛、肿胀和畸形，上肢不能活动，X线片显示肱骨中下1/3骨折。如出现神经损伤的体征，目前最正确的治疗是",[["A","牵引复位，石膏固定"],["B","手法复位，外固定架固定"],["C","切开复位，神经探查，接骨板固定"],["D","切开复位，髓内钉固定"]],"C","本例患者为肱骨中、下1/3骨折，伴有神经损伤体征，符合肱骨骨折手术指征，需要行手术治疗，切开复位，内固定（AB错），近年临床发展了骨折的微创钢板内固定术，采用锁定加压接骨板固定，提高了骨折的治疗效果（D错）；同时因患者有神经损伤体征，需在术中应进行神经探查，若神经完全断裂，可行一期修复，若为挫伤且神经连续性存在，则可切开神经外膜，减轻神经继发性病理改变，多数病例均可在伤后3～4个月内得到满意恢复。综上本例患者目前最正确的治疗为切开复位，神经探查，接骨板固定（C对）。","c195","N"],["2023-N132",27,"第四节 肠梗阻","是什么原因引起梗阻",2023,132,"B","","老年人结肠梗阻最常见的病因是",[["A","结肠癌"],["B","肠套叠"],["C","乙状结肠冗长"],["D","粘连性肠梗阻"]],"A","老年人结肠梗阻最常见的病因为肿瘤（A对），多伴有大便习惯改变。肠套叠（B错）为小儿肠梗阻的主要原因。粘连性肠梗阻（D错）的原因多为腹部手术后、有腹部损伤或腹膜炎病史。乙状结肠冗长（C错）为乙状结肠的解剖异常，易导致乙状结肠扭转，多见于有便秘病史的老年人，临床特点为以往有多次腹痛发作经排气、排便后缓解的表现。","","N"],["2023-N133",27,"第四节 肠梗阻","是什么原因引起梗阻",2023,133,"B","","儿童肠梗阻最常见的病因是",[["A","结肠癌"],["B","肠套叠"],["C","乙状结肠冗长"],["D","粘连性肠梗阻"]],"B","儿童肠梗阻最常见的病因肠套叠（B对），新生儿多因肠道先天性畸形致肠梗阻。结肠癌（A错）等肿瘤为老年人肠梗阻的常见病因。粘连性肠梗阻（D错）的原因多为腹部手术后、有腹部损伤或腹膜炎病史。乙状结肠冗长（C错）为乙状结肠的解剖异常，易导致乙状结肠扭转，多见于有便秘病史的老年人，临床特点为以往有多次腹痛发作经排气、排便后缓解的表现。","","N"],["2023-N134",17,"第一节 甲状腺疾病","喉上神经损伤",2023,134,"B","","甲状腺术后，出现饮水呛咳的原因是",[["A","损伤喉返神经"],["B","损伤喉上神经内支"],["C","损伤喉上神经外支"],["D","损伤颈交感干"]],"B","甲状腺术后，出现饮水呛咳的原因是损伤喉上神经内支（B对）。损伤喉上神经外支（C错）损伤会导致声带松弛、音调降低。损伤喉返神经（A错）会导致声音嘶哑，双侧喉返神经损伤会导致声带麻痹，引起失音或严重的呼吸困难。颈交感干（D错）自颅底至颈根部，在第一肋骨颈前方与胸交感干相连，位于颈动脉鞘后方，椎前筋膜覆盖下，甲状腺手术不涉及损伤颈交感干。","","N"],["2023-N135",17,"第一节 甲状腺疾病","喉返神经损伤",2023,135,"B","","甲状腺术后，出现声音嘶哑的原因是",[["A","损伤喉返神经"],["B","损伤喉上神经内支"],["C","损伤喉上神经外支"],["D","损伤颈交感干"]],"A","甲状腺术后，出现声音嘶哑的原因是损伤喉返神经（A对），双侧喉返神经损伤会导致声带麻痹，引起失音或严重的呼吸困难。损伤喉上神经内支（B错）会导致喉部黏膜感觉丧失，易误咽发生呛咳。损伤喉上神经外支（C错）损伤会导致声带松弛、音调降低。颈交感干（D错）自颅底至颈根部，在第一肋骨颈前方与胸交感干相连，位于颈动脉鞘后方，椎前筋膜覆盖下，甲状腺手术不涉及损伤颈交感干。","","N"],["2023-N160",32,"第四节 胆石症","胆囊结石治疗",2023,160,"X","","胆囊结石行胆囊切除术的手术指征，正确的有",[["A","结石直径≥3cm，无症状"],["B","儿童胆囊结石，无症状"],["C","伴有胆囊息肉样病变，直径大于1cm"],["D","瓷性胆囊"]],"ACD","儿童胆囊结石、无症状的成人胆囊结石，一般不主张做预防性胆囊切除手术（B错），胆绞痛反复发作、有并发症的胆囊结石，应做手术治疗，腹腔镜胆囊切除术（LC）是外科治疗的最佳选择。无症状胆囊结石出现以下情况应考虑手术治疗：①结石数量多及结石直径≥2～3cm（A对）；②胆囊壁钙化或瓷性胆囊（D对）；③伴有胆囊息肉，直径大于1cm（C对）；④胆囊壁增厚（＞3mm）即伴有慢性胆囊炎，同时对有合并糖尿病、心肺功能障碍、需要开腹手术的患者，也需要进行胆囊切除术。","","N"],["2023-N161",28,"第二节 急性阑尾炎","可辅助诊断的其他体征",2023,161,"X","","急性阑尾炎可能出现的阳性体征有",[["A","Rovsing征"],["B","Cullen征"],["C","Psoas征"],["D","Obturator征"]],"ACD","急性阑尾炎可能出现的阳性体征有Rovsing征——结肠充气试验（A对）、Psoas征——腰大肌试验（C对）、Obturator征——闭孔内肌试验（D对），属于急性阑尾炎的诊断性试验。Cullen征（B错）为少数重症胰腺炎后期患者脐周皮肤的青紫色改变表现，相应的在腰部、季肋部和下腹部皮肤出现的青紫色瘀斑为Grey-Turner征，原因为胰液外溢至皮下组织间隙，溶解皮下脂肪，毛细血管破裂出血所致，提示胰腺炎病情较重。","","N"],["2023-N162",27,"第五节 肠系膜血管缺血性疾病","肠系膜上动脉栓塞",2023,162,"X","","下列关于肠系膜上动脉栓塞的叙述，正确的有",[["A","腹痛症状多较剧烈"],["B","腹部体征早期较为轻微"],["C","栓塞多发生在肠系膜上动脉根部"],["D","选择性腹腔动脉造影有助于明确诊断"]],"ABD","肠系膜上动脉栓塞临床上表现为血运性肠梗阻，栓子多来自心脏，也可来自主动脉壁上的粥样斑块，栓子通常堵塞在肠系膜上动脉自然狭窄部，如空肠第一支的远端结肠中动脉分支处，或是更远的部分（C错）。肠系膜上动脉栓塞患者多有冠心病或房颤病史，临床表现因血管阻塞的部位、性质和发生的缓急而各有不同，剧烈的腹部绞痛是最早出现的症状（A对），难用药物缓解，可为全腹痛或呈局限性；病人的早期症状明显且严重，但腹部体征与其不相称，即“症征不符”，为急性肠缺血的临床特征（B对）。选择性动脉造影有较高的诊断价值，不仅能帮助诊断，还可鉴别是动脉栓塞、血栓形成或血管痉挛（D对），明确病变的性质和部位后，导管可保持在原位上给予血管扩张剂，并维持至手术后或栓塞病变治疗后，有利于提高缺血肠管的成活率。","","N"],["2023-N163",29,"第九节 肛裂","肛裂概述",2023,163,"X","","下列关于肛裂的叙述，正确的有",[["A","大多数位于肛管前正中线"],["B","多见于青中年人"],["C","常与前哨痔、肛乳头肥大同时存在"],["D","常表现为便秘、腹胀"]],"BC","肛裂是齿状线以下的肛管皮肤的小溃疡，常常引起疼痛、便血和愈合困难，在任何年龄均可发生，但多见于青中年人（B对），男女比例无明显差异。肛裂多发生于肛管后正中线，只有约7%发生于前正中线（A错）。肛裂可分为急性肛裂和慢性肛裂，临床表现相似，多表现为疼痛、便血和便秘（D），其中慢性肛裂常可见肛裂、前哨痔、肛乳头肥大同时存在（“肛裂三联症”），为陈旧性肛裂的表现（C对）。本题官方参考答案为BC，在各版本外科学教材中，虽部分慢性便秘患者可有腹胀、下腹不适等症状（九版诊断学P36），但不能作为“肛裂常表现为腹胀、便秘”（D错）的直接证据。","","N"],["2023-N164",57,"第三节 骨巨细胞瘤","骨巨细胞瘤临床表现",2023,164,"X","","关于骨巨细胞瘤的叙述，正确的有",[["A","瘤组织以单核基质细胞及多核巨细胞为主要成分"],["B","典型X线特征为骨端偏心位破坏，有明显骨膜反应"],["C","病变局部肿块有压痛，关节活动不受限"],["D","手术困难时，可采用放化疗，但放疗后易肉瘤变"]],"AD","骨巨细胞瘤是一种良性，但具有局部侵袭性的原发骨肿瘤，多侵犯长骨末端，典型的临床表现有病变处疼痛，肿胀，常见病变关节活动受限（C错），部分病人可出现病理性骨折，以突发剧痛为首发症状。影像学表现为病损处X线通常显示偏心、膨胀的溶骨性破坏，界限清晰，几乎没有反应性骨膜反应（B错）；病理学表现为瘤组织以单核基质细胞及多核巨细胞为主要成分（A对）。本病多采用手术治疗，彻底的囊内切除是首选的手术方法，但手术困难时如脊椎骨巨细胞瘤可采用放化疗，但放疗后易肉瘤变（D对），需要引起高度重视。","","N"],["2023-N165",56,"第一节 骨关节炎","关节畸形",2023,165,"X","","不属于骨关节炎导致的畸形变有",[["A","杵状指"],["B","Heberden结节"],["C","手指向尺侧偏斜"],["D","天鹅颈样畸形"]],"ACD","手指向尺侧偏斜（C错）和天鹅颈样畸形（D错）是类风湿性关节炎晚期特征性的临床表现之一（十版外科学P755）。杵状指（A错）是手指或足趾末端增生、肥厚、增宽、增厚，指甲从根部到末端拱形隆起呈杵状，原因一般为慢性缺氧、代谢障碍和中毒性损害等，常见于肺脓肿、支气管肺癌、亚急性感染性心内膜炎、肝硬化等。Heberden结节（B对）是骨关节炎手指指间关节病变表现，可见侧方增粗，称为Heberden结节。","","N"],["2024-N42",14,"","",2024,42,"A","","男性，82岁，因脑出血4小时经开颅减压手术后意识不清，对声、光刺激无反应，角膜反射、吞咽反射存在，尚可对疼痛刺激有反应。对该患者意识状态的评估，正确的是",[["A","昏睡"],["B","轻度昏迷"],["C","中度昏迷"],["D","深度昏迷"]],"B","本例患者术后意识不清，对声、光刺激无反应，角膜反射、吞咽反射存在，尚可对疼痛刺激有反应，对该患者意识状态的评估应为轻度昏迷（B对），轻度昏迷时，生命体征一般无明显异常。中度昏迷（C错）表现为：对周围事物及各种刺激均无反应，对于剧烈刺激可出现防御反射，角膜反射减弱，瞳孔对光反射迟钝，眼球无转动，同时生命体征会出现轻度异常，直肠膀胱功能也出现某种程度的障碍。重度昏迷（D错）表现为：全身肌肉松弛，对各种刺激全无反应，深、浅反射均消失，生命体征明显异常，肌张力低下，大小便失禁或出现去皮质强直状态。对昏迷的分度需要掌握各分度的反射、对疼痛反应、生命体征等鉴别点。昏睡（A错）是接近于人事不省的意识状态，病人处于熟睡状态，不易唤醒，虽在强刺激下（如压迫眶上神经，摇动病人身体等）可被唤醒，但很快又再入睡。醒时答话含糊或答非所问。","","N"],["2024-N57",1,"第三节 钾代谢紊乱","低钾血症诊断",2024,57,"A","","男性，55岁。因幽门梗阻呕吐10天，呕吐物为胃内容物。最可能出现的酸碱平衡紊乱是",[["A","低氯、高钾性碱中毒"],["B","低氯、低钾性碱中毒"],["C","低氯、高钾性酸中毒"],["D","低氯、低钾性酸中毒"]],"B","幽门梗阻呕吐10天，呕吐物为胃内容物，说明胃酸（HCl）丢失过多，机体失去大量的H⁺和Cl⁻，同时肠液中的HCO₃⁻未能被胃液的H⁺所中和，HCO₃⁻被重吸收入血，使血浆HCO₃⁻增高，另外Cl⁻丢失过多使近曲小管Cl⁻重吸收减少，为维持离子平衡，代偿性地重吸收HCO₃⁻增加，以上共同导致碱中毒。大量胃液的丢失相应地失去了Na⁺，机体代偿过程中，Na⁺-K⁺交换和Na⁺-H⁺交换增加，导致K⁺和H⁺的排出增多，以上机制共同导致了低氯、低钾性碱中毒（B对）。低钾低氯性碱中毒发生的常见情况：剧烈呕吐（如幽门梗阻）、肺心病（利尿过多过猛烈导致副作用），肝硬化（利尿过度、大量排放腹腔积液副作用）。","","N"],["2024-N58",10,"第四节 局部麻醉","利多卡因",2024,58,"A","","使用利多卡因行局部浸润麻醉时，单次最大剂量是",[["A","100mg"],["B","200mg"],["C","400mg"],["D","600mg"]],"C","使用利多卡因行局部浸润麻醉、神经阻滞时，单次最大剂量是400mg（C对）。使用利多卡因单次表面麻醉最大剂量是100mg（A错）。","","N"],["2024-N59",5,"第六节 有芽胞厌氧菌感染","破伤风临床表现",2024,59,"A","","下列有关破伤风的叙述，正确的是",[["A","最先出现颈部肌肉强烈收缩"],["B","光线不能诱发全身肌肉痉挛"],["C","发作时神志不清"],["D","可出现尿潴留"]],"D","破伤风是破伤风杆菌经由皮肤或黏膜伤口侵入人体，在缺氧环境下生长繁殖，产生毒素而引起阵发性肌肉痉挛的一种特异性感染，可能发生在各种创伤后，也可能发生在不洁条件下分娩的产妇和新生儿。破伤风杆菌产生痉挛毒素和溶血毒素。潜伏期通常为1周，也可短至1～2日或长达数月、数年，时间越短，预后越差。典型表现是由咀嚼肌（A错）依次累及面肌、颈项肌、背腹肌、四肢肌群、膈肌与肋间肌群，病人会形成“苦笑面容”、“角弓反张”，在肌肉强直的基础上，轻微的刺激，如声、光（B错）、触碰，或是咳嗽、吞咽等均可诱发强烈的阵发性痉挛，发作时病人呼吸急促、面色发绀、手足抽搐、头频频后仰、全身大汗，在痉挛、抽搐状况下，病人神志仍保持清醒（C错）。括约肌痉挛可引起尿潴留（D对）或便秘、吞咽困难致摄入营养障碍，持续的呼吸肌、膈肌与声门痉挛，可致窒息死亡。病程一般为3～4周，如处理适当，症状可逐渐减轻，痊愈后仍有一段时间的局部肌肉紧张或反射亢进。","","N"],["2024-N60",17,"第一节 甲状腺疾病","髓样癌",2024,60,"A","","下列关于甲状腺髓样癌的叙述，错误的是",[["A","临床较少见"],["B","起源于甲状腺滤泡上皮"],["C","分泌降钙素"],["D","可兼有淋巴和血行转移"]],"B","甲状腺髓样癌（MTC）占甲状腺癌6%，临床较少见（A对），属中度恶性肿瘤，起源于滤泡旁降钙素分泌细胞（B错，为本题正确答案），可分泌降钙素（C对），降钙素水平升高是MTC的重要标志，甲状腺肿块合并降钙素升高可确定诊断。MTC倾向于早期颈部淋巴结转移，微小癌也可以伴发转移，并可沿血道转移至肝、肺、脑等组织器官（D对）。除髓样癌外，绝大多数甲状腺癌起源于滤泡上皮细胞，主要包括甲状腺乳头状癌、甲状腺滤泡状癌。","","N"],["2024-N61",18,"第三节 乳腺良性疾病","导管内乳头状瘤诊断",2024,61,"A","","女性，45岁。间断出现乳头血性溢液半年。最可能的诊断是",[["A","乳头湿疹样癌"],["B","乳腺囊性增生症"],["C","乳管内乳头状瘤"],["D","乳腺纤维腺瘤"]],"C","中年女性患者，间断乳头血性溢液半年，最可能的诊断是乳管内乳头状瘤（C对），乳管内乳头状瘤多见于40～45岁经产妇，主要症状是乳头溢血性或浆液血性液体，而无疼痛，轻压乳晕区或挤压乳头时，有血性排液，可以帮助定位，治疗以手术为主，常规做病理检查。乳腺纤维腺瘤（D错）发病年龄以20～30岁最多，多数为单发，除肿块外，病人常无明显自觉症状，肿块增长缓慢，质似硬橡皮球的弹性感，表面光滑易于推动。乳腺囊性增生症（B错）常见于30～50岁的妇女，与卵巢功能失调有关，常有一侧或两侧乳房胀痛，轻者如针刺样，可累及肩部、上肢或胸背部，一般在月经来潮前明显，月经来潮后疼痛减轻或消失，少数病人可有乳头溢液，常为棕色、浆液性或血性液体，病程有时很长，但停经后症状常自动消失或减轻。乳头湿疹样癌（A错）是一种特殊类型的乳腺癌，又称Paget病，早期时常为一侧乳头瘙痒、变红，继而变为粗糙、增厚、糜烂，局部有痂皮、脱屑或渗出物，病变可逐步累及乳晕皮肤，初起时乳房内常没有肿块，病变进展后乳房内出现块状物。","","N"],["2024-N62",19,"第三节 气胸","张力性气胸",2024,62,"A","","张力性气胸时，首选的急救措施是",[["A","剖胸探查"],["B","胸膜腔穿刺减压"],["C","气管插管"],["D","气管切开"]],"B","张力性气胸时，首选的急救措施是胸膜腔穿刺减压（B对）或放置具有单向活瓣作用的胸腔穿刺针。开胸探查手术（A错）指征：进行性血胸、心脏大血管损伤、严重肺裂伤或气管、支气管损伤、食管破裂、胸腹或腹胸联合伤、胸壁大块缺损、胸内存留较大的异物。气管插管（C错）属于辅助呼吸措施（机械通气），目的是建立人工气道。气管切开（D错）主要用于支气管痉挛、喉头水肿、气道堵塞（不能解除）等严重呼吸困难者。","","N"],["2024-N63",20,"第三节 肺肿瘤","肺癌诊断",2024,63,"A","","男性，60岁。胸部X线片显示右肺上叶肺不张，并可见肺门部肿块影与之相邻。首先考虑的疾病是",[["A","周围型肺癌"],["B","肺结核"],["C","中央型肺癌"],["D","肺错构瘤"]],"C","老年男性患者（肿瘤好发年龄），胸部X线片显示右肺上叶肺不张（提示支气管完全阻塞），并可见肺门部肿块影与之相邻（提示淋巴结肿大），提示为中央型肺癌X线影像特征“反S征”，故首先考虑的疾病是中央型肺癌（C对）。肺癌的临床表现和癌肿的部位、大小、是否压迫、侵犯邻近器官以及有无转移等情况有着密切关系。中心型肺癌早期胸部X线片可无异常征象。当癌肿压迫阻塞支气管，排痰不畅，远端肺组织可发生感染（肺炎），当完全阻塞时发生肺不张。周围型肺癌（A错）最常见的X线表现为肺野周围孤立性圆形或椭圆形块，块影轮廓不规则，常呈现小的分叶或切迹，边缘模糊毛糙。肺错构瘤（D错）多见于男性青壮年，一般不出现症状，往往在胸部X线检查时发现，肿瘤呈圆形、椭圆形或分叶状块影，边界清楚，可以有钙化点，典型的表现为爆米花样钙化。肺结核（B错）在本例中主要是易和中央型肺癌混淆的肺门淋巴结结核，在X线平片上表现为肺门块影，多见于青少年，常有结核感染症状，注意本例中“倒S征”和“哑铃征”需要鉴别。","","N"],["2024-N64",23,"第一节 腹外疝概述","难复性疝",2024,64,"A","","男性，65岁。因右腹股沟斜疝行手术治疗，术中见疝囊的一部分由盲肠构成。应诊断为",[["A","肠管壁疝"],["B","滑动性疝"],["C","逆行性嵌顿疝"],["D","腹内疝"]],"B","疝囊壁的一部分由盲肠组成，该疝为滑动性疝（B对），疝囊壁的构成也可为乙状结肠或膀胱，见于右侧腹股沟。肠管壁疝（A错）或Richter疝，是指嵌顿的内容物仅为部分肠壁的嵌顿疝，系膜侧肠壁及其系膜并未进入疝囊，肠腔并未完全梗阻。逆行性嵌顿疝（C错）是指嵌顿肠管可包括几个肠袢，或呈“W”形，疝囊内各嵌顿肠袢之间的肠管可隐藏在腹腔内。腹内疝（D错）是由脏器或组织进入腹腔内的间隙囊内而形成，如网膜孔疝。","","N"],["2024-N65",50,"第二节 上肢神经损伤","桡神经损伤",2024,65,"A","","肱骨中下1/3骨折伴有桡神经损伤，可能丧失的运动功能是",[["A","伸指、伸腕"],["B","屈指、屈腕"],["C","伸指、并指"],["D","屈指、伸指"]],"A","桡神经损伤，可能丧失的运动功能是伸指、伸腕（A对）、伸拇、前臂旋后，典型的畸形是垂腕。与之相关的考点是，正中神经损伤导致的典型畸形为猿手，尺神经损伤导致的典型畸形为爪形手。","","N"],["2024-N66",57,"第二节 良性骨肿瘤","骨样骨瘤",2024,66,"A","","骨样骨瘤的好发部位是",[["A","颅骨"],["B","颈椎"],["C","肱骨"],["D","胫骨"]],"D","骨样骨瘤属于常见的良性骨肿瘤，好发年龄在5～20岁，男性较女性为多。好发部位以下肢长骨为主，70%～80%的病损在长骨，最常见于股骨、胫骨（D对）和肱骨的骨干或骨骺端，其次是脊柱、足、手骨。","","N"],["2024-N67",53,"第二节 腰椎退行性疾病","腰椎间盘突出症诊断",2024,67,"A","","男性，40岁。腰扭伤后反复腰痛2年，右下肢放射痛2个月，与劳累有关，咳嗽、用力排便可加重。骨科检查：右直腿抬高试验阳性，加强试验阳性。X线片示L₄₋₅椎间隙变窄。最可能的诊断是",[["A","急性腰扭伤"],["B","梨状肌综合征"],["C","腰椎管狭窄症"],["D","腰椎间盘突出症"]],"D","中年男性患者，腰扭伤后反复腰痛2年（提示首次发作诱因），右下肢放射痛2个月，与劳累有关，咳嗽、用力排便可加重（坐骨神经痛表现）。骨科检查：右腿直腿抬高实验阳性，加强实验阳性（提示坐骨神经受压），X线检查L₄₋₅间隙狭窄（腰椎间盘突出典型影像学表现），根据患者病史、临床表现和体征、影像学检查结果，最可能的诊断是腰椎间盘突出症（D对），通常情况下，腰腿痛＋腰椎间隙狭窄影像学检查结果，即可做出腰椎间盘突出症的初步诊断。急性腰扭伤（A错）通常不会出现下肢放射痛。梨状肌综合征（B错）主要表现为臀部和下肢疼痛，症状的出现和加重常与活动有关，休息可明显缓解，查体可见臀肌萎缩，臀部深压痛及直腿抬高试验阳性，但神经定位体征多不明确，髋关节外展、外旋位抗阻力时，可诱发症状。腰椎管狭窄（C错）是指多种原因所致椎管、神经根管、椎间孔的狭窄，并使相应部位的脊髓、马尾神经或神经根受压的病变，临床表现以下腰痛、马尾神经或腰神经受压症状为主要表现，以神经源性间歇性跛行为主要特点，临床特点为症状多而阳性体征少，结合CT和MRI检查可明确诊断。","","N"],["2024-N93",24,"第一节 腹部损伤概述","诊断性腹腔穿刺术",2024,93,"A","","男性，35岁。因车祸伤上腹痛2小时来院，诉腹痛剧烈，伴恶心、呕吐。查体：P130次/分，BP75/40mmHg，神志淡漠，全腹压痛、肌紧张，移动性浊音阳性，肠鸣音消失。为确定诊断，首选的检查是",[["A","立位腹平片"],["B","腹腔CT"],["C","腹腔穿刺"],["D","腹腔动脉造影"]],"C","中年男性患者，外伤致上腹部损伤2小时（上腹部损伤多为肝、脾损伤），诉腹痛剧烈，伴恶心，呕吐（腹部损伤常见表现，无特异性），查体：P130次/分（＞100次/分，脉搏明显加快），BP75/40mmHg（＜90/60mmHg，明显休克），神志淡漠（休克表现），全腹压痛，反跳痛，肌紧张（腹膜炎表现），移动浊音阳性，肠鸣音消失（腹膜炎表现），根据患者临床表现和体征，最可能的诊断是肝破裂导致失血性休克和胆汁性腹膜炎，为进一步确诊，首选检查是腹腔穿刺（C对），适用于怀疑有腹腔内出血或空腔脏器穿孔者，方法简便、快速、经济、安全，准确率达90%以上。腹腔CT（B错）对实质脏器损伤及其范围和程度有重要的诊断价值，但只适用于病情稳定又需要进一步明确诊断者。X线检查（A错）对空腔脏器损伤辅助诊断意义更大，但不适用于重伤，凡腹内脏器伤诊断已经确定，尤其是伴有休克者，应抓紧时间处理，不必再行X线检查，以免加重病情，延误治疗。腹腔动脉造影（D错）属侵入性检查手段，所要求的设备条件和技术条件也较高，不能普遍应用，对可疑肝、脾、膜、肾、十二指肠等脏器损伤，但其他检查方法未能证实者选择性血管造影可有很大帮助。","c205","N"],["2024-N94",24,"第一节 腹部损伤概述","是否存在多发性损伤",2024,94,"A","","男性，35岁。因车祸伤上腹痛2小时来院，诉腹痛剧烈，伴恶心、呕吐。查体：P130次/分，BP75/40mmHg，神志淡漠，全腹压痛、肌紧张，移动性浊音阳性，肠鸣音消失。最可能的诊断是",[["A","肝脾破裂"],["B","小肠破裂"],["C","胃破裂"],["D","腹膜后血肿"]],"A","中年男性患者，外伤致上腹部损伤2小时（上腹部损伤多为肝、脾损伤），诉腹痛剧烈，伴恶心，呕吐（腹部损伤常见表现，无特异性），查体：P130次/分（＞100次/分，脉搏明显加快），BP75/40mmHg（＜90/60mmHg，明显休克），神志淡漠（休克表现），全腹压痛，反跳痛，肌紧张（腹膜炎表现），移动浊音阳性，肠鸣音消失（腹膜炎表现），根据患者临床表现和体征，最可能的诊断是肝脾破裂（A对）导致失血性休克和胆汁性腹膜炎。胃破裂（C错）、小肠破裂（B错）主要表现是弥漫性腹膜炎，除胃肠道症状之外，最突出的表现是腹膜刺激征，严重时可发生感染性休克，但出血量一般不大（除非临近大血管有合并损伤）。腹膜后血肿（D错）多系高处坠落、挤压、车祸等所致腹膜后脏器（胰、肾、十二指肠）损伤，或骨盆或下段脊柱骨折和腹膜后血管损伤所引起，突出的表现是内出血征象、腰背痛和肠麻痹。","c205","N"],["2024-N95",24,"第一节 腹部损伤概述","腹部损伤处理",2024,95,"A","","男性，35岁。因车祸伤上腹痛2小时来院，诉腹痛剧烈，伴恶心、呕吐。查体：P130次/分，BP75/40mmHg，神志淡漠，全腹压痛、肌紧张，移动性浊音阳性，肠鸣音消失。在开放静脉输液的同时，首选的治疗方法是",[["A","保守治疗、观察"],["B","急诊剖腹探查"],["C","经腹腔动脉介入治疗"],["D","腹腔镜探查"]],"B","中年男性患者，外伤致上腹部损伤2小时（上腹部损伤多为肝、脾损伤），诉腹痛剧烈，伴恶心，呕吐（腹部损伤常见表现，无特异性），查体：P130次/分（＞100次/分，脉搏明显加快），BP75/40mmHg（＜90/60mmHg，明显休克），神志淡漠（休克表现），全腹压痛，反跳痛，肌紧张（腹膜炎表现），移动浊音阳性，肠鸣音消失（腹膜炎表现），根据患者临床表现和体征，最可能的诊断是肝脾破裂，继而导致失血性休克和胆汁性腹膜炎，此时需要积极抗休克，故在静脉输液的同时，还需首先采取的治疗措施为急诊剖腹探查（B对），特别是考虑到本例为肝脾破裂，首选手术治疗，要求彻底清创、确切止血、消除胆汁溢漏和建立通畅引流。闭合损伤需要急诊剖腹探查指征：①有明确的腹膜刺激征；②有腹腔游离气体；③腹腔穿刺或灌洗发现胆汁污染或肠内容物；④胃肠道出血；⑤持续低血压而难以用腹部以外的原因解释。本例明显休克，并有急性腹膜炎表现，不适合保守治疗和观察（A错），需要立刻处理。腹腔镜探查（D错）可应用于一般状况良好而不能明确有无或何种腹内脏器伤的病人。经腹腔动脉介入治疗（C错）如脾动脉栓塞术具有创伤小、无需特殊麻醉、手术时间短，疗效显著并发症少等特点，但目前对于介入治疗脾破裂的指征和适应证尚未达成统一，且本例合并肝脏损伤，在未能确定其他脏器损伤的条件下，经腹腔动脉介入治疗并不适用。","c205","N"],["2024-N96",40,"第二节 良性前列腺增生的诊断","良性前列腺增生临床表现",2024,96,"A","","男性，75岁。进行性排尿异常5年，表现为尿频、尿等待、排尿不能成线，常因尿液不自觉流出而湿内裤，直肠指诊示前列腺增大，中间沟变浅。该患者目前存在的情况是",[["A","真性尿失禁"],["B","急迫性尿失禁"],["C","压力性尿失禁"],["D","充溢性尿失禁"]],"D","老年男性患者，进行性排尿异常5年，现为尿频，尿等待，排尿不能成线（提示前列腺增生导致尿路梗阻），常因尿液不自觉流出而打湿内裤（尿失禁表现），直肠指诊示前列腺增大，中间沟变浅（提示前列腺增生），根据患者病史、临床表现和体征，最可能的诊断是良性前列腺增生，该患者目前存在的情况为充溢性尿失禁，系前列腺增生导致下尿路梗阻严重，当梗阻加重达一定程度时，残余尿逐渐增加，膀胱过度充盈时，膀胱内压超过尿道压，尿液不自主从尿道口溢出，发生充溢性尿失禁（D对）。压力性尿失禁（C错）是指当腹内压突然增高（咳嗽、喷嚏、大笑、运动等）时，尿液不随意地流出，可见于多次分娩和绝经后妇女（盆底肌松弛），也见于根治性前列腺切除术损伤尿道外括约肌时，多在直立体位时发生。急迫性尿失禁（B错）可能由膀胱的不随意收缩引起，发生严重的尿频、尿急而膀胱不受意识控制就开始排尿，通常继发于膀胱炎、神经源性膀胱以及重度膀胱出口梗阻。真性尿失禁（A错）又称为持续性尿失禁，是指尿液持续地昼夜从膀胱或泌尿道瘘中流出，几乎没有正常的排尿，膀胱呈空虚状态，常见的原因为外伤、手术或先天性疾病引起的膀胱颈和尿道括约肌的损伤。","c206","N"],["2024-N97",40,"第二节 良性前列腺增生的诊断","良性前列腺增生诊断",2024,97,"A","","男性，75岁。进行性排尿异常5年，表现为尿频、尿等待、排尿不能成线，常因尿液不自觉流出而湿内裤，直肠指诊示前列腺增大，中间沟变浅。导致此种情况最可能的原因是",[["A","慢性前列腺炎"],["B","良性前列腺增生"],["C","前列腺癌"],["D","膀胱癌"]],"B","老年男性患者，进行性排尿异常5年，现为尿频，尿等待，排尿不能成线（提示前列腺增生导致尿路梗阻），常因尿液不自觉流出而打湿内裤（尿失禁表现），直肠指诊示前列腺增大，中间沟变浅（提示前列腺增生），根据患者病史、临床表现和体征，最可能的诊断是良性前列腺增生（B对），通常情况下，以尿频、排尿不畅等临床表现为主诉的50岁以上男性患者，应首先考虑本病。慢性前列腺炎（A错）主要表现为长期、反复的会阴、下腹部等区域疼痛或不适，或表现为尿频、尿不尽，可伴有不同程度的性功能障碍、生育能力下降、精神、心理症状等一系列综合征，所不同的是没有反复尿路感染发作，有结节形成者，范围较局限，常有压痛，经抗感染治疗后，结节可缩小甚至消失。前列腺癌（C错）好发于前列腺外周带，也可伴有严重的尿急、尿频、血尿等下尿路症状，直肠指诊偶可扪及前列腺硬质结节，经直肠超声、磁共振等影像学检查可发现前列腺内的病灶，血清PSA明显升高，前列腺穿刺活检可确诊。膀胱癌（D错）最常见的症状是血尿，晚期多表现为尿频、尿急、尿痛。","c206","N"],["2024-N98",32,"第五节 胆道感染","急性结石性胆囊炎诊断与鉴别诊断",2024,98,"A","","男性，78岁。右上腹疼痛伴发热、恶心、呕吐5天入院。既往有高血压病10年，肺心病3年。查体：T38.5℃，P102次/分，R24次/分，BP156/98mmHg。皮肤、巩膜无黄染，右上腹明显压痛，轻度肌紧张，肠鸣音弱。化验：血Hb125g/L，WBC18.6×10⁹/L，血清淀粉酶286U/L，B超：胆囊12cm×6cm，壁厚0.6cm，腔内可见直径3cm结石一枚，总胆管直径0.8cm，肝下可见积液，胰腺显示不清。最可能的诊断是",[["A","急性胰腺炎"],["B","急性胆囊炎"],["C","急性胆管炎"],["D","十二指肠溃疡穿孔"]],"B","老年男性患者，右上腹疼痛伴发热、恶心呕吐5天（胆囊炎常见症状），查体：T38.5℃（＞37℃，中度发热），P102次/分（＞100次/分，脉率加快），R24次/分（＞20次/分，呼吸加快），BP156/98mmHg（＞140/90mmHg，高血压1级）。皮肤巩膜无黄染，右上腹明显压痛，轻度肌紧张（胆囊炎体征），肠鸣音减弱。化验：血Hb125g/L（男性Hb正常值120～160g/L），WBC18.6×10⁹/L（＞9.5×10⁹/L，提示感染），血淀粉酶286U/L（正常值35～135U/L，升高，提示胰腺受累），B超：胆囊12cm×6cm（5～8cm×3～5cm，胆囊增大），壁厚0.6cm（＞4mm，胆囊壁增厚），腔内可见直径3cm结石一枚（提示胆囊炎诱因），总胆管直径0.8cm，肝下可见积液（提示胆囊周围渗出），胰腺显示不清（提示胰腺受累），根据患者病史、临床表现体征、实验室检查结果和影像学表现，最可能的诊断是急性胆囊炎（B对）。急性胰腺炎（A错）表现为急性腹痛，常有恶心，频繁呕吐，且呕吐后腹痛不缓解，常有饮酒、油腻饮食的诱因，超声常见胰腺弥漫性肿大，轮廓线呈弧状膨出，有出血坏死时，可出现粗大的强回声。急性胆管炎（C错）临床主要表现为典型的上腹部剧烈疼痛、寒战高热和黄疸三联征（Charcot三联征），体温常高达40℃以上，脉率达120～140次/分钟，血压降低，呼吸浅快，轻度黄疸，剑突下压痛和肌紧张，肝区叩痛，有时可扪及肝大和胆囊肿大，超声可见肝内、外胆管不同程度地扩张，胆总管或肝内胆管结石，胆管壁增厚，胆囊增大。十二指肠溃疡穿孔（D错）多有长期溃疡病史和近期加重病史，最典型的表现是骤发性剧烈腹痛，如刀割样，呈持续性或阵发性加重，疼痛初始位于上腹部或心窝部，很快波及全腹但仍以上腹部为重，如病情进一步发展，病人可出现发热、心跳加快、血压下降、白细胞增高等全身感染中毒症状，腹胀、肠麻痹、腹腔积液等也随之出现并越来越重，体征有典型的急性腹膜炎“板状腹”表现，X线平片可见膈下游离气体。","c207","N"],["2024-N99",32,"第五节 胆道感染","手术方法",2024,99,"A","","男性，78岁。右上腹疼痛伴发热、恶心、呕吐5天入院。既往有高血压病10年，肺心病3年。查体：T38.5℃，P102次/分，R24次/分，BP156/98mmHg。皮肤、巩膜无黄染，右上腹明显压痛，轻度肌紧张，肠鸣音弱。化验：血Hb125g/L，WBC18.6×10⁹/L，血清淀粉酶286U/L，B超：胆囊12cm×6cm，壁厚0.6cm，腔内可见直径3cm结石一枚，总胆管直径0.8cm，肝下可见积液，胰腺显示不清。首选的治疗方法是",[["A","PTCD"],["B","急诊开腹手术"],["C","PTGD"],["D","保守治疗"]],"C","老年男性患者，右上腹疼痛伴发热、恶心呕吐5天（胆囊炎常见症状），查体：T38.5℃（＞37℃，中度发热），P102次/分（＞100次/分，脉率加快），R24次/分（＞20次/分，呼吸加快），BP156/98mmHg（＞140/90mmHg，高血压1级）。皮肤巩膜无黄染，右上腹明显压痛，轻度肌紧张（胆囊炎体征），肠鸣音减弱。化验：血Hb125g/L（男性Hb正常值120～160g/L），WBC18.6×10⁹/L（＞9.5×10⁹/L，提示感染），血淀粉酶286U/L（正常值35～135U/L，升高，提示胰腺受累），B超：胆囊12cm×6cm（5～8cm×3～5cm，胆囊增大），壁厚0.6cm（＞4mm，胆囊壁增厚），腔内可见直径3cm结石一枚（提示胆囊炎诱因），总胆管直径0.8cm，肝下可见积液（提示胆囊周围渗出），胰腺显示不清（提示胰腺受累），根据患者病史、临床表现体征、实验室检查结果和影像学表现，最可能的诊断是急性胆囊炎，治疗最终需要手术治疗，原则上应争取择期手术。考虑到本例患者高龄，且有高血压、肺心病等多脏器慢性病，考虑到老年患者急性期手术的危险性（B错），目前首选的治疗方式是超声引导下经皮经肝胆囊穿刺引流术（PTGD）（C对），以达到减压和引流的目的。保守治疗（D错）主要作为术前准备，经非手术治疗能够控制病情发展，为择期手术创造良好的条件。PTCD即经皮肝穿刺胆管引流（A错）用于急性胆管炎需急性减压引流的情况，可作为不能耐受外科手术的急性梗阻性化脓性胆管炎暂时性外引流，也可作为肝门部胆管癌或胰头癌术前减轻黄疸、改善肝功能，以提高手术安全性的一种手段。","c207","N"],["2024-N100",30,"第二节 肝脓肿","细菌性肝脓肿诊断",2024,100,"A","","女性，64岁。持续右上腹痛伴寒战、高热3天入院。既往有冠心病3年，糖尿病2年。查体：T39.6℃，巩膜无黄染，右肋缘下深压痛，无肌紧张，肝区叩痛阳性。化验：血WBC15.8×10⁹/L，B超：肝稍大，胆囊7cm×4cm，壁厚0.4cm，呈淤胆状，肝右叶可见8cm×6cm低回声区。最可能的诊断是",[["A","急性胆囊炎"],["B","急性胆管炎"],["C","肝癌"],["D","肝脓肿"]],"D","老年女性患者，既往冠心病3年，糖尿病2年（肝脓肿高发人群），持续性右上腹痛伴寒战高热3天，查体：T39.6℃（＞37℃，高热），巩膜无黄染，右肋缘下深压痛，无肌紧张，肝区叩痛阳性（肝脓肿体征）。化验：血WBC15.8×10⁹/L（＞9.5×10⁹/L，提示感染），B超：肝稍大，胆囊7cm×4cm，壁厚0.4cm，呈淤胆状（提示继发胆汁排出障碍），肝右叶可见8cm×6cm低回声区（提示肝脓肿），根据患者病史、临床表现和体征、实验室检查结果和影像学检查，最可能的诊断是肝脓肿（D对）。通常情况下，寒战高热＋肝区疼痛＋肝大＋超声检查结果，即可得出明确诊断。急性胆囊炎（A错）多表现为急腹症，常在进脂肪餐后或夜间发作，可有Murphy征（+），B超可见增大的胆囊，胆囊壁增厚，胆囊周围有渗出，也可探及胆囊内结石。急性胆管炎（B错）临床主要表现为典型的上腹部剧烈疼痛、寒战高热和黄疸三联征（Charcot三联征），体温常高达40℃以上，脉率达120～140次/分钟，血压降低，呼吸浅快，轻度黄疸，剑突下压痛和肌紧张，肝区叩痛，有时可扪及肝大和胆囊肿大，超声可见肝内、外胆管不同程度地扩张，胆总管或肝内胆管结石，胆管壁增厚，胆囊增大。肝癌（C错）早期一般无明显症状，中晚期可有肝区疼痛，及如食欲减退、腹胀、恶心、呕吐、腹泻等非特异性消化道症状，较少发热，可有低热，血清AFP升高，超声可显示肿瘤的大小、形态、部位以及肝静脉或门静脉有无癌栓等。","c208","N"],["2024-N101",30,"第二节 肝脓肿","细菌性肝脓肿检查",2024,101,"A","","女性，64岁。持续右上腹痛伴寒战、高热3天入院。既往有冠心病3年，糖尿病2年。查体：T39.6℃，巩膜无黄染，右肋缘下深压痛，无肌紧张，肝区叩痛阳性。化验：血WBC15.8×10⁹/L，B超：肝稍大，胆囊7cm×4cm，壁厚0.4cm，呈淤胆状，肝右叶可见8cm×6cm低回声区。为明确诊断，首选的检查是",[["A","腹部CT"],["B","腹平片"],["C","ERCP"],["D","肝脏穿刺"]],"A","老年女性患者，既往冠心病3年，糖尿病2年（肝脓肿高发人群），持续性右上腹痛伴寒战高热3天，查体：T39.6℃（＞37℃，高热），巩膜无黄染，右肋缘下深压痛，无肌紧张，肝区叩痛阳性（肝脓肿体征）。化验：血WBC15.8×10⁹/L（＞9.5×10⁹/L，提示感染），B超：肝稍大，胆囊7cm×4cm，壁厚0.4cm，呈淤胆状（提示继发胆汁排出障碍），肝右叶可见8cm×6cm低回声区（提示肝脓肿），根据患者病史、临床表现和体征、实验室检查结果和影像学检查，最可能的诊断是肝脓肿。通常情况下，寒战高热＋肝区疼痛＋肝大＋超声检查结果，即可得出明确诊断。超声检查可以测定脓肿部位、大小及距体表深度，且为确定脓肿穿刺点或手术引流进路提供了方便，为首选检查方法。本题患者已进行超声检查，进一步检查首选腹部CT（A对）。该患者脓肿面积较大，肝脏穿刺（D错）可作为确诊检查或治疗方法，为有创检查，故不作为首选。腹平片（B错）对肝脓肿无明确诊断意义，非常规检查。ERCP（内镜逆行胰胆管造影术）（C错）主要用于胰胆管疾病的诊断与治疗。本题有争议，医学考试中心公布的标准答案为A。","c208","N"],["2024-N102",30,"第二节 肝脓肿","细菌性肝脓肿临床表现",2024,102,"A","","女性，64岁。持续右上腹痛伴寒战、高热3天入院。既往有冠心病3年，糖尿病2年。查体：T39.6℃，巩膜无黄染，右肋缘下深压痛，无肌紧张，肝区叩痛阳性。化验：血WBC15.8×10⁹/L，B超：肝稍大，胆囊7cm×4cm，壁厚0.4cm，呈淤胆状，肝右叶可见8cm×6cm低回声区。此病的最大危害是",[["A","转移扩散"],["B","脓毒症"],["C","破裂出血"],["D","肝功受损"]],"B","老年女性患者，既往冠心病3年，糖尿病2年（肝脓肿高发人群），持续性右上腹痛伴寒战高热3天，查体：T39.6℃（＞37℃，高热），巩膜无黄染，右肋缘下深压痛，无肌紧张，肝区叩痛阳性（肝脓肿体征）。化验：血WBC15.8×10⁹/L（＞9.5×10⁹/L，提示感染），B超：肝稍大，胆囊7cm×4cm，壁厚0.4cm，呈淤胆状（提示继发胆汁排出障碍），肝右叶可见8cm×6cm低回声区（提示肝脓肿），根据患者病史、临床表现和体征、实验室检查结果和影像学检查，最可能的诊断是肝脓肿。通常情况下，寒战高热＋肝区疼痛＋肝大＋超声检查结果，即可得出明确诊断。此病最大的危害是脓肿未得到有效控制和治疗，脓肿导致脓毒症（B对），向肝内或邻近脏器浸润引起相应的并发症，细菌性肝脓肿一旦发生并发症，病死率成倍增加。","c208","N"],["2024-N103",57,"第四节 原发性恶性骨肿瘤","骨肉瘤诊断",2024,103,"A","","男性，17岁。外伤后左膝部持续性疼痛2月余。骨科检查：左膝部肿胀，皮温升高，静脉怒张，关节活动受限。首先考虑的疾病是",[["A","骨结核"],["B","风湿性关节炎"],["C","骨肉瘤"],["D","骨髓炎"]],"C","青少年男性患者，外伤（可能诱因）后左膝部持续性疼痛2月余（恶性骨肿瘤多有疼痛表现，骨肉瘤好发于股骨远端、胫骨近端），骨科检查：左膝部肿胀，皮温升高，静脉怒张，关节活动受限（骨肉瘤典型表现），根据患者病史、临床表现和体征，最可能的诊断是骨肉瘤（C对），骨肉瘤为骨组织原发恶性肿瘤，可有轻微外伤史，也可没有任何诱因，通过典型的疼痛和肿块、局部发热和静脉怒张的表现可做出判断，影像学检查和血清学检查有助于确诊。骨结核（A错）多有结核病全身表现，如低热、乏力、盗汗，典型病例还可见消瘦、食欲差、贫血等症状，是最常见的肺外继发性结核，脊柱结核最多，其特征性X线表现为区域性骨质疏松和周围少量钙化的破坏性病灶，可有特征性的“冷脓肿/寒性脓肿”。骨髓炎（D错）一般起病较急，伴有寒战高热，患肢剧痛，不敢活动，长骨干骺端有深压痛，通常发病2周后逐渐出现松质，虫蚀样散在骨破坏，有骨膜反应、新骨形成等。风湿性关节炎（B错）是溶血性链球菌感染所引起的全身变态反应性疾病，常有咽峡炎、丹毒等感染病史，关节红、肿、热、痛明显，不能活动，发病的部位常常是膝、髋、踝等下肢大关节，表现为多关节游走性疼痛，持续时间不长，数日可消退，治愈后很少复发，关节不遗留畸形，但可并发心脏病变。","c209","N"],["2024-N104",57,"第四节 原发性恶性骨肿瘤","骨肉瘤影像学表现",2024,104,"A","","男性，17岁。外伤后左膝部持续性疼痛2月余。骨科检查：左膝部肿胀，皮温升高，静脉怒张，关节活动受限。最可能的X线片表现是",[["A","“日光射线”形态"],["B","虫蚀样骨破坏"],["C","局限性骨质疏松"],["D","关节间隙变窄"]],"A","青少年男性患者，外伤（可能诱因）后左膝部持续性疼痛2月余（恶性骨肿瘤多有疼痛表现，骨肉瘤好发于股骨远端、胫骨近端），骨科检查：左膝部肿胀，皮温升高，静脉怒张，关节活动受限（骨肉瘤典型表现），根据患者病史、临床表现和体征，最可能的诊断是骨肉瘤，最可能的X线片表现是日光射线形态（A对），为新生瘤骨与长骨纵轴成直角时的表现，肿瘤穿破骨皮质后，软组织包块边缘会将正常骨外膜顶起，后者受刺激后所产生的骨膜反应形成Codman三角。虫蚀样骨破坏（B错）是尤文氏肉瘤的特征之一。局限性骨质疏松（C错）多见于骨与关节结核，是其最早的放射学表现。关节间隙变窄（D错）可见于膝关节结核、脊柱结核、强直性脊柱炎、骨关节炎等多种疾病，不具有特异性。","c209","N"],["2024-N105",57,"第四节 原发性恶性骨肿瘤","骨肉瘤诊断",2024,105,"A","","男性，17岁。外伤后左膝部持续性疼痛2月余。骨科检查：左膝部肿胀，皮温升高，静脉怒张，关节活动受限。下列检查中，对进一步诊断最有帮助的是",[["A","血常规"],["B","血沉和抗链“O”滴度"],["C","血清碱性磷酸酶"],["D","血培养"]],"C","青少年男性患者，外伤（可能诱因）后左膝部持续性疼痛2月余（恶性骨肿瘤多有疼痛表现，骨肉瘤好发于股骨远端、胫骨近端），骨科检查：左膝部肿胀，皮温升高，静脉怒张，关节活动受限（骨肉瘤典型表现），根据患者病史、临床表现和体征，最可能的诊断是骨肉瘤，对进一步诊断有意义的是血清碱性磷酸酶（C对）。骨肉瘤的治疗要点是术前化疗＋手术＋术后化疗。大多数骨与软组织肿瘤的实验室指标都在正常范围，结合影像学表现，异常的实验室指标具有一定的参考价值，如果碱性磷酸酶明显升高，要侧重考虑骨肉瘤，如果出现白细胞升高，血沉加快，CRP增高等炎症性表现，要侧重考虑尤因肉瘤，如果PSA升高，首先考虑前列腺癌骨转移。对肉瘤患者行血常规（A错）和血培养（D错）无诊断意义。血沉和抗链“O”滴度增高（B错）有助于诊断风湿性关节炎。","c209","N"],["2024-N106",54,"第二节 化脓性关节炎","化脓性关节炎诊断",2024,106,"A","","患者男，8岁。1天前出现发热，体温39℃，左膝关节肿痛，活动受限。骨科检查：左膝关节明显红、肿、热及压痛，关节活动度30～40度，X线片：左膝关节间隙增宽。最可能的诊断是",[["A","关节结核"],["B","风湿性关节炎"],["C","类风湿关节炎"],["D","化脓性关节炎"]],"D","8岁患儿（常见人群），发热一天，左膝关节压痛，活动受限（提示骨关节感染），骨科检查：左膝关节红肿热以及压痛，活动度30～40度（化脓性关节炎典型表现），X线检查：左膝关节间隙增宽（儿童化脓性关节炎典型影像学表现），根据患者临床表现和体征及影像学检查结果，最可能的诊断是化脓性关节炎（D对），结合局部症状和体征不难诊断，X线表现出现较晚，一般不能作为诊断依据。关节结核（A错）是结核分枝杆菌引起的继发性感染性疾病，常有结核病史，大多为单发性，起病前往往有局部外伤史，病变部位初起隐痛，活动后加剧，儿童病人常有“夜啼”，浅表关节检查可见关节肿胀和积液，并有压痛，关节常处于半屈曲状态，以缓解疼痛，晚期病人可见肌肉萎缩，关节呈梭形肿胀。风湿性关节炎（B错）是溶血性链球菌感染所引起的全身变态反应性疾病，常有咽峡炎、丹毒等感染病史，关节红、肿、热、痛明显，不能活动，发病的部位常常是膝、髋、踝等下肢大关节，表现为多关节游走性疼痛，持续时间不长，数日可消退，治愈后很少复发，关节不遗留畸形，但可并发心脏病变。类风湿关节炎（C错）属于自身免疫性疾病，好发于手、腕、足等小关节，表现为全身多发性和对称性慢性关节炎，其特点是关节痛和肿胀反复发作伴进行性发展，最终导致关节破坏、强直和畸形。","c210","N"],["2024-N107",54,"第二节 化脓性关节炎","关节腔注射抗生素",2024,107,"A","","患者男，8岁。1天前出现发热，体温39℃，左膝关节肿痛，活动受限。骨科检查：左膝关节明显红、肿、热及压痛，关节活动度30～40度，X线片：左膝关节间隙增宽。首选的治疗方案是",[["A","全身抗结核治疗"],["B","应用非甾体抗炎药"],["C","关节腔内注射抗生素"],["D","关节滑膜切除"]],"C","8岁患儿（常见人群），发热一天，左膝关节压痛，活动受限（提示骨关节感染），骨科检查：左膝关节红肿热以及压痛，活动度30～40度（化脓性关节炎典型表现），X线检查：左膝关节间隙增宽（儿童化脓性关节炎典型影像学表现），根据患者临床表现和体征及影像学检查结果，最可能的诊断是化脓性关节炎，下一步治疗是关节腔内注射抗生素（C对），每次治疗时抽净积液后注入抗生素，此后1～2次/天，直到关节液清亮，镜检正常。全身抗结核治疗（A错）属于骨关节结核的治疗，若治疗效果无效，可行关节滑膜切除（D错），关节滑膜切除也可作为类风湿关节炎的手术治疗方案。非甾体抗炎药（B错）一般作为非感染性骨关节疾病的对症治疗，对感染性骨关节疾病使用，可能会掩盖症状，延误病情，常规不应用。","c210","N"],["2024-N132",30,"第一节 肝解剖生理概要","肝的血供",2024,132,"B","","肝脏供血主要来源于",[["A","肝动脉"],["B","肝静脉"],["C","肝短静脉"],["D","门静脉"]],"D","肝脏的供血主要源于门静脉（D对），约占全部血供的70%～75%，其余25%～30%来自肝动脉（A错）。","","N"],["2024-N133",30,"第一节 肝解剖生理概要","肝的血供",2024,133,"B","","肝脏供氧主要来源于",[["A","肝动脉"],["B","肝静脉"],["C","肝短静脉"],["D","门静脉"]],"A","肝脏的供氧主要源于肝动脉（A对），肝动脉血含氧量高，但由于血流量少，只能供给肝所需氧量的40%～60%，而门静脉血含氧虽低些，但由于血流量多，也能提供肝剩余需氧量，同时门静脉（D错）收集肠道血液，供给肝营养。","","N"],["2024-N134",32,"第五节 胆道感染","急性梗阻性化脓性胆管炎临床表现",2024,134,"B","","Charcot三联征出现在",[["A","急性胆囊炎"],["B","急性化脓性胆管炎"],["C","重症急性胰腺炎"],["D","急性化脓性阑尾炎"]],"B","Charcot三联征包括上腹部剧烈疼痛、寒战高热和黄疸三联征，是急性化脓性胆管炎（B对）的典型临床表现和早期症状，当胆管梗阻和感染进一步加重时，其临床表现将继续发展，出现低血压和神志改变与之前的三项统称为Reynolds五联征，是诊断AOSC（急性梗阻性化脓性胆管炎）不可缺少的诊断依据。","","N"],["2024-N135",33,"第二节 胰腺炎","重症急性胰腺炎",2024,135,"B","","Cullen征出现在",[["A","急性胆囊炎"],["B","急性化脓性胆管炎"],["C","重症急性胰腺炎"],["D","急性化脓性阑尾炎"]],"C","急性胰腺炎病情严重时，患者腰部水肿，皮肤呈片状青紫色改变，称为Grey-Turner征，脐周皮肤呈青紫色改变则称Cullen征，这种皮肤改变是急性胰腺炎时胰液外溢至皮下组织间隙，溶解皮下脂肪，毛细血管破裂出血所致，也是病情较重的临床表现，提示重症急性胰腺炎（C对）。","","N"],["2024-N160",26,"第二节 胃癌及其他胃肿瘤","胃癌手术治疗",2024,160,"X","","胃癌的手术方式有",[["A","胃部分切除术"],["B","胃远端/近端大部切除或全胃切除术"],["C","胃癌扩大根治术"],["D","联合脏器切除"]],"ABCD","胃癌的手术方式可根据早期胃癌和进展期胃癌有所区别。早期胃癌的手术方式有：内镜下黏膜切除术或黏膜下切除术、腹腔镜下或开腹胃部分切除术（A对）、保留幽门的胃切除术、保留迷走神经的胃部分切除术和D₁手术等。进展期胃癌的手术方式有：胃癌根治术（包括根治性远端或近端胃大部切除术和全胃切除术）（B对）、扩大胃癌根治术（C对）与联合脏器切除术（D对）、姑息手术。","","N"],["2024-N161",27,"第五节 肠系膜血管缺血性疾病","肠系膜血管缺血性疾病病因",2024,161,"X","","肠系膜上静脉血栓形成的原因有",[["A","肝硬化门静脉高压症"],["B","腹腔感染"],["C","真性红细胞增多症"],["D","脾切除术后"]],"ABCD","肠系膜上静脉血栓形成最常见的原因是血液凝血病如真性红细胞增多症（C对）等，其他原因包括腹腔感染（B对）、肝硬化门静脉高压（A对）、钝性创伤或手术创伤、肾移植、脾切除（D对）等，口服避孕药引起静脉血栓形成的可能性也不容忽视。","","N"],["2024-N162",31,"门静脉高压","门静脉高压肝功能相关检查",2024,162,"X","","对评估肝功能分级有重要参考价值的指标有",[["A","血清胆红素"],["B","血清转氨酶"],["C","血清白蛋白"],["D","凝血酶原时间"]],"ACD","对评估肝功能分级有重要参考价值的指标包括：血清胆红素（A对）、血清白蛋白（C对）、凝血酶原延长时间（D对）、腹水情况、肝性脑病情况。","","N"],["2024-N163",32,"第八节 胆道疾病常见并发症","胆道出血病因",2024,163,"X","","胆道出血的原因有",[["A","肝脏损伤"],["B","胆囊炎"],["C","胆管结石"],["D","肝脏肿瘤"]],"ACD","胆道出血是指由于损伤或感染等原因导致肝内、外胆管与毗邻血管之间形成病理性内瘘，血液经胆管流入十二指肠，原因多样，合并结石的胆道梗阻和感染是胆道出血的首位原因，损伤致胆道出血见于肝暴力伤或锐器伤，医源性损伤如术中取石损伤胆管壁、经皮、经肝穿刺或手术肝胆管置管引流术中、术后均可导致胆道出血；其他原因如肝动脉瘤，肝癌等。大量胆道出血的典型表现具有三联征：①消化道出血：便血或呕血；②胆绞痛；③黄疸。肝脏损伤（A对）时，血液有时可通过损伤的胆管进入胆道导致胆道出血。根据8版黄家驷外科学，胆囊炎（B错）可导致胆囊黏膜炎症、溃疡或血管病变，引起胆道出血，但比较少见。胆管结石（C对）可导致胆管炎，胆管炎症及破溃可穿破伴行的肝动脉或门静脉，造成胆道出血。肝脏肿瘤（D对）破入肝内较大胆管，可引起胆道出血。本题有争议，医学考试中心公布的标准答案为ACD。","","N"],["2024-N164",53,"","",2024,164,"X","","脊髓型颈椎病可能的临床表现有",[["A","双足踩棉花感"],["B","双上肢麻木无力，浅反射减弱或消失"],["C","二便功能障碍"],["D","双下肢麻木无力，腱反射活跃或亢进"]],"ABCD","脊髓型颈椎病占颈椎病的10%～15%，病人出现上肢或下肢麻木无力、僵硬、双足踩棉花感（A对），足尖不能离地，触觉障碍，束胸感，双手精细动作笨拙，不能用筷子进餐，写字颤抖，手夹持东西无力等，在后期出现尿频或排尿、排便困难等大小便功能障碍（C对），检查时可有感觉障碍平面，肌力减退，四肢腱反射活跃或亢进（D对），而腹壁反射、提睾反射和肛门反射等浅反射减弱或消失（B对）。Hoffmann征、Babinski征等病理征可呈阳性。本型颈椎病需要与肌萎缩侧索硬化症和脊髓空洞症相鉴别。脊髓型颈椎病禁颈部理疗、按摩等，首选手术治疗。","","N"],["2024-N165",55,"第二节 脊柱结核","脊柱结核临床表现",2024,165,"X","","关于脊柱结核的叙述，正确的有",[["A","伴低热、盗汗、消瘦等全身症状"],["B","腰椎结核多数发生在附件"],["C","疼痛是最先出现的症状"],["D","寒性脓肿是少数患者就诊的原因"]],"ACD","腰椎结核病人可有低热、盗汗、消瘦等全身结核中毒症状（A对），疼痛是最先出现的症状（C对），常有较长期的腰部钝痛，夜间痛明显，局部痛为主，于劳动、咳嗽时加重，患处可有压痛、叩击痛及放射痛。拾物试验阳性。椎体破坏塌陷后会形成角状后凸畸形，为脊柱结核特有畸形。后期病人有腰大肌寒性脓肿形成，为少数病人就诊原因（D对）。因结核杆菌容易停留在椎体部，故腰椎结核多数发生在椎体，99%为椎体结核，1%为附件结核（B错）。MRI对脊柱结核的早期诊断具有较高价值，CT能早期发现确定病变范围。","","N"],["2025-N57",1,"第三节 钾代谢紊乱","低钾血症临床表现",2025,57,"A","","下列不属于低钾血症表现的是",[["A","腱反射消失"],["B","四肢乏力"],["C","恶心、呕吐"],["D","心电图T波高尖"]],"D","低钾血症指血清钾浓度低于3.5mmol/L，低钾血症最早的临床表现是肌无力，从四肢乏力（B对）进展到躯干和呼吸肌，神经系统表现包括腱反射减退或消失（A对），消化系统的表现为胃肠道功能紊乱，引发恶心、呕吐（C对）、腹胀、肠蠕动消失等，心脏受累表现为窦性心动过速、传导阻滞和节律异常，典型心电图改变为早期出现ST段压低、T波降低、增宽或倒置（D错，为本题正确答案），而T波高尖更常见于高钾血症。","","N"],["2025-N58",3,"第三节 感染性休克","感染性休克概述",2025,58,"A","","下列不属于全身炎症反应综合征的是",[["A","体温＞38℃"],["B","心率＜90次/分"],["C","呼吸＞20次/分"],["D","血白细胞＞12×10⁹/L"]],"B","全身炎症反应综合征（SIRS）指机体失控的自我持续放大和自我破坏的炎症瀑布反应，SIRS的诊断标准包括：体温＞38℃（A对）或＜36℃；心率＞90 次/分（B错，为本题正确答案）；呼吸急促＞20 次/分（C对）或过度通气，PaCO₂＜4.3kPa；白细胞计数＞12×10⁹/L（D对） 或＜4×10⁹/L，或未成熟白细胞＞10%。","","N"],["2025-N59",5,"第七节 外科应用抗菌药的原则","抗菌药物合理应用的基本原则",2025,59,"A","","下列抗菌药物应用原则的叙述，错误的是",[["A","严重感染可联合用药"],["B","轻症感染可口服给药"],["C","能单一用药者不必联合用药"],["D","体温正常即可停药"]],"D","抗菌药物在预防、控制与治疗外科感染中发挥重要作用，抗菌药物合理应用的基本原则包括：1.尽早确认致病菌；2.选择最佳的抗菌药物；3.制定合理的用药方案，其中需要考虑的要素有：1）对于单一抗菌药物不能控制的混合感染或严重感染时可以联合用药（A对）；2）感染局限或较轻、可接受口服给药者，应选用口服吸收完全的抗菌药物（B对）；3）能单一用药就不要联合用药（C对），不必要的联合用药会增加不良反应的风险和药物间的相互作用；4）抗菌药物一般在病人体温正常、白细胞计数正常、病情好转、局部病灶控制后停药，而不能仅仅因为体温正常就停药（D错，为本题正确答案）。","","N"],["2025-N60",40,"第二节 良性前列腺增生的诊断","良性前列腺增生直肠指诊",2025,60,"A","","常用于治疗前列腺增生症的联合用药方案是",[["A","α受体拮抗剂+5α还原酶抑制剂"],["B","β受体拮抗剂+5α还原酶抑制剂"],["C","α受体拮抗剂+β受体拮抗剂"],["D","β受体拮抗剂+植物类药"]],"A","前列腺增生症也称为良性前列腺增生（BPH），是引起男性老年人排尿障碍原因中最为常见的一种良性疾病，前列腺增生症的治疗包括：观察等待、药物治疗和手术治疗等，其中药物治疗的联合用药方案为α受体拮抗剂+5α还原酶抑制剂（A对），因为前列腺基质平滑肌中主要分布的是α₁受体，阻滞α₁受体能有效地降低膀胱颈及前列腺的平滑肌张力，减少尿道阻力，改善排尿功能，而5α还原酶抑制剂通过在前列腺内阻止睾酮转变为有活性的双氢睾酮，进而使前列腺体积部分缩小，改善排尿症状。β受体包括β₁受体、β₂受体和β₃受体，β₁受体主要分布于心脏，β₂受体主要分布于平滑肌上，β₃受体主要分布于白色及棕色脂肪组织，前列腺上无β受体分布，所以β受体拮抗剂对前列腺增生症治疗无效（BCD错）。","","N"],["2025-N61",21,"第一节 食管癌","食管癌手术治疗",2025,61,"A","","食管癌切除术最常用的食管替代物是",[["A","空肠"],["B","结肠"],["C","胃"],["D","回肠"]],"C","食管癌是一种常见的上消化道恶性肿瘤，食管癌的治疗原则是多学科综合治疗，包括手术、放射治疗和化学治疗，其中手术治疗是可切除食管癌的首选治疗方法，同时也能最大限度缓解患者的吞咽困难症状，食管癌切除术后消化道重建中最常用的食管替代物是胃（C对），同时也可根据病人个体情况选择空肠（A错）和结肠（B错），而回肠（D错）由于生理结构和功能差异，目前无法作为食管替代物。","","N"],["2025-N62",18,"第三节 乳腺良性疾病","纤维腺瘤概述",2025,62,"A","","下列关于乳房纤维腺瘤的叙述，正确的是",[["A","高发年龄为40～50岁"],["B","多数为单发"],["C","月经来潮时肿瘤可增大"],["D","肿瘤边界不清"]],"B","乳房纤维腺瘤是女性乳房良性肿瘤中发病率最高的肿瘤，约占良性肿瘤的75%，是小叶内纤维细胞对雌激素的敏感性异常增高所致，以青年女性常见，高发年龄是20～25岁（A错），约75%为单发（B对），除肿块外，病人常无明显自觉症状，月经周期对肿块的大小无明显影响（C错），肿块增长缓慢，质似硬橡皮球的弹性感，表面光滑，易于推动，肉眼观呈圆形或卵圆形结节状，与周围组织界限清楚（D错）。","","N"],["2025-N63",17,"第一节 甲状腺疾病","手术治疗",2025,63,"A","","符合甲状腺癌行双侧腺叶全切手术适应证的是",[["A","肿块直径2cm"],["B","肿块在腺体内"],["C","双侧颈部淋巴结转移"],["D","无颈部放射史"]],"C","甲状腺癌是最常见的甲状腺恶性肿瘤，以甲状腺内发现肿块为最常见的临床表现，手术是各型甲状腺癌（除未分化癌以外）的基本治疗方法，行甲状腺全切或近全切的适应证为：颈部有放射史（D错）；已有远处转移；双侧癌结节；甲状腺外侵犯（B错）；肿块直径大于4cm（A错）；不良病理类型：高细胞型、柱状细胞型、弥漫硬化型、岛状细胞或分化程度低的变型；双侧颈部多发淋巴结转移（C对）。","","N"],["2025-N64",28,"第二节 急性阑尾炎","全身症状",2025,64,"A","","下列关于急性阑尾炎穿孔时腹水性状的叙述，正确的是",[["A","草绿色，透明"],["B","黄色浑浊，含胆汁"],["C","血性，臭味重"],["D","稀薄脓性，略臭"]],"D","急性阑尾炎是外科常见病，是最多见的急腹症，当阑尾管壁坏死、穿孔后，经腹腔穿刺抽出的液体为稀薄脓性，略有臭味（D对）。草绿色，透明（A错）为结核性腹膜炎的腹水表现。黄色浑浊，含胆汁（B错）、无臭味为胃十二指肠急性穿孔时的腹水表现。血性，臭味重（C错）为绞窄性肠梗阻时的腹水表现。","","N"],["2025-N65",44,"第四节 骨折愈合过程","血肿炎症机化期",2025,65,"A","","骨折血肿炎症机化期需要的时间是",[["A","6小时"],["B","5天"],["C","2周"],["D","3个月"]],"C","骨折愈合是一个复杂而连续的过程，从组织学和细胞学的变化，可将这个过程分为：血肿炎症机化期、原始骨痂形成期和骨痂改造塑形期。在骨折伤后6～8小时（A错），内、外凝血系统被激活，与局部坏死组织引起无菌性炎性反应，随着纤维蛋白渗出，毛细血管增生，成纤维细胞、吞噬细胞侵人，逐步清除机化的血肿，形成肉芽组织并进而演变转化为纤维结缔组织，使骨折两断端连接在一起，此期即为血肿炎症机化期，需要2周（C对）时间。5天（B错）时骨折端附近骨外膜的成骨细胞正处于活跃增生，肉芽组织内成纤维细胞合成和分泌大量胶原纤维，促进骨折断端的连接。3个月（D错）为原始骨痂形成期所需要的时间，此期会形成内骨痂和外骨痂，随着骨痂不断钙化加强，骨折逐渐达到临床愈合。","","N"],["2025-N66",50,"第二节 上肢神经损伤","尺神经损伤",2025,66,"A","","腕掌侧切割伤，小指和环指内侧半感觉消失，夹纸试验阳性，可能损伤的神经是",[["A","正中神经"],["B","尺神经"],["C","桡神经"],["D","指掌侧总神经"]],"B","腕掌侧切割伤导致小指和环指内侧半感觉消失，夹纸试验阳性，可能损伤的神经是尺神经（B对），尺神经为臂丛内侧束延续，支配手部内在肌运动功能及感觉，尺神经运动功能障碍为第3、4蚓状肌麻痹所致的环、小指爪形手畸形，骨间肌和拇收肌麻痹所致的Froment征，手掌尺侧、环指尺侧及小指掌背侧的感觉障碍。正中神经（A错）由臂丛内、外侧束的正中神经内、外侧头组成，损伤后表现为拇短展肌、拇对掌肌麻痹所致的拇外展、对掌功能及拇、示指捏物功能丧失，感觉障碍位于手掌桡侧半，拇、示、中指和环指桡侧半，拇指指间关节和示、中指及环指桡侧半近侧指间关节以远的背面。桡神经（C错）来自臂丛后束，仅支配感觉，桡神经损伤后感觉障碍位于手背桡侧和桡侧2个半手指近侧指间关节以近。指掌侧总神经（D错）共3条，支配桡侧3个半手指掌面和近侧指关节以远背侧的皮肤。","","N"],["2025-N67",48,"第二节 脊髓损伤","不完全性脊髓损伤",2025,67,"A","","下列不属于不完全性脊髓损伤的是",[["A","前脊髓综合征"],["B","脊髓中央管周围综合征"],["C","脊髓半切综合征"],["D","马尾神经损伤"]],"D","脊髓损伤是脊柱骨折的严重并发症，由于椎体的移位或碎骨片突入于椎管内，使脊髓或马尾神经产生不同程度的损伤，可分为脊髓震荡、不完全性脊髓损伤、完全性脊髓损伤、脊髓圆锥损伤和马尾神经损伤（D错，为本题正确答案）。其中不完全性脊髓损伤指损伤平面以下保留某些感觉和运动功能，包括前脊髓综合征（A对）、脊髓中央管周围综合征（B对）、脊髓半切综合征（C对）。","","N"],["2025-N93",28,"第二节 急性阑尾炎","急性阑尾炎临床诊断",2025,93,"A","","女性，45岁。2天前自觉“胃痛”，后感觉右下腹疼痛并逐渐加重，伴恶心呕吐，1天来发热。查体：T38.8℃，P100次/分，R18次/分，BP90/60mmHg。下腹部明显压痛，右下腹肌紧张，肠鸣音1次/分。化验：血WBC19×10⁹/L，腹部超声示右下腹肠间积液，液深2.0cm。最可能的诊断是",[["A","卵巢囊肿蒂扭转"],["B","上消化道穿孔"],["C","急性机械性肠梗阻"],["D","穿孔性阑尾炎"]],"D","患者中年女性，2天前出现“胃痛”，后疼痛转移至右下腹并逐渐加重（急性阑尾炎的典型症状），伴有恶心呕吐、发热，查体：T38.8℃（正常参考值：36～37℃），P100次/分（正常参考值：60～100次/分），R18次/分，BP90/60mmHg（正常参考值：90～139/60～89mmHg），下腹明显压痛、右下腹肌紧张（腹膜刺激征，提示腹膜炎），肠鸣音减弱，辅助检查：WBC19×10⁹/L（正常参考值：3.5～9.5×10⁹/L，提示感染），腹部超声示右下腹肠间积液，液深2cm（提示阑尾穿孔）。综合患者的病史、症状、体征及辅助检查，该患者最可能的诊断是穿孔性阑尾炎（D对）。卵巢囊肿蒂扭转（A错）患者有明显而剧烈腹痛，腹部或盆腔检查中可扪及有压痛性的肿块。胃溃疡穿孔（B错）患者有长期反复腹痛的病史，然后突发上腹部“刀割样”疼痛，并迅速波及全腹，全腹压痛、反跳痛，以及腹肌紧张呈“板状腹”，立位X线检查可见膈下游离气体。肝脓肿（C错）以细菌性肝脓肿为主，典型症状是寒战、高热、肝区疼痛和肝大，部分病人可有黄疸，白细胞计数及中性粒细胞可明显增加，可见胆红素升高，血液细菌培养可阳性，超声检查可发现脓肿的液性暗区。","c220","N"],["2025-N94",28,"第二节 急性阑尾炎","切口选择",2025,94,"A","","女性，45岁。2天前自觉“胃痛”，后感觉右下腹疼痛并逐渐加重，伴恶心呕吐，1天来发热。查体：T38.8℃，P100次/分，R18次/分，BP90/60mmHg。下腹部明显压痛，右下腹肌紧张，肠鸣音1次/分。化验：血WBC19×10⁹/L，腹部超声示右下腹肠间积液，液深2.0cm。拟手术探查，适宜选择的切口是",[["A","上腹正中切口"],["B","右侧肋缘下切口"],["C","下腹正中切口"],["D","右下腹经腹直肌切口"]],"D","患者中年女性，2天前出现“胃痛”，后疼痛转移至右下腹并逐渐加重（急性阑尾炎的典型症状），伴有恶心呕吐、发热，查体：T38.8℃（正常参考值：36～37℃），P100次/分（正常参考值：60～100次/分），R18次/分，BP90/60mmHg（正常参考值：90～139/60～89mmHg），下腹明显压痛、右下腹肌紧张（腹膜刺激征，提示腹膜炎），肠鸣音减弱，辅助检查：WBC19×10⁹/L（正常参考值：3.5～9.5×10⁹/L，提示感染），腹部超声示右下腹肠间积液，液深2cm（提示阑尾穿孔）。综合患者的病史、症状、体征及辅助检查，该患者最可能的诊断是急性阑尾炎穿孔。手术探查，应选用右下腹经腹直肌切口（D对）。上腹正中切口（A错）常用于胃十二指肠溃疡穿孔，探查腹腔内污染情况，可暴露胃幽门和十二指肠，检查穿孔所在。右下肋缘切口（B错）主要用于肝胆区域的手术。下腹正中切口（C错）可用于腹股沟区疝中Stoppa 修补术的手术入路。","c220","N"],["2025-N95",25,"第二节 腹腔脓肿","盆腔脓肿诊断",2025,95,"A","","女性，45岁。2天前自觉“胃痛”，后感觉右下腹疼痛并逐渐加重，伴恶心呕吐，1天来发热。查体：T38.8℃，P100次/分，R18次/分，BP90/60mmHg。下腹部明显压痛，右下腹肌紧张，肠鸣音1次/分。化验：血WBC19×10⁹/L，腹部超声示右下腹肠间积液，液深2.0cm。术后第3天体温恢复正常。术后第6天体温再度升高，伴腹痛及里急后重。查体：T38.5℃，下腹部压痛，肠鸣音3次/分。化验：血WBC15×10⁹/L，Hb120g/L。最可能的诊断是",[["A","腹腔出血"],["B","伤口感染"],["C","盆腔脓肿"],["D","肠梗阻"]],"C","患者中年女性，2天前出现“胃痛”，后疼痛转移至右下腹并逐渐加重（急性阑尾炎的典型症状），伴有恶心呕吐、发热，查体：T38.8℃（正常参考值：36～37℃），P100次/分（正常参考值：60～100次/分），R18次/分，BP90/60mmHg（正常参考值：90～139/60～89mmHg），下腹明显压痛、右下腹肌紧张（腹膜刺激征，提示腹膜炎），肠鸣音减弱，辅助检查：WBC19×10⁹/L（正常参考值：3.5～9.5×10⁹/L，提示感染），腹部超声示右下腹肠间积液，液深2cm（提示阑尾穿孔）。术后第六天，再度出现发热，伴腹痛和里急后重的症状（直肠受到刺激，提示盆腔炎症），查体：体温38.5℃，下腹部有压痛，血WBC15×10⁹/L（正常参考值：3.5～9.5×10⁹/L，提示感染）。综合患者的病史、症状、体征及辅助检查，该患者最可能的诊断是盆腔脓肿（C对）。腹腔出血（A错）通常由于手术操作不当或术后并发症导致，多表现为腹痛、腹部膨隆、血压下降等症状，与该患者症状不符。伤口感染（B错）一般会有伤口局部的红肿、疼痛、发热甚至化脓，与该患者症状不符。肠梗阻（D错）典型症状包括腹痛、腹胀、呕吐和肛门停止排气排便，与该患者症状不符。","c220","N"],["2025-N96",27,"第四节 肠梗阻","是机械性还是动力性梗阻",2025,96,"A","","男性，68岁。阵发性下腹痛1周，加重3天伴停止排气排便来诊。既往体健。查体：BP130/80mmHg。腹部膨隆，全腹压痛，下腹部为重，无肌紧张，肠鸣音亢进。化验：血WBC12×10⁹/L，腹部X线平片提示小肠扩张，多发气液平。最可能的诊断是",[["A","上消化道穿孔"],["B","机械性肠梗阻"],["C","重症急性胰腺炎"],["D","急性化脓性阑尾炎"]],"B","患者老年男性，阵发性下腹痛1周，加重3天伴停止排气排便（肠梗阻典型症状），查体：BP130/80mmHg，腹部膨隆，全腹压痛，下腹部为重，无肌紧张，肠鸣音亢进（机械性肠梗阻典型体征），辅助检查：WBC12×10⁹/L（正常值：3.5～9.5×10⁹/L，提示感染），腹部X线平片提示小肠扩张，多发气液平（肠梗阻典型影像学表现）。根据患者症状、体征、辅助检查，该患者考虑诊断为机械性肠梗阻（B对）。上消化道穿孔（A错）患者有反复发作的上腹痛病史，典型症状为突发上腹部剧痛并迅速波及全腹，查体有明显的腹膜刺激征，立位X线检查可见膈下新月状游离气体影。重症急性胰腺炎（C错）常在饱餐或饮酒后突发，伴有明显的腹痛、腹胀、恶心呕吐，并可持续加重，然后逐渐出现循环、呼吸、肾及肝衰竭，早期病死率高。急性化脓性阑尾炎（D错）腹痛发作始于上腹，逐渐移向脐部，后转移并局限在右下腹，疼痛逐渐加重成持续性剧痛，可形成局限性腹膜炎，右下腹有局限性的压痛、反跳痛，腹肌紧张。","c221","N"],["2025-N97",27,"第四节 肠梗阻","肠梗阻辅助检查",2025,97,"A","","男性，68岁。阵发性下腹痛1周，加重3天伴停止排气排便来诊。既往体健。查体：BP130/80mmHg。腹部膨隆，全腹压痛，下腹部为重，无肌紧张，肠鸣音亢进。化验：血WBC12×10⁹/L，腹部X线平片提示小肠扩张，多发气液平。下列检查方法中不宜采用的是",[["A","腹部CT"],["B","钡剂上消化道造影"],["C","结肠镜"],["D","钡剂灌肠"]],"B","患者老年男性，阵发性下腹痛1周，加重3天伴停止排气排便（肠梗阻典型症状），查体：BP130/80mmHg，腹部膨隆，全腹压痛，下腹部为重，无肌紧张，肠鸣音亢进（机械性肠梗阻典型体征），辅助检查：WBC12×10⁹/L（正常值：3.5～9.5×10⁹/L，提示感染），腹部X线平片提示小肠扩张，多发气液平（肠梗阻典型影像学表现）。根据患者症状、体征、辅助检查，该患者考虑诊断为机械性肠梗阻。该患者目前不适合的检查是上消化道钡餐造影（B错，为本题正确答案），该检查目前不仅无法准确显示梗阻部位，还可能加重梗阻，导致钡剂滞留或穿孔等。腹部CT（A对）对于肠梗阻的诊断具有较高的准确性，能够清晰地显示肠道的形态、位置和梗阻的原因。结肠镜（C对）可用于协助诊断结直肠肿瘤等所致的肠梗阻。钡剂灌肠（D对）对于肠套叠、结肠肿瘤等所致的肠梗阻有一定的诊断意义，有助于了解梗阻的部位和性质。","c221","N"],["2025-N98",32,"第五节 胆道感染","急性梗阻性化脓性胆管炎诊断",2025,98,"A","","女性，55岁。1天前突发右上腹疼痛，伴恶心呕吐。2小时前寒战、发热来诊。既往胆囊结石病史10年。查体：T39.5℃，P100次/分，R18次/分，BP80/40mmHg。巩膜黄染。右上腹压痛，肝区叩击痛。化验：血WBC18×10⁹/L。最可能的诊断是",[["A","细菌性肝脓肿"],["B","上消化道穿孔"],["C","重症急性胰腺炎"],["D","急性梗阻性化脓性胆管炎"]],"D","患者中老年女性。既往胆囊结石病史10年（胆道感染的常见病因）。1天前突发右上腹疼痛（提示肝胆系疾病），伴恶心呕吐，2小时前出现寒战、发热，查体：T39.5℃（正常参考值：36～37℃，提示高热），P100次/分（正常参考值：60～100次/分），R18次/分，BP80/40mmHg（正常参考值：90～139/60～89mmHg，提示休克），巩膜黄染（提示黄疸），右上腹压痛，肝区叩击痛，辅助检查：血WBC18×10⁹/L（正常参考值：3.5～9.5×10⁹/L，提示感染）。根据患者的既往病史、临床表现、辅助检查，该患者最可能诊断的是急性梗阻性化脓性胆管炎（D对）。细菌性肝脓肿（A错）可继发于胆道梗阻、化脓性胆管炎时，细菌沿着胆管上行侵入肝脏，突发寒战、高热和持续性肝区钝痛或胀痛，可伴右肩牵涉痛，查体可见黄疸，肝脏肿大，有显著触痛，实验室检查见白细胞及中性粒细胞增高，转氨酶、碱性磷酸酶升高，重者胆红素升高，白蛋白下降。上消化道穿孔（B错）患者有反复发作的上腹痛病史，典型症状为突发上腹部剧痛并迅速波及全腹，查体有明显的腹膜刺激征，立位X线检查可见膈下新月状游离气体影。重症急性胰腺炎（C错）常在饱餐或饮酒后突发，伴有明显的腹痛、腹胀、恶心呕吐，并可持续加重，然后逐渐出现循环、呼吸、肾及肝衰竭，早期病死率高。","c222","N"],["2025-N99",32,"第五节 胆道感染","急性梗阻性化脓性胆管炎影像学检查",2025,99,"A","","女性，55岁。1天前突发右上腹疼痛，伴恶心呕吐。2小时前寒战、发热来诊。既往胆囊结石病史10年。查体：T39.5℃，P100次/分，R18次/分，BP80/40mmHg。巩膜黄染。右上腹压痛，肝区叩击痛。化验：血WBC18×10⁹/L。对明确诊断最有价值的检查是",[["A","腹部B超"],["B","MRCP"],["C","腹部CT"],["D","PTC"]],"B","患者中老年女性。既往胆囊结石病史10年（胆道感染的常见病因）。1天前突发右上腹疼痛（提示肝胆系疾病），伴恶心呕吐，2小时前出现寒战、发热，查体：T39.5℃（正常参考值：36～37℃，提示高热），P100次/分（正常参考值：60～100次/分），R18次/分，BP80/40mmHg（正常参考值：90～139/60～89mmHg，提示休克），巩膜黄染（提示黄疸），右上腹压痛，肝区叩击痛，辅助检查：血WBC18×10⁹/L（正常参考值：3.5～9.5×10⁹/L，提示感染）。根据患者的既往病史、临床表现、辅助检查，该患者最可能诊断的是急性梗阻性化脓性胆管炎。对明确诊断最有价值的检查是MRCP（B对），MRCP是一种无创诊断方法，能直观显示胆管分支形态，对胆道梗阻进行定位。腹部B超（A错）可用于胆道疾病的初步筛查，可以判断胆道梗阻的部位，但其精确度不如MRCP。腹部CT（C错）可以全面评估腹部各器官的情况，确定胆道梗阻的原因及部位，但对于胆管内部的细微结构显示不如MRCP。PTC（D错）（经皮肝穿刺胆道造影）虽能直接显示胆道形态，但属于有创检查，容易并发胆汁漏、出血及胆道感染，一般不作为首选检查方法。","c222","N"],["2025-N100",24,"第一节 腹部损伤概述","超声检查",2025,100,"A","","男性，34岁。1周前因车祸撞击左下胸部，卧床休息2天。1小时前背重物时突然晕倒来诊。查体：P110次/分，R30次/分，BP80/60mmHg，神清，面色苍白，左季肋区可见皮肤瘀斑。腹胀，全腹压痛及反跳痛，移动性浊音阳性，肠鸣音弱。为进一步明确诊断，急诊首选的腹部检查是",[["A","CT"],["B","B超"],["C","X线片"],["D","MRI"]],"B","患者青年男性。1周前因车祸撞击左下胸（脾位于左季肋区，胃底与膈之间，左下胸外伤容易引起脾破裂），卧床休息2天（脾破裂后被膜完整，出血量受到限制，不易被发现），1小时前因搬重物（诱因）突然晕倒来诊，查体：P110次/分（正常参考值：60～100次/分），R30次/分（正常成人静息状态下，呼吸为12～20次/分），血压80/60mmHg（正常参考值：90～139/60～89mmHg，提示大量出血导致休克），神清，面色苍白，左季肋区可见皮肤瘀斑，腹胀，全腹压痛及反跳痛，肌紧张（血液对腹膜的刺激所致），移动性浊音阳性（提示存在大量腹腔积血），肠鸣音减弱。为明确诊断，首选的检查是B超（B对），B超操作便捷，可以快速明确脾脏的损伤情况，同时可以动态观察伤情。CT（A错）虽可对脏器的损伤状况有更详细的了解，但其需要搬运患者，一般适用于伤情稳定的患者。X线片（C错）适用于胸部损伤、心肺病变、骨折的辅助诊断，对腹腔脏器的诊断效果欠佳。MRI（D错）虽然可以明确腹腔脏器的损伤情况，但检查时间较长，需要搬运患者，而该患者病情危急，所以不适用。","c223","N"],["2025-N101",24,"第二节 常见内脏损伤的特征和处理","脾损伤诊断",2025,101,"A","","男性，34岁。1周前因车祸撞击左下胸部，卧床休息2天。1小时前背重物时突然晕倒来诊。查体：P110次/分，R30次/分，BP80/60mmHg，神清，面色苍白，左季肋区可见皮肤瘀斑。腹胀，全腹压痛及反跳痛，移动性浊音阳性，肠鸣音弱。最可能的诊断是",[["A","脾破裂"],["B","肝破裂"],["C","肠系膜血管破裂"],["D","腹膜后血肿"]],"A","患者青年男性。1周前因车祸撞击左下胸（脾位于左季肋区，胃底与膈之间，左下胸外伤容易引起脾破裂），卧床休息2天（脾破裂后被膜完整，出血量受到限制，不易被发现），1小时前因搬重物（诱因）突然晕倒来诊，查体：P110次/分（正常参考值：60～100次/分），R30次/分（正常成人静息状态下，呼吸为12～20次/分），血压80/60mmHg（正常参考值：90～139/60～89mmHg，提示大量出血导致休克），神清，面色苍白，左季肋区可见皮肤瘀斑，腹胀，全腹压痛及反跳痛，肌紧张（血液对腹膜的刺激所致），移动性浊音阳性（提示存在大量腹腔积血），肠鸣音减弱。综合患者的外伤史、临床表现，该患者考虑诊断为脾破裂（A对）。肝破裂（B错）患者有右上腹外伤史，可出现失血性休克、胆汁性腹膜炎和腹腔继发性感染的相关表现。肠系膜血管破裂（C错）发生率较低，由腹部闭合性创伤所致，可伴有腹腔其他脏器损伤，临床表现为剧烈腹痛，可出现肠坏死和失血性休克。腹膜后血肿（D错）是腰腹部损伤的常见并发症，最常见原因是骨盆及脊柱骨折所致，突出的表现是内出血征象、腰背痛和肠麻痹，血肿巨大或伴有渗入腹腔者可有腹肌紧张、反跳痛、肠鸣音减弱或消失。","c223","N"],["2025-N102",24,"第一节 腹部损伤概述","腹部损伤处理",2025,102,"A","","男性，34岁。1周前因车祸撞击左下胸部，卧床休息2天。1小时前背重物时突然晕倒来诊。查体：P110次/分，R30次/分，BP80/60mmHg，神清，面色苍白，左季肋区可见皮肤瘀斑。腹胀，全腹压痛及反跳痛，移动性浊音阳性，肠鸣音弱。手术探查的顺序是",[["A","先探查胰腺，后探查肝脾"],["B","先探查肝脾，后探查胃肠道"],["C","先探查盆腔器官，后探查肝脾"],["D","最先探查肠系膜根部大血管"]],"B","患者青年男性。1周前因车祸撞击左下胸（脾位于左季肋区，胃底与膈之间，左下胸外伤容易引起脾破裂），卧床休息2天（脾破裂后被膜完整，出血量受到限制，不易被发现），1小时前因搬重物（诱因）突然晕倒来诊，查体：P110次/分（正常参考值：60～100次/分），R30次/分（正常成人静息状态下，呼吸为12～20次/分），血压80/60mmHg（正常参考值：90～139/60～89mmHg，提示大量出血导致休克），神清，面色苍白，左季肋区可见皮肤瘀斑，腹胀，全腹压痛及反跳痛，肌紧张（血液对腹膜的刺激所致），移动性浊音阳性（提示存在大量腹腔积血），肠鸣音减弱。综合患者的外伤史、临床表现，该患者考虑诊断为脾破裂，剖腹探查时应首先探查受伤的脏器，所以应先探查肝脾，再探查胃肠（B对），如果没有腹腔内大出血，则应对腹腔脏器进行系统、有序的探查，原则上应先探查肝、脾等实质性器官，然后是胃肠道及系膜，紧接着是盆腔脏器，再后是检查胃后壁和胰腺，最后是切开后腹膜探查十二指肠二、三、四段（ACD错）。","c223","N"],["2025-N103",57,"第六节 骨囊肿和其他良性疾病","骨囊肿诊断",2025,103,"A","","男童，11岁。左上臂近端隐痛2个月。骨科检查：左肩部无明显畸形，关节活动自如。X线片示左肱骨近端干骺端圆形透亮灶，界限清楚，骨皮质轻度变薄。目前应首先考虑的疾病是",[["A","骨囊肿"],["B","骨巨细胞瘤"],["C","骨肉瘤"],["D","骨软骨瘤"]],"A","11岁男性患儿（骨囊肿的多发人群）。左上臂近端（骨囊肿好发部位）隐痛2个月，骨科检查：左肩部无明显畸形，关节活动自如，X线显示：左肱骨近端干骺端一圆形透亮灶，界限清楚，骨皮质轻度变薄（骨囊肿典型X线改变）。综合患儿年龄、临床表现及辅助检查，首先应考虑的疾病是骨囊肿（A对）。骨巨细胞瘤（B错）好发于20～40岁人群，女性略多，股骨远端和胫骨近端多发，主要症状为疼痛和肿胀，局部包块压之有乒乓球样感觉和压痛，典型的X线特征为骨端偏心位、溶骨性、囊性破坏而无骨膜反应，病灶膨胀生长，骨皮质变薄，呈肥皂泡样改变。骨肉瘤（C错）好发于青少年，好发部位为股骨远端、胫骨近端和肱骨近端的干骺端，主要症状为局部疼痛，夜间尤重，局部表面皮温升高，静脉怒张，X线表现包括骨质破坏、明显的骨膜反应，可见Codman三角或“日光射线”形态。骨软骨瘤（D错）多发生于青少年，随机体发育而增大，以股骨远端、胫骨近端和肱骨近端多发，一般无明显症状，X线可见在干骺端从皮质突向软组织的骨性突起。","c224","N"],["2025-N104",57,"第六节 骨囊肿和其他良性疾病","骨囊肿治疗",2025,104,"A","","男童，11岁。左上臂近端隐痛2个月。骨科检查：左肩部无明显畸形，关节活动自如。X线片示左肱骨近端干骺端圆形透亮灶，界限清楚，骨皮质轻度变薄。最佳处理措施是",[["A","单纯放疗"],["B","病灶刮除植骨"],["C","单纯化疗"],["D","密切观察随诊"]],"D","11岁男性患儿（骨囊肿的多发人群）。左上臂近端（骨囊肿好发部位）隐痛2个月，骨科检查：左肩部无明显畸形，关节活动自如，X线显示：左肱骨近端干骺端一圆形透亮灶，界限清楚，骨皮质轻度变薄（骨囊肿典型X线改变）。综合患儿年龄、临床表现及辅助检查，首先应考虑的疾病是骨囊肿。虽然病灶清除刮骨（B错）是单纯性骨囊肿的标准治疗方式，但由于该患儿年龄较小（＜14岁），手术可能会损伤骨骺，且术后局部复发率较高，所以目前最合适的治疗措施是密切观察（D对）。单纯放疗（A错）通常用于骨恶性肿瘤的治疗，而骨囊肿是一种局限性瘤样病损，所以不适用。单纯化疗（C错）主要用于骨恶性肿瘤的治疗，该患儿不适用。","c224","N"],["2025-N105",57,"第六节 骨囊肿和其他良性疾病","动脉瘤性骨囊肿",2025,105,"A","","男童，11岁。左上臂近端隐痛2个月，骨科检查：左肩部无明显畸形，关节活动自如。X线片示左肱骨近端干骺端圆形透亮灶，界限清楚，骨皮质轻度变薄。两年后，患者左上臂近端疼痛加重，复查X线片示左肱骨上段气球样膨胀性囊状透亮灶，界限清楚，有骨性间隔，将囊腔分隔成泡沫状。目前考虑的诊断是",[["A","单纯性骨囊肿"],["B","骨巨细胞瘤"],["C","骨肉瘤"],["D","动脉瘤样骨囊肿"]],"D","11岁男性患儿（骨囊肿的多发人群）。左上臂近端（骨囊肿好发部位）隐痛2个月，骨科检查：左肩部无明显畸形，关节活动自如，X线显示：左肱骨近端干骺端一圆形透亮灶，界限清楚，骨皮质轻度变薄（骨囊肿典型X线改变）。2年后，该患儿左上臂疼痛加重，复查X线：肱骨上段近端气球样膨胀性囊性样变，界限清楚，有骨性间隔，将囊腔分隔为泡沫状（动脉瘤性骨囊肿典型X线改变），综合患儿年龄、临床表现及影像学检查，该患儿考虑的诊断是动脉瘤样骨囊肿（D对）。单纯性骨囊肿（A错）主要表现为肢体局部隐痛或肿胀，X线表现为干骺端的圆形或椭圆形溶骨性病灶，骨皮质轻度变薄。骨巨细胞瘤（B错）好发于20～40岁人群，女性略多，股骨远端和胫骨近端多发，主要症状为疼痛和肿胀，局部包块压之有乒乓球样感觉和压痛，典型的X线特征为骨端偏心位、溶骨性、囊性破坏而无骨膜反应，病灶膨胀生长，骨皮质变薄，呈肥皂泡样改变。骨肉瘤（C错）好发于青少年，好发部位为股骨远端、胫骨近端和肱骨近端的干骺端，主要症状为局部疼痛，夜间尤重，局部表面皮温升高，静脉怒张，X线表现包括骨质破坏、明显的骨膜反应，可见Codman三角或“日光射线”形态。","c224","N"],["2025-N106",51,"第五节 与慢性损伤相关的其他疾病","狭窄性腱鞘炎诊断",2025,106,"A","","女性，58岁。右拇指根部晨起僵硬伴疼痛半年，反复发作，未治疗。近1周出现右拇指疼痛加重，第一掌指关节轻度肿胀及活动受限，局部压痛明显，屈指可出现弹响。最可能的诊断是",[["A","类风湿关节炎"],["B","狭窄性腱鞘炎"],["C","风湿性关节炎"],["D","骨关节炎"]],"B","患者中老年女性（狭窄性腱鞘炎的的多发人群）。反复发作右拇指根部（狭窄性腱鞘炎的好发部位）晨起僵硬伴疼痛半年，近1周加重，第一掌指关节轻度肿胀伴活动受限，局部压痛明显，屈指可出现弹响（狭窄性腱鞘炎典型临床表现）。综合患者年龄、临床表现，该患者最可能的诊断是狭窄性腱鞘炎（B对）。类风湿性关节炎（A错）多发于35～50 岁女性，以对称性双手、腕、足等多关节肿痛为首发表现，伴晨僵，多超过1小时，晚期可出现“天鹅颈”样及“纽扣花”样关节畸形。风湿性关节炎（C错）是链球菌感染后所致风湿热在关节的表现，通常在链球菌感染后1个月内发作，典型表现是游走性多关节炎，常对称累及膝、踝、肩、腕、肘、髋等大关节，也可以呈现局部红、肿，热、痛等，症状2～6周内消失，关节功能完全恢，不遗留关节强直和畸形。骨关节炎（D错）好发于中老年人，好发部位为膝、髋、颈椎和腰椎等负重关节，以及远端指间关节、近端指间关节等，主要表现为活动后受累关节及其周围疼痛、压痛、僵硬、肿胀等，休息可缓解。","c225","N"],["2025-N107",51,"第五节 与慢性损伤相关的其他疾病","初始治疗中使用保守疗法",2025,107,"A","","女性，58岁。右拇指根部晨起僵硬伴疼痛半年，反复发作，未治疗。近1周出现右拇指疼痛加重，第一掌指关节轻度肿胀及活动受限，局部压痛明显，屈指可出现弹响。下列处理方法中，目前不考虑的是",[["A","局部制动"],["B","应用非甾体抗炎药"],["C","局部激素注射"],["D","腱鞘切开减压"]],"D","患者中老年女性（狭窄性腱鞘炎的的多发人群）。反复发作右拇指根部（狭窄性腱鞘炎的好发部位）晨起僵硬伴疼痛半年，近1周加重，第一掌指关节轻度肿胀伴活动受限，局部压痛明显，屈指可出现弹响（狭窄性腱鞘炎典型临床表现）。综合患者年龄、临床表现，该患者最可能的诊断是狭窄性腱鞘炎。狭窄性腱鞘炎的初始治疗多采用保守疗法，包括：调整手部活动、夹板固定等局部制动（A对）、短期使用非甾体抗炎药（B对），如果症状未能改善，可行局部糖皮质激素注射（C对）。腱鞘切开减压（D错，为本题正确答案）为手术治疗方法，适用于保守治疗无效或反复发作、腱鞘狭窄较重的患者，不作为首选治疗方法。","c225","N"],["2025-N132",32,"第五节 胆道感染","急性结石性胆囊炎临床表现",2025,132,"B","","急性胆囊炎的腹痛特点是",[["A","转移性腹痛、上腹痛减轻或消失"],["B","右下腹部疼痛、向会阴部放射"],["C","转移性腹痛、上腹痛持续"],["D","右上腹部疼痛、向右肩背部放射"]],"D","急性胆囊炎腹痛表现为右上腹绞痛或持续性疼痛，伴阵发加剧，疼痛向右肩放射（D对），伴畏寒发热。转移性腹痛、上腹痛减轻或持续（A错）是急性阑尾炎的典型表现，主要是因为持续而强烈的炎症刺激影响相应脊髓节段的躯体传入纤维，出现牵涉痛，使疼痛出现转移。右下腹部疼痛、向会阴部放射（B错）见于右侧输尿管结石，疼痛呈阵发性剧烈绞痛。转移性腹痛、上腹痛持续（C错）见于十二指肠溃疡穿孔，表现为突发上腹部刀割样疼痛，迅速蔓延至全腹部，上腹痛持续。","","N"],["2025-N133",26,"第三节 胃十二指肠溃疡的外科治疗","胃十二指肠溃疡穿孔临床表现",2025,133,"B","","十二指肠溃疡穿孔的腹痛特点是",[["A","转移性腹痛、上腹痛减轻或消失"],["B","右下腹部疼痛、向会阴部放射"],["C","转移性腹痛、上腹痛持续"],["D","右上腹部疼痛、向右肩背部放射"]],"C","十二指肠溃疡穿孔腹痛的特点为转移性腹痛、上腹痛持续（C对），表现为突发上腹部刀割样疼痛，迅速蔓延至全腹部，上腹痛持续。转移性腹痛、上腹痛减轻或持续（A错）是急性阑尾炎的典型表现，主要是因为持续而强烈的炎症刺激影响相应脊髓节段的躯体传入纤维，出现牵涉痛，使疼痛出现转移。右下腹部疼痛、向会阴部放射（B错）见于右侧输尿管结石，疼痛呈阵发性剧烈绞痛。右上腹部疼痛、向右肩放射（D错）见于急性胆囊炎，疼痛呈绞痛或持续性疼痛，阵发加剧，伴畏寒发热。","","N"],["2025-N134",31,"门静脉高压","分流术",2025,134,"B","","肝性脑病发生率较高的术式是",[["A","门静脉-下腔静脉分流术"],["B","远端脾-肾静脉分流术"],["C","贲门周围血管离断术"],["D","单纯脾切除术"]],"A","肝性脑病发生率最高的术式是门静脉-下腔静脉分流术（A对），这种术式直接将门静脉的血液分流至下腔静脉，导致肝脏的血液灌注减少，降低肝脏的解毒功能，从而显著增加肝性脑病的风险，可高达 20%～40%。远端脾-肾静脉分流术（B错）将脾静脉远端与左肾静脉进行端侧吻合，同时离断门-奇静脉侧支，包括胃冠状静脉和胃网膜静脉，该术式的优点是肝性脑病发生率低。贲门周围血管离断术（C错）操作时紧贴胃食管外壁，彻底离断所有进入的穿支血管，保留食管旁静脉丛，在一定程度上保留门-体间自发形成的分流，不直接改变门静脉的主要血流，肝性脑病的风险相对较低。单纯脾切除术（D错）主要是为了解决脾功能亢进，不改变门静脉的血流，能够降低门静脉压力，延缓肝病进展，但多联合断流术及分流术，较少进行单纯脾切除术。","","N"],["2025-N135",31,"门静脉高压","断流手术",2025,135,"B","","不降低入肝血流量的术式是",[["A","门静脉-下腔静脉分流术"],["B","远端脾-肾静脉分流术"],["C","贲门周围血管离断术"],["D","单纯脾切除术"]],"C","不减少入肝血流量的术式是贲门周围血管离断术（C对），该手术操作时紧贴胃食管外壁，彻底离断所有进入的穿支血管，保留食管旁静脉丛，在一定程度上保留门-体间自发形成的分流，不直接改变门静脉的主要血流，肝性脑病的风险相对较低。门静脉-下腔静脉分流术（A错）直接将门静脉的血液分流至下腔静脉，导致肝脏的血液灌注减少，降低肝脏的解毒功能，从而显著增加肝性脑病的风险，可高达 20%～40%。远端脾-肾静脉分流术（B错）将脾静脉远端与左肾静脉进行端侧吻合，同时离断门-奇静脉侧支，包括胃冠状静脉和胃网膜静脉，该术式的优点是肝性脑病发生率低。单纯脾切除术（D错）主要是为了解决脾功能亢进，不改变门静脉的血流，能够降低门静脉压力，延缓肝病进展，但多联合断流术及分流术，较少进行单纯脾切除术。","","N"],["2025-N160",33,"第二节 胰腺炎","手术适应证",2025,160,"X","","急性胰腺炎的手术适应证有",[["A","合并腹腔大出血"],["B","胰腺及胰周坏死组织继发感染"],["C","继发肠道穿孔"],["D","合并胆管结石"]],"ABCD","急性胰腺炎是一种常见的急腹症，其治疗方式包括非手术治疗和手术治疗，其中手术指征包括：合并腹腔大出血（A对）；胰腺及胰周坏死组织继发感染（B对），手术可以清除坏死组织和控制感染；继发肠道穿孔（C对）；胆总管下端梗阻或胆道感染，此时手术可能需要同时处理胰腺和胆道的问题；不能排除其他急腹症；胰腺假性囊肿。合并胆道结石是否需要手术，需要判断结石是否造成了胆总管下段的梗阻或胆道感染，D选项存在争议。","","N"],["2025-N161",32,"第四节 胆石症","肝切除术",2025,161,"X","","肝内胆管结石行病变肝切除术的适应证有",[["A","区域性肝内胆管结石伴肝脏萎缩"],["B","弥漫性肝内胆管结石"],["C","难以取净的肝段结石伴胆管扩张"],["D","局限性肝内胆管结石伴胆道出血"]],"ACD","肝内胆管结石又称肝胆管结石，是我国常见而难治的胆道疾病，手术是重要的治疗方式，其中行病变肝切除术的手术指征主要包括：区域性肝内胆管结石并发肝萎缩（A对）、纤维化、脓肿、胆瘘，切除病变肝脏可防止病情进一步恶化，并有助于恢复肝脏的整体功能；难以取净的胆管结石伴胆道扩张（C对），切除病变部分可有效解除梗阻，预防并发症；局限性肝内胆管结石伴胆道出血（D对），此时手术切除不仅能止血，还可去除结石，防止进一步的胆道损伤和相关并发症；不易手术的高位胆管狭窄伴有近端胆管结石；结石合并胆管癌变。弥漫性肝内胆管结石（B错）由于结石分布广泛，且常伴有复杂的胆道解剖变异和肝功能损害，通常不适合直接行病变肝切除术。","","N"],["2025-N162",19,"第三节 气胸","张力性气胸",2025,162,"X","","下列关于张力性气胸的叙述，正确的有",[["A","肺损伤处形成活瓣"],["B","纵隔左右摆动"],["C","呼吸循环障碍"],["D","可出现皮下气肿"]],"ACD","张力性气胸又称为高压性气胸，是气管、支气管或肺损伤处形成活瓣（A对），气体随每次吸气进入胸膜腔并积累增多，导致胸膜腔压力高于大气压，伤侧肺严重萎陷，纵隔显著向健侧移位，健侧肺受压，腔静脉回流障碍，引发严重的呼吸循环障碍（C对），此外，高于大气压的胸内压驱使气体进入纵隔或胸壁软组织，形成纵隔气肿或面、颈、胸部的皮下气肿（D对）。纵隔左右摆动（B错）是由于两侧胸膜腔压力不均衡，使纵隔在吸气时移向健侧，呼气时移向伤侧，是开放性气胸的特点。","","N"],["2025-N163",13,"第三节 术后并发症的防治","预防和治疗",2025,163,"X","","预防腹部切口裂开的方法有",[["A","腹部加压包扎"],["B","延迟拆线"],["C","加用减张缝合"],["D","及时处理腹胀"]],"ACD","腹部切口裂开指腹部手术切口的任何一层或全层裂开，主要原因有营养不良、切口缝合技术有缺陷、腹腔内压力突然增高，预防腹部切口裂开的方法包括：腹部加压包扎（A对）可以有效减少切口部位的张力，进而降低裂开风险；加用减张缝合（C对）是在手术缝合时采用特殊技术，同样有助于预防切口裂开；腹胀作为腹部手术后的常见并发症，及时处理腹胀（D对）能减少腹腔内压力，降低对切口的张力；应在良好麻醉、腹壁松弛条件下缝合切口，避免强行缝合造成腹膜等组织撕裂；病人咳嗽时，最好平卧，以减轻咳嗽时膈肌突然大幅度下降和腹内压力骤然增加。缝线的拆除时间应根据切口部位、局部血液供应情况、病人年龄、营养状况等来决定，延迟拆线（B错）虽能减少愈合初期因拆线导致的裂开风险，但可增加感染风险。","","N"],["2025-N164",51,"第五节 与慢性损伤相关的其他疾病","粘连性肩关节囊炎临床特点",2025,164,"X","","神经根型颈椎病和肩周炎可能的相同临床表现有",[["A","肩痛"],["B","肩关节活动受限"],["C","手痛"],["D","上臂痛"]],"ABD","神经根型颈椎病是发病率最高的一种颈椎病类型，由于突出的椎间盘、增生的钩椎关节压迫相应的神经根，引起神经根性刺激症状。肩周炎又称为粘连性肩关节囊炎，目前病因不明。神经根型颈椎病与肩周炎可能的相同临床表现有：肩痛（A对），神经根型颈椎病早期即可表现为肩颈痛，短期内加重，并向上肢放射，肩周炎的肩痛表现为肩部某一处局限性疼痛，与动作、姿势有明显关系；肩关节活动受限（B对），神经根型颈椎病主要是因为C₅神经根受压导致肌力减弱，三角肌无力和萎缩引起活动受限，肩周炎表现为肩各方向主动、被动活动均不同程度受限，以外旋外展和内旋后伸最重；上臂痛（D对），神经根型颈椎病主要是因为C₆和C₇神经根受压所致，疼痛沿上臂和前臂向远端放射，肩周炎的上臂痛一般发生在病程后期，由肩部疼痛放射至上臂所致。当C₆和C₇神经根受压时，神经根型颈椎病的疼痛可沿上臂和前臂向远端放射至手指，而肩周炎的疼痛在严重病例中一般仅放射至上臂，所以手痛（C错）主要是神经根型颈椎病的典型表现，不是两者共有的症状。","","N"],["2025-N165",55,"第一节 骨与关节结核概论","骨与关节结核发病特点",2025,165,"X","","骨与关节结核常见的发生部位有",[["A","腕关节"],["B","膝关节"],["C","髋关节"],["D","脊柱"]],"BCD","骨与关节结核是由结核分枝杆菌侵入骨或关节而引起的一种继发性感染性疾病，是最常见的肺外继发性结核，多继发于肺结核，好发于负重大、活动多、易于发生损伤的部位，常见的发生部位包括膝关节（B对）、髋关节（C对）和脊柱（D对），其中脊柱结核最多见，约占 50%以上，髋、膝关节结核各占约 15%。而腕关节（A错）结核相对较少见，因其活动范围较小且非承重关节，不易受结核杆菌侵犯。","","N"],["2026-N57",12,"第二节 心肺脑复苏","胸外按压",2026,57,"A","","单人进行成人体外心肺复苏时的按压-通气比例是",[["A","15：2"],["B","20：1"],["C","20：2"],["D","30：2"]],"D","心脏按压是间接或直接施压于心脏，使心脏维持充盈和搏出功能，并能诱导心脏恢复自主心律的措施。成人体外心肺复苏时的按压-通气比例是30：2（D对ABC错），即胸外按压30次后即进行2次通气。","","N"],["2026-N58",3,"第一节 外科休克概述","休克代偿期",2026,58,"A","","下列不属于休克代偿期的表现的是",[["A","心率加快"],["B","血压下降"],["C","呼吸加快"],["D","脉压减小"]],"B","休克代偿期属于休克早期阶段，其临床表现为神志清楚、精神紧张、皮肤开始变苍白、发凉、心率加快（A对）、脉压减小（D对）、呼吸加快（C对）、尿量正常或减少等，休克早期收缩压正常或稍升高，舒张压增高（B错，为本题正确答案）。","","N"],["2026-N59",13,"第三节 术后并发症的防治","术后肺部感染",2026,59,"A","","女性，68岁。胃癌根治术后6天，出现发热、咳嗽、呼吸急促，无明显腹痛，查体：T：39.8℃，P：120次/分，R：30次/分，BP：140/80mmHg，WBC：18×10⁹/L。该患者最有可能并发的感染是",[["A","切口感染"],["B","泌尿系感染"],["C","肺部感染"],["D","腹腔感染"]],"C","老年女性患者，胃癌根治术后6天，出现发热、咳嗽、呼吸急促（肺部感染表现），无明显腹痛，查体：T：39.8℃（正常范围为36～37℃，提示高热），P：120次/分（正常范围为60～100次/分，提示心率加快），R：30次/分（正常范围为12～20次/分，提示呼吸过快），BP：140/80mmHg（正常范围为90～139/60～89mmHg），WBC：18×10⁹/L（正常范围为3.5～9.5×10⁹/L，提示感染）。该患者最有可能并发的感染是肺部感染（C对）。切口感染（A错）临床表现为伤口局部红、肿、热、疼痛和触痛，有分泌物（浅表伤口感染），伴有或不伴有发热和白细胞增多。泌尿系感染（B错）中，急性膀胱炎表现为尿频、尿急、尿痛和排尿困难，可有轻度发热；急性肾盂肾炎则有高热、腰部疼痛与触痛。腹腔感染（D错）多为腹腔脓肿和腹膜炎，表现为发热、腹痛、腹部触痛及白细胞增多。","","N"],["2026-N60",42,"","",2026,60,"A","","下列选项中，应进行根治性肾切除术的是",[["A","解剖性或功能性孤立肾的肾癌"],["B","单侧肾癌伴肾静脉内癌栓"],["C","单侧肾血管平滑肌脂肪瘤"],["D","单侧肾癌伴肾功能不全"]],"B","根治性肾切除术主要应用于无法行肾部分切除术的T1期肾癌，以及T2～T4期肾癌，肾静脉内癌栓（B对）肿瘤侵及肾段静脉或肾静脉或下腔静脉，或侵及肾周围组织，但未侵犯同侧肾上腺，未超过肾周筋膜，属于T3期，因此应进行根治性肾切除术。部分T2期肾癌、发生于解剖性或功能性孤立肾的肾癌（A错），合并慢性肾脏病的肾癌、家族性肾癌、双侧肾癌等，在保证肿瘤控制的情况下可选择肾部分切除术。单侧肾血管平滑肌脂肪瘤（C错）是最常见的肾脏良性肿瘤，治疗手段为观察或肾部分切除术。单侧肾癌伴肾功能不全（D错）需优先评估对侧肾功能，若对侧肾功能正常，可考虑根治性切除；若对侧肾功能也受损，则优先选择保留肾单位手术。","","N"],["2026-N61",19,"第三节 气胸","胸腔闭式引流术",2026,61,"A","","无胸腔积液的创伤性气胸，放置胸腔闭式引流管的正确位置是",[["A","腋前线第2肋间"],["B","锁骨中线第2肋间"],["C","腋后线第6肋间"],["D","腋前线第6肋间"]],"B","无胸腔积液的创伤性气胸，放置胸腔闭式引流管的正确位置是前胸壁锁骨中线第2肋间（B对AD错），此处为胸腔顶部，空气会积聚于此。血胸引流则在腋中线与腋后线间第6或第7肋间隙（C错）。","","N"],["2026-N62",28,"第二节 急性阑尾炎","切口感染",2026,62,"A","","男，21岁，急性化脓性阑尾炎切除术后5天，切口疼痛伴发热。T38.5℃，血WBC15×10⁹/L，切口穿刺可见脓液，最重要的处理是",[["A","局部理疗"],["B","穿刺抽脓，局部注入抗生素"],["C","拆除缝线，通畅引流"],["D","加大抗生素用量"]],"C","年轻男性患者，急性化脓性阑尾炎切除术后5天，切口疼痛伴发热。T38.5℃（正常范围为36～37℃，提示发热），血WBC15×10⁹/L（正常范围为3.5～9.5×10⁹/L，提示感染），切口穿刺可见脓液（提示切口感染）。该患者可初步诊断为阑尾切除术后并发切口感染，最重要的处理是拆除缝线，通畅引流（C对），定期换药。局部理疗（A错）仅能促进局部血液循环，不适用于形成脓肿的阶段。穿刺抽脓、局部注入抗生素（B错）疗效有限，且无法充分引流。加大抗生素用量（D错）无法替代引流作用，且可能增加耐药风险。","","N"],["2026-N63",29,"第十一节 肛瘘","肛瘘切除术",2026,63,"A","","下列哪种肛瘘适合一期手术切除",[["A","低位复杂性肛瘘"],["B","低位单纯性肛瘘"],["C","低位复杂性肛瘘合并肛周脓肿"],["D","高位复杂性肛瘘"]],"B","一期手术切除肛瘘适用于瘘管位置低、结构简单的类型，以避免损伤肛门括约肌导致失禁。低位单纯性肛瘘（B对）因其瘘管位于浅表、路径单一，手术风险低，可一次性完整切除。低位复杂性肛瘘（A错）有多个瘘口和瘘管，一期手术易损伤括约肌，通常需分期处理。低位复杂性肛瘘合并肛周脓肿（C错）涉及急性脓肿形成，需优先引流处理感染，而非一期瘘管切除。高位复杂性肛瘘（D错）位于外括约肌深部以上，一期切除风险过高，常采取挂线术等分期方法。","","N"],["2026-N64",23,"第四节 其他腹外疝","其他腹外疝切口疝",2026,64,"A","","关于切口疝，下列说法正确的是",[["A","最常发生于旁正中切口"],["B","疝囊多数较完整"],["C","发生嵌顿的机会较小"],["D","多为易复性疝"]],"C","切口疝是发生于腹壁手术切口处的疝，疝环一般比较宽大，很少发生嵌顿（C对），最常发生切口疝的是经腹直肌切口，其次为正中切口和旁正中切口（A错），多数切口疝无完整疝囊（B错），疝内容物常可与腹膜外腹壁组织粘连而成为难复性疝（D错）。","","N"],["2026-N65",47,"第一节 髋关节脱位","固定、功能锻炼",2026,65,"A","","髋关节脱位复位后，需要牵拉或钉子鞋固定至少多久时间",[["A","2周"],["B","4周"],["C","6周"],["D","8周"]],"A","髋关节脱位复位后，需要牵拉或钉子鞋固定至少2～3周（A对BCD错），2～3周后开始活动关节，4周后扶双拐下地活动，3个月后可完全承重。","","N"],["2026-N66",55,"第一节 骨与关节结核概论","脓肿切开引流术",2026,66,"A","","骨关节结核患者，高热3天，体质虚弱，寒性脓肿混合感染，脓液粘稠，未经过规范的抗结核药物治疗，目前最适宜的治疗方式是",[["A","单纯规范的抗结核药物治疗"],["B","穿刺抽脓，注入抗结核药物"],["C","脓肿切开引流"],["D","病灶清除术"]],"C","骨关节结核患者，高热3天，体质虚弱，寒性脓肿混合感染，脓液粘稠，未经过规范的抗结核药物治疗，目前最适宜的治疗方式是脓肿切开引流（C对），寒性脓肿有混合性感染，体温高，中毒症状明显者，因全身状况不好，不能耐受病灶清除术，可以作寒性脓肿切开引流。待全身情况改善后再行病灶清除术（D错）。单纯规范的抗结核药物治疗（A错）可用于结核控制，但无法有效引流脓肿和处理混合感染。穿刺抽脓，注入抗结核药物（B错）适用于早期单纯性滑膜结核病例，且不主张对寒性脓肿进行反复抽脓与注入抗结核药物，多次操作会导致混合性感染和形成窦道。","","N"],["2026-N67",51,"第五节 与慢性损伤相关的其他疾病","肱骨外上髁炎",2026,67,"A","","女性，52岁，3个月来左肘部疼痛，向前臂外侧放射，肘关节活动正常，肱骨外上髁局限性压痛，外用药物无明显改善，目前最佳的治疗方法是",[["A","关节镜手术"],["B","压痛点封闭"],["C","按摩"],["D","加强腕部活动"]],"B","患者中年女性，3个月来左肘部疼痛，向前臂外侧放射，肘关节活动正常，肱骨外上髁局限性压痛（肱骨外上髁炎的特征性体征），外用药物无明显改善，根据患者的症状，考虑可能诊断为肱骨外上髁炎，目前最佳的治疗方法是压痛点封闭（B对），即在压痛点注射醋酸泼尼松龙等，一般可取得良好的近期效果。关节镜手术（A错）通常用于对有非手术治疗效果不佳的顽固疼痛者，非首选且创伤性大。按摩（C错）虽可能辅助缓解不适，但效果较慢且不针对炎症核心。加强腕部活动（D错）会增加肌腱负荷，可能加重疼痛，不利于恢复。","","N"],["2026-N93",23,"第三节 股疝","股疝诊断",2026,93,"A","","女性，70岁。10小时前提重物后感右侧大腿根部疼痛，并发现右侧腹股沟区肿物。2年前曾行开腹阑尾切除术。查体：腹软，无明显压痛，右侧腹股沟韧带下方可及肿物，直径3cm，触痛明显，平卧不消失。该患者最可能诊断为",[["A","腹股沟直疝"],["B","腹股沟斜疝"],["C","股疝"],["D","切口疝"]],"C","老年女性患者（股疝好发人群），10小时前提重物后感右侧大腿根部疼痛（腹内压增高，股疝常见诱因），并发现右侧腹股沟区肿物（提示股疝形成）。2年前曾行开腹阑尾切除术。查体：腹软，无明显压痛，右侧腹股沟韧带下方可及肿物，直径3cm，触痛明显，平卧不消失（提示嵌顿），考虑患者诊断为股疝（C对）。腹股沟直疝（A错）常见于年老体弱者，当病人直立时，在腹股沟内侧端、耻骨结节上外方出现一半球形肿块，平卧后疝块多能自行消失。腹股沟斜疝（B错）多见于儿童及青壮年，表现为腹股沟区突出的肿块。切口疝（D错）是发生于腹壁手术切口处的疝，主要症状是腹壁切口处逐渐膨隆，有肿块出现。","c235","N"],["2026-N94",23,"第三节 股疝","股疝临床表现",2026,94,"A","","女性，70岁。10小时前提重物后感右侧大腿根部疼痛，并发现右侧腹股沟区肿物。2年前曾行开腹阑尾切除术。查体：腹软，无明显压痛，右侧腹股沟韧带下方可及肿物，直径3cm，触痛明显，平卧不消失。术中证实为嵌顿疝，疝内容物为小肠。下列叙述错误的是",[["A","肠管呈紫黑色，无光泽及弹性，应考虑肠坏死"],["B","刺激肠管无蠕动，相应肠系膜动脉无搏动，应考虑肠坏死"],["C","逆行性嵌顿疝，术中应同时探查腹腔内肠管活性"],["D","无法确定肠管是否坏死时，可还纳入腹腔并结束手术"]],"D","老年女性患者（股疝好发人群），10小时前提重物后感右侧大腿根部疼痛（腹内压增高，股疝常见诱因），并发现右侧腹股沟区肿物（提示股疝形成）。2年前曾行开腹阑尾切除术。查体：腹软，无明显压痛，右侧腹股沟韧带下方可及肿物，直径3cm，触痛明显，平卧不消失（提示嵌顿），考虑患者诊断为股疝。术中证实为嵌顿疝，疝内容物为小肠，此时应正确判断疝内容物的活力，然后根据病情确定处理方法。在解除疝环压迫后，凡肠管呈紫黑色，失去光泽和弹性，刺激后无蠕动和相应肠系膜内无动脉搏动者，即可判定为肠坏死（AB对）。如肠管尚未坏死，则可将其送回腹腔，按易复性疝处理。不能肯定是否坏死时，可在其系膜根部注射0.25%～0.5%普鲁卡因60～80ml，再用温热等渗盐水纱布覆盖该段肠管或将其暂时送回腹腔，10～20分钟后再观察，切勿把活力可疑的肠管送回腹腔（D错，为本题正确答案）。如嵌顿的肠袢较多，应特别警惕逆行性嵌顿的可能，不仅要检查疝囊内肠袢的活力，还应检查位于腹腔内的中间肠袢的活力（C对）。","c235","N"],["2026-N95",23,"第三节 股疝","股疝治疗",2026,95,"A","","女性，70岁。10小时前提重物后感右侧大腿根部疼痛，并发现右侧腹股沟区肿物。2年前曾行开腹阑尾切除术。查体：腹软，无明显压痛，右侧腹股沟韧带下方可及肿物，直径3cm，触痛明显，平卧不消失。如发现肠管绞窄坏死，正确的手术方法是",[["A","坏死肠段切除术+疝囊高位结扎术"],["B","坏死肠段切除+疝修补术"],["C","坏死肠段切除+无张力疝修补"],["D","坏死肠段切除+填充式疝成形术"]],"A","老年女性患者（股疝好发人群），10小时前提重物后感右侧大腿根部疼痛（腹内压增高，股疝常见诱因），并发现右侧腹股沟区肿物（提示股疝形成）。2年前曾行开腹阑尾切除术。查体：腹软，无明显压痛，右侧腹股沟韧带下方可及肿物，直径3cm，触痛明显，平卧不消失（提示嵌顿），考虑患者诊断为股疝。如发现肠管绞窄坏死，应切除该段肠管并进行一期吻合，且因肠坏死伴有局部严重感染，通常只实施单纯疝囊高位结扎，腹壁的缺损应择期行手术加强，目前正确的手术方法是坏死肠段切除术+疝囊高位结扎术（A对）。手术区域因肠切除已污染，在高位结扎疝囊后，不宜行疝修补术（BCD错），因为感染风险极高，易导致修补失败。","c235","N"],["2026-N96",27,"第五节 肠系膜血管缺血性疾病","肠系膜上动脉栓塞",2026,96,"A","","男性，56岁。半小时前进食后突发剧烈腹痛，呕吐少量胃内容物，有心房颤动5年。查体：T 36℃，P 96次/分，R 24次/分，BP 130/95mmHg，心率115次/分。全腹软，散在轻压痛，肠鸣音活跃。血WBC 8.0×10⁹/L，ALT 35U/L，血清淀粉酶 110U/L。该患者最可能的诊断是",[["A","急性胰腺炎"],["B","胃十二指肠溃疡穿孔"],["C","肠系膜上动脉栓塞"],["D","急性胆管炎"]],"C","中年男性患者，半小时前进食后突发剧烈腹痛，呕吐少量胃内容物，有心房颤动5年。查体：T36℃（正常值范围36～37℃），P96次/分（正常值范围60～100次/分），R24次/分（正常值范围12～20次/分，提示呼吸加快），BP130/95mmHg（正常血压90～139/60～89mmHg），心率115次/分（脉搏短绌，提示房颤，并发血栓栓塞危险性大）。全腹软，散在轻压痛（肠系膜上动脉栓塞典型主诉与查体不相符），肠鸣音活跃。血WBC8.0×10⁹/L（正常值范围3.5～9.5×10⁹/L），ALT35U/L（正常值范围9～50U/L），血清淀粉酶110U/L（正常值范围35～135U/L）。最可能的诊断是肠系膜上动脉栓塞（C对），早期表现为突发剧烈腹部绞痛，但与轻微腹部体征不符的矛盾现象。急性胰腺炎（A错）常于饱餐和饮酒后突然发作剧烈腹痛，腹部压痛明显，坏死性胰腺炎可伴有腹膜刺激征，血清淀粉酶升高。胃十二指肠溃疡穿孔（B错）病人多有溃疡病史，表现为突发上腹部刀割样剧烈腹痛，迅速波及全腹，全腹压痛和反跳痛明显，腹肌紧张，呈“板状腹”。急性胆管炎（D错）是由细菌感染引起的胆道系统急性炎症，可出现典型的Charcot三联征：腹痛、寒战高热和黄疸。","c236","N"],["2026-N97",27,"第五节 肠系膜血管缺血性疾病","肠系膜血管缺血性疾病治疗",2026,97,"A","","男性，56岁。半小时前进食后突发剧烈腹痛，呕吐少量胃内容物，有心房颤动5年。查体：T 36℃，P 96次/分，R 24次/分，BP 130/95mmHg，心率115次/分。全腹软，散在轻压痛，肠鸣音活跃。血WBC 8.0×10⁹/L，ALT 35U/L，血清淀粉酶 110U/L。最恰当的处理是",[["A","观察病情，保守治疗"],["B","急诊穿孔修补术"],["C","急诊内镜下胆管引流"],["D","肠系膜上动脉切开取栓"]],"D","中年男性患者，半小时前进食后突发剧烈腹痛，呕吐少量胃内容物，有心房颤动5年。查体：T36℃（正常值范围36～37℃），P96次/分（正常值范围60～100次/分），R24次/分（正常值范围12～20次/分，提示呼吸加快），BP130/95mmHg（正常血压90～139/60～89mmHg），心率115次/分（脉搏短绌，提示房颤，并发血栓栓塞危险性大）。全腹软，散在轻压痛（肠系膜上动脉栓塞典型主诉与查体不相符），肠鸣音活跃。血WBC8.0×10⁹/L（正常值范围3.5～9.5×10⁹/L），ALT35U/L（正常值范围9～50U/L），血清淀粉酶110U/L（正常值范围35～135U/L）。最可能的诊断是肠系膜上动脉栓塞，最恰当的处理是肠系膜上动脉切开取栓（D对），患者出现腹部散在轻压痛，应尽早行剖腹探查，切除坏死肠管，行切开取栓术重建血供，保留有功能的肠管，根据肠管切除范围及切缘的血运情况行一期肠吻合或肠断端外置造口术。观察病情，保守治疗（A错）不适用于肠系膜上动脉栓塞患者，长期拖延可能导致肠坏死。急诊穿孔修补术（B错）适用于胃十二指肠溃疡急性穿孔。急诊内镜下胆管引流（C错）主要用于缓解阻塞性黄疸。","c236","N"],["2026-N98",18,"第四节 乳腺癌","乳腺癌根治术",2026,98,"A","","女性，45岁。发现右侧乳腺肿物1周来诊，既往体健。查体：右侧乳腺内上象限可及直径2cm质硬肿物。腋窝未触及明显肿大淋巴结。肿物穿刺病理示浸润性乳腺癌。该患者最合适的治疗是",[["A","乳腺癌改良根治术"],["B","全乳房切除术"],["C","乳腺癌扩大根治术"],["D","乳腺癌根治术"]],"A","患者中年女性，发现右侧乳腺肿物1周来诊，既往体健。查体：右侧乳腺内上象限可及直径2cm质硬肿物。腋窝未触及明显肿大淋巴结。肿物穿刺病理示浸润性乳腺癌。该患者乳腺癌分期为T₁N₀M₀，属于Ⅰ期，针对早期乳腺癌，乳腺癌改良根治术（A对）是最合适的手术方式，可保留了胸肌，术后外观效果较好，是目前常用的手术方式。全乳房切除术（B错）切除范围过于广泛，目前临床少用。乳腺癌根治术（D错）切除范围包括整个乳房、胸大肌、胸小肌及腋窝Ⅰ、Ⅱ、Ⅲ组淋巴结，在肿瘤侵犯胸大、小肌时可采用此术式。乳腺癌扩大根治术（C错）在乳腺癌根治术的基础上还需同时切除胸廓内动、静脉及其周围的淋巴结，目前临床少用。","c237","N"],["2026-N99",18,"第四节 乳腺癌","乳腺癌内分泌治疗",2026,99,"A","","女性，45岁。发现右侧乳腺肿物1周来诊，既往体健。查体：右侧乳腺内上象限可及直径2cm质硬肿物。腋窝未触及明显肿大淋巴结。肿物穿刺病理示浸润性乳腺癌。术后病理提示ER（-），HER2（+++），下列治疗药物中不恰当的是",[["A","环磷酰胺"],["B","他莫昔芬"],["C","曲妥珠单抗"],["D","多西他赛"]],"B","患者中年女性，发现右侧乳腺肿物1周来诊，既往体健。查体：右侧乳腺内上象限可及直径2cm质硬肿物。腋窝未触及明显肿大淋巴结。肿物穿刺病理示浸润性乳腺癌。术后病理提示ER（-），HER2（+++），癌基因HER2有过度表达者，适宜应用术后辅助化疗，如EC（表柔比星、环磷酰胺）序贯T（多西他赛或紫杉醇）、CT（多西他赛+环磷酰胺）的方案等（AD对）。曲妥珠单抗（C对）是抗HER2的靶向药物，可特异性结合HER2受体，抑制癌细胞增殖与转移。而他莫昔芬（B错，为本题正确答案）是选择性雌激素受体调节剂（SERM），仅对ER阳性乳腺癌治疗反应好。","c237","N"],["2026-N100",33,"第四节 胰腺癌和壶腹周围癌","胰腺癌诊断",2026,100,"A","","男性，68岁，右上腹不适伴进行性黄疸两周。查体：巩膜及全身皮肤黄染，腹部无明显压痛，右上腹触及球状光滑肿物。该患者首先考虑的诊断是",[["A","胰头癌"],["B","胆囊癌"],["C","肝门部胆管癌"],["D","肝内胆管癌"]],"A","老年男性患者，右上腹不适伴进行性黄疸两周（胰头癌典型表现）。查体：巩膜及全身皮肤黄染，腹部无明显压痛，右上腹触及球状光滑肿物（Courvoisier征，提示胰头癌）。该患者首先考虑的诊断是胰头癌（A对），典型进行性加重黄疸，胆囊显著肿大，但无压痛。胆囊癌（B错）出现腹部包块和进行性黄疸提示已进入晚期，常伴有其他症状，胆囊区可触及质硬、表面不光滑的肿物。肝门部胆管癌（C错）即上段胆管癌，主要表现为无痛性黄疸，因位于胆囊管开口以上，胆囊通常不肿大，甚至缩小。肝内胆管癌（D错）早期常无特殊临床症状，随着病情的进展，可出现腹部不适、体重下降、肝脏肿大或可触及腹部包块，胆道梗阻相对少见。","c238","N"],["2026-N101",33,"第四节 胰腺癌和壶腹周围癌","胰腺癌影像学检查",2026,101,"A","","男性，68岁，右上腹不适伴进行性黄疸两周。查体：巩膜及全身皮肤黄染，腹部无明显压痛，右上腹触及球状光滑肿物。为明确诊断，首选的检查是",[["A","PTC"],["B","ERCP"],["C","腹部CT"],["D","超声造影"]],"C","老年男性患者，右上腹不适伴进行性黄疸两周（胰头癌典型表现）。查体：巩膜及全身皮肤黄染，腹部无明显压痛，右上腹触及球状光滑肿物（Courvoisier征，提示胰头癌）。该患者首先考虑的诊断是胰头癌，为明确诊断，首选的检查是腹部CT（C对），胰腺薄层扫描增强CT及三维重建是首选影像学检查，能清晰显示肿瘤大小、位置、密度及血供情况，并判断肿瘤与血管、邻近器官的关系，评估肿瘤可切除性。PTC（经皮肝穿刺胆管造影）（A错）可用于诊断胆道病变。MRCP（B错）能够显示胰管、胆管梗阻部位及扩张程度，但不作为首选。超声造影（D错）可作为辅助检查，清晰度和准确性远低于CT。","c238","N"],["2026-N102",33,"第四节 胰腺癌和壶腹周围癌","根治性手术",2026,102,"A","","男性，68岁，右上腹不适伴进行性黄疸两周。查体：巩膜及全身皮肤黄染，腹部无明显压痛，右上腹触及球状光滑肿物。进一步检查发现肝内多发结节，转移性肿瘤可能性大，合适的治疗方法是",[["A","胰十二指肠切除术"],["B","胆囊切除术"],["C","胆肠吻合术"],["D","肝叶切除术"]],"C","老年男性患者，右上腹不适伴进行性黄疸两周（胰头癌典型表现）。查体：巩膜及全身皮肤黄染，腹部无明显压痛，右上腹触及球状光滑肿物（Courvoisier征，提示胰头癌）。该患者首先考虑的诊断是胰头癌，进一步检查发现肝内多发结节，转移性肿瘤可能性大，合适的治疗方法是胆肠吻合术（C对），该患者已发生肝转移，进展至晚期，无法进行根治性手术，胆肠吻合术能够解除胆道梗阻、缓解黄疸、改善肝功能及生活质量。胰十二指肠切除术（A错）的前提是肿瘤局限、无远处转移，该患者已有肝内多发转移，属于晚期，失去根治手术机会。胆囊切除术（B错）适用于胆囊癌患者。肝叶切除术（D错）适用于治疗肝内局限性肿瘤。","c238","N"],["2026-N103",57,"第四节 原发性恶性骨肿瘤","骨肉瘤诊断",2026,103,"A","","男童，12岁，一个月前无明显诱因出现右胫骨近端肿痛，皮温增高。X线显示胫骨近端溶骨性破坏，伴有骨膜反应及日光射线样改变。最可能的诊断是",[["A","骨结核"],["B","骨髓炎"],["C","骨肉瘤"],["D","骨巨细胞瘤"]],"C","患者为12岁男童（骨肉瘤好发年龄），无明显诱因出现右胫骨近端肿痛（骨肉瘤好发部位），皮温增高（骨肉瘤常见表现），X线显示胫骨近端溶骨性破坏，伴有骨膜反应及日光射线样改变（骨肉瘤典型影像学表现）。该患者最可能的诊断为骨肉瘤（C对）。骨肉瘤好发于青少年的股骨远端、胫骨近端和肱骨近端的干骺端，主要症状多为持续性局部疼痛，局部静脉怒张、皮温升高，X线表现为溶骨性破坏，可见Codman三角或呈“日光射线”形态。骨结核（A错）常有低热盗汗等全身结核症状，X线可见区域性骨质疏松和周围少量钙化的骨质破坏病灶。骨髓炎（B错）多为急性感染，有局部红肿热痛和全身感染症状，X线可见虫蚀样骨质破坏和骨膜反应，但无日光射线样改变。骨巨细胞瘤（D错）多见于20～40岁成人，X线表现为骨端破坏而无骨膜反应，病灶可见肥皂泡样改变。","c239","N"],["2026-N104",57,"第四节 原发性恶性骨肿瘤","骨肉瘤影像学表现",2026,104,"A","","男童，12岁，一个月前无明显诱因出现右胫骨近端肿痛，皮温增高。X线显示胫骨近端溶骨性破坏，伴有骨膜反应及日光射线样改变。为了明确诊断，还需要做的检查是",[["A","核素骨显像"],["B","组织活检"],["C","MRI"],["D","CT"]],"B","患者为12岁男童（骨肉瘤好发年龄），无明显诱因出现右胫骨近端肿痛（骨肉瘤好发部位），皮温增高（骨肉瘤常见表现），X线显示胫骨近端溶骨性破坏，伴有骨膜反应及日光射线样改变（骨肉瘤典型影像学表现）。该患者最可能的诊断为骨肉瘤，为了明确诊断，还需要做的检查是组织活检（B对），病理组织学检查是骨肿瘤最后确诊的唯一可靠检查。核素骨显像（A错）可以确定肿瘤的大小并发现转移病灶。MRI（C错）可用于明确肿瘤的边界和侵袭范围。CT（D错）可以提供高分辨率骨结构细节，但无法替代活检确诊。","c239","N"],["2026-N105",57,"第四节 原发性恶性骨肿瘤","骨肉瘤治疗",2026,105,"A","","男童，12岁，一个月前无明显诱因出现右胫骨近端肿痛，皮温增高。X线显示胫骨近端溶骨性破坏，伴有骨膜反应及日光射线样改变。最佳的治疗方式是",[["A","单纯截肢术"],["B","刮除植骨"],["C","化疗+保肢治疗"],["D","放疗"]],"C","患者为12岁男童（骨肉瘤好发年龄），无明显诱因出现右胫骨近端肿痛（骨肉瘤好发部位），皮温增高（骨肉瘤常见表现），X线显示胫骨近端溶骨性破坏，伴有骨膜反应及日光射线样改变（骨肉瘤典型影像学表现）。该患者最可能的诊断为骨肉瘤，最佳的治疗方式是化疗+保肢治疗（C对），即术前化疗缩小肿瘤后手术切除，保留肢体，以提高生存率并维持功能，术后继续化疗。单纯截肢术（A错）对于就诊较晚、破坏广泛和对其他辅助治疗无效的恶性骨肿瘤仍可考虑。刮除植骨（B错）仅适用于良性骨肿瘤及瘤样病变。骨肉瘤对放疗（D错）不敏感，效果有限。","c239","N"],["2026-N106",55,"第二节 脊柱结核","脊柱结核诊断",2026,106,"A","","女性，18岁。体瘦弱，脊柱后凸畸形，弯腰动作受限，腹股沟区有肿物，穿刺见灰白色脓液。该患者最可能的诊断是",[["A","腹股沟疝"],["B","脊柱结核"],["C","化脓性脊柱炎"],["D","化脓性骨髓炎"]],"B","患者青少年女性，体瘦弱（结核病常见体征），查体见脊柱后凸畸形（脊柱结核典型表现）、弯腰动作受限（关节活动障碍），腹股沟区触及肿物，穿刺抽出灰白色脓液（结核性脓肿特征，提示冷脓肿）。该患者考虑诊断为脊柱结核（B对）。脊柱结核可导致脊柱畸形和椎旁脓肿，椎旁脓肿积聚至一定程度，会穿破骨膜向下方流动，在远离病灶的部位出现脓肿。腹股沟疝（A错）通常表现为可复性包块，无全身表现。化脓性脊柱炎（C错）发病急、进展快，有高热及明显疼痛。化脓性骨髓炎（D错）多为急性感染，常累及四肢长骨，患处表现为局部红、肿、热、痛。","","N"],["2026-N107",55,"第二节 脊柱结核","MRI",2026,107,"A","","女性，18岁。体瘦弱，脊柱后凸畸形，弯腰动作受限，腹股沟区有肿物，穿刺见灰白色脓液。早期最具有诊断价值的检查是",[["A","MRI"],["B","X线"],["C","CT"],["D","结核菌素试验"]],"A","患者青少年女性，体瘦弱（结核病常见体征），查体见脊柱后凸畸形（脊柱结核典型表现）、弯腰动作受限（关节活动障碍），腹股沟区触及肿物，穿刺抽出灰白色脓液（结核性脓肿特征，提示冷脓肿）。该患者考虑诊断为脊柱结核，早期最具有诊断价值的检查是MRI（A对），MRI在结核炎性浸润阶段即可显示异常信号，是脊柱结核必不可少的检查方法。X线（B错）表现以骨质破坏和椎间隙狭窄为主，早期常无异常。CT（C错）可明确病灶部位、骨质破坏的程度，以及有无空洞和死骨形成，但对早期炎性改变敏感性不及MRI。结核菌素试验（D错）阳性仅提示结核感染可能，但无法定位脊柱病变。","","N"],["2026-N132",32,"第四节 胆石症","胆囊结石临床表现",2026,132,"B","","胆囊颈结石嵌顿的腹痛特点",[["A","突发上腹部持续性刀割样痛，查体呈板状腹"],["B","突发上腹部阵发性钻顶样剧痛，间歇期无痛"],["C","突发上腹部持续性绞痛，阵发性加重，向右肩部放射"],["D","突发上腹部持续性剧烈疼痛，呈束带状向腰背部放射"]],"C","结石嵌顿在胆囊壶腹部或颈部，胆囊排空受阻，胆囊内压力升高，胆囊强力收缩而突发持续性绞痛，呈阵发性加重，可向右肩胛部和背部放射（C对）。突发上腹部持续性刀割样痛，查体呈板状腹（A错）多见于胃肠道穿孔。突发上腹部阵发性钻顶样剧痛，间歇期无痛（B错）是胆道蛔虫症的典型特征。突发上腹部持续性剧烈疼痛，呈束带状向腰背部放射（D错）见于急性胰腺炎病变累及全胰时。","","N"],["2026-N133",26,"第三节 胃十二指肠溃疡的外科治疗","胃十二指肠溃疡穿孔临床表现",2026,133,"B","","上消化道穿孔的腹痛特点",[["A","突发上腹部持续性刀割样痛，查体呈板状腹"],["B","突发上腹部阵发性钻顶样剧痛，间歇期无痛"],["C","突发上腹部持续性绞痛，阵发性加重，向右肩部放射"],["D","突发上腹部持续性剧烈疼痛，呈束带状向腰背部放射"]],"A","上消化道穿孔是胃十二指肠溃疡的常见并发症，其典型腹痛特点为突发上腹部持续性刀割样痛，查体呈板状腹（A对），由于穿孔后酸性胃内容物流入腹腔，腹膜受刺激产生剧烈疼痛，腹肌紧张呈板状腹。突发上腹部阵发性钻顶样剧痛，间歇期无痛（B错）是胆道蛔虫症的典型特征。突发上腹部持续性绞痛，阵发性加重，向右肩部放射（C错）常见于胆囊结石。突发上腹部持续性剧烈疼痛，呈束带状向腰背部放射（D错）见于急性胰腺炎病变累及全胰时。","","N"],["2026-N134",17,"第一节 甲状腺疾病","手术治疗",2026,134,"B","","甲状腺乳头状癌基本治疗方法是",[["A","TSH抑制治疗"],["B","外放射治疗"],["C","放射性核素治疗"],["D","手术治疗"]],"D","甲状腺乳头状癌的基本治疗是手术治疗（D对），除未分化癌以外，手术是其他各型甲状腺癌的基本治疗方法。TSH抑制治疗（A错）指分化型甲状腺癌术后应用甲状腺激素抑制TSH（促甲状腺激素）分泌从而抑制癌组织的生长。外放射治疗（B错）主要用于甲状腺未分化癌。放射性核素治疗（C错）即¹³¹I治疗，用于术后残留或转移病灶的控制，属于辅助手段。","","N"],["2026-N135",17,"第一节 甲状腺疾病","外放射治疗",2026,135,"B","","甲状腺未分化癌治疗基本方法是",[["A","TSH抑制治疗"],["B","外放射治疗"],["C","放射性核素治疗"],["D","手术治疗"]],"B","甲状腺未分化癌是一种高度恶性的肿瘤，侵袭性强、进展迅速、早期易出现转移、手术后复发率高，首选治疗方法是外放射治疗（B对）。TSH抑制治疗（A错）指分化型甲状腺癌术后应用甲状腺激素抑制TSH（促甲状腺激素）分泌从而抑制癌组织的生长。放射性核素治疗（C错）即¹³¹I治疗，用于术后残留或转移病灶的控制，属于辅助手段。手术治疗（D错）是除未分化癌以外，其他各型甲状腺癌的基本治疗方法。","","N"],["2026-N160",23,"第二节 腹股沟疝","无张力疝修补术",2026,160,"X","","属于无张力疝修补术的是",[["A","Bassini法"],["B","Ferguson法"],["C","Stoppa手术"],["D","Lichtenstein手术"]],"CD","常用的无张力疝修补术有三种：①平片无张力疝修补术（Lichtenstein手术）（D对）：使用一适当大小的补片材料置于腹股沟管后壁。②疝环充填式无张力疝修补术（Rutkow手术）：使用一个锥形网塞置入已还纳疝囊的疝环中并加以固定，再用一成型补片置于精索后以加强腹股沟管后壁。③巨大补片加强内脏囊手术：又称Stoppa手术（C对），是在腹股沟处置入一块较大的补片以加强腹横筋膜，通过巨大补片挡住内脏囊，后因补片与腹膜发生粘连实现修补目的，多用于复杂疝和复发疝。Bassini法（A错）和Ferguson法（B错）属于传统的疝修补术，前者是加强或修补腹股沟管后壁的方法，后者是加强或修补腹股沟管前壁的方法。","","N"],["2026-N161",27,"第四节 肠梗阻","肠梗阻临床表现",2026,161,"X","","下列符合绞窄性肠梗阻的是",[["A","持续性腹痛阵发加重"],["B","肠鸣音亢进"],["C","腹部有压痛、反跳痛、肌紧张"],["D","腹部X线见孤立扩大的肠袢"]],"ABCD","绞窄性肠梗阻是指当肠系膜血管或肠壁小血管受压、血管腔栓塞或血栓形成造成相应肠段血运障碍，可引起肠坏死、穿孔。腹痛发作急骤，初始即为持续性剧烈疼痛，或在阵发性加重之间仍有持续性疼痛（A对）。随着病情进展，出现腹部压痛、反跳痛、腹肌紧张等腹膜刺激征（C对）。腹部X线检查见孤立扩大的肠袢（D对）。绞窄性肠梗阻早期肠鸣音可短暂亢进，因肠管缺血初期仍存在蠕动增强（试图克服梗阻），而晚期绞窄性肠梗阻时，肠壁肌肉因缺血坏死失去蠕动能力，肠鸣音减弱甚至消失。该题叙述不严谨，选项B在严格意义上来说也是符合的。","","N"],["2026-N162",19,"第三节 气胸","胸腔闭式引流术",2026,162,"X","","闭式胸腔引流术的适应症有",[["A","张力性气胸"],["B","拔除胸腔引流管后血胸复发"],["C","开胸手术后"],["D","中等量闭合性气胸"]],"ABCD","胸腔闭式引流术的适应证：①中、大量闭合性气胸（D对）、开放性气胸、张力性气胸（A对）；②经胸腔穿刺术治疗，伤员肺无法复张者；③需使用机械通气或人工通气的气胸或血气胸者；④拔除胸腔引流管后气胸或血胸复发者（B对）；⑤开胸手术后（C对）。","","N"],["2026-N163",8,"第二节 常见体表肿瘤与囊肿","黑色素瘤",2026,163,"X","","属于恶性的体表肿瘤有",[["A","黑色素瘤"],["B","隆突性皮肤纤维肉瘤"],["C","纤维黄色瘤"],["D","神经纤维瘤"]],"AB","黑色素瘤（A对）为高度恶性肿瘤，发展迅速。隆突性皮肤纤维肉瘤（B对）多见于躯干，来源于皮肤真皮层，低度恶性，切除后局部极易复发，多次复发恶性度增高，并可出现血行转移。纤维黄色瘤（C错）位于真皮层及皮下，多见于躯干、上臂近端，质硬，边界不清呈浸润感，易误认为恶性。神经纤维瘤（D错）主要累及皮肤、周围神经和中枢神经系统，为良性肿瘤。","","N"],["2026-N164",43,"第一节 先天性畸形","发育性髋关节脱位病因",2026,164,"X","","发育性髋关节脱位的原发性病理改变有",[["A","髋关节肌肉萎缩，韧带变粗变短"],["B","髋臼浅平，股骨头扁小"],["C","股骨颈前倾角增大，关节囊松弛"],["D","骨盆倾斜，脊柱侧凸"]],"BC","发育性髋关节脱位主要是髋臼、股骨近端和关节囊等均存在结构性畸形导致关节不稳定，直至发展为髋关节脱位。髋臼缘不发育，髋臼浅而平坦，股骨头较小，圆韧带肥厚，股骨头可在髋臼内、脱位或半脱位（B对）。股骨颈前倾角增大，关节囊松弛（C对）会加剧脱位倾向。由于股骨头脱位，可发生脊柱腰段侧凸或过度前凸，久而久之可致腰肌劳损和脊柱骨关节病、骨盆倾斜等（D错）。肌肉萎缩通常由脱位后长期制动或疼痛导致活动减少引起，而韧带变粗变短可能是关节囊松弛后的代偿性改变（A错）。","","N"],["2026-N165",44,"第三节 骨折的并发症","骨折的晚期并发症",2026,165,"X","","骨折晚期并发症有",[["A","急性骨萎缩"],["B","脂肪栓塞"],["C","缺血性骨坏死"],["D","缺血性肌挛缩"]],"ACD","骨折的晚期并发症有急性骨萎缩、缺血性骨坏死、缺血性肌挛缩等。急性骨萎缩（A对）即损伤所致关节附近的疼痛性骨质疏松和软组织萎缩，亦称反射性交感神经性营养不良。骨折可破坏某一骨折端的血液供应，从而使该骨折端发生缺血性坏死（C对）。缺血性肌挛缩（D对）是骨折最严重的并发症之一，是骨筋膜隔室综合征处理不当的严重后果。脂肪栓塞综合征（B错）是骨折的早期并发症，发生于成人，常见于青壮年股骨干骨折，是由于骨折处髓腔内血肿张力过大，骨髓被破坏，脂肪滴进入破裂的静脉窦内，可引起肺、脑脂肪栓塞。","","N"]];
